def _manual_builder_signal(df: pd.DataFrame, cfg: BacktestConfig) -> pd.Series:
    """
    Manual Strategy Builder V1.
    Construit un signal sans exécuter de code utilisateur.

    Logique V1 :
    - Entrée long si close > SMA entrée + RSI >= seuil.
    - Optionnel : breakout au-dessus du plus haut précédent.
    - Optionnel : volume supérieur à sa moyenne.
    - Sortie long si close < SMA sortie ou RSI < seuil de sortie.
    - Short symétrique uniquement si allow_short=True.
    - Le décalage t+1 reste appliqué ensuite par _build_signal.
    """
    close = pd.to_numeric(df["close"], errors="coerce")
    volume = pd.to_numeric(df.get("volume", pd.Series(np.nan, index=df.index)), errors="coerce")

    entry_sma_window = max(int(getattr(cfg, "manual_entry_sma_window", 50)), 2)
    exit_sma_window = max(int(getattr(cfg, "manual_exit_sma_window", 20)), 2)
    rsi_window = max(int(getattr(cfg, "manual_rsi_window", 14)), 2)
    breakout_window = max(int(getattr(cfg, "manual_breakout_window", 20)), 2)
    volume_window = max(int(getattr(cfg, "manual_volume_window", 20)), 2)

    entry_rsi_min = float(getattr(cfg, "manual_entry_rsi_min", 50.0))
    exit_rsi_min = float(getattr(cfg, "manual_exit_rsi_min", 45.0))
    volume_mult = float(getattr(cfg, "manual_volume_mult", 1.0))

    entry_sma = close.rolling(entry_sma_window).mean()
    exit_sma = close.rolling(exit_sma_window).mean()
    rsi = _rsi(close, rsi_window)

    long_entry = (close > entry_sma) & (rsi >= entry_rsi_min)
    long_exit = (close < exit_sma) | (rsi < exit_rsi_min)

    if getattr(cfg, "manual_use_breakout", False):
        rolling_high = close.shift(1).rolling(breakout_window).max()
        long_entry = long_entry & (close > rolling_high)

    if getattr(cfg, "manual_use_volume_filter", False):
        volume_ma = volume.rolling(volume_window).mean()
        long_entry = long_entry & (volume > volume_ma * volume_mult)

    short_entry = pd.Series(False, index=df.index)
    short_exit = pd.Series(False, index=df.index)

    if cfg.allow_short:
        short_entry = (close < entry_sma) & (rsi <= (100.0 - entry_rsi_min))
        short_exit = (close > exit_sma) | (rsi > (100.0 - exit_rsi_min))

        if getattr(cfg, "manual_use_breakout", False):
            rolling_low = close.shift(1).rolling(breakout_window).min()
            short_entry = short_entry & (close < rolling_low)

        if getattr(cfg, "manual_use_volume_filter", False):
            volume_ma = volume.rolling(volume_window).mean()
            short_entry = short_entry & (volume > volume_ma * volume_mult)

    signal = pd.Series(0.0, index=df.index)
    state = 0.0

    for i in range(len(df)):
        if state > 0 and bool(long_exit.iloc[i]):
            state = 0.0

        elif state < 0 and bool(short_exit.iloc[i]):
            state = 0.0

        if state == 0.0:
            if bool(long_entry.iloc[i]):
                state = 1.0
            elif cfg.allow_short and bool(short_entry.iloc[i]):
                state = -1.0

        signal.iloc[i] = state

    return signal.fillna(0.0).clip(-1.0, 1.0)


