# ============================================================
# BASIC HELPERS
# ============================================================

def _safe_float(value: Any, default: float = 0.0) -> float:
    try:
        if value is None or pd.isna(value):
            return default
        return float(value)
    except Exception:
        return default


def _clip(value: Any, low: float = 0.0, high: float = 1.0) -> float:
    try:
        return max(low, min(high, float(value)))
    except Exception:
        return low


def _normal_cdf(x: float) -> float:
    try:
        return 0.5 * (1.0 + erf(float(x) / sqrt(2.0)))
    except Exception:
        return np.nan


def _format_pct(x: Any, decimals: int = 2) -> str:
    try:
        if x is None or pd.isna(x):
            return "N/A"
        return f"{float(x):.{decimals}%}"
    except Exception:
        return "N/A"


def _format_num(x: Any, decimals: int = 2) -> str:
    try:
        if x is None or pd.isna(x):
            return "N/A"
        return f"{float(x):,.{decimals}f}"
    except Exception:
        return "N/A"


def _format_money(x: Any) -> str:
    try:
        if x is None or pd.isna(x):
            return "N/A"
        return f"${float(x):,.0f}"
    except Exception:
        return "N/A"


def _format_dt(value: Any) -> str:
    try:
        ts = pd.to_datetime(value)
        if pd.isna(ts):
            return str(value)
        return ts.strftime("%Y-%m-%d")
    except Exception:
        return str(value)


def _is_datetime_like_index(index: pd.Index) -> bool:
    try:
        return isinstance(index, pd.DatetimeIndex) or np.issubdtype(index.dtype, np.datetime64)
    except Exception:
        return False


def _plotly_config() -> dict[str, Any]:
    return {"displayModeBar": False, "responsive": True}


def _parse_pct_text(value: Any) -> float:
    try:
        if value is None:
            return np.nan
        txt = str(value).replace("%", "").replace(",", ".").strip()
        if txt in {"", "N/A", "nan", "None"}:
            return np.nan
        return float(txt) / 100.0
    except Exception:
        return np.nan


def _matrix_to_pct_table(matrix: pd.DataFrame) -> pd.DataFrame:
    if matrix.empty:
        return matrix
    out = matrix.copy()
    for col in out.columns:
        out[col] = out[col].map(lambda x: _format_pct(x) if pd.notna(x) else "N/A")
    return out


def _pct_badge(value: Any, positive_good: bool = True) -> str:
    raw = _safe_float(value, np.nan)
    if pd.isna(raw):
        return "N/A"
    arrow = "↑" if raw >= 0 else "↓"
    return f"{arrow} {_format_pct(raw)}"


def _card_grid(rows: list[dict[str, Any]], columns: int = 4) -> None:
    if not rows:
        return
    for start in range(0, len(rows), columns):
        cols = st.columns(min(columns, len(rows) - start))
        for col, row in zip(cols, rows[start:start + columns]):
            col.metric(str(row.get("label", "")), str(row.get("value", "N/A")), str(row.get("delta", "")) if row.get("delta") is not None else None)


