def _extract_ohlc(price_data: pd.DataFrame) -> pd.DataFrame:
    if price_data is None or len(price_data) == 0:
        return pd.DataFrame()

    df = price_data.copy()

    if isinstance(df.columns, pd.MultiIndex):
        df.columns = ["_".join([str(x) for x in col if str(x) != ""]) for col in df.columns]

    lower_map = {str(c).lower().replace(" ", "").replace("_", ""): c for c in df.columns}

    def pick(names: list[str]) -> str | None:
        for name in names:
            key = name.lower().replace(" ", "").replace("_", "")
            if key in lower_map:
                return lower_map[key]
        return None

    date_col = pick(["date", "datetime", "timestamp", "time"])
    if date_col is not None:
        parsed_dates = pd.to_datetime(df[date_col], errors="coerce")
        if parsed_dates.notna().sum() >= max(10, int(len(df) * 0.8)):
            df = df.copy()
            df.index = parsed_dates

    close_col = pick(["close", "adjclose", "adj close"])
    open_col = pick(["open"])
    high_col = pick(["high"])
    low_col = pick(["low"])
    volume_col = pick(["volume"])

    if close_col is None:
        numeric_cols = list(df.select_dtypes(include="number").columns)
        if not numeric_cols:
            return pd.DataFrame()
        close_col = numeric_cols[0]

    out = pd.DataFrame(index=df.index)
    out["close"] = pd.to_numeric(df[close_col], errors="coerce")
    out["open"] = pd.to_numeric(df[open_col], errors="coerce") if open_col is not None else out["close"]
    out["high"] = pd.to_numeric(df[high_col], errors="coerce") if high_col is not None else out[["open", "close"]].max(axis=1)
    out["low"] = pd.to_numeric(df[low_col], errors="coerce") if low_col is not None else out[["open", "close"]].min(axis=1)
    out["volume"] = pd.to_numeric(df[volume_col], errors="coerce") if volume_col is not None else np.nan

    out = out.replace([np.inf, -np.inf], np.nan).dropna(subset=["close"])
    out = out.loc[~out.index.duplicated(keep="last")]

    return out


def _sector_benchmark_guess(ticker: str) -> str:
    t = str(ticker or "").upper().strip()
    semi = {"NVDA", "AMD", "AVGO", "INTC", "MU", "MRVL", "TSM", "ASML", "ARM", "QCOM", "TXN", "AMAT", "LRCX"}
    mega_tech = {"AAPL", "MSFT", "GOOGL", "GOOG", "META", "ORCL", "CRM", "ADBE", "NOW", "SNOW"}
    energy = {"XOM", "CVX", "OXY", "SLB", "COP", "EOG"}
    financials = {"JPM", "BAC", "GS", "MS", "C", "WFC", "BLK"}
    healthcare = {"LLY", "UNH", "JNJ", "PFE", "MRK", "ABBV", "TMO"}
    if t in semi:
        return "SMH"
    if t in mega_tech:
        return "XLK"
    if t in energy:
        return "XLE"
    if t in financials:
        return "XLF"
    if t in healthcare:
        return "XLV"
    return "SPY"


def _resolve_benchmark_symbol(ticker: str, mode: str, custom: str = "") -> tuple[str, str]:
    mode = str(mode or "Ticker Buy & Hold")
    if mode == "Ticker Buy & Hold":
        return "", "Ticker Buy & Hold"
    if mode == "SPY":
        return "SPY", "SPY"
    if mode == "QQQ":
        return "QQQ", "QQQ"
    if mode == "IWM":
        return "IWM", "IWM"
    if mode == "Sector ETF":
        symbol = _sector_benchmark_guess(ticker)
        return symbol, f"Sector ETF ({symbol})"
    if mode == "Custom":
        symbol = str(custom or "").upper().strip()
        if symbol:
            return symbol, f"Custom ({symbol})"
    return "", "Ticker Buy & Hold"


def _load_benchmark_returns(df: pd.DataFrame, cfg: BacktestConfig) -> tuple[pd.Series, str, bool]:
    asset_returns = df["close"].pct_change().fillna(0.0)
    symbol = str(cfg.benchmark_ticker or "").upper().strip()

    if not symbol:
        return asset_returns, "Ticker Buy & Hold", False

    if not _is_datetime_like_index(df.index):
        return asset_returns, "Ticker Buy & Hold — fallback no datetime index", True

    try:
        import yfinance as yf  # optional, already used by the app in normal runtime

        start = pd.to_datetime(df.index.min()).date().isoformat()
        end = (pd.to_datetime(df.index.max()) + pd.Timedelta(days=3)).date().isoformat()

        bench = yf.download(symbol, start=start, end=end, progress=False, auto_adjust=True, threads=False)
        if bench is None or bench.empty:
            return asset_returns, f"{cfg.benchmark_label} — fallback unavailable", True

        if isinstance(bench.columns, pd.MultiIndex):
            bench.columns = ["_".join([str(x) for x in col if str(x) != ""]) for col in bench.columns]

        close_col = None
        for candidate in ["Close", "Adj Close", "close", "adjclose"]:
            matches = [c for c in bench.columns if str(c).lower().replace(" ", "") == candidate.lower().replace(" ", "")]
            if matches:
                close_col = matches[0]
                break

        if close_col is None:
            numeric_cols = list(bench.select_dtypes(include="number").columns)
            if not numeric_cols:
                return asset_returns, f"{cfg.benchmark_label} — fallback no close", True
            close_col = numeric_cols[0]

        bench_close = pd.to_numeric(bench[close_col], errors="coerce").dropna()
        bench_close.index = pd.to_datetime(bench_close.index)
        bench_close = bench_close.loc[~bench_close.index.duplicated(keep="last")]

        aligned = bench_close.reindex(pd.to_datetime(df.index)).ffill().bfill()
        bench_returns = aligned.pct_change().fillna(0.0)
        bench_returns.index = df.index

        if bench_returns.dropna().empty:
            return asset_returns, f"{cfg.benchmark_label} — fallback empty", True

        return bench_returns, cfg.benchmark_label or symbol, False

    except Exception:
        return asset_returns, f"{cfg.benchmark_label} — fallback error", True


def _benchmark_relative_trend_signal_v35(df: pd.DataFrame, cfg: BacktestConfig) -> pd.Series:
    """
    Benchmark-Relative Trend V3.5.

    Mutation moteur contrôlée issue de V3.4 :
    - le signal n'est pas price-only ;
    - il exige une performance active positive vs benchmark ;
    - optionnel : benchmark trend gate ;
    - optionnel : volatility cap ;
    - t+1 reste appliqué ensuite dans _build_signal.

    Important :
    - pas d'exécution de code utilisateur ;
    - pas de changement d'exit/sizing/cost ;
    - pas d'optimisation automatique.
    """
    close = pd.to_numeric(df["close"], errors="coerce").ffill()
    signal = pd.Series(0.0, index=df.index)

    if close.empty or len(close) < 80:
        return signal

    fast_h = max(int(getattr(cfg, "brt_fast_horizon", 20)), 2)
    slow_h = max(int(getattr(cfg, "brt_slow_horizon", 60)), fast_h + 1)
    min_active = float(getattr(cfg, "brt_min_active_mom_pct", 0.0)) / 100.0

    # Sécurité : une stratégie benchmark-relative ne doit pas comparer l'actif à lui-même.
    # Si aucun benchmark explicite n'est configuré, on force un proxy sectoriel/SPY.
    bench_cfg = cfg
    if not str(getattr(cfg, "benchmark_ticker", "") or "").strip():
        asset_ticker = str(getattr(cfg, "asset_ticker", "") or "").upper().strip()
        auto_symbol = _sector_benchmark_guess(asset_ticker) if asset_ticker else "SPY"
        bench_cfg = BacktestConfig(
            **{
                **cfg.__dict__,
                "benchmark_ticker": auto_symbol,
                "benchmark_label": f"Auto Sector ETF ({auto_symbol})",
                "benchmark_mode": "Sector ETF",
            }
        )

    benchmark_returns, benchmark_label, benchmark_fallback = _load_benchmark_returns(df, bench_cfg)

    benchmark_returns = (
        pd.to_numeric(benchmark_returns.reindex(close.index), errors="coerce")
        .replace([np.inf, -np.inf], np.nan)
        .fillna(0.0)
    )

    benchmark_nav = (1.0 + benchmark_returns).cumprod()
    benchmark_nav = benchmark_nav.replace([np.inf, -np.inf], np.nan).ffill().bfill()

    asset_ret_fast = close.pct_change(fast_h)
    asset_ret_slow = close.pct_change(slow_h)

    bench_ret_fast = benchmark_nav.pct_change(fast_h)
    bench_ret_slow = benchmark_nav.pct_change(slow_h)

    active_fast = asset_ret_fast - bench_ret_fast
    active_slow = asset_ret_slow - bench_ret_slow

    require_dual = bool(getattr(cfg, "brt_require_dual_horizon", True))

    if require_dual:
        long_core = (active_fast > min_active) & (active_slow > min_active)
        short_core = (active_fast < -min_active) & (active_slow < -min_active)
    else:
        active_score = 0.40 * active_fast + 0.60 * active_slow
        long_core = active_score > min_active
        short_core = active_score < -min_active

    gate = pd.Series(True, index=close.index)

    if bool(getattr(cfg, "brt_use_benchmark_trend_gate", True)):
        ma_window = max(int(getattr(cfg, "brt_benchmark_ma_window", 100)), 5)
        benchmark_ma = benchmark_nav.rolling(ma_window).mean()
        benchmark_uptrend = benchmark_nav > benchmark_ma

        long_core = long_core & benchmark_uptrend.fillna(False)

        if cfg.allow_short:
            benchmark_downtrend = benchmark_nav < benchmark_ma
            short_core = short_core & benchmark_downtrend.fillna(False)

    if bool(getattr(cfg, "brt_use_vol_cap", False)):
        vol_window = max(int(getattr(cfg, "brt_vol_window", 20)), 5)
        vol_pct = max(5.0, min(99.0, float(getattr(cfg, "brt_vol_percentile", 80.0)))) / 100.0

        realized_vol = close.pct_change().rolling(vol_window).std() * np.sqrt(252)
        hist_window = max(126, vol_window * 5)
        vol_cap = realized_vol.rolling(hist_window, min_periods=vol_window).quantile(vol_pct)

        vol_gate = (realized_vol <= vol_cap) | vol_cap.isna()
        long_core = long_core & vol_gate.fillna(True)
        short_core = short_core & vol_gate.fillna(True)

    raw = pd.Series(0.0, index=close.index)
    raw[long_core.fillna(False)] = 1.0

    if cfg.allow_short:
        raw[short_core.fillna(False)] = -1.0

    # Persistance prudente : on reste exposé tant que le signal relatif reste valide,
    # sans optimisation d'exit séparée.
    raw = raw.replace(0.0, np.nan).ffill().fillna(0.0)

    # Sortie si le signal relatif repasse clairement neutre/adverse.
    neutral_exit = (active_fast <= 0.0) & (active_slow <= 0.0)
    raw[neutral_exit.fillna(False)] = 0.0

    if not cfg.allow_short:
        raw = raw.clip(lower=0.0, upper=1.0)

    return raw.fillna(0.0).clip(-1.0, 1.0)


def _benchmark_relative_trend_diagnostics_v35b_pack(df: pd.DataFrame, cfg: BacktestConfig) -> dict[str, Any]:
    """
    Benchmark-Relative Signal Activity Diagnostics V3.5b.

    Lecture seule :
    - ne modifie pas le moteur ;
    - ne modifie pas le signal ;
    - ne modifie pas les trades ;
    - ne modifie pas l'equity curve ;
    - explique pourquoi Benchmark-Relative Trend V3.5 génère ou non des entrées.
    """
    def _bool_count(s: pd.Series) -> int:
        try:
            return int(pd.Series(s).fillna(False).astype(bool).sum())
        except Exception:
            return 0

    def _row(check: str, status: str, severity: str, value: Any, read: str) -> dict[str, Any]:
        return {
            "Check": str(check),
            "Status": str(status),
            "Severity": str(severity),
            "Value": str(value),
            "Read": str(read),
        }

    empty = {
        "enabled": False,
        "level": "Unavailable",
        "score": np.nan,
        "read": "Diagnostic V3.5b indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "checks": pd.DataFrame(),
        "debug": pd.DataFrame(),
        "active_bars": 0,
        "engine_active_bars": 0,
        "eligible_bars": 0,
        "benchmark_label": "N/A",
        "benchmark_fallback": True,
    }

    try:
        if df is None or df.empty or "close" not in df.columns:
            return empty

        close = pd.to_numeric(df["close"], errors="coerce").replace([np.inf, -np.inf], np.nan).ffill()
        close = close.dropna()

        if close.empty:
            return empty

        work_index = close.index
        n = max(int(len(close)), 1)

        fast_h = max(int(getattr(cfg, "brt_fast_horizon", 20)), 2)
        slow_h = max(int(getattr(cfg, "brt_slow_horizon", 60)), fast_h + 1)
        min_active = float(getattr(cfg, "brt_min_active_mom_pct", 0.0)) / 100.0

        bench_cfg = cfg
        auto_benchmark_used = False
        auto_symbol = ""

        if not str(getattr(cfg, "benchmark_ticker", "") or "").strip():
            asset_ticker = str(getattr(cfg, "asset_ticker", "") or "").upper().strip()
            auto_symbol = _sector_benchmark_guess(asset_ticker) if asset_ticker else "SPY"
            auto_benchmark_used = True
            bench_cfg = BacktestConfig(
                **{
                    **cfg.__dict__,
                    "benchmark_ticker": auto_symbol,
                    "benchmark_label": f"Auto Sector ETF ({auto_symbol})",
                    "benchmark_mode": "Sector ETF",
                }
            )

        benchmark_returns, benchmark_label, benchmark_fallback = _load_benchmark_returns(
            pd.DataFrame({"close": close}).reindex(df.index).ffill(),
            bench_cfg,
        )

        benchmark_returns = (
            pd.to_numeric(benchmark_returns.reindex(work_index), errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .fillna(0.0)
        )

        benchmark_nav = (1.0 + benchmark_returns).cumprod()
        benchmark_nav = benchmark_nav.replace([np.inf, -np.inf], np.nan).ffill().bfill()

        asset_ret_fast = close.pct_change(fast_h)
        asset_ret_slow = close.pct_change(slow_h)

        bench_ret_fast = benchmark_nav.pct_change(fast_h)
        bench_ret_slow = benchmark_nav.pct_change(slow_h)

        active_fast = asset_ret_fast - bench_ret_fast
        active_slow = asset_ret_slow - bench_ret_slow

        fast_pass = active_fast > min_active
        slow_pass = active_slow > min_active
        dual_pass = fast_pass & slow_pass

        require_dual = bool(getattr(cfg, "brt_require_dual_horizon", True))

        if require_dual:
            long_core_before_gates = dual_pass.copy()
            active_score = 0.50 * active_fast + 0.50 * active_slow
        else:
            active_score = 0.40 * active_fast + 0.60 * active_slow
            long_core_before_gates = active_score > min_active

        benchmark_gate = pd.Series(True, index=work_index)
        benchmark_ma = pd.Series(np.nan, index=work_index)

        if bool(getattr(cfg, "brt_use_benchmark_trend_gate", True)):
            ma_window = max(int(getattr(cfg, "brt_benchmark_ma_window", 100)), 5)
            benchmark_ma = benchmark_nav.rolling(ma_window).mean()
            benchmark_gate = benchmark_nav > benchmark_ma

        long_after_benchmark_gate = long_core_before_gates & benchmark_gate.fillna(False)

        vol_gate = pd.Series(True, index=work_index)
        realized_vol = pd.Series(np.nan, index=work_index)
        vol_cap = pd.Series(np.nan, index=work_index)

        if bool(getattr(cfg, "brt_use_vol_cap", False)):
            vol_window = max(int(getattr(cfg, "brt_vol_window", 20)), 5)
            vol_pct = max(5.0, min(99.0, float(getattr(cfg, "brt_vol_percentile", 80.0)))) / 100.0

            realized_vol = close.pct_change().rolling(vol_window).std() * np.sqrt(252)
            hist_window = max(126, vol_window * 5)
            vol_cap = realized_vol.rolling(hist_window, min_periods=vol_window).quantile(vol_pct)
            vol_gate = (realized_vol <= vol_cap) | vol_cap.isna()

        long_after_all_gates = long_after_benchmark_gate & vol_gate.fillna(True)

        raw_pre_persist = pd.Series(0.0, index=work_index)
        raw_pre_persist[long_after_all_gates.fillna(False)] = 1.0

        raw_persist = raw_pre_persist.replace(0.0, np.nan).ffill().fillna(0.0)

        neutral_exit = (active_fast <= 0.0) & (active_slow <= 0.0)
        raw_final = raw_persist.copy()
        raw_final[neutral_exit.fillna(False)] = 0.0

        if not bool(getattr(cfg, "allow_short", False)):
            raw_final = raw_final.clip(lower=0.0, upper=1.0)

        engine_signal = raw_final.shift(1).fillna(0.0).clip(-1.0, 1.0)

        valid_fast = int(active_fast.notna().sum())
        valid_slow = int(active_slow.notna().sum())

        fast_positive = _bool_count(fast_pass)
        slow_positive = _bool_count(slow_pass)
        dual_positive = _bool_count(dual_pass)
        core_positive = _bool_count(long_core_before_gates)
        benchmark_gate_pass = _bool_count(benchmark_gate)
        after_benchmark = _bool_count(long_after_benchmark_gate)
        vol_gate_pass = _bool_count(vol_gate)
        eligible = _bool_count(long_after_all_gates)
        raw_active = int((raw_final.abs() > 0).sum())
        engine_active = int((engine_signal.abs() > 0).sum())
        engine_changes = int((engine_signal.diff().abs().fillna(engine_signal.abs()) > 0).sum())

        fast_share = fast_positive / max(valid_fast, 1)
        slow_share = slow_positive / max(valid_slow, 1)
        dual_share = dual_positive / max(valid_slow, 1)
        core_share = core_positive / n
        benchmark_gate_share = benchmark_gate_pass / n
        after_benchmark_share = after_benchmark / n
        eligible_share = eligible / n
        engine_share = engine_active / n

        blockers = []

        if fast_positive <= 0:
            blockers.append("fast active momentum never positive")

        if slow_positive <= 0:
            blockers.append("slow active momentum never positive")

        if require_dual and dual_positive <= 0:
            blockers.append("dual 20D+60D condition never passes")

        if core_positive > 0 and after_benchmark <= 0:
            blockers.append("benchmark trend gate blocks all core signals")

        if after_benchmark > 0 and eligible <= 0:
            blockers.append("volatility cap blocks all benchmark-gated signals")

        if eligible > 0 and engine_active <= 0:
            blockers.append("eligible pre-shift signal disappears after t+1/neutral exit")

        if engine_active <= 0:
            level = "Inactive signal"
            score = 0.0
            read = (
                "Aucune exposition moteur : la stratégie reste cash. "
                "L'alpha négatif vient principalement de la comparaison cash vs benchmark."
            )
        elif engine_share < 0.05:
            level = "Thin signal"
            score = 35.0
            read = (
                "Signal actif mais très rare : échantillon trop faible pour conclure proprement."
            )
        elif engine_changes <= 1:
            level = "Static signal"
            score = 55.0
            read = (
                "Signal actif mais quasi statique : proche d'un trade unique ou d'une exposition continue."
            )
        else:
            level = "Signal active"
            score = 75.0
            read = (
                "Signal actif : le backtest peut être interprété, sous réserve OOS/overfit/sample."
            )

        cards = [
            {
                "label": "BRT activity",
                "value": level,
                "delta": f"{_format_num(score, 0)}/100",
            },
            {
                "label": "Engine active bars",
                "value": str(engine_active),
                "delta": _format_pct(engine_share, 0),
            },
            {
                "label": "Eligible bars",
                "value": str(eligible),
                "delta": "pre-shift",
            },
            {
                "label": "Fast active > min",
                "value": _format_pct(fast_share, 0),
                "delta": f"{fast_positive}/{valid_fast}",
            },
            {
                "label": "Slow active > min",
                "value": _format_pct(slow_share, 0),
                "delta": f"{slow_positive}/{valid_slow}",
            },
            {
                "label": "Dual pass",
                "value": _format_pct(dual_share, 0),
                "delta": "20D+60D",
            },
            {
                "label": "Benchmark gate pass",
                "value": _format_pct(benchmark_gate_share, 0),
                "delta": str(benchmark_label),
            },
            {
                "label": "After benchmark gate",
                "value": _format_pct(after_benchmark_share, 0),
                "delta": f"{after_benchmark} bars",
            },
            {
                "label": "Engine changes",
                "value": str(engine_changes),
                "delta": "after t+1",
            },
        ]

        checks = pd.DataFrame(
            [
                _row(
                    "Benchmark loaded",
                    "WARN" if benchmark_fallback else "PASS",
                    "Medium" if benchmark_fallback else "None",
                    benchmark_label,
                    "Si fallback=True, la comparaison relative peut être faussée.",
                ),
                _row(
                    "Fast active momentum",
                    "PASS" if fast_positive > 0 else "FAIL",
                    "None" if fast_positive > 0 else "High",
                    f"{fast_positive}/{valid_fast}",
                    "Nombre de barres où actif - benchmark sur horizon fast dépasse le seuil.",
                ),
                _row(
                    "Slow active momentum",
                    "PASS" if slow_positive > 0 else "FAIL",
                    "None" if slow_positive > 0 else "High",
                    f"{slow_positive}/{valid_slow}",
                    "Nombre de barres où actif - benchmark sur horizon slow dépasse le seuil.",
                ),
                _row(
                    "Dual horizon condition",
                    "PASS" if dual_positive > 0 else ("SKIP" if not require_dual else "FAIL"),
                    "None" if dual_positive > 0 else ("Low" if not require_dual else "High"),
                    f"{dual_positive}/{valid_slow}",
                    "Condition stricte fast ET slow. Peut être la cause de 0 trade.",
                ),
                _row(
                    "Core signal before gates",
                    "PASS" if core_positive > 0 else "FAIL",
                    "None" if core_positive > 0 else "High",
                    f"{core_positive}/{n}",
                    "Signal relatif avant filtre benchmark trend et volatility cap.",
                ),
                _row(
                    "Benchmark trend gate",
                    "PASS" if after_benchmark > 0 else ("SKIP" if not bool(getattr(cfg, "brt_use_benchmark_trend_gate", True)) else "FAIL"),
                    "None" if after_benchmark > 0 else ("Low" if not bool(getattr(cfg, "brt_use_benchmark_trend_gate", True)) else "High"),
                    f"{after_benchmark}/{n}",
                    "Nombre de barres conservées après trend gate benchmark.",
                ),
                _row(
                    "Volatility cap",
                    "PASS" if eligible > 0 else ("SKIP" if not bool(getattr(cfg, "brt_use_vol_cap", False)) else "FAIL"),
                    "None" if eligible > 0 else ("Low" if not bool(getattr(cfg, "brt_use_vol_cap", False)) else "Medium"),
                    f"{eligible}/{n}",
                    "Nombre de barres conservées après tous les gates.",
                ),
                _row(
                    "Engine exposure after t+1",
                    "PASS" if engine_active > 0 else "FAIL",
                    "None" if engine_active > 0 else "Critical",
                    f"{engine_active}/{n}",
                    "Exposition réellement utilisée par le moteur après shift t+1.",
                ),
            ]
        )

        summary = pd.DataFrame(
            [
                ["BRT V3.5b level", level, "Lecture synthétique de l'activité du signal."],
                ["BRT V3.5b score", f"{_format_num(score, 0)}/100", "Score d'activité, pas score de performance."],
                ["Read", read, "Interprétation opérationnelle."],
                ["Blockers", ", ".join(blockers) if blockers else "None", "Causes probables d'un signal inactif."],
                ["Benchmark label", benchmark_label, "Benchmark réellement utilisé."],
                ["Benchmark fallback", str(bool(benchmark_fallback)), "Fallback vers actif si benchmark externe indisponible."],
                ["Auto benchmark used", str(bool(auto_benchmark_used)), f"Proxy auto : {auto_symbol or 'N/A'}."],
                ["Fast horizon", str(fast_h), "Horizon court active momentum."],
                ["Slow horizon", str(slow_h), "Horizon long active momentum."],
                ["Min active momentum", _format_pct(min_active), "Seuil actif minimal vs benchmark."],
                ["Require dual horizon", str(bool(require_dual)), "Si True : fast ET slow doivent passer."],
                ["Benchmark trend gate", str(bool(getattr(cfg, 'brt_use_benchmark_trend_gate', True))), "Filtre benchmark > MA."],
                ["Benchmark MA window", str(int(getattr(cfg, "brt_benchmark_ma_window", 100))), "Fenêtre MA benchmark."],
                ["Vol cap enabled", str(bool(getattr(cfg, "brt_use_vol_cap", False))), "Filtre volatilité activé ou non."],
                ["Fast pass share", _format_pct(fast_share), "Part des barres valides où active_fast passe."],
                ["Slow pass share", _format_pct(slow_share), "Part des barres valides où active_slow passe."],
                ["Dual pass share", _format_pct(dual_share), "Part des barres où les deux horizons passent."],
                ["Core pass share", _format_pct(core_share), "Signal relatif avant gates."],
                ["Benchmark gate pass share", _format_pct(benchmark_gate_share), "Benchmark trend gate seul."],
                ["After benchmark gate share", _format_pct(after_benchmark_share), "Signal restant après benchmark gate."],
                ["Eligible share", _format_pct(eligible_share), "Signal restant avant shift t+1."],
                ["Engine active share", _format_pct(engine_share), "Exposition moteur après shift t+1."],
                ["Engine changes", str(engine_changes), "Nombre de changements d'exposition moteur."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        debug = pd.DataFrame(
            {
                "Date": [_format_dt(x) for x in work_index],
                "Close": close.values,
                "Benchmark NAV": benchmark_nav.values,
                "Asset ret fast": asset_ret_fast.values,
                "Bench ret fast": bench_ret_fast.values,
                "Active fast": active_fast.values,
                "Fast pass": fast_pass.fillna(False).astype(bool).values,
                "Asset ret slow": asset_ret_slow.values,
                "Bench ret slow": bench_ret_slow.values,
                "Active slow": active_slow.values,
                "Slow pass": slow_pass.fillna(False).astype(bool).values,
                "Dual pass": dual_pass.fillna(False).astype(bool).values,
                "Benchmark gate": benchmark_gate.fillna(False).astype(bool).values,
                "Vol gate": vol_gate.fillna(True).astype(bool).values,
                "Eligible pre-shift": long_after_all_gates.fillna(False).astype(bool).values,
                "Raw final pre-shift": raw_final.values,
                "Engine signal t+1": engine_signal.values,
            }
        )

        debug_display = debug.tail(80).copy()

        pct_cols = [
            "Asset ret fast",
            "Bench ret fast",
            "Active fast",
            "Asset ret slow",
            "Bench ret slow",
            "Active slow",
        ]

        for col in pct_cols:
            if col in debug_display.columns:
                debug_display[col] = debug_display[col].map(lambda x: _format_pct(x))

        if "Close" in debug_display.columns:
            debug_display["Close"] = debug_display["Close"].map(lambda x: _format_num(x))

        if "Benchmark NAV" in debug_display.columns:
            debug_display["Benchmark NAV"] = debug_display["Benchmark NAV"].map(lambda x: _format_num(x))

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "read": read,
            "cards": cards,
            "summary": summary,
            "checks": checks,
            "debug": debug_display,
            "active_bars": raw_active,
            "engine_active_bars": engine_active,
            "eligible_bars": eligible,
            "engine_changes": engine_changes,
            "benchmark_label": benchmark_label,
            "benchmark_fallback": bool(benchmark_fallback),
            "blockers": blockers,
        }

    except Exception as exc:
        out = empty.copy()
        out["enabled"] = True
        out["level"] = "Diagnostic error"
        out["score"] = 0.0
        out["read"] = f"Erreur diagnostic V3.5b : {exc}"
        out["summary"] = pd.DataFrame(
            [["Error", str(exc), "Erreur capturée sans interrompre le backtest."]],
            columns=["Metric", "Value", "Read"],
        )
        return out


def _render_benchmark_relative_trend_diagnostics_v35b(pack: dict[str, Any]) -> None:
    """
    Rendu Streamlit du diagnostic Benchmark-Relative Trend V3.5b.
    Lecture seule.
    """
    pack = pack if isinstance(pack, dict) else {}

    st.subheader("Benchmark-Relative Signal Activity Diagnostics V3.5b")
    st.caption(
        "Diagnostic lecture seule : active momentum fast/slow, dual horizon, benchmark trend gate, "
        "volatility cap, signal pré-shift et exposition moteur t+1. Aucun impact sur le moteur."
    )

    _card_grid(pack.get("cards", []), columns=6)

    level = str(pack.get("level", "Unavailable"))
    read = str(pack.get("read", ""))

    if level in {"Inactive signal", "Diagnostic error"}:
        st.error(f"Lecture V3.5b : {read}")
    elif level in {"Thin signal", "Static signal"}:
        st.warning(f"Lecture V3.5b : {read}")
    elif level == "Signal active":
        st.success(f"Lecture V3.5b : {read}")
    else:
        st.info(f"Lecture V3.5b : {read or 'Diagnostic indisponible.'}")

    summary = pack.get("summary", pd.DataFrame())
    checks = pack.get("checks", pd.DataFrame())
    debug = pack.get("debug", pd.DataFrame())

    with st.expander("BRT signal activity summary V3.5b", expanded=True):
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V3.5b indisponible.")

    with st.expander("BRT signal activity checks V3.5b", expanded=True):
        if isinstance(checks, pd.DataFrame) and not checks.empty:
            st.dataframe(checks, use_container_width=True, hide_index=True)
        else:
            st.info("Checks V3.5b indisponibles.")

    with st.expander("BRT debug map — last 80 bars V3.5b", expanded=False):
        if isinstance(debug, pd.DataFrame) and not debug.empty:
            st.dataframe(debug, use_container_width=True, hide_index=True)
        else:
            st.info("Debug map V3.5b indisponible.")


