def _rsi(close: pd.Series, window: int = 14) -> pd.Series:
    delta = close.diff()
    gain = delta.clip(lower=0.0)
    loss = -delta.clip(upper=0.0)

    avg_gain = gain.ewm(alpha=1 / max(window, 1), adjust=False).mean()
    avg_loss = loss.ewm(alpha=1 / max(window, 1), adjust=False).mean()

    rs = avg_gain / avg_loss.replace(0, np.nan)
    return (100 - (100 / (1 + rs))).fillna(50)



def _coerce_signal_value(value: Any) -> float:
    """Convertit BUY/SELL/SHORT/FLAT ou une exposition numérique en [-1, 1]."""
    try:
        if value is None or pd.isna(value):
            return np.nan
        txt = str(value).strip().upper()
        if txt in {"", "N/A", "NA", "NONE", "NAN"}:
            return np.nan
        if txt in {"BUY", "LONG", "L", "TRUE", "ON"}:
            return 1.0
        if txt in {"SELL", "EXIT", "FLAT", "CASH", "CLOSE", "0", "FALSE", "OFF"}:
            return 0.0
        if txt in {"SHORT", "S", "SELL_SHORT", "-1"}:
            return -1.0
        return float(txt.replace("%", "").replace(",", ".")) / (100.0 if "%" in txt else 1.0)
    except Exception:
        return np.nan


def _parse_custom_signal_input(uploaded_file: Any = None, pasted_text: str = "") -> tuple[pd.DataFrame | None, str]:
    """
    Parse un signal externe sans exécuter de code utilisateur.
    Formats supportés :
    - date,exposure
    - date,signal,size
    - date,position_pct
    Le signal sera ensuite aligné sur les prix et décalé d'un bar dans _build_signal.
    """
    raw: pd.DataFrame | None = None

    try:
        if uploaded_file is not None:
            raw = pd.read_csv(uploaded_file, sep=None, engine="python")
        elif pasted_text and str(pasted_text).strip():
            raw = pd.read_csv(StringIO(str(pasted_text).strip()), sep=None, engine="python")
    except Exception as exc:
        return None, f"Import signal impossible : {exc}"

    if raw is None or raw.empty:
        return None, "Aucun signal custom chargé."

    df = raw.copy()
    df.columns = [str(c).strip() for c in df.columns]
    lower = {str(c).lower().strip(): c for c in df.columns}
    source_columns = [str(c) for c in df.columns]
    raw_rows = int(len(df))

    date_col = None
    for candidate in ["date", "datetime", "timestamp", "time"]:
        if candidate in lower:
            date_col = lower[candidate]
            break

    signal_col = None
    for candidate in ["exposure", "position", "position_pct", "signal", "side", "size", "weight"]:
        if candidate in lower:
            signal_col = lower[candidate]
            break

    if signal_col is None:
        numeric_cols = list(df.select_dtypes(include="number").columns)
        if numeric_cols:
            signal_col = numeric_cols[0]
        elif len(df.columns) == 1:
            signal_col = df.columns[0]
        else:
            return None, "Colonnes attendues : date + exposure/signal/side/size/position_pct."

    out = pd.DataFrame()
    if date_col is not None:
        out["date"] = pd.to_datetime(df[date_col], errors="coerce")
    else:
        out["date"] = pd.NaT

    available_col = None
    for candidate in ["available_at", "available_time", "published_at", "release_time", "asof", "as_of", "effective_at"]:
        if candidate in lower:
            available_col = lower[candidate]
            break

    if available_col is not None:
        out["available_at"] = pd.to_datetime(df[available_col], errors="coerce")

    base_signal = df[signal_col].map(_coerce_signal_value)

    # Si une colonne size/weight existe en plus du signal textuel, on l'applique comme multiplicateur d'exposition.
    size_col = None
    for candidate in ["size", "weight", "position_size", "position_pct"]:
        if candidate in lower and lower[candidate] != signal_col:
            size_col = lower[candidate]
            break
    if size_col is not None:
        size = df[size_col].map(_coerce_signal_value).abs()
        base_signal = base_signal * size.fillna(1.0)

    out["signal"] = base_signal.clip(-1.0, 1.0)
    out = out.replace([np.inf, -np.inf], np.nan).dropna(subset=["signal"])

    if out.empty:
        return None, "Signal custom vide après nettoyage."

    if out["date"].notna().any():
        out = out.dropna(subset=["date"])
        out = out.sort_values("date").drop_duplicates("date", keep="last")
        if out.empty:
            return None, "Dates invalides dans le signal custom."
        status = f"Signal custom chargé : {len(out)} lignes datées."
    else:
        out = out.reset_index(drop=True)
        status = f"Signal custom chargé : {len(out)} lignes séquentielles."

    try:
        raw_date_series = pd.to_datetime(df[date_col], errors="coerce") if date_col is not None else pd.Series(dtype="datetime64[ns]")
        raw_duplicate_dates = int(raw_date_series.dropna().duplicated().sum()) if date_col is not None else 0
        raw_invalid_dates = int(raw_date_series.isna().sum()) if date_col is not None else 0
        raw_signal_abs_max = float(pd.to_numeric(base_signal, errors="coerce").abs().max()) if len(base_signal) else np.nan

        out.attrs.update(
            {
                "source_columns": source_columns,
                "raw_rows": raw_rows,
                "date_col": str(date_col or ""),
                "signal_col": str(signal_col or ""),
                "size_col": str(size_col or ""),
                "available_at_col": str(available_col or ""),
                "raw_duplicate_dates": raw_duplicate_dates,
                "raw_invalid_dates": raw_invalid_dates,
                "raw_signal_abs_max": raw_signal_abs_max,
                "parser_status": status,
                "parser_version": "Custom Signal Import parser + Safety metadata V2.6",
            }
        )
    except Exception:
        pass

    return out, status



def _price_index_bounds(price_index: pd.Index) -> tuple[pd.Timestamp | None, pd.Timestamp | None]:
    """Retourne la fenêtre réelle de prix chargée, si l'index est daté."""
    try:
        if not _is_datetime_like_index(price_index):
            return None, None

        idx = pd.to_datetime(pd.Index(price_index), errors="coerce")
        idx = pd.Series(idx).dropna()

        if idx.empty:
            return None, None

        return pd.Timestamp(idx.min()).normalize(), pd.Timestamp(idx.max()).normalize()
    except Exception:
        return None, None


def _make_custom_signal_sample(price_index: pd.Index) -> str:
    """
    Exemple dynamique basé sur les dates réellement chargées.
    Évite l'ancien exemple fixe qui pouvait tomber hors fenêtre.
    """
    try:
        start, end = _price_index_bounds(price_index)

        if start is None or end is None:
            return "date,exposure\n2025-01-02,0\n2025-01-03,1\n2025-01-10,0\n2025-01-15,-1"

        idx = pd.to_datetime(pd.Index(price_index), errors="coerce")
        idx = pd.Series(idx).dropna().drop_duplicates().sort_values()

        if len(idx) < 6:
            dates = pd.date_range(start=start, end=end, periods=min(4, max(2, len(idx))))
        else:
            # On prend des points répartis dans la fenêtre réelle.
            positions = np.linspace(0, len(idx) - 1, 6, dtype=int)
            dates = idx.iloc[positions].tolist()

        exposures = [0, 1, 1, 0, -1, 0]
        rows = ["date,exposure"]

        for i, dt in enumerate(dates):
            rows.append(f"{pd.Timestamp(dt).strftime('%Y-%m-%d')},{exposures[i % len(exposures)]}")

        return "\n".join(rows)

    except Exception:
        return "date,exposure\n2025-01-02,0\n2025-01-03,1\n2025-01-10,0\n2025-01-15,-1"


def _custom_signal_overlap_diagnostics(signal_df: Any, price_index: pd.Index) -> tuple[bool, str, dict[str, Any]]:
    """
    Vérifie que le signal custom peut réellement être testé sur l'historique chargé.
    Retourne : ready, message, diagnostics.
    """
    diagnostics = {
        "price_start": None,
        "price_end": None,
        "signal_start": None,
        "signal_end": None,
        "active_bars": 0,
        "changes": 0,
        "mode": "unknown",
    }

    if signal_df is None or not isinstance(signal_df, pd.DataFrame) or signal_df.empty:
        return False, "Aucun signal custom chargé.", diagnostics

    price_start, price_end = _price_index_bounds(price_index)
    diagnostics["price_start"] = price_start
    diagnostics["price_end"] = price_end

    if "signal" not in signal_df.columns:
        return False, "Signal custom invalide : colonne signal/exposure introuvable après parsing.", diagnostics

    has_dates = "date" in signal_df.columns and signal_df["date"].notna().any()

    if has_dates and price_start is not None and price_end is not None:
        sig_dates = pd.to_datetime(signal_df["date"], errors="coerce").dropna()

        if sig_dates.empty:
            return False, "Signal custom invalide : dates non lisibles.", diagnostics

        signal_start = pd.Timestamp(sig_dates.min()).normalize()
        signal_end = pd.Timestamp(sig_dates.max()).normalize()

        diagnostics["signal_start"] = signal_start
        diagnostics["signal_end"] = signal_end
        diagnostics["mode"] = "dated"

        overlap_start = max(price_start, signal_start)
        overlap_end = min(price_end, signal_end)

        if overlap_start > overlap_end:
            return (
                False,
                (
                    "Signal lu mais aucune date ne chevauche l'historique chargé. "
                    f"Historique disponible : {price_start.strftime('%Y-%m-%d')} → {price_end.strftime('%Y-%m-%d')}. "
                    f"Signal fourni : {signal_start.strftime('%Y-%m-%d')} → {signal_end.strftime('%Y-%m-%d')}."
                ),
                diagnostics,
            )

    else:
        diagnostics["mode"] = "sequential"

    aligned = _align_custom_signal_to_prices(signal_df, price_index)
    active_bars = int((aligned.abs() > 0).sum())
    changes = int((aligned.diff().abs().fillna(aligned.abs()) > 0).sum())

    diagnostics["active_bars"] = active_bars
    diagnostics["changes"] = changes

    if active_bars <= 0:
        return (
            False,
            (
                "Signal custom aligné, mais exposition active nulle sur toute la fenêtre. "
                "Vérifie que la colonne exposure contient bien 1, -1, BUY, LONG, SHORT ou des poids non nuls."
            ),
            diagnostics,
        )

    if changes <= 0:
        return (
            True,
            (
                f"Signal custom aligné : {active_bars} barres actives, mais aucun changement d'exposition détecté. "
                "Backtest possible, mais lecture limitée."
            ),
            diagnostics,
        )

    return (
        True,
        f"Signal custom aligné : {active_bars} barres actives · {changes} changements d'exposition détectés.",
        diagnostics,
    )



def _align_custom_signal_to_prices(signal_df: Any, price_index: pd.Index) -> pd.Series:
    """Aligne un signal importé sur l'index prix. Sortie non shiftée, _build_signal applique le t+1."""
    empty = pd.Series(0.0, index=price_index)
    if signal_df is None or not isinstance(signal_df, pd.DataFrame) or signal_df.empty:
        return empty

    try:
        sig = signal_df.copy()
        if "signal" not in sig.columns:
            return empty

        if "date" in sig.columns and sig["date"].notna().any() and _is_datetime_like_index(price_index):
            indexed = sig.dropna(subset=["date"]).copy()
            indexed.index = pd.to_datetime(indexed["date"])
            indexed = indexed.sort_index()
            series = pd.to_numeric(indexed["signal"], errors="coerce").dropna()
            series = series.loc[~series.index.duplicated(keep="last")]
            aligned = series.reindex(pd.to_datetime(price_index)).ffill().fillna(0.0)
            aligned.index = price_index
            return aligned.clip(-1.0, 1.0)

        # Fallback séquentiel : accepté uniquement si assez proche de la longueur prix.
        values = pd.to_numeric(sig["signal"], errors="coerce").dropna().clip(-1.0, 1.0).values
        if len(values) == len(price_index):
            return pd.Series(values, index=price_index).fillna(0.0)
        if len(values) < len(price_index):
            padded = np.concatenate([np.zeros(len(price_index) - len(values)), values])
            return pd.Series(padded, index=price_index).fillna(0.0)
        return pd.Series(values[-len(price_index):], index=price_index).fillna(0.0)
    except Exception:
        return empty


def _custom_signal_preview_tables(
    signal_df: Any,
    price_index: pd.Index,
    allow_short: bool,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """
    Preview compacte du signal custom :
    - raw_aligned_signal : signal importé aligné aux prix
    - effective_pre_shift : signal après règle short
    - engine_exposure_t1 : exposition réellement utilisée par le moteur après décalage t+1
    """
    raw_signal = _align_custom_signal_to_prices(signal_df, price_index)

    effective_signal = raw_signal.copy()
    if not allow_short:
        effective_signal = effective_signal.clip(lower=0.0, upper=1.0)

    engine_signal = effective_signal.shift(1).fillna(0.0).clip(-1.0, 1.0)

    preview = pd.DataFrame(
        {
            "date": pd.to_datetime(price_index),
            "raw_aligned_signal": raw_signal.values,
            "effective_pre_shift": effective_signal.values,
            "engine_exposure_t1": engine_signal.values,
        }
    )

    raw_change = preview["raw_aligned_signal"].diff().fillna(
        preview["raw_aligned_signal"]
    ).abs() > 0

    effective_change = preview["effective_pre_shift"].diff().fillna(
        preview["effective_pre_shift"]
    ).abs() > 0

    engine_change = preview["engine_exposure_t1"].diff().fillna(
        preview["engine_exposure_t1"]
    ).abs() > 0

    event_mask = raw_change | effective_change | engine_change

    events = preview.loc[event_mask].copy()

    if not preview.empty:
        boundary_rows = preview.iloc[[0, -1]].copy()
        events = (
            pd.concat([boundary_rows, events], ignore_index=True)
            .drop_duplicates(subset=["date"], keep="last")
            .sort_values("date")
        )

    events["date"] = events["date"].map(_format_dt)

    seg = preview[["date", "engine_exposure_t1"]].copy()
    seg["group"] = seg["engine_exposure_t1"].ne(
        seg["engine_exposure_t1"].shift()
    ).cumsum()

    segments = (
        seg.groupby("group", as_index=False)
        .agg(
            start=("date", "first"),
            end=("date", "last"),
            exposure=("engine_exposure_t1", "first"),
            bars=("date", "size"),
        )
    )

    segments = segments[segments["exposure"].abs() > 0].copy()

    if not segments.empty:
        segments["side"] = np.where(segments["exposure"] > 0, "LONG", "SHORT")
        segments["start"] = segments["start"].map(_format_dt)
        segments["end"] = segments["end"].map(_format_dt)
        segments = segments[["start", "end", "side", "exposure", "bars"]]

    return events.tail(30), segments


def _custom_signal_execution_diagnostics(
    signal_df: Any,
    price_index: pd.Index,
    allow_short: bool,
) -> tuple[list[dict[str, Any]], pd.DataFrame]:
    """
    Diagnostic compact du signal custom réellement exploitable par le moteur.
    Ne modifie pas le backtest : lecture uniquement.
    """
    raw_signal = _align_custom_signal_to_prices(signal_df, price_index)

    effective_signal = raw_signal.copy()
    if not allow_short:
        effective_signal = effective_signal.clip(lower=0.0, upper=1.0)

    engine_signal = effective_signal.shift(1).fillna(0.0).clip(-1.0, 1.0)

    n = max(len(engine_signal), 1)

    raw_active = int((raw_signal.abs() > 0).sum())
    effective_active = int((effective_signal.abs() > 0).sum())
    engine_active = int((engine_signal.abs() > 0).sum())

    long_bars = int((engine_signal > 0).sum())
    short_bars = int((engine_signal < 0).sum())
    neutralized_short_bars = int(((raw_signal < 0) & (effective_signal == 0)).sum())

    raw_changes = int((raw_signal.diff().abs().fillna(raw_signal.abs()) > 0).sum())
    engine_changes = int((engine_signal.diff().abs().fillna(engine_signal.abs()) > 0).sum())

    engine_turnover = float(engine_signal.diff().abs().fillna(engine_signal.abs()).sum())
    max_abs_exposure = float(engine_signal.abs().max()) if len(engine_signal) else 0.0

    price_start, price_end = _price_index_bounds(price_index)

    signal_mode = "sequential"
    signal_start = "N/A"
    signal_end = "N/A"

    try:
        if (
            signal_df is not None
            and isinstance(signal_df, pd.DataFrame)
            and "date" in signal_df.columns
            and signal_df["date"].notna().any()
        ):
            sig_dates = pd.to_datetime(signal_df["date"], errors="coerce").dropna()
            if not sig_dates.empty:
                signal_mode = "dated"
                signal_start = _format_dt(sig_dates.min())
                signal_end = _format_dt(sig_dates.max())
    except Exception:
        pass

    if engine_active <= 0:
        status = "NOT READY / FLAT"
    elif short_bars > 0 and allow_short:
        status = "READY LONG/SHORT"
    elif neutralized_short_bars > 0 and not allow_short:
        status = "READY LONG-ONLY ADJUSTED"
    elif long_bars > 0 and short_bars == 0:
        status = "READY LONG-ONLY"
    else:
        status = "READY"

    cards = [
        {
            "label": "Custom status",
            "value": status,
            "delta": "execution",
        },
        {
            "label": "Engine active bars",
            "value": str(engine_active),
            "delta": _format_pct(engine_active / n, 0),
        },
        {
            "label": "Long bars",
            "value": str(long_bars),
            "delta": "engine t+1",
        },
        {
            "label": "Short bars",
            "value": str(short_bars),
            "delta": "allowed" if allow_short else "disabled",
        },
        {
            "label": "Short bars neutralized",
            "value": str(neutralized_short_bars),
            "delta": "rule check",
        },
        {
            "label": "Signal turnover",
            "value": _format_num(engine_turnover),
            "delta": f"{engine_changes} changes",
        },
    ]

    health = pd.DataFrame(
        [
            [
                "Execution status",
                status,
                "Statut du signal réellement utilisé par le moteur.",
            ],
            [
                "Price window",
                (
                    f"{_format_dt(price_start)} → {_format_dt(price_end)}"
                    if price_start is not None and price_end is not None
                    else "N/A"
                ),
                "Fenêtre de prix disponible pour le backtest.",
            ],
            [
                "Signal mode",
                signal_mode,
                "Signal daté ou séquentiel.",
            ],
            [
                "Signal window",
                f"{signal_start} → {signal_end}",
                "Fenêtre fournie dans le CSV si le signal est daté.",
            ],
            [
                "Raw active bars",
                str(raw_active),
                "Barres actives avant règle short et avant décalage.",
            ],
            [
                "Effective active bars",
                str(effective_active),
                "Barres actives après neutralisation éventuelle des shorts.",
            ],
            [
                "Engine active bars",
                str(engine_active),
                "Barres actives réellement backtestées après décalage t+1.",
            ],
            [
                "Engine coverage",
                _format_pct(engine_active / n),
                "Pourcentage de l'historique où le moteur est exposé.",
            ],
            [
                "Raw signal changes",
                str(raw_changes),
                "Changements détectés dans le signal importé.",
            ],
            [
                "Engine signal changes",
                str(engine_changes),
                "Changements réellement appliqués après t+1.",
            ],
            [
                "Neutralized short bars",
                str(neutralized_short_bars),
                "Nombre de barres short mises à zéro car short désactivé.",
            ],
            [
                "Max abs exposure",
                _format_num(max_abs_exposure),
                "Exposition maximale absolue utilisée par le moteur.",
            ],
            [
                "Engine turnover",
                _format_num(engine_turnover),
                "Somme des changements absolus d'exposition moteur.",
            ],
        ],
        columns=["Metric", "Value", "Read"],
    )

    return cards, health


def _custom_signal_quality_summary(
    signal_df: Any,
    price_index: pd.Index,
    allow_short: bool,
) -> dict[str, Any]:
    """
    Résumé exploitable du signal custom pour le verdict, l'executive cockpit et l'export.
    Ne modifie pas le moteur.
    """
    if signal_df is None or not isinstance(signal_df, pd.DataFrame) or signal_df.empty:
        return {
            "verdict": "NO CUSTOM SIGNAL",
            "level": "error",
            "engine_active_bars": 0,
            "engine_coverage": 0.0,
            "long_bars": 0,
            "short_bars": 0,
            "short_bars_neutralized": 0,
            "engine_changes": 0,
            "engine_turnover": 0.0,
            "notes": ["Aucun signal custom exploitable."],
        }

    raw_signal = _align_custom_signal_to_prices(signal_df, price_index)

    effective_signal = raw_signal.copy()
    if not allow_short:
        effective_signal = effective_signal.clip(lower=0.0, upper=1.0)

    engine_signal = effective_signal.shift(1).fillna(0.0).clip(-1.0, 1.0)

    n = max(len(engine_signal), 1)

    engine_active_bars = int((engine_signal.abs() > 0).sum())
    long_bars = int((engine_signal > 0).sum())
    short_bars = int((engine_signal < 0).sum())
    short_bars_neutralized = int(((raw_signal < 0) & (effective_signal == 0)).sum())

    engine_changes = int(
        (engine_signal.diff().abs().fillna(engine_signal.abs()) > 0).sum()
    )
    engine_turnover = float(
        engine_signal.diff().abs().fillna(engine_signal.abs()).sum()
    )

    engine_coverage = engine_active_bars / n

    notes = []

    if engine_active_bars <= 0:
        verdict = "CUSTOM SIGNAL FLAT"
        level = "error"
        notes.append("Aucune exposition réellement appliquée au moteur.")

    elif short_bars > 0 and allow_short:
        verdict = "LONG/SHORT READY"
        level = "success"
        notes.append("Signal long/short accepté par le moteur.")

    elif short_bars_neutralized > 0 and not allow_short:
        verdict = "LONG-ONLY ADJUSTED"
        level = "warning"
        notes.append("Des signaux short ont été neutralisés car le short est désactivé.")

    else:
        verdict = "LONG-ONLY READY"
        level = "success"
        notes.append("Signal long-only accepté par le moteur.")

    if engine_coverage < 0.05:
        level = "warning" if level != "error" else level
        notes.append("Couverture moteur très faible : conclusion statistique fragile.")

    if engine_changes <= 1 and engine_active_bars > 0:
        level = "warning" if level != "error" else level
        notes.append("Signal quasi statique : le backtest ressemble à un trade unique.")

    return {
        "verdict": verdict,
        "level": level,
        "engine_active_bars": engine_active_bars,
        "engine_coverage": engine_coverage,
        "long_bars": long_bars,
        "short_bars": short_bars,
        "short_bars_neutralized": short_bars_neutralized,
        "engine_changes": engine_changes,
        "engine_turnover": engine_turnover,
        "notes": notes,
    }




# ============================================================
# DATA PROVENANCE / SIGNAL SAFETY GATE V2.6
# ============================================================

def _custom_signal_safety_gate_v26_pack(
    signal_df: Any,
    price_index: pd.Index,
    allow_short: bool = False,
) -> dict[str, Any]:
    """
    Data Provenance & Signal Safety Gate V2.6.

    Lecture seule :
    - ne modifie pas le moteur ;
    - ne modifie pas le signal ;
    - ne modifie pas l'equity curve ;
    - ne modifie pas le verdict principal.
    """
    def _row(gate: str, status: str, severity: str, value: Any, read: str) -> dict[str, Any]:
        return {
            "Gate": str(gate),
            "Status": str(status),
            "Severity": str(severity),
            "Value": str(value),
            "Read": str(read),
        }

    def _norm(x: Any) -> str:
        return str(x or "").lower().strip().replace(" ", "_").replace("-", "_")

    def _attrs(x: Any) -> dict[str, Any]:
        try:
            attrs = getattr(x, "attrs", {})
            return attrs if isinstance(attrs, dict) else {}
        except Exception:
            return {}

    if signal_df is None or not isinstance(signal_df, pd.DataFrame) or signal_df.empty:
        checks = pd.DataFrame(
            [
                _row(
                    "Custom signal present",
                    "SKIP",
                    "Low",
                    "0 rows",
                    "Aucun signal custom chargé : gate disponible mais non applicable.",
                )
            ]
        )

        summary = pd.DataFrame(
            [
                ["Safety level", "Not assessed", "Aucun signal externe à contrôler."],
                ["Safety score", "0/100", "Score non applicable sans signal custom."],
                ["Decision gate", "NO CUSTOM SIGNAL", "Le backtest courant ne dépend pas d'un CSV externe."],
                ["Forbidden leakage columns", "N/A", "Aucune colonne source inspectée."],
                ["Engine coverage", "N/A", "Aucune exposition moteur custom."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        return {
            "enabled": False,
            "level": "Not assessed",
            "score": 0.0,
            "read": "Aucun signal custom chargé : Data Provenance Gate non applicable.",
            "decision_gate": "NO CUSTOM SIGNAL",
            "checks": checks,
            "summary": summary,
            "metadata": pd.DataFrame(),
            "fail_count": 0,
            "warn_count": 0,
            "critical_count": 0,
            "high_count": 0,
            "forbidden_columns": [],
            "cards": [
                {"label": "Signal safety", "value": "Not assessed", "delta": "no custom signal"},
                {"label": "Leakage risk", "value": "N/A", "delta": "not used"},
                {"label": "Decision gate", "value": "NO CUSTOM SIGNAL", "delta": "safe skip"},
            ],
        }

    sig = signal_df.copy()
    attrs = _attrs(signal_df)

    source_columns = attrs.get("source_columns", [])
    if not isinstance(source_columns, list) or not source_columns:
        source_columns = [str(c) for c in sig.columns]

    raw_rows = int(attrs.get("raw_rows", len(sig)) or 0)
    date_col = str(attrs.get("date_col", "date" if "date" in sig.columns else "") or "")
    signal_col = str(attrs.get("signal_col", "signal" if "signal" in sig.columns else "") or "")
    size_col = str(attrs.get("size_col", "") or "")
    available_at_col = str(attrs.get("available_at_col", "") or "")
    raw_duplicate_dates = int(attrs.get("raw_duplicate_dates", 0) or 0)
    raw_invalid_dates = int(attrs.get("raw_invalid_dates", 0) or 0)
    raw_signal_abs_max = _safe_float(attrs.get("raw_signal_abs_max"), np.nan)
    parser_status = str(attrs.get("parser_status", "") or "")

    forbidden_tokens = [
        "future", "forward", "next", "tomorrow", "target", "label", "outcome",
        "realized", "actual", "lead", "lookahead", "look_ahead",
        "future_return", "next_return", "fwd_return", "forward_return",
        "return_next", "return_fwd", "next_close", "next_open",
        "future_close", "future_price", "pnl", "profit", "hit_target", "y",
    ]

    allowed_core = {
        "date", "datetime", "timestamp", "time", "signal", "exposure",
        "position", "position_pct", "side", "size", "weight",
        "available_at", "available_time", "published_at", "release_time",
        "asof", "as_of", "effective_at",
    }

    forbidden_columns = []
    for col in source_columns:
        norm = _norm(col)
        if norm in allowed_core:
            continue
        if any(tok == norm or tok in norm for tok in forbidden_tokens):
            forbidden_columns.append(str(col))

    raw_signal = _align_custom_signal_to_prices(sig, price_index)

    effective_signal = raw_signal.copy()
    if not allow_short:
        effective_signal = effective_signal.clip(lower=0.0, upper=1.0)

    engine_signal = effective_signal.shift(1).fillna(0.0).clip(-1.0, 1.0)

    n = max(len(engine_signal), 1)
    engine_active = int((engine_signal.abs() > 0).sum())
    engine_changes = int((engine_signal.diff().abs().fillna(engine_signal.abs()) > 0).sum())
    engine_coverage = engine_active / n
    short_neutralized = int(((raw_signal < 0) & (effective_signal == 0)).sum())
    first_engine_exposure = _safe_float(engine_signal.iloc[0], 0.0) if len(engine_signal) else 0.0

    price_start, price_end = _price_index_bounds(price_index)

    signal_mode = "sequential"
    signal_start = None
    signal_end = None

    try:
        if "date" in sig.columns and sig["date"].notna().any():
            sig_dates = pd.to_datetime(sig["date"], errors="coerce").dropna()
            if not sig_dates.empty:
                signal_mode = "dated"
                signal_start = pd.Timestamp(sig_dates.min()).normalize()
                signal_end = pd.Timestamp(sig_dates.max()).normalize()
    except Exception:
        pass

    rows = []

    rows.append(_row("Custom signal present", "PASS", "None", f"{len(sig)} clean / {raw_rows} raw", "Signal externe parsé sans exécution de code utilisateur."))
    rows.append(_row("Source columns retained", "PASS" if source_columns else "WARN", "None" if source_columns else "Low", ", ".join(source_columns[:12]) if source_columns else "N/A", "Colonnes source conservées pour audit de provenance."))

    if forbidden_columns:
        rows.append(_row("Forbidden leakage columns", "FAIL", "Critical", ", ".join(forbidden_columns[:12]), "Colonnes suspectes de target/future/next return : validation positive interdite sans retraitement."))
    else:
        rows.append(_row("Forbidden leakage columns", "PASS", "None", "0", "Aucune colonne explicitement future-looking détectée."))

    if signal_mode == "dated":
        rows.append(_row("Timestamp column", "PASS", "None", date_col or "date", "Signal daté : alignement temporel auditable."))
    else:
        rows.append(_row("Timestamp column", "WARN", "High", "sequential fallback", "Signal sans date exploitable : risque d'alignement ou de sélection de fenêtre."))

    rows.append(_row("Invalid raw dates", "WARN" if raw_invalid_dates > 0 else ("PASS" if signal_mode == "dated" else "SKIP"), "Medium" if raw_invalid_dates > 0 else ("None" if signal_mode == "dated" else "Low"), raw_invalid_dates, "Dates invalides avant nettoyage."))
    rows.append(_row("Duplicate raw dates", "WARN" if raw_duplicate_dates > 0 else ("PASS" if signal_mode == "dated" else "SKIP"), "Medium" if raw_duplicate_dates > 0 else ("None" if signal_mode == "dated" else "Low"), raw_duplicate_dates, "Doublons de date source avant nettoyage."))

    if signal_mode == "dated" and price_start is not None and price_end is not None and signal_start is not None and signal_end is not None:
        overlap_start = max(price_start, signal_start)
        overlap_end = min(price_end, signal_end)

        if overlap_start <= overlap_end:
            rows.append(_row("Price / signal overlap", "PASS", "None", f"{_format_dt(overlap_start)} -> {_format_dt(overlap_end)}", "Le signal chevauche la fenêtre de prix backtestée."))
        else:
            rows.append(_row("Price / signal overlap", "FAIL", "Critical", f"price {_format_dt(price_start)}->{_format_dt(price_end)} / signal {_format_dt(signal_start)}->{_format_dt(signal_end)}", "Aucun chevauchement temporel : signal non validable."))
    else:
        rows.append(_row("Price / signal overlap", "SKIP" if signal_mode != "dated" else "WARN", "Low" if signal_mode != "dated" else "Medium", "N/A", "Chevauchement non auditable sans dates ou index prix daté."))

    if "available_at" in sig.columns:
        try:
            available_at = pd.to_datetime(sig["available_at"], errors="coerce")
            invalid_available = int(available_at.isna().sum())
        except Exception:
            available_at = pd.Series(dtype="datetime64[ns]")
            invalid_available = len(sig)

        rows.append(_row("available_at present", "PASS" if invalid_available == 0 else "WARN", "None" if invalid_available == 0 else "Medium", available_at_col or "available_at", "Colonne de disponibilité détectée."))

        if "date" in sig.columns:
            try:
                d = pd.to_datetime(sig["date"], errors="coerce")
                future_available = int((available_at.dt.normalize() > d.dt.normalize()).fillna(False).sum())
            except Exception:
                future_available = 0

            rows.append(_row("available_at after decision date", "WARN" if future_available > 0 else "PASS", "High" if future_available > 0 else "None", future_available, "Si available_at est après date, aligner sur available_at ou imposer un lag."))
    else:
        rows.append(_row("available_at present", "SKIP", "Low", "missing", "Optionnel mais recommandé pour distinguer event_date et disponibilité réelle."))

    rows.append(_row("Engine t+1 shift enforced", "PASS", "None", "shift(1)", "Le moteur utilise l'exposition décalée d'une barre."))
    rows.append(_row("First engine exposure zero", "PASS" if abs(first_engine_exposure) <= 1e-12 else "FAIL", "None" if abs(first_engine_exposure) <= 1e-12 else "Critical", _format_num(first_engine_exposure), "La première barre moteur doit rester neutre après t+1."))

    if engine_active <= 0:
        rows.append(_row("Engine active exposure", "FAIL", "High", "0 bars", "Aucune exposition réellement backtestée."))
    elif engine_coverage < 0.05:
        rows.append(_row("Engine active exposure", "WARN", "Medium", _format_pct(engine_coverage), "Couverture faible : conclusion statistique fragile."))
    else:
        rows.append(_row("Engine active exposure", "PASS", "None", _format_pct(engine_coverage), "Exposition moteur exploitable."))

    rows.append(_row("Engine signal changes", "WARN" if engine_changes <= 1 and engine_active > 0 else "PASS", "Medium" if engine_changes <= 1 and engine_active > 0 else "None", engine_changes, "Changements d'exposition réellement appliqués après t+1."))
    rows.append(_row("Short signal neutralization", "WARN" if short_neutralized > 0 and not allow_short else "PASS", "Medium" if short_neutralized > 0 and not allow_short else "None", short_neutralized, "Barres short neutralisées si short désactivé."))
    rows.append(_row("Raw exposure clipping", "WARN" if pd.notna(raw_signal_abs_max) and raw_signal_abs_max > 1.0001 else "PASS", "Medium" if pd.notna(raw_signal_abs_max) and raw_signal_abs_max > 1.0001 else "None", _format_num(raw_signal_abs_max) if pd.notna(raw_signal_abs_max) else "N/A", "Exposition brute supérieure à 1 avant clipping."))
    rows.append(_row("Price index timestamp quality", "PASS" if _is_datetime_like_index(price_index) else "WARN", "None" if _is_datetime_like_index(price_index) else "High", f"{_format_dt(price_start)} -> {_format_dt(price_end)}" if _is_datetime_like_index(price_index) else "non-datetime", "Index prix daté requis pour audit temporel robuste."))

    checks = pd.DataFrame(rows)

    fail_count = int((checks["Status"].astype(str) == "FAIL").sum()) if not checks.empty else 0
    warn_count = int((checks["Status"].astype(str) == "WARN").sum()) if not checks.empty else 0
    critical_count = int(((checks["Status"].astype(str) == "FAIL") & (checks["Severity"].astype(str) == "Critical")).sum()) if not checks.empty else 0
    high_count = int((checks["Severity"].astype(str) == "High").sum()) if not checks.empty else 0
    medium_count = int((checks["Severity"].astype(str) == "Medium").sum()) if not checks.empty else 0
    low_count = int((checks["Severity"].astype(str) == "Low").sum()) if not checks.empty else 0

    score = 100.0
    score -= critical_count * 45.0
    score -= max(0, fail_count - critical_count) * 25.0
    score -= high_count * 12.0
    score -= medium_count * 7.0
    score -= low_count * 2.0
    score = max(0.0, min(100.0, score))

    if critical_count > 0:
        level = "Blocked"
        decision_gate = "BLOCKED"
        read = "Signal externe bloqué par risque de leakage ou causalité critique."
    elif fail_count > 0 or high_count > 0 or score < 70:
        level = "High caution"
        decision_gate = "MANUAL REVIEW"
        read = "Signal exploitable uniquement après revue manuelle des timestamps/provenance."
    elif warn_count > 0:
        level = "Review"
        decision_gate = "REVIEW BEFORE VALIDATION"
        read = "Signal acceptable techniquement mais avec avertissements de provenance."
    else:
        level = "Clean"
        decision_gate = "PASS"
        read = "Aucun risque majeur de provenance/leakage détecté."

    metadata = pd.DataFrame(
        [
            ["source_columns", ", ".join(source_columns), "Colonnes source observées dans le CSV."],
            ["raw_rows", str(raw_rows), "Lignes brutes avant nettoyage."],
            ["clean_rows", str(len(sig)), "Lignes après parsing."],
            ["date_col", date_col or "N/A", "Colonne utilisée comme date."],
            ["signal_col", signal_col or "N/A", "Colonne utilisée comme signal/exposure."],
            ["size_col", size_col or "N/A", "Colonne de taille utilisée si présente."],
            ["available_at_col", available_at_col or "N/A", "Colonne de disponibilité si présente."],
            ["signal_mode", signal_mode, "Mode daté ou séquentiel."],
            ["parser_status", parser_status or "N/A", "Message de parsing initial."],
            ["forbidden_columns", ", ".join(forbidden_columns) if forbidden_columns else "None", "Colonnes suspectes de leakage."],
        ],
        columns=["Field", "Value", "Read"],
    )

    summary = pd.DataFrame(
        [
            ["Safety level", level, "Lecture synthétique du Signal Safety Gate V2.6."],
            ["Safety score", f"{_format_num(score, 0)}/100", "Score pénalisé par leakage, timestamps, couverture et alignement."],
            ["Decision gate", decision_gate, "Décision de sécurité avant validation positive d'un signal externe."],
            ["Read", read, "Interprétation opérationnelle."],
            ["Forbidden leakage columns", ", ".join(forbidden_columns) if forbidden_columns else "None", "Colonnes future-looking / target détectées."],
            ["Signal mode", signal_mode, "Daté ou séquentiel."],
            ["Raw rows", str(raw_rows), "Lignes brutes avant nettoyage."],
            ["Clean rows", str(len(sig)), "Lignes nettoyées."],
            ["Duplicate raw dates", str(raw_duplicate_dates), "Doublons de dates source."],
            ["Invalid raw dates", str(raw_invalid_dates), "Dates invalides avant nettoyage."],
            ["Engine active bars", str(engine_active), "Barres réellement exposées après t+1."],
            ["Engine coverage", _format_pct(engine_coverage), "Part de l'historique exposée."],
            ["Engine changes", str(engine_changes), "Changements d'exposition après t+1."],
            ["Short neutralized", str(short_neutralized), "Barres short neutralisées si short désactivé."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    cards = [
        {"label": "Signal safety", "value": level, "delta": f"{_format_num(score, 0)}/100"},
        {"label": "Leakage columns", "value": str(len(forbidden_columns)), "delta": "forbidden"},
        {"label": "Decision gate", "value": decision_gate, "delta": "V2.6"},
        {"label": "Coverage", "value": _format_pct(engine_coverage, 0), "delta": f"{engine_active} bars"},
        {"label": "Warnings", "value": str(warn_count), "delta": "review"},
        {"label": "Fails", "value": str(fail_count), "delta": "blocking"},
    ]

    return {
        "enabled": True,
        "level": level,
        "score": score,
        "read": read,
        "decision_gate": decision_gate,
        "checks": checks,
        "summary": summary,
        "metadata": metadata,
        "fail_count": fail_count,
        "warn_count": warn_count,
        "critical_count": critical_count,
        "high_count": high_count,
        "forbidden_columns": forbidden_columns,
        "cards": cards,
    }


def _render_custom_signal_safety_gate_v26(pack: dict[str, Any]) -> None:
    pack = pack if isinstance(pack, dict) else {}

    st.markdown("**Data Provenance & Signal Safety Gate V2.6**")
    st.caption(
        "Contrôle lecture seule du signal externe : colonnes future-looking, timestamps, available_at, "
        "doublons, overlap prix/signal, t+1, couverture moteur et neutralisation short."
    )

    _card_grid(pack.get("cards", []), columns=6)

    level = str(pack.get("level", "Not assessed"))
    read = str(pack.get("read", ""))

    if level == "Blocked":
        st.error(f"Signal safety : {read}")
    elif level in {"High caution", "Review"}:
        st.warning(f"Signal safety : {read}")
    elif level == "Clean":
        st.success(f"Signal safety : {read}")
    else:
        st.info(f"Signal safety : {read or 'Aucun signal custom à contrôler.'}")

    summary = pack.get("summary", pd.DataFrame())
    checks = pack.get("checks", pd.DataFrame())
    metadata = pack.get("metadata", pd.DataFrame())

    with st.expander("Signal Safety summary V2.6", expanded=True):
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé Signal Safety indisponible.")

    with st.expander("Signal Safety checks V2.6", expanded=True):
        if isinstance(checks, pd.DataFrame) and not checks.empty:
            st.dataframe(checks, use_container_width=True, hide_index=True)
        else:
            st.info("Checks Signal Safety indisponibles.")

    with st.expander("Signal provenance metadata V2.6", expanded=False):
        if isinstance(metadata, pd.DataFrame) and not metadata.empty:
            st.dataframe(metadata, use_container_width=True, hide_index=True)
        else:
            st.info("Metadata provenance indisponible.")

# ============================================================
# CUSTOM SIGNAL IMPORT V2 / EXTERNAL STRATEGY VALIDATOR
# ============================================================

def _custom_signal_validator_v2_pack(
    signal_df: Any,
    price_index: pd.Index,
    allow_short: bool,
) -> dict[str, Any]:
    """
    Custom Signal Import V2 / External Strategy Validator.

    Lecture seule :
    - ne modifie pas le moteur ;
    - ne modifie pas l'equity curve ;
    - ne modifie pas le verdict ;
    - expose clairement le signal brut, le signal effectif et le signal réellement backtesté t+1.

    Objectif :
    transformer le Backtest Lab en validateur de stratégie externe.
    """
    empty = {
        "status": "NO CUSTOM SIGNAL",
        "level": "error",
        "cards": [],
        "health": pd.DataFrame(),
        "aligned": pd.DataFrame(),
        "events": pd.DataFrame(),
        "segments": pd.DataFrame(),
        "warnings": ["Aucun signal custom exploitable."],
        "summary": {},
    }

    if signal_df is None or not isinstance(signal_df, pd.DataFrame) or signal_df.empty:
        return empty

    try:
        raw_signal = _align_custom_signal_to_prices(signal_df, price_index)

        effective_signal = raw_signal.copy()
        if not allow_short:
            effective_signal = effective_signal.clip(lower=0.0, upper=1.0)

        engine_signal = effective_signal.shift(1).fillna(0.0).clip(-1.0, 1.0)

        n = max(len(engine_signal), 1)

        raw_active = int((raw_signal.abs() > 0).sum())
        effective_active = int((effective_signal.abs() > 0).sum())
        engine_active = int((engine_signal.abs() > 0).sum())

        long_bars = int((engine_signal > 0).sum())
        short_bars = int((engine_signal < 0).sum())
        flat_bars = int((engine_signal == 0).sum())

        raw_changes = int((raw_signal.diff().abs().fillna(raw_signal.abs()) > 0).sum())
        effective_changes = int((effective_signal.diff().abs().fillna(effective_signal.abs()) > 0).sum())
        engine_changes = int((engine_signal.diff().abs().fillna(engine_signal.abs()) > 0).sum())

        neutralized_short_bars = int(((raw_signal < 0) & (effective_signal == 0)).sum())

        engine_turnover = float(engine_signal.diff().abs().fillna(engine_signal.abs()).sum())
        max_abs_exposure = float(engine_signal.abs().max()) if len(engine_signal) else 0.0
        avg_abs_exposure = float(engine_signal.abs().mean()) if len(engine_signal) else 0.0
        net_bias = float(engine_signal.mean()) if len(engine_signal) else 0.0

        price_start, price_end = _price_index_bounds(price_index)

        signal_mode = "sequential"
        signal_start = "N/A"
        signal_end = "N/A"
        signal_rows = int(len(signal_df))

        try:
            if "date" in signal_df.columns and signal_df["date"].notna().any():
                sig_dates = pd.to_datetime(signal_df["date"], errors="coerce").dropna()
                if not sig_dates.empty:
                    signal_mode = "dated"
                    signal_start = _format_dt(sig_dates.min())
                    signal_end = _format_dt(sig_dates.max())
        except Exception:
            pass

        date_values = [
            _format_dt(x) if _is_datetime_like_index(price_index) else str(x)
            for x in list(price_index)
        ]

        aligned = pd.DataFrame(
            {
                "Date": date_values,
                "Raw Signal": raw_signal.values,
                "Effective Signal": effective_signal.values,
                "Engine Exposure T+1": engine_signal.values,
                "Raw Change": raw_signal.diff().abs().fillna(raw_signal.abs()).values,
                "Engine Change": engine_signal.diff().abs().fillna(engine_signal.abs()).values,
            }
        )

        aligned["Side"] = np.where(
            aligned["Engine Exposure T+1"] > 0,
            "LONG",
            np.where(aligned["Engine Exposure T+1"] < 0, "SHORT", "FLAT"),
        )

        change_mask = (
            pd.Series(aligned["Raw Change"]).abs().fillna(0) > 0
        ) | (
            pd.Series(aligned["Engine Change"]).abs().fillna(0) > 0
        )

        events = aligned.loc[change_mask.values].copy()

        if not aligned.empty:
            boundary = aligned.iloc[[0, len(aligned) - 1]].copy()
            events = (
                pd.concat([boundary, events], ignore_index=True)
                .drop_duplicates(subset=["Date"], keep="last")
                .sort_values("Date")
                .tail(50)
            )

        seg = aligned[["Date", "Engine Exposure T+1"]].copy()
        seg["group"] = seg["Engine Exposure T+1"].ne(seg["Engine Exposure T+1"].shift()).cumsum()

        segments = (
            seg.groupby("group", as_index=False)
            .agg(
                Start=("Date", "first"),
                End=("Date", "last"),
                Exposure=("Engine Exposure T+1", "first"),
                Bars=("Date", "size"),
            )
        )

        segments = segments[segments["Exposure"].abs() > 0].copy()

        if not segments.empty:
            segments["Side"] = np.where(segments["Exposure"] > 0, "LONG", "SHORT")
            segments = segments[["Start", "End", "Side", "Exposure", "Bars"]]

        warnings = []

        if engine_active <= 0:
            status = "FLAT / NOT TESTABLE"
            level = "error"
            warnings.append("Aucune exposition réellement appliquée au moteur après alignement et t+1.")

        elif engine_active / n < 0.05:
            status = "THIN SAMPLE"
            level = "warning"
            warnings.append("Couverture moteur inférieure à 5% : conclusion statistique fragile.")

        elif engine_changes <= 1:
            status = "STATIC SIGNAL"
            level = "warning"
            warnings.append("Signal quasi statique : le backtest ressemble à un trade unique ou à une exposition buy-and-hold.")

        elif short_bars > 0 and allow_short:
            status = "LONG/SHORT READY"
            level = "success"

        elif neutralized_short_bars > 0 and not allow_short:
            status = "LONG-ONLY ADJUSTED"
            level = "warning"
            warnings.append("Des signaux short ont été neutralisés car le short est désactivé.")

        else:
            status = "LONG-ONLY READY"
            level = "success"

        if raw_active > effective_active:
            warnings.append("Une partie du signal brut a été neutralisée avant passage moteur.")

        if max_abs_exposure > 1.0001:
            warnings.append("Exposition supérieure à 1 détectée avant clipping. Le moteur limite à [-1, 1].")

        if engine_turnover > max(engine_changes * 2.5, 10):
            warnings.append("Turnover élevé : vérifier que le signal ne sur-réagit pas au bruit.")

        health = pd.DataFrame(
            [
                ["Validator status", status, "Statut synthétique du signal externe."],
                [
                    "Price window",
                    (
                        f"{_format_dt(price_start)} → {_format_dt(price_end)}"
                        if price_start is not None and price_end is not None
                        else "N/A"
                    ),
                    "Fenêtre de prix disponible.",
                ],
                ["Signal mode", signal_mode, "Signal daté ou séquentiel."],
                ["Signal window", f"{signal_start} → {signal_end}", "Fenêtre fournie dans le CSV si le signal est daté."],
                ["Signal rows", str(signal_rows), "Nombre de lignes nettoyées dans le signal importé."],
                ["Raw active bars", str(raw_active), "Barres actives avant règle short et avant t+1."],
                ["Effective active bars", str(effective_active), "Barres actives après neutralisation éventuelle des shorts."],
                ["Engine active bars", str(engine_active), "Barres réellement backtestées après t+1."],
                ["Engine coverage", _format_pct(engine_active / n), "Part de l'historique où le moteur est exposé."],
                ["Long bars", str(long_bars), "Barres moteur en exposition long."],
                ["Short bars", str(short_bars), "Barres moteur en exposition short."],
                ["Flat bars", str(flat_bars), "Barres moteur sans exposition."],
                ["Neutralized short bars", str(neutralized_short_bars), "Barres short neutralisées car short désactivé."],
                ["Raw changes", str(raw_changes), "Changements dans le signal brut aligné."],
                ["Effective changes", str(effective_changes), "Changements après règle short."],
                ["Engine changes", str(engine_changes), "Changements réellement appliqués après t+1."],
                ["Engine turnover", _format_num(engine_turnover), "Somme absolue des changements d'exposition moteur."],
                ["Max abs exposure", _format_num(max_abs_exposure), "Exposition maximale absolue appliquée."],
                ["Average abs exposure", _format_num(avg_abs_exposure), "Exposition moyenne absolue."],
                ["Net bias", _format_num(net_bias), "Biais moyen : positif = long, négatif = short."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        cards = [
            {
                "label": "Validator status",
                "value": status,
                "delta": "custom signal",
            },
            {
                "label": "Engine coverage",
                "value": _format_pct(engine_active / n, 0),
                "delta": f"{engine_active} bars",
            },
            {
                "label": "Signal changes",
                "value": str(engine_changes),
                "delta": "after t+1",
            },
            {
                "label": "Long / Short bars",
                "value": f"{long_bars}/{short_bars}",
                "delta": "engine",
            },
            {
                "label": "Net bias",
                "value": _format_num(net_bias),
                "delta": "avg exposure",
            },
            {
                "label": "Turnover",
                "value": _format_num(engine_turnover),
                "delta": "signal",
            },
        ]

        safety_gate = _custom_signal_safety_gate_v26_pack(signal_df, price_index, allow_short)

        summary = {
            "safety_level": str(safety_gate.get("level", "N/A")) if isinstance(safety_gate, dict) else "N/A",
            "safety_score": _safe_float(safety_gate.get("score"), np.nan) if isinstance(safety_gate, dict) else np.nan,
            "safety_decision_gate": str(safety_gate.get("decision_gate", "N/A")) if isinstance(safety_gate, dict) else "N/A",
            "level": level,
            "signal_rows": signal_rows,
            "signal_mode": signal_mode,
            "signal_start": signal_start,
            "signal_end": signal_end,
            "engine_active_bars": engine_active,
            "engine_coverage": engine_active / n,
            "long_bars": long_bars,
            "short_bars": short_bars,
            "flat_bars": flat_bars,
            "neutralized_short_bars": neutralized_short_bars,
            "engine_changes": engine_changes,
            "engine_turnover": engine_turnover,
            "max_abs_exposure": max_abs_exposure,
            "avg_abs_exposure": avg_abs_exposure,
            "net_bias": net_bias,
            "warnings": warnings,
        }

        return {
            "status": status,
            "level": level,
            "cards": cards,
            "health": health,
            "aligned": aligned,
            "events": events,
            "segments": segments,
            "warnings": warnings,
            "summary": summary,
            "safety_gate_v26": safety_gate,
        }

    except Exception as exc:
        out = empty.copy()
        out["status"] = "VALIDATOR ERROR"
        out["warnings"] = [f"Erreur validator V2 : {exc}"]
        return out


def _render_custom_signal_validator_v2(
    signal_df: Any,
    price_index: pd.Index,
    allow_short: bool,
) -> dict[str, Any]:
    """
    Rendu Streamlit du Custom Signal Import V2.
    Lecture seule.
    """
    pack = _custom_signal_validator_v2_pack(signal_df, price_index, allow_short)

    st.markdown("**External Strategy Validator V2**")
    st.caption(
        "Validation du signal importé : signal brut, signal effectif, exposition réellement backtestée après t+1, "
        "couverture, turnover, biais long/short, segments actifs et export CSV. "
        "Aucun code utilisateur n'est exécuté."
    )

    _card_grid(pack.get("cards", []), columns=6)

    warnings = pack.get("warnings", [])
    safety_pack = pack.get("safety_gate_v26", {})
    if not isinstance(safety_pack, dict) or not safety_pack:
        safety_pack = _custom_signal_safety_gate_v26_pack(signal_df, price_index, allow_short)
        pack["safety_gate_v26"] = safety_pack

    _render_custom_signal_safety_gate_v26(safety_pack)


    if warnings:
        warning_text = " ".join([str(x) for x in warnings if str(x).strip()])
        if str(pack.get("level")) == "error":
            st.error(warning_text)
        else:
            st.warning(warning_text)

    health = pack.get("health", pd.DataFrame())
    events = pack.get("events", pd.DataFrame())
    segments = pack.get("segments", pd.DataFrame())
    aligned = pack.get("aligned", pd.DataFrame())

    with st.expander("Validator V2 health report", expanded=True):
        if isinstance(health, pd.DataFrame) and not health.empty:
            st.dataframe(health, use_container_width=True, hide_index=True)
        else:
            st.info("Health report indisponible.")

    with st.expander("Aligned signal export preview", expanded=False):
        if isinstance(aligned, pd.DataFrame) and not aligned.empty:
            st.dataframe(aligned.tail(60), use_container_width=True, hide_index=True)
        else:
            st.info("Signal aligné indisponible.")

    with st.expander("Signal change events", expanded=False):
        if isinstance(events, pd.DataFrame) and not events.empty:
            st.dataframe(events, use_container_width=True, hide_index=True)
        else:
            st.info("Aucun changement de signal détecté.")

    with st.expander("Active exposure segments", expanded=False):
        if isinstance(segments, pd.DataFrame) and not segments.empty:
            st.dataframe(segments, use_container_width=True, hide_index=True)
        else:
            st.info("Aucun segment actif détecté.")

    d1, d2, d3 = st.columns(3)

    if isinstance(aligned, pd.DataFrame) and not aligned.empty:
        d1.download_button(
            "Télécharger aligned signal CSV",
            data=aligned.to_csv(index=False).encode("utf-8"),
            file_name="custom_signal_aligned_t1.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_custom_signal_aligned_download",
        )

    if isinstance(events, pd.DataFrame) and not events.empty:
        d2.download_button(
            "Télécharger signal events CSV",
            data=events.to_csv(index=False).encode("utf-8"),
            file_name="custom_signal_events.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_custom_signal_events_download",
        )

    if isinstance(segments, pd.DataFrame) and not segments.empty:
        d3.download_button(
            "Télécharger signal segments CSV",
            data=segments.to_csv(index=False).encode("utf-8"),
            file_name="custom_signal_segments.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_custom_signal_segments_download",
        )

    return pack


def _build_signal(df: pd.DataFrame, cfg: BacktestConfig) -> pd.Series:
    close = df["close"]
    signal = pd.Series(0.0, index=df.index)

    if cfg.strategy == "SMA Trend":
        fast = close.rolling(cfg.fast_ma).mean()
        slow = close.rolling(cfg.slow_ma).mean()
        raw = (fast > slow).astype(float)
        if cfg.allow_short:
            raw = np.where(fast > slow, 1.0, np.where(fast < slow, -1.0, 0.0))
        signal = pd.Series(raw, index=df.index).fillna(0.0)

    elif cfg.strategy == "Breakout":
        high = close.shift(1).rolling(cfg.breakout_window).max()
        low = close.shift(1).rolling(cfg.breakout_window).min()

        raw = pd.Series(0.0, index=df.index)
        raw[close > high] = 1.0
        if cfg.allow_short:
            raw[close < low] = -1.0

        signal = raw.replace(0.0, np.nan).ffill().fillna(0.0)

    elif cfg.strategy == "RSI Mean Reversion":
        rsi = _rsi(close, cfg.rsi_window)

        raw = pd.Series(np.nan, index=df.index)
        raw[rsi < cfg.rsi_entry] = 1.0
        raw[rsi > cfg.rsi_exit] = 0.0

        if cfg.allow_short:
            raw[rsi > (100 - cfg.rsi_entry)] = -1.0
            raw[rsi < (100 - cfg.rsi_exit)] = 0.0

        signal = raw.ffill().fillna(0.0)

    elif cfg.strategy == "Volatility Filter Trend":
        fast = close.rolling(cfg.fast_ma).mean()
        slow = close.rolling(cfg.slow_ma).mean()
        vol = close.pct_change().rolling(cfg.vol_window).std() * np.sqrt(252)

        raw = np.where((fast > slow) & (vol < cfg.vol_threshold), 1.0, 0.0)
        if cfg.allow_short:
            raw = np.where((fast < slow) & (vol < cfg.vol_threshold), -1.0, raw)

        signal = pd.Series(raw, index=df.index).fillna(0.0)

    elif cfg.strategy == "Decision Proxy":
        fast = close.rolling(cfg.fast_ma).mean()
        slow = close.rolling(cfg.slow_ma).mean()
        mom = close.pct_change(20)
        vol = close.pct_change().rolling(cfg.vol_window).std() * np.sqrt(252)

        raw_score = (
            (fast > slow).astype(float) * 40
            + (mom > 0).astype(float) * 35
            + (vol < cfg.vol_threshold).astype(float) * 25
        )

        raw = (raw_score >= 65).astype(float)
        if cfg.allow_short:
            raw = np.where(raw_score <= 30, -1.0, raw)

        signal = pd.Series(raw, index=df.index).fillna(0.0)

    elif cfg.strategy == "Manual Builder":
        signal = _manual_builder_signal(df, cfg)

    elif cfg.strategy == "Benchmark-Relative Trend":
        signal = _benchmark_relative_trend_signal_v35(df, cfg)

    elif cfg.strategy == "Custom Signal Import":
        signal = _align_custom_signal_to_prices(getattr(cfg, "custom_signal_df", None), df.index)

        # Sécurité : si le short n'est pas autorisé, un signal custom négatif devient flat.
        if not cfg.allow_short:
            signal = signal.clip(lower=0.0, upper=1.0)

    return signal.shift(1).fillna(0.0).clip(-1.0, 1.0)


def _entry_reason(strategy: str, side: float) -> str:
    side_txt = "long" if side >= 0 else "short"
    mapping = {
        "SMA Trend": f"{side_txt.upper()} after fast/slow MA regime confirmation",
        "Breakout": f"{side_txt.upper()} after prior-window breakout confirmation",
        "RSI Mean Reversion": f"{side_txt.upper()} after RSI mean-reversion threshold",
        "Volatility Filter Trend": f"{side_txt.upper()} after trend confirmation under volatility cap",
        "Benchmark-Relative Trend": f"{side_txt.upper()} after benchmark-relative trend confirmation",
        "Decision Proxy": f"{side_txt.upper()} after composite proxy score threshold",
        "Manual Builder": f"{side_txt.upper()} from manual rule builder",
        "Custom Signal Import": f"{side_txt.upper()} from imported external signal",
    }
    return mapping.get(strategy, f"{side_txt.upper()} signal activated")


def _exit_reason(strategy: str, final_exit: bool = False) -> str:
    if final_exit:
        return "Open trade marked to last available close"
    mapping = {
        "SMA Trend": "Trend filter no longer confirms exposure",
        "Breakout": "Breakout state reversed or exposure closed",
        "RSI Mean Reversion": "RSI exit threshold or exposure close",
        "Volatility Filter Trend": "Trend/volatility filter no longer confirms exposure",
        "Benchmark-Relative Trend": "Benchmark-relative trend or regime gate no longer confirms exposure",
        "Decision Proxy": "Composite proxy score no longer confirms exposure",
        "Manual Builder": "Manual builder exit condition triggered",
        "Custom Signal Import": "Imported signal changed or closed exposure",
    }
    return mapping.get(strategy, "Exposure changed or closed")


# ============================================================
# POSITION SIZING / VOL TARGETING V1
# ============================================================

def _apply_position_sizing_layer(
    df: pd.DataFrame,
    signal: pd.Series,
    cfg: BacktestConfig,
) -> tuple[pd.Series, pd.DataFrame]:
    """
    Position Sizing / Vol Targeting V1.

    Objectif :
    - transformer le signal directionnel en exposition réelle ;
    - conserver le signal t+1 déjà produit par _build_signal ;
    - permettre Fixed Exposure, Vol Target, Trade Risk Budget, Drawdown Cut ;
    - rester sans levier : exposition finale bornée entre -100% et +100%.

    Lecture moteur :
    - signal = direction / conviction brute [-1, 1] ;
    - exposure = taille réellement backtestée après sizing.
    """
    if df is None or df.empty:
        empty = pd.Series(0.0, index=getattr(signal, "index", pd.Index([])))
        return empty, pd.DataFrame()

    base = pd.to_numeric(signal, errors="coerce").fillna(0.0).clip(-1.0, 1.0)
    close = pd.to_numeric(df["close"].reindex(base.index), errors="coerce").ffill()
    returns = close.pct_change().fillna(0.0)

    base_position = max(min(float(getattr(cfg, "position_pct", 100.0)) / 100.0, 1.0), 0.0)

    mode = str(getattr(cfg, "sizing_mode", "Fixed Exposure") or "Fixed Exposure")

    vol_target = max(float(getattr(cfg, "sizing_vol_target_pct", 20.0)), 0.1) / 100.0
    vol_window = max(int(getattr(cfg, "sizing_vol_window", 20)), 2)

    min_exp = max(min(float(getattr(cfg, "sizing_min_exposure_pct", 0.0)) / 100.0, 1.0), 0.0)
    max_exp = max(min(float(getattr(cfg, "sizing_max_exposure_pct", 100.0)) / 100.0, 1.0), 0.0)

    if max_exp < min_exp:
        max_exp = min_exp

    direction = np.sign(base)
    magnitude = base.abs()
    active = magnitude > 0

    realized_vol = (
        returns.rolling(vol_window).std().shift(1) * np.sqrt(252)
    ).replace([np.inf, -np.inf], np.nan)

    realized_vol = realized_vol.ffill()

    raw_abs = magnitude * base_position

    vol_multiplier = pd.Series(1.0, index=base.index)

    if "Vol Target" in mode:
        vol_multiplier = (vol_target / realized_vol.replace(0, np.nan)).replace([np.inf, -np.inf], np.nan)
        vol_multiplier = vol_multiplier.fillna(1.0).clip(lower=0.0, upper=5.0)

    target_abs = raw_abs * vol_multiplier

    target_abs = target_abs.where(active, 0.0)
    target_abs = target_abs.clip(lower=0.0, upper=max_exp)

    if min_exp > 0:
        target_abs = target_abs.where(~active, target_abs.clip(lower=min_exp))

    # Trade risk budget : risque par trade / distance stop.
    risk_budget_cap = pd.Series(np.nan, index=base.index)

    use_risk_budget = bool(getattr(cfg, "sizing_use_trade_risk_budget", False)) or ("Risk Budget" in mode)

    if use_risk_budget:
        stop_distance = max(float(getattr(cfg, "risk_stop_loss_pct", 8.0)), 0.1) / 100.0
        trade_risk = max(float(getattr(cfg, "sizing_trade_risk_pct", 1.0)), 0.01) / 100.0

        cap = trade_risk / stop_distance
        cap = max(0.0, min(max_exp, cap))

        risk_budget_cap = pd.Series(cap, index=base.index)
        target_abs = np.minimum(target_abs, risk_budget_cap)

    # Drawdown cut causal approximatif : basé sur une equity proxy laggée.
    dd_cut_active = pd.Series(False, index=base.index)
    dd_proxy = pd.Series(0.0, index=base.index)

    if bool(getattr(cfg, "sizing_use_drawdown_cut", False)):
        dd_cut = max(float(getattr(cfg, "sizing_drawdown_cut_pct", 15.0)), 0.1) / 100.0
        dd_floor = max(min(float(getattr(cfg, "sizing_drawdown_floor_pct", 25.0)) / 100.0, 1.0), 0.0)

        pre_cut_exposure = direction * target_abs
        proxy_returns = (pre_cut_exposure * returns).fillna(0.0)
        proxy_equity = (1.0 + proxy_returns).cumprod()
        proxy_peak = proxy_equity.cummax()
        dd_proxy = proxy_equity / proxy_peak.replace(0, np.nan) - 1.0
        dd_proxy = dd_proxy.replace([np.inf, -np.inf], np.nan).fillna(0.0)

        dd_cut_active = dd_proxy.shift(1).fillna(0.0) <= -dd_cut

        target_abs = target_abs.where(~(dd_cut_active & active), target_abs * dd_floor)

    exposure = direction * target_abs
    exposure = exposure.fillna(0.0).clip(-1.0, 1.0)

    denom = (magnitude * base_position).replace(0, np.nan)
    sizing_multiplier = (target_abs / denom).replace([np.inf, -np.inf], np.nan).fillna(0.0)

    sizing_frame = pd.DataFrame(
        {
            "target_abs_exposure": target_abs,
            "sizing_multiplier": sizing_multiplier,
            "realized_vol_ann": realized_vol,
            "vol_target_ann": vol_target,
            "risk_budget_cap": risk_budget_cap,
            "sizing_drawdown_proxy": dd_proxy,
            "sizing_drawdown_cut_active": dd_cut_active.astype(float),
        },
        index=base.index,
    )

    return exposure, sizing_frame


# ============================================================
# BACKTEST CORE
# ============================================================

def _apply_risk_specification_layer(
    df: pd.DataFrame,
    signal: pd.Series,
    cfg: BacktestConfig,
    exposure_abs_hint: pd.Series | None = None,
) -> tuple[pd.Series, pd.DataFrame, pd.Series, pd.Series, pd.Series]:
    """
    Risk Specification Layer V2 / OHLC Execution Upgrade.

    Objectif :
    - appliquer un overlay de risque au signal moteur déjà décalé t+1 ;
    - utiliser open/high/low/close lorsque disponible ;
    - exécuter stop / take profit / trailing au seuil, pas au close favorable ;
    - respecter les gaps adverses à l'open ;
    - injecter un P&L de sortie réaliste dans le moteur via risk_return_override ;
    - éviter l'exécution de code utilisateur.

    Hypothèses V2 :
    - stop-first en cas de stop et take profit touchés dans la même barre ;
    - fill au seuil pour stop/take/trailing ;
    - si gap adverse à l'open contre un stop/trailing, fill à l'open ;
    - pas encore de simulation carnet d'ordre / bid-ask / halt broker.
    """
    base = pd.to_numeric(signal, errors="coerce").fillna(0.0).clip(-1.0, 1.0)
    adjusted = pd.Series(0.0, index=base.index)
    risk_reason = pd.Series("", index=base.index, dtype=object)
    risk_return_override = pd.Series(np.nan, index=base.index, dtype=float)
    risk_exit_price = pd.Series(np.nan, index=base.index, dtype=float)

    if not getattr(cfg, "risk_layer_enabled", False):
        return base, pd.DataFrame(), risk_reason, risk_return_override, risk_exit_price

    close = pd.to_numeric(df["close"].reindex(base.index), errors="coerce").ffill()

    use_ohlc = bool(getattr(cfg, "risk_use_ohlc_execution", True))
    respect_open_gaps = bool(getattr(cfg, "risk_respect_open_gaps", True))

    if use_ohlc:
        open_ = pd.to_numeric(df.get("open", close).reindex(base.index), errors="coerce").fillna(close)
        high = pd.to_numeric(df.get("high", close).reindex(base.index), errors="coerce").fillna(close)
        low = pd.to_numeric(df.get("low", close).reindex(base.index), errors="coerce").fillna(close)
    else:
        open_ = close.copy()
        high = close.copy()
        low = close.copy()

    stop_loss = max(float(getattr(cfg, "risk_stop_loss_pct", 8.0)), 0.0) / 100.0
    take_profit = max(float(getattr(cfg, "risk_take_profit_pct", 20.0)), 0.0) / 100.0
    trailing_stop = max(float(getattr(cfg, "risk_trailing_stop_pct", 10.0)), 0.0) / 100.0
    max_holding = max(int(getattr(cfg, "risk_max_holding_bars", 30)), 1)
    cooldown_setting = max(int(getattr(cfg, "risk_cooldown_bars", 0)), 0)

    use_stop = bool(getattr(cfg, "risk_use_stop_loss", True)) and stop_loss > 0
    use_take = bool(getattr(cfg, "risk_use_take_profit", False)) and take_profit > 0
    use_trailing = bool(getattr(cfg, "risk_use_trailing_stop", False)) and trailing_stop > 0
    use_max_holding = bool(getattr(cfg, "risk_use_max_holding", False)) and max_holding > 0

    position_scale = max(min(float(getattr(cfg, "position_pct", 100.0)) / 100.0, 1.0), 0.0)
    if exposure_abs_hint is None:
        exposure_abs_hint = pd.Series(position_scale, index=base.index)
    else:
        exposure_abs_hint = (
            pd.to_numeric(exposure_abs_hint.reindex(base.index), errors="coerce")
            .fillna(position_scale)
            .clip(lower=0.0, upper=1.0)
        )

    def _sign(x: Any) -> float:
        val = _safe_float(x, 0.0)
        if val > 0:
            return 1.0
        if val < 0:
            return -1.0
        return 0.0

    def _price_from_trade_return(entry: float, ret: float, side: float) -> float:
        try:
            entry = float(entry)
            ret = float(ret)
            if entry <= 0:
                return np.nan

            if side > 0:
                return entry * (1.0 + ret)

            denom = 1.0 + ret
            if denom <= 1e-9:
                return np.nan

            return entry / denom
        except Exception:
            return np.nan

    def _bar_return_from_prev_close(prev_close: float, fill_price: float, side: float) -> float:
        try:
            prev_close = float(prev_close)
            fill_price = float(fill_price)

            if prev_close <= 0 or fill_price <= 0:
                return 0.0

            if side > 0:
                return fill_price / prev_close - 1.0

            return prev_close / fill_price - 1.0
        except Exception:
            return 0.0

    def _trade_returns_for_bar(entry: float, side: float, i: int) -> dict[str, float]:
        o = _safe_float(open_.iloc[i], np.nan)
        h = _safe_float(high.iloc[i], np.nan)
        l = _safe_float(low.iloc[i], np.nan)
        c = _safe_float(close.iloc[i], np.nan)

        if pd.isna(entry) or entry <= 0 or pd.isna(c) or c <= 0:
            return {
                "open": 0.0,
                "best": 0.0,
                "worst": 0.0,
                "close": 0.0,
                "open_price": c,
                "high_price": c,
                "low_price": c,
                "close_price": c,
            }

        if side > 0:
            return {
                "open": o / entry - 1.0,
                "best": h / entry - 1.0,
                "worst": l / entry - 1.0,
                "close": c / entry - 1.0,
                "open_price": o,
                "high_price": h,
                "low_price": l,
                "close_price": c,
            }

        return {
            "open": entry / o - 1.0,
            "best": entry / l - 1.0,
            "worst": entry / h - 1.0,
            "close": entry / c - 1.0,
            "open_price": o,
            "high_price": h,
            "low_price": l,
            "close_price": c,
        }

    in_trade = False
    side = 0.0
    entry_price = np.nan
    entry_date = None
    bars_held = 0
    best_return = 0.0

    lockout_side = 0.0
    cooldown_left = 0

    events: list[dict[str, Any]] = []

    for i, dt in enumerate(base.index):
        current_close = _safe_float(close.iloc[i], np.nan)
        prev_close = _safe_float(close.iloc[i - 1], current_close) if i > 0 else current_close

        desired = _safe_float(base.loc[dt], 0.0)
        desired_side = _sign(desired)

        if pd.isna(current_close) or current_close <= 0:
            adjusted.iloc[i] = 0.0
            continue

        # Lockout après risk exit : empêche la réentrée immédiate dans la même direction.
        if lockout_side != 0.0:
            if desired_side == 0.0:
                adjusted.iloc[i] = 0.0
                lockout_side = 0.0
                cooldown_left = 0
                continue

            if desired_side == lockout_side:
                if cooldown_setting > 0:
                    if cooldown_left > 0:
                        adjusted.iloc[i] = 0.0
                        cooldown_left -= 1
                        continue
                    lockout_side = 0.0
                else:
                    adjusted.iloc[i] = 0.0
                    continue
            else:
                lockout_side = 0.0
                cooldown_left = 0

        # Ouverture d'un trade si signal actif.
        if not in_trade:
            if desired_side != 0.0:
                in_trade = True
                side = desired_side
                entry_price = prev_close if pd.notna(prev_close) and prev_close > 0 else current_close
                entry_date = dt
                bars_held = 0
                best_return = 0.0
            else:
                adjusted.iloc[i] = 0.0
                continue

        # Sortie normale par signal flat.
        elif desired_side == 0.0:
            in_trade = False
            side = 0.0
            entry_price = np.nan
            entry_date = None
            bars_held = 0
            best_return = 0.0
            adjusted.iloc[i] = 0.0
            continue

        # Flip de signal : on repart sur un nouveau trade dans l'autre sens.
        elif desired_side != side:
            in_trade = True
            side = desired_side
            entry_price = prev_close if pd.notna(prev_close) and prev_close > 0 else current_close
            entry_date = dt
            bars_held = 0
            best_return = 0.0

        bars_held += 1

        path = _trade_returns_for_bar(entry_price, side, i)

        open_ret = _safe_float(path.get("open"), 0.0)
        best_bar_ret = _safe_float(path.get("best"), 0.0)
        worst_bar_ret = _safe_float(path.get("worst"), 0.0)
        close_ret = _safe_float(path.get("close"), 0.0)

        best_return = max(best_return, best_bar_ret)

        trigger = ""
        trigger_type = ""
        fill_trade_return = np.nan
        fill_price = np.nan
        execution_assumption = "OHLC threshold fill" if use_ohlc else "Close-only fallback"

        # Priorité conservatrice : stop first.
        if use_stop:
            stop_level = -stop_loss

            if respect_open_gaps and open_ret <= stop_level:
                trigger = f"Risk stop loss hit ({_format_pct(stop_level)})"
                trigger_type = "Stop loss"
                fill_trade_return = open_ret
                fill_price = _safe_float(path.get("open_price"), current_close)
                execution_assumption += " · adverse open gap respected"

            elif worst_bar_ret <= stop_level:
                trigger = f"Risk stop loss hit ({_format_pct(stop_level)})"
                trigger_type = "Stop loss"
                fill_trade_return = stop_level
                fill_price = _price_from_trade_return(entry_price, fill_trade_return, side)
                execution_assumption += " · threshold-capped"

        if not trigger and use_take:
            take_level = take_profit

            if best_bar_ret >= take_level:
                trigger = f"Risk take profit hit ({_format_pct(take_level)})"
                trigger_type = "Take profit"
                fill_trade_return = take_level
                fill_price = _price_from_trade_return(entry_price, fill_trade_return, side)
                execution_assumption += " · threshold-capped"

        if not trigger and use_trailing and best_return > 0:
            trail_floor = best_return - trailing_stop

            if respect_open_gaps and open_ret <= trail_floor:
                trigger = f"Risk trailing stop hit ({_format_pct(trailing_stop)})"
                trigger_type = "Trailing stop"
                fill_trade_return = open_ret
                fill_price = _safe_float(path.get("open_price"), current_close)
                execution_assumption += " · trailing open gap respected"

            elif worst_bar_ret <= trail_floor:
                trigger = f"Risk trailing stop hit ({_format_pct(trailing_stop)})"
                trigger_type = "Trailing stop"
                fill_trade_return = trail_floor
                fill_price = _price_from_trade_return(entry_price, fill_trade_return, side)
                execution_assumption += " · threshold-capped"

        if not trigger and use_max_holding and bars_held >= max_holding:
            trigger = f"Risk max holding reached ({max_holding} bars)"
            trigger_type = "Max holding"
            fill_trade_return = close_ret
            fill_price = current_close
            execution_assumption = "Close fill at max holding"

        if trigger:
            if pd.isna(fill_price) or fill_price <= 0:
                fill_price = current_close

            bar_fill_return = _bar_return_from_prev_close(prev_close, fill_price, side)

            bar_position_scale = _safe_float(exposure_abs_hint.iloc[i], position_scale)
            bar_position_scale = max(0.0, min(1.0, bar_position_scale))

            risk_return_override.iloc[i] = bar_position_scale * bar_fill_return
            risk_exit_price.iloc[i] = fill_price
            risk_reason.iloc[i] = trigger + " · Risk Specification Layer V2"

            events.append(
                {
                    "Trigger Date": _format_dt(dt),
                    "Effective Exit": "Same bar",
                    "Side": "LONG" if side > 0 else "SHORT",
                    "Rule": trigger,
                    "Trigger Type": trigger_type,
                    "Entry Date": _format_dt(entry_date),
                    "Entry Price": entry_price,
                    "Prev Close": prev_close,
                    "Open": _safe_float(path.get("open_price"), np.nan),
                    "High": _safe_float(path.get("high_price"), np.nan),
                    "Low": _safe_float(path.get("low_price"), np.nan),
                    "Close": _safe_float(path.get("close_price"), np.nan),
                    "Fill Price": fill_price,
                    "Trigger Return": fill_trade_return,
                    "Bar Fill Return": bar_fill_return,
                    "Sizing Exposure": bar_position_scale,
                    "Position Scaled Return": bar_position_scale * bar_fill_return,
                    "Best Return": best_return,
                    "Worst Bar Return": worst_bar_ret,
                    "Bars Held": bars_held,
                    "Execution Assumption": execution_assumption,
                    "Priority": "Conservative stop-first",
                }
            )

            adjusted.iloc[i] = 0.0

            event_side = side

            in_trade = False
            side = 0.0
            entry_price = np.nan
            entry_date = None
            bars_held = 0
            best_return = 0.0

            lockout_side = event_side
            cooldown_left = cooldown_setting

            continue

        adjusted.iloc[i] = desired

    risk_events = pd.DataFrame(events)

    return (
        adjusted.fillna(0.0).clip(-1.0, 1.0),
        risk_events,
        risk_reason,
        risk_return_override,
        risk_exit_price,
    )

def _run_backtest(df: pd.DataFrame, cfg: BacktestConfig) -> dict[str, Any]:
    if df.empty or len(df) < 60:
        return {"error": "Données insuffisantes pour un backtest robuste."}

    close = df["close"]
    returns = close.pct_change().fillna(0.0)
    benchmark_returns, benchmark_label, benchmark_fallback = _load_benchmark_returns(df, cfg)

    base_signal = _build_signal(df, cfg)
    signal = base_signal.copy()
    risk_events = pd.DataFrame()
    risk_reason = pd.Series("", index=df.index, dtype=object)
    risk_return_override = pd.Series(np.nan, index=df.index, dtype=float)
    risk_exit_price = pd.Series(np.nan, index=df.index, dtype=float)

    # Sizing pré-risk : sert à donner au Risk Layer V2 la taille réelle du trade
    # au moment d'un stop/take/trailing same-bar.
    pre_risk_exposure, pre_risk_sizing_frame = _apply_position_sizing_layer(df, base_signal, cfg)
    pre_risk_abs_hint = pre_risk_exposure.abs()

    if getattr(cfg, "risk_layer_enabled", False):
        (
            signal,
            risk_events,
            risk_reason,
            risk_return_override,
            risk_exit_price,
        ) = _apply_risk_specification_layer(
            df,
            base_signal,
            cfg,
            exposure_abs_hint=pre_risk_abs_hint,
        )

    exposure, sizing_frame = _apply_position_sizing_layer(df, signal, cfg)

    gross = exposure * returns

    if isinstance(risk_return_override, pd.Series) and risk_return_override.notna().any():
        override = pd.to_numeric(
            risk_return_override.reindex(gross.index),
            errors="coerce",
        )
        gross = gross.where(override.isna(), override)

    turnover = exposure.diff().abs().fillna(exposure.abs())
    cost_rate = (cfg.fee_bps + cfg.slippage_bps) / 10000.0
    costs = turnover * cost_rate

    net = gross - costs

    equity = cfg.capital * (1 + net).cumprod()
    benchmark = cfg.capital * (1 + benchmark_returns).cumprod()

    bt = pd.DataFrame(
        {
            "close": close,
            "open": df["open"].reindex(close.index) if "open" in df.columns else close,
            "high": df["high"].reindex(close.index) if "high" in df.columns else close,
            "low": df["low"].reindex(close.index) if "low" in df.columns else close,
            "volume": df["volume"].reindex(close.index) if "volume" in df.columns else np.nan,
            "base_signal": base_signal,
            "signal": signal,
            "risk_exit_reason": risk_reason,
            "risk_exit_price": risk_exit_price,
            "target_abs_exposure": sizing_frame.get("target_abs_exposure", pd.Series(np.nan, index=close.index)),
            "sizing_multiplier": sizing_frame.get("sizing_multiplier", pd.Series(np.nan, index=close.index)),
            "realized_vol_ann": sizing_frame.get("realized_vol_ann", pd.Series(np.nan, index=close.index)),
            "vol_target_ann": sizing_frame.get("vol_target_ann", pd.Series(np.nan, index=close.index)),
            "risk_budget_cap": sizing_frame.get("risk_budget_cap", pd.Series(np.nan, index=close.index)),
            "sizing_drawdown_proxy": sizing_frame.get("sizing_drawdown_proxy", pd.Series(np.nan, index=close.index)),
            "sizing_drawdown_cut_active": sizing_frame.get("sizing_drawdown_cut_active", pd.Series(0.0, index=close.index)),
            "exposure": exposure,
            "returns": returns,
            "benchmark_return": benchmark_returns,
            "strategy_return": net,
            "gross_return": gross,
            "costs": costs,
            "turnover": turnover,
            "equity": equity,
            "benchmark": benchmark,
        }
    )

    bt = bt.replace([np.inf, -np.inf], np.nan)

    required_cols = [
        "close",
        "open",
        "high",
        "low",
        "signal",
        "exposure",
        "returns",
        "benchmark_return",
        "strategy_return",
        "gross_return",
        "costs",
        "turnover",
        "equity",
        "benchmark",
    ]

    bt = bt.dropna(subset=[c for c in required_cols if c in bt.columns])

    if "risk_exit_reason" in bt.columns:
        bt["risk_exit_reason"] = bt["risk_exit_reason"].fillna("")

    if "risk_exit_price" in bt.columns:
        bt["risk_exit_price"] = pd.to_numeric(bt["risk_exit_price"], errors="coerce")

    if bt.empty:
        return {"error": "Backtest vide après nettoyage des données."}

    metrics = _compute_metrics(bt, cfg)
    metrics["Benchmark Label"] = benchmark_label
    metrics["Benchmark Fallback"] = benchmark_fallback
    metrics["Risk Layer Enabled"] = bool(getattr(cfg, "risk_layer_enabled", False))
    metrics["Risk Exits"] = int(len(risk_events)) if isinstance(risk_events, pd.DataFrame) else 0
    metrics["Risk Execution Model"] = (
        "OHLC threshold fill"
        if bool(getattr(cfg, "risk_use_ohlc_execution", True))
        else "Close-only fallback"
    )

    metrics["Sizing Mode"] = str(getattr(cfg, "sizing_mode", "Fixed Exposure"))
    metrics["Average Abs Exposure"] = float(bt["exposure"].abs().mean()) if "exposure" in bt.columns else np.nan
    metrics["Max Abs Exposure"] = float(bt["exposure"].abs().max()) if "exposure" in bt.columns else np.nan

    if "sizing_multiplier" in bt.columns:
        metrics["Average Sizing Multiplier"] = float(
            pd.to_numeric(bt["sizing_multiplier"], errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .dropna()
            .mean()
        )

    if "realized_vol_ann" in bt.columns:
        metrics["Average Input Vol Ann."] = float(
            pd.to_numeric(bt["realized_vol_ann"], errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .dropna()
            .mean()
        )

    if "sizing_drawdown_cut_active" in bt.columns:
        metrics["Drawdown Cut Bars"] = int(
            pd.to_numeric(bt["sizing_drawdown_cut_active"], errors="coerce")
            .fillna(0.0)
            .sum()
        )

    if "risk_budget_cap" in bt.columns:
        rb = pd.to_numeric(bt["risk_budget_cap"], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
        metrics["Risk Budget Cap"] = float(rb.iloc[-1]) if not rb.empty else np.nan

    metrics["Margin Stress Enabled"] = bool(getattr(cfg, "margin_stress_enabled", False))
    metrics["Margin Stress Leverage"] = float(getattr(cfg, "margin_leverage_multiple", 1.0))
    metrics["Margin Financing Rate"] = float(getattr(cfg, "margin_financing_rate_pct", 0.0)) / 100.0
    metrics["Margin Maintenance"] = float(getattr(cfg, "margin_maintenance_margin_pct", 25.0)) / 100.0

    brt_v35b_pack = {}
    if str(getattr(cfg, "strategy", "")) == "Benchmark-Relative Trend":
        brt_v35b_pack = _benchmark_relative_trend_diagnostics_v35b_pack(df, cfg)
        if isinstance(brt_v35b_pack, dict):
            metrics["BRT V3.5b Level"] = str(brt_v35b_pack.get("level", "N/A"))
            metrics["BRT V3.5b Score"] = _safe_float(brt_v35b_pack.get("score"), np.nan)
            metrics["BRT V3.5b Engine Active Bars"] = int(brt_v35b_pack.get("engine_active_bars", 0) or 0)
            metrics["BRT V3.5b Eligible Bars"] = int(brt_v35b_pack.get("eligible_bars", 0) or 0)

    trades = _extract_trades(bt, cfg)

    return {
        "data": bt,
        "metrics": metrics,
        "trades": trades,
        "signal": signal,
        "base_signal": base_signal,
        "risk_events": risk_events,
        "brt_v35b": brt_v35b_pack,
    }


def _compute_metrics(bt: pd.DataFrame, cfg: BacktestConfig | None = None) -> dict[str, Any]:
    if bt.empty:
        return {}

    daily = bt["strategy_return"].dropna()
    bench_daily = bt["benchmark_return"].dropna() if "benchmark_return" in bt.columns else bt["returns"].dropna()

    if daily.empty:
        return {}

    years = max(len(daily) / 252.0, 1 / 252)

    total_return = bt["equity"].iloc[-1] / bt["equity"].iloc[0] - 1
    benchmark_return = bt["benchmark"].iloc[-1] / bt["benchmark"].iloc[0] - 1

    cagr = (1 + total_return) ** (1 / years) - 1 if total_return > -1 else -1
    bench_cagr = (1 + benchmark_return) ** (1 / years) - 1 if benchmark_return > -1 else -1

    vol = daily.std() * np.sqrt(252)
    sharpe = daily.mean() / daily.std() * np.sqrt(252) if daily.std() > 0 else np.nan

    downside = daily[daily < 0]
    sortino = daily.mean() / downside.std() * np.sqrt(252) if len(downside) > 1 and downside.std() > 0 else np.nan

    dd = bt["equity"] / bt["equity"].cummax() - 1
    max_dd = dd.min()

    calmar = cagr / abs(max_dd) if max_dd < 0 else np.nan

    win_rate = (daily > 0).mean()
    avg_win = daily[daily > 0].mean() if (daily > 0).any() else 0.0
    avg_loss = daily[daily < 0].mean() if (daily < 0).any() else 0.0

    loss_sum = daily[daily < 0].sum()
    profit_factor = daily[daily > 0].sum() / abs(loss_sum) if loss_sum < 0 else np.nan

    active_changes = bt["exposure"].diff().abs().fillna(bt["exposure"].abs())
    trades_count = int((active_changes > 0).sum())

    bench_sharpe = bench_daily.mean() / bench_daily.std() * np.sqrt(252) if bench_daily.std() > 0 else np.nan

    prev_equity = bt["equity"].shift(1).fillna(bt["equity"].iloc[0])
    cost_dollars = (bt["costs"].abs() * prev_equity).sum()

    var_95 = daily.quantile(0.05)
    cvar_95 = daily[daily <= var_95].mean() if (daily <= var_95).any() else np.nan

    return {
        "Total Return": total_return,
        "CAGR": cagr,
        "Benchmark Return": benchmark_return,
        "Benchmark CAGR": bench_cagr,
        "Benchmark Sharpe": bench_sharpe,
        "Relative Alpha": total_return - benchmark_return,
        "CAGR Gap": cagr - bench_cagr,
        "Volatility": vol,
        "Sharpe": sharpe,
        "Sortino": sortino,
        "Max Drawdown": max_dd,
        "Calmar": calmar,
        "Win Rate": win_rate,
        "Average Win": avg_win,
        "Average Loss": avg_loss,
        "Profit Factor": profit_factor,
        "Expectancy / Day": daily.mean(),
        "VaR 95": var_95,
        "CVaR 95": cvar_95,
        "Exposure": (bt["exposure"].abs() > 0).mean(),
        "Turnover": bt["turnover"].sum(),
        "Trades": trades_count,
        "Final Equity": bt["equity"].iloc[-1],
        "Cost Drag": bt["costs"].sum(),
        "Cost Paid $": cost_dollars,
    }


def _trade_excursion(bt: pd.DataFrame, start: Any, end: Any, entry_price: float, side: float) -> tuple[float, float]:
    try:
        segment = bt.loc[start:end]
        if segment.empty:
            return np.nan, np.nan
        if side >= 0:
            path = segment["close"] / entry_price - 1.0
        else:
            path = entry_price / segment["close"] - 1.0
        return float(path.max()), float(path.min())
    except Exception:
        return np.nan, np.nan


def _extract_trades(bt: pd.DataFrame, cfg: BacktestConfig) -> pd.DataFrame:
    if bt.empty:
        return pd.DataFrame()

    exposure = bt["exposure"].fillna(0)
    changes = exposure.diff().fillna(exposure)
    points = changes[changes != 0]

    rows = []
    open_trade = None
    idx_is_dt = _is_datetime_like_index(bt.index)

    for bar_no, (dt, _) in enumerate(points.items()):
        current_exp = exposure.loc[dt]

        if open_trade is not None and (current_exp == 0 or np.sign(current_exp) != np.sign(open_trade["side"])):
            exit_price = bt.loc[dt, "close"]

            try:
                if "risk_exit_price" in bt.columns:
                    risk_px = _safe_float(bt.loc[dt, "risk_exit_price"], np.nan)
                    if pd.notna(risk_px) and risk_px > 0:
                        exit_price = risk_px
            except Exception:
                pass

            ret = bt.loc[dt, "equity"] / open_trade["entry_equity"] - 1
            mfe, mae = _trade_excursion(bt, open_trade["entry_date"], dt, open_trade["entry_price"], open_trade["side"])

            risk_exit_reason = ""
            try:
                if "risk_exit_reason" in bt.columns:
                    risk_exit_reason = str(bt.loc[dt, "risk_exit_reason"] or "").strip()
            except Exception:
                risk_exit_reason = ""

            exit_reason = risk_exit_reason if risk_exit_reason else _exit_reason(cfg.strategy, final_exit=False)

            rows.append(
                {
                    "Entry Date": _format_dt(open_trade["entry_date"]) if idx_is_dt else str(open_trade["entry_date"]),
                    "Exit Date": _format_dt(dt) if idx_is_dt else str(dt),
                    "Entry Bar": open_trade["entry_bar"],
                    "Exit Bar": int(bt.index.get_loc(dt)) if dt in bt.index else bar_no,
                    "Side": "LONG" if open_trade["side"] > 0 else "SHORT",
                    "Entry Price": open_trade["entry_price"],
                    "Exit Price": exit_price,
                    "Return": ret,
                    "MFE": mfe,
                    "MAE": mae,
                    "Bars": len(bt.loc[open_trade["entry_date"]:dt]),
                    "Entry Reason": open_trade["entry_reason"],
                    "Exit Reason": exit_reason,
                }
            )
            open_trade = None

        if current_exp != 0:
            open_trade = {
                "entry_date": dt,
                "entry_bar": int(bt.index.get_loc(dt)) if dt in bt.index else bar_no,
                "entry_price": bt.loc[dt, "close"],
                "entry_equity": bt.loc[dt, "equity"],
                "side": current_exp,
                "entry_reason": _entry_reason(cfg.strategy, current_exp),
            }

    if open_trade is not None:
        dt = bt.index[-1]
        mfe, mae = _trade_excursion(bt, open_trade["entry_date"], dt, open_trade["entry_price"], open_trade["side"])
        rows.append(
            {
                "Entry Date": _format_dt(open_trade["entry_date"]) if idx_is_dt else str(open_trade["entry_date"]),
                "Exit Date": _format_dt(dt) if idx_is_dt else str(dt),
                "Entry Bar": open_trade["entry_bar"],
                "Exit Bar": len(bt) - 1,
                "Side": "LONG" if open_trade["side"] > 0 else "SHORT",
                "Entry Price": open_trade["entry_price"],
                "Exit Price": bt.loc[dt, "close"],
                "Return": bt.loc[dt, "equity"] / open_trade["entry_equity"] - 1,
                "MFE": mfe,
                "MAE": mae,
                "Bars": len(bt.loc[open_trade["entry_date"]:dt]),
                "Entry Reason": open_trade["entry_reason"],
                "Exit Reason": _exit_reason(cfg.strategy, final_exit=True),
            }
        )

    return pd.DataFrame(rows)


def _worst_trades_contribution(trades: pd.DataFrame, metrics: dict[str, Any]) -> pd.DataFrame:
    if trades is None or trades.empty or "Return" not in trades.columns:
        return pd.DataFrame()

    df = trades.copy()
    df["Return_num"] = pd.to_numeric(df["Return"], errors="coerce")
    losses = df[df["Return_num"] < 0].copy()

    if losses.empty:
        return pd.DataFrame()

    total_loss = abs(losses["Return_num"].sum())
    if total_loss <= 0:
        return pd.DataFrame()

    losses = losses.sort_values("Return_num", ascending=True)
    losses["Loss Contribution"] = losses["Return_num"].abs() / total_loss
    losses["Cumulative Loss Contribution"] = losses["Loss Contribution"].cumsum()

    out = losses.head(10).copy()

    keep_cols = [
        "Entry Date", "Exit Date", "Side", "Entry Price", "Exit Price",
        "Return", "MFE", "MAE", "Bars",
        "Loss Contribution", "Cumulative Loss Contribution",
        "Entry Reason", "Exit Reason",
    ]

    out = out[[c for c in keep_cols if c in out.columns]]

    for col in ["Entry Price", "Exit Price"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_num(x))

    for col in ["Return", "MFE", "MAE", "Loss Contribution", "Cumulative Loss Contribution"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_pct(x))

    return out


def _trade_quality_diagnostics(trades: pd.DataFrame) -> tuple[pd.DataFrame, pd.DataFrame]:
    """
    Diagnostic trade-level :
    - corrige la confusion daily win rate vs trade win rate
    - mesure capture du MFE, giveback, loss vs MAE
    - identifie les trades où le problème vient de l'entrée, de la sortie ou du giveback
    """
    if trades is None or trades.empty:
        return pd.DataFrame(), pd.DataFrame()

    df = trades.copy()

    for col in ["Return", "MFE", "MAE", "Bars"]:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors="coerce")

    if "Return" not in df.columns:
        return pd.DataFrame(), pd.DataFrame()

    df = df.replace([np.inf, -np.inf], np.nan).dropna(subset=["Return"])

    if df.empty:
        return pd.DataFrame(), pd.DataFrame()

    winners = df[df["Return"] > 0].copy()
    losers = df[df["Return"] < 0].copy()

    trade_count = len(df)
    win_rate = len(winners) / trade_count if trade_count > 0 else np.nan

    avg_trade = float(df["Return"].mean()) if trade_count > 0 else np.nan
    avg_win = float(winners["Return"].mean()) if not winners.empty else np.nan
    avg_loss = float(losers["Return"].mean()) if not losers.empty else np.nan

    gross_profit = float(winners["Return"].sum()) if not winners.empty else 0.0
    gross_loss = abs(float(losers["Return"].sum())) if not losers.empty else 0.0

    profit_factor = gross_profit / gross_loss if gross_loss > 0 else np.nan
    payoff_ratio = avg_win / abs(avg_loss) if pd.notna(avg_win) and pd.notna(avg_loss) and avg_loss < 0 else np.nan

    avg_mfe = float(df["MFE"].mean()) if "MFE" in df.columns else np.nan
    avg_mae = float(df["MAE"].mean()) if "MAE" in df.columns else np.nan

    winner_mfe_capture = pd.Series(dtype=float)
    peak_to_exit_decay = pd.Series(dtype=float)
    loser_loss_price_mae = pd.Series(dtype=float)

    if "MFE" in df.columns:
        valid_winner_mfe = (df["Return"] > 0) & (df["MFE"].abs() > 1e-12)
        winner_mfe_capture = df.loc[valid_winner_mfe, "Return"] / df.loc[valid_winner_mfe, "MFE"]

        valid_mfe = df["MFE"].abs() > 1e-12
        peak_to_exit_decay = (df.loc[valid_mfe, "MFE"] - df.loc[valid_mfe, "Return"]).clip(lower=0.0)

    if "MAE" in df.columns and not losers.empty:
        valid_loser_mae = (losers["Return"] < 0) & (losers["MAE"].abs() > 1e-12)
        loser_loss_price_mae = losers.loc[valid_loser_mae, "Return"].abs() / losers.loc[valid_loser_mae, "MAE"].abs()

    open_marked = 0
    if "Exit Reason" in df.columns:
        open_marked = int(df["Exit Reason"].astype(str).str.contains("Open trade marked", case=False, na=False).sum())

    stats = pd.DataFrame(
        [
            ["Trade count", str(trade_count), "Nombre de trades détectés."],
            ["Trade win rate", _format_pct(win_rate), "Part des trades clôturés positifs."],
            ["Average trade return", _format_pct(avg_trade), "Rendement moyen par trade."],
            ["Average winning trade", _format_pct(avg_win), "Gain moyen des trades gagnants."],
            ["Average losing trade", _format_pct(avg_loss), "Perte moyenne des trades perdants."],
            ["Payoff ratio", _format_num(payoff_ratio), "Gain moyen / perte moyenne absolue."],
            ["Trade profit factor", _format_num(profit_factor), "Somme gains trades / somme pertes trades."],
            ["Avg MFE", _format_pct(avg_mfe), "Excursion favorable moyenne par trade."],
            ["Avg MAE", _format_pct(avg_mae), "Excursion défavorable moyenne par trade."],
            ["Winner MFE Capture", _format_pct(winner_mfe_capture.dropna().mean()), "Capture moyenne du MFE uniquement sur les trades gagnants."],
            ["Avg Peak-to-exit Decay", _format_pct(peak_to_exit_decay.dropna().mean()), "Performance rendue entre le meilleur point du trade et la sortie."], 
            ["Loser Loss / Price MAE", _format_pct(loser_loss_price_mae.dropna().mean()), "Perte réalisée rapportée à la pire excursion défavorable, uniquement sur les trades perdants."],
            ["Median holding bars", _format_num(df["Bars"].median(), 0) if "Bars" in df.columns else "N/A", "Durée médiane des trades en barres."],
            ["Open trades marked", str(open_marked), "Trades encore ouverts marqués au dernier close disponible."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    quality = df.copy()

    if "MFE" in quality.columns:
        # Capture du potentiel favorable uniquement sur les trades gagnants.
        # Sur un trade perdant, Return / MFE donne une lecture négative peu exploitable.
        quality["Winner MFE Capture"] = np.where(
            (quality["Return"] > 0) & (quality["MFE"].abs() > 1e-12),
            quality["Return"] / quality["MFE"],
            np.nan,
        )

        # Perte de performance entre le meilleur point du trade et la sortie.
        # Exemple : MFE +11%, Return -6% => decay ≈ 17 points.
        quality["Peak-to-exit Decay"] = np.where(
            quality["MFE"].abs() > 1e-12,
            (quality["MFE"] - quality["Return"]).clip(lower=0.0),
            np.nan,
        )
    else:
        quality["Winner MFE Capture"] = np.nan
        quality["Peak-to-exit Decay"] = np.nan

    if "MAE" in quality.columns:
        # Pour les trades perdants uniquement : perte réalisée vs pire excursion défavorable.
        quality["Loser Loss / Price MAE"] = np.where(
            (quality["Return"] < 0) & (quality["MAE"].abs() > 1e-12),
            quality["Return"].abs() / quality["MAE"].abs(),
            np.nan,
        )
    else:
        quality["Loser Loss / Price MAE"] = np.nan
    def diagnose_trade(row: pd.Series) -> str:
        ret = _safe_float(row.get("Return"), 0.0)
        mfe = _safe_float(row.get("MFE"), 0.0)
        mae = _safe_float(row.get("MAE"), 0.0)
        capture = _safe_float(row.get("Winner MFE Capture"), np.nan)
        give = _safe_float(row.get("Peak-to-exit Decay"), 0.0)
        loss_mae = _safe_float(row.get("Loser Loss / Price MAE"), np.nan)

        if ret < 0 and mfe > 0.05 and give > 0.08:
            return "Winner turned loser / exit problem"
        if ret < 0 and pd.notna(loss_mae) and loss_mae >= 0.85:
            return "Loss close to worst excursion"
        if ret < 0 and mfe <= 0.02:
            return "Bad entry / no favorable excursion"
        if ret > 0 and pd.notna(capture) and capture >= 0.70:
            return "Good MFE capture"
        if ret > 0 and pd.notna(capture) and capture < 0.35:
            return "Low capture despite profit"
        return "Neutral"

    quality["Diagnosis"] = quality.apply(diagnose_trade, axis=1)

    keep_cols = [
        "Entry Date", "Exit Date", "Side",
        "Return", "MFE", "MAE",
        "Winner MFE Capture", "Peak-to-exit Decay", "Loser Loss / Price MAE",
        "Bars", "Diagnosis",
        "Entry Reason", "Exit Reason",
    ]

    quality = quality[[c for c in keep_cols if c in quality.columns]]

    for col in ["Return", "MFE", "MAE", "Winner MFE Capture", "Peak-to-exit Decay", "Loser Loss / Price MAE"]:
        if col in quality.columns:
            quality[col] = quality[col].map(lambda x: _format_pct(x))

    return stats, quality


def _profit_factor_from_returns(returns: pd.Series) -> float:
    """Profit factor sur une série de rendements trade-level."""
    try:
        r = pd.to_numeric(returns, errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
        if r.empty:
            return np.nan

        gross_profit = float(r[r > 0].sum())
        gross_loss = abs(float(r[r < 0].sum()))

        if gross_loss <= 1e-12:
            return np.nan

        return gross_profit / gross_loss
    except Exception:
        return np.nan


def _trade_close_path(bt: pd.DataFrame, trade: pd.Series) -> tuple[pd.Series, pd.Series]:
    """
    Retourne le chemin de performance close-to-close d'un trade.
    Lecture uniquement : ne modifie pas le backtest.
    """
    try:
        if bt is None or bt.empty or trade is None:
            return pd.Series(dtype=float), pd.Series(dtype=float)

        entry_bar = int(_safe_float(trade.get("Entry Bar"), np.nan))
        exit_bar = int(_safe_float(trade.get("Exit Bar"), np.nan))

        if pd.isna(entry_bar) or pd.isna(exit_bar):
            return pd.Series(dtype=float), pd.Series(dtype=float)

        entry_bar = max(0, min(entry_bar, len(bt) - 1))
        exit_bar = max(entry_bar, min(exit_bar, len(bt) - 1))

        segment = bt.iloc[entry_bar:exit_bar + 1].copy()

        if segment.empty or "close" not in segment.columns:
            return pd.Series(dtype=float), pd.Series(dtype=float)

        entry_price = _safe_float(trade.get("Entry Price"), np.nan)

        if pd.isna(entry_price) or entry_price <= 0:
            entry_price = _safe_float(segment["close"].iloc[0], np.nan)

        if pd.isna(entry_price) or entry_price <= 0:
            return pd.Series(dtype=float), pd.Series(dtype=float)

        side_txt = str(trade.get("Side", "LONG")).upper().strip()
        is_short = side_txt == "SHORT"

        close = pd.to_numeric(segment["close"], errors="coerce").replace([np.inf, -np.inf], np.nan).ffill()

        if is_short:
            path = entry_price / close - 1.0
        else:
            path = close / entry_price - 1.0

        path = path.replace([np.inf, -np.inf], np.nan).fillna(0.0)

        return path, close

    except Exception:
        return pd.Series(dtype=float), pd.Series(dtype=float)


def _trade_ohlc_path(bt: pd.DataFrame, trade: pd.Series) -> tuple[pd.DataFrame, bool]:
    """
    Chemin OHLC d'un trade en espace rendement.

    Colonnes retournées :
    - close_return : rendement au close.
    - open_return  : rendement à l'open.
    - best_return  : meilleur rendement intrabar estimé via high/low.
    - worst_return : pire rendement intrabar estimé via high/low.

    Pour un short, best_return utilise le low et worst_return utilise le high.
    Lecture uniquement : ne modifie ni le moteur, ni les trades source.
    """
    try:
        if bt is None or bt.empty or trade is None:
            return pd.DataFrame(), False

        entry_bar = int(_safe_float(trade.get("Entry Bar"), np.nan))
        exit_bar = int(_safe_float(trade.get("Exit Bar"), np.nan))

        if pd.isna(entry_bar) or pd.isna(exit_bar):
            return pd.DataFrame(), False

        entry_bar = max(0, min(entry_bar, len(bt) - 1))
        exit_bar = max(entry_bar, min(exit_bar, len(bt) - 1))

        segment = bt.iloc[entry_bar:exit_bar + 1].copy()
        if segment.empty or "close" not in segment.columns:
            return pd.DataFrame(), False

        close = pd.to_numeric(segment["close"], errors="coerce").replace([np.inf, -np.inf], np.nan).ffill()

        has_ohlc = all(c in segment.columns for c in ["open", "high", "low"])
        if has_ohlc:
            open_ = pd.to_numeric(segment["open"], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(close)
            high = pd.to_numeric(segment["high"], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(close)
            low = pd.to_numeric(segment["low"], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(close)
        else:
            open_ = close.copy()
            high = close.copy()
            low = close.copy()

        entry_price = _safe_float(trade.get("Entry Price"), np.nan)
        if pd.isna(entry_price) or entry_price <= 0:
            entry_price = _safe_float(close.iloc[0], np.nan)
        if pd.isna(entry_price) or entry_price <= 0:
            return pd.DataFrame(), has_ohlc

        side_txt = str(trade.get("Side", "LONG")).upper().strip()
        is_short = side_txt == "SHORT"

        if is_short:
            out = pd.DataFrame(index=segment.index)
            out["close_return"] = entry_price / close - 1.0
            out["open_return"] = entry_price / open_ - 1.0
            out["best_return"] = entry_price / low - 1.0
            out["worst_return"] = entry_price / high - 1.0
        else:
            out = pd.DataFrame(index=segment.index)
            out["close_return"] = close / entry_price - 1.0
            out["open_return"] = open_ / entry_price - 1.0
            out["best_return"] = high / entry_price - 1.0
            out["worst_return"] = low / entry_price - 1.0

        out = out.replace([np.inf, -np.inf], np.nan).fillna(0.0)
        return out, has_ohlc

    except Exception:
        return pd.DataFrame(), False


def _exit_fill_return(
    threshold_return: float,
    open_return: float,
    is_stop: bool,
    adverse_open_gap_respected: bool = True,
) -> tuple[float, str]:
    """
    Retourne le rendement de sortie réaliste au seuil.

    - Take profit : capé au seuil cible pour éviter le biais optimiste.
    - Stop : capé au seuil, sauf gap d'ouverture adverse où l'open est plus mauvais.
    """
    try:
        threshold_return = float(threshold_return)
        open_return = float(open_return)
    except Exception:
        return threshold_return, "threshold-capped"

    if is_stop and adverse_open_gap_respected and open_return < threshold_return:
        return open_return, "threshold-capped + adverse open gap"

    return threshold_return, "threshold-capped"


def _exit_lab_baseline_return(
    bt: pd.DataFrame,
    trade: pd.Series,
    cfg: BacktestConfig,
) -> tuple[float, str]:
    """
    Baseline comparable pour l'Exit Efficiency Lab.

    Objectif :
    - reconstruire le rendement baseline sur le même chemin OHLC/close que les règles alternatives ;
    - inclure un coût round-trip simple ;
    - ne pas modifier le moteur, les trades, l'equity curve ou le verdict.
    """
    try:
        path, has_ohlc = _trade_ohlc_path(bt, trade)

        engine_return = _safe_float(trade.get("Return"), np.nan)

        if path is None or path.empty or "close_return" not in path.columns:
            return engine_return, "engine return fallback"

        round_trip_cost = 2.0 * (
            float(getattr(cfg, "fee_bps", 0.0)) + float(getattr(cfg, "slippage_bps", 0.0))
        ) / 10000.0

        baseline_return = float(path["close_return"].iloc[-1]) - round_trip_cost

        assumption = (
            "OHLC close baseline; costs included"
            if has_ohlc
            else "close-based baseline fallback; costs included"
        )

        return baseline_return, assumption

    except Exception:
        return _safe_float(trade.get("Return"), np.nan), "baseline fallback after error"


def _resolve_trade_entry_bar(bt: pd.DataFrame, trade: pd.Series) -> int | None:
    """
    Résout la barre d'entrée d'un trade.
    Priorité :
    1. Entry Bar si disponible.
    2. Entry Date si Entry Bar manque.
    """
    try:
        if bt is None or bt.empty or trade is None:
            return None

        entry_raw = trade.get("Entry Bar", np.nan)
        entry_bar_float = _safe_float(entry_raw, np.nan)

        if pd.notna(entry_bar_float):
            entry_bar = int(entry_bar_float)
            return max(0, min(entry_bar, len(bt) - 1))

        entry_date = trade.get("Entry Date", None)

        if entry_date is None:
            return None

        if not _is_datetime_like_index(bt.index):
            return None

        target = pd.to_datetime(entry_date, errors="coerce")

        if pd.isna(target):
            return None

        idx = pd.to_datetime(pd.Index(bt.index), errors="coerce")
        positions = np.where(idx >= target)[0]

        if len(positions) > 0:
            entry_bar = int(positions[0])
        else:
            entry_bar = len(bt) - 1

        return max(0, min(entry_bar, len(bt) - 1))

    except Exception:
        return None

def _entry_forward_path(
    bt: pd.DataFrame,
    trade: pd.Series,
    max_horizon: int = 20,
) -> tuple[pd.DataFrame, bool]:
    """
    Chemin forward après l'entrée du trade.

    Lecture uniquement :
    - ne modifie pas le moteur ;
    - ne modifie pas les trades ;
    - ne modifie pas l'equity curve ;
    - sert à diagnostiquer si l'entrée génère du follow-through après signal.

    Pour un long :
    - best_return = high / entry_price - 1
    - worst_return = low / entry_price - 1

    Pour un short :
    - best_return = entry_price / low - 1
    - worst_return = entry_price / high - 1
    """
    try:
        if bt is None or bt.empty or trade is None:
            return pd.DataFrame(), False

        entry_bar = _resolve_trade_entry_bar(bt, trade)

        if entry_bar is None:
            return pd.DataFrame(), False

        end_bar = min(entry_bar + int(max_horizon), len(bt) - 1)

        segment = bt.iloc[entry_bar:end_bar + 1].copy()

        if segment.empty or "close" not in segment.columns:
            return pd.DataFrame(), False

        close = (
            pd.to_numeric(segment["close"], errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .ffill()
        )

        has_ohlc = all(c in segment.columns for c in ["open", "high", "low"])

        if has_ohlc:
            high = (
                pd.to_numeric(segment["high"], errors="coerce")
                .replace([np.inf, -np.inf], np.nan)
                .fillna(close)
            )
            low = (
                pd.to_numeric(segment["low"], errors="coerce")
                .replace([np.inf, -np.inf], np.nan)
                .fillna(close)
            )
        else:
            high = close.copy()
            low = close.copy()

        entry_price = _safe_float(trade.get("Entry Price"), np.nan)

        if pd.isna(entry_price) or entry_price <= 0:
            entry_price = _safe_float(close.iloc[0], np.nan)

        if pd.isna(entry_price) or entry_price <= 0:
            return pd.DataFrame(), has_ohlc

        side_txt = str(trade.get("Side", "LONG")).upper().strip()
        is_short = side_txt == "SHORT"

        out = pd.DataFrame(index=segment.index)

        if is_short:
            out["close_return"] = entry_price / close - 1.0
            out["best_return"] = entry_price / low - 1.0
            out["worst_return"] = entry_price / high - 1.0
        else:
            out["close_return"] = close / entry_price - 1.0
            out["best_return"] = high / entry_price - 1.0
            out["worst_return"] = low / entry_price - 1.0

        out["bar_after_entry"] = np.arange(len(out))
        out = out.replace([np.inf, -np.inf], np.nan).fillna(0.0)

        return out, has_ohlc

    except Exception:
        return pd.DataFrame(), False


def _diagnose_entry_quality(row: pd.Series) -> str:
    """
    Diagnostic qualitatif par trade.
    Utilise les rendements forward post-entry, pas le rendement final du moteur.
    """
    fwd_1 = _safe_float(row.get("Fwd 1B"), np.nan)
    fwd_3 = _safe_float(row.get("Fwd 3B"), np.nan)
    fwd_5 = _safe_float(row.get("Fwd 5B"), np.nan)
    fwd_10 = _safe_float(row.get("Fwd 10B"), np.nan)
    fwd_20 = _safe_float(row.get("Fwd 20B"), np.nan)

    early_mfe = _safe_float(row.get("Early MFE 5B"), np.nan)
    early_mae = _safe_float(row.get("Early MAE 5B"), np.nan)

    if pd.notna(fwd_5) and pd.notna(early_mae) and fwd_5 > 0.02 and early_mae > -0.03:
        return "Good entry / clean follow-through"

    if pd.notna(fwd_1) and pd.notna(fwd_10) and fwd_1 < -0.02 and fwd_10 > 0.02:
        return "Early adverse move / delayed payoff"

    if pd.notna(fwd_5) and pd.notna(early_mfe) and fwd_5 < 0 and early_mfe < 0.02:
        return "Bad entry / no follow-through"

    if pd.notna(early_mae) and early_mae <= -0.05:
        return "High adverse excursion after entry"

    if pd.notna(fwd_5) and pd.notna(fwd_20) and fwd_5 <= 0 and fwd_20 > 0.03:
        return "Slow signal / payoff comes late"

    if pd.notna(fwd_3) and pd.notna(fwd_10) and fwd_3 > 0 and fwd_10 < 0:
        return "Short-lived edge / fast decay"

    return "Neutral"


def _entry_signal_quality_lab(
    bt: pd.DataFrame,
    trades: pd.DataFrame,
    horizons: tuple[int, ...] = (1, 3, 5, 10, 20),
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """
    Entry / Signal Quality Lab.

    Mesure ce qui arrive après chaque entrée :
    - forward return 1/3/5/10/20 bars ;
    - hit rate post-entry ;
    - early MFE / MAE ;
    - signal decay ;
    - bad entry share ;
    - diagnostic qualitatif par trade.

    Lecture seule : ne modifie ni le moteur, ni l'equity curve, ni le verdict.
    """
    if bt is None or bt.empty or trades is None or trades.empty:
        return pd.DataFrame(), pd.DataFrame()

    rows = []
    max_horizon = max(horizons)

    for _, trade in trades.iterrows():
        path, has_ohlc = _entry_forward_path(bt, trade, max_horizon=max_horizon)

        if path.empty:
            continue

        row = {
            "Entry Date": trade.get("Entry Date", "N/A"),
            "Exit Date": trade.get("Exit Date", "N/A"),
            "Side": trade.get("Side", "N/A"),
            "Entry Price": trade.get("Entry Price", np.nan),
            "Original Trade Return": trade.get("Return", np.nan),
            "Original MFE": trade.get("MFE", np.nan),
            "Original MAE": trade.get("MAE", np.nan),
            "Original Bars": trade.get("Bars", np.nan),
            "Data Mode": "OHLC forward path" if has_ohlc else "Close-only fallback",
        }

        for h in horizons:
            if len(path) > h:
                row[f"Fwd {h}B"] = float(path["close_return"].iloc[h])
            else:
                row[f"Fwd {h}B"] = np.nan

        early = path[path["bar_after_entry"] <= 5].copy()

        if not early.empty:
            row["Early MFE 5B"] = float(early["best_return"].max())
            row["Early MAE 5B"] = float(early["worst_return"].min())
        else:
            row["Early MFE 5B"] = np.nan
            row["Early MAE 5B"] = np.nan

        full_mfe = float(path["best_return"].max()) if not path.empty else np.nan
        full_mae = float(path["worst_return"].min()) if not path.empty else np.nan

        row["Forward MFE 20B"] = full_mfe
        row["Forward MAE 20B"] = full_mae

        fwd_5 = _safe_float(row.get("Fwd 5B"), np.nan)
        fwd_20 = _safe_float(row.get("Fwd 20B"), np.nan)

        row["Signal Decay 20B-5B"] = (
            fwd_20 - fwd_5
            if pd.notna(fwd_5) and pd.notna(fwd_20)
            else np.nan
        )

        rows.append(row)

    detail = pd.DataFrame(rows)

    if detail.empty:
        return pd.DataFrame(), pd.DataFrame()

    detail["Entry Diagnosis"] = detail.apply(_diagnose_entry_quality, axis=1)

    fwd_cols = [f"Fwd {h}B" for h in horizons if f"Fwd {h}B" in detail.columns]

    fwd_1 = pd.to_numeric(detail.get("Fwd 1B"), errors="coerce") if "Fwd 1B" in detail.columns else pd.Series(dtype=float)
    fwd_3 = pd.to_numeric(detail.get("Fwd 3B"), errors="coerce") if "Fwd 3B" in detail.columns else pd.Series(dtype=float)
    fwd_5 = pd.to_numeric(detail.get("Fwd 5B"), errors="coerce") if "Fwd 5B" in detail.columns else pd.Series(dtype=float)
    fwd_10 = pd.to_numeric(detail.get("Fwd 10B"), errors="coerce") if "Fwd 10B" in detail.columns else pd.Series(dtype=float)
    fwd_20 = pd.to_numeric(detail.get("Fwd 20B"), errors="coerce") if "Fwd 20B" in detail.columns else pd.Series(dtype=float)

    early_mfe = pd.to_numeric(detail.get("Early MFE 5B"), errors="coerce")
    early_mae = pd.to_numeric(detail.get("Early MAE 5B"), errors="coerce")
    decay = pd.to_numeric(detail.get("Signal Decay 20B-5B"), errors="coerce")

    def _avg(series: pd.Series) -> float:
        clean = series.replace([np.inf, -np.inf], np.nan).dropna()
        return float(clean.mean()) if not clean.empty else np.nan

    def _hit(series: pd.Series) -> float:
        clean = series.replace([np.inf, -np.inf], np.nan).dropna()
        return float((clean > 0).mean()) if not clean.empty else np.nan

    trade_count = int(len(detail))
    hit_1 = _hit(fwd_1)
    hit_3 = _hit(fwd_3)
    hit_5 = _hit(fwd_5)
    hit_10 = _hit(fwd_10)
    hit_20 = _hit(fwd_20)

    avg_1 = _avg(fwd_1)
    avg_3 = _avg(fwd_3)
    avg_5 = _avg(fwd_5)
    avg_10 = _avg(fwd_10)
    avg_20 = _avg(fwd_20)

    avg_early_mfe = _avg(early_mfe)
    avg_early_mae = _avg(early_mae)
    avg_decay = _avg(decay)

    bad_mask = detail["Entry Diagnosis"].astype(str).str.contains(
        "Bad entry|High adverse|no follow-through",
        case=False,
        regex=True,
        na=False,
    )
    bad_entry_share = float(bad_mask.mean()) if trade_count > 0 else np.nan

    clean_follow_mask = detail["Entry Diagnosis"].astype(str).str.contains(
        "Good entry",
        case=False,
        regex=False,
        na=False,
    )
    clean_follow_share = float(clean_follow_mask.mean()) if trade_count > 0 else np.nan

    # Score volontairement simple et stable.
    # Il récompense : hit rate 5B, avg 5B, early MFE, faible early MAE, faible bad entry share.
    score = 50.0

    if pd.notna(hit_5):
        score += (hit_5 - 0.50) * 35.0

    if pd.notna(avg_5):
        score += avg_5 * 350.0

    if pd.notna(avg_early_mfe):
        score += avg_early_mfe * 80.0

    if pd.notna(avg_early_mae):
        score += avg_early_mae * 120.0

    if pd.notna(bad_entry_share):
        score -= bad_entry_share * 30.0

    score = max(0.0, min(100.0, score))

    if trade_count < 5:
        quality_level = "Low sample"
    elif score >= 70 and pd.notna(avg_5) and avg_5 > 0:
        quality_level = "Strong entry edge"
    elif score >= 50:
        quality_level = "Mixed entry edge"
    else:
        quality_level = "Weak entry edge"

    stats = pd.DataFrame(
        [
            ["Entry quality level", quality_level, "Lecture synthétique de la qualité d'entrée."],
            ["Entry timing score", _format_num(score, 0) + "/100", "Score interne basé sur follow-through, MAE/MFE et hit rate."],
            ["Trade sample", str(trade_count), "Nombre de trades utilisés pour le diagnostic."],
            ["Hit rate 1B", _format_pct(hit_1), "Part des entrées positives après 1 barre."],
            ["Hit rate 3B", _format_pct(hit_3), "Part des entrées positives après 3 barres."],
            ["Hit rate 5B", _format_pct(hit_5), "Part des entrées positives après 5 barres."],
            ["Hit rate 10B", _format_pct(hit_10), "Part des entrées positives après 10 barres."],
            ["Hit rate 20B", _format_pct(hit_20), "Part des entrées positives après 20 barres."],
            ["Avg forward 1B", _format_pct(avg_1), "Rendement moyen 1 barre après entrée."],
            ["Avg forward 3B", _format_pct(avg_3), "Rendement moyen 3 barres après entrée."],
            ["Avg forward 5B", _format_pct(avg_5), "Rendement moyen 5 barres après entrée."],
            ["Avg forward 10B", _format_pct(avg_10), "Rendement moyen 10 barres après entrée."],
            ["Avg forward 20B", _format_pct(avg_20), "Rendement moyen 20 barres après entrée."],
            ["Avg early MFE 5B", _format_pct(avg_early_mfe), "Excursion favorable moyenne dans les 5 premières barres."],
            ["Avg early MAE 5B", _format_pct(avg_early_mae), "Excursion défavorable moyenne dans les 5 premières barres."],
            ["Avg signal decay 20B-5B", _format_pct(avg_decay), "Rendement 20B moins rendement 5B. Négatif = edge qui se dégrade."],
            ["Clean follow-through share", _format_pct(clean_follow_share), "Part des entrées avec follow-through propre."],
            ["Bad entry share", _format_pct(bad_entry_share), "Part des entrées avec mauvais timing ou forte adverse excursion."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    return stats, detail


def _render_entry_signal_quality_lab(bt: pd.DataFrame, trades: pd.DataFrame) -> None:
    """
    Rendu Streamlit du Entry / Signal Quality Lab.
    Bloc volontairement non silencieux : si le calcul ne sort rien,
    on affiche un diagnostic au lieu de return sans rien montrer.
    """
    st.subheader("Entry / Signal Quality Lab")
    st.caption(
        "Diagnostic lecture seule de la qualité d'entrée : forward returns 1/3/5/10/20 barres, "
        "hit rate post-entry, early MFE/MAE, signal decay et diagnostic qualitatif par trade. "
        "Ne modifie ni le moteur, ni l'equity curve, ni le verdict."
    )

    stats, detail = _entry_signal_quality_lab(bt, trades)

    if stats.empty or detail.empty:
        st.warning(
            "Entry / Signal Quality Lab appelé, mais aucune ligne affichable. "
            "Le bloc est bien exécuté, mais les données nécessaires au calcul ne sont pas disponibles."
        )

        diag = pd.DataFrame(
            [
                [
                    "bt rows",
                    str(len(bt)) if bt is not None else "0",
                    "Nombre de lignes dans le backtest moteur.",
                ],
                [
                    "trades rows",
                    str(len(trades)) if trades is not None else "0",
                    "Nombre de trades reçus par le bloc Entry Lab.",
                ],
                [
                    "bt columns",
                    ", ".join(list(bt.columns)) if bt is not None and hasattr(bt, "columns") else "N/A",
                    "Colonnes disponibles dans bt.",
                ],
                [
                    "trades columns",
                    ", ".join(list(trades.columns)) if trades is not None and hasattr(trades, "columns") else "N/A",
                    "Colonnes disponibles dans trades.",
                ],
                [
                    "required trade columns",
                    "Entry Bar, Entry Date, Entry Price, Side",
                    "Colonnes nécessaires pour reconstruire le chemin forward après entrée.",
                ],
            ],
            columns=["Diagnostic", "Value", "Read"],
        )

        st.dataframe(diag, use_container_width=True, hide_index=True)

        if trades is not None and isinstance(trades, pd.DataFrame) and not trades.empty:
            with st.expander("Debug trades preview", expanded=False):
                st.dataframe(trades.head(10), use_container_width=True, hide_index=True)

        return

    level = str(stats.loc[stats["Metric"] == "Entry quality level", "Value"].iloc[0])
    score = str(stats.loc[stats["Metric"] == "Entry timing score", "Value"].iloc[0])

    def _stat_value(metric_name: str) -> str:
        try:
            return str(stats.loc[stats["Metric"] == metric_name, "Value"].iloc[0])
        except Exception:
            return "N/A"

    cards = [
        {
            "label": "Entry quality",
            "value": level,
            "delta": score,
        },
        {
            "label": "Hit rate 5B",
            "value": _stat_value("Hit rate 5B"),
            "delta": "post-entry",
        },
        {
            "label": "Avg forward 5B",
            "value": _stat_value("Avg forward 5B"),
            "delta": "follow-through",
        },
        {
            "label": "Early MFE 5B",
            "value": _stat_value("Avg early MFE 5B"),
            "delta": "favorable",
        },
        {
            "label": "Early MAE 5B",
            "value": _stat_value("Avg early MAE 5B"),
            "delta": "adverse",
        },
        {
            "label": "Bad entry share",
            "value": _stat_value("Bad entry share"),
            "delta": "timing risk",
        },
    ]

    _card_grid(cards, columns=6)

    if "Strong" in level:
        st.success(
            "Lecture entry : les entrées montrent un follow-through exploitable après signal. "
            "À confirmer via walk-forward et échantillon plus large."
        )
    elif "Weak" in level:
        st.warning(
            "Lecture entry : le signal d'entrée semble faible ou mal timé. "
            "Le problème peut venir de l'entrée plutôt que seulement des sorties."
        )
    elif "Low sample" in level:
        st.info(
            "Lecture entry : échantillon trop faible pour conclure proprement. "
            "Les métriques sont utiles pour inspection, pas pour validation."
        )
    else:
        st.info(
            "Lecture entry : signal mitigé. Certaines entrées fonctionnent, mais le follow-through n'est pas stable."
        )

    with st.expander("Entry quality summary table", expanded=True):
        st.dataframe(stats, use_container_width=True, hide_index=True)

    display = detail.copy()

    if "Entry Price" in display.columns:
        display["Entry Price"] = display["Entry Price"].map(lambda x: _format_num(x))

    pct_cols = [
        "Original Trade Return",
        "Original MFE",
        "Original MAE",
        "Fwd 1B",
        "Fwd 3B",
        "Fwd 5B",
        "Fwd 10B",
        "Fwd 20B",
        "Early MFE 5B",
        "Early MAE 5B",
        "Forward MFE 20B",
        "Forward MAE 20B",
        "Signal Decay 20B-5B",
    ]

    for col in pct_cols:
        if col in display.columns:
            display[col] = display[col].map(lambda x: _format_pct(x))

    keep_cols = [
        "Entry Date",
        "Exit Date",
        "Side",
        "Entry Price",
        "Original Trade Return",
        "Fwd 1B",
        "Fwd 3B",
        "Fwd 5B",
        "Fwd 10B",
        "Fwd 20B",
        "Early MFE 5B",
        "Early MAE 5B",
        "Signal Decay 20B-5B",
        "Original Bars",
        "Entry Diagnosis",
        "Data Mode",
    ]

    display = display[[c for c in keep_cols if c in display.columns]]

    with st.expander("Trade-level entry map", expanded=True):
        st.dataframe(display, use_container_width=True, hide_index=True)


# ============================================================
# INTEGRITY + VERDICT
# ============================================================

def _simulate_exit_rule_on_trade(
    bt: pd.DataFrame,
    trade: pd.Series,
    rule_name: str,
    cfg: BacktestConfig,
) -> dict[str, Any]:
    """
    Simule une règle de sortie alternative sur un trade existant.

    V1 réaliste :
    - utilise OHLC si disponible ;
    - take profit capé au seuil cible au lieu du close supérieur ;
    - stop capé au seuil, avec gap d'ouverture adverse respecté ;
    - trailing / MFE giveback capés au niveau de déclenchement ;
    - lecture seule : ne modifie pas l'equity curve ni le verdict.
    """
    path, has_ohlc = _trade_ohlc_path(bt, trade)
    engine_return = _safe_float(trade.get("Return"), np.nan)
    baseline_return, baseline_assumption = _exit_lab_baseline_return(bt, trade, cfg)

    empty = {
        "Rule": rule_name,
        "Entry Date": trade.get("Entry Date", "N/A"),
        "Original Exit Date": trade.get("Exit Date", "N/A"),
        "Alternative Exit Date": "N/A",
        "Side": trade.get("Side", "N/A"),
        "Engine Return": engine_return,
        "Baseline Return": baseline_return,
        "Rule Return": np.nan,
        "Delta vs Baseline": np.nan,
        "Bars Held": np.nan,
        "Exit Trigger": "Unavailable",
        "Execution Assumption": "unavailable",
    }

    if path.empty:
        return empty

    round_trip_cost = 2.0 * (float(cfg.fee_bps) + float(cfg.slippage_bps)) / 10000.0

    exit_pos = len(path) - 1
    trigger = "Original exit"
    assumption = "OHLC threshold-capped" if has_ohlc else "close-based fallback"
    fill_return = float(path["close_return"].iloc[exit_pos])

    rule = str(rule_name)

    try:
        test_path = path.iloc[1:] if len(path) > 1 else path

        if rule.startswith("Stop "):
            stop = abs(_parse_pct_text(rule.replace("Stop ", "")))
            hits = test_path[test_path["worst_return"] <= -stop]

            if not hits.empty:
                hit_idx = hits.index[0]
                exit_pos = int(path.index.get_loc(hit_idx))
                fill_return, extra = _exit_fill_return(
                    threshold_return=-stop,
                    open_return=float(path.loc[hit_idx, "open_return"]),
                    is_stop=True,
                )
                trigger = f"Stop hit {rule.replace('Stop ', '')}"
                assumption = f"{assumption}; {extra}"

        elif rule.startswith("Take profit "):
            target = abs(_parse_pct_text(rule.replace("Take profit ", "")))
            hits = test_path[test_path["best_return"] >= target]

            if not hits.empty:
                hit_idx = hits.index[0]
                exit_pos = int(path.index.get_loc(hit_idx))
                fill_return, extra = _exit_fill_return(
                    threshold_return=target,
                    open_return=float(path.loc[hit_idx, "open_return"]),
                    is_stop=False,
                )
                trigger = f"Take profit hit {rule.replace('Take profit ', '')}"
                assumption = f"{assumption}; {extra}"

        elif rule.startswith("Time stop "):
            bars_txt = rule.replace("Time stop ", "").replace(" bars", "").strip()
            bars = int(float(bars_txt))
            exit_pos = min(max(bars, 1), len(path) - 1)
            fill_return = float(path["close_return"].iloc[exit_pos])
            trigger = f"Time stop {bars} bars"
            assumption = "close at time stop"

        elif rule.startswith("Trailing "):
            txt = rule.replace("Trailing ", "")
            trail_txt, activation_txt = txt.split(" after ")
            trail = abs(_parse_pct_text(trail_txt))
            activation = abs(_parse_pct_text(activation_txt.replace("+", "")))

            peak = path["best_return"].cummax()
            stop_level = peak - trail
            hits = path[(peak >= activation) & (path["worst_return"] <= stop_level)]
            hits = hits.iloc[1:] if len(hits) > 0 and hits.index[0] == path.index[0] else hits

            if not hits.empty:
                hit_idx = hits.index[0]
                exit_pos = int(path.index.get_loc(hit_idx))
                fill_return, extra = _exit_fill_return(
                    threshold_return=float(stop_level.loc[hit_idx]),
                    open_return=float(path.loc[hit_idx, "open_return"]),
                    is_stop=True,
                )
                trigger = f"Trailing stop {trail_txt}"
                assumption = f"{assumption}; {extra}"

        elif rule.startswith("MFE giveback "):
            txt = rule.replace("MFE giveback ", "")
            giveback_txt, activation_txt = txt.split(" after ")
            giveback = abs(_parse_pct_text(giveback_txt))
            activation = abs(_parse_pct_text(activation_txt.replace("+", "")))

            peak = path["best_return"].cummax()
            giveback_floor = peak * (1.0 - giveback)
            hits = path[(peak >= activation) & (path["worst_return"] <= giveback_floor)]
            hits = hits.iloc[1:] if len(hits) > 0 and hits.index[0] == path.index[0] else hits

            if not hits.empty:
                hit_idx = hits.index[0]
                exit_pos = int(path.index.get_loc(hit_idx))
                fill_return, extra = _exit_fill_return(
                    threshold_return=float(giveback_floor.loc[hit_idx]),
                    open_return=float(path.loc[hit_idx, "open_return"]),
                    is_stop=True,
                )
                trigger = f"MFE giveback {giveback_txt}"
                assumption = f"{assumption}; {extra}"

        else:
            fill_return = float(path["close_return"].iloc[exit_pos])
            assumption = "original close return"

    except Exception:
        exit_pos = len(path) - 1
        fill_return = float(path["close_return"].iloc[exit_pos])
        trigger = "Rule parsing fallback"
        assumption = "close-based fallback"

    exit_pos = max(0, min(int(exit_pos), len(path) - 1))
    alt_exit_date = path.index[exit_pos]

    rule_return = float(fill_return) - round_trip_cost

    return {
        "Rule": rule_name,
        "Engine Return": engine_return,
        "Entry Date": trade.get("Entry Date", "N/A"),
        "Original Exit Date": trade.get("Exit Date", "N/A"),
        "Alternative Exit Date": _format_dt(alt_exit_date),
        "Side": trade.get("Side", "N/A"),
        "Baseline Return": baseline_return,
        "Rule Return": rule_return,
        "Delta vs Baseline": rule_return - baseline_return if pd.notna(baseline_return) else np.nan,
        "Bars Held": int(exit_pos + 1),
        "Exit Trigger": trigger,
        "Execution Assumption": assumption,
    }

def _exit_efficiency_lab(
    bt: pd.DataFrame,
    trades: pd.DataFrame,
    cfg: BacktestConfig,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """
    Exit Efficiency Lab.
    Teste plusieurs sorties alternatives sur les trades existants.

    Important :
    - lecture seule ;
    - close-based proxy ;
    - ne modifie pas les signaux, l'equity curve, le verdict ou les métriques principales.
    """
    if bt is None or bt.empty or trades is None or trades.empty:
        return pd.DataFrame(), pd.DataFrame()

    rules = [
        "Baseline",
        "Stop -3%",
        "Stop -5%",
        "Stop -8%",
        "Take profit +5%",
        "Take profit +8%",
        "Take profit +12%",
        "Time stop 10 bars",
        "Time stop 20 bars",
        "Time stop 30 bars",
        "Trailing 5% after +5%",
        "Trailing 8% after +5%",
        "MFE giveback 50% after +5%",
        "MFE giveback 70% after +5%",
    ]

    detail_rows = []

    for _, trade in trades.iterrows():
        engine_return = _safe_float(trade.get("Return"), np.nan)
        baseline_return, baseline_assumption = _exit_lab_baseline_return(bt, trade, cfg)

        for rule in rules:
            if rule == "Baseline":
                row = {
                    "Rule": "Baseline",
                    "Entry Date": trade.get("Entry Date", "N/A"),
                    "Original Exit Date": trade.get("Exit Date", "N/A"),
                    "Alternative Exit Date": trade.get("Exit Date", "N/A"),
                    "Side": trade.get("Side", "N/A"),
                    "Engine Return": engine_return,
                    "Baseline Return": baseline_return,
                    "Rule Return": baseline_return,
                    "Delta vs Baseline": 0.0,
                    "Bars Held": trade.get("Bars", np.nan),
                    "Exit Trigger": "Original strategy exit",
                    "Execution Assumption": baseline_assumption,
                }
            else:
                row = _simulate_exit_rule_on_trade(bt, trade, rule, cfg)

            detail_rows.append(row)

    detail = pd.DataFrame(detail_rows)

    if detail.empty:
        return pd.DataFrame(), pd.DataFrame()

    summary_rows = []

    baseline = detail[detail["Rule"] == "Baseline"].copy()
    baseline_returns = pd.to_numeric(baseline["Rule Return"], errors="coerce").dropna()

    baseline_avg = float(baseline_returns.mean()) if not baseline_returns.empty else np.nan
    baseline_worst = float(baseline_returns.min()) if not baseline_returns.empty else np.nan
    baseline_pf = _profit_factor_from_returns(baseline_returns)

    for rule, grp in detail.groupby("Rule"):
        r = pd.to_numeric(grp["Rule Return"], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
        delta = pd.to_numeric(grp["Delta vs Baseline"], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()

        if r.empty:
            continue

        avg_return = float(r.mean())
        median_return = float(r.median())
        win_rate = float((r > 0).mean())
        profit_factor = _profit_factor_from_returns(r)
        worst_trade = float(r.min())
        best_trade = float(r.max())
        avg_delta = float(delta.mean()) if not delta.empty else np.nan
        improvement_share = float((delta > 0).mean()) if not delta.empty else np.nan

        changed_exits = int(
            (
                grp["Alternative Exit Date"].astype(str)
                != grp["Original Exit Date"].astype(str)
            ).sum()
        )

        # Score simple et lisible : amélioration moyenne, réduction du pire trade, profit factor.
        score = 50.0

        if pd.notna(avg_delta):
            score += avg_delta * 500.0

        if pd.notna(baseline_worst):
            score += (worst_trade - baseline_worst) * 250.0

        if pd.notna(profit_factor) and pd.notna(baseline_pf):
            score += (profit_factor - baseline_pf) * 10.0

        score = max(0.0, min(100.0, score))

        summary_rows.append(
            {
                "Rule": rule,
                "Avg Trade Return": avg_return,
                "Median Trade Return": median_return,
                "Win Rate": win_rate,
                "Profit Factor": profit_factor,
                "Worst Trade": worst_trade,
                "Best Trade": best_trade,
                "Avg Delta vs Baseline": avg_delta,
                "Improved Trades": improvement_share,
                "Changed Exits": changed_exits,
                "Exit Efficiency Score": score,
            }
        )

    summary = pd.DataFrame(summary_rows)

    if summary.empty:
        return pd.DataFrame(), pd.DataFrame()

    summary = summary.sort_values(
        ["Exit Efficiency Score", "Avg Delta vs Baseline", "Profit Factor"],
        ascending=[False, False, False],
    )

    return summary, detail


def _render_exit_efficiency_lab(bt: pd.DataFrame, trades: pd.DataFrame, cfg: BacktestConfig) -> None:
    """
    Rendu Streamlit du Exit Efficiency Lab.
    """
    summary, detail = _exit_efficiency_lab(bt, trades, cfg)

    if summary.empty:
        return

    st.subheader("Exit Efficiency Lab")
    st.caption(
        "Simulation lecture seule de règles de sortie alternatives sur les trades existants. "
        "Proxy OHLC / threshold-capped lorsque open/high/low sont disponibles : "
        "take profit et stop sont exécutés au seuil, pas au close favorable. "
        "Ne modifie ni le moteur, ni l'equity curve, ni le verdict."
    )

    baseline_row = summary[summary["Rule"] == "Baseline"].head(1)
    best_row = summary[summary["Rule"] != "Baseline"].head(1)

    if not best_row.empty:
        best = best_row.iloc[0]

        baseline_avg = (
            _safe_float(baseline_row.iloc[0].get("Avg Trade Return"), np.nan)
            if not baseline_row.empty
            else np.nan
        )

        cards = [
            {
                "label": "Best exit rule",
                "value": str(best.get("Rule", "N/A")),
                "delta": f"score {_format_num(best.get('Exit Efficiency Score'), 0)}/100",
            },
            {
                "label": "Avg trade return",
                "value": _format_pct(best.get("Avg Trade Return")),
                "delta": f"baseline {_format_pct(baseline_avg)}",
            },
            {
                "label": "Profit factor",
                "value": _format_num(best.get("Profit Factor")),
                "delta": "trade-level",
            },
            {
                "label": "Worst trade",
                "value": _format_pct(best.get("Worst Trade")),
                "delta": "loss control",
            },
            {
                "label": "Avg delta",
                "value": _format_pct(best.get("Avg Delta vs Baseline")),
                "delta": "vs current exits",
            },
            {
                "label": "Improved trades",
                "value": _format_pct(best.get("Improved Trades")),
                "delta": f"{int(best.get('Changed Exits', 0))} changed exits",
            },
        ]

        _card_grid(cards, columns=6)

        avg_delta = _safe_float(best.get("Avg Delta vs Baseline"), 0.0)
        worst_trade = _safe_float(best.get("Worst Trade"), 0.0)

        if avg_delta > 0.01:
            st.success(
                "Lecture exit : une règle alternative améliore nettement la moyenne des trades. "
                "À tester ensuite dans le moteur principal, mais seulement après validation robuste."
            )
        else:
            baseline_worst = (
                _safe_float(baseline_row.iloc[0].get("Worst Trade"), np.nan)
                if not baseline_row.empty
                else np.nan
            )

            if pd.notna(baseline_worst) and worst_trade > baseline_worst:
                st.info(
                    "Lecture exit : l'amélioration vient surtout de la réduction des pertes extrêmes, "
                    "pas forcément d'une hausse du rendement moyen."
                )
            else:
                st.warning(
                    "Lecture exit : aucune règle simple ne corrige clairement le profil de sortie. "
                    "Le problème peut venir de l'entrée, du régime ou du signal lui-même."
                )

    display_summary = summary.copy()

    for col in [
        "Avg Trade Return",
        "Median Trade Return",
        "Win Rate",
        "Worst Trade",
        "Best Trade",
        "Avg Delta vs Baseline",
        "Improved Trades",
    ]:
        if col in display_summary.columns:
            display_summary[col] = display_summary[col].map(_format_pct)

    for col in ["Profit Factor", "Exit Efficiency Score"]:
        if col in display_summary.columns:
            display_summary[col] = display_summary[col].map(_format_num)

    with st.expander("Exit rule comparison table", expanded=True):
        st.dataframe(display_summary, use_container_width=True, hide_index=True)

    if not best_row.empty and not detail.empty:
        best_rule = str(best_row.iloc[0].get("Rule", ""))

        best_detail = detail[detail["Rule"] == best_rule].copy()

        if not best_detail.empty:
            detail_cols = [
                "Rule",
                "Entry Date",
                "Original Exit Date",
                "Alternative Exit Date",
                "Side",
                "Engine Return",
                "Baseline Return",
                "Rule Return",
                "Delta vs Baseline",
                "Bars Held",
                "Exit Trigger",
                "Execution Assumption",
            ]

            best_detail = best_detail[
                [col for col in detail_cols if col in best_detail.columns]
            ].copy()

            for col in [
                "Engine Return",
                "Baseline Return",
                "Rule Return",
                "Delta vs Baseline",
            ]:
                if col in best_detail.columns:
                    best_detail[col] = best_detail[col].map(_format_pct)

            with st.expander(f"Trade-level detail — {best_rule}", expanded=False):
                st.caption(
                    "Engine Return = rendement réel du moteur. "
                    "Baseline Return = proxy comparable OHLC/close utilisé uniquement pour comparer les sorties. "
                    "Rule Return = rendement simulé avec la règle alternative."
                )
                st.dataframe(best_detail, use_container_width=True, hide_index=True)


# ============================================================
# INTEGRITY + VERDICT
# ============================================================

def _integrity_score(metrics: dict[str, Any], bt: pd.DataFrame, cfg: BacktestConfig) -> tuple[int, list[str]]:
    score = 100
    notes = []

    if len(bt) < 252:
        score -= 15
        notes.append("Historique inférieur à 1 an.")

    trades = int(metrics.get("Trades", 0) or 0)
    if trades < 5:
        score -= 20
        notes.append("Nombre de trades faible : risque de conclusion fragile.")

    if cfg.fee_bps <= 0 and cfg.slippage_bps <= 0:
        score -= 20
        notes.append("Coûts/slippage nuls : backtest probablement trop optimiste.")

    if bool(metrics.get("Benchmark Fallback", False)):
        score -= 5
        notes.append("Benchmark externe indisponible : fallback utilisé.")

    exposure = _safe_float(metrics.get("Exposure"), 0)
    if exposure < 0.05:
        score -= 10
        notes.append("Exposition très faible : résultats peu représentatifs.")
    if exposure > 0.95:
        score -= 5
        notes.append("Exposition quasi permanente : proche buy & hold.")

    max_dd = _safe_float(metrics.get("Max Drawdown"), 0)
    if max_dd < -0.35:
        score -= 10
        notes.append("Drawdown très élevé.")

    return max(0, min(100, int(score))), notes


def _verdict(metrics: dict[str, Any], integrity: int, notes: list[str]) -> tuple[str, str, list[str]]:
    total_return = _safe_float(metrics.get("Total Return"), 0)
    alpha = _safe_float(metrics.get("Relative Alpha"), 0)
    sharpe = _safe_float(metrics.get("Sharpe"), np.nan)
    max_dd = _safe_float(metrics.get("Max Drawdown"), 0)
    trades = int(metrics.get("Trades", 0) or 0)

    reasons = []

    if total_return <= 0:
        reasons.append("performance stratégie négative")
    if alpha < -0.10:
        reasons.append("sous-performance significative vs benchmark")
    if pd.notna(sharpe) and sharpe < 0:
        reasons.append("Sharpe négatif")
    if max_dd < -0.30:
        reasons.append("drawdown élevé")
    if trades < 5:
        reasons.append("échantillon de trades trop faible")
    if any("Historique inférieur" in note for note in notes):
        reasons.append("historique court")

    if total_return <= 0 or alpha < -0.20 or (pd.notna(sharpe) and sharpe < 0):
        return "REJECTED", "error", reasons or ["profil rendement/risque insuffisant"]

    if integrity < 55:
        return "FRAGILE", "warning", reasons or ["intégrité statistique faible"]

    if alpha > 0 and pd.notna(sharpe) and sharpe >= 1 and max_dd > -0.25 and integrity >= 75:
        if any("historique court" in r for r in reasons):
            return "WATCHLIST", "warning", reasons
        return "VALIDATED", "success", ["surperformance ajustée du risque et intégrité acceptable"]

    return "WATCHLIST", "warning", reasons or ["résultat exploitable mais pas assez robuste pour validation"]


def _research_verdict(edge_score: float, verdict: str, diagnostics: dict[str, Any]) -> str:
    if verdict == "REJECTED":
        return "REJECTED EDGE"
    if diagnostics.get("pbo_proxy", 1.0) >= 0.65:
        return "FRAGILE / OVERFIT RISK"
    if edge_score >= 75 and diagnostics.get("dsr_proxy", 0.0) >= 0.70:
        return "PAPER-TEST READY"
    if edge_score >= 55:
        return "RESEARCH CANDIDATE"
    return "FRAGILE"


# ============================================================
# ROBUSTNESS + RESEARCH DIAGNOSTICS
# ============================================================

def _cost_stress_matrix(df: pd.DataFrame, cfg: BacktestConfig) -> pd.DataFrame:
    fees = [0, 2, 5, 10, 20]
    slips = [0, 2, 5, 10, 20]
    matrix = pd.DataFrame(index=fees, columns=slips, dtype=float)

    for fee in fees:
        for slip in slips:
            test_cfg = BacktestConfig(**{**cfg.__dict__, "fee_bps": fee, "slippage_bps": slip})
            res = _run_backtest(df, test_cfg)
            matrix.loc[fee, slip] = res.get("metrics", {}).get("CAGR", np.nan) if "metrics" in res else np.nan

    matrix.index.name = "Fee bps"
    matrix.columns.name = "Slippage bps"
    return matrix


def _parameter_sensitivity_matrix(df: pd.DataFrame, cfg: BacktestConfig) -> pd.DataFrame:
    if cfg.strategy != "SMA Trend":
        return pd.DataFrame()

    fast_grid = [10, 20, 30, 50]
    slow_grid = [60, 100, 150, 200]
    matrix = pd.DataFrame(index=fast_grid, columns=slow_grid, dtype=float)

    for fast in fast_grid:
        for slow in slow_grid:
            if fast >= slow:
                matrix.loc[fast, slow] = np.nan
                continue
            test_cfg = BacktestConfig(**{**cfg.__dict__, "fast_ma": fast, "slow_ma": slow})
            res = _run_backtest(df, test_cfg)
            matrix.loc[fast, slow] = res.get("metrics", {}).get("CAGR", np.nan) if "metrics" in res else np.nan

    matrix.index.name = "Fast MA"
    matrix.columns.name = "Slow MA"
    return matrix


def _heatmap_fig(matrix: pd.DataFrame, title: str, value_suffix: str = "%") -> go.Figure:
    z = matrix.astype(float).values
    text = np.empty(z.shape, dtype=object)

    for i in range(z.shape[0]):
        for j in range(z.shape[1]):
            text[i, j] = _format_pct(z[i, j]) if pd.notna(z[i, j]) else "N/A"

    fig = go.Figure(
        data=go.Heatmap(
            z=z,
            x=[str(x) for x in matrix.columns],
            y=[str(y) for y in matrix.index],
            text=text,
            texttemplate="%{text}",
            hovertemplate="X=%{x}<br>Y=%{y}<br>Value=%{text}<extra></extra>",
            colorbar=dict(title=value_suffix),
            zmid=0,
            colorscale=[[0.0, "#ff4b5c"], [0.5, "#101826"], [1.0, "#55e6ff"]],
        )
    )

    fig.update_layout(
        title=title,
        height=360,
        margin=dict(l=15, r=15, t=55, b=15),
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        font=dict(color="#EAF6FF"),
    )
    fig.update_xaxes(type="category", title_text=matrix.columns.name or "")
    fig.update_yaxes(type="category", title_text=matrix.index.name or "")
    return fig


def _split_analysis(bt: pd.DataFrame) -> pd.DataFrame:
    """
    In-sample / Out-of-sample split V2.

    Lecture seule :
    - ne modifie pas le moteur ;
    - ne modifie pas les trades ;
    - ne modifie pas l'equity curve ;
    - sert uniquement à mesurer la robustesse hors-échantillon.
    """
    if len(bt) < 120:
        return pd.DataFrame()

    split = int(len(bt) * 0.60)

    parts = {
        "In-sample 60%": bt.iloc[:split].copy(),
        "Out-of-sample 40%": bt.iloc[split:].copy(),
        "Full": bt.copy(),
    }

    rows = []

    for name, part in parts.items():
        if len(part) < 20:
            continue

        m = _compute_metrics(part)

        daily = (
            pd.to_numeric(part["strategy_return"], errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .dropna()
        )

        bench = (
            pd.to_numeric(part["benchmark_return"], errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .dropna()
            if "benchmark_return" in part.columns
            else pd.Series(dtype=float)
        )

        var95 = float(daily.quantile(0.05)) if len(daily) >= 20 else np.nan
        cvar95 = (
            float(daily[daily <= var95].mean())
            if len(daily) >= 20 and (daily <= var95).any()
            else np.nan
        )

        hit_rate = float((daily > 0).mean()) if not daily.empty else np.nan
        active_share = (
            float((pd.to_numeric(part["exposure"], errors="coerce").fillna(0.0).abs() > 0).mean())
            if "exposure" in part.columns
            else np.nan
        )

        rows.append(
            {
                "Segment": name,
                "Start": _format_dt(part.index[0]),
                "End": _format_dt(part.index[-1]),
                "Obs": int(len(part)),
                "Return": m.get("Total Return"),
                "CAGR": m.get("CAGR"),
                "Benchmark": m.get("Benchmark Return"),
                "Alpha": m.get("Relative Alpha"),
                "Sharpe": m.get("Sharpe"),
                "Sortino": m.get("Sortino"),
                "Max DD": m.get("Max Drawdown"),
                "VaR 95": var95,
                "CVaR 95": cvar95,
                "Hit Rate": hit_rate,
                "Exposure": active_share,
            }
        )

    return pd.DataFrame(rows)


def _walk_forward_segments(bt: pd.DataFrame, segments: int = 5) -> pd.DataFrame:
    """
    Walk-forward segments V2.

    Découpe l'historique en fenêtres successives et mesure :
    - rendement ;
    - alpha ;
    - Sharpe ;
    - drawdown ;
    - CVaR ;
    - pass/fail par fenêtre.

    Important :
    ce n'est pas une ré-optimisation des paramètres. C'est une lecture de stabilité
    out-of-time sur le chemin déjà backtesté.
    """
    if not isinstance(bt, pd.DataFrame) or bt.empty or len(bt) < 160:
        return pd.DataFrame()

    segments = max(int(segments or 1), 2)
    cut_points = np.linspace(0, len(bt), segments + 1, dtype=int)

    rows = []

    for idx in range(segments):
        start_i = int(cut_points[idx])
        end_i = int(cut_points[idx + 1])

        part = bt.iloc[start_i:end_i].copy()

        if part.empty or len(part) < 25:
            continue

        m = _compute_metrics(part)

        daily = (
            pd.to_numeric(part["strategy_return"], errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .dropna()
        )

        var95 = float(daily.quantile(0.05)) if len(daily) >= 20 else np.nan
        cvar95 = (
            float(daily[daily <= var95].mean())
            if len(daily) >= 20 and (daily <= var95).any()
            else np.nan
        )

        ret = _safe_float(m.get("Total Return"), np.nan)
        alpha = _safe_float(m.get("Relative Alpha"), np.nan)
        sharpe = _safe_float(m.get("Sharpe"), np.nan)
        max_dd = _safe_float(m.get("Max Drawdown"), np.nan)

        pass_return = bool(pd.notna(ret) and ret > 0)
        pass_alpha = bool(pd.notna(alpha) and alpha > 0)
        pass_sharpe = bool(pd.notna(sharpe) and sharpe > 0)
        pass_dd = bool(pd.notna(max_dd) and max_dd > -0.25)

        pass_count = int(pass_return) + int(pass_alpha) + int(pass_sharpe) + int(pass_dd)

        if pass_count >= 3:
            status = "PASS"
        elif pass_count == 2:
            status = "MIXED"
        else:
            status = "FAIL"

        rows.append(
            {
                "Segment": f"WF {idx + 1}",
                "Start": _format_dt(part.index[0]),
                "End": _format_dt(part.index[-1]),
                "Obs": int(len(part)),
                "Return": ret,
                "CAGR": m.get("CAGR"),
                "Benchmark": m.get("Benchmark Return"),
                "Alpha": alpha,
                "Sharpe": sharpe,
                "Sortino": m.get("Sortino"),
                "Max DD": max_dd,
                "VaR 95": var95,
                "CVaR 95": cvar95,
                "Exposure": m.get("Exposure"),
                "Pass Return": pass_return,
                "Pass Alpha": pass_alpha,
                "Pass Sharpe": pass_sharpe,
                "Pass DD": pass_dd,
                "Pass Count": pass_count,
                "WF Status": status,
            }
        )

    return pd.DataFrame(rows)


def _bootstrap_summary(bt: pd.DataFrame, capital: float, n_sims: int = 750, seed: int = 42) -> pd.DataFrame:
    returns = bt["strategy_return"].dropna().values
    if len(returns) < 60:
        return pd.DataFrame()

    rng = np.random.default_rng(seed)
    horizon = len(returns)

    final_returns = []
    max_drawdowns = []
    sharpes = []

    for _ in range(n_sims):
        sample = rng.choice(returns, size=horizon, replace=True)
        equity = capital * np.cumprod(1 + sample)
        total_return = equity[-1] / equity[0] - 1
        dd = equity / np.maximum.accumulate(equity) - 1
        sharpe = np.mean(sample) / np.std(sample) * np.sqrt(252) if np.std(sample) > 0 else np.nan
        final_returns.append(total_return)
        max_drawdowns.append(np.min(dd))
        sharpes.append(sharpe)

    def row(name: str, arr: list[float]) -> dict[str, Any]:
        clean = pd.Series(arr).replace([np.inf, -np.inf], np.nan).dropna()
        return {
            "Metric": name,
            "P5": _format_pct(clean.quantile(0.05)) if "Return" in name or "Drawdown" in name else _format_num(clean.quantile(0.05)),
            "P50": _format_pct(clean.quantile(0.50)) if "Return" in name or "Drawdown" in name else _format_num(clean.quantile(0.50)),
            "P95": _format_pct(clean.quantile(0.95)) if "Return" in name or "Drawdown" in name else _format_num(clean.quantile(0.95)),
        }

    return pd.DataFrame([row("Total Return", final_returns), row("Max Drawdown", max_drawdowns), row("Sharpe", sharpes)])


def _bootstrap_raw(bt: pd.DataFrame, capital: float, n_sims: int = 500, seed: int = 7) -> dict[str, float]:
    returns = bt["strategy_return"].dropna().values
    if len(returns) < 60:
        return {}

    rng = np.random.default_rng(seed)
    horizon = len(returns)
    final_returns = []
    max_drawdowns = []

    for _ in range(n_sims):
        sample = rng.choice(returns, size=horizon, replace=True)
        equity = capital * np.cumprod(1 + sample)
        final_returns.append(equity[-1] / equity[0] - 1)
        max_drawdowns.append((equity / np.maximum.accumulate(equity) - 1).min())

    fr = pd.Series(final_returns).replace([np.inf, -np.inf], np.nan).dropna()
    dd = pd.Series(max_drawdowns).replace([np.inf, -np.inf], np.nan).dropna()

    return {
        "bootstrap_return_p5": float(fr.quantile(0.05)) if not fr.empty else np.nan,
        "bootstrap_return_p50": float(fr.quantile(0.50)) if not fr.empty else np.nan,
        "bootstrap_return_p95": float(fr.quantile(0.95)) if not fr.empty else np.nan,
        "bootstrap_dd_p5": float(dd.quantile(0.05)) if not dd.empty else np.nan,
    }


def _probabilistic_sharpe(bt: pd.DataFrame, benchmark_sr: float = 0.0) -> dict[str, float]:
    r = bt["strategy_return"].dropna().replace([np.inf, -np.inf], np.nan).dropna()
    if len(r) < 30 or r.std() <= 0:
        return {"psr": np.nan, "sr": np.nan, "skew": np.nan, "kurtosis": np.nan}

    sr_daily = r.mean() / r.std()
    sr_ann = sr_daily * np.sqrt(252)
    target_daily = benchmark_sr / np.sqrt(252)

    skew = float(r.skew())
    kurt = float(r.kurtosis() + 3.0)
    denom = np.sqrt(max(1e-9, 1.0 - skew * sr_daily + ((kurt - 1.0) / 4.0) * sr_daily**2))
    z = (sr_daily - target_daily) * np.sqrt(len(r) - 1.0) / denom
    psr = _normal_cdf(z)

    return {"psr": float(psr), "sr": float(sr_ann), "skew": skew, "kurtosis": kurt}


def _deflated_sharpe_proxy(psr: float, trials: int) -> float:
    if pd.isna(psr):
        return np.nan
    penalty = min(0.45, np.log1p(max(trials, 1)) / 8.0)
    return _clip(psr - penalty, 0.0, 1.0)


def _minimum_track_record_days(bt: pd.DataFrame, sr_threshold: float = 0.0, confidence: float = 0.95) -> float:
    r = bt["strategy_return"].dropna().replace([np.inf, -np.inf], np.nan).dropna()
    if len(r) < 30 or r.std() <= 0:
        return np.nan

    sr_daily = r.mean() / r.std()
    target_daily = sr_threshold / np.sqrt(252)
    if sr_daily <= target_daily:
        return np.inf

    skew = float(r.skew())
    kurt = float(r.kurtosis() + 3.0)
    denom = np.sqrt(max(1e-9, 1.0 - skew * sr_daily + ((kurt - 1.0) / 4.0) * sr_daily**2))
    z = 1.645 if confidence >= 0.95 else 1.282
    return float(1.0 + (z * denom / (sr_daily - target_daily)) ** 2)


def _cost_breakeven(cost_matrix: pd.DataFrame) -> dict[str, Any]:
    if cost_matrix.empty:
        return {"label": "N/A", "score": np.nan, "max_total_bps": np.nan}

    max_total = None
    positive_cells = 0
    total_cells = 0

    for fee in cost_matrix.index:
        for slip in cost_matrix.columns:
            val = _safe_float(cost_matrix.loc[fee, slip], np.nan)
            if pd.isna(val):
                continue
            total_cells += 1
            if val > 0:
                positive_cells += 1
                total = float(fee) + float(slip)
                max_total = total if max_total is None else max(max_total, total)

    if max_total is None:
        return {"label": "Failed", "score": 0.0, "max_total_bps": 0.0, "positive_share": 0.0}

    score = _clip((max_total / 40.0) * 0.65 + (positive_cells / max(total_cells, 1)) * 0.35) * 100.0
    return {
        "label": f"Survives up to {max_total:.0f} bps",
        "score": score,
        "max_total_bps": max_total,
        "positive_share": positive_cells / max(total_cells, 1),
    }


def _parameter_stability_score(matrix: pd.DataFrame) -> dict[str, Any]:
    if matrix.empty:
        return {"label": "N/A", "score": np.nan, "positive_share": np.nan, "median": np.nan, "best": np.nan}

    clean = matrix.stack().replace([np.inf, -np.inf], np.nan).dropna()
    if clean.empty:
        return {"label": "N/A", "score": np.nan, "positive_share": np.nan, "median": np.nan, "best": np.nan}

    positive_share = float((clean > 0).mean())
    median = float(clean.median())
    best = float(clean.max())
    if best > 0:
        plateau_share = float((clean >= max(0.0, best * 0.50)).mean())
    else:
        plateau_share = 0.0

    score = (positive_share * 45.0) + (_clip((median + 0.10) / 0.25) * 30.0) + (plateau_share * 25.0)
    score = max(0.0, min(100.0, score))

    if score >= 70:
        label = "Stable plateau"
    elif score >= 45:
        label = "Mixed surface"
    else:
        label = "Fragile surface"

    return {"label": label, "score": score, "positive_share": positive_share, "median": median, "best": best}


def _wf_stability_score(wf_df: pd.DataFrame) -> dict[str, Any]:
    """
    Walk-forward stability score V2.
    Compatible avec l'ancien format et le nouveau format numérique V2.
    """
    if wf_df.empty:
        return {
            "label": "N/A",
            "score": np.nan,
            "positive_share": np.nan,
            "median_alpha": np.nan,
            "pass_share": np.nan,
        }

    def _series_num(col: str) -> pd.Series:
        if col not in wf_df.columns:
            return pd.Series(dtype=float)

        s = wf_df[col]

        if s.dtype == object:
            return s.map(_parse_pct_text).replace([np.inf, -np.inf], np.nan).dropna()

        return pd.to_numeric(s, errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()

    returns = _series_num("Return")
    alphas = _series_num("Alpha")
    sharpes = _series_num("Sharpe")
    drawdowns = _series_num("Max DD")

    if returns.empty:
        return {
            "label": "N/A",
            "score": np.nan,
            "positive_share": np.nan,
            "median_alpha": np.nan,
            "pass_share": np.nan,
        }

    positive_share = float((returns > 0).mean())
    alpha_positive_share = float((alphas > 0).mean()) if not alphas.empty else 0.0
    median_alpha = float(alphas.median()) if not alphas.empty else 0.0
    sharpe_positive_share = float((sharpes > 0).mean()) if not sharpes.empty else 0.0
    dd_ok_share = float((drawdowns > -0.25).mean()) if not drawdowns.empty else 0.0

    if "WF Status" in wf_df.columns:
        pass_share = float((wf_df["WF Status"].astype(str) == "PASS").mean())
        mixed_share = float((wf_df["WF Status"].astype(str) == "MIXED").mean())
    else:
        pass_share = 0.0
        mixed_share = 0.0

    score = (
        positive_share * 25.0
        + alpha_positive_share * 25.0
        + sharpe_positive_share * 20.0
        + dd_ok_share * 15.0
        + pass_share * 15.0
        + mixed_share * 5.0
    )

    score = max(0.0, min(100.0, score))

    if score >= 70:
        label = "Stable WF"
    elif score >= 45:
        label = "Mixed WF"
    else:
        label = "Weak WF"

    return {
        "label": label,
        "score": score,
        "positive_share": positive_share,
        "alpha_positive_share": alpha_positive_share,
        "median_alpha": median_alpha,
        "sharpe_positive_share": sharpe_positive_share,
        "dd_ok_share": dd_ok_share,
        "pass_share": pass_share,
    }



# ============================================================
# WALK-FORWARD / OOS VALIDATION V2
# ============================================================

def _oos_validation_v2_pack(bt: pd.DataFrame, wf_df: pd.DataFrame | None = None) -> dict[str, Any]:
    """
    Walk-Forward / OOS Validation V2.

    Lecture seule :
    - ne modifie pas le moteur ;
    - ne modifie pas les signaux ;
    - ne modifie pas l'equity curve ;
    - ne modifie pas les trades ;
    - ne modifie pas le verdict principal.

    Objectif :
    - mesurer la dégradation In-Sample -> Out-of-Sample ;
    - produire un score OOS ;
    - identifier les failure drivers ;
    - fournir une matrice exportable.
    """
    if bt is None or bt.empty or len(bt) < 120:
        return {
            "level": "Unavailable",
            "score": np.nan,
            "read": "Historique insuffisant pour OOS V2.",
            "cards": [],
            "summary": pd.DataFrame(),
            "periods": pd.DataFrame(),
            "windows": pd.DataFrame(),
            "gate": pd.DataFrame(),
            "drivers": [],
        }

    split = int(len(bt) * 0.60)

    is_part = bt.iloc[:split].copy()
    oos_part = bt.iloc[split:].copy()

    is_m = _compute_metrics(is_part)
    oos_m = _compute_metrics(oos_part)
    full_m = _compute_metrics(bt)

    def _mget(m: dict[str, Any], key: str) -> float:
        return _safe_float(m.get(key), np.nan)

    is_return = _mget(is_m, "Total Return")
    oos_return = _mget(oos_m, "Total Return")

    is_cagr = _mget(is_m, "CAGR")
    oos_cagr = _mget(oos_m, "CAGR")

    is_alpha = _mget(is_m, "Relative Alpha")
    oos_alpha = _mget(oos_m, "Relative Alpha")

    is_sharpe = _mget(is_m, "Sharpe")
    oos_sharpe = _mget(oos_m, "Sharpe")

    is_dd = _mget(is_m, "Max Drawdown")
    oos_dd = _mget(oos_m, "Max Drawdown")

    is_cvar = _mget(is_m, "CVaR 95")
    oos_cvar = _mget(oos_m, "CVaR 95")

    return_degradation = oos_return - is_return if pd.notna(oos_return) and pd.notna(is_return) else np.nan
    cagr_degradation = oos_cagr - is_cagr if pd.notna(oos_cagr) and pd.notna(is_cagr) else np.nan
    alpha_degradation = oos_alpha - is_alpha if pd.notna(oos_alpha) and pd.notna(is_alpha) else np.nan
    sharpe_degradation = oos_sharpe - is_sharpe if pd.notna(oos_sharpe) and pd.notna(is_sharpe) else np.nan
    dd_degradation = oos_dd - is_dd if pd.notna(oos_dd) and pd.notna(is_dd) else np.nan

    pass_oos_return = bool(pd.notna(oos_return) and oos_return > 0)
    pass_oos_alpha = bool(pd.notna(oos_alpha) and oos_alpha > 0)
    pass_oos_sharpe = bool(pd.notna(oos_sharpe) and oos_sharpe > 0)
    pass_oos_dd = bool(pd.notna(oos_dd) and oos_dd > -0.25)

    if pd.notna(is_sharpe) and is_sharpe > 0.25 and pd.notna(oos_sharpe):
        pass_sharpe_decay = bool(oos_sharpe >= is_sharpe * 0.50)
    else:
        pass_sharpe_decay = bool(pd.notna(oos_sharpe) and oos_sharpe > -0.25)

    if pd.notna(is_alpha) and is_alpha > 0.05 and pd.notna(oos_alpha):
        pass_alpha_decay = bool(oos_alpha >= is_alpha * 0.25)
    else:
        pass_alpha_decay = bool(pd.notna(oos_alpha) and oos_alpha > -0.10)

    gate_rows = [
        ["OOS return > 0", pass_oos_return, _format_pct(oos_return), "La période hors-échantillon doit produire un rendement positif."],
        ["OOS alpha > 0", pass_oos_alpha, _format_pct(oos_alpha), "La stratégie doit battre son benchmark en OOS."],
        ["OOS Sharpe > 0", pass_oos_sharpe, _format_num(oos_sharpe), "Le Sharpe OOS doit rester positif."],
        ["OOS max DD > -25%", pass_oos_dd, _format_pct(oos_dd), "Le drawdown OOS ne doit pas être excessif."],
        ["Sharpe decay acceptable", pass_sharpe_decay, _format_num(sharpe_degradation), "La dégradation du Sharpe ne doit pas signaler un overfit évident."],
        ["Alpha decay acceptable", pass_alpha_decay, _format_pct(alpha_degradation), "La dégradation de l'alpha ne doit pas être trop brutale."],
    ]

    gate = pd.DataFrame(gate_rows, columns=["Gate", "Pass", "Value", "Read"])

    pass_count = int(gate["Pass"].astype(bool).sum())
    pass_share = pass_count / max(len(gate), 1)

    wf_score_pack = _wf_stability_score(wf_df if isinstance(wf_df, pd.DataFrame) else pd.DataFrame())
    wf_score = _safe_float(wf_score_pack.get("score"), 50.0)

    oos_score = (
        pass_share * 55.0
        + _clip((oos_alpha + 0.10) / 0.30) * 20.0
        + _clip((oos_sharpe + 0.50) / 2.00) * 15.0
        + _clip((oos_dd + 0.35) / 0.35) * 10.0
    )

    oos_score = 0.70 * oos_score + 0.30 * wf_score
    oos_score = max(0.0, min(100.0, oos_score))

    drivers = []

    if not pass_oos_return:
        drivers.append("negative OOS return")
    if not pass_oos_alpha:
        drivers.append("negative OOS alpha")
    if not pass_oos_sharpe:
        drivers.append("negative OOS Sharpe")
    if not pass_oos_dd:
        drivers.append("large OOS drawdown")
    if not pass_sharpe_decay:
        drivers.append("Sharpe decay")
    if not pass_alpha_decay:
        drivers.append("alpha decay")

    if oos_score >= 70 and pass_share >= 0.67:
        level = "OOS robust"
        read = "La stratégie survit correctement au découpage hors-échantillon."
    elif oos_score >= 45:
        level = "OOS mixed"
        read = "La validation hors-échantillon est mitigée : certaines métriques passent, mais la robustesse reste fragile."
    else:
        level = "OOS failed"
        read = "La stratégie échoue la validation hors-échantillon. Risque élevé d'overfit ou de régime non robuste."

    periods = pd.DataFrame(
        [
            {
                "Period": "In-sample 60%",
                "Start": _format_dt(is_part.index[0]),
                "End": _format_dt(is_part.index[-1]),
                "Obs": int(len(is_part)),
                "Return": is_return,
                "CAGR": is_cagr,
                "Benchmark": _mget(is_m, "Benchmark Return"),
                "Alpha": is_alpha,
                "Sharpe": is_sharpe,
                "Sortino": _mget(is_m, "Sortino"),
                "Max DD": is_dd,
                "CVaR 95": is_cvar,
                "Exposure": _mget(is_m, "Exposure"),
            },
            {
                "Period": "Out-of-sample 40%",
                "Start": _format_dt(oos_part.index[0]),
                "End": _format_dt(oos_part.index[-1]),
                "Obs": int(len(oos_part)),
                "Return": oos_return,
                "CAGR": oos_cagr,
                "Benchmark": _mget(oos_m, "Benchmark Return"),
                "Alpha": oos_alpha,
                "Sharpe": oos_sharpe,
                "Sortino": _mget(oos_m, "Sortino"),
                "Max DD": oos_dd,
                "CVaR 95": oos_cvar,
                "Exposure": _mget(oos_m, "Exposure"),
            },
            {
                "Period": "Full",
                "Start": _format_dt(bt.index[0]),
                "End": _format_dt(bt.index[-1]),
                "Obs": int(len(bt)),
                "Return": _mget(full_m, "Total Return"),
                "CAGR": _mget(full_m, "CAGR"),
                "Benchmark": _mget(full_m, "Benchmark Return"),
                "Alpha": _mget(full_m, "Relative Alpha"),
                "Sharpe": _mget(full_m, "Sharpe"),
                "Sortino": _mget(full_m, "Sortino"),
                "Max DD": _mget(full_m, "Max Drawdown"),
                "CVaR 95": _mget(full_m, "CVaR 95"),
                "Exposure": _mget(full_m, "Exposure"),
            },
        ]
    )

    windows = wf_df.copy() if isinstance(wf_df, pd.DataFrame) else pd.DataFrame()

    summary = pd.DataFrame(
        [
            ["OOS level", level, "Lecture synthétique de la validation hors-échantillon."],
            ["OOS score", f"{_format_num(oos_score, 0)}/100", "Score combinant gates OOS et stabilité walk-forward."],
            ["OOS gate pass", f"{pass_count}/{len(gate)}", "Nombre de critères hors-échantillon validés."],
            ["IS return", _format_pct(is_return), "Rendement in-sample."],
            ["OOS return", _format_pct(oos_return), "Rendement out-of-sample."],
            ["Return degradation", _format_pct(return_degradation), "OOS return moins IS return."],
            ["IS alpha", _format_pct(is_alpha), "Alpha in-sample vs benchmark."],
            ["OOS alpha", _format_pct(oos_alpha), "Alpha out-of-sample vs benchmark."],
            ["Alpha degradation", _format_pct(alpha_degradation), "OOS alpha moins IS alpha."],
            ["IS Sharpe", _format_num(is_sharpe), "Sharpe in-sample."],
            ["OOS Sharpe", _format_num(oos_sharpe), "Sharpe out-of-sample."],
            ["Sharpe degradation", _format_num(sharpe_degradation), "OOS Sharpe moins IS Sharpe."],
            ["IS max DD", _format_pct(is_dd), "Drawdown maximum in-sample."],
            ["OOS max DD", _format_pct(oos_dd), "Drawdown maximum out-of-sample."],
            ["DD degradation", _format_pct(dd_degradation), "OOS max DD moins IS max DD."],
            ["Failure drivers", "; ".join(drivers) if drivers else "None", "Raisons principales du rejet OOS."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    cards = [
        {"label": "OOS level", "value": level, "delta": "validation v2"},
        {"label": "OOS score", "value": f"{_format_num(oos_score, 0)}/100", "delta": f"{pass_count}/{len(gate)} gates"},
        {"label": "OOS return", "value": _format_pct(oos_return), "delta": "test period"},
        {"label": "OOS alpha", "value": _format_pct(oos_alpha), "delta": "vs benchmark"},
        {"label": "OOS Sharpe", "value": _format_num(oos_sharpe), "delta": "test period"},
        {"label": "OOS max DD", "value": _format_pct(oos_dd), "delta": "risk"},
    ]

    return {
        "level": level,
        "score": oos_score,
        "read": read,
        "cards": cards,
        "summary": summary,
        "periods": periods,
        "windows": windows,
        "gate": gate,
        "drivers": drivers,
        "pass_share": pass_share,
    }


def _render_oos_validation_v2(bt: pd.DataFrame, wf_df: pd.DataFrame) -> dict[str, Any]:
    """
    Rendu Streamlit Walk-Forward / OOS Validation V2.
    """
    pack = _oos_validation_v2_pack(bt, wf_df)

    st.subheader("Walk-Forward / OOS Validation V2")
    st.caption(
        "Validation hors-échantillon lecture seule : split IS/OOS, dégradation IS→OOS, "
        "gates pass/fail, stabilité par fenêtres et failure drivers. "
        "Ne modifie ni le moteur, ni l'equity curve, ni le verdict."
    )

    _card_grid(pack.get("cards", []), columns=6)

    level = str(pack.get("level", ""))

    if "failed" in level.lower():
        st.warning(f"Lecture OOS : {pack.get('read', '')}")
    elif "mixed" in level.lower():
        st.info(f"Lecture OOS : {pack.get('read', '')}")
    else:
        st.success(f"Lecture OOS : {pack.get('read', '')}")

    summary = pack.get("summary", pd.DataFrame())
    periods = pack.get("periods", pd.DataFrame())
    gate = pack.get("gate", pd.DataFrame())
    windows = pack.get("windows", pd.DataFrame())

    if isinstance(summary, pd.DataFrame) and not summary.empty:
        with st.expander("OOS V2 summary", expanded=True):
            st.dataframe(summary, use_container_width=True, hide_index=True)

    if isinstance(gate, pd.DataFrame) and not gate.empty:
        gate_display = gate.copy()
        if "Pass" in gate_display.columns:
            gate_display["Pass"] = gate_display["Pass"].map(lambda x: "PASS" if bool(x) else "FAIL")

        with st.expander("OOS pass/fail gates", expanded=True):
            st.dataframe(gate_display, use_container_width=True, hide_index=True)

    if isinstance(periods, pd.DataFrame) and not periods.empty:
        period_display = periods.copy()

        for col in ["Return", "CAGR", "Benchmark", "Alpha", "Max DD", "CVaR 95", "Exposure"]:
            if col in period_display.columns:
                period_display[col] = period_display[col].map(_format_pct)

        for col in ["Sharpe", "Sortino"]:
            if col in period_display.columns:
                period_display[col] = period_display[col].map(_format_num)

        with st.expander("IS / OOS period matrix", expanded=True):
            st.dataframe(period_display, use_container_width=True, hide_index=True)

    if isinstance(windows, pd.DataFrame) and not windows.empty:
        window_display = windows.copy()

        for col in ["Return", "CAGR", "Benchmark", "Alpha", "Max DD", "VaR 95", "CVaR 95", "Exposure"]:
            if col in window_display.columns:
                if pd.api.types.is_numeric_dtype(window_display[col]):
                    window_display[col] = window_display[col].map(_format_pct)

        for col in ["Sharpe", "Sortino"]:
            if col in window_display.columns:
                if pd.api.types.is_numeric_dtype(window_display[col]):
                    window_display[col] = window_display[col].map(_format_num)

        for col in ["Pass Return", "Pass Alpha", "Pass Sharpe", "Pass DD"]:
            if col in window_display.columns:
                window_display[col] = window_display[col].map(lambda x: "Yes" if bool(x) else "No")

        with st.expander("Walk-forward window stability map", expanded=True):
            st.dataframe(window_display, use_container_width=True, hide_index=True)

    return pack



def _pbo_proxy(param_diag: dict[str, Any], wf_diag: dict[str, Any], comparison: pd.DataFrame) -> float:
    # Proxy prudent : plus la surface de paramètres et le walk-forward sont faibles,
    # plus le risque d'overfit est élevé. Ce n'est pas un CSCV complet.
    param_score = _safe_float(param_diag.get("score"), 50.0)
    wf_score = _safe_float(wf_diag.get("score"), 50.0)

    comp_penalty = 0.0
    if not comparison.empty and "Verdict" in comparison.columns:
        rejected_share = float((comparison["Verdict"] == "REJECTED").mean())
        comp_penalty = rejected_share * 15.0

    stability = max(0.0, min(100.0, (param_score * 0.45 + wf_score * 0.45 + (100.0 - comp_penalty) * 0.10)))
    return _clip(1.0 - stability / 100.0)


def _strategy_comparison(df: pd.DataFrame, cfg: BacktestConfig) -> pd.DataFrame:
    """
    Strategy Tournament V2 / Comparison Lab.

    Lecture seule :
    - compare plusieurs stratégies sur la même fenêtre de prix ;
    - conserve les paramètres courants de frais, slippage, benchmark, sizing ;
    - teste Engine only et, si activé dans l'interface, Risk Layer ON ;
    - ne modifie pas le backtest principal, l'equity curve, les trades ou le verdict.
    """
    strategies = [
        "SMA Trend",
        "Breakout",
        "RSI Mean Reversion",
        "Volatility Filter Trend",
        "Decision Proxy",
        "Manual Builder",
    ]

    if getattr(cfg, "custom_signal_df", None) is not None:
        strategies.append("Custom Signal Import")

    risk_layer_currently_enabled = bool(getattr(cfg, "risk_layer_enabled", False))

    run_plan: list[tuple[str, str, bool]] = []

    for strategy in strategies:
        run_plan.append((strategy, "Engine only", False))

        if risk_layer_currently_enabled:
            run_plan.append((strategy, "Risk Layer ON", True))

    def _score_strategy(m: dict[str, Any], integrity: int) -> float:
        total_return = _safe_float(m.get("Total Return"), 0.0)
        alpha = _safe_float(m.get("Relative Alpha"), 0.0)
        sharpe = _safe_float(m.get("Sharpe"), np.nan)
        sortino = _safe_float(m.get("Sortino"), np.nan)
        calmar = _safe_float(m.get("Calmar"), np.nan)
        max_dd = _safe_float(m.get("Max Drawdown"), 0.0)
        cvar95 = _safe_float(m.get("CVaR 95"), np.nan)
        profit_factor = _safe_float(m.get("Profit Factor"), np.nan)
        exposure = _safe_float(m.get("Exposure"), 0.0)
        trades = int(m.get("Trades", 0) or 0)
        cost_paid = _safe_float(m.get("Cost Paid $"), 0.0)

        capital = max(float(getattr(cfg, "capital", 1.0)), 1.0)
        cost_pct = cost_paid / capital

        return_score = _clip((total_return + 0.10) / 0.50) * 100.0
        alpha_score = _clip((alpha + 0.10) / 0.35) * 100.0
        sharpe_score = _clip((sharpe + 0.50) / 2.00) * 100.0 if pd.notna(sharpe) else 0.0
        sortino_score = _clip((sortino + 0.50) / 2.50) * 100.0 if pd.notna(sortino) else 0.0
        calmar_score = _clip((calmar + 0.50) / 2.50) * 100.0 if pd.notna(calmar) else 0.0

        # max_dd est négatif. -45% => 0, 0% => 100.
        drawdown_score = _clip((max_dd + 0.45) / 0.45) * 100.0

        # cvar95 est négatif. -8% ou pire => 0, 0% => 100.
        cvar_score = _clip((cvar95 + 0.08) / 0.08) * 100.0 if pd.notna(cvar95) else 35.0

        profit_factor_score = _clip((profit_factor - 0.80) / 1.40) * 100.0 if pd.notna(profit_factor) else 35.0

        cost_score = _clip(1.0 - cost_pct / 0.05) * 100.0

        if exposure < 0.05:
            exposure_score = 35.0
        elif exposure > 0.98:
            exposure_score = 75.0
        else:
            exposure_score = 100.0

        trade_score = _clip(trades / 30.0) * 100.0

        score = (
            return_score * 0.10
            + alpha_score * 0.18
            + sharpe_score * 0.14
            + sortino_score * 0.10
            + calmar_score * 0.09
            + drawdown_score * 0.13
            + cvar_score * 0.09
            + profit_factor_score * 0.06
            + float(integrity) * 0.07
            + cost_score * 0.02
            + exposure_score * 0.01
            + trade_score * 0.01
        )

        if trades < 3:
            score = min(score, 45.0)

        if total_return <= 0 and alpha <= 0:
            score = min(score, 42.0)

        return max(0.0, min(100.0, float(score)))

    def _failure_drivers(m: dict[str, Any], integrity: int) -> str:
        total_return = _safe_float(m.get("Total Return"), 0.0)
        alpha = _safe_float(m.get("Relative Alpha"), 0.0)
        sharpe = _safe_float(m.get("Sharpe"), np.nan)
        sortino = _safe_float(m.get("Sortino"), np.nan)
        max_dd = _safe_float(m.get("Max Drawdown"), 0.0)
        cvar95 = _safe_float(m.get("CVaR 95"), np.nan)
        exposure = _safe_float(m.get("Exposure"), 0.0)
        trades = int(m.get("Trades", 0) or 0)
        risk_exits = int(m.get("Risk Exits", 0) or 0)

        issues = []

        if total_return <= 0:
            issues.append("negative return")
        if alpha < -0.05:
            issues.append("negative alpha")
        if pd.notna(sharpe) and sharpe < 0.30:
            issues.append("weak Sharpe")
        if pd.notna(sortino) and sortino < 0.50:
            issues.append("weak Sortino")
        if max_dd < -0.25:
            issues.append("high drawdown")
        if pd.notna(cvar95) and cvar95 < -0.03:
            issues.append("large CVaR")
        if trades < 5:
            issues.append("low trade sample")
        if exposure < 0.05:
            issues.append("low exposure")
        if exposure > 0.98:
            issues.append("quasi buy-and-hold")
        if integrity < 70:
            issues.append("integrity below 70")
        if bool(m.get("Benchmark Fallback", False)):
            issues.append("benchmark fallback")
        if risk_exits > 0:
            issues.append(f"{risk_exits} risk exits")

        return "; ".join(issues) if issues else "No major failure driver"

    def _research_bucket(score: float, m: dict[str, Any], verdict: str, integrity: int) -> str:
        alpha = _safe_float(m.get("Relative Alpha"), 0.0)
        sharpe = _safe_float(m.get("Sharpe"), np.nan)
        max_dd = _safe_float(m.get("Max Drawdown"), 0.0)
        trades = int(m.get("Trades", 0) or 0)

        if verdict == "REJECTED" or score < 40:
            return "Rejected"
        if trades < 5:
            return "Low sample"
        if score >= 75 and alpha > 0 and pd.notna(sharpe) and sharpe >= 1.0 and max_dd > -0.25 and integrity >= 75:
            return "Research candidate"
        if score >= 55:
            return "Watchlist"
        return "Fragile"

    rows = []

    for strategy, variant, risk_on in run_plan:
        try:
            test_cfg = BacktestConfig(
                **{
                    **cfg.__dict__,
                    "strategy": strategy,
                    "risk_layer_enabled": bool(risk_on),
                }
            )

            res = _run_backtest(df, test_cfg)

            if "metrics" not in res or "data" not in res:
                continue

            m = res["metrics"]
            integrity, notes = _integrity_score(m, res["data"], test_cfg)
            verdict, _, _ = _verdict(m, integrity, notes)

            score = _score_strategy(m, integrity)
            bucket = _research_bucket(score, m, verdict, integrity)

            is_current = (
                strategy == str(getattr(cfg, "strategy", ""))
                and bool(risk_on) == bool(getattr(cfg, "risk_layer_enabled", False))
            )

            rows.append(
                {
                    "Strategy": strategy,
                    "Execution Variant": variant,
                    "Current Config": "Yes" if is_current else "No",
                    "Tournament Score": score,
                    "Research Bucket": bucket,
                    "Verdict": verdict,

                    "Return": m.get("Total Return", np.nan),
                    "Benchmark": m.get("Benchmark Return", np.nan),
                    "Alpha": m.get("Relative Alpha", np.nan),
                    "CAGR": m.get("CAGR", np.nan),
                    "Sharpe": m.get("Sharpe", np.nan),
                    "Sortino": m.get("Sortino", np.nan),
                    "Calmar": m.get("Calmar", np.nan),
                    "Max DD": m.get("Max Drawdown", np.nan),
                    "VaR 95": m.get("VaR 95", np.nan),
                    "CVaR 95": m.get("CVaR 95", np.nan),
                    "Profit Factor": m.get("Profit Factor", np.nan),
                    "Exposure": m.get("Exposure", np.nan),
                    "Turnover": m.get("Turnover", np.nan),
                    "Trades": int(m.get("Trades", 0) or 0),
                    "Risk Exits": int(m.get("Risk Exits", 0) or 0),
                    "Cost Drag": m.get("Cost Drag", np.nan),
                    "Cost Paid $": m.get("Cost Paid $", np.nan),
                    "Test Integrity": integrity,
                    "Failure Drivers": _failure_drivers(m, integrity),
                }
            )

        except Exception as exc:
            rows.append(
                {
                    "Strategy": strategy,
                    "Execution Variant": variant,
                    "Current Config": "No",
                    "Tournament Score": 0.0,
                    "Research Bucket": "Error",
                    "Verdict": "ERROR",
                    "Failure Drivers": f"tournament run error: {exc}",
                }
            )

    out = pd.DataFrame(rows)

    if out.empty:
        return out

    out = out.sort_values(
        ["Tournament Score", "Alpha", "Sharpe"],
        ascending=[False, False, False],
    ).reset_index(drop=True)

    out.insert(0, "Rank", np.arange(1, len(out) + 1))

    display = out.copy()

    for col in [
        "Return",
        "Benchmark",
        "Alpha",
        "CAGR",
        "Max DD",
        "VaR 95",
        "CVaR 95",
        "Exposure",
        "Cost Drag",
    ]:
        if col in display.columns:
            display[col] = display[col].map(_format_pct)

    for col in [
        "Sharpe",
        "Sortino",
        "Calmar",
        "Profit Factor",
        "Turnover",
    ]:
        if col in display.columns:
            display[col] = display[col].map(_format_num)

    if "Tournament Score" in display.columns:
        display["Tournament Score"] = display["Tournament Score"].map(lambda x: _format_num(x, 0))

    if "Test Integrity" in display.columns:
        display["Test Integrity"] = display["Test Integrity"].map(lambda x: f"{int(_safe_float(x, 0))}/100")

    if "Cost Paid $" in display.columns:
        display["Cost Paid $"] = display["Cost Paid $"].map(_format_money)

    return display


# ============================================================
# OVERFIT / MULTIPLE TESTING LAB V1
# ============================================================

def _research_degrees_of_freedom_v1(
    cfg: BacktestConfig,
    sens_matrix: pd.DataFrame,
    cost_matrix: pd.DataFrame,
    comp_df: pd.DataFrame,
) -> pd.DataFrame:
    """
    Proxy des degrés de liberté de recherche.

    Lecture seule :
    - ne modifie pas le moteur ;
    - ne modifie pas le verdict ;
    - sert à estimer combien de choix implicites peuvent créer de l'overfit.
    """
    rows = []

    strategy_families = 6
    if getattr(cfg, "custom_signal_df", None) is not None:
        strategy_families += 1

    rows.append(
        {
            "Source": "Strategy families",
            "Count": strategy_families,
            "Read": "Nombre de familles de stratégies disponibles dans le Lab.",
        }
    )

    param_cells = 0
    if isinstance(sens_matrix, pd.DataFrame) and not sens_matrix.empty:
        param_cells = int(sens_matrix.stack().replace([np.inf, -np.inf], np.nan).dropna().shape[0])

    rows.append(
        {
            "Source": "Parameter grid cells",
            "Count": param_cells,
            "Read": "Nombre de combinaisons testées dans la surface de paramètres.",
        }
    )

    cost_cells = 0
    if isinstance(cost_matrix, pd.DataFrame) and not cost_matrix.empty:
        cost_cells = int(cost_matrix.stack().replace([np.inf, -np.inf], np.nan).dropna().shape[0])

    rows.append(
        {
            "Source": "Cost stress cells",
            "Count": cost_cells,
            "Read": "Nombre de scénarios frais/slippage testés.",
        }
    )

    tournament_rows = int(len(comp_df)) if isinstance(comp_df, pd.DataFrame) and not comp_df.empty else 0

    rows.append(
        {
            "Source": "Tournament configurations",
            "Count": tournament_rows,
            "Read": "Nombre de stratégies / variantes comparées dans Strategy Tournament.",
        }
    )

    risk_choices = 0
    if bool(getattr(cfg, "risk_layer_enabled", False)):
        risk_choices += 1
    if bool(getattr(cfg, "risk_use_stop_loss", False)):
        risk_choices += 1
    if bool(getattr(cfg, "risk_use_take_profit", False)):
        risk_choices += 1
    if bool(getattr(cfg, "risk_use_trailing_stop", False)):
        risk_choices += 1
    if bool(getattr(cfg, "risk_use_max_holding", False)):
        risk_choices += 1
    if bool(getattr(cfg, "risk_use_ohlc_execution", False)):
        risk_choices += 1

    rows.append(
        {
            "Source": "Risk layer choices",
            "Count": risk_choices,
            "Read": "Nombre de choix actifs dans le Risk Layer.",
        }
    )

    sizing_choices = 1
    sizing_mode = str(getattr(cfg, "sizing_mode", "Fixed Exposure"))

    if sizing_mode != "Fixed Exposure":
        sizing_choices += 1
    if bool(getattr(cfg, "sizing_use_trade_risk_budget", False)):
        sizing_choices += 1
    if bool(getattr(cfg, "sizing_use_drawdown_cut", False)):
        sizing_choices += 1

    rows.append(
        {
            "Source": "Sizing choices",
            "Count": sizing_choices,
            "Read": "Nombre de choix actifs dans Position Sizing.",
        }
    )

    margin_choices = 1 if bool(getattr(cfg, "margin_stress_enabled", False)) else 0

    rows.append(
        {
            "Source": "Margin stress choices",
            "Count": margin_choices,
            "Read": "Choix actifs dans le stress de levier/marge.",
        }
    )

    out = pd.DataFrame(rows)
    out["Count"] = pd.to_numeric(out["Count"], errors="coerce").fillna(0).astype(int)

    return out


def _overfit_multiple_testing_lab_v1_pack(
    bt: pd.DataFrame,
    metrics: dict[str, Any],
    cfg: BacktestConfig,
    sens_matrix: pd.DataFrame,
    wf_df: pd.DataFrame,
    comp_df: pd.DataFrame,
    cost_matrix: pd.DataFrame,
    psr: float | None = None,
    dsr: float | None = None,
    pbo: float | None = None,
    trials: int | None = None,
    param_diag: dict[str, Any] | None = None,
    wf_diag: dict[str, Any] | None = None,
    oos_pack: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """
    Overfit / Multiple Testing Lab V1.

    Lecture seule :
    - ne modifie pas le moteur ;
    - ne modifie pas les trades ;
    - ne modifie pas l'equity curve ;
    - ne modifie pas le verdict principal.

    Objectif :
    consolider PSR, DSR, PBO, surface de paramètres, walk-forward,
    OOS et tournament rejection pour mesurer le risque d'overfit.
    """
    if bt is None or not isinstance(bt, pd.DataFrame) or bt.empty:
        return {
            "level": "Unavailable",
            "score": np.nan,
            "risk_score": np.nan,
            "read": "Backtest indisponible.",
            "cards": [],
            "summary": pd.DataFrame(),
            "gates": pd.DataFrame(),
            "degrees_of_freedom": pd.DataFrame(),
            "failure_drivers": pd.DataFrame(),
        }

    param_diag = param_diag if isinstance(param_diag, dict) else _parameter_stability_score(sens_matrix)
    wf_diag = wf_diag if isinstance(wf_diag, dict) else _wf_stability_score(wf_df)
    oos_pack = oos_pack if isinstance(oos_pack, dict) else _oos_validation_v2_pack(bt, wf_df)

    if psr is None or pd.isna(psr):
        psr_pack = _probabilistic_sharpe(bt, benchmark_sr=0.0)
        psr = psr_pack.get("psr", np.nan)

    if trials is None:
        trials = 5
        if isinstance(sens_matrix, pd.DataFrame) and not sens_matrix.empty:
            trials += int(sens_matrix.stack().replace([np.inf, -np.inf], np.nan).dropna().shape[0])
        if isinstance(comp_df, pd.DataFrame) and not comp_df.empty:
            trials += int(len(comp_df))

    if dsr is None or pd.isna(dsr):
        dsr = _deflated_sharpe_proxy(psr, int(trials or 1))

    if pbo is None or pd.isna(pbo):
        pbo = _pbo_proxy(param_diag, wf_diag, comp_df)

    dof = _research_degrees_of_freedom_v1(cfg, sens_matrix, cost_matrix, comp_df)
    research_dof = int(pd.to_numeric(dof["Count"], errors="coerce").fillna(0).sum()) if not dof.empty else 0

    sample_days = int(len(bt))
    mtr_days = _minimum_track_record_days(bt)

    param_score = _safe_float(param_diag.get("score"), np.nan)
    wf_score = _safe_float(wf_diag.get("score"), np.nan)
    oos_score = _safe_float(oos_pack.get("score"), np.nan)

    tournament_rejected_share = np.nan
    tournament_rows = int(len(comp_df)) if isinstance(comp_df, pd.DataFrame) else 0

    if isinstance(comp_df, pd.DataFrame) and not comp_df.empty and "Verdict" in comp_df.columns:
        tournament_rejected_share = float((comp_df["Verdict"].astype(str).str.upper() == "REJECTED").mean())

    sensitivity_clean = pd.Series(dtype=float)
    if isinstance(sens_matrix, pd.DataFrame) and not sens_matrix.empty:
        sensitivity_clean = (
            sens_matrix.stack()
            .replace([np.inf, -np.inf], np.nan)
            .dropna()
            .astype(float)
        )

    positive_param_share = float((sensitivity_clean > 0).mean()) if not sensitivity_clean.empty else np.nan
    best_param = float(sensitivity_clean.max()) if not sensitivity_clean.empty else np.nan
    median_param = float(sensitivity_clean.median()) if not sensitivity_clean.empty else np.nan

    if pd.notna(best_param) and best_param > 0:
        near_best_share = float((sensitivity_clean >= best_param * 0.50).mean())
    else:
        near_best_share = np.nan

    pass_psr = bool(pd.notna(psr) and psr >= 0.60)
    pass_dsr = bool(pd.notna(dsr) and dsr >= 0.35)
    pass_pbo = bool(pd.notna(pbo) and pbo <= 0.50)
    pass_param = bool(pd.notna(param_score) and param_score >= 45.0)
    pass_wf = bool(pd.notna(wf_score) and wf_score >= 45.0)
    pass_oos = bool(pd.notna(oos_score) and oos_score >= 45.0)

    if pd.isna(mtr_days) or mtr_days == np.inf:
        pass_mtr = False
        mtr_value = "Infinite / unavailable"
    else:
        pass_mtr = bool(mtr_days <= sample_days * 1.50)
        mtr_value = _format_num(mtr_days, 0)

    pass_tournament = bool(
        pd.isna(tournament_rejected_share)
        or tournament_rejected_share <= 0.75
    )

    gates = pd.DataFrame(
        [
            ["PSR >= 60%", pass_psr, _format_pct(psr), "Probabilité approximative que le Sharpe réel soit supérieur à 0."],
            ["DSR >= 35%", pass_dsr, _format_pct(dsr), "PSR pénalisé par les essais multiples."],
            ["PBO <= 50%", pass_pbo, _format_pct(pbo), "Proxy de probabilité d'overfit."],
            ["Parameter stability >= 45", pass_param, f"{_format_num(param_score, 0)}/100", "La surface de paramètres ne doit pas être trop fragile."],
            ["Walk-forward stability >= 45", pass_wf, f"{_format_num(wf_score, 0)}/100", "La stratégie doit survivre aux fenêtres out-of-time."],
            ["OOS score >= 45", pass_oos, f"{_format_num(oos_score, 0)}/100", "La stratégie doit survivre au split hors-échantillon."],
            ["MTR feasible", pass_mtr, mtr_value, "Le track record requis ne doit pas dépasser excessivement l'échantillon."],
            ["Tournament rejection <= 75%", pass_tournament, _format_pct(tournament_rejected_share), "Le tournoi ne doit pas rejeter presque toutes les variantes."],
        ],
        columns=["Gate", "Pass", "Value", "Read"],
    )

    pass_count = int(gates["Pass"].astype(bool).sum())
    pass_share = pass_count / max(len(gates), 1)

    drivers = []

    if not pass_psr:
        drivers.append("weak PSR")
    if not pass_dsr:
        drivers.append("weak DSR after multiple-testing penalty")
    if not pass_pbo:
        drivers.append("high PBO proxy")
    if not pass_param:
        drivers.append("fragile parameter surface")
    if not pass_wf:
        drivers.append("weak walk-forward stability")
    if not pass_oos:
        drivers.append("weak OOS validation")
    if not pass_mtr:
        drivers.append("minimum track record not feasible")
    if not pass_tournament:
        drivers.append("high tournament rejection share")

    dof_penalty = _clip(research_dof / 80.0) * 20.0
    trial_penalty = _clip(np.log1p(max(int(trials or 1), 1)) / 5.0) * 15.0

    robustness_score = (
        pass_share * 45.0
        + _safe_float(dsr, 0.0) * 20.0
        + (1.0 - _safe_float(pbo, 1.0)) * 15.0
        + _safe_float(param_score, 0.0) * 0.10
        + _safe_float(oos_score, 0.0) * 0.10
        - dof_penalty
        - trial_penalty
    )

    robustness_score = max(0.0, min(100.0, robustness_score))
    overfit_risk_score = 100.0 - robustness_score

    if overfit_risk_score >= 70:
        level = "High overfit risk"
        read = "Le profil est fragile : pénalité essais multiples, OOS/WF ou surface de paramètres insuffisante."
    elif overfit_risk_score >= 45:
        level = "Moderate overfit risk"
        read = "Le profil est mitigé : certaines validations passent, mais le risque de data-mining reste visible."
    else:
        level = "Contained overfit risk"
        read = "Le risque d'overfit est contenu selon les proxys disponibles. À confirmer sur plus d'actifs et périodes."

    failure_drivers = pd.DataFrame(
        [{"Failure Driver": x, "Read": "Point bloquant détecté par Overfit / Multiple Testing Lab V1."} for x in drivers]
    )

    summary = pd.DataFrame(
        [
            ["Overfit level", level, "Lecture synthétique du risque d'overfit."],
            ["Robustness score", f"{_format_num(robustness_score, 0)}/100", "Score élevé = risque d'overfit plus faible."],
            ["Overfit risk score", f"{_format_num(overfit_risk_score, 0)}/100", "Score élevé = risque d'overfit plus élevé."],
            ["Gates passed", f"{pass_count}/{len(gates)}", "Nombre de critères de validation passés."],
            ["Research DoF proxy", str(research_dof), "Degrés de liberté de recherche approximatifs."],
            ["Trials proxy", str(int(trials or 0)), "Nombre d'essais utilisé dans la pénalité DSR."],
            ["PSR", _format_pct(psr), "Probabilistic Sharpe Ratio proxy."],
            ["DSR proxy", _format_pct(dsr), "Deflated Sharpe proxy après pénalité essais multiples."],
            ["PBO proxy", _format_pct(pbo), "Proxy de probabilité d'overfit."],
            ["Parameter score", f"{_format_num(param_score, 0)}/100", "Stabilité de la surface de paramètres."],
            ["Positive parameter share", _format_pct(positive_param_share), "Part des paramètres testés avec résultat positif."],
            ["Near-best parameter share", _format_pct(near_best_share), "Part de la surface proche du meilleur résultat."],
            ["WF score", f"{_format_num(wf_score, 0)}/100", "Stabilité walk-forward."],
            ["OOS score", f"{_format_num(oos_score, 0)}/100", "Validation hors-échantillon."],
            ["Tournament rejected share", _format_pct(tournament_rejected_share), "Part des stratégies rejetées dans le tournoi."],
            ["Failure drivers", "; ".join(drivers) if drivers else "None", "Raisons principales de fragilité."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    cards = [
        {"label": "Overfit read", "value": level, "delta": f"risk {_format_num(overfit_risk_score, 0)}/100"},
        {"label": "Robustness", "value": f"{_format_num(robustness_score, 0)}/100", "delta": f"{pass_count}/{len(gates)} gates"},
        {"label": "DSR proxy", "value": _format_pct(dsr, 0), "delta": f"{int(trials or 0)} trials"},
        {"label": "PBO proxy", "value": _format_pct(pbo, 0), "delta": "overfit"},
        {"label": "Research DoF", "value": str(research_dof), "delta": "proxy"},
        {"label": "OOS / WF", "value": f"{_format_num(oos_score, 0)} / {_format_num(wf_score, 0)}", "delta": "scores"},
    ]

    return {
        "level": level,
        "score": robustness_score,
        "risk_score": overfit_risk_score,
        "read": read,
        "cards": cards,
        "summary": summary,
        "gates": gates,
        "degrees_of_freedom": dof,
        "failure_drivers": failure_drivers,
        "drivers": drivers,
        "pass_share": pass_share,
        "trials": int(trials or 0),
        "research_dof": research_dof,
    }


# ============================================================
# CROSS-ASSET / MULTI-TICKER VALIDATION V1
# ============================================================

def _cross_asset_default_basket(ticker: str) -> list[str]:
    """
    Panier par défaut selon le ticker courant.
    """
    t = str(ticker or "").upper().strip()

    semi = ["NVDA", "AMD", "AVGO", "MU", "MRVL", "QCOM", "INTC", "SMH"]
    mega = ["AAPL", "MSFT", "GOOGL", "META", "AMZN", "ORCL", "QQQ", "XLK"]
    risk = ["SPY", "QQQ", "IWM", "DIA", "SMH", "XLK"]

    if t in semi:
        out = semi
    elif t in mega:
        out = mega
    else:
        out = [t] + risk if t else risk

    clean = []
    for x in out:
        x = str(x).upper().strip()
        if x and x not in clean:
            clean.append(x)

    return clean[:8]


def _sanitize_cross_asset_tickers(text: str, base_ticker: str, max_assets: int = 8) -> list[str]:
    """
    Nettoie une liste de tickers saisie par l'utilisateur.
    """
    raw = str(text or "").replace(";", ",").replace("\n", ",").split(",")

    tickers = []

    base = str(base_ticker or "").upper().strip()
    if base:
        tickers.append(base)

    for item in raw:
        t = str(item or "").upper().strip()
        t = t.replace(" ", "")

        if not t:
            continue

        # garde-fou simple : on évite les chaînes absurdes
        if len(t) > 12:
            continue

        if t not in tickers:
            tickers.append(t)

    return tickers[:max(1, int(max_assets or 8))]


def _load_cross_asset_price_data(
    symbol: str,
    base_ticker: str,
    base_df: pd.DataFrame,
) -> tuple[pd.DataFrame, str]:
    """
    Charge les prix d'un ticker pour la validation cross-asset.

    Pour le ticker courant, on réutilise base_df afin d'éviter un téléchargement inutile.
    Pour les autres, yfinance est utilisé si disponible.
    """
    symbol = str(symbol or "").upper().strip()
    base_ticker = str(base_ticker or "").upper().strip()

    if not symbol:
        return pd.DataFrame(), "empty symbol"

    if symbol == base_ticker and isinstance(base_df, pd.DataFrame) and not base_df.empty:
        return base_df.copy(), "current workspace data"

    try:
        import yfinance as yf

        if isinstance(base_df, pd.DataFrame) and not base_df.empty and _is_datetime_like_index(base_df.index):
            start = pd.to_datetime(base_df.index.min()).date().isoformat()
            end = (pd.to_datetime(base_df.index.max()) + pd.Timedelta(days=3)).date().isoformat()

            raw = yf.download(
                symbol,
                start=start,
                end=end,
                progress=False,
                auto_adjust=True,
                threads=False,
            )
        else:
            raw = yf.download(
                symbol,
                period="1y",
                progress=False,
                auto_adjust=True,
                threads=False,
            )

        px = _extract_ohlc(raw)

        if px.empty:
            return pd.DataFrame(), "download empty"

        return px, "downloaded"

    except Exception as exc:
        return pd.DataFrame(), f"download error: {exc}"


def _cross_asset_validation_v1_pack(
    ticker: str,
    base_df: pd.DataFrame,
    cfg: BacktestConfig,
    tickers: list[str],
) -> dict[str, Any]:
    """
    Cross-Asset / Multi-Ticker Validation V1.

    Lecture seule :
    - ne modifie pas le moteur du ticker courant ;
    - ne modifie pas les trades ;
    - ne modifie pas l'equity curve principale ;
    - ne modifie pas le verdict principal.

    Le module relance la même configuration sur un panier de tickers pour vérifier
    si l'edge est spécifique à un actif ou généralisable.
    """
    empty = {
        "enabled": False,
        "level": "Disabled",
        "score": np.nan,
        "read": "Cross-Asset V1 désactivé.",
        "cards": [],
        "summary": pd.DataFrame(),
        "ticker_matrix": pd.DataFrame(),
        "failure_drivers": pd.DataFrame(),
        "return_correlation": pd.DataFrame(),
        "daily_returns": pd.DataFrame(),
    }

    if base_df is None or not isinstance(base_df, pd.DataFrame) or base_df.empty:
        empty["level"] = "Unavailable"
        empty["read"] = "Données du ticker courant indisponibles."
        return empty

    tickers = [str(x).upper().strip() for x in tickers if str(x).strip()]
    tickers = list(dict.fromkeys(tickers))

    if not tickers:
        empty["level"] = "Unavailable"
        empty["read"] = "Aucun ticker cross-asset fourni."
        return empty

    rows = []
    failure_rows = []
    return_series = []

    for symbol in tickers:
        px, data_status = _load_cross_asset_price_data(
            symbol=symbol,
            base_ticker=ticker,
            base_df=base_df,
        )

        if px.empty or len(px) < 80:
            rows.append(
                {
                    "Ticker": symbol,
                    "Data Status": data_status,
                    "Obs": int(len(px)) if isinstance(px, pd.DataFrame) else 0,
                    "Cross Status": "DATA FAIL",
                    "Survival Score": 0.0,
                    "Return": np.nan,
                    "Benchmark": np.nan,
                    "Alpha": np.nan,
                    "Sharpe": np.nan,
                    "Sortino": np.nan,
                    "Max DD": np.nan,
                    "CVaR 95": np.nan,
                    "Trades": 0,
                    "Exposure": np.nan,
                    "OOS Level": "N/A",
                    "OOS Score": np.nan,
                    "Factor Level": "N/A",
                    "Regime Level": "N/A",
                    "Integrity": 0,
                    "Failure Drivers": "data unavailable",
                }
            )

            failure_rows.append(
                {
                    "Ticker": symbol,
                    "Failure Driver": "data unavailable",
                    "Read": data_status,
                }
            )
            continue

        try:
            bench_symbol, bench_label = _resolve_benchmark_symbol(
                symbol,
                getattr(cfg, "benchmark_mode", "Ticker Buy & Hold"),
                getattr(cfg, "benchmark_ticker", ""),
            )

            local_cfg = replace(
                cfg,
                benchmark_ticker=bench_symbol,
                benchmark_label=bench_label,
            )

            result = _run_backtest(px, local_cfg)

            if not isinstance(result, dict) or result.get("error"):
                rows.append(
                    {
                        "Ticker": symbol,
                        "Data Status": data_status,
                        "Obs": int(len(px)),
                        "Cross Status": "ENGINE FAIL",
                        "Survival Score": 0.0,
                        "Return": np.nan,
                        "Benchmark": np.nan,
                        "Alpha": np.nan,
                        "Sharpe": np.nan,
                        "Sortino": np.nan,
                        "Max DD": np.nan,
                        "CVaR 95": np.nan,
                        "Trades": 0,
                        "Exposure": np.nan,
                        "OOS Level": "N/A",
                        "OOS Score": np.nan,
                        "Factor Level": "N/A",
                        "Regime Level": "N/A",
                        "Integrity": 0,
                        "Failure Drivers": str(result.get("error", "engine fail")),
                    }
                )
                continue

            bt_i = result.get("data", pd.DataFrame())
            metrics_i = result.get("metrics", {})
            trades_i = result.get("trades", pd.DataFrame())

            integrity_i, notes_i = _integrity_score(metrics_i, bt_i, local_cfg)

            wf_i = _walk_forward_segments(bt_i)
            oos_i = _oos_validation_v2_pack(bt_i, wf_i)
            factor_i = _factor_benchmark_attribution_v2_pack(bt_i)
            regime_i = _regime_attribution_v2_pack(bt_i)
            psr_i = _probabilistic_sharpe(bt_i, benchmark_sr=0.0).get("psr", np.nan)

            total_return = _safe_float(metrics_i.get("Total Return"), np.nan)
            alpha = _safe_float(metrics_i.get("Relative Alpha"), np.nan)
            sharpe = _safe_float(metrics_i.get("Sharpe"), np.nan)
            sortino = _safe_float(metrics_i.get("Sortino"), np.nan)
            max_dd = _safe_float(metrics_i.get("Max Drawdown"), np.nan)
            cvar = _safe_float(metrics_i.get("CVaR 95"), np.nan)
            exposure = _safe_float(metrics_i.get("Exposure"), np.nan)
            trades_count = int(metrics_i.get("Trades", 0) or 0)
            oos_score = _safe_float(oos_i.get("score"), np.nan)

            pass_return = bool(pd.notna(total_return) and total_return > 0)
            pass_alpha = bool(pd.notna(alpha) and alpha > 0)
            pass_sharpe = bool(pd.notna(sharpe) and sharpe > 0)
            pass_dd = bool(pd.notna(max_dd) and max_dd > -0.30)
            pass_oos = bool(pd.notna(oos_score) and oos_score >= 45)
            pass_sample = bool(trades_count >= 3 and integrity_i >= 60)
            pass_psr = bool(pd.notna(psr_i) and psr_i >= 0.50)

            gates = [
                pass_return,
                pass_alpha,
                pass_sharpe,
                pass_dd,
                pass_oos,
                pass_sample,
                pass_psr,
            ]

            survival_score = float(np.mean(gates) * 100.0)

            if survival_score >= 70:
                cross_status = "PASS"
            elif survival_score >= 45:
                cross_status = "MIXED"
            else:
                cross_status = "FAIL"

            drivers = []

            if not pass_return:
                drivers.append("negative return")
            if not pass_alpha:
                drivers.append("negative alpha")
            if not pass_sharpe:
                drivers.append("weak Sharpe")
            if not pass_dd:
                drivers.append("large drawdown")
            if not pass_oos:
                drivers.append("weak OOS")
            if not pass_sample:
                drivers.append("weak sample/integrity")
            if not pass_psr:
                drivers.append("weak PSR")

            for d in drivers:
                failure_rows.append(
                    {
                        "Ticker": symbol,
                        "Failure Driver": d,
                        "Read": "Cross-asset gate failed.",
                    }
                )

            rows.append(
                {
                    "Ticker": symbol,
                    "Data Status": data_status,
                    "Obs": int(len(bt_i)),
                    "Cross Status": cross_status,
                    "Survival Score": survival_score,
                    "Return": total_return,
                    "Benchmark": _safe_float(metrics_i.get("Benchmark Return"), np.nan),
                    "Alpha": alpha,
                    "Sharpe": sharpe,
                    "Sortino": sortino,
                    "Max DD": max_dd,
                    "CVaR 95": cvar,
                    "Trades": trades_count,
                    "Exposure": exposure,
                    "OOS Level": str(oos_i.get("level", "N/A")),
                    "OOS Score": oos_score,
                    "Factor Level": str(factor_i.get("level", "N/A")),
                    "Regime Level": str(regime_i.get("level", "N/A")),
                    "Integrity": integrity_i,
                    "Failure Drivers": "; ".join(drivers) if drivers else "None",
                }
            )

            if isinstance(bt_i, pd.DataFrame) and not bt_i.empty and "strategy_return" in bt_i.columns:
                s = pd.to_numeric(bt_i["strategy_return"], errors="coerce").replace([np.inf, -np.inf], np.nan)
                s.name = symbol
                return_series.append(s)

        except Exception as exc:
            rows.append(
                {
                    "Ticker": symbol,
                    "Data Status": data_status,
                    "Obs": int(len(px)) if isinstance(px, pd.DataFrame) else 0,
                    "Cross Status": "ERROR",
                    "Survival Score": 0.0,
                    "Return": np.nan,
                    "Benchmark": np.nan,
                    "Alpha": np.nan,
                    "Sharpe": np.nan,
                    "Sortino": np.nan,
                    "Max DD": np.nan,
                    "CVaR 95": np.nan,
                    "Trades": 0,
                    "Exposure": np.nan,
                    "OOS Level": "N/A",
                    "OOS Score": np.nan,
                    "Factor Level": "N/A",
                    "Regime Level": "N/A",
                    "Integrity": 0,
                    "Failure Drivers": str(exc),
                }
            )

            failure_rows.append(
                {
                    "Ticker": symbol,
                    "Failure Driver": "runtime error",
                    "Read": str(exc),
                }
            )

    matrix = pd.DataFrame(rows)

    if matrix.empty:
        empty["level"] = "Unavailable"
        empty["read"] = "Aucun résultat cross-asset calculable."
        return empty

    valid = matrix[~matrix["Cross Status"].isin(["DATA FAIL", "ENGINE FAIL", "ERROR"])].copy()

    if valid.empty:
        level = "Cross-asset failed"
        score = 0.0
        read = "Aucun ticker du panier n'a pu être validé correctement."
        pass_share = 0.0
        mixed_share = 0.0
        fail_share = 1.0
        median_alpha = np.nan
        median_sharpe = np.nan
    else:
        pass_share = float((valid["Cross Status"] == "PASS").mean())
        mixed_share = float((valid["Cross Status"] == "MIXED").mean())
        fail_share = float((valid["Cross Status"] == "FAIL").mean())

        score = float(pd.to_numeric(valid["Survival Score"], errors="coerce").dropna().mean())
        median_alpha = float(pd.to_numeric(valid["Alpha"], errors="coerce").dropna().median()) if pd.to_numeric(valid["Alpha"], errors="coerce").dropna().size else np.nan
        median_sharpe = float(pd.to_numeric(valid["Sharpe"], errors="coerce").dropna().median()) if pd.to_numeric(valid["Sharpe"], errors="coerce").dropna().size else np.nan

        if pass_share >= 0.60 and score >= 65:
            level = "Cross-asset robust"
            read = "La stratégie survit sur une majorité du panier testé."
        elif pass_share + mixed_share >= 0.50 and score >= 40:
            level = "Cross-asset mixed"
            read = "La stratégie montre une robustesse transversale mitigée."
        else:
            level = "Cross-asset failed"
            read = "La stratégie ne se généralise pas correctement au panier testé."

    corr = pd.DataFrame()
    daily_returns = pd.DataFrame()

    try:
        if return_series:
            daily_returns = pd.concat(return_series, axis=1).replace([np.inf, -np.inf], np.nan).dropna(how="all")
            corr = daily_returns.corr()
    except Exception:
        corr = pd.DataFrame()
        daily_returns = pd.DataFrame()

    failure_df = pd.DataFrame(failure_rows)

    summary = pd.DataFrame(
        [
            ["Cross-asset level", level, "Lecture synthétique de la validation multi-actifs."],
            ["Cross-asset score", f"{_format_num(score, 0)}/100", "Score moyen de survie sur les tickers testés."],
            ["Tickers tested", str(len(matrix)), "Nombre de tickers demandés."],
            ["Valid tickers", str(len(valid)), "Tickers avec backtest exploitable."],
            ["PASS share", _format_pct(pass_share), "Part du panier avec statut PASS."],
            ["MIXED share", _format_pct(mixed_share), "Part du panier avec statut MIXED."],
            ["FAIL share", _format_pct(fail_share), "Part du panier avec statut FAIL."],
            ["Median alpha", _format_pct(median_alpha), "Alpha médian du panier."],
            ["Median Sharpe", _format_num(median_sharpe), "Sharpe médian du panier."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    cards = [
        {"label": "Cross-asset read", "value": level, "delta": f"{_format_num(score, 0)}/100"},
        {"label": "Valid tickers", "value": str(len(valid)), "delta": f"{len(matrix)} requested"},
        {"label": "PASS share", "value": _format_pct(pass_share, 0), "delta": "survival"},
        {"label": "Median alpha", "value": _format_pct(median_alpha), "delta": "basket"},
        {"label": "Median Sharpe", "value": _format_num(median_sharpe), "delta": "basket"},
        {"label": "FAIL share", "value": _format_pct(fail_share, 0), "delta": "fragility"},
    ]

    return {
        "enabled": True,
        "level": level,
        "score": score,
        "read": read,
        "cards": cards,
        "summary": summary,
        "ticker_matrix": matrix,
        "failure_drivers": failure_df,
        "return_correlation": corr,
        "daily_returns": daily_returns,
    }


def _render_cross_asset_validation_v1(
    ticker: str,
    base_df: pd.DataFrame,
    cfg: BacktestConfig,
) -> dict[str, Any]:
    """
    Rendu Streamlit Cross-Asset / Multi-Ticker Validation V1.
    """
    st.subheader("Cross-Asset / Multi-Ticker Validation V1")
    st.caption(
        "Validation lecture seule : relance la même configuration sur plusieurs tickers "
        "pour mesurer la généralisation de l'edge. Aucun impact sur le moteur principal, "
        "les trades, l'equity curve ou le verdict."
    )

    default_basket = _cross_asset_default_basket(ticker)

    ca0, ca1 = st.columns([3, 1])

    ticker_text = ca0.text_input(
        "Tickers cross-asset",
        value=", ".join(default_basket),
        key="bt_cross_asset_tickers",
        help="Sépare les tickers par virgules. Le ticker courant est ajouté automatiquement.",
    )

    max_assets = ca1.slider(
        "Max assets",
        min_value=3,
        max_value=12,
        value=8,
        step=1,
        key="bt_cross_asset_max_assets",
    )

    run_cross_asset = st.toggle(
        "Activer Cross-Asset Validation",
        value=False,
        key="bt_cross_asset_enabled",
    )

    if not run_cross_asset:
        st.info("Cross-Asset V1 désactivé. Active le toggle pour lancer les téléchargements et la validation multi-tickers.")
        return {
            "enabled": False,
            "level": "Disabled",
            "score": np.nan,
            "read": "Cross-Asset V1 désactivé.",
            "cards": [],
            "summary": pd.DataFrame(),
            "ticker_matrix": pd.DataFrame(),
            "failure_drivers": pd.DataFrame(),
            "return_correlation": pd.DataFrame(),
            "daily_returns": pd.DataFrame(),
        }

    tickers = _sanitize_cross_asset_tickers(
        ticker_text,
        base_ticker=ticker,
        max_assets=max_assets,
    )

    with st.spinner("Validation cross-asset en cours..."):
        pack = _cross_asset_validation_v1_pack(
            ticker=ticker,
            base_df=base_df,
            cfg=cfg,
            tickers=tickers,
        )

    _card_grid(pack.get("cards", []), columns=6)

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))

    if "failed" in level.lower():
        st.warning(f"Lecture cross-asset : {read}")
