    if isinstance(matrix, pd.DataFrame) and not matrix.empty:
        display = matrix.copy()

        pct_cols = [
            "Survival Score",
            "Return",
            "Benchmark",
            "Alpha",
            "Max DD",
            "CVaR 95",
            "Exposure",
            "OOS Score",
        ]

        for col in pct_cols:
            if col in display.columns:
                if col in {"Survival Score", "OOS Score"}:
                    display[col] = display[col].map(lambda x: f"{_format_num(x, 0)}/100")
