def _render_backtest_header(ticker: str, cfg: BacktestConfig, metrics: dict[str, Any], integrity: int, diagnostics: dict[str, Any], research_label: str) -> None:
    edge_score = diagnostics.get("edge_score", np.nan)
    pbo = diagnostics.get("pbo_proxy", np.nan)
    dsr = diagnostics.get("dsr_proxy", np.nan)

    st.markdown(
        f"""
<div class="qt-status-strip">
  <div>
    <div class="qt-kicker">BACKTEST RESEARCH LAB</div>
    <div class="qt-strip-title">{ticker} · {cfg.strategy}</div>
    <div class="qt-muted">Benchmark: {metrics.get("Benchmark Label", "Benchmark")} · signal t+1 · costs/slippage included</div>
  </div>
  <div class="qt-stat"><span>Verdict</span><b>{research_label}</b></div>
  <div class="qt-stat"><span>Edge</span><b>{_format_num(edge_score, 0)}/100</b></div>
  <div class="qt-stat"><span>Alpha</span><b>{_format_pct(metrics.get("Relative Alpha"))}</b></div>
  <div class="qt-stat"><span>DSR proxy</span><b>{_format_pct(dsr, 0)}</b></div>
  <div class="qt-stat"><span>PBO proxy</span><b>{_format_pct(pbo, 0)}</b></div>
  <div class="qt-stat"><span>Integrity</span><b>{integrity}/100</b></div>
</div>
        """,
        unsafe_allow_html=True,
    )


def _render_metric_cards(metrics: dict[str, Any], integrity: int, diagnostics: dict[str, Any]) -> None:
    rows = [
        {"label": "CAGR", "value": _format_pct(metrics.get("CAGR")), "delta": "strategy"},
        {"label": "Alpha", "value": _format_pct(metrics.get("Relative Alpha")), "delta": metrics.get("Benchmark Label", "benchmark")},
        {"label": "Sharpe", "value": _format_num(metrics.get("Sharpe")), "delta": f"PSR {_format_pct(diagnostics.get('psr'), 0)}"},
        {"label": "Max DD", "value": _format_pct(metrics.get("Max Drawdown")), "delta": "drawdown"},
        {"label": "Trades", "value": str(int(metrics.get("Trades", 0) or 0)), "delta": f"Exposure {_format_pct(metrics.get('Exposure'), 0)}"},
        {"label": "Test Integrity", "value": f"{integrity}/100", "delta": "process"},
    ]
    _card_grid(rows, columns=6)


def _render_verdict_banner(metrics: dict[str, Any], integrity: int, notes: list[str], diagnostics: dict[str, Any]) -> None:
    verdict, level, reasons = _verdict(metrics, integrity, notes)
    research_label = _research_verdict(diagnostics.get("edge_score", 0), verdict, diagnostics)
    msg = (
        f"Research Verdict: {research_label} · "
        f"Backtest Verdict: {verdict} · "
        f"Alpha: {_format_pct(metrics.get('Relative Alpha'))} · "
        f"CAGR gap: {_format_pct(metrics.get('CAGR Gap'))} · "
        f"Cost breakeven: {diagnostics.get('cost', {}).get('label', 'N/A')} · "
        f"Test Integrity: {integrity}/100"
    )

    custom_diag = diagnostics.get("custom_signal", {})
    if isinstance(custom_diag, dict) and custom_diag.get("verdict"):
        msg += f" · Custom Signal: {custom_diag.get('verdict')}"

    if level == "success" and diagnostics.get("edge_score", 0) >= 70:
        st.success(msg)
    elif level == "error" or "REJECTED" in research_label:
        st.error(msg)
    else:
        st.warning(msg)


def _render_driver_chips(reasons: list[str], notes: list[str]) -> None:
    clean = [x for x in reasons if str(x).strip()] + [x for x in notes if str(x).strip()]
    if not clean:
        return
    chips = "".join([f"<span class='qt-chip'>{str(x).upper()}</span>" for x in clean])
    st.markdown(f"<div class='qt-chip-row'>{chips}</div>", unsafe_allow_html=True)


def _render_strategy_compare_summary(comp: pd.DataFrame) -> None:
    """
    Rendu Strategy Tournament V2 / Comparison Lab.
    Lecture seule.
    """
    if comp is None or comp.empty:
        st.info("Comparaison indisponible.")
        return

    st.subheader("Strategy Tournament V2 / Comparison Lab")
    st.caption(
        "Comparaison institutionnelle des stratégies : rendement, alpha, Sharpe, Sortino, Calmar, drawdown, "
        "CVaR, coûts, intégrité et Risk Layer ON/OFF lorsque le Risk Layer est activé. "
        "Bloc lecture seule : aucun impact sur le moteur, les trades, l'equity curve ou le verdict principal."
    )

    view = comp.copy()

    def _num_col(col: str) -> pd.Series:
        if col not in view.columns:
            return pd.Series(np.nan, index=view.index)
        return pd.to_numeric(
            view[col].astype(str)
            .str.replace("/100", "", regex=False)
            .str.replace("$", "", regex=False)
            .str.replace(",", "", regex=False)
            .str.replace("%", "", regex=False)
            .str.strip(),
            errors="coerce",
        )

    view["_score_raw"] = _num_col("Tournament Score")
    view["_alpha_raw"] = view["Alpha"].map(_parse_pct_text) if "Alpha" in view.columns else np.nan
    view["_return_raw"] = view["Return"].map(_parse_pct_text) if "Return" in view.columns else np.nan
    view["_sharpe_raw"] = _num_col("Sharpe")
    view["_maxdd_raw"] = view["Max DD"].map(_parse_pct_text) if "Max DD" in view.columns else np.nan

    ranked = view.sort_values("_score_raw", ascending=False).copy()
    winner = ranked.head(1)

    if winner.empty:
        st.info("Tournament vide après nettoyage.")
        return

    w = winner.iloc[0]

    best_alpha = view.sort_values("_alpha_raw", ascending=False).head(1)
    best_sharpe = view.sort_values("_sharpe_raw", ascending=False).head(1)
    best_dd = view.sort_values("_maxdd_raw", ascending=False).head(1)

    current_rows = view[view.get("Current Config", "No").astype(str) == "Yes"].copy()
    current_rank = "N/A"

    if not current_rows.empty and "Rank" in current_rows.columns:
        current_rank = str(current_rows.iloc[0].get("Rank", "N/A"))

    accepted_mask = view.get("Research Bucket", "").astype(str).isin(
        ["Research candidate", "Watchlist"]
    )

    rejected_share = float((view.get("Research Bucket", "").astype(str) == "Rejected").mean()) if len(view) else np.nan

    cards = [
        {
            "label": "Tournament winner",
            "value": str(w.get("Strategy", "N/A")),
            "delta": f"{w.get('Tournament Score', 'N/A')}/100 · {w.get('Execution Variant', '')}",
        },
        {
            "label": "Current config rank",
            "value": current_rank,
            "delta": "current run",
        },
        {
            "label": "Best alpha",
            "value": str(best_alpha.iloc[0].get("Strategy", "N/A")) if not best_alpha.empty else "N/A",
            "delta": str(best_alpha.iloc[0].get("Alpha", "N/A")) if not best_alpha.empty else "N/A",
        },
        {
            "label": "Best Sharpe",
            "value": str(best_sharpe.iloc[0].get("Strategy", "N/A")) if not best_sharpe.empty else "N/A",
            "delta": str(best_sharpe.iloc[0].get("Sharpe", "N/A")) if not best_sharpe.empty else "N/A",
        },
        {
            "label": "Lowest drawdown",
            "value": str(best_dd.iloc[0].get("Strategy", "N/A")) if not best_dd.empty else "N/A",
            "delta": str(best_dd.iloc[0].get("Max DD", "N/A")) if not best_dd.empty else "N/A",
        },
        {
            "label": "Rejected share",
            "value": _format_pct(rejected_share),
            "delta": "tournament breadth",
        },
    ]

    _card_grid(cards, columns=6)

    winner_bucket = str(w.get("Research Bucket", ""))
    winner_score = _safe_float(w.get("_score_raw"), np.nan)

    if winner_bucket == "Research candidate":
        st.success(
            "Lecture tournament : une stratégie ressort comme candidate de recherche. "
            "À confirmer ensuite via walk-forward, stress costs, tail risk et validation OOS."
        )
    elif bool(accepted_mask.any()):
        st.info(
            "Lecture tournament : aucune validation ferme, mais au moins une stratégie mérite une surveillance. "
            "La sélection doit rester conditionnée aux diagnostics de robustesse."
        )
    else:
        st.warning(
            "Lecture tournament : aucune stratégie ne présente un profil suffisamment robuste. "
            "Le signal ou le régime testé doit probablement être retravaillé."
        )

    ranking_cols = [
        "Rank",
        "Strategy",
        "Execution Variant",
        "Current Config",
        "Tournament Score",
        "Research Bucket",
        "Verdict",
        "Return",
        "Benchmark",
        "Alpha",
        "Sharpe",
        "Sortino",
        "Calmar",
        "Max DD",
        "CVaR 95",
        "Profit Factor",
        "Trades",
        "Risk Exits",
        "Test Integrity",
        "Failure Drivers",
    ]

    ranking = comp[[c for c in ranking_cols if c in comp.columns]].copy()

    st.markdown("**Institutional ranking**")
    st.dataframe(ranking, use_container_width=True, hide_index=True)

    if (
        "Execution Variant" in comp.columns
        and comp["Execution Variant"].astype(str).str.contains("Risk Layer ON", case=False, na=False).any()
    ):
        raw = comp.copy()

        raw["_score"] = pd.to_numeric(
            raw["Tournament Score"].astype(str).str.replace("/100", "", regex=False),
            errors="coerce",
        )

        raw["_return"] = raw["Return"].map(_parse_pct_text) if "Return" in raw.columns else np.nan
        raw["_alpha"] = raw["Alpha"].map(_parse_pct_text) if "Alpha" in raw.columns else np.nan
        raw["_maxdd"] = raw["Max DD"].map(_parse_pct_text) if "Max DD" in raw.columns else np.nan

        engine = raw[raw["Execution Variant"] == "Engine only"].copy()
        risk = raw[raw["Execution Variant"] == "Risk Layer ON"].copy()

        delta_rows = []

        for strategy in sorted(set(engine["Strategy"]).intersection(set(risk["Strategy"]))):
            e = engine[engine["Strategy"] == strategy].head(1)
            r = risk[risk["Strategy"] == strategy].head(1)

            if e.empty or r.empty:
                continue

            e0 = e.iloc[0]
            r0 = r.iloc[0]

            delta_rows.append(
                {
                    "Strategy": strategy,
                    "Δ Score": _safe_float(r0.get("_score"), np.nan) - _safe_float(e0.get("_score"), np.nan),
                    "Δ Return": _safe_float(r0.get("_return"), np.nan) - _safe_float(e0.get("_return"), np.nan),
                    "Δ Alpha": _safe_float(r0.get("_alpha"), np.nan) - _safe_float(e0.get("_alpha"), np.nan),
                    "Δ Max DD": _safe_float(r0.get("_maxdd"), np.nan) - _safe_float(e0.get("_maxdd"), np.nan),
                    "Engine Score": _format_num(e0.get("_score"), 0),
                    "Risk Layer Score": _format_num(r0.get("_score"), 0),
                    "Read": "Risk Layer improves score" if _safe_float(r0.get("_score"), 0) > _safe_float(e0.get("_score"), 0) else "Risk Layer does not improve score",
                }
            )

        risk_delta = pd.DataFrame(delta_rows)

        if not risk_delta.empty:
            for col in ["Δ Return", "Δ Alpha", "Δ Max DD"]:
                if col in risk_delta.columns:
                    risk_delta[col] = risk_delta[col].map(_format_pct)

            if "Δ Score" in risk_delta.columns:
                risk_delta["Δ Score"] = risk_delta["Δ Score"].map(lambda x: _format_num(x, 0))

            with st.expander("Risk Layer ON/OFF delta", expanded=True):
                st.caption(
                    "Compare chaque stratégie en Engine only vs Risk Layer ON. "
                    "Δ Max DD positif = drawdown moins négatif, donc amélioration du risque."
                )
                st.dataframe(risk_delta, use_container_width=True, hide_index=True)

    failure_cols = [
        "Rank",
        "Strategy",
        "Execution Variant",
        "Research Bucket",
        "Verdict",
        "Failure Drivers",
    ]

    failure = comp[[c for c in failure_cols if c in comp.columns]].copy()

    with st.expander("Failure driver map", expanded=True):
        st.caption(
            "Carte des raisons de rejet ou de fragilité. Sert à distinguer un problème d'alpha, de drawdown, "
            "de coût, d'échantillon ou de dépendance au Risk Layer."
        )
        st.dataframe(failure, use_container_width=True, hide_index=True)

    full_cols = [
        "Rank",
        "Strategy",
        "Execution Variant",
        "Current Config",
        "Tournament Score",
        "Research Bucket",
        "Verdict",
        "Return",
        "Benchmark",
        "Alpha",
        "CAGR",
        "Sharpe",
        "Sortino",
        "Calmar",
        "Max DD",
        "VaR 95",
        "CVaR 95",
        "Profit Factor",
        "Exposure",
        "Turnover",
        "Trades",
        "Risk Exits",
        "Cost Drag",
        "Cost Paid $",
        "Test Integrity",
        "Failure Drivers",
    ]

    full = comp[[c for c in full_cols if c in comp.columns]].copy()

    with st.expander("Full tournament matrix", expanded=False):
        st.dataframe(full, use_container_width=True, hide_index=True)

    st.download_button(
        "Télécharger le tournament CSV",
        data=full.to_csv(index=False).encode("utf-8"),
        file_name="strategy_tournament_v2.csv",
        mime="text/csv",
        use_container_width=True,
        key="bt_strategy_tournament_v2_download",
    )



def _strategy_research_layer_v21_pack(
    comp: pd.DataFrame,
    diagnostics: dict[str, Any] | None = None,
    metrics: dict[str, Any] | None = None,
    integrity: int | float = 0,
) -> dict[str, Any]:
    """
    Strategy Research Layer V2.1 — Candidate Ranking / Action Plan.

    Lecture seule :
    - ne relance pas le moteur ;
    - ne modifie pas les signaux ;
    - ne modifie pas l'equity curve ;
    - ne modifie pas les trades ;
    - ne modifie pas le verdict.

    Objectif :
    convertir le Strategy Tournament V2 en couche de décision research :
    paper-test queue, retest, reject, blockers et action plan.
    """
    diagnostics = diagnostics if isinstance(diagnostics, dict) else {}
    metrics = metrics if isinstance(metrics, dict) else {}

    empty = {
        "level": "Unavailable",
        "score": np.nan,
        "read": "Strategy tournament indisponible.",
        "cards": [],
        "shortlist": pd.DataFrame(),
        "current_diagnosis": pd.DataFrame(),
        "action_plan": pd.DataFrame(),
    }

    if comp is None or not isinstance(comp, pd.DataFrame) or comp.empty:
        return empty

    view = comp.copy()

    def _col(name: str, default: Any = "") -> pd.Series:
        if name in view.columns:
            return view[name]
        return pd.Series(default, index=view.index)

    def _num_text(value: Any) -> float:
        try:
            txt = (
                str(value)
                .replace("/100", "")
                .replace("$", "")
                .replace(",", "")
                .replace("%", "")
                .strip()
            )
            if txt in {"", "N/A", "nan", "None"}:
                return np.nan
            return float(txt)
        except Exception:
            return np.nan

    view["_score"] = _col("Tournament Score").map(_num_text)
    view["_alpha"] = _col("Alpha").map(_parse_pct_text)
    view["_return"] = _col("Return").map(_parse_pct_text)
    view["_maxdd"] = _col("Max DD").map(_parse_pct_text)
    view["_cvar"] = _col("CVaR 95").map(_parse_pct_text)
    view["_sharpe"] = _col("Sharpe").map(_num_text)
    view["_sortino"] = _col("Sortino").map(_num_text)
    view["_profit_factor"] = _col("Profit Factor").map(_num_text)
    view["_trades"] = _col("Trades").map(_num_text)
    view["_integrity"] = _col("Test Integrity").map(_num_text)

    def _blockers(row: pd.Series) -> list[str]:
        issues: list[str] = []

        ret = _safe_float(row.get("_return"), np.nan)
        alpha = _safe_float(row.get("_alpha"), np.nan)
        sharpe = _safe_float(row.get("_sharpe"), np.nan)
        maxdd = _safe_float(row.get("_maxdd"), np.nan)
        cvar = _safe_float(row.get("_cvar"), np.nan)
        trades = _safe_float(row.get("_trades"), np.nan)
        bucket = str(row.get("Research Bucket", ""))
        verdict = str(row.get("Verdict", ""))

        if pd.notna(ret) and ret <= 0:
            issues.append("negative return")
        if pd.notna(alpha) and alpha <= 0:
            issues.append("negative alpha")
        if pd.notna(sharpe) and sharpe < 0.50:
            issues.append("weak Sharpe")
        if pd.notna(maxdd) and maxdd < -0.25:
            issues.append("high drawdown")
        if pd.notna(cvar) and cvar < -0.04:
            issues.append("large CVaR")
        if pd.notna(trades) and trades < 5:
            issues.append("low trade sample")
        if "Rejected" in bucket or verdict.upper() == "REJECTED":
            issues.append("rejected by tournament")

        return list(dict.fromkeys([x for x in issues if str(x).strip()]))

    view["_blockers"] = view.apply(_blockers, axis=1)
    view["_blocker_count"] = view["_blockers"].map(len)

    def _action(row: pd.Series) -> str:
        score = _safe_float(row.get("_score"), np.nan)
        alpha = _safe_float(row.get("_alpha"), np.nan)
        sharpe = _safe_float(row.get("_sharpe"), np.nan)
        maxdd = _safe_float(row.get("_maxdd"), np.nan)
        trades = _safe_float(row.get("_trades"), np.nan)
        blockers = int(row.get("_blocker_count", 0) or 0)
        bucket = str(row.get("Research Bucket", ""))

        if (
            pd.notna(score)
            and score >= 70
            and pd.notna(alpha)
            and alpha > 0
            and pd.notna(sharpe)
            and sharpe >= 0.80
            and pd.notna(maxdd)
            and maxdd > -0.25
            and pd.notna(trades)
            and trades >= 5
            and blockers <= 1
            and bucket in {"Research candidate", "Watchlist"}
        ):
            return "Paper-test queue"

        if (
            pd.notna(score)
            and score >= 55
            and pd.notna(alpha)
            and alpha > -0.03
            and pd.notna(maxdd)
            and maxdd > -0.35
            and blockers <= 3
        ):
            return "Retest with OOS/WF"

        if (
            pd.notna(score)
            and score >= 45
            and pd.notna(maxdd)
            and maxdd > -0.35
        ):
            return "Research watchlist / revise rules"

        return "Reject for now"

    view["_action"] = view.apply(_action, axis=1)

    def _priority(row: pd.Series) -> float:
        score = _safe_float(row.get("_score"), 0.0)
        alpha = _safe_float(row.get("_alpha"), 0.0)
        sharpe = _safe_float(row.get("_sharpe"), 0.0)
        maxdd = _safe_float(row.get("_maxdd"), -1.0)
        blockers = int(row.get("_blocker_count", 0) or 0)

        priority = (
            score
            + max(alpha, -0.20) * 100.0
            + max(sharpe, -1.0) * 4.0
            + max(maxdd, -0.60) * 20.0
            - blockers * 8.0
        )

        return max(0.0, min(100.0, float(priority)))

    view["_priority"] = view.apply(_priority, axis=1)

    ranked = view.sort_values(
        ["_priority", "_score", "_alpha", "_sharpe"],
        ascending=[False, False, False, False],
    ).copy()

    shortlist_rows = []

    for _, row in ranked.head(10).iterrows():
        shortlist_rows.append(
            {
                "Rank": row.get("Rank", "N/A"),
                "Strategy": row.get("Strategy", "N/A"),
                "Variant": row.get("Execution Variant", "N/A"),
                "Current": row.get("Current Config", "No"),
                "Bucket": row.get("Research Bucket", "N/A"),
                "Tournament Score": row.get("Tournament Score", "N/A"),
                "Research Priority": f"{_format_num(row.get('_priority'), 0)}/100",
                "Return": row.get("Return", "N/A"),
                "Alpha": row.get("Alpha", "N/A"),
                "Sharpe": row.get("Sharpe", "N/A"),
                "Max DD": row.get("Max DD", "N/A"),
                "Trades": row.get("Trades", "N/A"),
                "Action": row.get("_action", "N/A"),
                "Blockers": "; ".join(row.get("_blockers", [])) if row.get("_blockers", []) else "None",
            }
        )

    shortlist = pd.DataFrame(shortlist_rows)

    current_mask = _col("Current Config", "No").astype(str).str.upper().eq("YES")
    current = view[current_mask].copy()

    current_rows = []

    if not current.empty:
        cur = current.iloc[0]
        current_rows = [
            ["Current strategy", cur.get("Strategy", "N/A"), "Stratégie actuellement testée."],
            ["Current variant", cur.get("Execution Variant", "N/A"), "Variante moteur / Risk Layer."],
            ["Current rank", cur.get("Rank", "N/A"), "Rang dans le Strategy Tournament."],
            ["Current action", cur.get("_action", "N/A"), "Décision research recommandée."],
            ["Current blockers", "; ".join(cur.get("_blockers", [])) if cur.get("_blockers", []) else "None", "Points bloquants détectés."],
            ["Tournament score", cur.get("Tournament Score", "N/A"), "Score relatif dans le tournoi."],
            ["Alpha", cur.get("Alpha", "N/A"), "Sur/sous-performance vs benchmark."],
            ["Sharpe", cur.get("Sharpe", "N/A"), "Qualité rendement / risque."],
            ["Max DD", cur.get("Max DD", "N/A"), "Drawdown maximum."],
            ["Trades", cur.get("Trades", "N/A"), "Taille de l'échantillon trade-level."],
            ["Integrity", f"{int(_safe_float(integrity, 0))}/100", "Score d'intégrité du test courant."],
        ]
    else:
        current_rows = [
            ["Current strategy", "N/A", "Aucune ligne Current Config détectée dans le tournament."],
        ]

    current_diagnosis = pd.DataFrame(current_rows, columns=["Metric", "Value", "Read"])

    paper_count = int(view["_action"].astype(str).str.contains("Paper-test queue", case=False, na=False).sum())
    retest_count = int(view["_action"].astype(str).str.contains("Retest", case=False, na=False).sum())
    rejected_count = int(view["_action"].astype(str).str.contains("Reject", case=False, na=False).sum())

    best = ranked.iloc[0] if not ranked.empty else pd.Series(dtype=object)
    best_strategy = str(best.get("Strategy", "N/A"))
    best_action = str(best.get("_action", "N/A"))
    best_score = _safe_float(best.get("_priority"), np.nan)

    # Blockers globaux depuis diagnostics.
    global_blockers: list[str] = []

    pbo = _safe_float(diagnostics.get("pbo_proxy"), np.nan)
    dsr = _safe_float(diagnostics.get("dsr_proxy"), np.nan)

    if pd.notna(pbo) and pbo >= 0.65:
        global_blockers.append("high PBO / overfit risk")
    if pd.notna(dsr) and dsr < 0.30:
        global_blockers.append("weak DSR proxy")

    oos_pack = diagnostics.get("oos_v2", {})
    if isinstance(oos_pack, dict) and "failed" in str(oos_pack.get("level", "")).lower():
        global_blockers.append("OOS failed")

    overfit_pack = diagnostics.get("overfit_v1", {})
    if isinstance(overfit_pack, dict) and "high" in str(overfit_pack.get("level", "")).lower():
        global_blockers.append("high overfit risk")

    factor_pack = diagnostics.get("factor_v2", {})
    if isinstance(factor_pack, dict) and "negative" in str(factor_pack.get("level", "")).lower():
        global_blockers.append("negative factor attribution")

    if paper_count > 0:
        level = "Paper-test candidate found"
        score = 80.0
        read = "Au moins une stratégie passe les critères minimaux de promotion research."
    elif retest_count > 0:
        level = "Retest candidates only"
        score = 55.0
        read = "Aucune stratégie n'est prête pour paper-test, mais certaines méritent un retest contrôlé."
    else:
        level = "No deployable candidate"
        score = 25.0
        read = "Le tournament ne produit pas de candidat research exploitable dans cette configuration."

    if global_blockers:
        score = max(0.0, score - min(30.0, len(global_blockers) * 8.0))
        if paper_count > 0:
            level = "Candidate found but blocked"
            read = "Un candidat existe, mais des blockers globaux imposent une validation supplémentaire."

    action_rows: list[dict[str, Any]] = []

    def _add_action(priority: str, blocker: str, action: str, read: str) -> None:
        action_rows.append(
            {
                "Priority": priority,
                "Blocker": blocker,
                "Recommended Action": action,
                "Read": read,
            }
        )

    blocker_flat = []
    for items in view["_blockers"].tolist():
        blocker_flat.extend(items if isinstance(items, list) else [])

    blocker_counts = pd.Series(blocker_flat).value_counts().to_dict() if blocker_flat else {}

    if blocker_counts.get("negative alpha", 0) > 0:
        _add_action(
            "High",
            "negative alpha",
            "Do not optimize exits first; fix signal/benchmark edge before risk tuning.",
            "Un alpha négatif signale que le problème vient probablement du signal ou de l'exposition benchmark.",
        )

    if blocker_counts.get("weak Sharpe", 0) > 0:
        _add_action(
            "High",
            "weak Sharpe",
            "Work on regime filter, entry timing, and noise reduction.",
            "Un Sharpe faible indique une mauvaise qualité rendement/volatilité.",
        )

    if blocker_counts.get("high drawdown", 0) > 0:
        _add_action(
            "Medium",
            "high drawdown",
            "Retest with Risk Layer, position sizing, and drawdown cut.",
            "Le drawdown peut être traité par sizing/risk, mais seulement si l'alpha brut existe.",
        )

    if blocker_counts.get("low trade sample", 0) > 0:
        _add_action(
            "Medium",
            "low trade sample",
            "Increase history window or use higher-frequency validation before conclusion.",
            "Un faible nombre de trades rend les métriques instables.",
        )

    if "OOS failed" in global_blockers:
        _add_action(
            "Critical",
            "OOS failed",
            "Reject current parameters until out-of-sample improves.",
            "Une stratégie qui échoue OOS ne doit pas être promue en paper-test.",
        )

    if "high PBO / overfit risk" in global_blockers or "high overfit risk" in global_blockers:
        _add_action(
            "Critical",
            "overfit risk",
            "Reduce research degrees of freedom and validate on unseen windows.",
            "Le risque d'overfit impose une validation plus stricte avant toute promotion.",
        )

    if "negative factor attribution" in global_blockers:
        _add_action(
            "High",
            "negative factor attribution",
            "Separate beta timing from residual alpha; do not accept hidden benchmark drag.",
            "L'attribution factorielle négative indique une exposition benchmark mal exploitée.",
        )

    if not action_rows:
        _add_action(
            "Info",
            "None",
            "Keep current candidate under monitoring and extend validation window.",
            "Aucun blocker majeur consolidé n'a été détecté par le Strategy Research Layer.",
        )

    action_plan = pd.DataFrame(action_rows)

    cards = [
        {
            "label": "Research decision",
            "value": level,
            "delta": f"{_format_num(score, 0)}/100",
        },
        {
            "label": "Best candidate",
            "value": best_strategy,
            "delta": best_action,
        },
        {
            "label": "Best priority",
            "value": f"{_format_num(best_score, 0)}/100",
            "delta": "research score",
        },
        {
            "label": "Paper-test queue",
            "value": str(paper_count),
            "delta": "candidates",
        },
        {
            "label": "Retest queue",
            "value": str(retest_count),
            "delta": "controlled retest",
        },
        {
            "label": "Reject count",
            "value": str(rejected_count),
            "delta": "not actionable",
        },
    ]

    return {
        "level": level,
        "score": score,
        "read": read,
        "cards": cards,
        "shortlist": shortlist,
        "current_diagnosis": current_diagnosis,
        "action_plan": action_plan,
        "global_blockers": global_blockers,
    }



def _strategy_candidate_deep_dive_v22_pack(
    comp: pd.DataFrame,
    diagnostics: dict[str, Any] | None = None,
    metrics: dict[str, Any] | None = None,
    integrity: int | float = 0,
) -> dict[str, Any]:
    """
    Strategy Research Layer V2.2 — Candidate Deep Dive.

    Lecture seule :
    - ne relance pas le moteur ;
    - ne modifie pas les signaux ;
    - ne modifie pas les trades ;
    - ne modifie pas l'equity curve ;
    - ne modifie pas le verdict.

    Objectif :
    produire une fiche par stratégie :
    strengths, weaknesses, reason for rejection, retest conditions,
    next experiment et kill criteria.
    """
    diagnostics = diagnostics if isinstance(diagnostics, dict) else {}
    metrics = metrics if isinstance(metrics, dict) else {}

    empty = {
        "level": "Unavailable",
        "score": np.nan,
        "read": "Strategy tournament indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "deep_dive": pd.DataFrame(),
        "experiment_queue": pd.DataFrame(),
    }

    if comp is None or not isinstance(comp, pd.DataFrame) or comp.empty:
        return empty

    view = comp.copy()

    def _col(name: str, default: Any = "") -> pd.Series:
        if name in view.columns:
            return view[name]
        return pd.Series(default, index=view.index)

    def _num_text(value: Any) -> float:
        try:
            txt = (
                str(value)
                .replace("/100", "")
                .replace("$", "")
                .replace(",", "")
                .replace("%", "")
                .strip()
            )
            if txt in {"", "N/A", "nan", "None"}:
                return np.nan
            return float(txt)
        except Exception:
            return np.nan

    view["_score"] = _col("Tournament Score").map(_num_text)
    view["_alpha"] = _col("Alpha").map(_parse_pct_text)
    view["_return"] = _col("Return").map(_parse_pct_text)
    view["_maxdd"] = _col("Max DD").map(_parse_pct_text)
    view["_cvar"] = _col("CVaR 95").map(_parse_pct_text)
    view["_sharpe"] = _col("Sharpe").map(_num_text)
    view["_sortino"] = _col("Sortino").map(_num_text)
    view["_pf"] = _col("Profit Factor").map(_num_text)
    view["_trades"] = _col("Trades").map(_num_text)
    view["_integrity"] = _col("Test Integrity").map(_num_text)

    def _strategy_blockers(row: pd.Series) -> list[str]:
        blockers: list[str] = []

        ret = _safe_float(row.get("_return"), np.nan)
        alpha = _safe_float(row.get("_alpha"), np.nan)
        sharpe = _safe_float(row.get("_sharpe"), np.nan)
        sortino = _safe_float(row.get("_sortino"), np.nan)
        maxdd = _safe_float(row.get("_maxdd"), np.nan)
        cvar = _safe_float(row.get("_cvar"), np.nan)
        pf = _safe_float(row.get("_pf"), np.nan)
        trades = _safe_float(row.get("_trades"), np.nan)
        integrity_score = _safe_float(row.get("_integrity"), np.nan)
        bucket = str(row.get("Research Bucket", ""))
        verdict = str(row.get("Verdict", "")).upper()

        if pd.notna(ret) and ret <= 0:
            blockers.append("negative return")
        if pd.notna(alpha) and alpha <= 0:
            blockers.append("negative alpha")
        if pd.notna(sharpe) and sharpe < 0.50:
            blockers.append("weak Sharpe")
        if pd.notna(sortino) and sortino < 0.50:
            blockers.append("weak Sortino")
        if pd.notna(maxdd) and maxdd < -0.25:
            blockers.append("high drawdown")
        if pd.notna(cvar) and cvar < -0.035:
            blockers.append("large CVaR")
        if pd.notna(pf) and pf < 1.00:
            blockers.append("profit factor below 1")
        if pd.notna(trades) and trades < 10:
            blockers.append("low trade sample")
        if pd.notna(integrity_score) and integrity_score < 70:
            blockers.append("integrity below 70")
        if "Rejected" in bucket or verdict == "REJECTED":
            blockers.append("rejected by tournament")

        return list(dict.fromkeys(blockers))

    def _strategy_strengths(row: pd.Series) -> list[str]:
        strengths: list[str] = []

        ret = _safe_float(row.get("_return"), np.nan)
        alpha = _safe_float(row.get("_alpha"), np.nan)
        sharpe = _safe_float(row.get("_sharpe"), np.nan)
        sortino = _safe_float(row.get("_sortino"), np.nan)
        maxdd = _safe_float(row.get("_maxdd"), np.nan)
        cvar = _safe_float(row.get("_cvar"), np.nan)
        pf = _safe_float(row.get("_pf"), np.nan)
        trades = _safe_float(row.get("_trades"), np.nan)
        integrity_score = _safe_float(row.get("_integrity"), np.nan)
        bucket = str(row.get("Research Bucket", ""))

        if pd.notna(ret) and ret > 0:
            strengths.append("positive return")
        if pd.notna(alpha) and alpha > 0:
            strengths.append("positive alpha")
        if pd.notna(sharpe) and sharpe >= 0.80:
            strengths.append("acceptable Sharpe")
        if pd.notna(sortino) and sortino >= 1.00:
            strengths.append("acceptable Sortino")
        if pd.notna(maxdd) and maxdd > -0.15:
            strengths.append("controlled drawdown")
        if pd.notna(cvar) and cvar > -0.025:
            strengths.append("contained tail loss")
        if pd.notna(pf) and pf >= 1.20:
            strengths.append("profit factor above 1.2")
        if pd.notna(trades) and trades >= 10:
            strengths.append("usable trade sample")
        if pd.notna(integrity_score) and integrity_score >= 75:
            strengths.append("good test integrity")
        if bucket in {"Research candidate", "Watchlist"}:
            strengths.append(f"bucket: {bucket}")

        return list(dict.fromkeys(strengths))

    def _reason_for_rejection(blockers: list[str]) -> str:
        if "negative alpha" in blockers and "negative return" in blockers:
            return "No residual edge: strategy loses money and underperforms benchmark."
        if "negative alpha" in blockers:
            return "Benchmark-relative edge is negative."
        if "weak Sharpe" in blockers or "weak Sortino" in blockers:
            return "Risk-adjusted quality is insufficient."
        if "high drawdown" in blockers or "large CVaR" in blockers:
            return "Risk profile is too fragile for promotion."
        if "low trade sample" in blockers:
            return "Trade sample is too small for reliable inference."
        if "profit factor below 1" in blockers:
            return "Trade distribution is not profitable after losses."
        if "rejected by tournament" in blockers:
            return "Rejected by tournament score / bucket."
        return "No hard rejection driver detected."

    def _retest_conditions(row: pd.Series, blockers: list[str]) -> str:
        conditions = []

        if "negative alpha" in blockers:
            conditions.append("alpha > 0 vs benchmark")
        if "negative return" in blockers:
            conditions.append("total return > 0")
        if "weak Sharpe" in blockers:
            conditions.append("Sharpe >= 0.5 minimum, ideally >= 1.0")
        if "high drawdown" in blockers:
            conditions.append("max drawdown > -25%")
        if "large CVaR" in blockers:
            conditions.append("CVaR 95 better than -3.5%")
        if "low trade sample" in blockers:
            conditions.append(">= 10 trades minimum")
        if "profit factor below 1" in blockers:
            conditions.append("profit factor > 1.1")

        if not conditions:
            conditions.append("maintain alpha > 0, Sharpe > 0.8 and drawdown < 25%")

        return "; ".join(conditions)

    def _next_experiment(row: pd.Series, blockers: list[str]) -> str:
        strategy = str(row.get("Strategy", ""))

        if "negative alpha" in blockers:
            if "Trend" in strategy or strategy in {"SMA Trend", "Volatility Filter Trend"}:
                return "Test regime filter and benchmark-neutral trend variant before exit optimization."
            if "Breakout" in strategy:
                return "Retest breakout window and volatility confirmation; avoid pure price breakout."
            if "RSI" in strategy:
                return "Retest RSI thresholds with regime filter; avoid mean reversion in persistent trend regime."
            return "Redesign signal source; do not optimize exits before fixing alpha."

        if "weak Sharpe" in blockers:
            return "Add noise filter, volatility gate, or regime filter; measure Sharpe/OOS impact."

        if "high drawdown" in blockers or "large CVaR" in blockers:
            return "Retest with Risk Layer, drawdown cut, CVaR-aware sizing, and OHLC stop execution."

        if "low trade sample" in blockers:
            return "Extend historical window or lower timeframe before drawing conclusions."

        if "profit factor below 1" in blockers:
            return "Analyze trade distribution; improve entry selectivity or loss control."

        return "Run controlled retest on longer window and verify OOS / walk-forward stability."

    def _kill_criteria(blockers: list[str]) -> str:
        criteria = [
            "alpha remains <= 0 after retest",
            "OOS gates remain failed",
        ]

        if "high drawdown" in blockers:
            criteria.append("max DD remains worse than -30%")
        if "large CVaR" in blockers:
            criteria.append("CVaR 95 remains worse than -4%")
        if "low trade sample" in blockers:
            criteria.append("trade sample remains below 10")
        if "weak Sharpe" in blockers:
            criteria.append("Sharpe remains below 0.5")

        return "; ".join(list(dict.fromkeys(criteria)))

    def _grade(row: pd.Series, blockers: list[str], strengths: list[str]) -> str:
        score = _safe_float(row.get("_score"), np.nan)
        alpha = _safe_float(row.get("_alpha"), np.nan)
        sharpe = _safe_float(row.get("_sharpe"), np.nan)
        maxdd = _safe_float(row.get("_maxdd"), np.nan)
        trades = _safe_float(row.get("_trades"), np.nan)
        bucket = str(row.get("Research Bucket", ""))

        if (
            pd.notna(score)
            and score >= 75
            and pd.notna(alpha)
            and alpha > 0
            and pd.notna(sharpe)
            and sharpe >= 1.0
            and pd.notna(maxdd)
            and maxdd > -0.25
            and pd.notna(trades)
            and trades >= 10
            and len(blockers) <= 1
        ):
            return "A / paper-test review"

        if (
            pd.notna(score)
            and score >= 55
            and len(blockers) <= 3
            and bucket in {"Watchlist", "Research candidate", "Fragile"}
        ):
            return "B / controlled retest"

        if pd.notna(score) and score >= 40 and len(blockers) <= 4:
            return "C / revise rules"

        if "negative alpha" in blockers or "negative return" in blockers:
            return "D / redesign signal"

        return "F / reject"

    rows = []
    experiment_rows = []

    for _, row in view.iterrows():
        blockers = _strategy_blockers(row)
        strengths = _strategy_strengths(row)
        grade = _grade(row, blockers, strengths)
        reason = _reason_for_rejection(blockers)
        retest = _retest_conditions(row, blockers)
        next_exp = _next_experiment(row, blockers)
        kill = _kill_criteria(blockers)

        score = _safe_float(row.get("_score"), 0.0)
        alpha = _safe_float(row.get("_alpha"), 0.0)
        sharpe = _safe_float(row.get("_sharpe"), 0.0)
        maxdd = _safe_float(row.get("_maxdd"), -1.0)

        priority = (
            score
            + max(alpha, -0.25) * 100.0
            + max(sharpe, -1.0) * 4.0
            + max(maxdd, -0.60) * 15.0
            + len(strengths) * 4.0
            - len(blockers) * 7.0
        )

        priority = max(0.0, min(100.0, float(priority)))

        strategy = str(row.get("Strategy", "N/A"))
        variant = str(row.get("Execution Variant", "N/A"))

        decision = "Reject / redesign"

        if "A / paper-test" in grade:
            decision = "Paper-test review"
        elif "B / controlled retest" in grade:
            decision = "Controlled retest"
        elif "C / revise" in grade:
            decision = "Revise rules"
        elif "D / redesign" in grade:
            decision = "Redesign signal"

        rows.append(
            {
                "Rank": row.get("Rank", "N/A"),
                "Strategy": strategy,
                "Variant": variant,
                "Current": row.get("Current Config", "No"),
                "Bucket": row.get("Research Bucket", "N/A"),
                "Verdict": row.get("Verdict", "N/A"),
                "Tournament Score": row.get("Tournament Score", "N/A"),
                "Review Priority": f"{_format_num(priority, 0)}/100",
                "Grade": grade,
                "Decision": decision,
                "Return": row.get("Return", "N/A"),
                "Alpha": row.get("Alpha", "N/A"),
                "Sharpe": row.get("Sharpe", "N/A"),
                "Max DD": row.get("Max DD", "N/A"),
                "CVaR 95": row.get("CVaR 95", "N/A"),
                "Trades": row.get("Trades", "N/A"),
                "Strengths": "; ".join(strengths) if strengths else "None",
                "Weaknesses": "; ".join(blockers) if blockers else "None",
                "Reason for Rejection": reason,
                "Retest Conditions": retest,
                "Next Experiment": next_exp,
                "Kill Criteria": kill,
            }
        )

        experiment_rows.append(
            {
                "Priority": f"{_format_num(priority, 0)}/100",
                "Strategy": strategy,
                "Variant": variant,
                "Decision": decision,
                "Objective": reason,
                "Change To Test": next_exp,
                "Success Criteria": retest,
                "Failure / Kill Criteria": kill,
                "Risk": "High" if len(blockers) >= 4 else ("Medium" if len(blockers) >= 2 else "Low"),
            }
        )

    deep_dive = pd.DataFrame(rows)
    experiment_queue = pd.DataFrame(experiment_rows)

    if not deep_dive.empty:
        deep_dive["_sort"] = deep_dive["Review Priority"].map(lambda x: _num_text(x))
        deep_dive = deep_dive.sort_values("_sort", ascending=False).drop(columns=["_sort"]).reset_index(drop=True)

    if not experiment_queue.empty:
        experiment_queue["_sort"] = experiment_queue["Priority"].map(lambda x: _num_text(x))
        experiment_queue = experiment_queue.sort_values("_sort", ascending=False).drop(columns=["_sort"]).reset_index(drop=True)

    blocker_flat = []

    if not deep_dive.empty and "Weaknesses" in deep_dive.columns:
        for txt in deep_dive["Weaknesses"].astype(str).tolist():
            if txt != "None":
                blocker_flat += [x.strip() for x in txt.split(";") if x.strip()]

    blocker_counts = pd.Series(blocker_flat).value_counts() if blocker_flat else pd.Series(dtype=int)
    dominant_blocker = str(blocker_counts.index[0]) if not blocker_counts.empty else "None"

    actionable = int(deep_dive["Decision"].astype(str).str.contains("Paper-test|Controlled retest", case=False, regex=True).sum()) if not deep_dive.empty else 0
    redesign = int(deep_dive["Decision"].astype(str).str.contains("Redesign", case=False, regex=False).sum()) if not deep_dive.empty else 0
    reject = int(deep_dive["Decision"].astype(str).str.contains("Reject", case=False, regex=False).sum()) if not deep_dive.empty else 0

    best_name = "N/A"
    best_decision = "N/A"
    best_priority = np.nan

    if not deep_dive.empty:
        best = deep_dive.iloc[0]
        best_name = str(best.get("Strategy", "N/A"))
        best_decision = str(best.get("Decision", "N/A"))
        best_priority = _num_text(best.get("Review Priority", np.nan))

    current_rows = deep_dive[deep_dive.get("Current", "No").astype(str).str.upper().eq("YES")] if not deep_dive.empty else pd.DataFrame()
    current_decision = str(current_rows.iloc[0].get("Decision", "N/A")) if not current_rows.empty else "N/A"

    global_blockers = []

    pbo = _safe_float(diagnostics.get("pbo_proxy"), np.nan)
    dsr = _safe_float(diagnostics.get("dsr_proxy"), np.nan)

    if pd.notna(pbo) and pbo >= 0.65:
        global_blockers.append("high PBO / overfit risk")
    if pd.notna(dsr) and dsr < 0.30:
        global_blockers.append("weak DSR proxy")

    oos_pack = diagnostics.get("oos_v2", {})
    if isinstance(oos_pack, dict) and "failed" in str(oos_pack.get("level", "")).lower():
        global_blockers.append("OOS failed")

    if actionable > 0:
        level = "Actionable retest candidates"
        score = 60.0
        read = "Au moins une stratégie mérite une revue contrôlée avant rejet final."
    elif redesign > 0:
        level = "Redesign required"
        score = 30.0
        read = "Le tournament exige surtout une reprise du signal ou du régime, pas une optimisation de sortie."
    else:
        level = "Reject universe"
        score = 15.0
        read = "Aucun candidat ne mérite une promotion dans l'état actuel."

    if global_blockers:
        score = max(0.0, score - min(25.0, len(global_blockers) * 6.0))
        read = read + " Blockers globaux présents : " + "; ".join(global_blockers) + "."

    summary = pd.DataFrame(
        [
            ["Deep dive level", level, "Lecture synthétique du Candidate Deep Dive."],
            ["Deep dive score", f"{_format_num(score, 0)}/100", "Score de revue candidat, pénalisé par blockers globaux."],
            ["Strategies reviewed", str(len(deep_dive)), "Nombre de stratégies analysées."],
            ["Actionable candidates", str(actionable), "Paper-test review ou controlled retest."],
            ["Redesign candidates", str(redesign), "Stratégies nécessitant une refonte du signal."],
            ["Reject candidates", str(reject), "Stratégies à rejeter dans l'état actuel."],
            ["Best review target", best_name, "Stratégie prioritaire pour analyse détaillée."],
            ["Best decision", best_decision, "Décision associée au meilleur candidat."],
            ["Best priority", f"{_format_num(best_priority, 0)}/100", "Priorité de revue du meilleur candidat."],
            ["Current decision", current_decision, "Décision pour la configuration actuellement testée."],
            ["Dominant blocker", dominant_blocker, "Blocage le plus fréquent dans le tournament."],
            ["Global blockers", "; ".join(global_blockers) if global_blockers else "None", "Blockers macro du research layer."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    cards = [
        {
            "label": "Deep dive",
            "value": level,
            "delta": f"{_format_num(score, 0)}/100",
        },
        {
            "label": "Best review target",
            "value": best_name,
            "delta": best_decision,
        },
        {
            "label": "Best priority",
            "value": f"{_format_num(best_priority, 0)}/100",
            "delta": "review score",
        },
        {
            "label": "Actionable",
            "value": str(actionable),
            "delta": "retest/paper",
        },
        {
            "label": "Redesign",
            "value": str(redesign),
            "delta": "signal work",
        },
        {
            "label": "Dominant blocker",
            "value": dominant_blocker,
            "delta": "failure mode",
        },
    ]

    return {
        "level": level,
        "score": score,
        "read": read,
        "cards": cards,
        "summary": summary,
        "deep_dive": deep_dive,
        "experiment_queue": experiment_queue,
        "dominant_blocker": dominant_blocker,
        "global_blockers": global_blockers,
    }


def _render_strategy_candidate_deep_dive_v22(
    comp: pd.DataFrame,
    diagnostics: dict[str, Any],
    metrics: dict[str, Any],
    integrity: int | float,
) -> dict[str, Any]:
    """
    Rendu Streamlit Candidate Deep Dive V2.2.
    Lecture seule.
    """
    pack = _strategy_candidate_deep_dive_v22_pack(
        comp=comp,
        diagnostics=diagnostics,
        metrics=metrics,
        integrity=integrity,
    )

    st.subheader("Candidate Deep Dive V2.2")
    st.caption(
        "Fiche détaillée par stratégie : forces, faiblesses, raison de rejet, conditions de retest, "
        "prochaine expérience et critères de kill. Lecture seule : aucun impact sur le moteur, "
        "les trades, l'equity curve ou le verdict."
    )

    _card_grid(pack.get("cards", []), columns=6)

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))

    if "Actionable" in level:
        st.info(f"Lecture deep dive : {read}")
    elif "Redesign" in level:
        st.warning(f"Lecture deep dive : {read}")
    elif "Reject" in level:
        st.warning(f"Lecture deep dive : {read}")
    else:
        st.info(f"Lecture deep dive : {read}")

    summary = pack.get("summary", pd.DataFrame())
    deep_dive = pack.get("deep_dive", pd.DataFrame())
    experiment_queue = pack.get("experiment_queue", pd.DataFrame())

    with st.expander("Candidate deep dive matrix V2.2", expanded=True):
        if isinstance(deep_dive, pd.DataFrame) and not deep_dive.empty:
            st.dataframe(deep_dive, use_container_width=True, hide_index=True)
        else:
            st.info("Candidate deep dive indisponible.")

    with st.expander("Per-strategy experiment queue V2.2", expanded=True):
        if isinstance(experiment_queue, pd.DataFrame) and not experiment_queue.empty:
            st.dataframe(experiment_queue, use_container_width=True, hide_index=True)
        else:
            st.info("Experiment queue indisponible.")

    with st.expander("Deep dive summary V2.2", expanded=False):
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé deep dive indisponible.")

    experiment_designer_v23 = _render_strategy_experiment_designer_v23(
        candidate_pack=pack,
        diagnostics=diagnostics,
        metrics=metrics,
        integrity=integrity,
    )
    pack["experiment_designer_v23"] = experiment_designer_v23

    d1, d2, d3 = st.columns(3)

    if isinstance(deep_dive, pd.DataFrame) and not deep_dive.empty:
        d1.download_button(
            "Télécharger candidate deep dive CSV",
            data=deep_dive.to_csv(index=False).encode("utf-8"),
            file_name="strategy_candidate_deep_dive_v22.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_strategy_candidate_deep_dive_v22_download",
        )

    if isinstance(experiment_queue, pd.DataFrame) and not experiment_queue.empty:
        d2.download_button(
            "Télécharger experiment queue CSV",
            data=experiment_queue.to_csv(index=False).encode("utf-8"),
            file_name="strategy_experiment_queue_v22.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_strategy_experiment_queue_v22_download",
        )

    if isinstance(summary, pd.DataFrame) and not summary.empty:
        d3.download_button(
            "Télécharger deep dive summary CSV",
            data=summary.to_csv(index=False).encode("utf-8"),
            file_name="strategy_deep_dive_summary_v22.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_strategy_deep_dive_summary_v22_download",
        )

    return pack




def _strategy_experiment_designer_v23_pack(
    candidate_pack: dict[str, Any],
    diagnostics: dict[str, Any] | None = None,
    metrics: dict[str, Any] | None = None,
    integrity: int | float = 0,
) -> dict[str, Any]:
    """
    Strategy Experiment Designer V2.3.

    Lecture seule :
    - ne relance pas le moteur ;
    - ne modifie pas les signaux ;
    - ne modifie pas les trades ;
    - ne modifie pas l'equity curve ;
    - ne modifie pas le verdict.

    Objectif :
    transformer Candidate Deep Dive V2.2 en protocole d'expériences :
    hypothèse, changement à tester, grille de paramètres, succès/échec,
    OOS protocol, cost guard et promotion gate.
    """
    diagnostics = diagnostics if isinstance(diagnostics, dict) else {}
    metrics = metrics if isinstance(metrics, dict) else {}
    candidate_pack = candidate_pack if isinstance(candidate_pack, dict) else {}

    deep_dive = candidate_pack.get("deep_dive", pd.DataFrame())
    experiment_queue = candidate_pack.get("experiment_queue", pd.DataFrame())

    empty = {
        "level": "Unavailable",
        "score": np.nan,
        "read": "Candidate Deep Dive V2.2 indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "experiments": pd.DataFrame(),
        "parameter_plan": pd.DataFrame(),
        "protocol": pd.DataFrame(),
    }

    if not isinstance(experiment_queue, pd.DataFrame) or experiment_queue.empty:
        return empty

    if not isinstance(deep_dive, pd.DataFrame):
        deep_dive = pd.DataFrame()

    def _priority_num(value: Any) -> float:
        try:
            txt = str(value).replace("/100", "").replace("%", "").strip()
            if txt in {"", "N/A", "nan", "None"}:
                return 0.0
            return float(txt)
        except Exception:
            return 0.0

    def _match_deep_row(strategy: str, variant: str) -> pd.Series:
        if deep_dive.empty:
            return pd.Series(dtype=object)

        mask = deep_dive.get("Strategy", pd.Series("", index=deep_dive.index)).astype(str).eq(str(strategy))

        if "Variant" in deep_dive.columns:
            mask = mask & deep_dive["Variant"].astype(str).eq(str(variant))

        hit = deep_dive.loc[mask]

        if hit.empty:
            hit = deep_dive.loc[
                deep_dive.get("Strategy", pd.Series("", index=deep_dive.index)).astype(str).eq(str(strategy))
            ]

        if hit.empty:
            return pd.Series(dtype=object)

        return hit.iloc[0]

    def _infer_hypothesis(strategy: str, objective: str, weaknesses: str, change: str) -> str:
        txt = f"{strategy} {objective} {weaknesses} {change}".lower()

        if "negative alpha" in txt or "benchmark-relative" in txt:
            return "A regime-aware or benchmark-neutral signal variant can turn raw directionality into positive residual alpha."

        if "oos" in txt or "overfit" in txt:
            return "The candidate is only useful if the edge survives unseen windows and reduced research degrees of freedom."

        if "sharpe" in txt or "noise" in txt:
            return "A stricter noise filter can improve risk-adjusted returns without killing the trade sample."

        if "drawdown" in txt or "cvar" in txt or "tail" in txt:
            return "Risk overlay and sizing constraints can reduce tail loss without destroying alpha."

        if "low trade sample" in txt or "sample" in txt:
            return "The signal needs a larger validation window before any conclusion is statistically acceptable."

        if "breakout" in str(strategy).lower():
            return "Breakout quality improves if price breakout is confirmed by volatility and trend regime."

        if "rsi" in str(strategy).lower():
            return "Mean reversion should only be tested inside regimes where reversal behaviour is historically present."

        return "The next experiment must isolate whether the failure comes from signal design, regime filter, or risk layer."

    def _infer_test_type(strategy: str, decision: str, weaknesses: str, change: str) -> str:
        txt = f"{strategy} {decision} {weaknesses} {change}".lower()

        if "redesign" in txt:
            return "Signal redesign"

        if "regime" in txt:
            return "Regime filter test"

        if "risk" in txt or "drawdown" in txt or "cvar" in txt:
            return "Risk overlay test"

        if "breakout" in txt or "rsi" in txt or "sma" in txt:
            return "Parameter retest"

        return "Controlled retest"

    def _infer_parameter_grid(strategy: str, change: str, weaknesses: str) -> list[dict[str, str]]:
        strategy_txt = str(strategy)
        txt = f"{strategy} {change} {weaknesses}".lower()

        rows: list[dict[str, str]] = []

        def add(parameter: str, baseline: str, test_grid: str, rationale: str) -> None:
            rows.append(
                {
                    "Parameter": parameter,
                    "Baseline": baseline,
                    "Test Grid": test_grid,
                    "Rationale": rationale,
                }
            )

        if "volatility filter" in strategy_txt.lower():
            add("fast_ma", "current config", "20, 30, 50", "Tester la vitesse du signal trend.")
            add("slow_ma", "current config", "100, 150, 200", "Tester la persistance du régime.")
            add("vol_threshold", "current config", "20%, 30%, 40%, disabled", "Vérifier si le filtre vol crée ou détruit l'alpha.")
            add("benchmark neutral check", "Ticker Buy & Hold", "Ticker, SPY, QQQ, Sector ETF", "Identifier si l'alpha négatif vient du benchmark choisi.")
            add("regime gate", "off", "price > SMA200, benchmark momentum > 0, vol regime low/medium", "Ne tester le trend que dans des régimes porteurs.")

        elif "breakout" in strategy_txt.lower():
            add("breakout_window", "current config", "20, 55, 100", "Évaluer si le breakout court est trop bruité.")
            add("vol confirmation", "off", "on/off + vol < 20/30/40%", "Éviter les faux breakouts en régime instable.")
            add("trend confirmation", "off", "close > SMA100 / SMA200", "Limiter les breakouts contre-régime.")
            add("risk stop", "current config", "5%, 8%, 12%", "Contrôler CVaR et drawdown.")
            add("minimum sample", "current sample", ">= 10 trades", "Ne pas promouvoir un signal avec échantillon trop faible.")

        elif "rsi" in strategy_txt.lower():
            add("rsi_window", "current config", "10, 14, 21", "Tester la vitesse du mean reversion.")
            add("rsi_entry", "current config", "25, 30, 35", "Tester le seuil d'entrée.")
            add("rsi_exit", "current config", "50, 55, 60", "Tester la normalisation de sortie.")
            add("regime filter", "off", "trend weak / volatility medium / benchmark flat", "Éviter le mean reversion en tendance persistante.")
            add("max holding", "off/current", "5, 10, 20 bars", "Limiter les trades qui ne mean-revert pas rapidement.")

        elif "sma" in strategy_txt.lower() or "trend" in strategy_txt.lower():
            add("fast_ma", "current config", "10, 20, 50", "Tester la vitesse du trend.")
            add("slow_ma", "current config", "100, 150, 200", "Tester la définition du régime.")
            add("benchmark neutral check", "Ticker Buy & Hold", "Ticker, SPY, QQQ, Sector ETF", "Séparer beta timing et alpha résiduel.")
            add("risk layer", "off/current", "stop 5/8/12%, trailing 8/10/15%", "Réduire drawdown seulement après alpha brut positif.")
            add("OOS gate", "current", "60/40 split + 5 WF windows", "Éviter la promotion si l'edge ne survit pas hors-échantillon.")

        elif "manual" in strategy_txt.lower() or "decision" in strategy_txt.lower():
            add("signal components", "current config", "trend only, momentum only, trend+momentum, trend+vol", "Isoler le composant qui détruit l'alpha.")
            add("entry threshold", "current config", "strict / neutral / permissive", "Tester la sélectivité d'entrée.")
            add("regime filter", "off", "benchmark positive, low vol, risk-on only", "Limiter les signaux aux régimes exploitables.")
            add("risk layer", "off/current", "disabled until alpha > 0", "Ne pas optimiser les sorties avant edge signal.")
            add("research degrees", "current", "reduce active choices by 50%", "Réduire le risque d'overfit.")

        else:
            add("signal source", "current config", "baseline, stricter entry, regime-gated entry", "Identifier si le signal contient un edge brut.")
            add("benchmark mode", "current", "Ticker, SPY, QQQ, Sector ETF", "Tester la robustesse de l'alpha.")
            add("risk layer", "current", "off, stop, trailing, max holding", "Tester le profil de risque après alpha positif.")
            add("OOS protocol", "current", "60/40 split + walk-forward", "Contrôle anti-overfit minimal.")

        if "negative alpha" in txt:
            add("alpha gate", "failed", "alpha > 0 required before exit optimization", "Bloquer l'optimisation des sorties si l'edge benchmark est négatif.")

        if "low trade sample" in txt:
            add("sample window", "current", "2y / 3y / 5y or higher-frequency validation", "Augmenter la taille d'échantillon avant conclusion.")

        return rows

    def _risk_level_to_protocol(risk: str, global_blockers: list[str]) -> str:
        risk_txt = str(risk).lower()
        blockers_txt = " ".join([str(x).lower() for x in global_blockers])

        if "high" in risk_txt or "oos" in blockers_txt or "overfit" in blockers_txt:
            return "Strict: 60/40 IS/OOS, 5 walk-forward windows, no promotion if OOS alpha <= 0 or PBO >= 65%."

        if "medium" in risk_txt:
            return "Standard: 60/40 IS/OOS, walk-forward review, promotion only if alpha and Sharpe improve together."

        return "Light: verify no deterioration in alpha, Sharpe, max DD and costs."

    global_blockers = candidate_pack.get("global_blockers", [])
    if not isinstance(global_blockers, list):
        global_blockers = []

    pbo = _safe_float(diagnostics.get("pbo_proxy"), np.nan)
    dsr = _safe_float(diagnostics.get("dsr_proxy"), np.nan)
    psr = _safe_float(diagnostics.get("psr_proxy"), np.nan)

    cost_drag = _safe_float(metrics.get("Cost Drag"), np.nan)
    alpha = _safe_float(metrics.get("Relative Alpha"), np.nan)
    sharpe = _safe_float(metrics.get("Sharpe"), np.nan)
    max_dd = _safe_float(metrics.get("Max Drawdown"), np.nan)

    experiment_rows = []
    parameter_rows = []

    for i, (_, row) in enumerate(experiment_queue.iterrows(), start=1):
        strategy = str(row.get("Strategy", "N/A"))
        variant = str(row.get("Variant", "N/A"))
        decision = str(row.get("Decision", "N/A"))
        objective = str(row.get("Objective", "N/A"))
        change = str(row.get("Change To Test", "N/A"))
        success = str(row.get("Success Criteria", "N/A"))
        kill = str(row.get("Failure / Kill Criteria", row.get("Kill Criteria", "N/A")))
        risk = str(row.get("Risk", "Medium"))
        priority = _priority_num(row.get("Priority", 0))

        deep_row = _match_deep_row(strategy, variant)

        weaknesses = str(deep_row.get("Weaknesses", "N/A")) if not deep_row.empty else "N/A"
        strengths = str(deep_row.get("Strengths", "N/A")) if not deep_row.empty else "N/A"
        grade = str(deep_row.get("Grade", "N/A")) if not deep_row.empty else "N/A"

        hypothesis = _infer_hypothesis(strategy, objective, weaknesses, change)
        test_type = _infer_test_type(strategy, decision, weaknesses, change)
        oos_protocol = _risk_level_to_protocol(risk, global_blockers)

        cost_guard = (
            "Retest must remain acceptable under +5/+10 bps fee-slippage stress; do not promote if edge disappears after realistic costs."
        )

        promotion_gate = (
            "Promote only if alpha > 0, Sharpe >= 0.5, max DD > -25%, OOS gate passes, "
            "and no critical causality/data integrity failure appears."
        )

        if pd.notna(pbo):
            promotion_gate += f" Current PBO proxy={_format_pct(pbo, 0)}; require improvement below 65%."

        if pd.notna(dsr):
            promotion_gate += f" Current DSR proxy={_format_pct(dsr, 0)}; require improvement above 30%."

        do_not_optimize = "Exit rules" if "negative alpha" in weaknesses.lower() or "benchmark-relative" in objective.lower() else "None"

        if "negative alpha" in weaknesses.lower():
            evidence_required = "Show positive benchmark-relative alpha before testing exit improvements."
        elif "low trade sample" in weaknesses.lower():
            evidence_required = "Increase trade sample or window length before statistical promotion."
        elif "oos" in " ".join([str(x).lower() for x in global_blockers]):
            evidence_required = "Pass OOS and walk-forward gates before any paper-test."
        else:
            evidence_required = "Show simultaneous improvement in alpha, Sharpe, drawdown and cost robustness."

        expected_cost = (
            f"Current cost drag {_format_pct(cost_drag)}; experiment must survive stressed transaction costs."
            if pd.notna(cost_drag)
            else "Cost drag unavailable; include transaction-cost stress before promotion."
        )

        experiment_id = f"EXP-V23-{i:02d}"

        experiment_rows.append(
            {
                "Experiment ID": experiment_id,
                "Priority": f"{_format_num(priority, 0)}/100",
                "Strategy": strategy,
                "Variant": variant,
                "Current Grade": grade,
                "Decision": decision,
                "Test Type": test_type,
                "Hypothesis": hypothesis,
                "Objective": objective,
                "Change To Test": change,
                "Success Criteria": success,
                "Failure / Kill Criteria": kill,
                "OOS Protocol": oos_protocol,
                "Cost Guard": cost_guard,
                "Promotion Gate": promotion_gate,
                "Do Not Optimize Yet": do_not_optimize,
                "Evidence Required": evidence_required,
                "Risk": risk,
                "Expected Cost Read": expected_cost,
                "Strengths": strengths,
                "Weaknesses": weaknesses,
            }
        )

        for param_row in _infer_parameter_grid(strategy, change, weaknesses):
            parameter_rows.append(
                {
                    "Experiment ID": experiment_id,
                    "Strategy": strategy,
                    "Variant": variant,
                    "Parameter": param_row.get("Parameter", "N/A"),
                    "Baseline": param_row.get("Baseline", "N/A"),
                    "Test Grid": param_row.get("Test Grid", "N/A"),
                    "Rationale": param_row.get("Rationale", "N/A"),
                    "Guardrail": "No promotion without OOS pass and positive alpha.",
                }
            )

    experiments = pd.DataFrame(experiment_rows)
    parameter_plan = pd.DataFrame(parameter_rows)

    if not experiments.empty:
        experiments["_sort"] = experiments["Priority"].map(_priority_num)
        experiments = experiments.sort_values("_sort", ascending=False).drop(columns=["_sort"]).reset_index(drop=True)

    if not parameter_plan.empty and not experiments.empty:
        order = {eid: i for i, eid in enumerate(experiments["Experiment ID"].astype(str).tolist())}
        parameter_plan["_sort"] = parameter_plan["Experiment ID"].astype(str).map(order).fillna(999)
        parameter_plan = parameter_plan.sort_values("_sort").drop(columns=["_sort"]).reset_index(drop=True)

    high_risk = int(experiments["Risk"].astype(str).str.contains("High", case=False, regex=False).sum()) if not experiments.empty else 0
    redesign = int(experiments["Decision"].astype(str).str.contains("Redesign", case=False, regex=False).sum()) if not experiments.empty else 0
    retest = int(experiments["Decision"].astype(str).str.contains("Retest|Revise|Paper", case=False, regex=True).sum()) if not experiments.empty else 0

    top_experiment = "N/A"
    top_strategy = "N/A"
    top_priority = np.nan
    top_test_type = "N/A"

    if not experiments.empty:
        top = experiments.iloc[0]
        top_experiment = str(top.get("Experiment ID", "N/A"))
        top_strategy = str(top.get("Strategy", "N/A"))
        top_priority = _priority_num(top.get("Priority", 0))
        top_test_type = str(top.get("Test Type", "N/A"))

    protocol = pd.DataFrame(
        [
            [
                "1. Freeze baseline",
                "Freeze current code, config, benchmark, costs and data window.",
                "Baseline artifacts saved before experiment.",
                "No moving benchmark or costs after seeing results.",
            ],
            [
                "2. Define hypothesis",
                "Each experiment must test one explicit hypothesis.",
                "Hypothesis written before retest.",
                "No vague parameter mining.",
            ],
            [
                "3. Run minimal grid",
                "Use the proposed parameter plan only.",
                "Grid remains small and interpretable.",
                "Avoid expanding grid after seeing winners.",
            ],
            [
                "4. Validate OOS",
                "Use strict OOS / walk-forward when overfit, DSR or PBO blockers exist.",
                "OOS alpha > 0 and OOS Sharpe > 0.",
                "No paper-test if OOS fails.",
            ],
            [
                "5. Apply cost guard",
                "Retest with fee/slippage stress.",
                "Edge survives realistic cost stress.",
                "Reject if positive edge exists only at zero costs.",
            ],
            [
                "6. Promote or kill",
                "Promote only if promotion gate passes; otherwise kill or redesign.",
                "Decision logged with failure reason.",
                "Do not optimize exits before signal alpha exists.",
            ],
        ],
        columns=["Stage", "Action", "Pass Condition", "Guardrail"],
    )

    base_score = 20.0

    if retest > 0:
        base_score += min(30.0, retest * 8.0)

    if redesign > 0:
        base_score += min(20.0, redesign * 3.0)

    if high_risk > 0:
        base_score -= min(20.0, high_risk * 4.0)

    if pd.notna(pbo) and pbo >= 0.65:
        base_score -= 10.0

    if pd.notna(dsr) and dsr < 0.30:
        base_score -= 8.0

    if pd.notna(alpha) and alpha <= 0:
        base_score -= 8.0

    score = max(0.0, min(100.0, base_score))

    # V2.3 level guard:
    # un plan peut être généré techniquement, mais ne doit pas être affiché
    # comme "ready" si le score est très faible.
    if score < 25.0 and not experiments.empty:
        level = "Redesign plan required"
        read = (
            "Le plan expérimental existe, mais le score est trop faible pour le qualifier de ready. "
            "Priorité : reprendre le signal, réduire l'overfit et restaurer l'alpha avant toute promotion."
        )
    elif not experiments.empty and retest > 0:
        level = "Experiment plan ready"
        read = "Les recommandations V2.2 sont converties en protocole d'expériences contrôlées."
    elif redesign > 0:
        level = "Redesign plan required"
        read = "Le plan expérimental est surtout orienté refonte du signal avant toute optimisation de sortie."
    else:
        level = "No experiment promoted"
        read = "Aucune expérience ne mérite une promotion ; conserver uniquement les critères de rejet."

    if global_blockers:
        read = read + " Blockers globaux à respecter : " + "; ".join([str(x) for x in global_blockers]) + "."

    summary = pd.DataFrame(
        [
            ["Designer level", level, "Lecture synthétique de l'Experiment Designer."],
            ["Designer score", f"{_format_num(score, 0)}/100", "Score de maturité du plan expérimental."],
            ["Experiments designed", str(len(experiments)), "Nombre d'expériences candidates."],
            ["Retest / revise experiments", str(retest), "Expériences pouvant être testées de façon contrôlée."],
            ["Redesign experiments", str(redesign), "Expériences de refonte du signal."],
            ["High-risk experiments", str(high_risk), "Expériences à protocole strict."],
            ["Top experiment", top_experiment, "ID de l'expérience prioritaire."],
            ["Top strategy", top_strategy, "Stratégie prioritaire."],
            ["Top test type", top_test_type, "Type d'expérience prioritaire."],
            ["Top priority", f"{_format_num(top_priority, 0)}/100", "Priorité issue de V2.2."],
            ["Current alpha", _format_pct(alpha), "Alpha courant vs benchmark."],
            ["Current Sharpe", _format_num(sharpe), "Sharpe courant."],
            ["Current max DD", _format_pct(max_dd), "Drawdown courant."],
            ["Current PSR proxy", _format_pct(psr), "PSR proxy courant."],
            ["Current DSR proxy", _format_pct(dsr), "DSR proxy courant."],
            ["Current PBO proxy", _format_pct(pbo), "PBO proxy courant."],
            ["Global blockers", "; ".join([str(x) for x in global_blockers]) if global_blockers else "None", "Blockers globaux hérités du research layer."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    cards = [
        {
            "label": "Experiment designer",
            "value": level,
            "delta": f"{_format_num(score, 0)}/100",
        },
        {
            "label": "Top experiment",
            "value": top_experiment,
            "delta": top_strategy,
        },
        {
            "label": "Top priority",
            "value": f"{_format_num(top_priority, 0)}/100",
            "delta": top_test_type,
        },
        {
            "label": "Experiments",
            "value": str(len(experiments)),
            "delta": f"{retest} retest / {redesign} redesign",
        },
        {
            "label": "High-risk tests",
            "value": str(high_risk),
            "delta": "strict OOS",
        },
        {
            "label": "Main guardrail",
            "value": "Alpha first",
            "delta": "before exits",
        },
    ]

    return {
        "level": level,
        "score": score,
        "read": read,
        "cards": cards,
        "summary": summary,
        "experiments": experiments,
        "parameter_plan": parameter_plan,
        "protocol": protocol,
    }



def _strategy_experiment_runner_blueprint_v24_pack(
    experiment_designer_pack: dict[str, Any],
) -> dict[str, Any]:
    """
    Experiment Runner Blueprint V2.4.

    Lecture seule :
    - ne relance aucun backtest ;
    - ne modifie pas les signaux ;
    - ne modifie pas les trades ;
    - ne modifie pas l'equity curve ;
    - ne modifie pas le verdict.

    Objectif :
    transformer Strategy Experiment Designer V2.3 en plan d'exécution contrôlé :
    run queue, mutations de paramètres, freeze checklist, promotion gates,
    kill gates et statut d'exécution.
    """
    experiment_designer_pack = experiment_designer_pack if isinstance(experiment_designer_pack, dict) else {}

    experiments = experiment_designer_pack.get("experiments", pd.DataFrame())
    parameter_plan = experiment_designer_pack.get("parameter_plan", pd.DataFrame())
    protocol = experiment_designer_pack.get("protocol", pd.DataFrame())

    empty = {
        "level": "Unavailable",
        "score": np.nan,
        "read": "Experiment Designer V2.3 indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "blueprints": pd.DataFrame(),
        "run_queue": pd.DataFrame(),
        "freeze_checklist": pd.DataFrame(),
    }

    if not isinstance(experiments, pd.DataFrame) or experiments.empty:
        return empty

    if not isinstance(parameter_plan, pd.DataFrame):
        parameter_plan = pd.DataFrame()

    if not isinstance(protocol, pd.DataFrame):
        protocol = pd.DataFrame()

    def _priority_num(value: Any) -> float:
        try:
            txt = str(value).replace("/100", "").replace("%", "").strip()
            if txt in {"", "N/A", "nan", "None"}:
                return 0.0
            return float(txt)
        except Exception:
            return 0.0

    def _split_grid_values(value: Any) -> list[str]:
        txt = str(value if value is not None else "").strip()

        if txt in {"", "N/A", "nan", "None"}:
            return ["N/A"]

        # On garde le parsing simple et prudent :
        # une ligne = mutation one-factor-at-a-time, pas de combinatoire exhaustive.
        parts = [x.strip() for x in txt.split(",") if x.strip()]

        if not parts:
            parts = [txt]

        # Limite anti-explosion : blueprint, pas grid runner complet.
        return parts[:8]

    def _pick_col(row: pd.Series, names: list[str], default: str = "N/A") -> str:
        for name in names:
            if name in row.index:
                val = row.get(name)
                if str(val).strip() not in {"", "nan", "None"}:
                    return str(val)
        return default

    designer_level = str(experiment_designer_pack.get("level", "N/A"))
    designer_score = _safe_float(experiment_designer_pack.get("score"), np.nan)
    designer_read = str(experiment_designer_pack.get("read", ""))

    blueprint_rows = []
    run_rows = []

    run_counter = 1

    for idx, (_, exp) in enumerate(experiments.iterrows(), start=1):
        exp_id = str(exp.get("Experiment ID", f"EXP-V23-{idx:02d}"))
        strategy = str(exp.get("Strategy", "N/A"))
        variant = str(exp.get("Variant", "N/A"))
        priority = str(exp.get("Priority", "0/100"))
        priority_num = _priority_num(priority)
        decision = str(exp.get("Decision", "N/A"))
        test_type = str(exp.get("Test Type", "N/A"))
        hypothesis = str(exp.get("Hypothesis", "N/A"))
        objective = str(exp.get("Objective", "N/A"))
        change = str(exp.get("Change To Test", "N/A"))
        success = str(exp.get("Success Criteria", "N/A"))
        kill = str(exp.get("Failure / Kill Criteria", "N/A"))
        oos_protocol = str(exp.get("OOS Protocol", "N/A"))
        cost_guard = str(exp.get("Cost Guard", "N/A"))
        promotion_gate = str(exp.get("Promotion Gate", "N/A"))
        do_not_optimize = str(exp.get("Do Not Optimize Yet", "N/A"))
        evidence = str(exp.get("Evidence Required", "N/A"))
        risk = str(exp.get("Risk", "N/A"))

        params = pd.DataFrame()
        if not parameter_plan.empty and "Experiment ID" in parameter_plan.columns:
            params = parameter_plan[
                parameter_plan["Experiment ID"].astype(str).eq(exp_id)
            ].copy()

        parameter_count = int(len(params)) if isinstance(params, pd.DataFrame) else 0

        if parameter_count > 0:
            param_summary = "; ".join(
                [
                    f"{str(r.get('Parameter', 'N/A'))}: {str(r.get('Test Grid', 'N/A'))}"
                    for _, r in params.head(10).iterrows()
                ]
            )
        else:
            param_summary = "No parameter grid available."

        # V2.4 safety gate:
        # si le score V2.3 est trop faible, tous les blueprints restent bloqués.
        # On peut les afficher comme plan de travail, mais pas comme retest prêt.
        if pd.notna(designer_score) and designer_score < 25.0:
            runner_status = "BLOCKED / DESIGN ONLY"
        elif "redesign" in decision.lower() or priority_num <= 0:
            runner_status = "BLOCKED / DESIGN ONLY"
        elif "revise" in decision.lower() or "retest" in decision.lower() or priority_num > 0:
            runner_status = "READY AS MANUAL RETEST BLUEPRINT"
        else:
            runner_status = "DESIGN ONLY"

        if "negative alpha" in evidence.lower() or "alpha" in promotion_gate.lower():
            alpha_gate = "alpha > 0 before any exit optimization"
        else:
            alpha_gate = "positive edge evidence required"

        blueprint_id = f"BP-V24-{idx:02d}"

        blueprint_rows.append(
            {
                "Blueprint ID": blueprint_id,
                "Experiment ID": exp_id,
                "Priority": priority,
                "Strategy": strategy,
                "Variant": variant,
                "Decision": decision,
                "Test Type": test_type,
                "Runner Status": runner_status,
                "Execution Mode": "Manual retest blueprint only",
                "Hypothesis": hypothesis,
                "Objective": objective,
                "Change To Test": change,
                "Parameter Plan": param_summary,
                "Parameter Count": parameter_count,
                "OOS Protocol": oos_protocol,
                "Cost Guard": cost_guard,
                "Success Criteria": success,
                "Kill Criteria": kill,
                "Promotion Gate": promotion_gate,
                "Alpha Gate": alpha_gate,
                "Do Not Optimize Yet": do_not_optimize,
                "Evidence Required": evidence,
                "Risk": risk,
                "Engine Impact": "None",
                "Run State": "NOT EXECUTED",
            }
        )

        if parameter_count > 0:
            for _, param in params.iterrows():
                parameter = str(param.get("Parameter", "N/A"))
                baseline = str(param.get("Baseline", "N/A"))
                test_grid = str(param.get("Test Grid", "N/A"))
                rationale = str(param.get("Rationale", "N/A"))
                guardrail = str(param.get("Guardrail", "No promotion without OOS pass and positive alpha."))

                for candidate_value in _split_grid_values(test_grid):
                    run_rows.append(
                        {
                            "Run ID": f"RUN-V24-{run_counter:03d}",
                            "Blueprint ID": blueprint_id,
                            "Experiment ID": exp_id,
                            "Strategy": strategy,
                            "Variant": variant,
                            "Priority": priority,
                            "Decision": decision,
                            "Test Type": test_type,
                            "Parameter": parameter,
                            "Baseline": baseline,
                            "Candidate Value": candidate_value,
                            "Mutation": f"{parameter} = {candidate_value}",
                            "Rationale": rationale,
                            "Success Gate": success,
                            "Kill Gate": kill,
                            "Promotion Gate": promotion_gate,
                            "OOS Protocol": oos_protocol,
                            "Cost Guard": cost_guard,
                            "Guardrail": guardrail,
                            "Run State": "NOT EXECUTED",
                            "Execution Permission": "Manual only",
                            "Engine Impact": "None - blueprint only",
                        }
                    )
                    run_counter += 1
        else:
            run_rows.append(
                {
                    "Run ID": f"RUN-V24-{run_counter:03d}",
                    "Blueprint ID": blueprint_id,
                    "Experiment ID": exp_id,
                    "Strategy": strategy,
                    "Variant": variant,
                    "Priority": priority,
                    "Decision": decision,
                    "Test Type": test_type,
                    "Parameter": "full_experiment",
                    "Baseline": "current config",
                    "Candidate Value": change,
                    "Mutation": change,
                    "Rationale": objective,
                    "Success Gate": success,
                    "Kill Gate": kill,
                    "Promotion Gate": promotion_gate,
                    "OOS Protocol": oos_protocol,
                    "Cost Guard": cost_guard,
                    "Guardrail": "No auto-run. Manual retest only after baseline freeze.",
                    "Run State": "NOT EXECUTED",
                    "Execution Permission": "Manual only",
                    "Engine Impact": "None - blueprint only",
                }
            )
            run_counter += 1

    blueprints = pd.DataFrame(blueprint_rows)
    run_queue = pd.DataFrame(run_rows)

    if not blueprints.empty:
        blueprints["_sort"] = blueprints["Priority"].map(_priority_num)
        blueprints = blueprints.sort_values("_sort", ascending=False).drop(columns=["_sort"]).reset_index(drop=True)

    if not run_queue.empty:
        run_queue["_sort"] = run_queue["Priority"].map(_priority_num)
        run_queue = run_queue.sort_values(["_sort", "Run ID"], ascending=[False, True]).drop(columns=["_sort"]).reset_index(drop=True)

    freeze_checklist = pd.DataFrame(
        [
            [
                "1. Code freeze",
                "Save current stable backtest_lab.py before any retest.",
                "Stable copy exists.",
                "No code edit during result review.",
            ],
            [
                "2. Config freeze",
                "Record strategy, benchmark, costs, sizing, risk layer and data window.",
                "Baseline config recorded.",
                "Do not change benchmark after seeing results.",
            ],
            [
                "3. Data freeze",
                "Use the same price window for baseline and candidate runs.",
                "Same start/end dates.",
                "No cherry-picked date window.",
            ],
            [
                "4. One-factor-at-a-time",
                "Use V2.4 run queue as one-factor mutation list.",
                "Each run has one explicit mutation.",
                "No combinatorial expansion before OOS pass.",
            ],
            [
                "5. OOS protocol",
                "Apply the OOS protocol inherited from V2.3.",
                "OOS alpha > 0 and OOS Sharpe > 0.",
                "No promotion if OOS remains failed.",
            ],
            [
                "6. Cost guard",
                "Retest under realistic fee/slippage stress.",
                "Edge survives costs.",
                "Reject if edge only exists at zero costs.",
            ],
            [
                "7. Promotion gate",
                "Promote only if alpha, Sharpe, drawdown, OOS and causality gates pass.",
                "Promotion gate logged.",
                "No exit optimization before alpha exists.",
            ],
            [
                "8. Result ledger",
                "Save every run result, including failures.",
                "All runs logged.",
                "No deleting failed runs.",
            ],
        ],
        columns=["Stage", "Action", "Pass Condition", "Guardrail"],
    )

    ready_blueprints = int(
        blueprints["Runner Status"].astype(str).str.contains("READY", case=False, regex=False).sum()
    ) if not blueprints.empty and "Runner Status" in blueprints.columns else 0

    blocked_blueprints = int(
        blueprints["Runner Status"].astype(str).str.contains("BLOCKED", case=False, regex=False).sum()
    ) if not blueprints.empty and "Runner Status" in blueprints.columns else 0

    high_risk_runs = int(
        run_queue["Risk"].astype(str).str.contains("High", case=False, regex=False).sum()
    ) if not run_queue.empty and "Risk" in run_queue.columns else 0

    top_blueprint = "N/A"
    top_strategy = "N/A"
    top_experiment = "N/A"

    if not blueprints.empty:
        top = blueprints.iloc[0]
        top_blueprint = str(top.get("Blueprint ID", "N/A"))
        top_strategy = str(top.get("Strategy", "N/A"))
        top_experiment = str(top.get("Experiment ID", "N/A"))

    if pd.notna(designer_score) and designer_score < 25:
        level = "Blueprint drafted / redesign first"
        score = max(0.0, min(25.0, designer_score + 10.0))
        read = (
            "La run queue est construite, mais elle reste bloquée en design-only : "
            "le score V2.3 est trop faible pour autoriser une exécution expérimentale propre."
        )
    elif ready_blueprints > 0:
        level = "Blueprint ready / manual retest only"
        score = min(100.0, 35.0 + ready_blueprints * 10.0)
        read = "Les expériences V2.3 sont converties en blueprints de retest manuel contrôlé."
    else:
        level = "Blueprint unavailable"
        score = 0.0
        read = "Aucun blueprint exécutable n'est disponible."

    if designer_read:
        read = read + f" Lecture V2.3 : {designer_read}"

    summary = pd.DataFrame(
        [
            ["Runner blueprint level", level, "Lecture synthétique du blueprint runner."],
            ["Runner blueprint score", f"{_format_num(score, 0)}/100", "Score de maturité du blueprint, pas score de performance."],
            ["Designer level input", designer_level, "Niveau hérité de Strategy Experiment Designer V2.3."],
            ["Designer score input", f"{_format_num(designer_score, 0)}/100", "Score hérité de V2.3."],
            ["Blueprints", str(len(blueprints)), "Nombre de blueprints d'expérience."],
            ["Ready blueprints", str(ready_blueprints), "Blueprints prêts uniquement pour retest manuel."],
            ["Blocked blueprints", str(blocked_blueprints), "Blueprints bloqués en design-only."],
            ["Run queue rows", str(len(run_queue)), "Nombre de mutations one-factor-at-a-time."],
            ["High-risk runs", str(high_risk_runs), "Runs nécessitant protocole strict."],
            ["Top blueprint", top_blueprint, "Blueprint prioritaire."],
            ["Top experiment", top_experiment, "Expérience V2.3 prioritaire."],
            ["Top strategy", top_strategy, "Stratégie prioritaire."],
            ["Execution state", "NOT EXECUTED", "V2.4 prépare les runs mais ne les lance pas."],
            ["Main guardrail", "No auto-run", "Aucun retest automatique dans cette brique."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    cards = [
        {
            "label": "Runner blueprint",
            "value": level,
            "delta": f"{_format_num(score, 0)}/100",
        },
        {
            "label": "Blueprints",
            "value": str(len(blueprints)),
            "delta": f"{ready_blueprints} ready / {blocked_blueprints} blocked",
        },
        {
            "label": "Run queue",
            "value": str(len(run_queue)),
            "delta": "not executed",
        },
        {
            "label": "Top blueprint",
            "value": top_blueprint,
            "delta": top_strategy,
        },
        {
            "label": "High-risk runs",
            "value": str(high_risk_runs),
            "delta": "strict OOS",
        },
        {
            "label": "Execution",
            "value": "Not executed",
            "delta": "design only",
        },
    ]

    return {
        "level": level,
        "score": score,
        "read": read,
        "cards": cards,
        "summary": summary,
        "blueprints": blueprints,
        "run_queue": run_queue,
        "freeze_checklist": freeze_checklist,
    }


def _render_experiment_runner_blueprint_v24(
    experiment_designer_pack: dict[str, Any],
) -> dict[str, Any]:
    """
    Rendu Streamlit Experiment Runner Blueprint V2.4.
    Lecture seule.
    """
    pack = _strategy_experiment_runner_blueprint_v24_pack(experiment_designer_pack)

    st.subheader("Experiment Runner Blueprint V2.4")
    st.caption(
        "Convertit les plans V2.3 en run queue contrôlée : mutations one-factor-at-a-time, "
        "freeze checklist, OOS protocol, cost guard, promotion gate et kill gate. "
        "Lecture seule : aucun retest n'est lancé automatiquement."
    )

    _card_grid(pack.get("cards", []), columns=6)

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))

    if "redesign" in level.lower() or "blocked" in read.lower():
        st.warning(f"Lecture runner blueprint : {read}")
    elif "ready" in level.lower():
        st.info(f"Lecture runner blueprint : {read}")
    else:
        st.info(f"Lecture runner blueprint : {read}")

    blueprints = pack.get("blueprints", pd.DataFrame())
    run_queue = pack.get("run_queue", pd.DataFrame())
    freeze_checklist = pack.get("freeze_checklist", pd.DataFrame())
    summary = pack.get("summary", pd.DataFrame())

    with st.expander("Runner blueprint matrix V2.4", expanded=True):
        if isinstance(blueprints, pd.DataFrame) and not blueprints.empty:
            st.dataframe(blueprints, use_container_width=True, hide_index=True)
        else:
            st.info("Runner blueprint matrix indisponible.")

    with st.expander("Candidate run queue V2.4", expanded=True):
        if isinstance(run_queue, pd.DataFrame) and not run_queue.empty:
            st.dataframe(run_queue, use_container_width=True, hide_index=True)
        else:
            st.info("Candidate run queue indisponible.")

    with st.expander("Execution freeze checklist V2.4", expanded=True):
        if isinstance(freeze_checklist, pd.DataFrame) and not freeze_checklist.empty:
            st.dataframe(freeze_checklist, use_container_width=True, hide_index=True)
        else:
            st.info("Freeze checklist indisponible.")

    with st.expander("Runner blueprint summary V2.4", expanded=False):
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé Runner Blueprint indisponible.")

    d1, d2, d3 = st.columns(3)

    if isinstance(blueprints, pd.DataFrame) and not blueprints.empty:
        d1.download_button(
            "Télécharger runner blueprint CSV",
            data=blueprints.to_csv(index=False).encode("utf-8"),
            file_name="experiment_runner_blueprint_v24.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_experiment_runner_blueprint_v24_download",
        )

    if isinstance(run_queue, pd.DataFrame) and not run_queue.empty:
        d2.download_button(
            "Télécharger run queue CSV",
            data=run_queue.to_csv(index=False).encode("utf-8"),
            file_name="experiment_run_queue_v24.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_experiment_run_queue_v24_download",
        )

    if isinstance(freeze_checklist, pd.DataFrame) and not freeze_checklist.empty:
        d3.download_button(
            "Télécharger freeze checklist CSV",
            data=freeze_checklist.to_csv(index=False).encode("utf-8"),
            file_name="experiment_freeze_checklist_v24.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_experiment_freeze_checklist_v24_download",
        )

    controlled_retest_ledger_v25 = _render_controlled_retest_ledger_v25(pack)
    pack["controlled_retest_ledger_v25"] = controlled_retest_ledger_v25


    return pack



def _controlled_retest_ledger_v25_pack(
    runner_pack: dict[str, Any],
) -> dict[str, Any]:
    """
    Controlled Retest Ledger V2.5.
    Lecture seule : ne lance aucun retest, ne modifie pas le moteur,
    les trades, l'equity curve ou le verdict.
    """
    runner_pack = runner_pack if isinstance(runner_pack, dict) else {}

    run_queue = runner_pack.get("run_queue", pd.DataFrame())
    blueprints = runner_pack.get("blueprints", pd.DataFrame())
    runner_summary = runner_pack.get("summary", pd.DataFrame())

    if not isinstance(run_queue, pd.DataFrame):
        run_queue = pd.DataFrame()

    if not isinstance(blueprints, pd.DataFrame):
        blueprints = pd.DataFrame()

    if not isinstance(runner_summary, pd.DataFrame):
        runner_summary = pd.DataFrame()

    def _num_from_text(value: Any, default: float = 0.0) -> float:
        try:
            txt = str(value).replace("/100", "").replace("%", "").strip()
            if txt in {"", "N/A", "nan", "None"}:
                return default
            return float(txt)
        except Exception:
            return default

    def _summary_value(metric: str, default: Any = "N/A") -> Any:
        try:
            if runner_summary.empty or "Metric" not in runner_summary.columns or "Value" not in runner_summary.columns:
                return default
            hit = runner_summary.loc[runner_summary["Metric"].astype(str).eq(metric)]
            if hit.empty:
                return default
            return hit["Value"].iloc[0]
        except Exception:
            return default

    designer_score = _num_from_text(_summary_value("Designer score input", "0"), 0.0)
    runner_score = _safe_float(runner_pack.get("score"), np.nan)

    blueprint_status = {}
    blueprint_promotion = {}

    if not blueprints.empty and "Blueprint ID" in blueprints.columns:
        for _, row in blueprints.iterrows():
            bp = str(row.get("Blueprint ID", "")).strip()
            if not bp:
                continue
            blueprint_status[bp] = str(row.get("Runner Status", "N/A"))
            blueprint_promotion[bp] = str(row.get("Promotion Gate", "N/A"))

    if run_queue.empty:
        ledger = pd.DataFrame()
    else:
        ledger = run_queue.copy()

        for col in [
            "Run ID",
            "Blueprint ID",
            "Experiment ID",
            "Strategy",
            "Variant",
            "Priority",
            "Decision",
            "Test Type",
            "Parameter",
            "Baseline",
            "Candidate Value",
            "Mutation",
            "Execution Permission",
            "Run State",
        ]:
            if col not in ledger.columns:
                ledger[col] = "N/A"

        ledger.insert(
            0,
            "Retest ID",
            [f"RTL-V25-{i:03d}" for i in range(1, len(ledger) + 1)],
        )

        ledger["Blueprint Status"] = ledger["Blueprint ID"].astype(str).map(blueprint_status).fillna("N/A")
        ledger["Promotion Gate"] = ledger["Blueprint ID"].astype(str).map(blueprint_promotion).fillna("N/A")

        blocked_mask = (
            ledger["Blueprint Status"].astype(str).str.contains("BLOCKED|DESIGN", case=False, regex=True, na=False)
            | ledger["Run State"].astype(str).str.contains("BLOCKED|DESIGN", case=False, regex=True, na=False)
            | (designer_score < 25.0)
        )

        ledger["Retest State"] = np.where(
            blocked_mask,
            "BLOCKED / WAITING REDESIGN",
            "PENDING MANUAL RETEST",
        )

        ledger["Result Status"] = "NOT REVIEWED"
        ledger["Manual Result Logged"] = "No"

        ledger["Baseline Alpha"] = "from current report"
        ledger["Baseline Sharpe"] = "from current report"
        ledger["Baseline Max DD"] = "from current report"

        ledger["Candidate Alpha"] = ""
        ledger["Candidate Sharpe"] = ""
        ledger["Candidate Max DD"] = ""
        ledger["Candidate CVaR 95"] = ""
        ledger["Candidate PBO Proxy"] = ""
        ledger["Candidate DSR Proxy"] = ""

        ledger["OOS Gate"] = "NOT CHECKED"
        ledger["Cost Gate"] = "NOT CHECKED"
        ledger["Causality Gate"] = "NOT CHECKED"
        ledger["Data Integrity Gate"] = "NOT CHECKED"
        ledger["Promotion Gate Status"] = "NOT CHECKED"
        ledger["Kill Gate Status"] = "NOT CHECKED"

        ledger["Post-Run Decision"] = np.where(
            blocked_mask,
            "DO NOT RUN BEFORE REDESIGN",
            "AWAITING MANUAL RESULT",
        )

        ledger["Failure Reason"] = np.where(
            blocked_mask,
            "Designer/runner blueprint below execution threshold.",
            "",
        )

        ledger["Reviewer Note"] = ""

    ledger_rows = int(len(ledger)) if isinstance(ledger, pd.DataFrame) else 0

    blocked_rows = (
        int(ledger["Retest State"].astype(str).str.contains("BLOCKED", case=False, na=False).sum())
        if isinstance(ledger, pd.DataFrame) and not ledger.empty and "Retest State" in ledger.columns
        else 0
    )

    pending_rows = (
        int(ledger["Retest State"].astype(str).eq("PENDING MANUAL RETEST").sum())
        if isinstance(ledger, pd.DataFrame) and not ledger.empty and "Retest State" in ledger.columns
        else 0
    )

    logged_rows = (
        int(ledger["Manual Result Logged"].astype(str).str.upper().eq("YES").sum())
        if isinstance(ledger, pd.DataFrame) and not ledger.empty and "Manual Result Logged" in ledger.columns
        else 0
    )

    if ledger_rows <= 0:
        level = "Unavailable"
        score = 0.0
        read = "Aucune run queue V2.4 disponible pour construire le ledger."
    elif pending_rows > 0 and designer_score >= 25.0:
        level = "Ledger ready for manual retest"
        score = 35.0
        read = "Le registre est prêt pour des retests manuels contrôlés. Aucun run automatique n'est lancé."
    else:
        level = "Ledger drafted / redesign first"
        score = 15.0
        read = (
            "Le registre est construit, mais les runs restent bloqués : "
            "redesign ou score expérimental insuffisant avant tout retest propre."
        )

    scorecard_schema = pd.DataFrame(
        [
            ["Alpha gate", "Candidate alpha > 0 vs benchmark", "PROMOTE only if positive", "KILL or redesign if alpha remains <= 0"],
            ["Sharpe gate", "Candidate Sharpe >= 0.5 minimum", "Prefer >= 1.0 before promotion", "Reject if Sharpe remains weak"],
            ["Drawdown gate", "Candidate max DD > -25%", "Risk acceptable before paper-test", "Reject if drawdown remains excessive"],
            ["OOS gate", "OOS alpha > 0 and OOS Sharpe > 0", "No paper-test without OOS pass", "Kill if OOS remains failed"],
            ["Cost gate", "Edge survives fee/slippage stress", "Reject zero-cost-only edge", "Kill if costs erase edge"],
            ["Causality gate", "No look-ahead/data failure", "Critical gate", "Immediate reject if failed"],
            ["PBO / DSR gate", "PBO improves and DSR improves", "PBO preferably < 65%, DSR > 30%", "No promotion if overfit persists"],
            ["Result ledger", "Every run logged, including failures", "Audit trail complete", "No deleting failed runs"],
        ],
        columns=["Gate", "Pass Condition", "Promotion Rule", "Kill Rule"],
    )

    promotion_gate = pd.DataFrame(
        [
            ["1. Baseline frozen", "Current code/config/window/costs saved", "No moving benchmark after results"],
            ["2. One-factor mutation", "Exactly one explicit mutation per run", "No combinatorial expansion before OOS pass"],
            ["3. Manual execution only", "Run is launched deliberately by the user", "No automatic retest from V2.5"],
            ["4. OOS validation", "OOS alpha > 0 and OOS Sharpe > 0", "No promotion if OOS remains failed"],
            ["5. Cost robustness", "Candidate survives realistic costs", "Reject if edge only exists at zero costs"],
            ["6. Causality / data gates", "All critical gates pass", "Immediate reject on look-ahead or data failure"],
            ["7. Promote / kill decision", "Decision written in ledger", "No silent cherry-picking"],
        ],
        columns=["Stage", "Pass Condition", "Guardrail"],
    )

    result_template = pd.DataFrame(
        [
            {
                "Retest ID": "RTL-V25-XXX",
                "Run ID": "RUN-V24-XXX",
                "Execution Date UTC": "",
                "Ticker": "",
                "Window": "",
                "Strategy": "",
                "Mutation": "",
                "Baseline Alpha": "",
                "Candidate Alpha": "",
                "Baseline Sharpe": "",
                "Candidate Sharpe": "",
                "Baseline Max DD": "",
                "Candidate Max DD": "",
                "OOS Gate": "PASS/FAIL",
                "Cost Gate": "PASS/FAIL",
                "Causality Gate": "PASS/FAIL",
                "Decision": "PROMOTE / RETEST / KILL / REDESIGN",
                "Reviewer Note": "",
            }
        ]
    )

    summary = pd.DataFrame(
        [
            ["Retest ledger level", level, "Lecture synthétique du Controlled Retest Ledger V2.5."],
            ["Retest ledger score", f"{_format_num(score, 0)}/100", "Score de maturité du registre, pas score de performance."],
            ["Runner score input", f"{_format_num(runner_score, 0)}/100" if pd.notna(runner_score) else "N/A", "Score hérité du Runner Blueprint V2.4."],
            ["Designer score input", f"{_format_num(designer_score, 0)}/100", "Score hérité de l'Experiment Designer V2.3."],
            ["Ledger rows", str(ledger_rows), "Nombre de runs V2.4 convertis en lignes de ledger."],
            ["Pending manual retests", str(pending_rows), "Runs prêts uniquement pour retest manuel contrôlé."],
            ["Blocked retests", str(blocked_rows), "Runs bloqués par redesign / score insuffisant."],
            ["Manual results logged", str(logged_rows), "Résultats manuels déjà renseignés dans le ledger."],
            ["Main guardrail", "No auto-run", "V2.5 prépare le registre mais ne lance aucun backtest."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    cards = [
        {"label": "Retest ledger", "value": level, "delta": f"{_format_num(score, 0)}/100"},
        {"label": "Ledger rows", "value": str(ledger_rows), "delta": "V2.4 runs"},
        {"label": "Pending manual", "value": str(pending_rows), "delta": "manual only"},
        {"label": "Blocked", "value": str(blocked_rows), "delta": "redesign first"},
        {"label": "Results logged", "value": str(logged_rows), "delta": "manual records"},
        {"label": "Execution", "value": "Not executed", "delta": "ledger only"},
    ]

    return {
        "level": level,
        "score": score,
        "read": read,
        "cards": cards,
        "summary": summary,
        "ledger": ledger,
        "scorecard_schema": scorecard_schema,
        "promotion_gate": promotion_gate,
        "result_template": result_template,
        "pending_manual_retests": pending_rows,
        "blocked_retests": blocked_rows,
        "manual_results_logged": logged_rows,
    }


def _render_controlled_retest_ledger_v25(
    runner_pack: dict[str, Any],
) -> dict[str, Any]:
    """
    Rendu Streamlit Controlled Retest Ledger V2.5.
    Lecture seule.
    """
    pack = _controlled_retest_ledger_v25_pack(runner_pack)

    st.subheader("Controlled Retest Ledger V2.5")
    st.caption(
        "Registre de retest manuel : baseline freeze, mutation one-factor-at-a-time, "
        "gates OOS/coûts/causalité/données, décision promote/kill et audit trail. "
        "Lecture seule : aucun retest n'est lancé automatiquement."
    )

    _card_grid(pack.get("cards", []), columns=6)

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))

    if "redesign" in level.lower() or "blocked" in level.lower():
        st.warning(f"Lecture retest ledger : {read}")
    else:
        st.info(f"Lecture retest ledger : {read}")

    ledger = pack.get("ledger", pd.DataFrame())
    scorecard = pack.get("scorecard_schema", pd.DataFrame())
    promotion_gate = pack.get("promotion_gate", pd.DataFrame())
    result_template = pack.get("result_template", pd.DataFrame())
    summary = pack.get("summary", pd.DataFrame())

    with st.expander("Controlled Retest Ledger — V2.5", expanded=True):
        if isinstance(ledger, pd.DataFrame) and not ledger.empty:
            st.dataframe(ledger, use_container_width=True, hide_index=True)
        else:
            st.info("Controlled retest ledger indisponible.")

    with st.expander("Retest scorecard schema V2.5", expanded=True):
        if isinstance(scorecard, pd.DataFrame) and not scorecard.empty:
            st.dataframe(scorecard, use_container_width=True, hide_index=True)
        else:
            st.info("Scorecard indisponible.")

    with st.expander("Promotion / kill gate V2.5", expanded=True):
        if isinstance(promotion_gate, pd.DataFrame) and not promotion_gate.empty:
            st.dataframe(promotion_gate, use_container_width=True, hide_index=True)
        else:
            st.info("Promotion gate indisponible.")

    with st.expander("Manual Result Template — V2.5", expanded=False):
        if isinstance(result_template, pd.DataFrame) and not result_template.empty:
            st.dataframe(result_template, use_container_width=True, hide_index=True)
        else:
            st.info("Template indisponible.")

    with st.expander("Retest Ledger Summary — V2.5", expanded=False):
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé retest ledger indisponible.")

    d1, d2, d3 = st.columns(3)

    if isinstance(ledger, pd.DataFrame) and not ledger.empty:
        d1.download_button(
            "Télécharger controlled retest ledger CSV",
            data=ledger.to_csv(index=False).encode("utf-8"),
            file_name="controlled_retest_ledger_v25.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_controlled_retest_ledger_v25_download",
        )

    if isinstance(scorecard, pd.DataFrame) and not scorecard.empty:
        d2.download_button(
            "Télécharger retest scorecard CSV",
            data=scorecard.to_csv(index=False).encode("utf-8"),
            file_name="controlled_retest_scorecard_v25.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_controlled_retest_scorecard_v25_download",
        )

    if isinstance(result_template, pd.DataFrame) and not result_template.empty:
        d3.download_button(
            "Télécharger manual result template CSV",
            data=result_template.to_csv(index=False).encode("utf-8"),
            file_name="controlled_retest_result_template_v25.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_controlled_retest_result_template_v25_download",
        )

    return pack





