# ============================================================
# TAIL / DOWNSIDE RISK DIAGNOSTICS
# ============================================================

def _max_consecutive_true(mask: Any) -> int:
    """Compte la plus longue séquence consécutive de True."""
    try:
        series = pd.Series(mask).fillna(False).astype(bool)
        best = 0
        current = 0

        for value in series:
            if value:
                current += 1
                best = max(best, current)
            else:
                current = 0

        return int(best)
    except Exception:
        return 0


def _rolling_compound_return(returns: pd.Series, window: int) -> pd.Series:
    """Rendement composé rolling : utile pour worst 5D / 20D."""
    try:
        r = pd.to_numeric(returns, errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
        if len(r) < window:
            return pd.Series(dtype=float)
        return (1.0 + r).rolling(window).apply(lambda x: np.prod(x) - 1.0, raw=True)
    except Exception:
        return pd.Series(dtype=float)


def _tail_risk_diagnostics(bt: pd.DataFrame) -> dict[str, Any]:
    """
    Diagnostic queue de distribution / downside.
    Lecture uniquement : ne modifie pas le backtest, le verdict, ni le score.
    """
    empty = {
        "cards": [],
        "table": pd.DataFrame(),
        "risk_level": "N/A",
        "risk_note": "Tail diagnostics indisponible.",
    }

    if bt is None or not isinstance(bt, pd.DataFrame) or bt.empty:
        return empty

    if "strategy_return" not in bt.columns or "equity" not in bt.columns:
        return empty

    r = (
        pd.to_numeric(bt["strategy_return"], errors="coerce")
        .replace([np.inf, -np.inf], np.nan)
        .dropna()
    )

    if len(r) < 30:
        return {
            **empty,
            "risk_level": "Insufficient history",
            "risk_note": "Historique trop court pour une lecture tail robuste.",
        }

    equity = (
        pd.to_numeric(bt["equity"], errors="coerce")
        .replace([np.inf, -np.inf], np.nan)
        .dropna()
    )

    if equity.empty:
        return empty

    dd = equity / equity.cummax() - 1.0

    active_mask = pd.Series(True, index=bt.index)
    if "exposure" in bt.columns:
        active_mask = pd.to_numeric(bt["exposure"], errors="coerce").fillna(0.0).abs() > 0

    active_r = r.loc[r.index.intersection(bt.index[active_mask])] if not active_mask.empty else pd.Series(dtype=float)

    q01 = float(r.quantile(0.01))
    q05 = float(r.quantile(0.05))
    q50 = float(r.quantile(0.50))
    q95 = float(r.quantile(0.95))
    q99 = float(r.quantile(0.99))

    cvar_95 = float(r[r <= q05].mean()) if (r <= q05).any() else np.nan
    cvar_99 = float(r[r <= q01].mean()) if (r <= q01).any() else np.nan

    active_q05 = float(active_r.quantile(0.05)) if len(active_r) >= 20 else np.nan
    active_cvar_95 = float(active_r[active_r <= active_q05].mean()) if len(active_r) >= 20 and (active_r <= active_q05).any() else np.nan
    active_worst_day = float(active_r.min()) if len(active_r) else np.nan

    downside = r[r < 0]
    downside_deviation = float(np.sqrt(np.mean(np.minimum(r, 0.0) ** 2)) * np.sqrt(252)) if len(r) else np.nan

    skew = float(r.skew()) if len(r) >= 30 else np.nan
    excess_kurtosis = float(r.kurtosis()) if len(r) >= 30 else np.nan

    tail_ratio = float(q95 / abs(q05)) if q05 < 0 else np.nan
    gain_to_pain = float(r[r > 0].sum() / abs(r[r < 0].sum())) if (r < 0).any() else np.nan

    worst_1d = float(r.min())
    best_1d = float(r.max())

    roll_5d = _rolling_compound_return(r, 5)
    roll_20d = _rolling_compound_return(r, 20)

    worst_5d = float(roll_5d.min()) if not roll_5d.dropna().empty else np.nan
    worst_20d = float(roll_20d.min()) if not roll_20d.dropna().empty else np.nan

    best_5d = float(roll_5d.max()) if not roll_5d.dropna().empty else np.nan
    best_20d = float(roll_20d.max()) if not roll_20d.dropna().empty else np.nan

    ulcer_index = float(np.sqrt(np.mean(np.square(dd.dropna())))) if not dd.dropna().empty else np.nan
    pain_index = float(abs(dd.dropna().mean())) if not dd.dropna().empty else np.nan

    dd_q05 = float(dd.quantile(0.05)) if not dd.dropna().empty else np.nan
    cdar_95 = float(dd[dd <= dd_q05].mean()) if (dd <= dd_q05).any() else np.nan

    max_time_underwater = _max_consecutive_true(dd < -1e-12)
    max_loss_streak = _max_consecutive_true(r < 0)

    # Niveau de risque synthétique, volontairement simple et lisible.
    risk_level = "Contained"

    if (
        _safe_float(cvar_99, 0.0) <= -0.08
        or _safe_float(worst_20d, 0.0) <= -0.25
        or _safe_float(cdar_95, 0.0) <= -0.35
    ):
        risk_level = "Extreme tail risk"
    elif (
        _safe_float(cvar_95, 0.0) <= -0.04
        or _safe_float(worst_5d, 0.0) <= -0.12
        or _safe_float(cdar_95, 0.0) <= -0.25
    ):
        risk_level = "High downside risk"
    elif (
        _safe_float(cvar_95, 0.0) <= -0.025
        or _safe_float(worst_5d, 0.0) <= -0.08
        or _safe_float(cdar_95, 0.0) <= -0.15
    ):
        risk_level = "Moderate downside risk"

    if risk_level == "Extreme tail risk":
        risk_note = (
            "Queue de perte extrême détectée : la stratégie doit être lue avec sizing réduit, "
            "stress de gap et contrôle drawdown strict."
        )
    elif risk_level == "High downside risk":
        risk_note = (
            "Downside significatif : le rendement moyen ne suffit pas, il faut surveiller CVaR, "
            "pertes multi-jours et drawdown conditionnel."
        )
    elif risk_level == "Moderate downside risk":
        risk_note = (
            "Risque de queue présent mais pas extrême sur cette fenêtre. À confirmer sur plus d'historique."
        )
    else:
        risk_note = (
            "Risque tail contenu sur cette fenêtre, sous réserve de la qualité et de la longueur de l'historique."
        )

    cards = [
        {
            "label": "Tail risk level",
            "value": risk_level,
            "delta": "read-only",
        },
        {
            "label": "CVaR 95",
            "value": _format_pct(cvar_95),
            "delta": "avg worst 5%",
        },
        {
            "label": "CVaR 99",
            "value": _format_pct(cvar_99),
            "delta": "avg worst 1%",
        },
        {
            "label": "Worst 5D",
            "value": _format_pct(worst_5d),
            "delta": "compound",
        },
        {
            "label": "CDaR 95",
            "value": _format_pct(cdar_95),
            "delta": "drawdown tail",
        },
        {
            "label": "Tail ratio",
            "value": _format_num(tail_ratio),
            "delta": "P95 / |P5|",
        },
    ]

    table = pd.DataFrame(
        [
            ["VaR 95", _format_pct(q05), "Perte journalière au 5e percentile."],
            ["CVaR 95", _format_pct(cvar_95), "Perte moyenne des 5% pires journées."],
            ["VaR 99", _format_pct(q01), "Perte journalière au 1er percentile."],
            ["CVaR 99", _format_pct(cvar_99), "Perte moyenne des 1% pires journées."],
            ["Median daily return", _format_pct(q50), "Rendement journalier médian."],
            ["Best 1D", _format_pct(best_1d), "Meilleure journée stratégie."],
            ["Worst 1D", _format_pct(worst_1d), "Pire journée stratégie."],
            ["Best 5D", _format_pct(best_5d), "Meilleure fenêtre composée 5 jours."],
            ["Worst 5D", _format_pct(worst_5d), "Pire fenêtre composée 5 jours."],
            ["Best 20D", _format_pct(best_20d), "Meilleure fenêtre composée 20 jours."],
            ["Worst 20D", _format_pct(worst_20d), "Pire fenêtre composée 20 jours."],
            ["Downside deviation", _format_pct(downside_deviation), "Volatilité annualisée des rendements négatifs."],
            ["Skew", _format_num(skew), "Asymétrie de la distribution des rendements."],
            ["Excess kurtosis", _format_num(excess_kurtosis), "Épaisseur des queues vs distribution normale."],
            ["Tail ratio", _format_num(tail_ratio), "Ratio P95 / |P5|. Supérieur à 1 = upside tail plus large."],
            ["Gain to pain", _format_num(gain_to_pain), "Somme gains / somme pertes absolues."],
            ["Ulcer Index", _format_pct(ulcer_index), "Profondeur moyenne quadratique du drawdown."],
            ["Pain Index", _format_pct(pain_index), "Drawdown moyen absolu."],
            ["CDaR 95", _format_pct(cdar_95), "Drawdown moyen dans les 5% pires états de drawdown."],
            ["Max time underwater", _format_num(max_time_underwater, 0), "Plus longue période sous un précédent plus-haut."],
            ["Max loss streak", _format_num(max_loss_streak, 0), "Plus longue séquence de jours négatifs."],
            ["Active VaR 95", _format_pct(active_q05), "VaR 95 uniquement sur les jours exposés."],
            ["Active CVaR 95", _format_pct(active_cvar_95), "CVaR 95 uniquement sur les jours exposés."],
            ["Active worst day", _format_pct(active_worst_day), "Pire journée lorsque le moteur est réellement exposé."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    return {
        "cards": cards,
        "table": table,
        "risk_level": risk_level,
        "risk_note": risk_note,
    }


def _render_tail_risk_block(bt: pd.DataFrame) -> None:
    """Rendu Streamlit du diagnostic tail risk."""
    pack = _tail_risk_diagnostics(bt)

    table = pack.get("table", pd.DataFrame())
    cards = pack.get("cards", [])

    if table is None or table.empty:
        return

    st.subheader("Tail / downside diagnostics")
    st.caption(
        "Lecture des pertes extrêmes et du downside : VaR, CVaR, skew, kurtosis, "
        "worst 1D/5D/20D, drawdown conditionnel et risque actif. "
        "Bloc lecture seule : ne modifie pas le backtest."
    )

    _card_grid(cards, columns=6)

    risk_level = str(pack.get("risk_level", "N/A"))
    risk_note = str(pack.get("risk_note", ""))

    if "Extreme" in risk_level or "High" in risk_level:
        st.warning(risk_note)
    elif "Moderate" in risk_level:
        st.info(risk_note)
    else:
        st.success(risk_note)

    with st.expander("Table tail / downside risk", expanded=True):
        st.dataframe(table, use_container_width=True, hide_index=True)



