def _render_event_stress_block(event_stress: pd.DataFrame) -> None:
    """
    Rendu Tail / Event Stress Lab V2.
    Lecture seule : ne modifie pas le moteur, l'equity curve, les trades ou le verdict.
    """
    if event_stress is None or event_stress.empty:
        return

    st.subheader("Tail / Event Stress Lab V2")
    st.caption(
        "Stress événementiel en lecture seule : gaps, squeeze, dump, slippage shock, borrow fee, "
        "forced cover, trading halt et historical replay. "
        "Current = choc sur l'exposition actuelle. "
        "Worst Active = choc appliqué à la pire exposition réellement prise dans l'historique. "
        "Aucun impact sur le backtest moteur."
    )

    _render_event_stress_cockpit(event_stress)

    severity_cols = [
        "Scenario",
        "Event Class",
        "Underlying Shock",
        "Adverse To",
        "Current Exposure",
        "Current Impact",
        "Worst Active Impact",
        "Historical Risk Level",
        "Extra Slippage",
        "Borrow Fee Ann.",
        "Forced Cover Proxy",
        "Trading Halt Bars",
        "Stress Read",
    ]

    severity_view = event_stress[[c for c in severity_cols if c in event_stress.columns]].copy()

    st.markdown("**Scenario severity map**")
    st.dataframe(
        severity_view,
        use_container_width=True,
        hide_index=True,
    )

    current_cols = [
        "Scenario",
        "Event Class",
        "Underlying Shock",
        "Current Exposure",
        "Current Impact",
        "Current Equity After Shock",
        "Current Risk Level",
    ]

    current_view = event_stress[[c for c in current_cols if c in event_stress.columns]].copy()

    with st.expander("Current exposure shock", expanded=False):
        st.caption(
            "Impact théorique si l'événement arrive maintenant, avec l'exposition actuelle du moteur."
        )
        st.dataframe(
            current_view,
            use_container_width=True,
            hide_index=True,
        )

    hist_cols = [
        "Scenario",
        "Event Class",
        "Max Abs Exposure",
        "Avg Active Exposure",
        "Worst Active Impact",
        "Worst Active Date",
        "Worst Active Equity After Shock",
        "Historical Risk Level",
    ]

    hist_view = event_stress[[c for c in hist_cols if c in event_stress.columns]].copy()

    with st.expander("Historical active-exposure stress", expanded=True):
        st.caption(
            "Impact théorique sur les expositions effectivement prises par le moteur dans l'historique."
        )
        st.dataframe(
            hist_view,
            use_container_width=True,
            hide_index=True,
        )

    upside_cols = [
        "Scenario",
        "Best Active Impact",
        "Best Active Date",
        "Best Active Equity After Shock",
        "Read",
    ]

    upside_view = event_stress[[c for c in upside_cols if c in event_stress.columns]].copy()

    with st.expander("Best active impact / upside scenarios", expanded=False):
        st.caption(
            "Montre les scénarios qui auraient été favorables selon les expositions historiques du moteur."
        )
        st.dataframe(
            upside_view,
            use_container_width=True,
            hide_index=True,
        )

    mechanics_cols = [
        "Scenario",
        "Event Class",
        "Underlying Shock",
        "Extra Slippage",
        "Borrow Fee Ann.",
        "Borrow Days",
        "Trading Halt Bars",
        "Forced Cover Proxy",
        "Stress Read",
    ]

    mechanics_view = event_stress[[c for c in mechanics_cols if c in event_stress.columns]].copy()

    with st.expander("Stress mechanics / assumptions", expanded=False):
        st.caption(
            "Hypothèses mécaniques utilisées par le stress. "
            "Ce sont des proxies prudents, pas une simulation microstructure complète."
        )
        st.dataframe(
            mechanics_view,
            use_container_width=True,
            hide_index=True,
        )


def _pct_to_float_safe(x, default=0.0):
    try:
        if x is None:
            return default
        if isinstance(x, str):
            s = x.replace("%", "").replace(",", ".").strip()
            if s in ["", "N/A", "nan", "None"]:
                return default
            return float(s) / 100.0
        return float(x)
    except Exception:
        return default


def _render_event_stress_cockpit(event_stress: pd.DataFrame) -> None:
    """
    Cockpit synthétique du stress event.
    Lecture uniquement. Ne modifie aucun calcul.
    """
    if event_stress is None or event_stress.empty:
        return

    df = event_stress.copy()

    current_worst_row = None
    hist_worst_row = None
    hist_best_row = None

    if "Current Impact" in df.columns:
        tmp = df.copy()
        tmp["_current_impact_num"] = tmp["Current Impact"].apply(_pct_to_float_safe)
        current_worst_row = tmp.loc[tmp["_current_impact_num"].idxmin()]

    if "Worst Active Impact" in df.columns:
        tmp = df.copy()
        tmp["_worst_active_num"] = tmp["Worst Active Impact"].apply(_pct_to_float_safe)
        hist_worst_row = tmp.loc[tmp["_worst_active_num"].idxmin()]

    if "Best Active Impact" in df.columns:
        tmp = df.copy()
        tmp["_best_active_num"] = tmp["Best Active Impact"].apply(_pct_to_float_safe)
        hist_best_row = tmp.loc[tmp["_best_active_num"].idxmax()]

    # ------------------------------------------------------------
    # Current exposure must be computed BEFORE using is_current_flat
    # ------------------------------------------------------------
    current_exposure = "N/A"
    if current_worst_row is not None and "Current Exposure" in current_worst_row.index:
        current_exposure = current_worst_row.get("Current Exposure", "N/A")

    def _exposure_to_float_safe(x: Any, default: float = 0.0) -> float:
        try:
            if x is None or pd.isna(x):
                return default
            txt = str(x).replace(",", ".").strip()
            if txt in {"", "N/A", "nan", "None"}:
                return default
            has_pct = "%" in txt
            txt = txt.replace("%", "")
            val = float(txt)
            return val / 100.0 if has_pct else val
        except Exception:
            return default

    current_exposure_num = _exposure_to_float_safe(current_exposure, default=0.0)
    is_current_flat = abs(current_exposure_num) < 1e-9

    # ------------------------------------------------------------
    # Current cockpit reading
    # ------------------------------------------------------------
    if is_current_flat:
        current_scenario = "Flat"
        current_impact = "0.00%"
        current_risk = "No current exposure"
    else:
        current_scenario = current_worst_row.get("Scenario", "N/A") if current_worst_row is not None else "N/A"
        current_impact = current_worst_row.get("Current Impact", "N/A") if current_worst_row is not None else "N/A"
        current_risk = current_worst_row.get("Current Risk Level", "N/A") if current_worst_row is not None else "N/A"

    hist_scenario = hist_worst_row.get("Scenario", "N/A") if hist_worst_row is not None else "N/A"
    hist_impact = hist_worst_row.get("Worst Active Impact", "N/A") if hist_worst_row is not None else "N/A"
    hist_date = hist_worst_row.get("Worst Active Date", "N/A") if hist_worst_row is not None else "N/A"

    best_scenario = hist_best_row.get("Scenario", "N/A") if hist_best_row is not None else "N/A"
    best_impact = hist_best_row.get("Best Active Impact", "N/A") if hist_best_row is not None else "N/A"

    cols = st.columns(6)

    with cols[0]:
        st.metric("Current exposure", current_exposure)

    with cols[1]:
        st.metric("Current worst shock", current_impact, current_scenario)

    with cols[2]:
        st.metric("Current risk", current_risk)

    with cols[3]:
        st.metric("Historical worst", hist_impact, hist_scenario)

    with cols[4]:
        st.metric("Worst active date", str(hist_date))

    with cols[5]:
        st.metric("Best active shock", best_impact, best_scenario)

    # Lecture synthétique
    hist_num = _pct_to_float_safe(hist_impact)

    if is_current_flat and abs(hist_num) > 0.05:
        st.info(
            "Lecture stress : aucune exposition actuelle, donc le choc courant est neutre. "
            "Mais l'historique montre une vulnérabilité importante lorsque le moteur est exposé."
        )
    elif hist_num <= -0.20:
        st.warning(
            "Lecture stress : risque historique extrême détecté sur exposition active. "
            "La stratégie doit être lue avec contrôle de gap, stop effectif ou sizing réduit."
        )
    elif hist_num <= -0.10:
        st.warning(
            "Lecture stress : risque historique élevé sur exposition active. "
            "Le moteur peut subir un choc sévère en cas de gap adverse."
        )
    else:
        st.success(
            "Lecture stress : risque event contenu sur la fenêtre testée, sous réserve de la qualité de l'historique."
        )


# ============================================================
# ECONOMETRIC DIAGNOSTICS / MCO V1
# ============================================================

def _ols_alpha_beta_pack(
    y: pd.Series,
    x: pd.Series,
    annualization: int = 252,
) -> dict[str, Any]:
    """
    OLS simple : strategy_return = alpha + beta * benchmark_return + residual.

    Lecture seule :
    - ne modifie pas le moteur ;
    - ne modifie pas l'equity curve ;
    - ne modifie pas les trades ;
    - ne modifie pas le verdict.
    """
    try:
        data = pd.concat(
            [
                pd.to_numeric(y, errors="coerce").rename("strategy"),
                pd.to_numeric(x, errors="coerce").rename("benchmark"),
            ],
            axis=1,
        ).replace([np.inf, -np.inf], np.nan).dropna()

        if len(data) < 30:
            return {}

        yv = data["strategy"].astype(float)
        xv = data["benchmark"].astype(float)

        x_var = float(xv.var(ddof=1))
        y_var = float(yv.var(ddof=1))

        if x_var <= 1e-16 or y_var <= 1e-16:
            return {}

        x_mean = float(xv.mean())
        y_mean = float(yv.mean())

        cov_xy = float(np.cov(xv, yv, ddof=1)[0, 1])
        beta = cov_xy / x_var
        alpha_daily = y_mean - beta * x_mean

        fitted = alpha_daily + beta * xv
        residuals = yv - fitted

        sse = float((residuals ** 2).sum())
        sst = float(((yv - y_mean) ** 2).sum())
        r2 = 1.0 - sse / sst if sst > 1e-16 else np.nan

        n = int(len(data))
        sxx = float(((xv - x_mean) ** 2).sum())

        if n > 2 and sxx > 1e-16:
            mse = sse / max(n - 2, 1)
            se_beta = np.sqrt(mse / sxx)
            se_alpha = np.sqrt(mse * (1.0 / n + (x_mean ** 2) / sxx))
            t_alpha = alpha_daily / se_alpha if se_alpha > 1e-16 else np.nan
            t_beta = beta / se_beta if se_beta > 1e-16 else np.nan
        else:
            se_beta = np.nan
            se_alpha = np.nan
            t_alpha = np.nan
            t_beta = np.nan

        alpha_ann = alpha_daily * annualization

        bench_vol_ann = float(xv.std(ddof=1) * np.sqrt(annualization))
        strat_vol_ann = float(yv.std(ddof=1) * np.sqrt(annualization))
        resid_vol_ann = float(residuals.std(ddof=1) * np.sqrt(annualization))

        active = yv - xv
        tracking_error = float(active.std(ddof=1) * np.sqrt(annualization))
        active_premium = float(active.mean() * annualization)
        information_ratio = active_premium / tracking_error if tracking_error > 1e-16 else np.nan

        corr = float(yv.corr(xv))

        resid_acf1 = float(residuals.autocorr(lag=1)) if len(residuals) > 3 else np.nan
        resid_sq_acf1 = float((residuals ** 2).autocorr(lag=1)) if len(residuals) > 3 else np.nan

        upside_mask = xv > 0
        downside_mask = xv < 0

        def _conditional_beta(mask: pd.Series) -> float:
            try:
                sub = data.loc[mask].copy()
                if len(sub) < 10:
                    return np.nan
                bx = sub["benchmark"].astype(float)
                by = sub["strategy"].astype(float)
                vx = float(bx.var(ddof=1))
                if vx <= 1e-16:
                    return np.nan
                return float(np.cov(bx, by, ddof=1)[0, 1] / vx)
            except Exception:
                return np.nan

        upside_beta = _conditional_beta(upside_mask)
        downside_beta = _conditional_beta(downside_mask)

        return {
            "n": n,
            "alpha_daily": float(alpha_daily),
            "alpha_ann": float(alpha_ann),
            "beta": float(beta),
            "t_alpha": float(t_alpha) if pd.notna(t_alpha) else np.nan,
            "t_beta": float(t_beta) if pd.notna(t_beta) else np.nan,
            "r2": float(r2) if pd.notna(r2) else np.nan,
            "corr": corr,
            "strategy_vol_ann": strat_vol_ann,
            "benchmark_vol_ann": bench_vol_ann,
            "resid_vol_ann": resid_vol_ann,
            "tracking_error": tracking_error,
            "active_premium": active_premium,
            "information_ratio": information_ratio,
            "resid_acf1": resid_acf1,
            "resid_sq_acf1": resid_sq_acf1,
            "resid_skew": float(residuals.skew()),
            "resid_kurtosis": float(residuals.kurtosis()),
            "upside_beta": upside_beta,
            "downside_beta": downside_beta,
            "residuals": residuals,
            "fitted": fitted,
            "data": data,
        }

    except Exception:
        return {}


def _rolling_econometric_table(
    bt: pd.DataFrame,
    window: int = 60,
    annualization: int = 252,
) -> pd.DataFrame:
    """
    Rolling alpha/beta/R².
    Lecture seule.
    """
    try:
        if bt is None or bt.empty:
            return pd.DataFrame()

        if "strategy_return" not in bt.columns or "benchmark_return" not in bt.columns:
            return pd.DataFrame()

        data = pd.concat(
            [
                pd.to_numeric(bt["strategy_return"], errors="coerce").rename("strategy"),
                pd.to_numeric(bt["benchmark_return"], errors="coerce").rename("benchmark"),
            ],
            axis=1,
        ).replace([np.inf, -np.inf], np.nan).dropna()

        if len(data) < max(window + 5, 80):
            return pd.DataFrame()

        y = data["strategy"]
        x = data["benchmark"]

        roll_cov = y.rolling(window).cov(x)
        roll_var = x.rolling(window).var()

        beta = roll_cov / roll_var.replace(0, np.nan)
        alpha_daily = y.rolling(window).mean() - beta * x.rolling(window).mean()
        alpha_ann = alpha_daily * annualization

        corr = y.rolling(window).corr(x)
        r2 = corr ** 2

        residual = y - (alpha_daily + beta * x)
        resid_vol = residual.rolling(window).std() * np.sqrt(annualization)

        out = pd.DataFrame(
            {
                "Date": data.index,
                "Rolling Alpha Ann.": alpha_ann,
                "Rolling Beta": beta,
                "Rolling R²": r2,
                "Rolling Residual Vol": resid_vol,
            }
        ).replace([np.inf, -np.inf], np.nan).dropna()

        if out.empty:
            return pd.DataFrame()

        out["Date"] = out["Date"].map(_format_dt)

        return out

    except Exception:
        return pd.DataFrame()


def _econometric_diagnostics(bt: pd.DataFrame) -> dict[str, Any]:
    """
    Econometric Diagnostics / MCO V1.

    Objectif :
    savoir si la stratégie produit un alpha propre ou si elle n'est qu'une
    exposition déguisée au benchmark.

    Lecture seule.
    """
    if bt is None or bt.empty:
        return {
            "summary": pd.DataFrame(),
            "rolling": pd.DataFrame(),
            "residuals": pd.DataFrame(),
            "cards": [],
            "level": "Unavailable",
            "read": "Backtest vide.",
        }

    if "strategy_return" not in bt.columns or "benchmark_return" not in bt.columns:
        return {
            "summary": pd.DataFrame(),
            "rolling": pd.DataFrame(),
            "residuals": pd.DataFrame(),
            "cards": [],
            "level": "Unavailable",
            "read": "Colonnes strategy_return / benchmark_return manquantes.",
        }

    pack = _ols_alpha_beta_pack(bt["strategy_return"], bt["benchmark_return"])

    if not pack:
        return {
            "summary": pd.DataFrame(),
            "rolling": pd.DataFrame(),
            "residuals": pd.DataFrame(),
            "cards": [],
            "level": "Unavailable",
            "read": "Échantillon insuffisant ou benchmark non exploitable.",
        }

    alpha_ann = _safe_float(pack.get("alpha_ann"), np.nan)
    beta = _safe_float(pack.get("beta"), np.nan)
    t_alpha = _safe_float(pack.get("t_alpha"), np.nan)
    r2 = _safe_float(pack.get("r2"), np.nan)
    resid_acf1 = _safe_float(pack.get("resid_acf1"), np.nan)
    resid_sq_acf1 = _safe_float(pack.get("resid_sq_acf1"), np.nan)
    upside_beta = _safe_float(pack.get("upside_beta"), np.nan)
    downside_beta = _safe_float(pack.get("downside_beta"), np.nan)
    information_ratio = _safe_float(pack.get("information_ratio"), np.nan)

    if pd.notna(t_alpha) and t_alpha >= 2.0 and pd.notna(alpha_ann) and alpha_ann > 0:
        level = "Positive alpha signal"
        read = "Alpha annualisé positif avec t-stat alpha supérieur à 2. Lecture favorable, à confirmer OOS."
    elif pd.notna(t_alpha) and t_alpha <= -2.0:
        level = "Negative alpha signal"
        read = "Alpha statistiquement négatif. La stratégie détruit probablement de la valeur vs benchmark."
    elif pd.notna(r2) and r2 >= 0.65 and abs(beta) >= 0.75:
        level = "Benchmark-driven"
        read = "Forte dépendance au benchmark : le résultat ressemble surtout à une exposition marché/facteur."
    elif pd.notna(r2) and r2 <= 0.20 and pd.notna(alpha_ann) and alpha_ann > 0:
        level = "Low benchmark dependence"
        read = "Faible R² avec alpha positif : possible source d'alpha indépendante, mais à valider."
    else:
        level = "Mixed / inconclusive"
        read = "Lecture économétrique mitigée : alpha, beta et dépendance benchmark ne donnent pas un signal net."

    summary = pd.DataFrame(
        [
            ["Sample", str(int(pack.get("n", 0))), "Nombre de rendements utilisés dans la régression."],
            ["Alpha annualized", _format_pct(pack.get("alpha_ann")), "Intercept MCO annualisé. Mesure l'alpha non expliqué par le benchmark."],
            ["Alpha t-stat", _format_num(pack.get("t_alpha")), "t-stat de l'intercept. Approximation : |t| > 2 = signal plus solide."],
            ["Beta", _format_num(pack.get("beta")), "Sensibilité de la stratégie au benchmark."],
            ["Beta t-stat", _format_num(pack.get("t_beta")), "Significativité approximative de l'exposition benchmark."],
            ["R²", _format_pct(pack.get("r2")), "Part de variance stratégie expliquée par le benchmark."],
            ["Correlation", _format_num(pack.get("corr")), "Corrélation stratégie vs benchmark."],
            ["Information ratio", _format_num(pack.get("information_ratio")), "Active premium / tracking error."],
            ["Active premium ann.", _format_pct(pack.get("active_premium")), "Rendement annualisé moyen de stratégie - benchmark."],
            ["Tracking error ann.", _format_pct(pack.get("tracking_error")), "Volatilité annualisée de stratégie - benchmark."],
            ["Strategy vol ann.", _format_pct(pack.get("strategy_vol_ann")), "Volatilité annualisée de la stratégie."],
            ["Benchmark vol ann.", _format_pct(pack.get("benchmark_vol_ann")), "Volatilité annualisée du benchmark."],
            ["Residual vol ann.", _format_pct(pack.get("resid_vol_ann")), "Volatilité annualisée non expliquée par le benchmark."],
            ["Residual autocorr lag1", _format_num(pack.get("resid_acf1")), "Autocorrélation des résidus. Élevée = dépendance temporelle non modélisée."],
            ["Residual squared autocorr lag1", _format_num(pack.get("resid_sq_acf1")), "Proxy volatility clustering sur les résidus."],
            ["Residual skew", _format_num(pack.get("resid_skew")), "Asymétrie des résidus."],
            ["Residual kurtosis", _format_num(pack.get("resid_kurtosis")), "Excès de kurtosis des résidus. Élevé = queues épaisses."],
            ["Upside beta", _format_num(pack.get("upside_beta")), "Beta conditionnel quand le benchmark est positif."],
            ["Downside beta", _format_num(pack.get("downside_beta")), "Beta conditionnel quand le benchmark est négatif."],
            ["Asymmetric beta", _format_num(downside_beta - upside_beta) if pd.notna(downside_beta) and pd.notna(upside_beta) else "N/A", "Downside beta - upside beta. Positif = plus exposé dans les baisses."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    rolling = _rolling_econometric_table(bt, window=60)

    rolling_summary = pd.DataFrame()

    if not rolling.empty:
        tmp = rolling.copy()
        for col in ["Rolling Alpha Ann.", "Rolling Beta", "Rolling R²", "Rolling Residual Vol"]:
            if col in tmp.columns:
                tmp[col + "_num"] = pd.to_numeric(tmp[col], errors="coerce")

        rolling_summary = pd.DataFrame(
            [
                ["Rolling alpha last", _format_pct(tmp["Rolling Alpha Ann._num"].iloc[-1]), "Dernier alpha annualisé rolling 60 barres."],
                ["Rolling alpha median", _format_pct(tmp["Rolling Alpha Ann._num"].median()), "Médiane de l'alpha rolling."],
                ["Rolling beta last", _format_num(tmp["Rolling Beta_num"].iloc[-1]), "Dernier beta rolling 60 barres."],
                ["Rolling beta median", _format_num(tmp["Rolling Beta_num"].median()), "Médiane du beta rolling."],
                ["Rolling R² last", _format_pct(tmp["Rolling R²_num"].iloc[-1]), "Dernier R² rolling."],
                ["Rolling R² median", _format_pct(tmp["Rolling R²_num"].median()), "Médiane du R² rolling."],
                ["Rolling residual vol last", _format_pct(tmp["Rolling Residual Vol_num"].iloc[-1]), "Dernière volatilité résiduelle rolling."],
            ],
            columns=["Metric", "Value", "Read"],
        )

    residuals = pd.DataFrame()

    try:
        resid = pack.get("residuals", pd.Series(dtype=float)).copy()
        if isinstance(resid, pd.Series) and not resid.empty:
            residuals = pd.DataFrame(
                [
                    ["Worst residual day", _format_pct(resid.min()), _format_dt(resid.idxmin())],
                    ["Best residual day", _format_pct(resid.max()), _format_dt(resid.idxmax())],
                    ["Residual VaR 95", _format_pct(resid.quantile(0.05)), "5% quantile"],
                    ["Residual CVaR 95", _format_pct(resid[resid <= resid.quantile(0.05)].mean()), "Expected shortfall résiduel"],
                    ["Positive residual share", _format_pct((resid > 0).mean()), "Part des jours où la stratégie surperforme le modèle MCO"],
                ],
                columns=["Residual Diagnostic", "Value", "Read"],
            )
    except Exception:
        residuals = pd.DataFrame()

    cards = [
        {
            "label": "MCO read",
            "value": level,
            "delta": "OLS",
        },
        {
            "label": "Alpha ann.",
            "value": _format_pct(alpha_ann),
            "delta": f"t={_format_num(t_alpha)}",
        },
        {
            "label": "Beta",
            "value": _format_num(beta),
            "delta": "vs benchmark",
        },
        {
            "label": "R²",
            "value": _format_pct(r2),
            "delta": "explained variance",
        },
        {
            "label": "Info ratio",
            "value": _format_num(information_ratio),
            "delta": "active risk",
        },
        {
            "label": "Vol clustering",
            "value": _format_num(resid_sq_acf1),
            "delta": "resid² acf1",
        },
    ]

    return {
        "summary": summary,
        "rolling": rolling,
        "rolling_summary": rolling_summary,
        "residuals": residuals,
        "cards": cards,
        "level": level,
        "read": read,
    }



# ============================================================
# FACTOR / BENCHMARK ATTRIBUTION V2
# ============================================================

def _factor_compound_return(returns: pd.Series) -> float:
    """
    Rendement composé robuste.
    """
    try:
        r = (
            pd.to_numeric(returns, errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .dropna()
        )

        if r.empty:
            return np.nan

        return float((1.0 + r).prod() - 1.0)

    except Exception:
        return np.nan


def _factor_regression_core(strategy_returns: pd.Series, benchmark_returns: pd.Series) -> dict[str, Any]:
    """
    Régression simple strategy_return = alpha + beta * benchmark_return + residual.

    Lecture seule.
    """
    try:
        frame = pd.DataFrame(
            {
                "strategy": pd.to_numeric(strategy_returns, errors="coerce"),
                "benchmark": pd.to_numeric(benchmark_returns, errors="coerce"),
            }
        ).replace([np.inf, -np.inf], np.nan).dropna()

        if len(frame) < 30:
            return {}

        y = frame["strategy"].astype(float).values
        x = frame["benchmark"].astype(float).values

        x_var = float(np.var(x, ddof=1))
        y_var = float(np.var(y, ddof=1))

        if x_var <= 1e-12 or y_var <= 1e-12:
            return {}

        X = np.column_stack([np.ones(len(x)), x])
        coef = np.linalg.lstsq(X, y, rcond=None)[0]

        alpha_daily = float(coef[0])
        beta = float(coef[1])

        fitted = X @ coef
        residual = y - fitted

        ss_res = float(np.sum(residual ** 2))
        ss_tot = float(np.sum((y - y.mean()) ** 2))
        r2 = 1.0 - ss_res / ss_tot if ss_tot > 1e-12 else np.nan

        dof = max(len(y) - 2, 1)
        sigma2 = ss_res / dof

        try:
            cov = sigma2 * np.linalg.inv(X.T @ X)
            se_alpha = float(np.sqrt(cov[0, 0]))
            se_beta = float(np.sqrt(cov[1, 1]))
        except Exception:
            se_alpha = np.nan
            se_beta = np.nan

        t_alpha = alpha_daily / se_alpha if pd.notna(se_alpha) and se_alpha > 0 else np.nan
        t_beta = beta / se_beta if pd.notna(se_beta) and se_beta > 0 else np.nan

        corr = float(np.corrcoef(x, y)[0, 1]) if len(x) > 2 else np.nan

        active = frame["strategy"] - frame["benchmark"]
        tracking_error = float(active.std() * np.sqrt(252)) if active.std() > 0 else np.nan
        active_premium = float(active.mean() * 252)
        information_ratio = active_premium / tracking_error if pd.notna(tracking_error) and tracking_error > 0 else np.nan

        up_mask = frame["benchmark"] > 0
        down_mask = frame["benchmark"] < 0

        def _conditional_beta(mask: pd.Series) -> float:
            try:
                sub = frame.loc[mask].copy()
                if len(sub) < 10 or sub["benchmark"].var() <= 1e-12:
                    return np.nan
                return float(np.cov(sub["strategy"], sub["benchmark"])[0, 1] / sub["benchmark"].var())
            except Exception:
                return np.nan

        upside_beta = _conditional_beta(up_mask)
        downside_beta = _conditional_beta(down_mask)

        return {
            "n": int(len(frame)),
            "alpha_daily": alpha_daily,
            "alpha_ann": alpha_daily * 252.0,
            "beta": beta,
            "t_alpha": t_alpha,
            "t_beta": t_beta,
            "r2": r2,
            "corr": corr,
            "residual": pd.Series(residual, index=frame.index),
            "fitted": pd.Series(fitted, index=frame.index),
            "tracking_error": tracking_error,
            "active_premium": active_premium,
            "information_ratio": information_ratio,
            "upside_beta": upside_beta,
            "downside_beta": downside_beta,
            "frame": frame,
        }

    except Exception:
        return {}


def _factor_capture_ratio(strategy: pd.Series, benchmark: pd.Series, direction: str) -> float:
    """
    Capture ratio conditionnel :
    - up capture : perf stratégie quand benchmark > 0 / perf benchmark quand benchmark > 0
    - down capture : perf stratégie quand benchmark < 0 / perf benchmark quand benchmark < 0

    Pour le down capture, plus bas est généralement mieux si le benchmark baisse.
    """
    try:
        frame = pd.DataFrame(
            {
                "strategy": pd.to_numeric(strategy, errors="coerce"),
                "benchmark": pd.to_numeric(benchmark, errors="coerce"),
            }
        ).replace([np.inf, -np.inf], np.nan).dropna()

        if direction == "up":
            sub = frame[frame["benchmark"] > 0]
        else:
            sub = frame[frame["benchmark"] < 0]

        if len(sub) < 10:
            return np.nan

        s_ret = _factor_compound_return(sub["strategy"])
        b_ret = _factor_compound_return(sub["benchmark"])

        if pd.isna(b_ret) or abs(b_ret) <= 1e-12:
            return np.nan

        return float(s_ret / b_ret)

    except Exception:
        return np.nan


def _factor_conditional_table_v2(
    daily: pd.DataFrame,
    beta: float,
) -> pd.DataFrame:
    """
    Attribution conditionnelle benchmark up / down / flat.
    """
    if daily is None or daily.empty:
        return pd.DataFrame()

    rows = []

    regimes = [
        ("Benchmark up", daily["Benchmark Return"] > 0),
        ("Benchmark down", daily["Benchmark Return"] < 0),
        ("Benchmark flat", daily["Benchmark Return"].abs() <= 1e-12),
        ("Strategy active", daily["Abs Exposure"] > 0 if "Abs Exposure" in daily.columns else daily["Strategy Return"].abs() > 0),
        ("Strategy flat", daily["Abs Exposure"] <= 0 if "Abs Exposure" in daily.columns else daily["Strategy Return"].abs() <= 0),
    ]

    for name, mask in regimes:
        try:
            sub = daily.loc[mask].copy()

            if len(sub) < 5:
                continue

            s = sub["Strategy Return"]
            b = sub["Benchmark Return"]
            active = sub["Active Return"]
            beta_comp = sub["Beta Component Return"]
            residual = sub["Residual Return"]

            bench_total = _factor_compound_return(b)
            strat_total = _factor_compound_return(s)

            capture = strat_total / bench_total if pd.notna(bench_total) and abs(bench_total) > 1e-12 else np.nan

            rows.append(
                {
                    "Regime": name,
                    "Obs": int(len(sub)),
                    "Obs Share": len(sub) / max(len(daily), 1),
                    "Strategy Return": strat_total,
                    "Benchmark Return": bench_total,
                    "Active Return": _factor_compound_return(active),
                    "Beta Component Return": _factor_compound_return(beta_comp),
                    "Residual Return": _factor_compound_return(residual),
                    "Capture Ratio": capture,
                    "Avg Exposure": float(sub["Exposure"].mean()) if "Exposure" in sub.columns else np.nan,
                    "Avg Abs Exposure": float(sub["Abs Exposure"].mean()) if "Abs Exposure" in sub.columns else np.nan,
                    "Hit Rate": float((s > 0).mean()),
                    "Active Hit Rate": float((active > 0).mean()),
                    "Beta Used": beta,
                }
            )

        except Exception:
            continue

    return pd.DataFrame(rows)


def _factor_rolling_table_v2(bt: pd.DataFrame, window: int = 60) -> pd.DataFrame:
    """
    Rolling beta / alpha / R2 / active return.
    """
    if bt is None or bt.empty or len(bt) < window + 20:
        return pd.DataFrame()

    rows = []

    s = pd.to_numeric(bt["strategy_return"], errors="coerce")
    b = pd.to_numeric(bt["benchmark_return"], errors="coerce")

    for i in range(window, len(bt) + 1):
        sub_s = s.iloc[i - window:i]
        sub_b = b.iloc[i - window:i]
        pack = _factor_regression_core(sub_s, sub_b)

        if not pack:
            continue

        date = bt.index[i - 1]

        rows.append(
            {
                "Date": _format_dt(date),
                "Rolling Alpha Ann.": pack.get("alpha_ann", np.nan),
                "Rolling Beta": pack.get("beta", np.nan),
                "Rolling R2": pack.get("r2", np.nan),
                "Rolling Information Ratio": pack.get("information_ratio", np.nan),
                "Rolling Active Return": _factor_compound_return(sub_s - sub_b),
                "Obs": int(pack.get("n", 0)),
            }
        )

    return pd.DataFrame(rows)


def _factor_benchmark_attribution_v2_pack(bt: pd.DataFrame) -> dict[str, Any]:
    """
    Factor / Benchmark Attribution V2.

    Lecture seule :
    - ne modifie pas le moteur ;
    - ne modifie pas les trades ;
    - ne modifie pas l'equity curve ;
    - ne modifie pas le verdict.

    Objectif :
    distinguer :
    - beta component ;
    - residual / selection return ;
    - active return ;
    - market capture ;
    - benchmark timing ;
    - alpha réel vs exposition benchmark déguisée.
    """
    empty = {
        "level": "Unavailable",
        "score": np.nan,
        "read": "Attribution benchmark indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "decomposition": pd.DataFrame(),
        "conditional": pd.DataFrame(),
        "rolling": pd.DataFrame(),
        "daily_map": pd.DataFrame(),
        "drivers": [],
    }

    if bt is None or not isinstance(bt, pd.DataFrame) or bt.empty:
        return empty

    required = {"strategy_return", "benchmark_return"}
    if not required.issubset(set(bt.columns)):
        return empty

    strategy = pd.to_numeric(bt["strategy_return"], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
    benchmark = pd.to_numeric(bt["benchmark_return"], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)

    reg = _factor_regression_core(strategy, benchmark)

    if not reg:
        return empty

    beta = _safe_float(reg.get("beta"), np.nan)
    alpha_ann = _safe_float(reg.get("alpha_ann"), np.nan)
    t_alpha = _safe_float(reg.get("t_alpha"), np.nan)
    r2 = _safe_float(reg.get("r2"), np.nan)
    info_ratio = _safe_float(reg.get("information_ratio"), np.nan)
    tracking_error = _safe_float(reg.get("tracking_error"), np.nan)
    active_premium = _safe_float(reg.get("active_premium"), np.nan)
    upside_beta = _safe_float(reg.get("upside_beta"), np.nan)
    downside_beta = _safe_float(reg.get("downside_beta"), np.nan)

    beta_component = beta * benchmark
    residual_component = strategy - beta_component
    active_return = strategy - benchmark

    exposure = (
        pd.to_numeric(bt["exposure"], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
        if "exposure" in bt.columns
        else pd.Series(0.0, index=bt.index)
    )

    daily = pd.DataFrame(
        {
            "Date": [_format_dt(x) for x in bt.index],
            "Strategy Return": strategy,
            "Benchmark Return": benchmark,
            "Active Return": active_return,
            "Beta Component Return": beta_component,
            "Residual Return": residual_component,
            "Exposure": exposure,
            "Abs Exposure": exposure.abs(),
            "Benchmark Direction": np.where(benchmark > 0, "Benchmark up", np.where(benchmark < 0, "Benchmark down", "Benchmark flat")),
        },
        index=bt.index,
    )

    strategy_total = _factor_compound_return(strategy)
    benchmark_total = _factor_compound_return(benchmark)
    active_total = _factor_compound_return(active_return)
    beta_component_total = _factor_compound_return(beta_component)
    residual_total = _factor_compound_return(residual_component)

    up_capture = _factor_capture_ratio(strategy, benchmark, "up")
    down_capture = _factor_capture_ratio(strategy, benchmark, "down")

    bench_up = benchmark > 0
    bench_down = benchmark < 0

    avg_exp_up = float(exposure.loc[bench_up].mean()) if bench_up.any() else np.nan
    avg_exp_down = float(exposure.loc[bench_down].mean()) if bench_down.any() else np.nan
    timing_spread = avg_exp_up - avg_exp_down if pd.notna(avg_exp_up) and pd.notna(avg_exp_down) else np.nan

    drivers = []

    if pd.notna(alpha_ann) and alpha_ann < 0:
        drivers.append("negative regression alpha")

    if pd.notna(active_total) and active_total < 0:
        drivers.append("negative active return")

    if pd.notna(r2) and r2 > 0.55 and pd.notna(alpha_ann) and alpha_ann <= 0:
        drivers.append("benchmark-driven with no alpha")

    if pd.notna(up_capture) and up_capture < 0.60:
        drivers.append("weak upside capture")

    if pd.notna(down_capture) and down_capture > 1.00:
        drivers.append("high downside capture")

    if pd.notna(timing_spread) and timing_spread < -0.05:
        drivers.append("poor benchmark timing")

    if pd.notna(downside_beta) and pd.notna(upside_beta) and downside_beta > upside_beta + 0.25:
        drivers.append("asymmetric downside beta")

    alpha_score = _clip((alpha_ann + 0.10) / 0.30) * 30.0 if pd.notna(alpha_ann) else 0.0
    active_score = _clip((active_total + 0.10) / 0.30) * 20.0 if pd.notna(active_total) else 0.0
    residual_score = _clip((residual_total + 0.08) / 0.25) * 20.0 if pd.notna(residual_total) else 0.0

    up_score = _clip(up_capture / 1.00) * 15.0 if pd.notna(up_capture) else 7.5
    down_score = _clip((1.20 - down_capture) / 1.20) * 10.0 if pd.notna(down_capture) else 5.0
    timing_score = _clip((timing_spread + 0.20) / 0.40) * 5.0 if pd.notna(timing_spread) else 2.5

    score = alpha_score + active_score + residual_score + up_score + down_score + timing_score
    score = max(0.0, min(100.0, score))

    if pd.notna(alpha_ann) and alpha_ann > 0 and pd.notna(t_alpha) and t_alpha >= 1.5 and pd.notna(residual_total) and residual_total > 0:
        level = "Real alpha candidate"
        read = "Alpha positif, residual return positif et t-stat alpha convenable. À confirmer OOS."
    elif pd.notna(r2) and r2 >= 0.55 and pd.notna(alpha_ann) and alpha_ann <= 0:
        level = "Benchmark disguised"
        read = "La stratégie ressemble surtout à une exposition benchmark mal rémunérée."
    elif pd.notna(active_total) and active_total < 0 and pd.notna(alpha_ann) and alpha_ann < 0:
        level = "Negative active exposure"
        read = "La stratégie sous-performe le benchmark et présente un alpha de régression négatif."
    elif pd.notna(up_capture) and pd.notna(down_capture) and up_capture > 0.8 and down_capture < 0.8:
        level = "Constructive capture"
        read = "La capture de marché est relativement asymétrique dans le bon sens."
    else:
        level = "Mixed factor read"
        read = "L'attribution benchmark est mitigée : beta, capture et residual return ne donnent pas un signal net."

    decomposition = pd.DataFrame(
        [
            ["Strategy total return", strategy_total, "Performance composée de la stratégie."],
            ["Benchmark total return", benchmark_total, "Performance composée du benchmark."],
            ["Active return", active_total, "Performance stratégie moins benchmark."],
            ["Beta component return", beta_component_total, "Part du rendement expliquée par beta × benchmark_return."],
            ["Residual / selection return", residual_total, "Part non expliquée par le beta benchmark."],
            ["Alpha annualized", alpha_ann, "Intercept annualisé de la régression."],
            ["Alpha t-stat", t_alpha, "Significativité approximative de l'alpha."],
            ["Beta", beta, "Sensibilité moyenne au benchmark."],
            ["R2", r2, "Part de variance expliquée par le benchmark."],
            ["Information ratio", info_ratio, "Active premium / tracking error."],
            ["Tracking error ann.", tracking_error, "Volatilité annualisée de l'active return."],
            ["Active premium ann.", active_premium, "Moyenne annualisée stratégie - benchmark."],
            ["Up capture", up_capture, "Capture de la performance les jours benchmark positifs."],
            ["Down capture", down_capture, "Capture de la performance les jours benchmark négatifs."],
            ["Upside beta", upside_beta, "Beta conditionnel quand le benchmark monte."],
            ["Downside beta", downside_beta, "Beta conditionnel quand le benchmark baisse."],
            ["Avg exposure when benchmark up", avg_exp_up, "Exposition moyenne les jours benchmark positifs."],
            ["Avg exposure when benchmark down", avg_exp_down, "Exposition moyenne les jours benchmark négatifs."],
            ["Benchmark timing spread", timing_spread, "Exposition moyenne up moins exposition moyenne down."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    conditional = _factor_conditional_table_v2(daily, beta)
    rolling = _factor_rolling_table_v2(bt, window=60)

    summary = pd.DataFrame(
        [
            ["Factor level", level, "Lecture synthétique de l'attribution benchmark."],
            ["Factor score", f"{_format_num(score, 0)}/100", "Score interne combinant alpha, active return, residual return et capture."],
            ["Alpha annualized", _format_pct(alpha_ann), "Alpha annualisé de régression."],
            ["Beta", _format_num(beta), "Sensibilité au benchmark."],
            ["R2", _format_pct(r2), "Variance expliquée par le benchmark."],
            ["Active return", _format_pct(active_total), "Rendement actif composé."],
            ["Residual return", _format_pct(residual_total), "Rendement non expliqué par le beta benchmark."],
            ["Up capture", _format_pct(up_capture), "Capture en marché haussier benchmark."],
            ["Down capture", _format_pct(down_capture), "Capture en marché baissier benchmark."],
            ["Timing spread", _format_pct(timing_spread), "Exposition moyenne benchmark up moins benchmark down."],
            ["Failure drivers", "; ".join(drivers) if drivers else "None", "Raisons principales de fragilité factorielle."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    cards = [
        {"label": "Factor read", "value": level, "delta": f"{_format_num(score, 0)}/100"},
        {"label": "Alpha ann.", "value": _format_pct(alpha_ann), "delta": f"t={_format_num(t_alpha)}"},
        {"label": "Beta", "value": _format_num(beta), "delta": f"R2 {_format_pct(r2, 0)}"},
        {"label": "Active return", "value": _format_pct(active_total), "delta": "vs benchmark"},
        {"label": "Residual return", "value": _format_pct(residual_total), "delta": "selection"},
        {"label": "Up / Down capture", "value": f"{_format_pct(up_capture, 0)} / {_format_pct(down_capture, 0)}", "delta": "market capture"},
    ]

    return {
        "level": level,
        "score": score,
        "read": read,
        "cards": cards,
        "summary": summary,
        "decomposition": decomposition,
        "conditional": conditional,
        "rolling": rolling,
        "daily_map": daily,
        "drivers": drivers,
    }


def _render_factor_benchmark_attribution_v2(bt: pd.DataFrame) -> dict[str, Any]:
    """
    Rendu Streamlit Factor / Benchmark Attribution V2.
    """
    pack = _factor_benchmark_attribution_v2_pack(bt)

    st.subheader("Factor / Benchmark Attribution V2")
    st.caption(
        "Attribution benchmark lecture seule : beta component, active return, residual return, "
        "up/down capture, benchmark timing, rolling beta/alpha et failure drivers. "
        "Aucun impact sur le moteur, les trades, l'equity curve ou le verdict."
    )

    if pack.get("level") == "Unavailable":
        st.info("Factor Attribution V2 indisponible : benchmark ou historique insuffisant.")
        return pack

    _card_grid(pack.get("cards", []), columns=6)

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))

    if level in {"Benchmark disguised", "Negative active exposure"}:
        st.warning(f"Lecture factorielle : {read}")
    elif level in {"Mixed factor read"}:
        st.info(f"Lecture factorielle : {read}")
    else:
        st.success(f"Lecture factorielle : {read}")

    summary = pack.get("summary", pd.DataFrame())
    decomposition = pack.get("decomposition", pd.DataFrame())
    conditional = pack.get("conditional", pd.DataFrame())
    rolling = pack.get("rolling", pd.DataFrame())
    daily = pack.get("daily_map", pd.DataFrame())

    if isinstance(summary, pd.DataFrame) and not summary.empty:
        with st.expander("Factor V2 summary", expanded=True):
            st.dataframe(summary, use_container_width=True, hide_index=True)

    if isinstance(decomposition, pd.DataFrame) and not decomposition.empty:
        display_decomp = decomposition.copy()

        pct_metrics = {
            "Strategy total return",
            "Benchmark total return",
            "Active return",
            "Beta component return",
            "Residual / selection return",
            "Alpha annualized",
            "R2",
            "Tracking error ann.",
            "Active premium ann.",
            "Up capture",
            "Down capture",
            "Avg exposure when benchmark up",
            "Avg exposure when benchmark down",
            "Benchmark timing spread",
        }

        display_decomp["Value"] = display_decomp.apply(
            lambda row: _format_pct(row["Value"]) if row["Metric"] in pct_metrics else _format_num(row["Value"]),
            axis=1,
        )

        with st.expander("Benchmark decomposition table", expanded=True):
            st.dataframe(display_decomp, use_container_width=True, hide_index=True)

    if isinstance(conditional, pd.DataFrame) and not conditional.empty:
        display_cond = conditional.copy()

        for col in [
            "Obs Share",
            "Strategy Return",
            "Benchmark Return",
            "Active Return",
            "Beta Component Return",
            "Residual Return",
            "Capture Ratio",
            "Avg Exposure",
            "Avg Abs Exposure",
            "Hit Rate",
            "Active Hit Rate",
        ]:
            if col in display_cond.columns:
                display_cond[col] = display_cond[col].map(_format_pct)

        if "Beta Used" in display_cond.columns:
            display_cond["Beta Used"] = display_cond["Beta Used"].map(_format_num)

        with st.expander("Benchmark up/down attribution", expanded=True):
            st.dataframe(display_cond, use_container_width=True, hide_index=True)

    if isinstance(rolling, pd.DataFrame) and not rolling.empty:
        display_roll = rolling.tail(80).copy()

        for col in ["Rolling Alpha Ann.", "Rolling R2", "Rolling Active Return"]:
            if col in display_roll.columns:
                display_roll[col] = display_roll[col].map(_format_pct)

        for col in ["Rolling Beta", "Rolling Information Ratio"]:
            if col in display_roll.columns:
                display_roll[col] = display_roll[col].map(_format_num)

        with st.expander("Rolling factor map 60D", expanded=False):
            st.dataframe(display_roll, use_container_width=True, hide_index=True)

    if isinstance(daily, pd.DataFrame) and not daily.empty:
        daily_display = daily.tail(120).copy()

        for col in [
            "Strategy Return",
            "Benchmark Return",
            "Active Return",
            "Beta Component Return",
            "Residual Return",
            "Exposure",
            "Abs Exposure",
        ]:
            if col in daily_display.columns:
                daily_display[col] = daily_display[col].map(_format_pct)

        with st.expander("Daily benchmark attribution map — recent observations", expanded=False):
            st.dataframe(daily_display, use_container_width=True, hide_index=True)

    d1, d2, d3 = st.columns(3)

    if isinstance(decomposition, pd.DataFrame) and not decomposition.empty:
        d1.download_button(
            "Télécharger factor decomposition CSV",
            data=decomposition.to_csv(index=False).encode("utf-8"),
            file_name="factor_benchmark_decomposition_v2.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_factor_v2_decomposition_download",
        )

    if isinstance(conditional, pd.DataFrame) and not conditional.empty:
        d2.download_button(
            "Télécharger benchmark attribution CSV",
            data=conditional.to_csv(index=False).encode("utf-8"),
            file_name="factor_benchmark_conditional_v2.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_factor_v2_conditional_download",
        )

    if isinstance(daily, pd.DataFrame) and not daily.empty:
        d3.download_button(
            "Télécharger daily factor map CSV",
            data=daily.to_csv(index=False).encode("utf-8"),
            file_name="daily_factor_benchmark_map_v2.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_factor_v2_daily_download",
        )

    return pack




def _render_econometric_diagnostics(bt: pd.DataFrame) -> None:
    """
    Rendu Streamlit Econometric Diagnostics / MCO V1.
    Lecture seule.
    """
    pack = _econometric_diagnostics(bt)

    st.subheader("Econometric Diagnostics / MCO V1")
    st.caption(
        "Régression linéaire simple : strategy_return = alpha + beta × benchmark_return + résidus. "
        "Objectif : distinguer un vrai alpha d'une simple exposition déguisée au benchmark. "
        "Bloc lecture seule : aucun impact sur le moteur, les trades, l'equity curve ou le verdict."
    )

    summary = pack.get("summary", pd.DataFrame())

    if summary is None or summary.empty:
        st.info(pack.get("read", "Diagnostic MCO indisponible."))
        return

    _card_grid(pack.get("cards", []), columns=6)

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))

    if "Positive alpha" in level:
        st.success(f"Lecture MCO : {read}")
    elif "Negative alpha" in level or "Benchmark-driven" in level:
        st.warning(f"Lecture MCO : {read}")
    else:
        st.info(f"Lecture MCO : {read}")

    with st.expander("OLS alpha / beta summary", expanded=True):
        st.dataframe(summary, use_container_width=True, hide_index=True)

    rolling_summary = pack.get("rolling_summary", pd.DataFrame())

    if rolling_summary is not None and not rolling_summary.empty:
        with st.expander("Rolling alpha / beta summary", expanded=True):
            st.dataframe(rolling_summary, use_container_width=True, hide_index=True)

    rolling = pack.get("rolling", pd.DataFrame())

    if rolling is not None and not rolling.empty:
        display_rolling = rolling.tail(30).copy()

        for col in ["Rolling Alpha Ann.", "Rolling R²", "Rolling Residual Vol"]:
            if col in display_rolling.columns:
                display_rolling[col] = display_rolling[col].map(_format_pct)

        if "Rolling Beta" in display_rolling.columns:
            display_rolling["Rolling Beta"] = display_rolling["Rolling Beta"].map(_format_num)

        with st.expander("Rolling 60-bar alpha / beta map", expanded=False):
            st.caption("Dernières 30 observations rolling. Sert à détecter une instabilité du beta ou de l'alpha.")
            st.dataframe(display_rolling, use_container_width=True, hide_index=True)

    residuals = pack.get("residuals", pd.DataFrame())

    if residuals is not None and not residuals.empty:
        with st.expander("Residual diagnostics", expanded=True):
            st.dataframe(residuals, use_container_width=True, hide_index=True)



