def _test_harness_cases_v1(cfg: BacktestConfig) -> list[tuple[str, BacktestConfig]]:
    base_kwargs = dict(cfg.__dict__)

    cases = [
        ("Current configuration", cfg),
        (
            "SMA Trend / fixed exposure",
            BacktestConfig(
                **{
                    **base_kwargs,
                    "strategy": "SMA Trend",
                    "risk_layer_enabled": False,
                    "sizing_mode": "Fixed Exposure",
                    "margin_stress_enabled": False,
                    "benchmark_ticker": "",
                    "benchmark_label": "Ticker Buy & Hold",
                }
            ),
        ),
        (
            "SMA Trend / risk layer ON",
            BacktestConfig(
                **{
                    **base_kwargs,
                    "strategy": "SMA Trend",
                    "risk_layer_enabled": True,
                    "risk_use_stop_loss": True,
                    "risk_stop_loss_pct": 8.0,
                    "risk_use_take_profit": False,
                    "risk_use_trailing_stop": False,
                    "risk_use_max_holding": False,
                    "risk_use_ohlc_execution": True,
                    "sizing_mode": "Fixed Exposure",
                    "benchmark_ticker": "",
                    "benchmark_label": "Ticker Buy & Hold",
                }
            ),
        ),
        (
            "Manual Builder / fixed exposure",
            BacktestConfig(
                **{
                    **base_kwargs,
                    "strategy": "Manual Builder",
                    "risk_layer_enabled": False,
                    "sizing_mode": "Fixed Exposure",
                    "margin_stress_enabled": False,
                    "benchmark_ticker": "",
                    "benchmark_label": "Ticker Buy & Hold",
                }
            ),
        ),
        (
            "Breakout / fixed exposure",
            BacktestConfig(
                **{
                    **base_kwargs,
                    "strategy": "Breakout",
                    "risk_layer_enabled": False,
                    "sizing_mode": "Fixed Exposure",
                    "margin_stress_enabled": False,
                    "benchmark_ticker": "",
                    "benchmark_label": "Ticker Buy & Hold",
                }
            ),
        ),
    ]

    return cases


def _run_internal_test_harness_v1(df: pd.DataFrame, cfg: BacktestConfig) -> dict[str, Any]:
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return {
            "enabled": True,
            "level": "Failed",
            "score": 0.0,
            "read": "Données prix indisponibles.",
            "summary": pd.DataFrame(),
            "cases": pd.DataFrame(),
            "failures": pd.DataFrame([{"Case": "global", "Failure": "price dataframe empty"}]),
        }

    required_bt_cols = {
        "close",
        "signal",
        "exposure",
        "returns",
        "strategy_return",
        "benchmark_return",
        "equity",
        "benchmark",
    }

    required_metrics = {
        "Total Return",
        "CAGR",
        "Benchmark Return",
        "Relative Alpha",
        "Sharpe",
        "Max Drawdown",
        "Trades",
    }

    case_rows = []
    failure_rows = []

    for case_name, case_cfg in _test_harness_cases_v1(cfg):
        try:
            res = _run_backtest(df, case_cfg)

            if not isinstance(res, dict) or res.get("error"):
                err = str(res.get("error", "unknown engine error")) if isinstance(res, dict) else "invalid engine result"
                case_rows.append(
                    {
                        "Case": case_name,
                        "Status": "FAIL",
                        "Rows": 0,
                        "Trades": 0,
                        "Return": np.nan,
                        "Alpha": np.nan,
                        "Sharpe": np.nan,
                        "Max DD": np.nan,
                        "Integrity": 0,
                        "Failure": err,
                    }
                )
                failure_rows.append({"Case": case_name, "Failure": err})
                continue

            bt_i = res.get("data", pd.DataFrame())
            metrics_i = res.get("metrics", {})
            trades_i = res.get("trades", pd.DataFrame())

            missing_cols = sorted(list(required_bt_cols - set(bt_i.columns))) if isinstance(bt_i, pd.DataFrame) else sorted(list(required_bt_cols))
            missing_metrics = sorted(list(required_metrics - set(metrics_i.keys()))) if isinstance(metrics_i, dict) else sorted(list(required_metrics))

            integrity_i, _ = _integrity_score(metrics_i, bt_i, case_cfg)

            failures = []

            if bt_i is None or not isinstance(bt_i, pd.DataFrame) or bt_i.empty:
                failures.append("bt empty")

            if missing_cols:
                failures.append("missing bt columns: " + ", ".join(missing_cols))

            if missing_metrics:
                failures.append("missing metrics: " + ", ".join(missing_metrics))

            trades_count = int(metrics_i.get("Trades", 0) or 0) if isinstance(metrics_i, dict) else 0

            if failures:
                status = "FAIL"
            elif trades_count <= 0:
                status = "WARN"
                failures.append("no trades detected")
            elif integrity_i < 50:
                status = "WARN"
                failures.append("integrity below 50")
            else:
                status = "PASS"

            failure_text = "; ".join(failures) if failures else "None"

            if failures:
                failure_rows.append({"Case": case_name, "Failure": failure_text})

            case_rows.append(
                {
                    "Case": case_name,
                    "Status": status,
                    "Rows": int(len(bt_i)) if isinstance(bt_i, pd.DataFrame) else 0,
                    "Trades": trades_count,
                    "Return": metrics_i.get("Total Return", np.nan) if isinstance(metrics_i, dict) else np.nan,
                    "Alpha": metrics_i.get("Relative Alpha", np.nan) if isinstance(metrics_i, dict) else np.nan,
                    "Sharpe": metrics_i.get("Sharpe", np.nan) if isinstance(metrics_i, dict) else np.nan,
                    "Max DD": metrics_i.get("Max Drawdown", np.nan) if isinstance(metrics_i, dict) else np.nan,
                    "Integrity": integrity_i,
                    "Failure": failure_text,
                }
            )

        except Exception as exc:
            case_rows.append(
                {
                    "Case": case_name,
                    "Status": "FAIL",
                    "Rows": 0,
                    "Trades": 0,
                    "Return": np.nan,
                    "Alpha": np.nan,
                    "Sharpe": np.nan,
                    "Max DD": np.nan,
                    "Integrity": 0,
                    "Failure": str(exc),
                }
            )
            failure_rows.append({"Case": case_name, "Failure": str(exc)})

    cases_df = pd.DataFrame(case_rows)
    failures_df = pd.DataFrame(failure_rows)

    pass_count = int((cases_df["Status"] == "PASS").sum()) if not cases_df.empty else 0
    warn_count = int((cases_df["Status"] == "WARN").sum()) if not cases_df.empty else 0
    fail_count = int((cases_df["Status"] == "FAIL").sum()) if not cases_df.empty else 0

    total_cases = max(len(cases_df), 1)
    score = pass_count / total_cases * 100.0 + warn_count / total_cases * 50.0

    if fail_count > 0:
        level = "Failed"
        read = "Au moins un cas critique échoue. Corriger avant d'ajouter une nouvelle brique."
    elif warn_count > 0:
        level = "Warnings"
        read = "Aucun crash critique, mais certains cas sont fragiles ou sans trades."
    else:
        level = "Passed"
        read = "Tous les smoke tests internes passent sans erreur critique."

    summary = pd.DataFrame(
        [
            ["Harness level", level, "Lecture synthétique du Test Harness interne."],
            ["Harness score", f"{_format_num(score, 0)}/100", "Score PASS/WARN/FAIL."],
            ["Cases", str(len(cases_df)), "Nombre de configurations testées."],
            ["PASS", str(pass_count), "Cas sans erreur critique."],
            ["WARN", str(warn_count), "Cas fonctionnels mais fragiles."],
            ["FAIL", str(fail_count), "Cas en erreur critique."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    return {
        "enabled": True,
        "level": level,
        "score": score,
        "read": read,
        "summary": summary,
        "cases": cases_df,
        "failures": failures_df,
    }







def _test_harness_export_zip_audit_v15(
    report_md: str,
    manifest: dict[str, Any],
    tables: dict[str, Any],
    zip_bytes: bytes,
) -> dict[str, Any]:
    """
    Internal Test Harness V1.5 — Export ZIP Audit / Reproducibility Check.

    Lecture seule :
    - audite le ZIP généré ;
    - vérifie les fichiers attendus ;
    - vérifie la cohérence manifest/tables ;
    - vérifie les sections critiques du Markdown ;
    - ne modifie ni le moteur, ni les trades, ni l'equity curve, ni le verdict.
    """
    checks: list[dict[str, Any]] = []

    def _add(check: str, status: str, severity: str, value: Any, read: str) -> None:
        checks.append(
            {
                "Check": str(check),
                "Status": str(status).upper(),
                "Severity": str(severity),
                "Value": str(value),
                "Read": str(read),
            }
        )

    def _is_nonempty_df(value: Any) -> bool:
        return isinstance(value, pd.DataFrame) and not value.empty

    tables = tables if isinstance(tables, dict) else {}
    manifest = manifest if isinstance(manifest, dict) else {}

    expected_table_names = [
        str(name) for name, table in tables.items()
        if _is_nonempty_df(table)
    ]

    expected_files = ["research_report.md", "manifest.json"]

    for name in expected_table_names:
        if name == "summary":
            expected_files.append("summary.csv")
        else:
            expected_files.append(f"tables/{name}.csv")

    expected_files = list(dict.fromkeys(expected_files))

    zip_names: list[str] = []
    zip_ok = False

    try:
        if not isinstance(zip_bytes, (bytes, bytearray)) or len(zip_bytes) <= 0:
            raise ValueError("zip_bytes empty or invalid")

        with zipfile.ZipFile(BytesIO(zip_bytes), "r") as zf:
            zip_names = zf.namelist()
            bad_file = zf.testzip()
            if bad_file is not None:
                raise ValueError(f"ZIP corrupted at file: {bad_file}")
            zip_ok = True

        _add(
            "ZIP readable",
            "PASS",
            "None",
            f"{len(zip_names)} files",
            "Le ZIP est lisible et testzip ne détecte pas de corruption.",
        )

    except Exception as exc:
        _add(
            "ZIP readable",
            "FAIL",
            "Critical",
            "invalid",
            str(exc),
        )

    zip_set = set(zip_names)

    def _resolve_zip_name(expected: str) -> str | None:
        expected = str(expected)

        if expected in zip_set:
            return expected

        suffix = "/" + expected

        for name in zip_names:
            name_s = str(name)
            if name_s.endswith(suffix):
                return name_s

        return None

    missing_files = [f for f in expected_files if _resolve_zip_name(f) is None]

    _add(
        "Expected files present",
        "PASS" if not missing_files else "FAIL",
        "None" if not missing_files else "Critical",
        "None" if not missing_files else ", ".join(missing_files[:12]),
        "Vérifie que research_report.md, manifest.json, summary.csv et toutes les tables attendues sont dans le ZIP.",
    )

    duplicate_count = len(zip_names) - len(zip_set)

    _add(
        "No duplicate files in ZIP",
        "PASS" if duplicate_count == 0 else "WARN",
        "None" if duplicate_count == 0 else "Medium",
        duplicate_count,
        "Un ZIP reproductible ne doit pas contenir de doublons de chemins.",
    )

    try:
        json.dumps(manifest, ensure_ascii=False, default=_export_json_default)
        _add(
            "Manifest JSON serializable",
            "PASS",
            "None",
            "serializable",
            "Le manifest peut être sérialisé en JSON.",
        )
    except Exception as exc:
        _add(
            "Manifest JSON serializable",
            "FAIL",
            "Critical",
            "not serializable",
            str(exc),
        )

    manifest_tables = manifest.get("tables_included", [])
    if not isinstance(manifest_tables, list):
        manifest_tables = []

    manifest_tables_set = set([str(x) for x in manifest_tables])
    expected_tables_set = set(expected_table_names)

    missing_manifest_tables = sorted(expected_tables_set - manifest_tables_set)
    stale_manifest_tables = sorted(manifest_tables_set - expected_tables_set)

    manifest_ok = not missing_manifest_tables and not stale_manifest_tables

    _add(
        "Manifest tables_included matches exported tables",
        "PASS" if manifest_ok else "FAIL",
        "None" if manifest_ok else "High",
        f"manifest={len(manifest_tables_set)} / expected={len(expected_tables_set)}",
        (
            "Manifest tables_included cohérent avec les DataFrames non vides."
            if manifest_ok
            else f"Missing={missing_manifest_tables[:8]} / Stale={stale_manifest_tables[:8]}"
        ),
    )

    harness_block = manifest.get("internal_test_harness_v1", {})

    _add(
        "Manifest internal_test_harness_v1 block present",
        "PASS" if isinstance(harness_block, dict) and bool(harness_block) else "FAIL",
        "None" if isinstance(harness_block, dict) and bool(harness_block) else "High",
        "present" if isinstance(harness_block, dict) and bool(harness_block) else "missing",
        "Le manifest doit contenir le bloc internal_test_harness_v1.",
    )

    report_txt = str(report_md or "")

    required_sections = [
        "1. Verdict",
        "7. Internal Test Harness V1",
        "Failure severity ledger V1.4",
        "Causality / look-ahead guard V1.3",
        "Data integrity gates V1.2",
        "Module check matrix V1.1",
        "8. Reproducibility",
    ]

    missing_sections = [s for s in required_sections if s not in report_txt]

    _add(
        "Markdown required sections present",
        "PASS" if not missing_sections else "FAIL",
        "None" if not missing_sections else "High",
        "None" if not missing_sections else ", ".join(missing_sections),
        "Le rapport Markdown doit contenir les sections critiques de reproductibilité.",
    )

    csv_files = [f for f in expected_files if f.endswith(".csv")]
    empty_csv_files = []

    if zip_ok:
        try:
            with zipfile.ZipFile(BytesIO(zip_bytes), "r") as zf:
                for file_name in csv_files:
                    resolved_name = _resolve_zip_name(file_name)

                    if resolved_name is None:
                        continue

                    payload = zf.read(resolved_name)

                    if len(payload) <= 0:
                        empty_csv_files.append(file_name)
        except Exception as exc:
            empty_csv_files.append(f"csv read error: {exc}")

    _add(
        "CSV payloads non-empty",
        "PASS" if not empty_csv_files else "FAIL",
        "None" if not empty_csv_files else "High",
        "None" if not empty_csv_files else ", ".join(empty_csv_files[:10]),
        "Les fichiers CSV attendus doivent contenir un payload non vide.",
    )

    missing_core = [
        x for x in ["research_report.md", "manifest.json", "summary.csv"]
        if _resolve_zip_name(x) is None
    ]

    _add(
        "Core export files present",
        "PASS" if not missing_core else "FAIL",
        "None" if not missing_core else "Critical",
        "None" if not missing_core else ", ".join(missing_core),
        "Contrôle minimal des fichiers cœur.",
    )

    signal_safety_manifest = manifest.get("custom_signal_safety_v26", {})
    signal_safety_tables = [
        "custom_signal_safety_summary_v26",
        "custom_signal_safety_checks_v26",
        "custom_signal_safety_metadata_v26",
    ]

    signal_safety_detected = (
        isinstance(signal_safety_manifest, dict)
        and bool(signal_safety_manifest)
    ) or any(
        key in tables and isinstance(tables.get(key), pd.DataFrame) and not tables.get(key).empty
        for key in signal_safety_tables
    ) or ("Data Provenance & Signal Safety Gate V2.6" in report_txt)

    if signal_safety_detected:
        _add(
            "Manifest custom_signal_safety_v26 block present",
            "PASS" if isinstance(signal_safety_manifest, dict) and bool(signal_safety_manifest) else "FAIL",
            "None" if isinstance(signal_safety_manifest, dict) and bool(signal_safety_manifest) else "High",
            "present" if isinstance(signal_safety_manifest, dict) and bool(signal_safety_manifest) else "missing",
            "Le manifest doit contenir le bloc custom_signal_safety_v26.",
        )

        missing_signal_tables = [
            key for key in signal_safety_tables
            if key not in tables
            or not isinstance(tables.get(key), pd.DataFrame)
            or tables.get(key).empty
        ]

        _add(
            "Signal Safety V2.6 export tables present",
            "PASS" if not missing_signal_tables else "FAIL",
            "None" if not missing_signal_tables else "High",
            "None" if not missing_signal_tables else ", ".join(missing_signal_tables),
            "Les DataFrames Signal Safety V2.6 doivent être présents avant ZIP.",
        )

        missing_signal_files = [
            f"tables/{key}.csv"
            for key in signal_safety_tables
            if _resolve_zip_name(f"tables/{key}.csv") is None
        ]

        _add(
            "Signal Safety V2.6 export files present",
            "PASS" if not missing_signal_files else "FAIL",
            "None" if not missing_signal_files else "High",
            "None" if not missing_signal_files else ", ".join(missing_signal_files),
            "Les CSV Signal Safety V2.6 doivent être présents dans le ZIP final.",
        )

        _add(
            "Markdown Signal Safety V2.6 section present",
            "PASS" if "Data Provenance & Signal Safety Gate V2.6" in report_txt else "FAIL",
            "None" if "Data Provenance & Signal Safety Gate V2.6" in report_txt else "High",
            "present" if "Data Provenance & Signal Safety Gate V2.6" in report_txt else "missing",
            "Le rapport Markdown doit contenir la section Data Provenance & Signal Safety Gate V2.6.",
        )

        expected_manifest_keys = ["enabled", "level", "score", "decision_gate", "failures", "warnings"]
        missing_signal_manifest_keys = [
            key for key in expected_manifest_keys
            if not isinstance(signal_safety_manifest, dict) or key not in signal_safety_manifest
        ]

        _add(
            "Manifest Signal Safety V2.6 keys present",
            "PASS" if not missing_signal_manifest_keys else "WARN",
            "None" if not missing_signal_manifest_keys else "Medium",
            "None" if not missing_signal_manifest_keys else ", ".join(missing_signal_manifest_keys),
            "Le bloc manifest custom_signal_safety_v26 doit exposer level, score, gate et compteurs.",
        )


    checks_df = pd.DataFrame(checks)

    status_counts = checks_df["Status"].astype(str).str.upper().value_counts().to_dict()
    severity_counts = checks_df["Severity"].astype(str).value_counts().to_dict()

    pass_count = int(status_counts.get("PASS", 0))
    warn_count = int(status_counts.get("WARN", 0))
    fail_count = int(status_counts.get("FAIL", 0))

    critical_count = int(severity_counts.get("Critical", 0))
    high_count = int(severity_counts.get("High", 0))
    medium_count = int(severity_counts.get("Medium", 0))
    low_count = int(severity_counts.get("Low", 0))

    penalty = (
        critical_count * 35.0
        + high_count * 20.0
        + medium_count * 8.0
        + low_count * 3.0
        + warn_count * 2.0
    )

    score = max(0.0, min(100.0, 100.0 - penalty))

    if critical_count > 0:
        level = "Critical failure"
        read = "Export ZIP audit failed on critical reproducibility files."
    elif fail_count > 0 or high_count > 0:
        level = "Failed"
        read = "Export ZIP audit detected missing files or manifest inconsistency."
    elif warn_count > 0 or medium_count > 0 or low_count > 0:
        level = "Warnings"
        read = "Export ZIP audit passed core checks but has non-blocking warnings."
    else:
        level = "Clean"
        read = "ZIP, manifest, Markdown and table file set are coherent."

    summary = pd.DataFrame(
        [
            ["Export audit level", level, "Lecture synthétique de l'audit ZIP."],
            ["Export audit score", f"{_format_num(score, 0)}/100", "Score pénalisé par fichiers manquants, manifest incohérent ou sections absentes."],
            ["Expected files", str(len(expected_files)), "Nombre de fichiers attendus dans le ZIP."],
            ["ZIP files", str(len(zip_names)), "Nombre de fichiers observés dans le ZIP."],
            ["Tables expected", str(len(expected_table_names)), "Nombre de tables CSV attendues."],
            ["Missing files", str(len(missing_files)), "Fichiers attendus absents du ZIP."],
            ["PASS", str(pass_count), "Checks validés."],
            ["WARN", str(warn_count), "Checks en avertissement."],
            ["FAIL", str(fail_count), "Checks en échec."],
            ["Critical severity", str(critical_count), "Échecs bloquants."],
            ["High severity", str(high_count), "Échecs importants."],
            ["Medium severity", str(medium_count), "Avertissements moyens."],
            ["ZIP readable", str(bool(zip_ok)), "ZIP lisible par zipfile."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    return {
        "enabled": True,
        "level": level,
        "score": score,
        "read": read,
        "summary": summary,
        "checks": checks_df,
        "expected_files": expected_files,
        "zip_files": zip_names,
        "missing_files": missing_files,
        "fail_count": fail_count,
        "warn_count": warn_count,
        "critical_count": critical_count,
        "high_count": high_count,
    }



def _test_harness_failure_severity_ledger_v14(
    pack: dict[str, Any],
) -> dict[str, Any]:
    """
    Internal Test Harness V1.4 — Failure Severity Ledger.

    Agrège tous les contrôles internes :
    - smoke test cases ;
    - module checks V1.1 ;
    - data integrity gates V1.2 ;
    - causality / look-ahead guard V1.3 ;
    - failures explicites.

    Lecture seule :
    - ne relance pas le moteur ;
    - ne modifie ni le backtest, ni les trades, ni le verdict ;
    - transforme seulement les diagnostics existants en ledger institutionnel.
    """
    pack = pack if isinstance(pack, dict) else {}

    rows: list[dict[str, Any]] = []

    def _status_norm(value: Any) -> str:
        txt = str(value or "").strip().upper()
        if txt in {"PASS", "PASSED", "OK", "TRUE"}:
            return "PASS"
        if txt in {"WARN", "WARNING"}:
            return "WARN"
        if txt in {"FAIL", "FAILED", "ERROR", "CRITICAL"}:
            return "FAIL"
        if txt in {"SKIP", "SKIPPED", "N/A", "NA"}:
            return "SKIP"
        return txt if txt else "UNKNOWN"

    def _severity(block: str, status: str, check: str = "") -> str:
        status = _status_norm(status)
        block_l = str(block or "").lower()
        check_l = str(check or "").lower()

        if status == "PASS":
            return "None"

        if status == "SKIP":
            return "Info"

        if status == "WARN":
            if "causality" in block_l or "look-ahead" in block_l:
                return "High"
            if "data" in block_l or "integrity" in block_l:
                return "Medium"
            return "Low"

        if status == "FAIL":
            if (
                "causality" in block_l
                or "look-ahead" in block_l
                or "data" in block_l
                or "integrity" in block_l
                or "failure" in block_l
                or "engine" in check_l
                or "signal" in check_l
                or "equity" in check_l
                or "benchmark" in check_l
            ):
                return "Critical"

            if "module" in block_l:
                return "High"

            if "case" in block_l or "smoke" in block_l:
                return "High"

            return "Medium"

        return "Info"

    def _safe_text(value: Any) -> str:
        try:
            if value is None:
                return ""
            if pd.isna(value):
                return ""
        except Exception:
            pass
        return str(value)

    def _add_row(block: str, check: Any, status: Any, value: Any = "", read: Any = "") -> None:
        status_n = _status_norm(status)
        severity = _severity(block, status_n, _safe_text(check))

        rows.append(
            {
                "Block": str(block),
                "Check": _safe_text(check) or "N/A",
                "Status": status_n,
                "Severity": severity,
                "Value": _safe_text(value),
                "Read": _safe_text(read),
            }
        )

    def _add_frame(
        block: str,
        frame: Any,
        check_candidates: list[str],
        value_candidates: list[str] | None = None,
        read_candidates: list[str] | None = None,
    ) -> None:
        if frame is None or not isinstance(frame, pd.DataFrame) or frame.empty:
            return

        value_candidates = value_candidates or []
        read_candidates = read_candidates or ["Read", "Failure"]

        for _, row in frame.iterrows():
            check = "N/A"
            for col in check_candidates:
                if col in frame.columns:
                    check = row.get(col, "N/A")
                    break

            status = row.get("Status", row.get("Pass", "UNKNOWN"))

            if isinstance(status, (bool, np.bool_)):
                status = "PASS" if bool(status) else "FAIL"

            value = ""
            for col in value_candidates:
                if col in frame.columns:
                    value = row.get(col, "")
                    break

            read = ""
            for col in read_candidates:
                if col in frame.columns:
                    read = row.get(col, "")
                    break

            _add_row(block, check, status, value, read)

    cases = pack.get("cases", pd.DataFrame())
    failures = pack.get("failures", pd.DataFrame())
    modules = pack.get("module_checks", pd.DataFrame())
    data_gates = pack.get("data_integrity_gates", pd.DataFrame())
    causality = pack.get("causality_guard", pd.DataFrame())

    _add_frame(
        "Smoke test cases",
        cases,
        check_candidates=["Case"],
        value_candidates=["Trades", "Integrity", "Return"],
        read_candidates=["Failure"],
    )

    if isinstance(failures, pd.DataFrame) and not failures.empty:
        for _, row in failures.iterrows():
            check = row.get("Case", row.get("Gate", row.get("Module", "Failure")))
            read = row.get("Failure", row.get("Read", "Critical harness failure."))
            _add_row("Harness failures", check, "FAIL", "", read)

    _add_frame(
        "Module Check Matrix V1.1",
        modules,
        check_candidates=["Module", "Function"],
        value_candidates=["Rows"],
        read_candidates=["Read"],
    )

    _add_frame(
        "Data Integrity Gates V1.2",
        data_gates,
        check_candidates=["Gate"],
        value_candidates=["Value"],
        read_candidates=["Read"],
    )

    _add_frame(
        "Causality / Look-ahead Guard V1.3",
        causality,
        check_candidates=["Gate"],
        value_candidates=["Value"],
        read_candidates=["Read"],
    )

    ledger = pd.DataFrame(rows)

    if ledger.empty:
        ledger = pd.DataFrame(
            [
                {
                    "Block": "Failure Severity Ledger V1.4",
                    "Check": "No diagnostics available",
                    "Status": "WARN",
                    "Severity": "Medium",
                    "Value": "empty",
                    "Read": "Aucun diagnostic Test Harness disponible pour construire le ledger.",
                }
            ]
        )

    status_counts = ledger["Status"].astype(str).str.upper().value_counts().to_dict()
    severity_counts = ledger["Severity"].astype(str).value_counts().to_dict()

    pass_count = int(status_counts.get("PASS", 0))
    warn_count = int(status_counts.get("WARN", 0))
    fail_count = int(status_counts.get("FAIL", 0))
    skip_count = int(status_counts.get("SKIP", 0))
    unknown_count = int(status_counts.get("UNKNOWN", 0))

    critical_count = int(severity_counts.get("Critical", 0))
    high_count = int(severity_counts.get("High", 0))
    medium_count = int(severity_counts.get("Medium", 0))
    low_count = int(severity_counts.get("Low", 0))
    info_count = int(severity_counts.get("Info", 0))

    penalty = (
        critical_count * 35.0
        + high_count * 20.0
        + medium_count * 10.0
        + low_count * 4.0
        + skip_count * 2.0
        + unknown_count * 3.0
    )

    score = max(0.0, min(100.0, 100.0 - penalty))

    if critical_count > 0:
        level = "Critical failure"
        read = f"{critical_count} critical issue(s) detected. Harness output must be reviewed before trusting the research pack."
    elif high_count > 0 or fail_count > 0:
        level = "Failed"
        read = f"{fail_count} failed check(s) detected. Review high-severity diagnostics."
    elif warn_count > 0 or medium_count > 0 or low_count > 0:
        level = "Warnings"
        read = f"No hard failure, but {warn_count} warning(s) require review."
    else:
        level = "Clean"
        read = "All harness checks are PASS or non-critical. No severity issue detected."

    summary = pd.DataFrame(
        [
            ["Severity level", level, "Lecture synthétique du ledger."],
            ["Severity score", f"{_format_num(score, 0)}/100", "Score pénalisé par Critical/High/Medium/Low/WARN/SKIP."],
            ["Total checks", str(len(ledger)), "Nombre total de lignes consolidées."],
            ["PASS", str(pass_count), "Contrôles validés."],
            ["WARN", str(warn_count), "Contrôles en avertissement."],
            ["FAIL", str(fail_count), "Contrôles en échec."],
            ["SKIP", str(skip_count), "Contrôles ignorés ou indisponibles."],
            ["Critical severity", str(critical_count), "Problèmes bloquants : causalité, données, moteur, equity ou failures."],
            ["High severity", str(high_count), "Problèmes sérieux à traiter avant validation."],
            ["Medium severity", str(medium_count), "Problèmes de robustesse ou de qualité de diagnostic."],
            ["Low severity", str(low_count), "Avertissements non bloquants."],
            ["Info severity", str(info_count), "Informations / modules ignorés."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    return {
        "enabled": True,
        "level": level,
        "score": score,
        "read": read,
        "summary": summary,
        "ledger": ledger,
        "fail_count": fail_count,
        "warn_count": warn_count,
        "critical_count": critical_count,
        "high_count": high_count,
        "medium_count": medium_count,
        "low_count": low_count,
        "skip_count": skip_count,
    }



def _test_harness_causality_guard_v13(
    df: pd.DataFrame,
    cfg: BacktestConfig,
) -> pd.DataFrame:
    """
    Internal Test Harness V1.3 — Causality / Look-ahead Guard.

    Lecture seule :
    - reconstruit le signal brut causal ;
    - vérifie que le signal moteur correspond au signal brut décalé d'une barre ;
    - vérifie la cohérence exposure / returns / costs / equity / trades ;
    - ne modifie ni le moteur, ni les trades, ni l'equity curve, ni le verdict.
    """
    rows: list[dict[str, Any]] = []

    def _gate(gate: str, status: str, value: Any, read: str) -> None:
        rows.append(
            {
                "Gate": str(gate),
                "Status": str(status),
                "Value": str(value),
                "Read": str(read),
            }
        )

    def _max_abs_diff(a: Any, b: Any) -> float:
        try:
            aa = pd.to_numeric(a, errors="coerce")
            bb = pd.to_numeric(b, errors="coerce")
            diff = (aa - bb).replace([np.inf, -np.inf], np.nan).dropna()
            if diff.empty:
                return np.nan
            return float(diff.abs().max())
        except Exception:
            return np.nan

    def _finite_max_abs(series: Any) -> float:
        try:
            s = pd.to_numeric(series, errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
            if s.empty:
                return np.nan
            return float(s.abs().max())
        except Exception:
            return np.nan

    def _status_from_diff(diff: float, tol: float = 1e-10, warn_tol: float = 1e-6) -> str:
        if pd.isna(diff):
            return "WARN"
        if diff <= tol:
            return "PASS"
        if diff <= warn_tol:
            return "WARN"
        return "FAIL"

    def _expected_shifted_signal(price_df: pd.DataFrame, local_cfg: BacktestConfig) -> pd.Series:
        close = pd.to_numeric(price_df["close"], errors="coerce")
        raw = pd.Series(0.0, index=price_df.index)

        strategy = str(getattr(local_cfg, "strategy", ""))

        if strategy == "SMA Trend":
            fast = close.rolling(int(local_cfg.fast_ma)).mean()
            slow = close.rolling(int(local_cfg.slow_ma)).mean()

            if bool(local_cfg.allow_short):
                raw = pd.Series(
                    np.where(fast > slow, 1.0, np.where(fast < slow, -1.0, 0.0)),
                    index=price_df.index,
                )
            else:
                raw = pd.Series((fast > slow).astype(float), index=price_df.index)

        elif strategy == "Breakout":
            high = close.shift(1).rolling(int(local_cfg.breakout_window)).max()
            low = close.shift(1).rolling(int(local_cfg.breakout_window)).min()

            tmp = pd.Series(0.0, index=price_df.index)
            tmp[close > high] = 1.0

            if bool(local_cfg.allow_short):
                tmp[close < low] = -1.0

            raw = tmp.replace(0.0, np.nan).ffill().fillna(0.0)

        elif strategy == "RSI Mean Reversion":
            rsi = _rsi(close, int(local_cfg.rsi_window))

            tmp = pd.Series(np.nan, index=price_df.index)
            tmp[rsi < float(local_cfg.rsi_entry)] = 1.0
            tmp[rsi > float(local_cfg.rsi_exit)] = 0.0

            if bool(local_cfg.allow_short):
                tmp[rsi > (100.0 - float(local_cfg.rsi_entry))] = -1.0
                tmp[rsi < (100.0 - float(local_cfg.rsi_exit))] = 0.0

            raw = tmp.ffill().fillna(0.0)

        elif strategy == "Volatility Filter Trend":
            fast = close.rolling(int(local_cfg.fast_ma)).mean()
            slow = close.rolling(int(local_cfg.slow_ma)).mean()
            vol = close.pct_change().rolling(int(local_cfg.vol_window)).std() * np.sqrt(252.0)

            tmp = np.where((fast > slow) & (vol < float(local_cfg.vol_threshold)), 1.0, 0.0)

            if bool(local_cfg.allow_short):
                tmp = np.where((fast < slow) & (vol < float(local_cfg.vol_threshold)), -1.0, tmp)

            raw = pd.Series(tmp, index=price_df.index).fillna(0.0)

        elif strategy == "Decision Proxy":
            fast = close.rolling(int(local_cfg.fast_ma)).mean()
            slow = close.rolling(int(local_cfg.slow_ma)).mean()
            mom = close.pct_change(20)
            vol = close.pct_change().rolling(int(local_cfg.vol_window)).std() * np.sqrt(252.0)

            raw_score = (
                (fast > slow).astype(float) * 40.0
                + (mom > 0).astype(float) * 35.0
                + (vol < float(local_cfg.vol_threshold)).astype(float) * 25.0
            )

            tmp = (raw_score >= 65.0).astype(float)

            if bool(local_cfg.allow_short):
                tmp = np.where(raw_score <= 30.0, -1.0, tmp)

            raw = pd.Series(tmp, index=price_df.index).fillna(0.0)

        elif strategy == "Manual Builder":
            raw = _manual_builder_signal(price_df, local_cfg).fillna(0.0)

        elif strategy == "Custom Signal Import":
            raw = _align_custom_signal_to_prices(getattr(local_cfg, "custom_signal_df", None), price_df.index)

            if not bool(local_cfg.allow_short):
                raw = raw.clip(lower=0.0, upper=1.0)

        else:
            raw = pd.Series(0.0, index=price_df.index)

        return raw.shift(1).fillna(0.0).clip(-1.0, 1.0)

    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame(
            [
                {
                    "Gate": "Price dataframe",
                    "Status": "FAIL",
                    "Value": "empty",
                    "Read": "Aucune donnée prix exploitable pour le causality guard.",
                }
            ]
        )

    try:
        res = _run_backtest(df, cfg)
    except Exception as exc:
        return pd.DataFrame(
            [
                {
                    "Gate": "Backtest engine run",
                    "Status": "FAIL",
                    "Value": "exception",
                    "Read": str(exc),
                }
            ]
        )

    if not isinstance(res, dict) or res.get("error"):
        return pd.DataFrame(
            [
                {
                    "Gate": "Backtest engine run",
                    "Status": "FAIL",
                    "Value": str(res.get("error", "invalid result")) if isinstance(res, dict) else "invalid result",
                    "Read": "Le moteur doit produire un résultat avant contrôle de causalité.",
                }
            ]
        )

    bt = res.get("data", pd.DataFrame())
    trades = res.get("trades", pd.DataFrame())
    risk_events = res.get("risk_events", pd.DataFrame())

    if bt is None or not isinstance(bt, pd.DataFrame) or bt.empty:
        return pd.DataFrame(
            [
                {
                    "Gate": "Backtest dataframe",
                    "Status": "FAIL",
                    "Value": "empty",
                    "Read": "Backtest vide après exécution moteur.",
                }
            ]
        )

    # --------------------------------------------------------
    # Signal t+1 / look-ahead guard
    # --------------------------------------------------------
    try:
        expected = _expected_shifted_signal(df, cfg).reindex(bt.index).fillna(0.0)
        engine_base = pd.to_numeric(bt.get("base_signal", pd.Series(0.0, index=bt.index)), errors="coerce").fillna(0.0)
        engine_signal = pd.to_numeric(bt.get("signal", pd.Series(0.0, index=bt.index)), errors="coerce").fillna(0.0)

        diff_base = _max_abs_diff(engine_base, expected)

        _gate(
            "Base signal equals raw signal shifted t+1",
            _status_from_diff(diff_base),
            _format_num(diff_base, 12),
            "Reconstruit le signal brut causal puis vérifie le décalage d'une barre.",
        )

        first_base = float(engine_base.iloc[0]) if len(engine_base) else np.nan
        first_signal = float(engine_signal.iloc[0]) if len(engine_signal) else np.nan

        _gate(
            "First base signal bar zero",
            "PASS" if pd.notna(first_base) and abs(first_base) <= 1e-12 else "FAIL",
            _format_num(first_base, 12),
            "Le signal t+1 doit être neutre sur la première barre.",
        )

        _gate(
            "First effective signal bar zero",
            "PASS" if pd.notna(first_signal) and abs(first_signal) <= 1e-12 else "WARN",
            _format_num(first_signal, 12),
            "Le signal effectif doit idéalement rester neutre sur la première barre.",
        )

    except Exception as exc:
        _gate(
            "Base signal equals raw signal shifted t+1",
            "FAIL",
            "exception",
            str(exc),
        )

    # --------------------------------------------------------
    # Exposure / signal causality
    # --------------------------------------------------------
    if "exposure" in bt.columns and "signal" in bt.columns:
        exposure = pd.to_numeric(bt["exposure"], errors="coerce").fillna(0.0)
        signal = pd.to_numeric(bt["signal"], errors="coerce").fillna(0.0)

        first_exposure = float(exposure.iloc[0]) if len(exposure) else np.nan

        _gate(
            "First exposure bar zero",
            "PASS" if pd.notna(first_exposure) and abs(first_exposure) <= 1e-12 else "FAIL",
            _format_num(first_exposure, 12),
            "Aucune exposition ne doit exister avant la première décision décalée.",
        )

        active_exposure = exposure.abs() > 1e-12
        active_without_signal = active_exposure & (signal.abs() <= 1e-12)
        active_without_signal_share = float(active_without_signal.mean()) if len(active_without_signal) else 0.0

        _gate(
            "No exposure without signal",
            "PASS" if active_without_signal_share <= 1e-12 else "FAIL",
            _format_pct(active_without_signal_share),
            "Une exposition active doit être portée par un signal actif.",
        )

        sign_mismatch = active_exposure & (np.sign(exposure) != np.sign(signal))
        sign_mismatch_share = float(sign_mismatch.mean()) if len(sign_mismatch) else 0.0

        _gate(
            "Exposure sign matches signal sign",
            "PASS" if sign_mismatch_share <= 1e-12 else "FAIL",
            _format_pct(sign_mismatch_share),
            "Le signe de l'exposition doit correspondre au signe du signal.",
        )

    # --------------------------------------------------------
    # Return / costs / equity accounting
    # --------------------------------------------------------
    if all(c in bt.columns for c in ["strategy_return", "gross_return", "costs"]):
        net_expected = pd.to_numeric(bt["gross_return"], errors="coerce") - pd.to_numeric(bt["costs"], errors="coerce")
        diff_net = _max_abs_diff(bt["strategy_return"], net_expected)

        _gate(
            "Net return equals gross minus costs",
            _status_from_diff(diff_net),
            _format_num(diff_net, 12),
            "strategy_return doit être égal à gross_return - costs.",
        )

    if all(c in bt.columns for c in ["gross_return", "exposure", "returns"]):
        expected_gross = pd.to_numeric(bt["exposure"], errors="coerce").fillna(0.0) * pd.to_numeric(bt["returns"], errors="coerce").fillna(0.0)

        mask = pd.Series(True, index=bt.index)

        if "risk_exit_reason" in bt.columns:
            risk_reason = bt["risk_exit_reason"].astype(str).fillna("")
            mask = risk_reason.str.strip().eq("")

        if mask.any():
            diff_gross = _max_abs_diff(bt.loc[mask, "gross_return"], expected_gross.loc[mask])
        else:
            diff_gross = np.nan

        _gate(
            "Gross return equals exposure times asset return",
            _status_from_diff(diff_gross, tol=1e-9, warn_tol=1e-5),
            _format_num(diff_gross, 12),
            "Hors sorties Risk Layer, gross_return doit suivre exposure × returns.",
        )

    if all(c in bt.columns for c in ["turnover", "exposure"]):
        exposure = pd.to_numeric(bt["exposure"], errors="coerce").fillna(0.0)
        expected_turnover = exposure.diff().abs().fillna(exposure.abs())
        diff_turnover = _max_abs_diff(bt["turnover"], expected_turnover)

        _gate(
            "Turnover equals absolute exposure change",
            _status_from_diff(diff_turnover),
            _format_num(diff_turnover, 12),
            "turnover doit être égal à abs(diff exposure), première barre incluse.",
        )

    if all(c in bt.columns for c in ["costs", "turnover"]):
        cost_rate = (float(getattr(cfg, "fee_bps", 0.0)) + float(getattr(cfg, "slippage_bps", 0.0))) / 10000.0
        expected_costs = pd.to_numeric(bt["turnover"], errors="coerce").fillna(0.0) * cost_rate
        diff_costs = _max_abs_diff(bt["costs"], expected_costs)

        _gate(
            "Costs equal turnover times cost rate",
            _status_from_diff(diff_costs),
            _format_num(diff_costs, 12),
            "Les coûts doivent être mécaniquement liés au turnover et aux bps configurés.",
        )

    if all(c in bt.columns for c in ["equity", "strategy_return"]):
        net = pd.to_numeric(bt["strategy_return"], errors="coerce").fillna(0.0)
        expected_equity = float(getattr(cfg, "capital", 1.0)) * (1.0 + net).cumprod()
        diff_equity = _max_abs_diff(bt["equity"], expected_equity)

        _gate(
            "Equity recursion",
            _status_from_diff(diff_equity, tol=1e-6, warn_tol=1e-3),
            _format_num(diff_equity, 8),
            "L'equity curve doit correspondre à capital × cumprod(1 + strategy_return).",
        )

    if all(c in bt.columns for c in ["benchmark", "benchmark_return"]):
        bench_ret = pd.to_numeric(bt["benchmark_return"], errors="coerce").fillna(0.0)
        expected_benchmark = float(getattr(cfg, "capital", 1.0)) * (1.0 + bench_ret).cumprod()
        diff_benchmark = _max_abs_diff(bt["benchmark"], expected_benchmark)

        _gate(
            "Benchmark recursion",
            _status_from_diff(diff_benchmark, tol=1e-6, warn_tol=1e-3),
            _format_num(diff_benchmark, 8),
            "La courbe benchmark doit correspondre à capital × cumprod(1 + benchmark_return).",
        )

    # --------------------------------------------------------
    # Trades causality
    # --------------------------------------------------------
    if trades is None or not isinstance(trades, pd.DataFrame) or trades.empty:
        _gate(
            "Trade causality sample",
            "WARN",
            "0 trades",
            "Aucun trade pour valider la causalité trade-level.",
        )
    else:
        if "Entry Bar" in trades.columns:
            entry_bar = pd.to_numeric(trades["Entry Bar"], errors="coerce")
            valid_entry_bounds = ((entry_bar >= 0) & (entry_bar < len(bt))).fillna(False)
            entry_bounds_share = float(valid_entry_bounds.mean()) if len(valid_entry_bounds) else 0.0

            _gate(
                "Trade entry bars inside backtest",
                "PASS" if entry_bounds_share >= 0.99 else "FAIL",
                _format_pct(entry_bounds_share),
                "Chaque Entry Bar doit pointer dans le backtest.",
            )

            if "exposure" in bt.columns:
                exposure = pd.to_numeric(bt["exposure"], errors="coerce").fillna(0.0)
                active_ok = []

                for _, tr in trades.iterrows():
                    eb = int(_safe_float(tr.get("Entry Bar"), -1))
                    if 0 <= eb < len(bt):
                        active_ok.append(abs(float(exposure.iloc[eb])) > 1e-12)
                    else:
                        active_ok.append(False)

                active_share = float(pd.Series(active_ok).mean()) if active_ok else 0.0

                _gate(
                    "Trade entry has active exposure",
                    "PASS" if active_share >= 0.99 else "FAIL",
                    _format_pct(active_share),
                    "Une entrée trade doit correspondre à une barre d'exposition active.",
                )

        if "Entry Bar" in trades.columns and "Exit Bar" in trades.columns:
            entry_bar = pd.to_numeric(trades["Entry Bar"], errors="coerce")
            exit_bar = pd.to_numeric(trades["Exit Bar"], errors="coerce")

            valid_order = ((entry_bar <= exit_bar) & entry_bar.notna() & exit_bar.notna())
            order_share = float(valid_order.mean()) if len(valid_order) else 0.0

            _gate(
                "Trade entry before exit",
                "PASS" if order_share >= 0.99 else "FAIL",
                _format_pct(order_share),
                "Entry Bar doit être inférieur ou égal à Exit Bar.",
            )

            valid_exit_bounds = ((exit_bar >= 0) & (exit_bar < len(bt))).fillna(False)
            exit_bounds_share = float(valid_exit_bounds.mean()) if len(valid_exit_bounds) else 0.0

            _gate(
                "Trade exit bars inside backtest",
                "PASS" if exit_bounds_share >= 0.99 else "FAIL",
                _format_pct(exit_bounds_share),
                "Chaque Exit Bar doit pointer dans le backtest.",
            )

    # --------------------------------------------------------
    # Risk exits alignment
    # --------------------------------------------------------
    risk_enabled = bool(getattr(cfg, "risk_layer_enabled", False))

    if risk_enabled:
        if risk_events is None or not isinstance(risk_events, pd.DataFrame):
            _gate(
                "Risk event causality",
                "FAIL",
                "invalid",
                "Risk Layer actif : risk_events doit être un DataFrame.",
            )
        elif risk_events.empty:
            _gate(
                "Risk event causality",
                "PASS",
                "0 events",
                "Risk Layer actif mais aucune sortie risque déclenchée sur cette fenêtre.",
            )
        else:
            if "risk_exit_reason" in bt.columns:
                risk_reason = bt["risk_exit_reason"].astype(str).str.strip()
                marked_bars = int((risk_reason != "").sum())

                _gate(
                    "Risk exits marked on backtest bars",
                    "PASS" if marked_bars >= min(len(risk_events), len(bt)) else "WARN",
                    f"events={len(risk_events)} / marked_bars={marked_bars}",
                    "Les sorties risk doivent laisser une trace sur les barres du backtest.",
                )
            else:
                _gate(
                    "Risk exits marked on backtest bars",
                    "WARN",
                    "risk_exit_reason missing",
                    "Colonne risk_exit_reason absente.",
                )
    else:
        _gate(
            "Risk layer disabled causality",
            "PASS",
            "disabled",
            "Risk Layer désactivé : pas de contrôle risk-exit nécessaire.",
        )

    out = pd.DataFrame(rows)

    if out.empty:
        return pd.DataFrame(
            [
                {
                    "Gate": "Causality / Look-ahead Guard",
                    "Status": "WARN",
                    "Value": "empty",
                    "Read": "Aucun gate généré.",
                }
            ]
        )

    return out



def _test_harness_data_integrity_gates_v12(
    df: pd.DataFrame,
    cfg: BacktestConfig,
) -> pd.DataFrame:
    """
    Internal Test Harness V1.2 — Data Integrity Gates.

    Lecture seule :
    - relance le backtest courant ;
    - vérifie les données prix, les colonnes moteur, les rendements, l'equity,
      le benchmark, les expositions, les coûts et les trades ;
    - ne modifie ni le moteur, ni les trades, ni l'equity curve, ni le verdict.
    """
    rows: list[dict[str, Any]] = []

    def _gate(gate: str, status: str, value: Any, read: str) -> None:
        rows.append(
            {
                "Gate": str(gate),
                "Status": str(status),
                "Value": str(value),
                "Read": str(read),
            }
        )

    def _finite_share(series: Any) -> float:
        try:
            s = pd.to_numeric(series, errors="coerce").replace([np.inf, -np.inf], np.nan)
            if len(s) == 0:
                return 0.0
            return float(s.notna().mean())
        except Exception:
            return 0.0

    def _bool_status(condition: bool, warn: bool = False) -> str:
        if condition:
            return "PASS"
        return "WARN" if warn else "FAIL"

    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame(
            [
                {
                    "Gate": "Price dataframe",
                    "Status": "FAIL",
                    "Value": "empty",
                    "Read": "Aucune donnée prix exploitable.",
                }
            ]
        )

    # -----------------------------
    # Prix / index
    # -----------------------------
    price_rows = int(len(df))
    _gate(
        "Price rows",
        "PASS" if price_rows >= 60 else "FAIL",
        price_rows,
        "Minimum requis : 60 observations.",
    )

    idx_unique = bool(df.index.is_unique)
    _gate(
        "Index unique",
        "PASS" if idx_unique else "FAIL",
        idx_unique,
        "L'index prix ne doit pas contenir de doublons.",
    )

    try:
        if _is_datetime_like_index(df.index):
            idx_sorted = bool(pd.Index(pd.to_datetime(df.index)).is_monotonic_increasing)
            idx_mode = "datetime"
        else:
            idx_sorted = bool(df.index.is_monotonic_increasing)
            idx_mode = "non-datetime"
    except Exception:
        idx_sorted = False
        idx_mode = "unknown"

    _gate(
        "Index sorted",
        "PASS" if idx_sorted else "WARN",
        idx_mode,
        "Un index non trié peut casser l'interprétation temporelle.",
    )

    for col in ["close", "open", "high", "low"]:
        if col in df.columns:
            share = _finite_share(df[col])
            _gate(
                f"Price column {col}",
                "PASS" if share >= 0.98 else "WARN",
                _format_pct(share),
                f"Part de valeurs finies dans {col}.",
            )
        else:
            status = "FAIL" if col == "close" else "WARN"
            _gate(
                f"Price column {col}",
                status,
                "missing",
                f"Colonne {col} absente.",
            )

    if "close" in df.columns:
        close = pd.to_numeric(df["close"], errors="coerce").replace([np.inf, -np.inf], np.nan)
        positive_share = float((close > 0).mean()) if len(close) else 0.0
        _gate(
            "Close positive",
            "PASS" if positive_share >= 0.99 else "FAIL",
            _format_pct(positive_share),
            "Le close doit être positif sur presque toute la fenêtre.",
        )

        ret = close.pct_change().replace([np.inf, -np.inf], np.nan).dropna()
        ret_finite_share = float(ret.notna().mean()) if len(ret) else 0.0
        _gate(
            "Raw return finite",
            "PASS" if ret_finite_share >= 0.98 else "WARN",
            _format_pct(ret_finite_share),
            "Les rendements prix bruts doivent être finis.",
        )

    if all(c in df.columns for c in ["open", "high", "low", "close"]):
        open_ = pd.to_numeric(df["open"], errors="coerce")
        high = pd.to_numeric(df["high"], errors="coerce")
        low = pd.to_numeric(df["low"], errors="coerce")
        close = pd.to_numeric(df["close"], errors="coerce")

        valid_ohlc = (
            (high >= open_)
            & (high >= close)
            & (low <= open_)
            & (low <= close)
            & (high >= low)
        )

        valid_share = float(valid_ohlc.fillna(False).mean()) if len(valid_ohlc) else 0.0

        _gate(
            "OHLC consistency",
            "PASS" if valid_share >= 0.98 else "WARN",
            _format_pct(valid_share),
            "Vérifie high/low/open/close : high doit dominer, low doit être inférieur.",
        )
    else:
        _gate(
            "OHLC consistency",
            "WARN",
            "partial OHLC",
            "OHLC incomplet : certains diagnostics utilisent un fallback close-only.",
        )

    # -----------------------------
    # Backtest engine
    # -----------------------------
    try:
        res = _run_backtest(df, cfg)
    except Exception as exc:
        return pd.DataFrame(
            rows
            + [
                {
                    "Gate": "Backtest engine run",
                    "Status": "FAIL",
                    "Value": "exception",
                    "Read": str(exc),
                }
            ]
        )

    if not isinstance(res, dict) or res.get("error"):
        _gate(
            "Backtest engine run",
            "FAIL",
            str(res.get("error", "invalid result")) if isinstance(res, dict) else "invalid result",
            "Le moteur doit produire un résultat exploitable.",
        )
        return pd.DataFrame(rows)

    bt = res.get("data", pd.DataFrame())
    trades = res.get("trades", pd.DataFrame())
    risk_events = res.get("risk_events", pd.DataFrame())
    metrics = res.get("metrics", {})

    _gate(
        "Backtest engine run",
        "PASS" if isinstance(bt, pd.DataFrame) and not bt.empty else "FAIL",
        f"{len(bt) if isinstance(bt, pd.DataFrame) else 0} rows",
        "Le moteur doit retourner un DataFrame backtest non vide.",
    )

    if bt is None or not isinstance(bt, pd.DataFrame) or bt.empty:
        return pd.DataFrame(rows)

    required_cols = [
        "close",
        "signal",
        "exposure",
        "returns",
        "benchmark_return",
        "strategy_return",
        "gross_return",
        "costs",
        "turnover",
        "equity",
        "benchmark",
    ]

    missing_cols = [c for c in required_cols if c not in bt.columns]

    _gate(
        "Backtest required columns",
        "PASS" if not missing_cols else "FAIL",
        "None" if not missing_cols else ", ".join(missing_cols),
        "Colonnes moteur critiques attendues dans bt.",
    )

    _gate(
        "Backtest row count",
        "PASS" if len(bt) >= 60 else "FAIL",
        len(bt),
        "Nombre d'observations conservées après nettoyage moteur.",
    )

    try:
        aligned_len = abs(len(bt) - len(df)) <= max(5, int(len(df) * 0.05))
    except Exception:
        aligned_len = False

    _gate(
        "Price/backtest length alignment",
        "PASS" if aligned_len else "WARN",
        f"price={len(df)} / bt={len(bt)}",
        "Le nettoyage moteur ne doit pas supprimer une part excessive des données.",
    )

    finite_cols = [
        "returns",
        "benchmark_return",
        "strategy_return",
        "gross_return",
        "costs",
        "turnover",
        "equity",
        "benchmark",
        "signal",
        "exposure",
    ]

    for col in finite_cols:
        if col in bt.columns:
            share = _finite_share(bt[col])
            _gate(
                f"Finite {col}",
                "PASS" if share >= 0.995 else "FAIL",
                _format_pct(share),
                f"Part de valeurs finies dans {col}.",
            )

    if "equity" in bt.columns:
        eq = pd.to_numeric(bt["equity"], errors="coerce").replace([np.inf, -np.inf], np.nan)
        positive_eq = float((eq > 0).mean()) if len(eq) else 0.0
        _gate(
            "Equity positive",
            "PASS" if positive_eq >= 0.995 else "FAIL",
            _format_pct(positive_eq),
            "L'equity curve doit rester positive.",
        )

    if "signal" in bt.columns:
        sig = pd.to_numeric(bt["signal"], errors="coerce").replace([np.inf, -np.inf], np.nan)
        max_abs_sig = float(sig.abs().max()) if sig.notna().any() else np.nan
        _gate(
            "Signal bounds",
            "PASS" if pd.notna(max_abs_sig) and max_abs_sig <= 1.000001 else "FAIL",
            _format_num(max_abs_sig),
            "Le signal moteur doit être borné dans [-1, 1].",
        )

        first_signal = float(sig.iloc[0]) if len(sig) and pd.notna(sig.iloc[0]) else np.nan
        _gate(
            "First signal bar zero",
            "PASS" if pd.notna(first_signal) and abs(first_signal) <= 1e-12 else "WARN",
            _format_num(first_signal),
            "Proxy causal : le premier signal doit être neutre après décalage t+1.",
        )

    if "exposure" in bt.columns:
        exp = pd.to_numeric(bt["exposure"], errors="coerce").replace([np.inf, -np.inf], np.nan)
        max_abs_exp = float(exp.abs().max()) if exp.notna().any() else np.nan
        _gate(
            "Exposure bounds",
            "PASS" if pd.notna(max_abs_exp) and max_abs_exp <= 1.000001 else "FAIL",
            _format_num(max_abs_exp),
            "L'exposition finale doit être bornée dans [-1, 1].",
        )

    if "costs" in bt.columns:
        costs = pd.to_numeric(bt["costs"], errors="coerce").replace([np.inf, -np.inf], np.nan)
        min_cost = float(costs.min()) if costs.notna().any() else np.nan
        _gate(
            "Costs non-negative",
            "PASS" if pd.notna(min_cost) and min_cost >= -1e-12 else "FAIL",
            _format_num(min_cost),
            "Les coûts doivent être nuls ou positifs.",
        )

    if "turnover" in bt.columns:
        turnover = pd.to_numeric(bt["turnover"], errors="coerce").replace([np.inf, -np.inf], np.nan)
        min_turnover = float(turnover.min()) if turnover.notna().any() else np.nan
        _gate(
            "Turnover non-negative",
            "PASS" if pd.notna(min_turnover) and min_turnover >= -1e-12 else "FAIL",
            _format_num(min_turnover),
            "Le turnover doit être nul ou positif.",
        )

    if isinstance(metrics, dict):
        metric_keys = ["Total Return", "CAGR", "Benchmark Return", "Relative Alpha", "Sharpe", "Max Drawdown", "Trades"]
        missing_metrics = [k for k in metric_keys if k not in metrics]
        _gate(
            "Core metrics present",
            "PASS" if not missing_metrics else "FAIL",
            "None" if not missing_metrics else ", ".join(missing_metrics),
            "Métriques principales attendues après moteur.",
        )

    # -----------------------------
    # Trades
    # -----------------------------
    if trades is None or not isinstance(trades, pd.DataFrame) or trades.empty:
        _gate(
            "Trades dataframe",
            "WARN",
            "0 rows",
            "Aucun trade extrait. Peut être normal pour un signal flat, mais limite la validation.",
        )
    else:
        trade_required = ["Entry Date", "Exit Date", "Entry Bar", "Exit Bar", "Side", "Entry Price", "Exit Price", "Return"]
        missing_trade_cols = [c for c in trade_required if c not in trades.columns]

        _gate(
            "Trade required columns",
            "PASS" if not missing_trade_cols else "FAIL",
            "None" if not missing_trade_cols else ", ".join(missing_trade_cols),
            "Colonnes trade-level nécessaires aux diagnostics.",
        )

        if "Entry Bar" in trades.columns and "Exit Bar" in trades.columns:
            entry_bar = pd.to_numeric(trades["Entry Bar"], errors="coerce")
            exit_bar = pd.to_numeric(trades["Exit Bar"], errors="coerce")
            valid_order = ((entry_bar <= exit_bar) & entry_bar.notna() & exit_bar.notna())
            valid_order_share = float(valid_order.mean()) if len(valid_order) else 0.0

            _gate(
                "Trade bar order",
                "PASS" if valid_order_share >= 0.99 else "FAIL",
                _format_pct(valid_order_share),
                "Chaque trade doit avoir Entry Bar <= Exit Bar.",
            )

        if "Return" in trades.columns:
            trade_ret_share = _finite_share(trades["Return"])
            _gate(
                "Trade returns finite",
                "PASS" if trade_ret_share >= 0.99 else "FAIL",
                _format_pct(trade_ret_share),
                "Les rendements trade-level doivent être finis.",
            )

    # -----------------------------
    # Risk events
    # -----------------------------
    risk_layer_enabled = bool(getattr(cfg, "risk_layer_enabled", False))

    if risk_layer_enabled:
        if risk_events is None or not isinstance(risk_events, pd.DataFrame):
            _gate(
                "Risk events dataframe",
                "FAIL",
                "invalid",
                "Risk Layer actif : risk_events doit être un DataFrame.",
            )
        else:
            _gate(
                "Risk events dataframe",
                "PASS",
                f"{len(risk_events)} rows",
                "Risk Layer actif : risk_events collecté correctement.",
            )
    else:
        _gate(
            "Risk events disabled",
            "PASS",
            f"{len(risk_events) if isinstance(risk_events, pd.DataFrame) else 0} rows",
            "Risk Layer désactivé : risk_events peut rester vide.",
        )

    out = pd.DataFrame(rows)

    if out.empty:
        return pd.DataFrame(
            [
                {
                    "Gate": "Data Integrity Gates",
                    "Status": "WARN",
                    "Value": "empty",
                    "Read": "Aucun gate généré.",
                }
            ]
        )

    return out



def _test_harness_module_checks_v11(
    df: pd.DataFrame,
    cfg: BacktestConfig,
) -> pd.DataFrame:
    """
    Internal Test Harness V1.1 — Module Check Matrix.

    Lecture seule :
    - relance le backtest courant ;
    - vérifie que les principaux modules analytiques sont appelables ;
    - ne modifie ni le moteur, ni les trades, ni l'equity curve, ni le verdict.
    """
    rows: list[dict[str, Any]] = []

    def _rows_count(result: Any) -> int:
        try:
            if isinstance(result, pd.DataFrame):
                return int(len(result))

            if isinstance(result, tuple):
                total = 0
                for item in result:
                    if isinstance(item, pd.DataFrame):
                        total += int(len(item))
                    elif isinstance(item, dict):
                        for value in item.values():
                            if isinstance(value, pd.DataFrame):
                                total += int(len(value))
                return total

            if isinstance(result, dict):
                total = 0
                for value in result.values():
                    if isinstance(value, pd.DataFrame):
                        total += int(len(value))
                return total

            return 0
        except Exception:
            return 0

    try:
        res = _run_backtest(df, cfg)

        if not isinstance(res, dict) or res.get("error"):
            err = str(res.get("error", "unknown backtest error")) if isinstance(res, dict) else "invalid backtest result"
            return pd.DataFrame(
                [
                    {
                        "Module": "Backtest core",
                        "Function": "_run_backtest",
                        "Status": "FAIL",
                        "Rows": 0,
                        "Read": err,
                    }
                ]
            )

        bt = res.get("data", pd.DataFrame())
        trades = res.get("trades", pd.DataFrame())
        risk_events = res.get("risk_events", pd.DataFrame())

    except Exception as exc:
        return pd.DataFrame(
            [
                {
                    "Module": "Backtest core",
                    "Function": "_run_backtest",
                    "Status": "FAIL",
                    "Rows": 0,
                    "Read": str(exc),
                }
            ]
        )

    def _run_check(module: str, function_name: str, fn: Any, *args: Any) -> None:
        try:
            if fn is None or not callable(fn):
                rows.append(
                    {
                        "Module": module,
                        "Function": function_name,
                        "Status": "SKIP",
                        "Rows": 0,
                        "Read": "Function not present in current file.",
                    }
                )
                return

            result = fn(*args)

            rows.append(
                {
                    "Module": module,
                    "Function": function_name,
                    "Status": "PASS",
                    "Rows": _rows_count(result),
                    "Read": "Module callable.",
                }
            )

        except Exception as exc:
            rows.append(
                {
                    "Module": module,
                    "Function": function_name,
                    "Status": "FAIL",
                    "Rows": 0,
                    "Read": str(exc),
                }
            )

    try:
        wf_df = _walk_forward_segments(bt)
        rows.append(
            {
                "Module": "Walk-forward segments",
                "Function": "_walk_forward_segments",
                "Status": "PASS",
                "Rows": int(len(wf_df)) if isinstance(wf_df, pd.DataFrame) else 0,
                "Read": "Module callable.",
            }
        )
    except Exception as exc:
        wf_df = pd.DataFrame()
        rows.append(
            {
                "Module": "Walk-forward segments",
                "Function": "_walk_forward_segments",
                "Status": "FAIL",
                "Rows": 0,
                "Read": str(exc),
            }
        )

    _run_check(
        "OOS Validation V2",
        "_oos_validation_v2_pack",
        globals().get("_oos_validation_v2_pack"),
        bt,
        wf_df,
    )

    _run_check(
        "Factor / Benchmark Attribution V2",
        "_factor_benchmark_attribution_v2_pack",
        globals().get("_factor_benchmark_attribution_v2_pack"),
        bt,
    )

    _run_check(
        "Regime Attribution V2",
        "_regime_attribution_v2_pack",
        globals().get("_regime_attribution_v2_pack"),
        bt,
    )

    _run_check(
        "Leverage / Margin Stress V1",
        "_leverage_margin_stress_pack",
        globals().get("_leverage_margin_stress_pack"),
        bt,
        cfg,
    )

    _run_check(
        "Trade Lifecycle Audit V1",
        "_trade_lifecycle_audit_pack",
        globals().get("_trade_lifecycle_audit_pack"),
        bt,
        trades,
        cfg,
        risk_events,
    )

    _run_check(
        "Exit Efficiency Lab",
        "_exit_efficiency_lab",
        globals().get("_exit_efficiency_lab"),
        bt,
        trades,
        cfg,
    )

    _run_check(
        "Entry / Signal Quality Lab",
        "_entry_signal_quality_lab",
        globals().get("_entry_signal_quality_lab"),
        bt,
        trades,
    )

    out = pd.DataFrame(rows)

    if out.empty:
        return pd.DataFrame(
            [
                {
                    "Module": "Module Check Matrix",
                    "Function": "_test_harness_module_checks_v11",
                    "Status": "WARN",
                    "Rows": 0,
                    "Read": "No module check row generated.",
                }
            ]
        )

    return out



def _render_internal_test_harness_v1(df: pd.DataFrame, cfg: BacktestConfig) -> dict[str, Any]:
    st.subheader("Internal Test Harness V1")
    st.caption(
        "Smoke tests internes lecture seule : relance plusieurs configurations contrôlées "
        "et vérifie que le moteur produit des données, métriques et trades exploitables. "
        "Aucun impact sur le backtest courant, les trades, l'equity curve ou le verdict."
    )

    run_harness = st.button(
        "Lancer Test Harness V1",
        key="bt_internal_test_harness_v1_run",
        use_container_width=True,
    )

    if run_harness:
        with st.spinner("Test Harness V1 en cours..."):
            pack = _run_internal_test_harness_v1(df, cfg)
        st.session_state["bt_internal_test_harness_v1_pack"] = pack
    else:
        pack = st.session_state.get(
            "bt_internal_test_harness_v1_pack",
            _test_harness_empty_pack_v1(),
        )

    if not isinstance(pack, dict):
        pack = _test_harness_empty_pack_v1()

    if not bool(pack.get("enabled", False)):
        st.info("Test Harness V1 non exécuté. Clique sur le bouton pour lancer les smoke tests internes.")
        return pack

    level = str(pack.get("level", "Not run"))
    score = _safe_float(pack.get("score"), np.nan)

    module_checks = pack.get("module_checks", pd.DataFrame())

    if not isinstance(module_checks, pd.DataFrame) or module_checks.empty:
        module_checks = _test_harness_module_checks_v11(df, cfg)
        pack["module_checks"] = module_checks
        st.session_state["bt_internal_test_harness_v1_pack"] = pack

    data_gates = pack.get("data_integrity_gates", pd.DataFrame())

    if not isinstance(data_gates, pd.DataFrame) or data_gates.empty:
        data_gates = _test_harness_data_integrity_gates_v12(df, cfg)
        pack["data_integrity_gates"] = data_gates
        st.session_state["bt_internal_test_harness_v1_pack"] = pack

    causality_guard = pack.get("causality_guard", pd.DataFrame())

    if not isinstance(causality_guard, pd.DataFrame) or causality_guard.empty:
        causality_guard = _test_harness_causality_guard_v13(df, cfg)
        pack["causality_guard"] = causality_guard
        st.session_state["bt_internal_test_harness_v1_pack"] = pack

    severity_pack = pack.get("failure_severity_ledger", {})

    if not isinstance(severity_pack, dict) or not isinstance(severity_pack.get("ledger", None), pd.DataFrame):
        severity_pack = _test_harness_failure_severity_ledger_v14(pack)
        pack["failure_severity_ledger"] = severity_pack
        st.session_state["bt_internal_test_harness_v1_pack"] = pack

    severity_summary = severity_pack.get("summary", pd.DataFrame()) if isinstance(severity_pack, dict) else pd.DataFrame()
    severity_ledger = severity_pack.get("ledger", pd.DataFrame()) if isinstance(severity_pack, dict) else pd.DataFrame()

    cards = [
        {"label": "Harness read", "value": level, "delta": f"{_format_num(score, 0)}/100"},
        {"label": "Cases", "value": str(len(pack.get("cases", pd.DataFrame()))), "delta": "configs"},
        {"label": "Failures", "value": str(len(pack.get("failures", pd.DataFrame()))), "delta": "issues"},
        {
            "label": "Module checks",
            "value": str(len(module_checks)) if isinstance(module_checks, pd.DataFrame) else "0",
            "delta": (
                f"{int((module_checks['Status'].astype(str) == 'FAIL').sum())} fail"
                if isinstance(module_checks, pd.DataFrame) and not module_checks.empty and "Status" in module_checks.columns
                else "diagnostics"
            ),
        },
        {
            "label": "Data gates",
            "value": str(len(data_gates)) if isinstance(data_gates, pd.DataFrame) else "0",
            "delta": (
                f"{int((data_gates['Status'].astype(str) == 'FAIL').sum())} fail"
                if isinstance(data_gates, pd.DataFrame) and not data_gates.empty and "Status" in data_gates.columns
                else "integrity"
            ),
        },
        {
            "label": "Causality",
            "value": str(len(causality_guard)) if isinstance(causality_guard, pd.DataFrame) else "0",
            "delta": (
                f"{int((causality_guard['Status'].astype(str) == 'FAIL').sum())} fail"
                if isinstance(causality_guard, pd.DataFrame) and not causality_guard.empty and "Status" in causality_guard.columns
                else "look-ahead"
            ),
        },
        {
            "label": "Severity ledger",
            "value": str(severity_pack.get("level", "N/A")) if isinstance(severity_pack, dict) else "N/A",
            "delta": (
                f"{int(severity_pack.get('fail_count', 0))} fail / {int(severity_pack.get('warn_count', 0))} warn"
                if isinstance(severity_pack, dict)
                else "severity"
            ),
        },
    ]

    _card_grid(cards, columns=3)

    if level == "Failed":
        st.warning(f"Lecture Test Harness : {pack.get('read', '')}")
    elif level == "Warnings":
        st.info(f"Lecture Test Harness : {pack.get('read', '')}")
    else:
        st.success(f"Lecture Test Harness : {pack.get('read', '')}")

    summary = pack.get("summary", pd.DataFrame())
    cases = pack.get("cases", pd.DataFrame())
    failures = pack.get("failures", pd.DataFrame())

    if isinstance(summary, pd.DataFrame) and not summary.empty:
        display_summary = summary.copy().astype(str)
        with st.expander("Test Harness summary", expanded=True):
            st.dataframe(display_summary, use_container_width=True, hide_index=True)

    if isinstance(cases, pd.DataFrame) and not cases.empty:
        display_cases = cases.copy()

        for col in ["Return", "Alpha", "Max DD"]:
            if col in display_cases.columns:
                display_cases[col] = display_cases[col].map(_format_pct)

        if "Sharpe" in display_cases.columns:
            display_cases["Sharpe"] = display_cases["Sharpe"].map(_format_num)

        if "Integrity" in display_cases.columns:
            display_cases["Integrity"] = display_cases["Integrity"].map(lambda x: f"{int(_safe_float(x, 0))}/100")

        for col in display_cases.columns:
            display_cases[col] = display_cases[col].astype(str)

        with st.expander("Test cases matrix", expanded=True):
            st.dataframe(display_cases, use_container_width=True, hide_index=True)

    if isinstance(severity_ledger, pd.DataFrame) and not severity_ledger.empty:
        with st.expander("Failure severity ledger V1.4", expanded=True):
            if isinstance(severity_summary, pd.DataFrame) and not severity_summary.empty:
                st.markdown("**Severity summary**")
                st.dataframe(severity_summary, use_container_width=True, hide_index=True)

            display_severity = severity_ledger.copy()

            for col in display_severity.columns:
                display_severity[col] = display_severity[col].astype(str)

            st.markdown("**Consolidated check ledger**")
            st.dataframe(display_severity, use_container_width=True, hide_index=True)

    if isinstance(causality_guard, pd.DataFrame) and not causality_guard.empty:
        display_causality = causality_guard.copy()

        for col in display_causality.columns:
            display_causality[col] = display_causality[col].astype(str)

        with st.expander("Causality / look-ahead guard V1.3", expanded=True):
            st.dataframe(display_causality, use_container_width=True, hide_index=True)

    if isinstance(data_gates, pd.DataFrame) and not data_gates.empty:
        display_gates = data_gates.copy()

        for col in display_gates.columns:
            display_gates[col] = display_gates[col].astype(str)

        with st.expander("Data integrity gates V1.2", expanded=True):
            st.dataframe(display_gates, use_container_width=True, hide_index=True)

    if isinstance(module_checks, pd.DataFrame) and not module_checks.empty:
        display_modules = module_checks.copy()

        if "Rows" in display_modules.columns:
            display_modules["Rows"] = pd.to_numeric(
                display_modules["Rows"],
                errors="coerce",
            ).fillna(0).astype(int)

        for col in display_modules.columns:
            if col != "Rows":
                display_modules[col] = display_modules[col].astype(str)

        with st.expander("Module check matrix V1.1", expanded=True):
            st.dataframe(display_modules, use_container_width=True, hide_index=True)

    if isinstance(failures, pd.DataFrame) and not failures.empty:
        display_failures = failures.copy().astype(str)
        with st.expander("Harness failures", expanded=True):
            st.dataframe(display_failures, use_container_width=True, hide_index=True)
    else:
        with st.expander("Harness failures", expanded=False):
            st.info("Aucun failure critique détecté.")

    return pack


