    def _md_cell(value: Any) -> str:
        try:
            if value is None or pd.isna(value):
                return "N/A"
        except Exception:
            pass

        txt = str(value)
        txt = txt.replace("|", "/")
        txt = txt.replace("\n", " ")
        txt = txt.replace("\r", " ")
        return txt.strip() if txt.strip() else "N/A"

