                {"section": "execution_realism_v28", "item": "median_dollar_volume", "value": _safe_float(execution_realism_pack.get("median_dollar_volume"), np.nan)},
                {"section": "execution_realism_v28", "item": "max_trade_adv", "value": _safe_float(execution_realism_pack.get("max_trade_adv"), np.nan)},
                {"section": "execution_realism_v28", "item": "worst_active_gap", "value": _safe_float(execution_realism_pack.get("worst_active_gap"), np.nan)},
