        "Signal Date",
        "Entry Date",
        "Exit Date",
        "Entry Bar",
        "Exit Bar",
        "Bars",
        "Base Signal",
        "Engine Signal",
        "Entry Exposure",
        "Exit Exposure",
        "Sizing Exposure",
        "Sizing Multiplier",
        "Input Vol Ann.",
        "Risk Budget Cap",
        "Entry Price",
        "Exit Price",
        "Return",
        "MFE",
        "MAE",
        "MFE Capture",
        "Entry Equity",
        "Exit Equity",
        "Entry Cost $",
        "Exit Cost $",
        "Total Cost $",
        "Total Cost % of Entry Equity",
        "Entry Reason",
        "Exit Reason",
        "Risk Exit",
        "Risk Rule",
        "Risk Fill Price",
        "Risk Position Scaled Return",
        "Risk Execution Assumption",
        "Margin Stress Tag",
