def _controlled_mutation_runner_v36_plan(cfg: BacktestConfig) -> pd.DataFrame:
    """Queue V3.6 : mutations BRT contrôlées, une hypothèse à la fois."""
    dual = bool(getattr(cfg, "brt_require_dual_horizon", True))
    gate = bool(getattr(cfg, "brt_use_benchmark_trend_gate", True))
    volcap = bool(getattr(cfg, "brt_use_vol_cap", False))
    fast = int(getattr(cfg, "brt_fast_horizon", 20))
    slow = int(getattr(cfg, "brt_slow_horizon", 60))
    min_mom = float(getattr(cfg, "brt_min_active_mom_pct", 0.0))

    return pd.DataFrame([
        [0, "RUN-V36-BASE", "Current BRT control", "none", "baseline", "control only"],
        [1, "RUN-V36-01", "Relax dual horizon", "brt_require_dual_horizon", f"{dual} -> {not dual}", "alpha>0, Sharpe>0, trades>=10"],
        [2, "RUN-V36-02", "Benchmark trend gate flip", "brt_use_benchmark_trend_gate", f"{gate} -> {not gate}", "test if gate blocks/helps edge"],
        [3, "RUN-V36-03", "Active momentum threshold relaxation", "brt_min_active_mom_pct", f"{min_mom:g} -> -1.0", "more sample without alpha collapse"],
        [4, "RUN-V36-04", "Volatility cap flip", "brt_use_vol_cap", f"{volcap} -> {not volcap}", "CVaR/DD improve without killing alpha"],
        [5, "RUN-V36-05", "Faster active horizons", "horizon-pair hypothesis", f"{fast}/{slow} -> 10/40", "follow-through and active alpha improve"],
    ], columns=["Order", "Run ID", "Mutation", "One Factor Changed", "Config Delta", "Promotion Gate"])


def _controlled_mutation_runner_v36_mutated_cfg(cfg: BacktestConfig, run_id: str) -> BacktestConfig:
    """Retourne une copie mutée de cfg. Ne modifie jamais cfg en place."""
    d = dict(cfg.__dict__)
    d["strategy"] = "Benchmark-Relative Trend"

    if run_id == "RUN-V36-01":
        d["brt_require_dual_horizon"] = not bool(getattr(cfg, "brt_require_dual_horizon", True))
    elif run_id == "RUN-V36-02":
        d["brt_use_benchmark_trend_gate"] = not bool(getattr(cfg, "brt_use_benchmark_trend_gate", True))
    elif run_id == "RUN-V36-03":
        d["brt_min_active_mom_pct"] = -1.0
    elif run_id == "RUN-V36-04":
        d["brt_use_vol_cap"] = not bool(getattr(cfg, "brt_use_vol_cap", False))
    elif run_id == "RUN-V36-05":
        d["brt_fast_horizon"] = 10
        d["brt_slow_horizon"] = 40

    return BacktestConfig(**d)


def _controlled_mutation_runner_v36_score(metrics: dict[str, Any], integrity: int) -> float:
    """Score research simple : alpha, return, Sharpe, drawdown, sample, intégrité."""
    alpha = _safe_float(metrics.get("Relative Alpha"), 0.0)
    total = _safe_float(metrics.get("Total Return"), 0.0)
    sharpe = _safe_float(metrics.get("Sharpe"), np.nan)
    max_dd = _safe_float(metrics.get("Max Drawdown"), 0.0)
    trades = int(metrics.get("Trades", 0) or 0)

    alpha_score = _clip((alpha + 0.10) / 0.35) * 100.0
    return_score = _clip((total + 0.05) / 0.30) * 100.0
    sharpe_score = _clip((sharpe + 0.50) / 1.50) * 100.0 if pd.notna(sharpe) else 0.0
    dd_score = _clip((max_dd + 0.45) / 0.45) * 100.0
    trade_score = _clip(trades / 30.0) * 100.0

    score = (
        alpha_score * 0.30
        + return_score * 0.20
        + sharpe_score * 0.18
        + dd_score * 0.12
        + trade_score * 0.10
        + float(integrity) * 0.10
    )

    if trades < 5:
        score = min(score, 45.0)
    if alpha <= 0 and total <= 0:
        score = min(score, 40.0)

    return max(0.0, min(100.0, float(score)))


def _controlled_mutation_runner_v36_decision(metrics: dict[str, Any], score: float) -> str:
    alpha = _safe_float(metrics.get("Relative Alpha"), 0.0)
    total = _safe_float(metrics.get("Total Return"), 0.0)
    sharpe = _safe_float(metrics.get("Sharpe"), np.nan)
    max_dd = _safe_float(metrics.get("Max Drawdown"), 0.0)
    trades = int(metrics.get("Trades", 0) or 0)

    if alpha > 0 and total > 0 and pd.notna(sharpe) and sharpe > 0 and trades >= 10 and max_dd > -0.30:
        return "PROMOTE TO OOS RETEST"
    if alpha > 0 and trades < 10:
        return "HOLD / NEED SAMPLE"
    if score >= 55 and (alpha > 0 or total > 0):
        return "MANUAL REVIEW"
    return "REJECT MUTATION"


def _controlled_mutation_runner_v36_pack(df: pd.DataFrame, cfg: BacktestConfig) -> dict[str, Any]:
    """
    Controlled Mutation Runner V3.6.
    Lecture seule : relance une queue courte BRT ; aucun impact sur moteur/trades/equity/verdict courants.
    """
    plan = _controlled_mutation_runner_v36_plan(cfg)

    if str(getattr(cfg, "strategy", "")) != "Benchmark-Relative Trend":
        return {
            "level": "Not applicable",
            "score": np.nan,
            "decision": "NO RUN",
            "read": "V3.6 cible uniquement Benchmark-Relative Trend.",
            "plan": plan,
            "summary": pd.DataFrame(),
            "results": pd.DataFrame(),
            "gates": pd.DataFrame(),
            "cards": [
                {"label": "Mutation runner", "value": "Not applicable", "delta": "BRT only"},
                {"label": "Queue", "value": str(len(plan)), "delta": "planned"},
                {"label": "Decision", "value": "NO RUN", "delta": "V3.6"},
            ],
        }

    rows = []
    gate_rows = []
    base = {}

    for _, prow in plan.iterrows():
        run_id = str(prow["Run ID"])
        try:
            test_cfg = _controlled_mutation_runner_v36_mutated_cfg(cfg, run_id)
            res = _run_backtest(df, test_cfg)
            if not isinstance(res, dict) or "metrics" not in res or "data" not in res:
                raise RuntimeError(str(res.get("error", "run failed")) if isinstance(res, dict) else "run failed")

            m = res["metrics"]
            integ, notes = _integrity_score(m, res["data"], test_cfg)
            verdict_run, _, reasons = _verdict(m, integ, notes)
            score = _controlled_mutation_runner_v36_score(m, integ)
            decision = _controlled_mutation_runner_v36_decision(m, score)

            alpha = _safe_float(m.get("Relative Alpha"), np.nan)
            total = _safe_float(m.get("Total Return"), np.nan)
            sharpe = _safe_float(m.get("Sharpe"), np.nan)
            max_dd = _safe_float(m.get("Max Drawdown"), np.nan)
            trades_n = int(m.get("Trades", 0) or 0)
            exposure = _safe_float(m.get("Exposure"), np.nan)

            if run_id == "RUN-V36-BASE":
                base = {"alpha": alpha, "total": total, "sharpe": sharpe, "trades": trades_n}

            rows.append({
                "Order": int(prow["Order"]),
                "Run ID": run_id,
                "Mutation": str(prow["Mutation"]),
                "One Factor Changed": str(prow["One Factor Changed"]),
                "Config Delta": str(prow["Config Delta"]),
                "Score": score,
                "Decision": decision,
                "Verdict": verdict_run,
                "Total Return": total,
                "Benchmark Return": _safe_float(m.get("Benchmark Return"), np.nan),
                "Alpha": alpha,
                "Sharpe": sharpe,
                "Max DD": max_dd,
                "Trades": trades_n,
                "Exposure": exposure,
                "Integrity": integ,
                "BRT Activity": str(m.get("BRT V3.5b Level", "N/A")),
                "Engine Active Bars": int(m.get("BRT V3.5b Engine Active Bars", 0) or 0),
                "Reasons": "; ".join([str(x) for x in reasons]) if reasons else "N/A",
            })

            for gate_name, ok, val in [
                ("Active alpha > 0", alpha > 0, alpha),
                ("Total return > 0", total > 0, total),
                ("Sharpe > 0", pd.notna(sharpe) and sharpe > 0, sharpe),
                ("Trades >= 10", trades_n >= 10, trades_n),
                ("Max DD > -30%", pd.notna(max_dd) and max_dd > -0.30, max_dd),
                ("Integrity >= 70", integ >= 70, integ),
            ]:
                gate_rows.append({"Run ID": run_id, "Gate": gate_name, "Status": "PASS" if ok else "FAIL", "Value": val})

        except Exception as exc:
            rows.append({
                "Order": int(prow["Order"]),
                "Run ID": run_id,
                "Mutation": str(prow["Mutation"]),
                "One Factor Changed": str(prow["One Factor Changed"]),
                "Config Delta": str(prow["Config Delta"]),
                "Score": 0.0,
                "Decision": "RUN ERROR",
                "Verdict": "ERROR",
                "Total Return": np.nan,
                "Benchmark Return": np.nan,
                "Alpha": np.nan,
                "Sharpe": np.nan,
                "Max DD": np.nan,
                "Trades": 0,
                "Exposure": np.nan,
                "Integrity": 0,
                "BRT Activity": "N/A",
                "Engine Active Bars": 0,
                "Reasons": str(exc),
            })

    results = pd.DataFrame(rows)
    gates = pd.DataFrame(gate_rows)

    if not results.empty and base:
        results["Delta Alpha vs Base"] = pd.to_numeric(results["Alpha"], errors="coerce") - base.get("alpha", np.nan)
        results["Delta Return vs Base"] = pd.to_numeric(results["Total Return"], errors="coerce") - base.get("total", np.nan)
        results["Delta Sharpe vs Base"] = pd.to_numeric(results["Sharpe"], errors="coerce") - base.get("sharpe", np.nan)
        results["Delta Trades vs Base"] = pd.to_numeric(results["Trades"], errors="coerce") - base.get("trades", 0)

    ranked = results.sort_values(["Score", "Alpha", "Sharpe"], ascending=[False, False, False]) if not results.empty else pd.DataFrame()
    best = ranked.iloc[0].to_dict() if not ranked.empty else {}

    promote_count = int((results.get("Decision", pd.Series(dtype=str)).astype(str) == "PROMOTE TO OOS RETEST").sum()) if not results.empty else 0
    review_count = int(results.get("Decision", pd.Series(dtype=str)).astype(str).isin(["PROMOTE TO OOS RETEST", "HOLD / NEED SAMPLE", "MANUAL REVIEW"]).sum()) if not results.empty else 0

    if promote_count > 0:
        level = "Candidate found"
        decision = "PROMOTE BEST TO OOS RETEST"
        read = "Une mutation passe les gates minimaux. Prochaine étape : OOS contrôlé, sans exits/sizing optimization."
    elif review_count > 0:
        level = "Research candidate"
        decision = "MANUAL REVIEW ONLY"
        read = "Certaines mutations améliorent le profil mais ne passent pas encore les gates complets."
    else:
        level = "No mutation promoted"
        decision = "REJECT CURRENT QUEUE"
        read = "Aucune mutation V3.6 ne répare l'edge. Revenir au signal/régime ou élargir les hypothèses."

    summary = pd.DataFrame([
        ["Runner level", level, "Lecture synthétique du Controlled Mutation Runner V3.6."],
        ["Runner score", f"{_format_num(best.get('Score'), 0)}/100", "Score du meilleur run, pas score live."],
        ["Decision", decision, "Décision research après mutations contrôlées."],
        ["Best run", str(best.get("Run ID", "N/A")), "Mutation la mieux classée."],
        ["Best mutation", str(best.get("Mutation", "N/A")), "Hypothèse testée."],
        ["Best alpha", _format_pct(best.get("Alpha")), "Alpha vs benchmark du meilleur run."],
        ["Promoted runs", str(promote_count), "Runs passant les gates minimaux."],
        ["Review runs", str(review_count), "Runs non rejetés immédiatement."],
        ["Read", read, "Interprétation opérationnelle."],
    ], columns=["Metric", "Value", "Read"])

    cards = [
        {"label": "Mutation runner", "value": level, "delta": f"{_format_num(best.get('Score'), 0)}/100"},
        {"label": "Decision", "value": decision, "delta": "V3.6"},
        {"label": "Best run", "value": str(best.get("Run ID", "N/A")), "delta": str(best.get("Mutation", ""))[:35]},
        {"label": "Best alpha", "value": _format_pct(best.get("Alpha")), "delta": "vs benchmark"},
        {"label": "Promoted", "value": str(promote_count), "delta": "OOS candidates"},
        {"label": "Queue", "value": str(len(plan)), "delta": "one-factor runs"},
    ]

    return {
        "level": level,
        "score": best.get("Score", np.nan),
        "decision": decision,
        "read": read,
        "plan": plan,
        "summary": summary,
        "results": results,
        "gates": gates,
        "cards": cards,
    }


def _render_controlled_mutation_runner_v36(df: pd.DataFrame, cfg: BacktestConfig, ticker: str = "") -> dict[str, Any]:
    """Rendu Streamlit V3.6. Aucun run automatique : bouton manuel."""
    st.subheader("Controlled Mutation Runner / Research Queue V3.6")
    st.caption(
        "Runner lecture seule : mutations Benchmark-Relative Trend une hypothèse à la fois. "
        "Exits, sizing, coûts, benchmark et fenêtre restent gelés. Aucun impact moteur/trades/equity/verdict."
    )

    plan = _controlled_mutation_runner_v36_plan(cfg)

    _card_grid([
        {"label": "Runner status", "value": "Manual trigger", "delta": "not automatic"},
        {"label": "Queue", "value": str(len(plan)), "delta": "planned"},
        {"label": "Mode", "value": "One-factor", "delta": "controlled"},
        {"label": "Frozen", "value": "Exits/sizing/costs", "delta": "locked"},
        {"label": "Strategy", "value": str(getattr(cfg, "strategy", "N/A")), "delta": "current"},
        {"label": "Decision", "value": "RESEARCH ONLY", "delta": "V3.6"},
    ], columns=6)

    st.info("V3.6 ne lance aucun retest automatiquement. Clique seulement pour exécuter la queue sur la fenêtre actuelle.")

    key = "bt_v36_" + str(ticker).upper() + "_" + str(getattr(cfg, "strategy", "")).replace(" ", "_")
    c1, c2 = st.columns([1, 3])

    if c1.button("Lancer V3.6 controlled runs", use_container_width=True, key=key + "_run"):
        with st.spinner("V3.6 controlled mutations en cours..."):
            st.session_state[key] = _controlled_mutation_runner_v36_pack(df, cfg)

    if c2.button("Effacer résultat V3.6 en mémoire", use_container_width=True, key=key + "_clear"):
        st.session_state.pop(key, None)

    with st.expander("Planned one-factor queue V3.6", expanded=True):
        st.dataframe(plan, use_container_width=True, hide_index=True)

    pack = st.session_state.get(key)

    if not isinstance(pack, dict):
        return {
            "level": "Not run",
            "decision": "MANUAL TRIGGER REQUIRED",
            "plan": plan,
            "summary": pd.DataFrame(),
            "results": pd.DataFrame(),
            "gates": pd.DataFrame(),
        }

    _card_grid(pack.get("cards", []), columns=6)

    level = str(pack.get("level", "N/A"))
    read = str(pack.get("read", ""))

    if level == "Candidate found":
        st.success(f"Lecture V3.6 : {read}")
    elif level in {"Research candidate", "No mutation promoted"}:
        st.warning(f"Lecture V3.6 : {read}")
    else:
        st.info(f"Lecture V3.6 : {read}")

    with st.expander("Controlled mutation summary V3.6", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        st.dataframe(summary, use_container_width=True, hide_index=True) if isinstance(summary, pd.DataFrame) and not summary.empty else st.info("Résumé V3.6 indisponible.")

    results = pack.get("results", pd.DataFrame())

    with st.expander("Controlled mutation results V3.6", expanded=True):
        if isinstance(results, pd.DataFrame) and not results.empty:
            display = results.copy()

            for col in ["Total Return", "Benchmark Return", "Alpha", "Max DD", "Exposure", "Delta Alpha vs Base", "Delta Return vs Base"]:
                if col in display.columns:
                    display[col] = display[col].map(lambda x: _format_pct(x))

            for col in ["Score", "Sharpe", "Delta Sharpe vs Base"]:
                if col in display.columns:
                    display[col] = display[col].map(lambda x: _format_num(x))

            st.dataframe(display, use_container_width=True, hide_index=True)
        else:
            st.info("Résultats V3.6 indisponibles.")

    gates = pack.get("gates", pd.DataFrame())

    with st.expander("Promotion gates by run V3.6", expanded=False):
        st.dataframe(gates, use_container_width=True, hide_index=True) if isinstance(gates, pd.DataFrame) and not gates.empty else st.info("Gates V3.6 indisponibles.")

    d1, d2 = st.columns(2)

    if isinstance(results, pd.DataFrame) and not results.empty:
        d1.download_button(
            "Télécharger V3.6 results CSV",
            data=results.to_csv(index=False).encode("utf-8"),
            file_name="controlled_mutation_runner_v36_results.csv",
            mime="text/csv",
            use_container_width=True,
            key=key + "_results_csv",
        )

    if isinstance(gates, pd.DataFrame) and not gates.empty:
        d2.download_button(
            "Télécharger V3.6 gates CSV",
            data=gates.to_csv(index=False).encode("utf-8"),
            file_name="controlled_mutation_runner_v36_gates.csv",
            mime="text/csv",
            use_container_width=True,
            key=key + "_gates_csv",
        )

    return pack


