def _signal_candidate_factory_v37_state_signal(
    entry: pd.Series,
    exit_: pd.Series,
    index: pd.Index,
) -> pd.Series:
    """
    Transforme des conditions entry/exit en exposition longue persistante.
    Lecture uniquement : aucun effet sur _build_signal.
    """
    entry = pd.Series(entry, index=index).fillna(False).astype(bool)
    exit_ = pd.Series(exit_, index=index).fillna(False).astype(bool)

    values = []
    state = 0.0

    for i in range(len(index)):
        if state > 0 and bool(exit_.iloc[i]):
            state = 0.0

        if state == 0.0 and bool(entry.iloc[i]):
            state = 1.0

        values.append(state)

    return pd.Series(values, index=index).fillna(0.0).clip(0.0, 1.0)


def _signal_candidate_factory_v37_benchmark_cfg(cfg: BacktestConfig) -> BacktestConfig:
    """
    Résout un benchmark exploitable pour les tests V3.7.
    Si l'UI est sur Ticker Buy & Hold, on force le proxy sectoriel comme BRT V3.5.
    """
    if str(getattr(cfg, "benchmark_ticker", "") or "").strip():
        return cfg

    asset_ticker = str(getattr(cfg, "asset_ticker", "") or "").upper().strip()
    auto_symbol = _sector_benchmark_guess(asset_ticker) if asset_ticker else "SPY"

    return BacktestConfig(
        **{
            **cfg.__dict__,
            "benchmark_ticker": auto_symbol,
            "benchmark_label": f"Auto Sector ETF ({auto_symbol})",
            "benchmark_mode": "Sector ETF",
        }
    )


def _signal_candidate_factory_v37_candidate_signals(
    df: pd.DataFrame,
    cfg: BacktestConfig,
) -> tuple[pd.DataFrame, dict[str, pd.Series], str, bool]:
    """
    Génère plusieurs familles de signaux internes.
    Ces signaux sont ensuite passés dans le moteur existant via Custom Signal Import.
    Aucun nouveau mode moteur n'est ajouté.
    """
    catalog = _signal_candidate_factory_v37_catalog()

    if df is None or df.empty or "close" not in df.columns:
        return catalog, {}, "N/A", True

    close = pd.to_numeric(df["close"], errors="coerce").replace([np.inf, -np.inf], np.nan).ffill()
    close = close.dropna()

    if close.empty or len(close) < 80:
        return catalog, {}, "N/A", True

    bench_cfg = _signal_candidate_factory_v37_benchmark_cfg(cfg)

    bench_returns, bench_label, bench_fallback = _load_benchmark_returns(
        df.reindex(close.index),
        bench_cfg,
    )

    bench_returns = (
        pd.to_numeric(bench_returns.reindex(close.index), errors="coerce")
        .replace([np.inf, -np.inf], np.nan)
        .fillna(0.0)
    )

    bench_nav = (1.0 + bench_returns).cumprod()
    bench_nav = bench_nav.replace([np.inf, -np.inf], np.nan).ffill().bfill()

    asset_ret_5 = close.pct_change(5)
    asset_ret_20 = close.pct_change(20)
    asset_ret_60 = close.pct_change(60)

    bench_ret_20 = bench_nav.pct_change(20)
    bench_ret_60 = bench_nav.pct_change(60)

    active_20 = asset_ret_20 - bench_ret_20
    active_60 = asset_ret_60 - bench_ret_60
    active_score = 0.55 * active_20 + 0.45 * active_60

    sma20 = close.rolling(20).mean()
    sma50 = close.rolling(50).mean()
    sma100 = close.rolling(100).mean()
    sma200 = close.rolling(200).mean()

    bench_ma50 = bench_nav.rolling(50).mean()
    bench_ma100 = bench_nav.rolling(100).mean()

    bench_up50 = bench_nav > bench_ma50
    bench_up100 = bench_nav > bench_ma100

    high20 = close.shift(1).rolling(20).max()
    high55 = close.shift(1).rolling(55).max()

    realized_vol = close.pct_change().rolling(20).std() * np.sqrt(252)
    vol_q40 = realized_vol.rolling(126, min_periods=20).quantile(0.40)
    vol_q80 = realized_vol.rolling(126, min_periods=20).quantile(0.80)

    signals: dict[str, pd.Series] = {}

    # 1) Relative momentum moins strict que le BRT 20D+60D.
    entry = (active_score > 0.0) & bench_up50
    exit_ = (active_score < -0.02) | (close < sma50)
    signals["RUN-V37-01"] = _signal_candidate_factory_v37_state_signal(entry, exit_, close.index)

    # 2) Breakout prix seulement si l'actif bat le benchmark à court terme.
    entry = (close > high20) & (active_20 > 0.0)
    exit_ = (close < sma20) | (active_20 < -0.015)
    signals["RUN-V37-02"] = _signal_candidate_factory_v37_state_signal(entry, exit_, close.index)

    # 3) Trend actif conditionné par régime benchmark.
    entry = (close > sma50) & (asset_ret_20 > 0.0) & bench_up100
    exit_ = (close < sma50) | (~bench_up100) | (asset_ret_20 < -0.05)
    signals["RUN-V37-03"] = _signal_candidate_factory_v37_state_signal(entry, exit_, close.index)

    # 4) Pullback dans tendance longue + benchmark favorable.
    entry = (close > sma100) & bench_up100 & (asset_ret_5 < -0.02) & (active_60 > -0.05)
    exit_ = (close < sma50) | (active_20 < -0.03) | (~bench_up100)
    signals["RUN-V37-04"] = _signal_candidate_factory_v37_state_signal(entry, exit_, close.index)

    # 5) Breakout après contraction de volatilité.
    vol_contracted = realized_vol <= vol_q40
    vol_bad = realized_vol > vol_q80
    entry = (close > high20) & vol_contracted & (active_20 > -0.01)
    exit_ = (close < sma20) | vol_bad | (active_20 < -0.03)
    signals["RUN-V37-05"] = _signal_candidate_factory_v37_state_signal(entry, exit_, close.index)

    # 6) Sector-relative trend : trend prix + relative strength.
    entry = (close > sma100) & (active_20 > 0.0) & (active_60 > -0.02)
    exit_ = (close < sma50) | (active_20 < -0.03)
    signals["RUN-V37-06"] = _signal_candidate_factory_v37_state_signal(entry, exit_, close.index)

    # 7) Contrôle momentum absolu.
    entry = (close > sma100) & (asset_ret_60 > 0.0)
    exit_ = (close < sma100) | (asset_ret_20 < -0.05)
    signals["RUN-V37-07"] = _signal_candidate_factory_v37_state_signal(entry, exit_, close.index)

    return catalog, signals, bench_label, bool(bench_fallback)


def _signal_candidate_factory_v37_signal_df(signal: pd.Series) -> pd.DataFrame:
    """Convertit un signal interne en DataFrame compatible Custom Signal Import."""
    s = pd.to_numeric(signal, errors="coerce").fillna(0.0).clip(-1.0, 1.0)

    if _is_datetime_like_index(s.index):
        return pd.DataFrame({"date": pd.to_datetime(s.index), "signal": s.values})

    return pd.DataFrame({"signal": s.values})


def _signal_candidate_factory_v37_score(
    metrics: dict[str, Any],
    integrity: int,
    oos_alpha: float,
) -> float:
    """Score research V3.7 : edge, alpha, sample, OOS proxy, drawdown."""
    alpha = _safe_float(metrics.get("Relative Alpha"), 0.0)
    total = _safe_float(metrics.get("Total Return"), 0.0)
    sharpe = _safe_float(metrics.get("Sharpe"), np.nan)
    max_dd = _safe_float(metrics.get("Max Drawdown"), 0.0)
    trades = int(metrics.get("Trades", 0) or 0)
    exposure = _safe_float(metrics.get("Exposure"), 0.0)

    alpha_score = _clip((alpha + 0.05) / 0.35) * 100.0
    return_score = _clip((total + 0.05) / 0.30) * 100.0
    sharpe_score = _clip((sharpe + 0.50) / 1.75) * 100.0 if pd.notna(sharpe) else 0.0
    dd_score = _clip((max_dd + 0.45) / 0.45) * 100.0
    sample_score = _clip(trades / 30.0) * 100.0

    # Exposition utile : trop faible = non interprétable, trop permanente = proche buy&hold.
    if exposure <= 0:
        exposure_score = 0.0
    elif exposure < 0.05:
        exposure_score = 35.0
    elif exposure <= 0.80:
        exposure_score = 100.0
    else:
        exposure_score = 60.0

    oos_score = _clip((oos_alpha + 0.05) / 0.25) * 100.0 if pd.notna(oos_alpha) else 0.0

    score = (
        alpha_score * 0.26
        + return_score * 0.16
        + sharpe_score * 0.14
        + dd_score * 0.10
        + sample_score * 0.12
        + exposure_score * 0.08
        + oos_score * 0.09
        + float(integrity) * 0.05
    )

    if trades < 5:
        score = min(score, 45.0)

    if exposure < 0.02:
        score = min(score, 40.0)

    if alpha <= 0 and total <= 0:
        score = min(score, 45.0)

    return max(0.0, min(100.0, float(score)))


def _signal_candidate_factory_v37_decision(
    metrics: dict[str, Any],
    score: float,
    oos_alpha: float,
) -> str:
    alpha = _safe_float(metrics.get("Relative Alpha"), 0.0)
    total = _safe_float(metrics.get("Total Return"), 0.0)
    sharpe = _safe_float(metrics.get("Sharpe"), np.nan)
    max_dd = _safe_float(metrics.get("Max Drawdown"), 0.0)
    trades = int(metrics.get("Trades", 0) or 0)
    exposure = _safe_float(metrics.get("Exposure"), 0.0)

    if (
        alpha > 0
        and total > 0
        and pd.notna(sharpe)
        and sharpe > 0
        and trades >= 10
        and exposure >= 0.05
        and max_dd > -0.35
        and (pd.isna(oos_alpha) or oos_alpha >= 0)
    ):
        return "PROMOTE TO CONTROLLED OOS"

    if alpha > 0 and trades >= 5 and exposure >= 0.03:
        return "RESEARCH CANDIDATE"

    if trades < 5 or exposure < 0.02:
        return "REJECT / INACTIVE SAMPLE"

    return "REJECT SIGNAL"


def _signal_candidate_factory_v37_pack(df: pd.DataFrame, cfg: BacktestConfig) -> dict[str, Any]:
    """
    Signal Candidate Factory V3.7.
    Lance manuellement plusieurs familles de signaux internes via Custom Signal Import.
    Aucun impact sur le backtest courant.
    """
    catalog, signals, benchmark_label, benchmark_fallback = _signal_candidate_factory_v37_candidate_signals(df, cfg)
    bench_cfg = _signal_candidate_factory_v37_benchmark_cfg(cfg)

    if not signals:
        return {
            "level": "Unavailable",
            "score": np.nan,
            "decision": "NO RUN",
            "read": "Données insuffisantes pour générer des candidats V3.7.",
            "catalog": catalog,
            "summary": pd.DataFrame(),
            "results": pd.DataFrame(),
            "gates": pd.DataFrame(),
            "cards": [
                {"label": "Signal factory", "value": "Unavailable", "delta": "V3.7"},
                {"label": "Candidates", "value": "0", "delta": "not generated"},
                {"label": "Benchmark", "value": benchmark_label, "delta": "fallback" if benchmark_fallback else "loaded"},
            ],
        }

    rows = []
    gate_rows = []

    catalog_map = {
        str(row["Candidate ID"]): row.to_dict()
        for _, row in catalog.iterrows()
    }

    for run_id, signal in signals.items():
        meta = catalog_map.get(run_id, {})
        sig_df = _signal_candidate_factory_v37_signal_df(signal)

        try:
            test_cfg = BacktestConfig(
                **{
                    **bench_cfg.__dict__,
                    "strategy": "Custom Signal Import",
                    "custom_signal_df": sig_df,
                    "allow_short": False,
                }
            )

            res = _run_backtest(df, test_cfg)

            if not isinstance(res, dict) or "metrics" not in res or "data" not in res:
                raise RuntimeError(str(res.get("error", "run failed")) if isinstance(res, dict) else "run failed")

            bt = res["data"]
            m = res["metrics"]

            integ, notes = _integrity_score(m, bt, test_cfg)
            verdict_run, _, reasons = _verdict(m, integ, notes)

            split_df = _split_analysis(bt)
            oos_alpha = np.nan
            oos_return = np.nan

            if isinstance(split_df, pd.DataFrame) and not split_df.empty and "Segment" in split_df.columns:
                oos = split_df[split_df["Segment"].astype(str).str.contains("Out-of-sample", case=False, na=False)]
                if not oos.empty:
                    oos_alpha = _safe_float(oos.iloc[0].get("Alpha"), np.nan)
                    oos_return = _safe_float(oos.iloc[0].get("Return"), np.nan)

            score = _signal_candidate_factory_v37_score(m, integ, oos_alpha)
            decision = _signal_candidate_factory_v37_decision(m, score, oos_alpha)

            exposure_series = pd.to_numeric(bt.get("exposure", pd.Series(dtype=float)), errors="coerce").fillna(0.0)
            active_bars = int((exposure_series.abs() > 0).sum()) if not exposure_series.empty else 0
            changes = int((exposure_series.diff().abs().fillna(exposure_series.abs()) > 0).sum()) if not exposure_series.empty else 0

            alpha = _safe_float(m.get("Relative Alpha"), np.nan)
            total = _safe_float(m.get("Total Return"), np.nan)
            sharpe = _safe_float(m.get("Sharpe"), np.nan)
            max_dd = _safe_float(m.get("Max Drawdown"), np.nan)
            trades_n = int(m.get("Trades", 0) or 0)
            exposure = _safe_float(m.get("Exposure"), np.nan)

            rows.append(
                {
                    "Candidate ID": run_id,
                    "Signal Family": str(meta.get("Signal Family", run_id)),
                    "Track": str(meta.get("Track", "N/A")),
                    "Score": score,
                    "Decision": decision,
                    "Verdict": verdict_run,
                    "Total Return": total,
                    "Benchmark Return": _safe_float(m.get("Benchmark Return"), np.nan),
                    "Alpha": alpha,
                    "OOS Return": oos_return,
                    "OOS Alpha": oos_alpha,
                    "Sharpe": sharpe,
                    "Max DD": max_dd,
                    "Trades": trades_n,
                    "Exposure": exposure,
                    "Active Bars": active_bars,
                    "Engine Changes": changes,
                    "Integrity": integ,
                    "Benchmark": str(m.get("Benchmark Label", benchmark_label)),
                    "Why": str(meta.get("Why", "N/A")),
                    "Reasons": "; ".join([str(x) for x in reasons]) if reasons else "N/A",
                }
            )

            for gate_name, ok, val in [
                ("Engine exposure > 0", active_bars > 0, active_bars),
                ("Trades >= 10", trades_n >= 10, trades_n),
                ("Alpha > 0", alpha > 0, alpha),
                ("Total return > 0", total > 0, total),
                ("OOS alpha >= 0", pd.notna(oos_alpha) and oos_alpha >= 0, oos_alpha),
                ("Sharpe > 0", pd.notna(sharpe) and sharpe > 0, sharpe),
                ("Max DD > -35%", pd.notna(max_dd) and max_dd > -0.35, max_dd),
                ("Integrity >= 60", integ >= 60, integ),
            ]:
                gate_rows.append(
                    {
                        "Candidate ID": run_id,
                        "Gate": gate_name,
                        "Status": "PASS" if ok else "FAIL",
                        "Value": val,
                    }
                )

        except Exception as exc:
            rows.append(
                {
                    "Candidate ID": run_id,
                    "Signal Family": str(meta.get("Signal Family", run_id)),
                    "Track": str(meta.get("Track", "N/A")),
                    "Score": 0.0,
                    "Decision": "RUN ERROR",
                    "Verdict": "ERROR",
                    "Total Return": np.nan,
                    "Benchmark Return": np.nan,
                    "Alpha": np.nan,
                    "OOS Return": np.nan,
                    "OOS Alpha": np.nan,
                    "Sharpe": np.nan,
                    "Max DD": np.nan,
                    "Trades": 0,
                    "Exposure": np.nan,
                    "Active Bars": 0,
                    "Engine Changes": 0,
                    "Integrity": 0,
                    "Benchmark": benchmark_label,
                    "Why": str(meta.get("Why", "N/A")),
                    "Reasons": str(exc),
                }
            )

    results = pd.DataFrame(rows)
    gates = pd.DataFrame(gate_rows)

    ranked = (
        results.sort_values(["Score", "Alpha", "OOS Alpha", "Sharpe"], ascending=[False, False, False, False])
        if not results.empty
        else pd.DataFrame()
    )

    best = ranked.iloc[0].to_dict() if not ranked.empty else {}

    promote_count = int((results.get("Decision", pd.Series(dtype=str)).astype(str) == "PROMOTE TO CONTROLLED OOS").sum()) if not results.empty else 0
    review_count = int(results.get("Decision", pd.Series(dtype=str)).astype(str).isin(["PROMOTE TO CONTROLLED OOS", "RESEARCH CANDIDATE"]).sum()) if not results.empty else 0

    if promote_count > 0:
        level = "Candidate found"
        decision = "PROMOTE BEST TO OOS"
        read = "Au moins un signal candidat passe les gates minimaux. Prochaine étape : OOS contrôlé et gel des paramètres."
    elif review_count > 0:
        level = "Research candidate"
        decision = "MANUAL REVIEW"
        read = "Un ou plusieurs signaux améliorent le profil mais ne passent pas encore tous les gates."
    else:
        level = "No candidate"
        decision = "REBUILD SIGNAL FAMILY"
        read = "Aucun candidat V3.7 ne répare suffisamment l'edge. Il faut élargir ou changer la famille de signal."

    summary = pd.DataFrame(
        [
            ["Factory level", level, "Lecture synthétique de la Signal Candidate Factory V3.7."],
            ["Factory score", f"{_format_num(best.get('Score'), 0)}/100", "Score du meilleur candidat."],
            ["Decision", decision, "Décision research après scan des familles de signaux."],
            ["Best candidate", str(best.get("Candidate ID", "N/A")), "Candidat le mieux classé."],
            ["Best signal family", str(best.get("Signal Family", "N/A")), "Famille de signal la mieux classée."],
            ["Best alpha", _format_pct(best.get("Alpha")), "Alpha vs benchmark."],
            ["Best OOS alpha", _format_pct(best.get("OOS Alpha")), "Alpha hors-échantillon proxy."],
            ["Best trades", str(int(_safe_float(best.get("Trades"), 0))), "Nombre de changements/trades moteur."],
            ["Benchmark", benchmark_label, "Benchmark utilisé pour les candidats."],
            ["Benchmark fallback", str(bool(benchmark_fallback)), "Fallback benchmark détecté ou non."],
            ["Promoted candidates", str(promote_count), "Candidats éligibles à OOS contrôlé."],
            ["Review candidates", str(review_count), "Candidats non rejetés immédiatement."],
            ["Read", read, "Interprétation opérationnelle."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    cards = [
        {"label": "Signal factory", "value": level, "delta": f"{_format_num(best.get('Score'), 0)}/100"},
        {"label": "Decision", "value": decision, "delta": "V3.7"},
        {"label": "Best signal", "value": str(best.get("Signal Family", "N/A"))[:28], "delta": str(best.get("Candidate ID", "N/A"))},
        {"label": "Best alpha", "value": _format_pct(best.get("Alpha")), "delta": "vs benchmark"},
        {"label": "Best OOS alpha", "value": _format_pct(best.get("OOS Alpha")), "delta": "split proxy"},
        {"label": "Promoted", "value": str(promote_count), "delta": "OOS candidates"},
    ]

    return {
        "level": level,
        "score": best.get("Score", np.nan),
        "decision": decision,
        "read": read,
        "catalog": catalog,
        "summary": summary,
        "results": results,
        "gates": gates,
        "cards": cards,
    }


def _render_signal_candidate_factory_v37(
    df: pd.DataFrame,
    cfg: BacktestConfig,
    ticker: str = "",
) -> dict[str, Any]:
    """Rendu Streamlit V3.7. Runner manuel, lecture seule."""
    st.subheader("Signal Candidate Factory / Research Ideas V3.7")
    st.caption(
        "Factory lecture seule : teste plusieurs familles de signaux internes via Custom Signal Import. "
        "Aucun changement du moteur principal, aucun changement du verdict courant, aucun live/paper."
    )

    catalog = _signal_candidate_factory_v37_catalog()

    _card_grid(
        [
            {"label": "Factory status", "value": "Manual trigger", "delta": "not automatic"},
            {"label": "Candidates", "value": str(len(catalog)), "delta": "signal families"},
            {"label": "Execution route", "value": "Custom Signal Import", "delta": "engine-safe"},
            {"label": "Frozen", "value": "Costs/sizing/exits", "delta": "inherited"},
            {"label": "Benchmark", "value": "Auto sector if needed", "delta": "V3.7"},
            {"label": "Decision", "value": "RESEARCH ONLY", "delta": "no deployment"},
        ],
        columns=6,
    )

    st.warning(
        "V3.7 est un scanner de recherche. Il peut identifier un candidat, mais ne valide rien seul : "
        "tout candidat doit ensuite passer OOS, overfit, execution, liquidity et deployment gates."
    )

    key = "bt_v37_" + str(ticker).upper() + "_" + str(getattr(cfg, "strategy", "")).replace(" ", "_")
    c1, c2 = st.columns([1, 3])

    if c1.button("Lancer V3.7 signal factory", use_container_width=True, key=key + "_run"):
        with st.spinner("V3.7 signal candidates en cours..."):
            st.session_state[key] = _signal_candidate_factory_v37_pack(df, cfg)

    if c2.button("Effacer résultat V3.7 en mémoire", use_container_width=True, key=key + "_clear"):
        st.session_state.pop(key, None)

    with st.expander("Signal candidate catalog V3.7", expanded=True):
        st.dataframe(catalog, use_container_width=True, hide_index=True)

    pack = st.session_state.get(key)

    if not isinstance(pack, dict):
        return {
            "level": "Not run",
            "decision": "MANUAL TRIGGER REQUIRED",
            "catalog": catalog,
            "summary": pd.DataFrame(),
            "results": pd.DataFrame(),
            "gates": pd.DataFrame(),
        }

    _card_grid(pack.get("cards", []), columns=6)

    level = str(pack.get("level", "N/A"))
    read = str(pack.get("read", ""))

    if level == "Candidate found":
        st.success(f"Lecture V3.7 : {read}")
    elif level == "Research candidate":
        st.warning(f"Lecture V3.7 : {read}")
    elif level == "No candidate":
        st.error(f"Lecture V3.7 : {read}")
    else:
        st.info(f"Lecture V3.7 : {read}")

    summary = pack.get("summary", pd.DataFrame())
    results = pack.get("results", pd.DataFrame())
    gates = pack.get("gates", pd.DataFrame())

    with st.expander("Signal factory summary V3.7", expanded=True):
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V3.7 indisponible.")

    with st.expander("Signal candidate results V3.7", expanded=True):
        if isinstance(results, pd.DataFrame) and not results.empty:
            display = results.copy()

            pct_cols = [
                "Total Return",
                "Benchmark Return",
                "Alpha",
                "OOS Return",
                "OOS Alpha",
                "Max DD",
                "Exposure",
            ]

            for col in pct_cols:
                if col in display.columns:
                    display[col] = display[col].map(lambda x: _format_pct(x))

            for col in ["Score", "Sharpe"]:
                if col in display.columns:
                    display[col] = display[col].map(lambda x: _format_num(x))

            st.dataframe(display, use_container_width=True, hide_index=True)
        else:
            st.info("Résultats V3.7 indisponibles.")

    with st.expander("Promotion gates by candidate V3.7", expanded=False):
        if isinstance(gates, pd.DataFrame) and not gates.empty:
            gate_display = gates.copy()

            if "Value" in gate_display.columns:
                gate_display["Value"] = gate_display["Value"].map(
                    lambda x: _format_pct(x) if isinstance(x, float) and abs(x) <= 2 else str(x)
                )

            st.dataframe(gate_display, use_container_width=True, hide_index=True)
        else:
            st.info("Gates V3.7 indisponibles.")

    d1, d2, d3 = st.columns(3)

    if isinstance(results, pd.DataFrame) and not results.empty:
        d1.download_button(
            "Télécharger V3.7 results CSV",
            data=results.to_csv(index=False).encode("utf-8"),
            file_name="signal_candidate_factory_v37_results.csv",
            mime="text/csv",
            use_container_width=True,
            key=key + "_results_csv",
        )

    if isinstance(gates, pd.DataFrame) and not gates.empty:
        d2.download_button(
            "Télécharger V3.7 gates CSV",
            data=gates.to_csv(index=False).encode("utf-8"),
            file_name="signal_candidate_factory_v37_gates.csv",
            mime="text/csv",
            use_container_width=True,
            key=key + "_gates_csv",
        )

    d3.download_button(
        "Télécharger V3.7 catalog CSV",
        data=catalog.to_csv(index=False).encode("utf-8"),
        file_name="signal_candidate_factory_v37_catalog.csv",
        mime="text/csv",
        use_container_width=True,
        key=key + "_catalog_csv",
    )

    return pack


