def _v38_safe_series(index: pd.Index, value: float = 0.0) -> pd.Series:
    return pd.Series(float(value), index=index).replace([np.inf, -np.inf], np.nan).fillna(0.0)


def _v38_signal_to_df(signal: pd.Series, price_index: pd.Index) -> pd.DataFrame:
    sig = pd.to_numeric(signal.reindex(price_index), errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0).clip(-1.0, 1.0)
    if _is_datetime_like_index(price_index):
        return pd.DataFrame({"date": pd.to_datetime(price_index), "signal": sig.values})
    return pd.DataFrame({"signal": sig.values})


