def _render_economic_hypothesis_signal_source_builder_v39(
    ticker: str,
    df: pd.DataFrame,
    bt: pd.DataFrame,
    trades: pd.DataFrame,
    metrics: dict[str, Any],
    cfg: BacktestConfig,
    diagnostics: dict[str, Any],
) -> dict[str, Any]:
    """
    Rendu Streamlit V3.9.
    """
    pack = _economic_hypothesis_signal_source_builder_v39_pack(
        ticker=ticker,
        df=df,
        bt=bt,
        trades=trades,
        metrics=metrics,
        cfg=cfg,
        diagnostics=diagnostics,
    )

    st.subheader("Economic Hypothesis / Signal Source Builder V3.9")
    st.caption(
        "Builder lecture seule : transforme l'échec source/edge en hypothèses économiques testables. "
        "Aucun retest automatique, aucun changement moteur, aucun changement des exits, du sizing, des coûts, "
        "de l'equity curve ou du verdict."
    )

    _card_grid(pack.get("cards", []), columns=6)

    read = str(pack.get("read", ""))

    if str(pack.get("decision", "")).startswith("BUILD"):
        st.error(f"Lecture V3.9 : {read}")
    elif "REPAIR" in str(pack.get("decision", "")):
        st.warning(f"Lecture V3.9 : {read}")
    else:
        st.info(f"Lecture V3.9 : {read}")

    summary = pack.get("summary", pd.DataFrame())
    source_matrix = pack.get("source_matrix", pd.DataFrame())
    implementation_spec = pack.get("implementation_spec", pd.DataFrame())
    queue = pack.get("queue", pd.DataFrame())
    data_requirements = pack.get("data_requirements", pd.DataFrame())
    do_not_do = pack.get("do_not_do", pd.DataFrame())

    with st.expander("Signal source builder summary V3.9", expanded=True):
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V3.9 indisponible.")

    with st.expander("Economic hypothesis source matrix V3.9", expanded=True):
        if isinstance(source_matrix, pd.DataFrame) and not source_matrix.empty:
            st.dataframe(source_matrix, use_container_width=True, hide_index=True)
        else:
            st.info("Matrice d'hypothèses V3.9 indisponible.")

    with st.expander("One-factor source run queue V3.9", expanded=True):
        if isinstance(queue, pd.DataFrame) and not queue.empty:
            st.dataframe(queue, use_container_width=True, hide_index=True)
        else:
            st.info("Queue V3.9 indisponible.")

    with st.expander("Implementation protocol V3.9", expanded=False):
        if isinstance(implementation_spec, pd.DataFrame) and not implementation_spec.empty:
            st.dataframe(implementation_spec, use_container_width=True, hide_index=True)
        else:
            st.info("Protocole V3.9 indisponible.")

    with st.expander("Data requirements V3.9", expanded=False):
        if isinstance(data_requirements, pd.DataFrame) and not data_requirements.empty:
            st.dataframe(data_requirements, use_container_width=True, hide_index=True)
        else:
            st.info("Data requirements V3.9 indisponibles.")

    with st.expander("Dependency map / do-not-do rules V3.9", expanded=False):
        if isinstance(do_not_do, pd.DataFrame) and not do_not_do.empty:
            st.dataframe(do_not_do, use_container_width=True, hide_index=True)
        else:
            st.info("Règles V3.9 indisponibles.")

    d1, d2, d3 = st.columns(3)

    if isinstance(source_matrix, pd.DataFrame) and not source_matrix.empty:
        d1.download_button(
            "Télécharger source matrix V3.9 CSV",
            data=source_matrix.to_csv(index=False).encode("utf-8"),
            file_name="signal_source_builder_v39_matrix.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v39_source_matrix_csv",
        )

    if isinstance(queue, pd.DataFrame) and not queue.empty:
        d2.download_button(
            "Télécharger run queue V3.9 CSV",
            data=queue.to_csv(index=False).encode("utf-8"),
            file_name="signal_source_builder_v39_queue.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v39_queue_csv",
        )

    if isinstance(implementation_spec, pd.DataFrame) and not implementation_spec.empty:
        payload = {
            "version": "V3.9",
            "module": "Economic Hypothesis / Signal Source Builder",
            "decision": str(pack.get("decision", "N/A")),
            "level": str(pack.get("level", "N/A")),
            "score": _safe_float(pack.get("score"), np.nan),
            "top_candidate": pack.get("top_candidate", {}),
            "root_flags": pack.get("root_flags", []),
            "source_matrix": source_matrix.to_dict(orient="records"),
            "run_queue": queue.to_dict(orient="records") if isinstance(queue, pd.DataFrame) else [],
            "guardrail": "read_only_no_engine_change",
        }

        d3.download_button(
            "Télécharger blueprint V3.9 JSON",
            data=json.dumps(payload, indent=2, default=str).encode("utf-8"),
            file_name="signal_source_builder_v39_blueprint.json",
            mime="application/json",
            use_container_width=True,
            key="bt_v39_blueprint_json",
        )

    return pack




