        risk_max_holding_bars = 30
        risk_cooldown_bars = 0
        risk_use_ohlc_execution = True
        risk_respect_open_gaps = True
        sizing_mode = "Fixed Exposure"
        sizing_vol_target_pct = 20.0
        sizing_vol_window = 20
