        sizing_max_exposure_pct = 100.0
        sizing_use_drawdown_cut = False
        sizing_drawdown_cut_pct = 15.0
        sizing_drawdown_floor_pct = 25.0
        sizing_use_trade_risk_budget = False
        sizing_trade_risk_pct = 1.0
