# ============================================================
# ROBUST TRADE MAP RESOLVER V4.4b — appended override
# ============================================================

def _v44b_to_float(value, default=np.nan):
    try:
        if value is None:
            return default
        if isinstance(value, str):
            txt = value.strip().replace(",", ".")
            if txt in {"", "N/A", "NA", "nan", "None"}:
                return default
            is_pct = "%" in txt
            txt = txt.replace("%", "").replace("$", "").replace("/100", "").strip()
            txt = txt.replace(" ", "")
            out = float(txt)
            return out / 100.0 if is_pct else out
        if pd.isna(value):
            return default
        return float(value)
    except Exception:
        return default


def _v44b_format_pct(value, decimals=2):
    try:
        return _format_pct(value, decimals)
    except Exception:
        try:
            if value is None or pd.isna(value):
                return "N/A"
            return f"{float(value):.{decimals}%}"
        except Exception:
            return "N/A"


def _v44b_format_num(value, decimals=2):
    try:
        return _format_num(value, decimals)
    except Exception:
        try:
            if value is None or pd.isna(value):
                return "N/A"
            return f"{float(value):,.{decimals}f}"
        except Exception:
            return "N/A"


def _v44b_format_dt(value):
    try:
        return _format_dt(value)
    except Exception:
        try:
            ts = pd.to_datetime(value)
            if pd.isna(ts):
                return str(value)
            return ts.strftime("%Y-%m-%d")
        except Exception:
            return str(value)


def _v44b_norm_col(col):
    return str(col or "").strip().lower().replace(" ", "_").replace("-", "_")


def _v44b_pick_col(frame, candidates):
    try:
        if frame is None or not hasattr(frame, "columns"):
            return None
        lookup = {_v44b_norm_col(c): c for c in frame.columns}
        for cand in candidates:
            key = _v44b_norm_col(cand)
            if key in lookup:
                return lookup[key]
        for cand in candidates:
            key = _v44b_norm_col(cand)
            for norm, original in lookup.items():
                if key in norm or norm in key:
                    return original
    except Exception:
        return None
    return None


def _v44b_extract_kwargs(args, kwargs):
    names = ["ticker", "df", "bt", "trades", "metrics", "cfg", "diagnostics"]
    out = dict(kwargs or {})
    for name, value in zip(names, args or []):
        out.setdefault(name, value)
    return out


def _v44b_iter_objects(obj, path="root", seen=None):
    if seen is None:
        seen = set()
    try:
        oid = id(obj)
        if oid in seen:
            return
        seen.add(oid)
        yield path, obj
        if isinstance(obj, dict):
            for k, v in obj.items():
                yield from _v44b_iter_objects(v, f"{path}.{k}", seen)
        elif isinstance(obj, (list, tuple)):
            for i, v in enumerate(obj):
                yield from _v44b_iter_objects(v, f"{path}[{i}]", seen)
    except Exception:
        return


def _v44b_parse_changes(raw):
    import ast
    import re
    if isinstance(raw, dict):
        return dict(raw)
    if raw is None:
        return {}
    txt = str(raw).strip()
    if not txt or txt.upper() in {"N/A", "NONE", "NAN"}:
        return {}
    try:
        parsed = ast.literal_eval(txt)
        if isinstance(parsed, dict):
            return dict(parsed)
    except Exception:
        pass
    changes = {}
    for key, val in re.findall(r"([A-Za-z_][A-Za-z0-9_]*)\s*[:=]\s*([-+]?[0-9]*\.?[0-9]+|True|False|true|false)", txt):
        if str(val).lower() in {"true", "false"}:
            changes[key] = str(val).lower() == "true"
        else:
            f = float(val)
            changes[key] = int(f) if abs(f - int(f)) < 1e-12 else f
    return changes


def _v44b_find_best_mutation_source(diagnostics=None):
    candidates = []
    search_roots = []
    if isinstance(diagnostics, dict):
        search_roots.append(("diagnostics", diagnostics))
    try:
        session_items = {str(k): v for k, v in st.session_state.items()}
        search_roots.append(("session_state", session_items))
    except Exception:
        pass

    for root_name, root in search_roots:
        for path, obj in _v44b_iter_objects(root, root_name):
            if not isinstance(obj, pd.DataFrame) or obj.empty:
                continue
            cols_norm = [_v44b_norm_col(c) for c in obj.columns]
            path_l = str(path).lower()
            has_mutation = any("mutation" in c for c in cols_norm) or "v43" in path_l
            has_result = any(x in " ".join(cols_norm) for x in ["score", "alpha", "return", "sharpe", "mutation"])
            if not (has_mutation and has_result):
                continue
            score_col = _v44b_pick_col(obj, ["Score", "V4.3 Score", "Mutation Score", "Research Score", "Total Score"])
            alpha_col = _v44b_pick_col(obj, ["Active Alpha", "Alpha", "Relative Alpha", "Avg Active Return"])
            ret_col = _v44b_pick_col(obj, ["Total Return", "Strategy Return", "Return"])
            if score_col is not None:
                values = obj[score_col].map(_v44b_to_float)
            elif alpha_col is not None:
                values = obj[alpha_col].map(_v44b_to_float)
            elif ret_col is not None:
                values = obj[ret_col].map(_v44b_to_float)
            else:
                values = pd.Series(range(len(obj)), index=obj.index)
            try:
                idx = values.astype(float).replace([np.inf, -np.inf], np.nan).idxmax()
                row = obj.loc[idx]
            except Exception:
                row = obj.iloc[0]
            candidates.append((path, obj, row))

    if not candidates:
        return None, pd.DataFrame(), pd.Series(dtype=object)

    # Privilégie explicitement V4.3 si plusieurs tables existent.
    candidates = sorted(candidates, key=lambda x: ("v43" not in str(x[0]).lower(), len(str(x[0]))))
    return candidates[0]


def _v44b_row_value(row, candidates, default="N/A"):
    try:
        if row is None or len(row) == 0:
            return default
        lookup = {_v44b_norm_col(k): k for k in row.index}
        for cand in candidates:
            key = _v44b_norm_col(cand)
            if key in lookup:
                return row.get(lookup[key], default)
        for cand in candidates:
            key = _v44b_norm_col(cand)
            for norm, original in lookup.items():
                if key in norm or norm in key:
                    return row.get(original, default)
    except Exception:
        pass
    return default


def _v44b_make_cfg_copy(cfg, changes):
    try:
        if cfg is None:
            return cfg
        base = dict(getattr(cfg, "__dict__", {}))
        allowed = set(base.keys())
        clean = {}
        for k, v in dict(changes or {}).items():
            if k in allowed:
                clean[k] = v
        base.update(clean)
        return BacktestConfig(**base)
    except Exception:
        return cfg


def _v44b_resolve_bar(bt, trade, side="entry"):
    try:
        if bt is None or bt.empty or trade is None:
            return None, "missing bt/trade"
        if side == "entry":
            bar_col = _v44b_pick_col(pd.DataFrame(columns=list(trade.index)), ["Entry Bar", "Entry Index", "entry_bar"])
            date_col = _v44b_pick_col(pd.DataFrame(columns=list(trade.index)), ["Entry Date", "Entry Time", "entry_date"])
        else:
            bar_col = _v44b_pick_col(pd.DataFrame(columns=list(trade.index)), ["Exit Bar", "Exit Index", "exit_bar"])
            date_col = _v44b_pick_col(pd.DataFrame(columns=list(trade.index)), ["Exit Date", "Exit Time", "exit_date"])

        if bar_col is not None:
            raw = trade.get(bar_col, np.nan)
            val = _v44b_to_float(raw, np.nan)
            if pd.notna(val):
                bar = int(val)
                if 0 <= bar < len(bt):
                    return bar, "bar column"

        if date_col is not None:
            raw_date = trade.get(date_col, None)
            target = pd.to_datetime(raw_date, errors="coerce")
            if pd.notna(target):
                try:
                    idx = pd.to_datetime(pd.Index(bt.index), errors="coerce")
                    if pd.notna(idx).sum() > 0:
                        # Exact/nearest date resolver. Entry prefers first bar >= date; exit prefers last bar <= date.
                        exact = np.where(idx.normalize() == target.normalize())[0]
                        if len(exact) > 0:
                            return int(exact[0] if side == "entry" else exact[-1]), "date exact"
                        if side == "entry":
                            pos = np.where(idx >= target)[0]
                            if len(pos) > 0:
                                return int(pos[0]), "date forward"
                        else:
                            pos = np.where(idx <= target)[0]
                            if len(pos) > 0:
                                return int(pos[-1]), "date backward"
                        # final fallback : nearest absolute distance
                        diffs = np.abs(idx.view("i8") - pd.Timestamp(target).value)
                        return int(np.nanargmin(diffs)), "date nearest"
                except Exception:
                    pass
    except Exception as exc:
        return None, f"resolver error: {exc}"
    return None, "unresolved"


def _v44b_trade_failure_map(bt, trades):
    if bt is None or not isinstance(bt, pd.DataFrame) or bt.empty:
        return pd.DataFrame(), {"total": 0, "decomposed": 0, "skipped": 0, "skip_reasons": ["empty backtest"]}
    if trades is None or not isinstance(trades, pd.DataFrame) or trades.empty:
        return pd.DataFrame(), {"total": 0, "decomposed": 0, "skipped": 0, "skip_reasons": ["empty trades"]}

    rows = []
    skip_reasons = []
    close_all = pd.to_numeric(bt.get("close", pd.Series(index=bt.index, dtype=float)), errors="coerce").ffill()

    for _, trade in trades.iterrows():
        entry_bar, entry_source = _v44b_resolve_bar(bt, trade, "entry")
        exit_bar, exit_source = _v44b_resolve_bar(bt, trade, "exit")
        if entry_bar is None or exit_bar is None:
            skip_reasons.append(f"unresolved bars: {entry_source}/{exit_source}")
            continue
        entry_bar = max(0, min(int(entry_bar), len(bt) - 1))
        exit_bar = max(entry_bar, min(int(exit_bar), len(bt) - 1))
        segment = bt.iloc[entry_bar:exit_bar + 1].copy()
        if segment.empty:
            skip_reasons.append("empty segment")
            continue

        side_txt = str(trade.get("Side", "LONG")).upper().strip()
        side_sign = -1.0 if side_txt == "SHORT" else 1.0

        seg_close = pd.to_numeric(segment.get("close", close_all.iloc[entry_bar:exit_bar + 1]), errors="coerce").ffill()
        entry_price = _v44b_to_float(trade.get("Entry Price", np.nan), np.nan)
        exit_price = _v44b_to_float(trade.get("Exit Price", np.nan), np.nan)
        if pd.isna(entry_price) or entry_price <= 0:
            entry_price = _v44b_to_float(seg_close.iloc[0], np.nan)
        if pd.isna(exit_price) or exit_price <= 0:
            exit_price = _v44b_to_float(seg_close.iloc[-1], np.nan)

        trade_return = _v44b_to_float(trade.get("Return", np.nan), np.nan)
        if pd.isna(trade_return) and pd.notna(entry_price) and pd.notna(exit_price) and entry_price > 0 and exit_price > 0:
            trade_return = exit_price / entry_price - 1.0 if side_sign > 0 else entry_price / exit_price - 1.0

        if "benchmark_return" in segment.columns:
            bench_r = pd.to_numeric(segment["benchmark_return"], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
            benchmark_return = float((1.0 + bench_r).prod() - 1.0)
        elif "returns" in segment.columns:
            bench_r = pd.to_numeric(segment["returns"], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
            benchmark_return = float((1.0 + bench_r).prod() - 1.0)
        else:
            benchmark_return = 0.0

        active_return = trade_return - benchmark_return if pd.notna(trade_return) else np.nan

        fwd_end = min(entry_bar + 5, len(bt) - 1)
        fwd = bt.iloc[entry_bar:fwd_end + 1].copy()
        fwd_close = pd.to_numeric(fwd.get("close", pd.Series(index=fwd.index, dtype=float)), errors="coerce").ffill()
        fwd5 = np.nan
        entry_5b_mfe = np.nan
        entry_5b_mae = np.nan
        try:
            base_px = entry_price if pd.notna(entry_price) and entry_price > 0 else float(fwd_close.iloc[0])
            if side_sign > 0:
                fwd_path = fwd_close / base_px - 1.0
            else:
                fwd_path = base_px / fwd_close - 1.0
            fwd5 = float(fwd_path.iloc[-1]) if not fwd_path.empty else np.nan
            if all(c in fwd.columns for c in ["high", "low"]):
                high = pd.to_numeric(fwd["high"], errors="coerce").fillna(fwd_close)
                low = pd.to_numeric(fwd["low"], errors="coerce").fillna(fwd_close)
                if side_sign > 0:
                    entry_5b_mfe = float((high / base_px - 1.0).max())
                    entry_5b_mae = float((low / base_px - 1.0).min())
                else:
                    entry_5b_mfe = float((base_px / low - 1.0).max())
                    entry_5b_mae = float((base_px / high - 1.0).min())
            else:
                entry_5b_mfe = float(fwd_path.max())
                entry_5b_mae = float(fwd_path.min())
        except Exception:
            pass

        mfe = _v44b_to_float(trade.get("MFE", np.nan), np.nan)
        mae = _v44b_to_float(trade.get("MAE", np.nan), np.nan)
        avg_abs_exposure = float(pd.to_numeric(segment.get("exposure", pd.Series(index=segment.index, dtype=float)), errors="coerce").abs().mean()) if "exposure" in segment.columns else np.nan
        costs_sum = float(pd.to_numeric(segment.get("costs", pd.Series(0.0, index=segment.index)), errors="coerce").fillna(0.0).sum()) if "costs" in segment.columns else 0.0
        turnover_sum = float(pd.to_numeric(segment.get("turnover", pd.Series(0.0, index=segment.index)), errors="coerce").fillna(0.0).sum()) if "turnover" in segment.columns else 0.0

        if pd.notna(active_return) and active_return >= 0:
            label = "Good trade / not failure"
        elif benchmark_return > 0.01 and pd.notna(trade_return) and trade_return < benchmark_return:
            label = "Underperformed bullish benchmark"
        elif pd.notna(fwd5) and fwd5 < 0:
            label = "Bad entry / negative follow-through"
        elif pd.notna(avg_abs_exposure) and avg_abs_exposure < 0.25:
            label = "Cash drag / low exposure"
        else:
            label = "Unclassified active loss"

        rows.append(
            {
                "Entry Date": _v44b_format_dt(bt.index[entry_bar]),
                "Exit Date": _v44b_format_dt(bt.index[exit_bar]),
                "Side": side_txt or "LONG",
                "Bars": int(exit_bar - entry_bar + 1),
                "Trade Return": trade_return,
                "Benchmark Return During Trade": benchmark_return,
                "Active Return vs Benchmark": active_return,
                "Entry 5B Forward": fwd5,
                "Entry 5B MFE": entry_5b_mfe,
                "Entry 5B MAE": entry_5b_mae,
                "MFE": mfe,
                "MAE": mae,
                "Avg Abs Exposure": avg_abs_exposure,
                "Costs Sum": costs_sum,
                "Turnover Sum": turnover_sum,
                "Failure Label": label,
                "Entry Resolver": entry_source,
                "Exit Resolver": exit_source,
            }
        )

    out = pd.DataFrame(rows)
    stats = {
        "total": int(len(trades)),
        "decomposed": int(len(out)),
        "skipped": int(max(0, len(trades) - len(out))),
        "skip_reasons": sorted(set(skip_reasons))[:8],
    }
    return out, stats


def _v44b_failure_contribution(trade_map):
    if trade_map is None or not isinstance(trade_map, pd.DataFrame) or trade_map.empty:
        return pd.DataFrame()
    dfm = trade_map.copy()
    active = pd.to_numeric(dfm.get("Active Return vs Benchmark"), errors="coerce").replace([np.inf, -np.inf], np.nan)
    dfm["_loss"] = (-active).clip(lower=0.0).fillna(0.0)
    total_loss = float(dfm["_loss"].sum())
    grouped = dfm.groupby("Failure Label", dropna=False).agg(
        Trades=("Failure Label", "size"),
        Avg_Active_Return=("Active Return vs Benchmark", "mean"),
        Loss=("_loss", "sum"),
    ).reset_index()
    grouped["Loss_Contribution"] = grouped["Loss"] / total_loss if total_loss > 0 else 0.0
    grouped = grouped.sort_values(["Loss_Contribution", "Trades"], ascending=[False, False])
    return grouped[["Failure Label", "Trades", "Avg_Active_Return", "Loss_Contribution"]]


def _v44b_display_trade_map(trade_map):
    if trade_map is None or not isinstance(trade_map, pd.DataFrame) or trade_map.empty:
        return pd.DataFrame()
    out = trade_map.copy()
    for col in [
        "Trade Return", "Benchmark Return During Trade", "Active Return vs Benchmark",
        "Entry 5B Forward", "Entry 5B MFE", "Entry 5B MAE", "MFE", "MAE",
        "Avg Abs Exposure", "Costs Sum",
    ]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _v44b_format_pct(x))
    if "Turnover Sum" in out.columns:
        out["Turnover Sum"] = out["Turnover Sum"].map(lambda x: _v44b_format_num(x))
    return out


def _v44b_display_contribution(contrib):
    if contrib is None or not isinstance(contrib, pd.DataFrame) or contrib.empty:
        return pd.DataFrame()
    out = contrib.copy()
    for col in ["Avg_Active_Return", "Loss_Contribution"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _v44b_format_pct(x))
    return out


def _v44b_daily_audit(bt, n=120):
    if bt is None or not isinstance(bt, pd.DataFrame) or bt.empty:
        return pd.DataFrame()
    cols = ["close", "exposure", "strategy_return", "benchmark_return", "costs", "turnover", "equity", "benchmark"]
    keep = [c for c in cols if c in bt.columns]
    out = bt[keep].tail(n).copy()
    out.insert(0, "Date", [_v44b_format_dt(x) for x in out.index])
    for col in ["exposure", "strategy_return", "benchmark_return", "costs", "turnover"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _v44b_format_pct(x))
    for col in ["close", "equity", "benchmark"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _v44b_format_num(x))
    return out.reset_index(drop=True)


def _mutation_trade_failure_decomposition_v44_pack(*args, **kwargs):
    kw = _v44b_extract_kwargs(args, kwargs)
    ticker = kw.get("ticker", "")
    df = kw.get("df", None)
    bt = kw.get("bt", None)
    trades = kw.get("trades", None)
    metrics = kw.get("metrics", {}) or {}
    cfg = kw.get("cfg", None)
    diagnostics = kw.get("diagnostics", {}) or {}

    source_path, source_df, best_row = _v44b_find_best_mutation_source(diagnostics)
    mutation_id = str(_v44b_row_value(best_row, ["Mutation ID", "Experiment ID", "ID", "mutation_id"], "N/A"))
    mutation_name = str(_v44b_row_value(best_row, ["Mutation", "Best mutation", "Name", "mutation_name"], "N/A"))
    raw_changes = _v44b_row_value(best_row, ["Changes", "Change", "Config Changes", "Params", "change_to_test"], {})
    changes = _v44b_parse_changes(raw_changes)

    replay_error = ""
    replay = {}
    replay_bt = bt
    replay_trades = trades
    replay_metrics = metrics
    test_cfg = _v44b_make_cfg_copy(cfg, changes)

    try:
        if df is not None and cfg is not None and callable(globals().get("_run_backtest")):
            replay = _run_backtest(df, test_cfg)
            if isinstance(replay, dict) and not replay.get("error"):
                replay_bt = replay.get("data", bt)
                replay_trades = replay.get("trades", trades)
                replay_metrics = replay.get("metrics", metrics)
            elif isinstance(replay, dict):
                replay_error = str(replay.get("error", "unknown replay error"))
    except Exception as exc:
        replay_error = str(exc)

    trade_map, resolver_stats = _v44b_trade_failure_map(replay_bt, replay_trades)
    contrib = _v44b_failure_contribution(trade_map)

    total_return = _v44b_to_float((replay_metrics or {}).get("Total Return"), np.nan)
    benchmark_return = _v44b_to_float((replay_metrics or {}).get("Benchmark Return"), np.nan)
    active_alpha = _v44b_to_float((replay_metrics or {}).get("Relative Alpha"), np.nan)
    if pd.isna(active_alpha) and pd.notna(total_return) and pd.notna(benchmark_return):
        active_alpha = total_return - benchmark_return
    sharpe = _v44b_to_float((replay_metrics or {}).get("Sharpe"), np.nan)

    flat_bench_return = np.nan
    flat_share = np.nan
    engine_active_bars = 0
    try:
        if replay_bt is not None and isinstance(replay_bt, pd.DataFrame) and not replay_bt.empty:
            exp = pd.to_numeric(replay_bt.get("exposure", pd.Series(0.0, index=replay_bt.index)), errors="coerce").fillna(0.0)
            flat = exp.abs() <= 1e-12
            engine_active_bars = int((~flat).sum())
            flat_share = float(flat.mean())
            if "benchmark_return" in replay_bt.columns:
                br = pd.to_numeric(replay_bt.loc[flat, "benchmark_return"], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
                flat_bench_return = float((1.0 + br).prod() - 1.0) if len(br) else 0.0
    except Exception:
        pass

    dominant_failure = "N/A"
    if isinstance(contrib, pd.DataFrame) and not contrib.empty:
        dominant_failure = str(contrib.iloc[0].get("Failure Label", "N/A"))

    negative_trade_share = np.nan
    avg_entry_5b = np.nan
    try:
        if not trade_map.empty:
            ar = pd.to_numeric(trade_map["Active Return vs Benchmark"], errors="coerce")
            negative_trade_share = float((ar < 0).mean())
            avg_entry_5b = float(pd.to_numeric(trade_map["Entry 5B Forward"], errors="coerce").mean())
    except Exception:
        pass

    if pd.notna(flat_bench_return) and flat_bench_return > 0.25 and pd.notna(active_alpha) and active_alpha < 0:
        level = "Cash drag dominant"
        read = "L'alpha négatif vient surtout d'une faible exposition pendant un benchmark haussier."
        next_track = "coverage without overfit"
        score = 25.0
    elif "Underperformed bullish benchmark" in dominant_failure:
        level = "Active underperformance"
        read = "Les trades exposés sous-performent le benchmark pendant les phases haussières."
        next_track = "source quality / active alpha"
        score = 20.0
    elif "Bad entry" in dominant_failure or (pd.notna(avg_entry_5b) and avg_entry_5b < 0):
        level = "Entry timing failure"
        read = "Le problème prioritaire vient du follow-through négatif après entrée."
        next_track = "entry confirmation"
        score = 30.0
    elif pd.notna(active_alpha) and active_alpha >= 0:
        level = "Failure not dominant"
        read = "La mutation ne montre pas d'alpha actif négatif dans le replay isolé."
        next_track = "OOS only after gates"
        score = 55.0
    else:
        level = "Unresolved failure"
        read = "La mutation reste négative, mais la cause dominante n'est pas encore isolée proprement."
        next_track = "source forensics"
        score = 15.0

    incomplete = resolver_stats.get("decomposed", 0) < resolver_stats.get("total", 0)

    summary = pd.DataFrame(
        [
            ["V4.4b level", level, "Lecture synthétique de l'autopsie V4.4b."],
            ["V4.4b score", f"{_v44b_format_num(score, 0)}/100", "Score research explicatif, pas score de performance."],
            ["Read", read, "Interprétation opérationnelle."],
            ["V4.3 source", str(source_path or "N/A"), "Table source utilisée pour sélectionner la mutation."],
            ["Best mutation ID", mutation_id, "Mutation V4.3 rejouée."],
            ["Best mutation", mutation_name, "Nom de la mutation."],
            ["Changes", str(changes or raw_changes), "Paramètres modifiés par V4.3."],
            ["Strategy return", _v44b_format_pct(total_return), "Rendement du replay mutation."],
            ["Benchmark return", _v44b_format_pct(benchmark_return), "Rendement benchmark sur la même fenêtre."],
            ["Active alpha", _v44b_format_pct(active_alpha), "Stratégie - benchmark."],
            ["Sharpe", _v44b_format_num(sharpe), "Sharpe du replay."],
            ["Trades total", str(resolver_stats.get("total", 0)), "Trades détectés par le replay."],
            ["Trades decomposed", str(resolver_stats.get("decomposed", 0)), "Trades reconstruits par Entry/Exit Bar ou Entry/Exit Date."],
            ["Trades skipped", str(resolver_stats.get("skipped", 0)), "Trades non résolus."],
            ["Engine active bars", str(engine_active_bars), "Barres exposées dans le replay."],
            ["Flat benchmark return", _v44b_format_pct(flat_bench_return), "Rendement benchmark pendant les périodes cash."],
            ["Flat share", _v44b_format_pct(flat_share), "Part du replay sans exposition."],
            ["Dominant failure", dominant_failure, "Cause dominante par contribution de perte active."],
            ["Next track", next_track, "Prochaine piste contrôlée."],
            ["Replay error", replay_error or "None", "Erreur de replay si présente."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    checks = pd.DataFrame(
        [
            ["Best V4.3 mutation available", "PASS" if mutation_id != "N/A" or changes else "WARN", mutation_id, "Mutation V4.3 utilisée pour replay isolé."],
            ["Replay isolation", "PASS" if not replay_error else "WARN", "new cfg copy via BacktestConfig", "Aucun changement permanent sur cfg/moteur courant."],
            ["Trades generated", "PASS" if resolver_stats.get("total", 0) > 0 else "FAIL", resolver_stats.get("total", 0), "Échantillon de trades du replay."],
            ["Trades decomposed", "PASS" if not incomplete else "WARN", f"{resolver_stats.get('decomposed', 0)}/{resolver_stats.get('total', 0)}", "Résolution robuste Entry Bar/Exit Bar puis Entry Date/Exit Date."],
            ["Engine active bars", "PASS" if engine_active_bars > 0 else "FAIL", engine_active_bars, "Barres exposées dans le replay."],
            ["Active alpha positive", "PASS" if pd.notna(active_alpha) and active_alpha > 0 else "FAIL", _v44b_format_pct(active_alpha), "Condition minimale avant OOS."],
            ["Trade active selection", "FAIL" if pd.notna(negative_trade_share) and negative_trade_share > 0.50 else "PASS", _v44b_format_pct(negative_trade_share), "Part des trades avec active return négatif."],
            ["Entry 5B follow-through", "WARN" if pd.notna(avg_entry_5b) and avg_entry_5b < 0 else "PASS", _v44b_format_pct(avg_entry_5b), "Follow-through moyen 5 barres après entrée."],
            ["Cash drag proxy", "WARN" if pd.notna(flat_bench_return) and flat_bench_return > 0.10 else "PASS", _v44b_format_pct(flat_bench_return), "Benchmark return pendant les périodes flat."],
            ["Do not promote", "PASS", "RESEARCH ONLY", "V4.4b explique l'échec, ne valide rien."],
        ],
        columns=["Check", "Status", "Value", "Read"],
    )

    actions = pd.DataFrame(
        [
            ["P0", "Do not OOS yet", "Alpha V4.4b <= 0 or trade selection weak", "Ne pas lancer OOS tant que l'alpha actif reste négatif."],
            ["P0", "Complete trade autopsy", f"{resolver_stats.get('decomposed', 0)}/{resolver_stats.get('total', 0)} decomposed", "Contrôler les trades non résolus si le compteur n'est pas complet."],
            ["P0", "Decompose active losers", dominant_failure, "Inspecter les trades avec plus forte contribution négative."],
            ["P1", "Coverage repair", "Cash drag / low exposure risk", "Augmenter couverture seulement si active return des barres exposées devient positif."],
            ["P1", "Entry confirmation", "Follow-through risk", "Tester confirmation 3B/5B uniquement si elle reste one-factor."],
            ["P1", "Reject mutation if needed", "If trade active return remains negative", "Revenir à V3.9/V4.0 source candidate plutôt que forcer exits/sizing."],
        ],
        columns=["Priority", "Action", "Reason", "Next Step"],
    )

    cards = [
        {"label": "V4.4b failure map", "value": level, "delta": f"{_v44b_format_num(score, 0)}/100"},
        {"label": "Mutation audited", "value": mutation_id, "delta": mutation_name},
        {"label": "Trades decomposed", "value": f"{resolver_stats.get('decomposed', 0)}/{resolver_stats.get('total', 0)}", "delta": "robust resolver"},
        {"label": "Active alpha", "value": _v44b_format_pct(active_alpha), "delta": "vs benchmark"},
        {"label": "Dominant failure", "value": dominant_failure, "delta": "root cause"},
        {"label": "Next track", "value": next_track, "delta": "research"},
    ]

    return {
        "enabled": True,
        "level": level,
        "score": score,
        "read": read,
        "mutation_id": mutation_id,
        "mutation_name": mutation_name,
        "changes": changes,
        "cards": cards,
        "summary": summary,
        "checks": checks,
        "trade_map": trade_map,
        "trade_map_display": _v44b_display_trade_map(trade_map),
        "failure_contribution": contrib,
        "failure_contribution_display": _v44b_display_contribution(contrib),
        "actions": actions,
        "daily_audit": _v44b_daily_audit(replay_bt, 120),
        "resolver_stats": resolver_stats,
        "incomplete_trade_map": incomplete,
        "active_alpha": active_alpha,
        "dominant_failure": dominant_failure,
        "next_track": next_track,
    }


def _render_mutation_trade_failure_decomposition_v44(*args, **kwargs):
    pack = _mutation_trade_failure_decomposition_v44_pack(*args, **kwargs)

    st.subheader("Mutation Trade Failure Decomposition V4.4b")
    st.caption(
        "Autopsie lecture seule de la meilleure mutation V4.3 : replay isolé, trade map robuste par bar/date, "
        "active return, cash drag, timing d'entrée et prochaine hypothèse. Aucun impact sur le moteur courant, "
        "l'equity curve ou le verdict."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    read = str(pack.get("read", ""))
    level = str(pack.get("level", ""))
    if "Cash drag" in level:
        st.info(f"Lecture V4.4b : {read}")
    elif "Failure not" in level:
        st.success(f"Lecture V4.4b : {read}")
    else:
        st.warning(f"Lecture V4.4b : {read}")

    if bool(pack.get("incomplete_trade_map", False)):
        stats = pack.get("resolver_stats", {}) or {}
        st.warning(
            "Trade map incomplet : "
            f"{stats.get('decomposed', 0)}/{stats.get('total', 0)} trades décomposés. "
            "V4.4b a utilisé le resolver bar/date, mais certains trades restent non résolus."
        )

    with st.expander("V4.4b failure summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.4b indisponible.")

    with st.expander("V4.4b failure checks", expanded=True):
        checks = pack.get("checks", pd.DataFrame())
        if isinstance(checks, pd.DataFrame) and not checks.empty:
            st.dataframe(checks, use_container_width=True, hide_index=True)
        else:
            st.info("Checks V4.4b indisponibles.")

    with st.expander("V4.4b robust trade failure map", expanded=True):
        display = pack.get("trade_map_display", pd.DataFrame())
        if isinstance(display, pd.DataFrame) and not display.empty:
            st.dataframe(display, use_container_width=True, hide_index=True)
        else:
            st.info("Aucun trade décomposable par le resolver V4.4b.")

    with st.expander("V4.4b failure contribution by label", expanded=True):
        contrib = pack.get("failure_contribution_display", pd.DataFrame())
        if isinstance(contrib, pd.DataFrame) and not contrib.empty:
            st.dataframe(contrib, use_container_width=True, hide_index=True)
        else:
            st.info("Contribution par label indisponible.")

    with st.expander("V4.4b next controlled actions", expanded=True):
        actions = pack.get("actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.4b indisponibles.")

    with st.expander("V4.4b daily audit — last 120 bars", expanded=False):
        audit = pack.get("daily_audit", pd.DataFrame())
        if isinstance(audit, pd.DataFrame) and not audit.empty:
            st.dataframe(audit, use_container_width=True, hide_index=True)
        else:
            st.info("Daily audit V4.4b indisponible.")

    return pack

