def _v45_safe_series_bool(value, index):
    try:
        if isinstance(value, pd.Series):
            return value.reindex(index).fillna(False).astype(bool)
        return pd.Series(bool(value), index=index)
    except Exception:
        return pd.Series(False, index=index)


def _v45_compound_return(series) -> float:
    try:
        s = pd.to_numeric(series, errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
        if len(s) == 0:
            return np.nan
        return float((1.0 + s).prod() - 1.0)
    except Exception:
        return np.nan


def _v45_make_cfg(cfg, changes: dict):
    try:
        if callable(globals().get("_v44b_make_cfg_copy")):
            return _v44b_make_cfg_copy(cfg, changes)
        base = dict(getattr(cfg, "__dict__", {}))
        base.update({k: v for k, v in dict(changes or {}).items() if k in base})
        return BacktestConfig(**base)
    except Exception:
        return cfg


def _v45_brt_filter_frame(df: pd.DataFrame, cfg: BacktestConfig) -> dict[str, Any]:
    """
    Reconstruit la cascade de filtres Benchmark-Relative Trend.
    Lecture seule : ne modifie ni cfg, ni signal moteur, ni equity curve.
    """
    empty = {
        "available": False,
        "reason": "BRT filter frame unavailable.",
        "frame": pd.DataFrame(),
        "benchmark_label": "N/A",
        "benchmark_fallback": True,
        "params": {},
    }

    try:
        if df is None or len(df) == 0 or cfg is None:
            return empty

        work = _extract_ohlc(df) if callable(globals().get("_extract_ohlc")) else df.copy()
        if work is None or work.empty or "close" not in work.columns:
            return empty

        close = (
            pd.to_numeric(work["close"], errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .ffill()
            .dropna()
        )

        if close.empty or len(close) < 80:
            out = empty.copy()
            out["reason"] = "Historique insuffisant pour V4.5."
            return out

        work = work.reindex(close.index).copy()

        fast_h = max(int(getattr(cfg, "brt_fast_horizon", 20)), 2)
        slow_h = max(int(getattr(cfg, "brt_slow_horizon", 60)), fast_h + 1)
        min_active = float(getattr(cfg, "brt_min_active_mom_pct", 0.0)) / 100.0
        require_dual = bool(getattr(cfg, "brt_require_dual_horizon", True))
        use_benchmark_gate = bool(getattr(cfg, "brt_use_benchmark_trend_gate", True))
        use_vol_cap = bool(getattr(cfg, "brt_use_vol_cap", False))

        bench_cfg = cfg
        auto_benchmark_used = False
        auto_symbol = ""

        if not str(getattr(cfg, "benchmark_ticker", "") or "").strip():
            asset_ticker = str(getattr(cfg, "asset_ticker", "") or "").upper().strip()
            auto_symbol = _sector_benchmark_guess(asset_ticker) if asset_ticker else "SPY"
            auto_benchmark_used = True
            bench_cfg = _v45_make_cfg(
                cfg,
                {
                    "benchmark_ticker": auto_symbol,
                    "benchmark_label": f"Auto Sector ETF ({auto_symbol})",
                    "benchmark_mode": "Sector ETF",
                },
            )

        benchmark_returns, benchmark_label, benchmark_fallback = _load_benchmark_returns(work, bench_cfg)
        benchmark_returns = (
            pd.to_numeric(benchmark_returns.reindex(close.index), errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .fillna(0.0)
        )

        benchmark_nav = (1.0 + benchmark_returns).cumprod()
        benchmark_nav = benchmark_nav.replace([np.inf, -np.inf], np.nan).ffill().bfill()

        asset_ret_fast = close.pct_change(fast_h)
        asset_ret_slow = close.pct_change(slow_h)
        bench_ret_fast = benchmark_nav.pct_change(fast_h)
        bench_ret_slow = benchmark_nav.pct_change(slow_h)

        active_fast = asset_ret_fast - bench_ret_fast
        active_slow = asset_ret_slow - bench_ret_slow

        fast_pass = active_fast > min_active
        slow_pass = active_slow > min_active
        dual_pass = fast_pass & slow_pass

        active_score = 0.40 * active_fast + 0.60 * active_slow

        if require_dual:
            core_pass = dual_pass.copy()
        else:
            core_pass = active_score > min_active

        benchmark_gate = pd.Series(True, index=close.index)
        benchmark_ma = pd.Series(np.nan, index=close.index)
        benchmark_gate_margin = pd.Series(np.nan, index=close.index)

        if use_benchmark_gate:
            ma_window = max(int(getattr(cfg, "brt_benchmark_ma_window", 100)), 5)
            benchmark_ma = benchmark_nav.rolling(ma_window).mean()
            benchmark_gate = benchmark_nav > benchmark_ma
            benchmark_gate_margin = benchmark_nav / benchmark_ma.replace(0, np.nan) - 1.0

        after_benchmark = core_pass & benchmark_gate.fillna(False)

        realized_vol = close.pct_change().rolling(max(int(getattr(cfg, "brt_vol_window", 20)), 5)).std() * np.sqrt(252)
        vol_gate = pd.Series(True, index=close.index)
        vol_cap = pd.Series(np.nan, index=close.index)
        vol_margin = pd.Series(np.nan, index=close.index)

        if use_vol_cap:
            vol_window = max(int(getattr(cfg, "brt_vol_window", 20)), 5)
            vol_pct = max(5.0, min(99.0, float(getattr(cfg, "brt_vol_percentile", 80.0)))) / 100.0
            realized_vol = close.pct_change().rolling(vol_window).std() * np.sqrt(252)
            hist_window = max(126, vol_window * 5)
            vol_cap = realized_vol.rolling(hist_window, min_periods=vol_window).quantile(vol_pct)
            vol_gate = (realized_vol <= vol_cap) | vol_cap.isna()
            vol_margin = vol_cap - realized_vol

        eligible = after_benchmark & vol_gate.fillna(True)

        raw = pd.Series(0.0, index=close.index)
        raw[eligible.fillna(False)] = 1.0

        raw_persist = raw.replace(0.0, np.nan).ffill().fillna(0.0)
        neutral_exit = (active_fast <= 0.0) & (active_slow <= 0.0)

        raw_final = raw_persist.copy()
        raw_final[neutral_exit.fillna(False)] = 0.0

        if not bool(getattr(cfg, "allow_short", False)):
            raw_final = raw_final.clip(lower=0.0, upper=1.0)

        engine_signal = raw_final.shift(1).fillna(0.0).clip(-1.0, 1.0)

        frame = pd.DataFrame(index=close.index)
        frame["close"] = close
        frame["benchmark_return"] = benchmark_returns
        frame["benchmark_nav"] = benchmark_nav
        frame["asset_ret_fast"] = asset_ret_fast
        frame["bench_ret_fast"] = bench_ret_fast
        frame["active_fast"] = active_fast
        frame["fast_pass"] = fast_pass.fillna(False).astype(bool)
        frame["asset_ret_slow"] = asset_ret_slow
        frame["bench_ret_slow"] = bench_ret_slow
        frame["active_slow"] = active_slow
        frame["slow_pass"] = slow_pass.fillna(False).astype(bool)
        frame["dual_pass"] = dual_pass.fillna(False).astype(bool)
        frame["active_score"] = active_score
        frame["core_pass"] = core_pass.fillna(False).astype(bool)
        frame["benchmark_gate"] = benchmark_gate.fillna(False).astype(bool)
        frame["benchmark_gate_margin"] = benchmark_gate_margin
        frame["after_benchmark_gate"] = after_benchmark.fillna(False).astype(bool)
        frame["realized_vol"] = realized_vol
        frame["vol_cap"] = vol_cap
        frame["vol_margin"] = vol_margin
        frame["vol_gate"] = vol_gate.fillna(True).astype(bool)
        frame["eligible_pre_shift"] = eligible.fillna(False).astype(bool)
        frame["raw_final_pre_shift"] = raw_final
        frame["engine_signal_t1"] = engine_signal

        for h in [1, 3, 5, 10, 20]:
            frame[f"asset_fwd_{h}b"] = close.shift(-h) / close - 1.0
            frame[f"bench_fwd_{h}b"] = benchmark_nav.shift(-h) / benchmark_nav - 1.0
            frame[f"active_fwd_{h}b"] = frame[f"asset_fwd_{h}b"] - frame[f"bench_fwd_{h}b"]

        missing_count = pd.Series(0, index=frame.index, dtype=int)
        missing_labels = pd.Series("", index=frame.index, dtype=object)

        def _add_missing(mask, label):
            nonlocal missing_count, missing_labels
            failed = ~pd.Series(mask, index=frame.index).fillna(False).astype(bool)
            missing_count = missing_count + failed.astype(int)
            missing_labels = np.where(
                failed,
                np.where(missing_labels.astype(str) == "", label, missing_labels.astype(str) + " + " + label),
                missing_labels,
            )
            missing_labels = pd.Series(missing_labels, index=frame.index, dtype=object)

        _add_missing(frame["fast_pass"], "fast active")
        if require_dual:
            _add_missing(frame["slow_pass"], "slow active")
        else:
            _add_missing(frame["core_pass"], "active score")
        if use_benchmark_gate:
            _add_missing(frame["benchmark_gate"], "benchmark gate")
        if use_vol_cap:
            _add_missing(frame["vol_gate"], "vol cap")

        frame["missing_count"] = missing_count
        frame["missing_conditions"] = missing_labels.replace("", "None")
        frame["active_threshold_margin"] = frame["active_score"] - min_active
        frame["distance_to_threshold"] = np.minimum(frame["active_fast"] - min_active, frame["active_slow"] - min_active)

        return {
            "available": True,
            "reason": "OK",
            "frame": frame.replace([np.inf, -np.inf], np.nan),
            "benchmark_label": benchmark_label,
            "benchmark_fallback": bool(benchmark_fallback),
            "params": {
                "fast_horizon": fast_h,
                "slow_horizon": slow_h,
                "min_active": min_active,
                "require_dual": require_dual,
                "use_benchmark_gate": use_benchmark_gate,
                "use_vol_cap": use_vol_cap,
                "auto_benchmark_used": auto_benchmark_used,
                "auto_symbol": auto_symbol,
            },
        }

    except Exception as exc:
        out = empty.copy()
        out["reason"] = f"V4.5 BRT frame error: {exc}"
        return out


def _v45_filter_table(brt_pack: dict[str, Any]) -> pd.DataFrame:
    try:
        frame = brt_pack.get("frame", pd.DataFrame())
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return pd.DataFrame()

        n = max(len(frame), 1)

        def add(rows, condition, mask, read):
            mask = pd.Series(mask, index=frame.index).fillna(False).astype(bool)
            passed = int(mask.sum())
            rows.append(
                {
                    "Filter / Condition": condition,
                    "Bars passing": f"{passed}/{n}",
                    "Pass rate": passed / n,
                    "Bars blocked": n - passed,
                    "Block rate": 1.0 - passed / n,
                    "Read": read,
                }
            )

        rows = []
        add(rows, "Fast active momentum", frame["fast_pass"], "Actif > benchmark sur horizon fast.")
        add(rows, "Slow active momentum", frame["slow_pass"], "Actif > benchmark sur horizon slow.")
        add(rows, "Dual/core condition", frame["core_pass"], "Condition centrale avant gates.")
        add(rows, "Benchmark trend gate", frame["benchmark_gate"], "Benchmark en tendance positive selon la MA configurée.")
        add(rows, "After benchmark gate", frame["after_benchmark_gate"], "Signal restant après filtre benchmark.")
        add(rows, "Volatility gate", frame["vol_gate"], "Filtre de volatilité, s'il est activé.")
        add(rows, "Eligible pre-shift", frame["eligible_pre_shift"], "Signal candidat avant t+1.")
        add(rows, "Engine exposure t+1", frame["engine_signal_t1"].abs() > 0, "Exposition réellement active après décalage moteur.")

        return pd.DataFrame(rows)

    except Exception:
        return pd.DataFrame()


def _v45_near_miss_table(brt_pack: dict[str, Any], limit: int = 40) -> pd.DataFrame:
    try:
        frame = brt_pack.get("frame", pd.DataFrame())
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            return pd.DataFrame()

        near = frame.copy()
        near = near[~near["eligible_pre_shift"].fillna(False).astype(bool)].copy()

        if near.empty:
            return pd.DataFrame()

        near["near_miss_rank"] = (
            near["missing_count"].astype(float) * 10.0
            - pd.to_numeric(near["active_threshold_margin"], errors="coerce").fillna(-1.0)
        )

        near = near[
            (near["missing_count"] <= 2)
            | (pd.to_numeric(near["active_threshold_margin"], errors="coerce") > -0.03)
            | (pd.to_numeric(near["active_fwd_5b"], errors="coerce") > 0.02)
        ].copy()

        if near.empty:
            return pd.DataFrame()

        near = near.sort_values(["missing_count", "near_miss_rank"], ascending=[True, True]).head(limit)

        out = pd.DataFrame(
            {
                "Date": [_format_dt(x) for x in near.index],
                "Close": near["close"],
                "Missing condition": near["missing_conditions"],
                "Missing count": near["missing_count"],
                "Active fast": near["active_fast"],
                "Active slow": near["active_slow"],
                "Active score": near["active_score"],
                "Distance to threshold": near["distance_to_threshold"],
                "Benchmark gate margin": near["benchmark_gate_margin"],
                "Vol margin": near["vol_margin"],
                "Would-be exposure": 1.0,
                "Next 5B active return": near["active_fwd_5b"],
                "Next 10B active return": near["active_fwd_10b"],
                "Next 20B active return": near["active_fwd_20b"],
            }
        )

        return out.replace([np.inf, -np.inf], np.nan)

    except Exception:
        return pd.DataFrame()


def _v45_run_variant(df: pd.DataFrame, cfg: BacktestConfig, label: str, changes: dict, base_coverage: float = np.nan) -> dict[str, Any]:
    try:
        test_cfg = _v45_make_cfg(cfg, changes)
        result = _run_backtest(df, test_cfg)

        if not isinstance(result, dict) or result.get("error"):
            return {
                "Variant": label,
                "Changes": str(changes or "no change"),
                "Status": "ERROR",
                "Coverage": np.nan,
                "Coverage delta": np.nan,
                "Trades": np.nan,
                "Strategy return": np.nan,
                "Benchmark return": np.nan,
                "Active alpha": np.nan,
                "Exposed active return": np.nan,
                "Exposed hit rate": np.nan,
                "Decision": "ERROR",
                "Read": str(result.get("error", "unknown error")) if isinstance(result, dict) else "unknown error",
            }

        bt = result.get("data", pd.DataFrame())
        metrics = result.get("metrics", {}) or {}

        if bt is None or not isinstance(bt, pd.DataFrame) or bt.empty:
            return {
                "Variant": label,
                "Changes": str(changes or "no change"),
                "Status": "EMPTY",
                "Coverage": np.nan,
                "Coverage delta": np.nan,
                "Trades": np.nan,
                "Strategy return": np.nan,
                "Benchmark return": np.nan,
                "Active alpha": np.nan,
                "Exposed active return": np.nan,
                "Exposed hit rate": np.nan,
                "Decision": "REJECT",
                "Read": "Backtest variant vide.",
            }

        exp = pd.to_numeric(bt.get("exposure", pd.Series(0.0, index=bt.index)), errors="coerce").fillna(0.0)
        active_mask = exp.abs() > 1e-12

        coverage = float(active_mask.mean()) if len(active_mask) else np.nan
        coverage_delta = coverage - base_coverage if pd.notna(base_coverage) else np.nan

        strat_active = np.nan
        bench_active = np.nan
        exposed_active = np.nan
        exposed_hit = np.nan

        if active_mask.any():
            strat_active = _v45_compound_return(bt.loc[active_mask, "strategy_return"])
            bench_active = _v45_compound_return(bt.loc[active_mask, "benchmark_return"])
            exposed_active = strat_active - bench_active if pd.notna(strat_active) and pd.notna(bench_active) else np.nan

            active_bar_alpha = (
                pd.to_numeric(bt.loc[active_mask, "strategy_return"], errors="coerce")
                - pd.to_numeric(bt.loc[active_mask, "benchmark_return"], errors="coerce")
            )
            active_bar_alpha = active_bar_alpha.replace([np.inf, -np.inf], np.nan).dropna()
            exposed_hit = float((active_bar_alpha > 0).mean()) if not active_bar_alpha.empty else np.nan

        total_alpha = _safe_float(metrics.get("Relative Alpha"), np.nan)
        trades = int(_safe_float(metrics.get("Trades"), 0))

        if coverage <= 0:
            decision = "NO_COVERAGE"
            read = "La relaxation ne crée toujours aucune exposition."
            status = "FAIL"
        elif pd.notna(exposed_active) and exposed_active > 0 and (pd.isna(coverage_delta) or coverage_delta >= 0):
            decision = "V46_RESEARCH_CANDIDATE"
            read = "Couverture exploitable : les barres exposées battent le benchmark. À tester en V4.6, sans promotion directe."
            status = "PASS"
        elif pd.notna(exposed_active) and exposed_active <= 0:
            decision = "REJECT_COVERAGE_REPAIR"
            read = "La couverture augmente éventuellement, mais les barres exposées ne battent pas le benchmark."
            status = "FAIL"
        else:
            decision = "INCONCLUSIVE"
            read = "Couverture créée mais active return exposé non mesurable."
            status = "WARN"

        return {
            "Variant": label,
            "Changes": str(changes or "no change"),
            "Status": status,
            "Coverage": coverage,
            "Coverage delta": coverage_delta,
            "Trades": trades,
            "Strategy return": _safe_float(metrics.get("Total Return"), np.nan),
            "Benchmark return": _safe_float(metrics.get("Benchmark Return"), np.nan),
            "Active alpha": total_alpha,
            "Exposed strategy return": strat_active,
            "Exposed benchmark return": bench_active,
            "Exposed active return": exposed_active,
            "Exposed hit rate": exposed_hit,
            "Decision": decision,
            "Read": read,
        }

    except Exception as exc:
        return {
            "Variant": label,
            "Changes": str(changes or "no change"),
            "Status": "ERROR",
            "Coverage": np.nan,
            "Coverage delta": np.nan,
            "Trades": np.nan,
            "Strategy return": np.nan,
            "Benchmark return": np.nan,
            "Active alpha": np.nan,
            "Exposed active return": np.nan,
            "Exposed hit rate": np.nan,
            "Decision": "ERROR",
            "Read": str(exc),
        }


def _v45_variant_table(df: pd.DataFrame, cfg: BacktestConfig, v44_pack: dict[str, Any] | None = None) -> pd.DataFrame:
    if df is None or cfg is None:
        return pd.DataFrame()

    changes_from_v44 = {}
    try:
        if isinstance(v44_pack, dict):
            changes_from_v44 = v44_pack.get("changes", {}) or {}
    except Exception:
        changes_from_v44 = {}

    base_cfg = _v45_make_cfg(cfg, changes_from_v44)

    variants: list[tuple[str, dict]] = [("Current V4.4b replay config", {})]

    try:
        if str(getattr(base_cfg, "strategy", "")) == "Benchmark-Relative Trend":
            if bool(getattr(base_cfg, "brt_require_dual_horizon", True)):
                variants.append(("One-factor: disable dual horizon", {"brt_require_dual_horizon": False}))

            current_min = float(getattr(base_cfg, "brt_min_active_mom_pct", 0.0))
            variants.append(("One-factor: relax active threshold -1ppt", {"brt_min_active_mom_pct": current_min - 1.0}))

            if bool(getattr(base_cfg, "brt_use_benchmark_trend_gate", True)):
                variants.append(("One-factor: benchmark gate off", {"brt_use_benchmark_trend_gate": False}))

                current_ma = int(getattr(base_cfg, "brt_benchmark_ma_window", 100))
                if current_ma != 50:
                    variants.append(("One-factor: benchmark MA 50", {"brt_benchmark_ma_window": 50}))

            if bool(getattr(base_cfg, "brt_use_vol_cap", False)):
                variants.append(("One-factor: volatility cap off", {"brt_use_vol_cap": False}))

            current_fast = int(getattr(base_cfg, "brt_fast_horizon", 20))
            if current_fast > 10:
                variants.append(("One-factor: fast horizon 10", {"brt_fast_horizon": 10}))

            current_slow = int(getattr(base_cfg, "brt_slow_horizon", 60))
            if current_slow > 40:
                variants.append(("One-factor: slow horizon 40", {"brt_slow_horizon": 40}))
    except Exception:
        pass

    first = _v45_run_variant(df, base_cfg, variants[0][0], variants[0][1], base_coverage=np.nan)
    base_coverage = _safe_float(first.get("Coverage"), np.nan)

    rows = [first]
    for label, changes in variants[1:]:
        rows.append(_v45_run_variant(df, base_cfg, label, changes, base_coverage=base_coverage))

    return pd.DataFrame(rows)


def _coverage_without_overfit_v45_pack(*args, **kwargs) -> dict[str, Any]:
    kw = _v44b_extract_kwargs(args, kwargs) if callable(globals().get("_v44b_extract_kwargs")) else dict(kwargs or {})

    df = kw.get("df", None)
    cfg = kw.get("cfg", None)
    ticker = kw.get("ticker", "")
    v44_pack = kwargs.get("v44_pack", {}) if isinstance(kwargs, dict) else {}
    if not isinstance(v44_pack, dict):
        v44_pack = {}

    empty = {
        "enabled": False,
        "level": "Unavailable",
        "score": 0.0,
        "read": "V4.5 indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "filter_table": pd.DataFrame(),
        "near_miss": pd.DataFrame(),
        "variant_table": pd.DataFrame(),
        "actions": pd.DataFrame(),
        "decision": "NO_DECISION",
    }

    try:
        if df is None or cfg is None:
            out = empty.copy()
            out["read"] = "df/cfg manquant pour V4.5."
            return out

        test_cfg = _v45_make_cfg(cfg, v44_pack.get("changes", {}) if isinstance(v44_pack, dict) else {})

        brt_pack = _v45_brt_filter_frame(df, test_cfg)
        filter_table = _v45_filter_table(brt_pack)
        near_miss = _v45_near_miss_table(brt_pack)
        variant_table = _v45_variant_table(df, test_cfg, v44_pack)

        frame = brt_pack.get("frame", pd.DataFrame()) if isinstance(brt_pack, dict) else pd.DataFrame()

        engine_active_bars = 0
        eligible_bars = 0
        n = 0
        current_coverage = np.nan

        if isinstance(frame, pd.DataFrame) and not frame.empty:
            n = len(frame)
            engine_active_bars = int((pd.to_numeric(frame["engine_signal_t1"], errors="coerce").fillna(0.0).abs() > 0).sum())
            eligible_bars = int(frame["eligible_pre_shift"].fillna(False).astype(bool).sum())
            current_coverage = engine_active_bars / max(n, 1)

        best_candidate = pd.Series(dtype=object)

        if isinstance(variant_table, pd.DataFrame) and not variant_table.empty:
            candidates = variant_table[
                (variant_table["Variant"] != "Current V4.4b replay config")
                & (pd.to_numeric(variant_table["Exposed active return"], errors="coerce") > 0)
                & (pd.to_numeric(variant_table["Coverage"], errors="coerce") > 0)
            ].copy()

            if not candidates.empty:
                candidates["_sort_alpha"] = pd.to_numeric(candidates["Exposed active return"], errors="coerce")
                candidates["_sort_cov"] = pd.to_numeric(candidates["Coverage"], errors="coerce")
                candidates = candidates.sort_values(["_sort_alpha", "_sort_cov"], ascending=[False, False])
                best_candidate = candidates.iloc[0]

        any_coverage_repair = False
        any_negative_repair = False

        if isinstance(variant_table, pd.DataFrame) and not variant_table.empty:
            non_current = variant_table[variant_table["Variant"] != "Current V4.4b replay config"].copy()
            any_coverage_repair = bool((pd.to_numeric(non_current["Coverage"], errors="coerce") > current_coverage).any())
            any_negative_repair = bool(
                (
                    (pd.to_numeric(non_current["Coverage"], errors="coerce") > current_coverage)
                    & (pd.to_numeric(non_current["Exposed active return"], errors="coerce") <= 0)
                ).any()
            )

        if not best_candidate.empty:
            level = "Coverage candidate found"
            score = 55.0
            decision = "PREPARE_V46_CONTROLLED_MUTATION_RUNNER"
            read = (
                "Une relaxation one-factor crée de la couverture avec active return exposé positif. "
                "Elle doit passer en V4.6 runner contrôlé, sans promotion directe."
            )
        elif any_coverage_repair and any_negative_repair:
            level = "Coverage rejected"
            score = 30.0
            decision = "REJECT_COVERAGE_REPAIR"
            read = (
                "La couverture peut être augmentée, mais les barres exposées restent négatives vs benchmark. "
                "Ne pas forcer la couverture."
            )
        elif engine_active_bars <= 0 and eligible_bars <= 0:
            level = "Signal blocked before exposure"
            score = 20.0
            decision = "RETURN_SOURCE_REDESIGN"
            read = (
                "Aucune barre éligible et aucune exposition moteur. Le problème vient de la source ou des gates, "
                "pas des exits/sizing."
            )
        else:
            level = "Coverage inconclusive"
            score = 35.0
            decision = "CONTINUE_DIAGNOSTIC"
            read = "V4.5 ne valide pas encore de réparation de couverture suffisamment propre."

        near_count = int(len(near_miss)) if isinstance(near_miss, pd.DataFrame) else 0

        summary = pd.DataFrame(
            [
                ["V4.5 level", level, "Lecture synthétique du diagnostic coverage without overfit."],
                ["V4.5 score", f"{_format_num(score, 0)}/100", "Score research explicatif, pas score de performance."],
                ["Read", read, "Interprétation opérationnelle."],
                ["Ticker", str(ticker or "N/A"), "Ticker audité."],
                ["Strategy", str(getattr(test_cfg, "strategy", "N/A")), "Stratégie replay utilisée."],
                ["Benchmark label", str(brt_pack.get("benchmark_label", "N/A")), "Benchmark relatif réellement utilisé."],
                ["Benchmark fallback", str(bool(brt_pack.get("benchmark_fallback", True))), "Fallback benchmark si téléchargement externe indisponible."],
                ["Bars", str(n), "Nombre de barres auditées."],
                ["Eligible pre-shift bars", str(eligible_bars), "Barres candidates avant t+1."],
                ["Engine active bars", str(engine_active_bars), "Barres exposées après t+1."],
                ["Engine coverage", _format_pct(current_coverage), "Couverture moteur actuelle."],
                ["Near-miss bars", str(near_count), "Barres proches d'un signal mais bloquées par au moins un gate."],
                ["Best one-factor candidate", str(best_candidate.get("Variant", "None")) if not best_candidate.empty else "None", "Meilleure relaxation one-factor si active return exposé positif."],
                ["Best exposed active return", _format_pct(best_candidate.get("Exposed active return", np.nan)) if not best_candidate.empty else "N/A", "Active return sur les barres exposées du meilleur candidat."],
                ["Decision", decision, "Décision de recherche V4.5."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        actions = pd.DataFrame(
            [
                ["P0", "Do not OOS yet", "V4.5 is research only", "OOS interdit tant qu'aucune réparation one-factor n'a été validée par active return exposé positif."],
                ["P0", "Do not promote", "Coverage diagnostic only", "Ne pas promouvoir une mutation depuis V4.5 directement."],
                ["P0", "Reject blind coverage", "Coverage alone is not edge", "Augmenter la couverture uniquement si les barres exposées battent le benchmark."],
                ["P1", "Prepare V4.6 if candidate exists", "One-factor candidate with positive exposed active return", "Runner contrôlé V4.6 uniquement sur les candidats V4.5 propres."],
                ["P1", "Return to source redesign if rejected", "Coverage repair negative or blocked", "Revenir V3.9/V4.0 source candidate si l'exposition réparée reste active-negative."],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        cards = [
            {"label": "V4.5 coverage map", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Engine coverage", "value": _format_pct(current_coverage, 0), "delta": f"{engine_active_bars} bars"},
            {"label": "Eligible bars", "value": str(eligible_bars), "delta": "pre-shift"},
            {"label": "Near-miss bars", "value": str(near_count), "delta": "blocked candidates"},
            {"label": "Best candidate", "value": str(best_candidate.get("Variant", "None")) if not best_candidate.empty else "None", "delta": "one-factor"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "read": read,
            "cards": cards,
            "summary": summary,
            "filter_table": filter_table,
            "near_miss": near_miss,
            "variant_table": variant_table,
            "actions": actions,
            "decision": decision,
            "brt_pack": brt_pack,
            "best_candidate": best_candidate.to_dict() if not best_candidate.empty else {},
        }

    except Exception as exc:
        out = empty.copy()
        out["enabled"] = True
        out["level"] = "Diagnostic error"
        out["score"] = 0.0
        out["read"] = f"Erreur V4.5 : {exc}"
        out["summary"] = pd.DataFrame(
            [["Error", str(exc), "Erreur capturée sans interrompre le backtest."]],
            columns=["Metric", "Value", "Read"],
        )
        return out


def _v45_display_filter_table(table: pd.DataFrame) -> pd.DataFrame:
    if table is None or not isinstance(table, pd.DataFrame) or table.empty:
        return pd.DataFrame()
    out = table.copy()
    for col in ["Pass rate", "Block rate"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_pct(x))
    return out


