def _v46_extract_context(args, kwargs) -> dict[str, Any]:
    """
    Extraction robuste du contexte courant.
    Compatible avec les appels nommés du render principal.
    """
    try:
        if callable(globals().get("_v44b_extract_kwargs")):
            kw = _v44b_extract_kwargs(args, kwargs)
        else:
            kw = dict(kwargs or {})
    except Exception:
        kw = dict(kwargs or {})

    out = dict(kw or {})

    for key in ["df", "cfg", "ticker", "bt", "trades", "metrics", "current_metrics"]:
        if key in kwargs:
            out[key] = kwargs.get(key)

    out["v44_pack"] = kwargs.get("v44_pack", out.get("v44_pack", {}))
    out["v45_pack"] = kwargs.get("v45_pack", out.get("v45_pack", {}))

    return out


def _v46_make_cfg(cfg, changes: dict | None = None):
    try:
        if callable(globals().get("_v45_make_cfg")):
            return _v45_make_cfg(cfg, changes or {})
        if callable(globals().get("_v44b_make_cfg_copy")):
            return _v44b_make_cfg_copy(cfg, changes or {})
        base = dict(getattr(cfg, "__dict__", {}))
        base.update({k: v for k, v in dict(changes or {}).items() if k in base})
        return BacktestConfig(**base)
    except Exception:
        return cfg


def _v46_compound_return(series: Any) -> float:
    try:
        s = (
            pd.to_numeric(series, errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .fillna(0.0)
        )
        if len(s) == 0:
            return np.nan
        return float((1.0 + s).prod() - 1.0)
    except Exception:
        return np.nan


def _v46_condition_stats(frame: pd.DataFrame, mask: pd.Series, label: str) -> dict[str, Any]:
    """
    Mesure research d'une condition source.
    Important : utilise des forward returns historiques uniquement pour router les hypothèses,
    pas pour valider une stratégie ni modifier le moteur.
    """
    try:
        if frame is None or frame.empty:
            return {
                "Sample": 0,
                "Coverage": 0.0,
                "Avg active 5B": np.nan,
                "Avg active 10B": np.nan,
                "Avg active 20B": np.nan,
                "Hit 10B": np.nan,
                "Hit 20B": np.nan,
            }

        m = pd.Series(mask, index=frame.index).fillna(False).astype(bool)
        n = max(len(frame), 1)
        sample = int(m.sum())

        if sample <= 0:
            return {
                "Sample": 0,
                "Coverage": 0.0,
                "Avg active 5B": np.nan,
                "Avg active 10B": np.nan,
                "Avg active 20B": np.nan,
                "Hit 10B": np.nan,
                "Hit 20B": np.nan,
            }

        def _avg(col: str) -> float:
            if col not in frame.columns:
                return np.nan
            x = (
                pd.to_numeric(frame.loc[m, col], errors="coerce")
                .replace([np.inf, -np.inf], np.nan)
                .dropna()
            )
            return float(x.mean()) if not x.empty else np.nan

        def _hit(col: str) -> float:
            if col not in frame.columns:
                return np.nan
            x = (
                pd.to_numeric(frame.loc[m, col], errors="coerce")
                .replace([np.inf, -np.inf], np.nan)
                .dropna()
            )
            return float((x > 0).mean()) if not x.empty else np.nan

        return {
            "Sample": sample,
            "Coverage": sample / n,
            "Avg active 5B": _avg("active_fwd_5b"),
            "Avg active 10B": _avg("active_fwd_10b"),
            "Avg active 20B": _avg("active_fwd_20b"),
            "Hit 10B": _hit("active_fwd_10b"),
            "Hit 20B": _hit("active_fwd_20b"),
        }

    except Exception:
        return {
            "Sample": 0,
            "Coverage": 0.0,
            "Avg active 5B": np.nan,
            "Avg active 10B": np.nan,
            "Avg active 20B": np.nan,
            "Hit 10B": np.nan,
            "Hit 20B": np.nan,
        }


def _v46_score_source(stats: dict[str, Any], prior: float = 0.0) -> float:
    """
    Score research, pas score de performance.
    Récompense : échantillon suffisant, active return forward positif, hit rate positif.
    Pénalise : sample trop faible.
    """
    try:
        sample = int(stats.get("Sample", 0) or 0)
        coverage = _safe_float(stats.get("Coverage"), 0.0)
        avg10 = _safe_float(stats.get("Avg active 10B"), np.nan)
        avg20 = _safe_float(stats.get("Avg active 20B"), np.nan)
        hit10 = _safe_float(stats.get("Hit 10B"), np.nan)
        hit20 = _safe_float(stats.get("Hit 20B"), np.nan)

        score = 35.0 + float(prior)

        if sample >= 8:
            score += 8.0
        elif sample >= 4:
            score += 3.0
        elif sample > 0:
            score -= 10.0
        else:
            score -= 25.0

        if pd.notna(avg10):
            score += avg10 * 450.0
        if pd.notna(avg20):
            score += avg20 * 300.0

        if pd.notna(hit10):
            score += (hit10 - 0.50) * 30.0
        if pd.notna(hit20):
            score += (hit20 - 0.50) * 20.0

        if coverage > 0.35:
            score -= 6.0  # trop proche d'un pseudo buy-and-hold
        if coverage < 0.01 and sample > 0:
            score -= 6.0

        return max(0.0, min(100.0, float(score)))

    except Exception:
        return 0.0


def _v46_market_source_frame(df: pd.DataFrame, cfg: BacktestConfig, ticker: str = "") -> dict[str, Any]:
    """
    Construit une frame research pour router les nouvelles familles de source.
    Lecture seule.
    """
    empty = {
        "available": False,
        "frame": pd.DataFrame(),
        "benchmark_label": "N/A",
        "benchmark_fallback": True,
        "reason": "V4.6 market frame unavailable.",
    }

    try:
        if df is None or cfg is None:
            return empty

        work = _extract_ohlc(df) if callable(globals().get("_extract_ohlc")) else df.copy()

        if work is None or work.empty or "close" not in work.columns:
            return empty

        close = (
            pd.to_numeric(work["close"], errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .ffill()
            .dropna()
        )

        if close.empty or len(close) < 80:
            out = empty.copy()
            out["reason"] = "Historique insuffisant pour V4.6."
            return out

        work = work.reindex(close.index).copy()

        bench_cfg = cfg
        if not str(getattr(cfg, "benchmark_ticker", "") or "").strip():
            asset_ticker = str(ticker or getattr(cfg, "asset_ticker", "") or "").upper().strip()
            auto_symbol = _sector_benchmark_guess(asset_ticker) if asset_ticker else "SPY"
            bench_cfg = _v46_make_cfg(
                cfg,
                {
                    "benchmark_ticker": auto_symbol,
                    "benchmark_label": f"Auto Sector ETF ({auto_symbol})",
                    "benchmark_mode": "Sector ETF",
                },
            )

        benchmark_returns, benchmark_label, benchmark_fallback = _load_benchmark_returns(work, bench_cfg)

        benchmark_returns = (
            pd.to_numeric(benchmark_returns.reindex(close.index), errors="coerce")
            .replace([np.inf, -np.inf], np.nan)
            .fillna(0.0)
        )

        asset_returns = close.pct_change().fillna(0.0)

        asset_nav = (1.0 + asset_returns).cumprod()
        benchmark_nav = (1.0 + benchmark_returns).cumprod()

        frame = pd.DataFrame(index=close.index)
        frame["close"] = close
        frame["asset_return"] = asset_returns
        frame["benchmark_return"] = benchmark_returns
        frame["active_return"] = asset_returns - benchmark_returns
        frame["asset_nav"] = asset_nav
        frame["benchmark_nav"] = benchmark_nav
        frame["active_nav"] = asset_nav / benchmark_nav.replace(0.0, np.nan) - 1.0

        for h in [3, 5, 10, 20, 40, 60]:
            frame[f"asset_ret_{h}b"] = close.pct_change(h)
            frame[f"bench_ret_{h}b"] = benchmark_nav.pct_change(h)
            frame[f"active_ret_{h}b"] = frame[f"asset_ret_{h}b"] - frame[f"bench_ret_{h}b"]

        for h in [5, 10, 20]:
            frame[f"asset_fwd_{h}b"] = close.shift(-h) / close - 1.0
            frame[f"bench_fwd_{h}b"] = benchmark_nav.shift(-h) / benchmark_nav - 1.0
            frame[f"active_fwd_{h}b"] = frame[f"asset_fwd_{h}b"] - frame[f"bench_fwd_{h}b"]

        frame["ma_20"] = close.rolling(20).mean()
        frame["ma_50"] = close.rolling(50).mean()
        frame["ma_100"] = close.rolling(100).mean()

        frame["high_20"] = close.shift(1).rolling(20).max()
        frame["high_60"] = close.shift(1).rolling(60).max()
        frame["low_20"] = close.shift(1).rolling(20).min()
        frame["low_60"] = close.shift(1).rolling(60).min()

        frame["price_breakout_20"] = close > frame["high_20"]
        frame["price_breakout_60"] = close > frame["high_60"]

        frame["bench_ma_50"] = benchmark_nav.rolling(50).mean()
        frame["bench_ma_100"] = benchmark_nav.rolling(100).mean()
        frame["benchmark_trend_50"] = benchmark_nav > frame["bench_ma_50"]
        frame["benchmark_trend_100"] = benchmark_nav > frame["bench_ma_100"]

        frame["realized_vol_20"] = asset_returns.rolling(20).std() * np.sqrt(252)

        try:
            frame["vol_rank_126"] = frame["realized_vol_20"].rolling(126, min_periods=30).apply(
                lambda x: pd.Series(x).rank(pct=True).iloc[-1],
                raw=False,
            )
        except Exception:
            frame["vol_rank_126"] = np.nan

        frame["squeeze_proxy"] = (
            (pd.to_numeric(frame["vol_rank_126"], errors="coerce") <= 0.35)
            & (close > frame["ma_50"])
        )

        rolling_peak_60 = close.rolling(60, min_periods=20).max()
        frame["drawdown_60"] = close / rolling_peak_60.replace(0.0, np.nan) - 1.0
        frame["drawdown_reversal_proxy"] = (
            (frame["drawdown_60"] <= -0.08)
            & (frame["asset_ret_5b"] > 0.0)
            & (frame["active_ret_5b"] > -0.01)
        )

        open_ = (
            pd.to_numeric(work.get("open", close), errors="coerce")
            .reindex(close.index)
            .fillna(close)
        )

        frame["open_gap"] = open_ / close.shift(1).replace(0.0, np.nan) - 1.0

        volume = pd.to_numeric(work.get("volume", pd.Series(np.nan, index=work.index)), errors="coerce").reindex(close.index)

        if volume.notna().sum() >= 30:
            vol_mean = volume.rolling(60, min_periods=20).mean()
            vol_std = volume.rolling(60, min_periods=20).std()
            frame["volume_z"] = (volume - vol_mean) / vol_std.replace(0.0, np.nan)
        else:
            frame["volume_z"] = np.nan

        frame["event_proxy"] = (
            (frame["open_gap"].abs() >= 0.025)
            | (pd.to_numeric(frame["volume_z"], errors="coerce") >= 2.0)
        )

        frame["regime_acceleration_proxy"] = (
            (frame["active_ret_5b"] > 0.0)
            & (frame["active_ret_20b"] > frame["active_ret_60b"])
            & (frame["asset_ret_10b"] > 0.0)
        )

        frame["sector_rotation_proxy"] = (
            frame["benchmark_trend_50"].fillna(False)
            & (frame["active_ret_5b"] > 0.0)
            & (frame["active_ret_20b"] > -0.02)
        )

        frame["benchmark_pullback_proxy"] = (
            frame["benchmark_trend_50"].fillna(False)
            & (frame["active_ret_20b"] < 0.0)
            & (frame["drawdown_60"] > -0.12)
            & (close > frame["ma_100"])
        )

        frame["relative_breakout_proxy"] = (
            (frame["price_breakout_20"].fillna(False) | frame["price_breakout_60"].fillna(False))
            & (frame["active_ret_5b"] > -0.01)
        )

        return {
            "available": True,
            "frame": frame.replace([np.inf, -np.inf], np.nan),
            "benchmark_label": benchmark_label,
            "benchmark_fallback": bool(benchmark_fallback),
            "reason": "OK",
        }

    except Exception as exc:
        out = empty.copy()
        out["reason"] = f"V4.6 market frame error: {exc}"
        return out


def _v46_source_queue(frame_pack: dict[str, Any], v45_pack: dict[str, Any]) -> tuple[pd.DataFrame, pd.DataFrame]:
    """
    Construit la queue de sources à tester ensuite.
    """
    try:
        frame = frame_pack.get("frame", pd.DataFrame()) if isinstance(frame_pack, dict) else pd.DataFrame()
        if frame is None or not isinstance(frame, pd.DataFrame) or frame.empty:
            return pd.DataFrame(), pd.DataFrame()

        v45_decision = str(v45_pack.get("decision", "") if isinstance(v45_pack, dict) else "")
        v45_level = str(v45_pack.get("level", "") if isinstance(v45_pack, dict) else "")

        coverage_rejected = "REJECT_COVERAGE_REPAIR" in v45_decision or "Coverage rejected" in v45_level

        hypotheses = [
            {
                "Source family": "Relative breakout",
                "Condition": frame["relative_breakout_proxy"],
                "Why": "Remplacer le slow relative trend par un déclencheur de cassure relative plus réactif.",
                "V4.7 test": "Relative breakout source micro-runner",
                "Prior": 10.0 if coverage_rejected else 5.0,
                "Risk": "Peut acheter des faux breakouts si volume/régime non confirmé.",
            },
            {
                "Source family": "Regime acceleration",
                "Condition": frame["regime_acceleration_proxy"],
                "Why": "Chercher les phases où l'actif accélère déjà vs benchmark au lieu d'attendre une confirmation slow trop tardive.",
                "V4.7 test": "Active acceleration source micro-runner",
                "Prior": 9.0 if coverage_rejected else 5.0,
                "Risk": "Risque de chasing si l'accélération est déjà épuisée.",
            },
            {
                "Source family": "Volatility squeeze",
                "Condition": frame["squeeze_proxy"],
                "Why": "Tester compression de volatilité + tendance, utile si les mouvements viennent par expansion brusque.",
                "V4.7 test": "Volatility squeeze source micro-runner",
                "Prior": 6.0 if coverage_rejected else 4.0,
                "Risk": "Peut rester flat longtemps ; risque de faux départ sans expansion.",
            },
            {
                "Source family": "Earnings / event-driven proxy",
                "Condition": frame["event_proxy"] & (frame["active_ret_3b"] > -0.02),
                "Why": "Si le titre bouge par catalyseurs, une source price-only lente est mal adaptée.",
                "V4.7 test": "Event proxy source micro-runner",
                "Prior": 7.0 if coverage_rejected else 3.0,
                "Risk": "Proxy incomplet sans vraies dates earnings/news ; nécessite contrôle anti-lookahead.",
            },
            {
                "Source family": "Drawdown reversal",
                "Condition": frame["drawdown_reversal_proxy"],
                "Why": "Tester rebond après drawdown contrôlé quand le trend relatif classique ne capte pas les reprises.",
                "V4.7 test": "Drawdown reversal source micro-runner",
                "Prior": 2.0,
                "Risk": "Peut acheter des couteaux qui tombent si le régime se détériore.",
            },
            {
                "Source family": "Sector rotation",
                "Condition": frame["sector_rotation_proxy"],
                "Why": "Tester participation à un secteur porteur plutôt qu'une surperformance absolue slow.",
                "V4.7 test": "Sector participation source micro-runner",
                "Prior": 1.0,
                "Risk": "Peut devenir trop proche d'un benchmark sectoriel.",
            },
            {
                "Source family": "Benchmark-relative pullback",
                "Condition": frame["benchmark_pullback_proxy"],
                "Why": "Alternative contrariante : entrer quand l'actif corrige dans un benchmark encore haussier.",
                "V4.7 test": "Relative pullback source micro-runner",
                "Prior": -2.0 if coverage_rejected else 0.0,
                "Risk": "V4.5 a déjà rejeté la réparation de couverture ; piste secondaire seulement.",
            },
            {
                "Source family": "Current BRT continuation",
                "Condition": (frame["active_ret_20b"] > 0.0) & (frame["active_ret_60b"] > 0.0) & frame["benchmark_trend_50"].fillna(False),
                "Why": "Source actuelle proche : à garder comme témoin, pas comme priorité.",
                "V4.7 test": "Control only / no priority",
                "Prior": -12.0 if coverage_rejected else -4.0,
                "Risk": "Déjà bloqué par V4.5 : dual/core trop strict et coverage repair négatif.",
            },
        ]

        rows = []

        for h in hypotheses:
            stats = _v46_condition_stats(frame, h["Condition"], h["Source family"])
            score = _v46_score_source(stats, prior=float(h.get("Prior", 0.0)))

            if int(stats.get("Sample", 0) or 0) <= 0:
                decision = "LOW PRIORITY"
            elif score >= 60:
                decision = "V4.7 CANDIDATE"
            elif score >= 45:
                decision = "WATCH"
            else:
                decision = "LOW PRIORITY"

            rows.append(
                {
                    "Priority score": score,
                    "Decision": decision,
                    "Source family": h["Source family"],
                    "Sample": int(stats.get("Sample", 0) or 0),
                    "Coverage": stats.get("Coverage", np.nan),
                    "Avg active 5B": stats.get("Avg active 5B", np.nan),
                    "Avg active 10B": stats.get("Avg active 10B", np.nan),
                    "Avg active 20B": stats.get("Avg active 20B", np.nan),
                    "Hit 10B": stats.get("Hit 10B", np.nan),
                    "Hit 20B": stats.get("Hit 20B", np.nan),
                    "Why": h["Why"],
                    "V4.7 test": h["V4.7 test"],
                    "Main risk": h["Risk"],
                }
            )

        queue = pd.DataFrame(rows)

        if not queue.empty:
            queue = queue.sort_values(
                ["Priority score", "Sample", "Avg active 10B"],
                ascending=[False, False, False],
            ).reset_index(drop=True)

        rejected = pd.DataFrame(
            [
                [
                    "Coverage repair",
                    "Rejected",
                    "V4.5 showed coverage can be increased but exposed active return stays negative.",
                    "Do not force more exposure.",
                ],
                [
                    "Benchmark-relative slow trend",
                    "Rejected as primary",
                    "Slow active momentum / dual-core condition blocks the source.",
                    "Keep only as control benchmark.",
                ],
                [
                    "Exits / sizing optimization",
                    "Blocked",
                    "The source is not producing valid positive exposure.",
                    "Do not tune exits/sizing before source edge.",
                ],
                [
                    "OOS",
                    "Blocked",
                    "No validated source candidate yet.",
                    "OOS only after V4.7/V4.8 candidate passes source diagnostics.",
                ],
                [
                    "Promotion / live",
                    "Blocked",
                    "All V4.x blocks are research-only.",
                    "No promotion from V4.6.",
                ],
            ],
            columns=["Track", "Status", "Reason", "Action"],
        )

        return queue, rejected

    except Exception:
        return pd.DataFrame(), pd.DataFrame()


def _source_redesign_router_v46_pack(*args, **kwargs) -> dict[str, Any]:
    """
    V4.6 — Source Redesign Router / Source Hypothesis Queue.

    Lecture seule :
    - ne modifie pas cfg ;
    - ne modifie pas le moteur ;
    - ne modifie pas l'equity curve ;
    - ne promeut aucune mutation ;
    - transforme V4.5 en queue de recherche V4.7.
    """
    ctx = _v46_extract_context(args, kwargs)

    df = ctx.get("df", None)
    cfg = ctx.get("cfg", None)
    ticker = str(ctx.get("ticker", "") or "")
    v44_pack = ctx.get("v44_pack", {})
    v45_pack = ctx.get("v45_pack", {})

    if (not isinstance(v45_pack, dict) or not v45_pack) and isinstance(v44_pack, dict):
        v45_pack = v44_pack.get("coverage_without_overfit_v45", {})

    empty = {
        "enabled": False,
        "level": "Unavailable",
        "score": 0.0,
        "decision": "NO_DECISION",
        "read": "V4.6 indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "source_queue": pd.DataFrame(),
        "rejected_tracks": pd.DataFrame(),
        "evidence": pd.DataFrame(),
        "blueprint": pd.DataFrame(),
        "actions": pd.DataFrame(),
    }

    try:
        if df is None or cfg is None:
            out = empty.copy()
            out["read"] = "df/cfg manquant pour V4.6."
            return out

        market_pack = _v46_market_source_frame(df, cfg, ticker=ticker)
        frame = market_pack.get("frame", pd.DataFrame())

        source_queue, rejected_tracks = _v46_source_queue(market_pack, v45_pack if isinstance(v45_pack, dict) else {})

        top = pd.Series(dtype=object)
        if isinstance(source_queue, pd.DataFrame) and not source_queue.empty:
            top = source_queue.iloc[0]

        top_family = str(top.get("Source family", "None")) if not top.empty else "None"
        top_score = _safe_float(top.get("Priority score"), 0.0) if not top.empty else 0.0
        top_decision = str(top.get("Decision", "NO CANDIDATE")) if not top.empty else "NO CANDIDATE"

        v45_decision = str(v45_pack.get("decision", "N/A")) if isinstance(v45_pack, dict) else "N/A"
        v45_level = str(v45_pack.get("level", "N/A")) if isinstance(v45_pack, dict) else "N/A"

        if top_score >= 60 and top_decision == "V4.7 CANDIDATE":
            level = "Source redesign candidate"
            decision = "PREPARE_V47_SOURCE_MICRO_RUNNER"
            score = min(75.0, top_score)
            read = (
                f"V4.6 route vers {top_family}. La couverture BRT est rejetée ; "
                "la prochaine étape doit tester une nouvelle source, pas optimiser exits/sizing."
            )
        elif top_score >= 45:
            level = "Source redesign watchlist"
            decision = "BUILD_V47_CONSERVATIVE_SOURCE_TEST"
            score = top_score
            read = (
                f"V4.6 identifie {top_family} comme meilleure piste relative, mais le signal reste à tester prudemment."
            )
        else:
            level = "Source redesign required"
            decision = "REBUILD_SOURCE_LAYER"
            score = max(20.0, top_score)
            read = (
                "Aucune famille de source ne ressort assez proprement. Il faut reconstruire la couche source "
                "plutôt que forcer le coverage ou le sizing."
            )

        evidence_rows = []

        if isinstance(frame, pd.DataFrame) and not frame.empty:
            evidence_rows = [
                [
                    "Market rows",
                    str(len(frame)),
                    "Nombre de barres disponibles pour router les hypothèses.",
                ],
                [
                    "Benchmark",
                    str(market_pack.get("benchmark_label", "N/A")),
                    "Benchmark utilisé pour les active returns.",
                ],
                [
                    "Benchmark fallback",
                    str(bool(market_pack.get("benchmark_fallback", True))),
                    "Si True, la lecture relative est moins fiable.",
                ],
                [
                    "Current V4.5 decision",
                    v45_decision,
                    "Décision issue du diagnostic coverage.",
                ],
                [
                    "Current V4.5 level",
                    v45_level,
                    "Niveau V4.5.",
                ],
                [
                    "Relative breakout samples",
                    str(int(pd.Series(frame.get("relative_breakout_proxy", False), index=frame.index).fillna(False).astype(bool).sum())),
                    "Nombre de barres détectées par le proxy relative breakout.",
                ],
                [
                    "Regime acceleration samples",
                    str(int(pd.Series(frame.get("regime_acceleration_proxy", False), index=frame.index).fillna(False).astype(bool).sum())),
                    "Nombre de barres détectées par le proxy acceleration.",
                ],
                [
                    "Volatility squeeze samples",
                    str(int(pd.Series(frame.get("squeeze_proxy", False), index=frame.index).fillna(False).astype(bool).sum())),
                    "Nombre de barres détectées par le proxy squeeze.",
                ],
                [
                    "Event proxy samples",
                    str(int(pd.Series(frame.get("event_proxy", False), index=frame.index).fillna(False).astype(bool).sum())),
                    "Nombre de barres détectées par gap/volume proxy.",
                ],
            ]

        evidence = pd.DataFrame(evidence_rows, columns=["Evidence", "Value", "Read"])

        blueprint = pd.DataFrame(
            [
                [
                    "V4.7 objective",
                    "Source micro-runner",
                    "Tester 3 à 5 variantes de la meilleure famille source, en lecture seule.",
                ],
                [
                    "Primary family",
                    top_family,
                    "Famille prioritaire selon V4.6.",
                ],
                [
                    "Primary rule",
                    str(top.get("V4.7 test", "N/A")) if not top.empty else "N/A",
                    "Bloc V4.7 recommandé.",
                ],
                [
                    "Allowed mutation type",
                    "source-only / one-family",
                    "Ne pas mélanger source + exits + sizing.",
                ],
                [
                    "Validation condition",
                    "exposed active return > 0 and enough active bars",
                    "Même logique que V4.5 : pas seulement plus de trades.",
                ],
                [
                    "Still forbidden",
                    "OOS / promotion / live / exits / sizing",
                    "Interdit tant que la source n'a pas passé V4.7/V4.8.",
                ],
            ],
            columns=["Item", "Value", "Read"],
        )

        actions = pd.DataFrame(
            [
                [
                    "P0",
                    "Do not OOS",
                    "Source not validated",
                    "OOS seulement après un candidat source positif et non-overfit.",
                ],
                [
                    "P0",
                    "Do not promote",
                    "V4.6 is a router",
                    "Aucune mutation ne doit être promue depuis V4.6.",
                ],
                [
                    "P0",
                    "Do not tune exits/sizing",
                    "Failure is source-level",
                    "Le problème n'est pas encore la sortie ou la taille de position.",
                ],
                [
                    "P1",
                    "Build V4.7 source micro-runner",
                    f"Best route: {top_family}",
                    "Tester uniquement la famille source prioritaire.",
                ],
                [
                    "P1",
                    "Keep current BRT as control",
                    "BRT failed but remains a useful benchmark",
                    "Comparer les nouvelles sources contre BRT, pas l'effacer.",
                ],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        summary = pd.DataFrame(
            [
                ["V4.6 level", level, "Lecture synthétique du router de source."],
                ["V4.6 score", f"{_format_num(score, 0)}/100", "Score research explicatif, pas score de performance."],
                ["Decision", decision, "Décision de recherche V4.6."],
                ["Read", read, "Interprétation opérationnelle."],
                ["Ticker", ticker or "N/A", "Ticker audité."],
                ["V4.5 decision", v45_decision, "Décision coverage précédente."],
                ["Top source family", top_family, "Famille source prioritaire."],
                ["Top source score", f"{_format_num(top_score, 0)}/100", "Score de priorité research."],
                ["Top V4.7 test", str(top.get("V4.7 test", "N/A")) if not top.empty else "N/A", "Bloc suivant recommandé."],
                ["Benchmark", str(market_pack.get("benchmark_label", "N/A")), "Benchmark relatif utilisé."],
                ["Benchmark fallback", str(bool(market_pack.get("benchmark_fallback", True))), "Qualité du benchmark."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        cards = [
            {"label": "V4.6 router", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Top source", "value": top_family, "delta": "V4.7 route"},
            {"label": "Top score", "value": f"{_format_num(top_score, 0)}/100", "delta": top_decision},
            {"label": "V4.5 input", "value": v45_decision, "delta": "coverage result"},
            {"label": "Next block", "value": decision, "delta": "research only"},
            {"label": "Do not promote", "value": "PASS", "delta": "no engine impact"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "source_queue": source_queue,
            "rejected_tracks": rejected_tracks,
            "evidence": evidence,
            "blueprint": blueprint,
            "actions": actions,
            "market_pack": market_pack,
            "top_source_family": top_family,
        }

    except Exception as exc:
        out = empty.copy()
        out["enabled"] = True
        out["level"] = "Diagnostic error"
        out["score"] = 0.0
        out["decision"] = "ERROR"
        out["read"] = f"Erreur V4.6 : {exc}"
        out["summary"] = pd.DataFrame(
            [["Error", str(exc), "Erreur capturée sans interrompre le backtest."]],
            columns=["Metric", "Value", "Read"],
        )
        return out


def _v46_display_source_queue(table: pd.DataFrame) -> pd.DataFrame:
    if table is None or not isinstance(table, pd.DataFrame) or table.empty:
        return pd.DataFrame()

    out = table.copy()

    if "Priority score" in out.columns:
        out["Priority score"] = out["Priority score"].map(lambda x: _format_num(x, 0))

    for col in [
        "Coverage",
        "Avg active 5B",
        "Avg active 10B",
        "Avg active 20B",
        "Hit 10B",
        "Hit 20B",
    ]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_pct(x))

    return out


def _render_source_redesign_router_v46(*args, **kwargs) -> dict[str, Any]:
    pack = _source_redesign_router_v46_pack(*args, **kwargs)

    st.subheader("Source Redesign Router V4.6")
    st.caption(
        "Router lecture seule après V4.5 : transforme le rejet du coverage repair en file d'hypothèses source. "
        "Classe les familles de source à tester ensuite : relative breakout, regime acceleration, volatility squeeze, "
        "event-driven proxy, drawdown reversal, sector rotation et pullback relatif. "
        "Aucun impact sur le moteur courant, l'equity curve, les trades ou le verdict."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))

    if "candidate" in level.lower():
        st.warning(f"Lecture V4.6 : {read}")
    elif "required" in level.lower() or "error" in level.lower():
        st.error(f"Lecture V4.6 : {read}")
    else:
        st.info(f"Lecture V4.6 : {read}")

    with st.expander("V4.6 source redesign summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.6 indisponible.")

    with st.expander("V4.6 source hypothesis queue", expanded=True):
        queue = _v46_display_source_queue(pack.get("source_queue", pd.DataFrame()))
        if isinstance(queue, pd.DataFrame) and not queue.empty:
            st.dataframe(queue, use_container_width=True, hide_index=True)
        else:
            st.info("Source hypothesis queue indisponible.")

    with st.expander("V4.6 rejected tracks", expanded=True):
        rejected = pack.get("rejected_tracks", pd.DataFrame())
        if isinstance(rejected, pd.DataFrame) and not rejected.empty:
            st.dataframe(rejected, use_container_width=True, hide_index=True)
        else:
            st.info("Rejected tracks indisponibles.")

    with st.expander("V4.6 evidence map", expanded=False):
        evidence = pack.get("evidence", pd.DataFrame())
        if isinstance(evidence, pd.DataFrame) and not evidence.empty:
            st.dataframe(evidence, use_container_width=True, hide_index=True)
        else:
            st.info("Evidence map indisponible.")

    with st.expander("V4.7 recommended blueprint", expanded=True):
        blueprint = pack.get("blueprint", pd.DataFrame())
        if isinstance(blueprint, pd.DataFrame) and not blueprint.empty:
            st.dataframe(blueprint, use_container_width=True, hide_index=True)
        else:
            st.info("Blueprint V4.7 indisponible.")

    with st.expander("V4.6 next controlled actions", expanded=True):
        actions = pack.get("actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.6 indisponibles.")

    return pack


# Wrapper : on garde V4.4b + V4.5 intacts et on ajoute V4.6 juste après.
if "_V45_RENDER_BASE_FOR_V46" not in globals():
    _V45_RENDER_BASE_FOR_V46 = _render_mutation_trade_failure_decomposition_v44


def _render_mutation_trade_failure_decomposition_v44(*args, **kwargs):
    v44_pack = _V45_RENDER_BASE_FOR_V46(*args, **kwargs)

    try:
        v45_pack = {}
        if isinstance(v44_pack, dict):
            v45_pack = v44_pack.get("coverage_without_overfit_v45", {})

        v46_kwargs = dict(kwargs)
        v46_kwargs["v44_pack"] = v44_pack
        v46_kwargs["v45_pack"] = v45_pack

        v46_pack = _render_source_redesign_router_v46(*args, **v46_kwargs)

        if isinstance(v44_pack, dict):
            v44_pack["source_redesign_router_v46"] = v46_pack

    except Exception as exc:
        st.warning(f"V4.6 Source Redesign Router indisponible : {exc}")

    return v44_pack

