def _v47_scan_primitive(frame: pd.DataFrame, spec: dict[str, Any]) -> dict[str, Any]:
    """
    Calcule la qualité brute d'une primitive.
    Ce n'est pas une stratégie : pas de sizing, pas d'exit, pas de promotion.
    """
    try:
        idx = frame.index
        mask = _v47_safe_bool(spec.get("Condition", False), idx)
        sample = int(mask.sum())
        coverage = sample / max(len(frame), 1)

        row = {
            "Family": str(spec.get("Family", "N/A")),
            "Primitive": str(spec.get("Primitive", "N/A")),
            "Decision": "REJECT",
            "Sample": sample,
            "Coverage": coverage,
            "Avg active 3B": np.nan,
            "Avg active 5B": np.nan,
            "Avg active 10B": np.nan,
            "Avg active 20B": np.nan,
            "Median active 10B": np.nan,
            "Median active 20B": np.nan,
            "Worst active 10B": np.nan,
            "Worst active 20B": np.nan,
            "Hit 3B": np.nan,
            "Hit 5B": np.nan,
            "Hit 10B": np.nan,
            "Hit 20B": np.nan,
            "Stability": np.nan,
            "Raw alpha score": 0.0,
            "Rationale": str(spec.get("Rationale", "")),
            "Overfit risk": str(spec.get("Overfit risk", "Medium")),
        }

        if sample <= 0:
            row["Decision"] = "NO_SAMPLE"
            return row

        positive_horizons = 0
        measurable_horizons = 0

        for h in [3, 5, 10, 20]:
            col = f"active_fwd_{h}b"

            if col not in frame.columns:
                continue

            x = (
                pd.to_numeric(frame.loc[mask, col], errors="coerce")
                .replace([np.inf, -np.inf], np.nan)
                .dropna()
            )

            if x.empty:
                continue

            measurable_horizons += 1

            avg = float(x.mean())
            med = float(x.median())
            worst = float(x.min())
            hit = float((x > 0.0).mean())

            row[f"Avg active {h}B"] = avg
            row[f"Hit {h}B"] = hit

            if h in [10, 20]:
                row[f"Median active {h}B"] = med
                row[f"Worst active {h}B"] = worst

            if avg > 0.0 and hit >= 0.50:
                positive_horizons += 1

        stability = positive_horizons / max(measurable_horizons, 1)
        row["Stability"] = stability

        score = 30.0

        if sample >= 20:
            score += 10.0
        elif sample >= 10:
            score += 6.0
        elif sample >= 5:
            score += 1.0
        else:
            score -= 12.0

        if coverage > 0.45:
            score -= 12.0
        elif coverage > 0.30:
            score -= 6.0
        elif 0.03 <= coverage <= 0.25:
            score += 4.0

        avg5 = _safe_float(row.get("Avg active 5B"), np.nan)
        avg10 = _safe_float(row.get("Avg active 10B"), np.nan)
        avg20 = _safe_float(row.get("Avg active 20B"), np.nan)

        hit10 = _safe_float(row.get("Hit 10B"), np.nan)
        hit20 = _safe_float(row.get("Hit 20B"), np.nan)

        if pd.notna(avg5):
            score += avg5 * 250.0
        if pd.notna(avg10):
            score += avg10 * 350.0
        if pd.notna(avg20):
            score += avg20 * 250.0

        if pd.notna(hit10):
            score += (hit10 - 0.50) * 30.0
        if pd.notna(hit20):
            score += (hit20 - 0.50) * 20.0

        score += stability * 18.0

        worst10 = _safe_float(row.get("Worst active 10B"), np.nan)
        worst20 = _safe_float(row.get("Worst active 20B"), np.nan)

        if pd.notna(worst10) and worst10 < -0.10:
            score -= 6.0
        if pd.notna(worst20) and worst20 < -0.15:
            score -= 8.0

        risk = str(spec.get("Overfit risk", "Medium"))

        if risk == "High":
            score -= 8.0
        elif risk == "Medium":
            score -= 3.0

        score = max(0.0, min(100.0, float(score)))
        row["Raw alpha score"] = score

        if sample < 8:
            row["Decision"] = "LOW_SAMPLE"
        elif score >= 62 and pd.notna(avg10) and avg10 > 0 and pd.notna(avg20) and avg20 > 0 and stability >= 0.50:
            row["Decision"] = "RAW_ALPHA_CANDIDATE"
        elif score >= 48 and ((pd.notna(avg10) and avg10 > 0) or (pd.notna(avg20) and avg20 > 0)):
            row["Decision"] = "WATCH"
        else:
            row["Decision"] = "REJECT"

        return row

    except Exception as exc:
        return {
            "Family": str(spec.get("Family", "N/A")),
            "Primitive": str(spec.get("Primitive", "N/A")),
            "Decision": "ERROR",
            "Sample": 0,
            "Coverage": 0.0,
            "Avg active 3B": np.nan,
            "Avg active 5B": np.nan,
            "Avg active 10B": np.nan,
            "Avg active 20B": np.nan,
            "Median active 10B": np.nan,
            "Median active 20B": np.nan,
            "Worst active 10B": np.nan,
            "Worst active 20B": np.nan,
            "Hit 3B": np.nan,
            "Hit 5B": np.nan,
            "Hit 10B": np.nan,
            "Hit 20B": np.nan,
            "Stability": np.nan,
            "Raw alpha score": 0.0,
            "Rationale": str(exc),
            "Overfit risk": str(spec.get("Overfit risk", "Medium")),
        }


def _v47_raw_alpha_discovery_table(frame: pd.DataFrame) -> pd.DataFrame:
    try:
        specs = _v47_primitive_specs(frame)
        rows = [_v47_scan_primitive(frame, spec) for spec in specs]
        table = pd.DataFrame(rows)

        if table.empty:
            return table

        table = table.sort_values(
            ["Raw alpha score", "Sample", "Avg active 10B"],
            ascending=[False, False, False],
        ).reset_index(drop=True)

        return table

    except Exception:
        return pd.DataFrame()


def _v47_family_summary(scan: pd.DataFrame) -> pd.DataFrame:
    try:
        if scan is None or not isinstance(scan, pd.DataFrame) or scan.empty:
            return pd.DataFrame()

        rows = []

        for family, grp in scan.groupby("Family"):
            scores = pd.to_numeric(grp["Raw alpha score"], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
            avg10 = pd.to_numeric(grp["Avg active 10B"], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
            avg20 = pd.to_numeric(grp["Avg active 20B"], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()

            candidates = int(grp["Decision"].astype(str).isin(["RAW_ALPHA_CANDIDATE", "WATCH"]).sum())

            rows.append(
                {
                    "Family": family,
                    "Best score": float(scores.max()) if not scores.empty else np.nan,
                    "Avg score": float(scores.mean()) if not scores.empty else np.nan,
                    "Best primitive": str(grp.sort_values("Raw alpha score", ascending=False).iloc[0].get("Primitive", "N/A")),
                    "Candidate / watch count": candidates,
                    "Mean active 10B": float(avg10.mean()) if not avg10.empty else np.nan,
                    "Mean active 20B": float(avg20.mean()) if not avg20.empty else np.nan,
                    "Primitive count": int(len(grp)),
                }
            )

        out = pd.DataFrame(rows)

        if not out.empty:
            out = out.sort_values(
                ["Best score", "Candidate / watch count"],
                ascending=[False, False],
            ).reset_index(drop=True)

        return out

    except Exception:
        return pd.DataFrame()


def _v47_raw_alpha_discovery_pack(*args, **kwargs) -> dict[str, Any]:
    """
    V4.7 — Source Rebuild Lab / Raw Alpha Discovery.

    Lecture seule :
    - ne modifie pas cfg ;
    - ne lance pas de stratégie ;
    - ne modifie pas le moteur ;
    - ne modifie pas l'equity curve ;
    - ne promeut aucun signal ;
    - cherche seulement des conditions primitives avec forward active return positif.
    """
    ctx = _v47_extract_context(args, kwargs)

    df = ctx.get("df", None)
    cfg = ctx.get("cfg", None)
    ticker = str(ctx.get("ticker", "") or "")
    v44_pack = ctx.get("v44_pack", {})
    v46_pack = ctx.get("v46_pack", {})

    if (not isinstance(v46_pack, dict) or not v46_pack) and isinstance(v44_pack, dict):
        v46_pack = v44_pack.get("source_redesign_router_v46", {})

    empty = {
        "enabled": False,
        "level": "Unavailable",
        "score": 0.0,
        "decision": "NO_DECISION",
        "read": "V4.7 indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "raw_alpha_scan": pd.DataFrame(),
        "family_summary": pd.DataFrame(),
        "positive_primitives": pd.DataFrame(),
        "rejected_primitives": pd.DataFrame(),
        "blueprint": pd.DataFrame(),
        "actions": pd.DataFrame(),
    }

    try:
        if df is None or cfg is None:
            out = empty.copy()
            out["read"] = "df/cfg manquant pour V4.7."
            return out

        market_pack = _v47_enrich_market_frame(df, cfg, ticker=ticker)
        frame = market_pack.get("frame", pd.DataFrame())

        scan = _v47_raw_alpha_discovery_table(frame)
        family = _v47_family_summary(scan)

        positive = pd.DataFrame()
        rejected = pd.DataFrame()
        top = pd.Series(dtype=object)

        if isinstance(scan, pd.DataFrame) and not scan.empty:
            positive = scan[scan["Decision"].astype(str).isin(["RAW_ALPHA_CANDIDATE", "WATCH"])].copy()
            rejected = scan[~scan["Decision"].astype(str).isin(["RAW_ALPHA_CANDIDATE", "WATCH"])].copy()
            top = scan.iloc[0]

        top_primitive = str(top.get("Primitive", "None")) if not top.empty else "None"
        top_family = str(top.get("Family", "None")) if not top.empty else "None"
        top_score = _safe_float(top.get("Raw alpha score"), 0.0) if not top.empty else 0.0
        top_decision = str(top.get("Decision", "NO CANDIDATE")) if not top.empty else "NO CANDIDATE"

        candidate_count = int((scan["Decision"].astype(str) == "RAW_ALPHA_CANDIDATE").sum()) if isinstance(scan, pd.DataFrame) and not scan.empty else 0
        watch_count = int((scan["Decision"].astype(str) == "WATCH").sum()) if isinstance(scan, pd.DataFrame) and not scan.empty else 0
        tested_count = int(len(scan)) if isinstance(scan, pd.DataFrame) else 0

        v46_decision = str(v46_pack.get("decision", "N/A")) if isinstance(v46_pack, dict) else "N/A"
        v46_level = str(v46_pack.get("level", "N/A")) if isinstance(v46_pack, dict) else "N/A"

        if candidate_count > 0 and top_decision == "RAW_ALPHA_CANDIDATE":
            level = "Raw alpha candidate found"
            decision = "PREPARE_V48_PRIMITIVE_SOURCE_MICRO_RUNNER"
            score = min(80.0, max(55.0, top_score))
            read = (
                f"V4.7 détecte une primitive exploitable : {top_primitive}. "
                "Prochaine étape : V4.8 micro-runner source-only, sans exits/sizing/OOS."
            )
        elif watch_count > 0:
            level = "Raw alpha watchlist"
            decision = "REFINE_V47_OR_PREPARE_CONSERVATIVE_V48"
            score = min(60.0, max(40.0, top_score))
            read = (
                f"V4.7 trouve une piste fragile : {top_primitive}. "
                "Elle doit rester en watchlist et ne justifie pas encore une promotion."
            )
        else:
            level = "No raw alpha primitive"
            decision = "SOURCE_DATA_EXPANSION_REQUIRED"
            score = max(10.0, min(40.0, top_score))
            read = (
                "Aucune condition primitive ne montre d'active return forward suffisamment positif. "
                "Il faut enrichir la source de données ou élargir le protocole avant tout OOS."
            )

        summary = pd.DataFrame(
            [
                ["V4.7 level", level, "Lecture synthétique du Raw Alpha Discovery."],
                ["V4.7 score", f"{_format_num(score, 0)}/100", "Score research explicatif, pas score de performance."],
                ["Decision", decision, "Décision de recherche V4.7."],
                ["Read", read, "Interprétation opérationnelle."],
                ["Ticker", ticker or "N/A", "Ticker audité."],
                ["V4.6 input", v46_decision, "Décision précédente du Source Redesign Router."],
                ["V4.6 level", v46_level, "Niveau V4.6."],
                ["Benchmark", str(market_pack.get("benchmark_label", "N/A")), "Benchmark relatif utilisé."],
                ["Benchmark fallback", str(bool(market_pack.get("benchmark_fallback", True))), "Si True, les active returns sont moins fiables."],
                ["Primitives tested", str(tested_count), "Nombre de conditions primitives scannées."],
                ["Raw alpha candidates", str(candidate_count), "Primitives avec signal brut candidat."],
                ["Watch primitives", str(watch_count), "Primitives fragiles à surveiller."],
                ["Top primitive", top_primitive, "Meilleure primitive brute."],
                ["Top family", top_family, "Famille de la meilleure primitive."],
                ["Top decision", top_decision, "Décision associée à la meilleure primitive."],
                ["Top score", f"{_format_num(top_score, 0)}/100", "Score brut de la meilleure primitive."],
                ["Top avg active 10B", _format_pct(top.get("Avg active 10B", np.nan)) if not top.empty else "N/A", "Forward active return moyen 10 barres."],
                ["Top avg active 20B", _format_pct(top.get("Avg active 20B", np.nan)) if not top.empty else "N/A", "Forward active return moyen 20 barres."],
                ["Top hit 10B", _format_pct(top.get("Hit 10B", np.nan)) if not top.empty else "N/A", "Hit rate actif 10 barres."],
                ["Top hit 20B", _format_pct(top.get("Hit 20B", np.nan)) if not top.empty else "N/A", "Hit rate actif 20 barres."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        blueprint = pd.DataFrame(
            [
                [
                    "If candidate found",
                    "Build V4.8 Primitive Source Micro-Runner",
                    "Tester seulement la primitive source prioritaire, avec signal causal t+1.",
                ],
                [
                    "If watchlist only",
                    "Refine primitive definitions",
                    "Ne pas promouvoir : vérifier sample, stabilité multi-horizon et active return médian.",
                ],
                [
                    "If no primitive",
                    "Source data expansion",
                    "Ajouter vraies données catalyseurs : earnings dates, revisions, options/IV, volume institutionnel, secteur/factor.",
                ],
                [
                    "Validation rule",
                    "exposed active return > 0, enough bars, median > 0, hit rate > 50%",
                    "Pas seulement plus de trades ou plus de couverture.",
                ],
                [
                    "Still forbidden",
                    "OOS / promotion / live / exits / sizing",
                    "Interdit tant qu'un micro-runner source-only V4.8 n'est pas positif.",
                ],
            ],
            columns=["Item", "Value", "Read"],
        )

        actions = pd.DataFrame(
            [
                [
                    "P0",
                    "Do not OOS",
                    "Raw source not validated",
                    "OOS seulement après V4.8/V4.9 si une primitive devient source candidate.",
                ],
                [
                    "P0",
                    "Do not promote",
                    "V4.7 is discovery only",
                    "Aucune primitive ne doit modifier le moteur courant.",
                ],
                [
                    "P0",
                    "Do not tune exits/sizing",
                    "Failure is still source-level",
                    "Ne pas compenser une source faible par sorties ou taille de position.",
                ],
                [
                    "P1",
                    "Prepare V4.8 only if candidate/watch exists",
                    f"Top primitive: {top_primitive}",
                    "Construire un micro-runner source-only si la primitive est au moins watchlist.",
                ],
                [
                    "P1",
                    "Expand data if no candidate",
                    "Price-only primitives may be insufficient",
                    "Ajouter catalyseurs/event data plutôt que forcer des seuils prix.",
                ],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        cards = [
            {"label": "V4.7 raw alpha", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Top primitive", "value": top_primitive, "delta": top_family},
            {"label": "Top score", "value": f"{_format_num(top_score, 0)}/100", "delta": top_decision},
            {"label": "Candidates", "value": str(candidate_count), "delta": "raw alpha"},
            {"label": "Watchlist", "value": str(watch_count), "delta": "fragile"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "raw_alpha_scan": scan,
            "family_summary": family,
            "positive_primitives": positive,
            "rejected_primitives": rejected,
            "blueprint": blueprint,
            "actions": actions,
            "market_pack": market_pack,
            "top_primitive": top.to_dict() if not top.empty else {},
        }

    except Exception as exc:
        out = empty.copy()
        out["enabled"] = True
        out["level"] = "Diagnostic error"
        out["score"] = 0.0
        out["decision"] = "ERROR"
        out["read"] = f"Erreur V4.7 : {exc}"
        out["summary"] = pd.DataFrame(
            [["Error", str(exc), "Erreur capturée sans interrompre le backtest."]],
            columns=["Metric", "Value", "Read"],
        )
        return out


def _v47_display_raw_alpha_table(table: pd.DataFrame, limit: int | None = None) -> pd.DataFrame:
    if table is None or not isinstance(table, pd.DataFrame) or table.empty:
        return pd.DataFrame()

    out = table.copy()

    if limit is not None:
        out = out.head(int(limit)).copy()

    if "Raw alpha score" in out.columns:
        out["Raw alpha score"] = out["Raw alpha score"].map(lambda x: _format_num(x, 0))

    for col in [
        "Coverage",
        "Avg active 3B",
        "Avg active 5B",
        "Avg active 10B",
        "Avg active 20B",
        "Median active 10B",
        "Median active 20B",
        "Worst active 10B",
        "Worst active 20B",
        "Hit 3B",
        "Hit 5B",
        "Hit 10B",
        "Hit 20B",
        "Stability",
    ]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_pct(x))

    return out


def _v47_display_family_summary(table: pd.DataFrame) -> pd.DataFrame:
    if table is None or not isinstance(table, pd.DataFrame) or table.empty:
        return pd.DataFrame()

    out = table.copy()

    for col in ["Best score", "Avg score"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_num(x, 0))

    for col in ["Mean active 10B", "Mean active 20B"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_pct(x))

    return out


def _render_raw_alpha_discovery_v47(*args, **kwargs) -> dict[str, Any]:
    pack = _v47_raw_alpha_discovery_pack(*args, **kwargs)

    st.subheader("Source Rebuild Lab / Raw Alpha Discovery V4.7")
    st.caption(
        "Scanner lecture seule après V4.6 : teste des conditions primitives price/active/gap/volume/volatility/trend/pullback "
        "et mesure leurs forward active returns 3B/5B/10B/20B. Ce bloc ne crée pas de stratégie, ne modifie pas le moteur, "
        "ne change ni l'equity curve ni le verdict et ne promeut aucun signal."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))

    if "candidate" in level.lower():
        st.warning(f"Lecture V4.7 : {read}")
    elif "no raw" in level.lower() or "error" in level.lower():
        st.error(f"Lecture V4.7 : {read}")
    else:
        st.info(f"Lecture V4.7 : {read}")

    with st.expander("V4.7 raw alpha summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.7 indisponible.")

    with st.expander("V4.7 raw alpha leaderboard", expanded=True):
        scan = _v47_display_raw_alpha_table(pack.get("raw_alpha_scan", pd.DataFrame()))
        if isinstance(scan, pd.DataFrame) and not scan.empty:
            st.dataframe(scan, use_container_width=True, hide_index=True)
        else:
            st.info("Raw alpha scan indisponible.")

    with st.expander("V4.7 family summary", expanded=True):
        family = _v47_display_family_summary(pack.get("family_summary", pd.DataFrame()))
        if isinstance(family, pd.DataFrame) and not family.empty:
            st.dataframe(family, use_container_width=True, hide_index=True)
        else:
            st.info("Family summary V4.7 indisponible.")

    with st.expander("V4.7 candidate / watch primitives", expanded=True):
        positive = _v47_display_raw_alpha_table(pack.get("positive_primitives", pd.DataFrame()))
        if isinstance(positive, pd.DataFrame) and not positive.empty:
            st.dataframe(positive, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune primitive candidate/watch détectée.")

    with st.expander("V4.7 rejected primitives — top rejected", expanded=False):
        rejected = _v47_display_raw_alpha_table(pack.get("rejected_primitives", pd.DataFrame()), limit=25)
        if isinstance(rejected, pd.DataFrame) and not rejected.empty:
            st.dataframe(rejected, use_container_width=True, hide_index=True)
        else:
            st.info("Rejected primitives indisponibles.")

    with st.expander("V4.8 recommended blueprint", expanded=True):
        blueprint = pack.get("blueprint", pd.DataFrame())
        if isinstance(blueprint, pd.DataFrame) and not blueprint.empty:
            st.dataframe(blueprint, use_container_width=True, hide_index=True)
        else:
            st.info("Blueprint V4.8 indisponible.")

    with st.expander("V4.7 next controlled actions", expanded=True):
        actions = pack.get("actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.7 indisponibles.")

    return pack


# Wrapper : on garde V4.4b + V4.5 + V4.6 intacts et on ajoute V4.7 juste après.
if "_V46_RENDER_BASE_FOR_V47" not in globals():
    _V46_RENDER_BASE_FOR_V47 = _render_mutation_trade_failure_decomposition_v44


def _render_mutation_trade_failure_decomposition_v44(*args, **kwargs):
    v44_pack = _V46_RENDER_BASE_FOR_V47(*args, **kwargs)

    try:
        v46_pack = {}
        if isinstance(v44_pack, dict):
            v46_pack = v44_pack.get("source_redesign_router_v46", {})

        v47_kwargs = dict(kwargs)
        v47_kwargs["v44_pack"] = v44_pack
        v47_kwargs["v46_pack"] = v46_pack

        v47_pack = _render_raw_alpha_discovery_v47(*args, **v47_kwargs)

        if isinstance(v44_pack, dict):
            v44_pack["raw_alpha_discovery_v47"] = v47_pack

    except Exception as exc:
        st.warning(f"V4.7 Raw Alpha Discovery indisponible : {exc}")

    return v44_pack


