def _v48_extract_context(args, kwargs) -> dict[str, Any]:
    """
    Extraction robuste du contexte courant.
    Compatible avec V4.4b -> V4.7.
    """
    try:
        if callable(globals().get("_v47_extract_context")):
            ctx = _v47_extract_context(args, kwargs)
        elif callable(globals().get("_v46_extract_context")):
            ctx = _v46_extract_context(args, kwargs)
        elif callable(globals().get("_v44b_extract_kwargs")):
            ctx = _v44b_extract_kwargs(args, kwargs)
        else:
            ctx = dict(kwargs or {})
    except Exception:
        ctx = dict(kwargs or {})

    out = dict(ctx or {})

    for key in ["df", "cfg", "ticker", "bt", "trades", "metrics", "current_metrics"]:
        if key in kwargs:
            out[key] = kwargs.get(key)

    out["v44_pack"] = kwargs.get("v44_pack", out.get("v44_pack", {}))
    out["v45_pack"] = kwargs.get("v45_pack", out.get("v45_pack", {}))
    out["v46_pack"] = kwargs.get("v46_pack", out.get("v46_pack", {}))
    out["v47_pack"] = kwargs.get("v47_pack", out.get("v47_pack", {}))

    return out


def _v48_summary_value(pack: dict[str, Any], metric: str, default: Any = "N/A") -> Any:
    try:
        summary = pack.get("summary", pd.DataFrame()) if isinstance(pack, dict) else pd.DataFrame()
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            hit = summary[summary["Metric"].astype(str) == str(metric)]
            if not hit.empty:
                return hit.iloc[0].get("Value", default)
    except Exception:
        pass
    return default


def _v48_data_availability_map(df: pd.DataFrame, cfg: BacktestConfig, ticker: str = "") -> dict[str, Any]:
    """
    Cartographie des données actuellement disponibles vs données manquantes.
    Lecture seule.
    """
    empty = {
        "rows": pd.DataFrame(),
        "n_rows": 0,
        "sample_years": np.nan,
        "start": "N/A",
        "end": "N/A",
        "benchmark": "N/A",
        "benchmark_fallback": True,
        "has_volume": False,
        "has_datetime": False,
    }

    try:
        if df is None or cfg is None:
            return empty

        work = _extract_ohlc(df) if callable(globals().get("_extract_ohlc")) else df.copy()

        if work is None or not isinstance(work, pd.DataFrame) or work.empty:
            return empty

        n = int(len(work))
        has_datetime = _is_datetime_like_index(work.index) if callable(globals().get("_is_datetime_like_index")) else False

        if has_datetime:
            start = pd.to_datetime(work.index.min())
            end = pd.to_datetime(work.index.max())
            sample_years = max((end - start).days / 365.25, 0.0)
            start_txt = _format_dt(start)
            end_txt = _format_dt(end)
        else:
            sample_years = n / 252.0
            start_txt = "N/A"
            end_txt = "N/A"

        volume = pd.to_numeric(work.get("volume", pd.Series(np.nan, index=work.index)), errors="coerce")
        has_volume = bool(volume.notna().sum() >= max(30, int(0.50 * n)))

        asset_ticker = str(ticker or getattr(cfg, "asset_ticker", "") or "").upper().strip()
        benchmark_symbol = str(getattr(cfg, "benchmark_ticker", "") or "").upper().strip()

        if not benchmark_symbol:
            benchmark_symbol = _sector_benchmark_guess(asset_ticker) if asset_ticker else "SPY"

        benchmark_label = f"Auto Sector ETF ({benchmark_symbol})" if benchmark_symbol else "Ticker Buy & Hold"

        rows = [
            [
                "OHLC price history",
                "AVAILABLE" if all(c in work.columns for c in ["open", "high", "low", "close"]) else "PARTIAL",
                f"{n} rows",
                "Base price data is present, but V4.7 shows price-only primitives are insufficient.",
            ],
            [
                "Basic volume",
                "AVAILABLE" if has_volume else "MISSING / WEAK",
                f"{int(volume.notna().sum())} valid rows",
                "Basic volume exists only as a proxy. It does not identify institutional participation.",
            ],
            [
                "Single benchmark",
                "AVAILABLE",
                benchmark_label,
                "Current active return is mainly versus one benchmark. Multi-benchmark attribution is still missing.",
            ],
            [
                "Longer history",
                "MISSING" if sample_years < 2.0 else "AVAILABLE",
                f"{_format_num(sample_years, 2)} years",
                "One-year windows can miss regime changes. Source search needs 2Y/3Y/5Y if available.",
            ],
            [
                "Earnings dates",
                "MISSING",
                "event_date / report_time / available_at",
                "Needed to test whether alpha is catalyst-driven rather than price-state-driven.",
            ],
            [
                "Earnings surprise",
                "MISSING",
                "EPS surprise / revenue surprise / margin surprise",
                "Needed to distinguish real post-earnings drift from random gaps.",
            ],
            [
                "Analyst revisions",
                "MISSING",
                "revision date / estimate before-after / available_at",
                "Needed because mega-cap semiconductor moves can be estimate-revision driven.",
            ],
            [
                "Guidance / forward estimates",
                "MISSING",
                "forward EPS/revenue/FCF revisions",
                "Needed to test whether forward estimate momentum explains relative performance.",
            ],
            [
                "Options IV / skew / gamma proxy",
                "MISSING",
                "IV rank / skew / term structure / gamma exposure proxy",
                "Needed to test squeeze, dealer positioning and event-vol regimes.",
            ],
            [
                "News / catalyst tags",
                "MISSING",
                "timestamp / tag / source / severity",
                "Needed to separate AI/data-center/order/news catalysts from ordinary price movement.",
            ],
            [
                "Macro / liquidity regime",
                "MISSING",
                "rates / USD / Nasdaq liquidity / VIX / yields",
                "Needed to avoid comparing the stock to SMH without risk/liquidity context.",
            ],
            [
                "Factor / benchmark alternatives",
                "MISSING",
                "SMH / QQQ / XLK / SPY / SOXX / factor proxies",
                "Needed to determine whether the benchmark choice is hiding true alpha.",
            ],
        ]

        table = pd.DataFrame(rows, columns=["Data block", "Status", "Current evidence", "Read"])

        return {
            "rows": table,
            "n_rows": n,
            "sample_years": sample_years,
            "start": start_txt,
            "end": end_txt,
            "benchmark": benchmark_label,
            "benchmark_fallback": False,
            "has_volume": has_volume,
            "has_datetime": has_datetime,
        }

    except Exception:
        return empty


def _v48_score_requirement(
    family: str,
    base: float,
    price_only_failed: bool,
    short_sample: bool,
    ticker: str,
) -> float:
    try:
        score = float(base)

        if price_only_failed:
            score += 10.0

        if short_sample and "Longer sample" in family:
            score += 18.0

        t = str(ticker or "").upper().strip()
        semi = {"NVDA", "AMD", "AVGO", "INTC", "MU", "MRVL", "TSM", "ASML", "ARM", "QCOM", "TXN", "AMAT", "LRCX"}

        if t in semi and any(x in family for x in ["Earnings", "Analyst", "Guidance", "Options", "Sector"]):
            score += 5.0

        return max(0.0, min(100.0, score))

    except Exception:
        return float(base)


def _v48_expansion_requirements_table(
    data_map: dict[str, Any],
    v46_pack: dict[str, Any],
    v47_pack: dict[str, Any],
    ticker: str,
) -> pd.DataFrame:
    """
    Classe les familles de données à ajouter.
    """
    try:
        v46_decision = str(v46_pack.get("decision", "")) if isinstance(v46_pack, dict) else ""
        v47_decision = str(v47_pack.get("decision", "")) if isinstance(v47_pack, dict) else ""

        price_only_failed = (
            "REBUILD_SOURCE_LAYER" in v46_decision
            or "SOURCE_DATA_EXPANSION_REQUIRED" in v47_decision
        )

        sample_years = _safe_float(data_map.get("sample_years"), np.nan) if isinstance(data_map, dict) else np.nan
        short_sample = bool(pd.notna(sample_years) and sample_years < 2.0)

        specs = [
            {
                "Data family": "Earnings dates / earnings surprise",
                "Base": 82,
                "Why required": "V4.7 rejected price-only primitives. Earnings shocks may explain active returns that pure price states miss.",
                "Required fields": "ticker, fiscal_period, event_date, report_time, available_at, EPS actual/estimate, revenue actual/estimate, surprise %",
                "Minimal integration": "Point-in-time CSV/API adapter; join only after available_at.",
                "Anti-leakage rule": "Use surprise only after report availability; no actual value before release timestamp.",
                "V4.9 test": "Post-earnings drift / surprise continuation scanner",
            },
            {
                "Data family": "Analyst revisions",
                "Base": 80,
                "Why required": "If alpha is driven by estimate revision cycles, price breakout and active reversal will arrive too late.",
                "Required fields": "revision_date, available_at, broker/source, metric, old_estimate, new_estimate, horizon",
                "Minimal integration": "Revision momentum features by 5/20/60 bars.",
                "Anti-leakage rule": "Only revisions timestamped before decision bar; no latest snapshot backfilled.",
                "V4.9 test": "Estimate revision momentum scanner",
            },
            {
                "Data family": "Guidance / forward estimates",
                "Base": 78,
                "Why required": "NVDA-like moves can be forward-guidance repricing, not mechanical trend.",
                "Required fields": "guidance date, available_at, forward EPS/revenue/FCF, revision direction, consensus delta",
                "Minimal integration": "Forward estimate acceleration table.",
                "Anti-leakage rule": "Consensus must be point-in-time, never final revised history.",
                "V4.9 test": "Forward estimate acceleration scanner",
            },
            {
                "Data family": "Options IV / skew / gamma proxy",
                "Base": 76,
                "Why required": "Volatility squeeze proxies failed using realized volatility only. Options data may capture event-vol and dealer positioning.",
                "Required fields": "date, expiry, ATM IV, IV rank, skew, term structure, put/call, gamma exposure proxy",
                "Minimal integration": "Daily options feature table aligned t+1.",
                "Anti-leakage rule": "Use end-of-day option snapshot only on next decision bar.",
                "V4.9 test": "IV expansion / gamma squeeze scanner",
            },
            {
                "Data family": "Multi-benchmark / factor attribution",
                "Base": 74,
                "Why required": "SMH may be too strict or not the correct risk benchmark across regimes.",
                "Required fields": "daily returns for SMH, SOXX, QQQ, XLK, SPY, factor proxies, rates proxies",
                "Minimal integration": "Rolling active returns vs multiple benchmarks.",
                "Anti-leakage rule": "Benchmarks must be aligned to same calendar and same close timestamp.",
                "V4.9 test": "Benchmark selection / factor-relative alpha map",
            },
            {
                "Data family": "Longer sample expansion",
                "Base": 58,
                "Why required": "V4.7 uses roughly one year. A single regime can make all price-only conditions look dead.",
                "Required fields": "2Y / 3Y / 5Y OHLCV plus benchmarks",
                "Minimal integration": "Same scanner over multiple windows.",
                "Anti-leakage rule": "Do not tune on full sample then report same sample as validation.",
                "V4.9 test": "Multi-window raw alpha stability scanner",
            },
            {
                "Data family": "News / catalyst tags",
                "Base": 68,
                "Why required": "Price-only primitives cannot distinguish AI/datacenter/product/order/regulatory catalysts from noise.",
                "Required fields": "timestamp, headline/source, catalyst tag, severity, ticker relevance",
                "Minimal integration": "Event tag table with manual or API classification.",
                "Anti-leakage rule": "Use publication timestamp, not later article updates or outcome labels.",
                "V4.9 test": "Catalyst-tag active return scanner",
            },
            {
                "Data family": "Abnormal dollar volume / institutional participation",
                "Base": 62,
                "Why required": "Basic volume z-score is weaker than dollar volume, block flow, or institutional participation proxies.",
                "Required fields": "volume, dollar volume, relative volume, block proxy, dark/ATS proxy if available",
                "Minimal integration": "Abnormal participation feature table.",
                "Anti-leakage rule": "Use completed daily volume only after close; intraday requires timestamped bars.",
                "V4.9 test": "Abnormal participation scanner",
            },
            {
                "Data family": "Macro / liquidity regime",
                "Base": 58,
                "Why required": "Semiconductor alpha can depend on rates, USD, Nasdaq liquidity, volatility and risk appetite.",
                "Required fields": "UST yields, DXY/UUP, QQQ/SPY regime, VIX/VIXY, liquidity proxy",
                "Minimal integration": "Daily macro regime table.",
                "Anti-leakage rule": "Use same-day close only for next-day signal unless intraday timestamps exist.",
                "V4.9 test": "Macro-conditioned source scanner",
            },
            {
                "Data family": "Fundamental / valuation regime",
                "Base": 54,
                "Why required": "Momentum may fail when valuation repricing dominates. Need regime context for multiples and growth.",
                "Required fields": "forward PE, EV/Sales, revenue growth, margin, FCF, ROE/ROIC, revisions",
                "Minimal integration": "Quarterly/fundamental feature table with release dates.",
                "Anti-leakage rule": "Fundamentals must be available_at aligned; no restated future fundamentals.",
                "V4.9 test": "Valuation-growth regime scanner",
            },
        ]

        rows = []

        for spec in specs:
            score = _v48_score_requirement(
                spec["Data family"],
                spec["Base"],
                price_only_failed=price_only_failed,
                short_sample=short_sample,
                ticker=ticker,
            )

            if score >= 85:
                decision = "P0 REQUIRED"
            elif score >= 75:
                decision = "P1 REQUIRED"
            elif score >= 65:
                decision = "P2 USEFUL"
            else:
                decision = "P3 OPTIONAL"

            rows.append(
                {
                    "Priority score": score,
                    "Decision": decision,
                    "Data family": spec["Data family"],
                    "Why required": spec["Why required"],
                    "Required fields": spec["Required fields"],
                    "Minimal integration": spec["Minimal integration"],
                    "Anti-leakage rule": spec["Anti-leakage rule"],
                    "V4.9 test": spec["V4.9 test"],
                }
            )

        out = pd.DataFrame(rows)

        if not out.empty:
            out = out.sort_values(
                ["Priority score", "Decision"],
                ascending=[False, True],
            ).reset_index(drop=True)

        return out

    except Exception:
        return pd.DataFrame()


def _v48_protocol_tables() -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    """
    Protocoles d'intégration des nouvelles sources.
    """
    anti_leakage = pd.DataFrame(
        [
            ["available_at mandatory", "Every external feature needs an availability timestamp.", "If missing, feature cannot validate a positive signal."],
            ["event_date != available_at", "Event date and market availability can differ.", "Decision bar must use available_at, not economic period."],
            ["t+1 enforcement", "All external signals must be shifted one bar before backtest.", "Same rule as Custom Signal Import."],
            ["point-in-time only", "No final revised snapshot for estimates/fundamentals.", "Use the value known at the decision date."],
            ["no outcome labels", "No future return, target hit, realized surprise after event in feature columns.", "Leakage columns must block validation."],
            ["calendar alignment", "External data must align to trading calendar and market close convention.", "Non-trading days forward-fill only after availability."],
            ["source tag", "Every feature row must keep source/provider tag.", "Needed for audit and reproducibility."],
        ],
        columns=["Rule", "Definition", "Operational consequence"],
    )

    adapter_schema = pd.DataFrame(
        [
            ["date", "datetime/date", "Trading date used for alignment."],
            ["available_at", "datetime", "Earliest timestamp the information was tradable."],
            ["ticker", "string", "Asset identifier."],
            ["feature_family", "string", "earnings / revision / options / news / macro / factor."],
            ["feature_name", "string", "Stable feature name."],
            ["value", "float/string", "Feature value or normalized state."],
            ["source", "string", "Provider or manual source tag."],
            ["confidence", "float optional", "Optional reliability score."],
            ["notes", "string optional", "Audit note."],
        ],
        columns=["Column", "Type", "Read"],
    )

    v49_plan = pd.DataFrame(
        [
            ["V4.9A", "External Source Data Adapter", "Parser + safety gate for catalyst/fundamental/options CSV tables."],
            ["V4.9B", "Catalyst Feature Audit", "Coverage, timestamp quality, leakage checks, feature missingness."],
            ["V4.9C", "Catalyst Raw Alpha Scanner", "Same logic as V4.7, but on external features."],
            ["V4.9D", "Multi-benchmark Active Return Map", "SMH/QQQ/XLK/SPY/factor-relative forward active returns."],
            ["V4.9E", "Source Candidate Selection", "Only if external features produce positive forward active return."],
        ],
        columns=["Step", "Block", "Purpose"],
    )

    return anti_leakage, adapter_schema, v49_plan


def _source_data_expansion_map_v48_pack(*args, **kwargs) -> dict[str, Any]:
    """
    V4.8 — Source Data Expansion Map / Catalyst Requirements.

    Lecture seule :
    - ne modifie pas cfg ;
    - ne crée pas de stratégie ;
    - ne modifie pas le moteur ;
    - ne modifie pas l'equity curve ;
    - ne promeut aucune source ;
    - transforme l'échec V4.7 en cahier des charges data.
    """
    ctx = _v48_extract_context(args, kwargs)

    df = ctx.get("df", None)
    cfg = ctx.get("cfg", None)
    ticker = str(ctx.get("ticker", "") or "")

    v44_pack = ctx.get("v44_pack", {})
    v45_pack = ctx.get("v45_pack", {})
    v46_pack = ctx.get("v46_pack", {})
    v47_pack = ctx.get("v47_pack", {})

    if isinstance(v44_pack, dict):
        if not isinstance(v45_pack, dict) or not v45_pack:
            v45_pack = v44_pack.get("coverage_without_overfit_v45", {})
        if not isinstance(v46_pack, dict) or not v46_pack:
            v46_pack = v44_pack.get("source_redesign_router_v46", {})
        if not isinstance(v47_pack, dict) or not v47_pack:
            v47_pack = v44_pack.get("raw_alpha_discovery_v47", {})

    empty = {
        "enabled": False,
        "level": "Unavailable",
        "score": 0.0,
        "decision": "NO_DECISION",
        "read": "V4.8 indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "data_availability": pd.DataFrame(),
        "requirements": pd.DataFrame(),
        "anti_leakage": pd.DataFrame(),
        "adapter_schema": pd.DataFrame(),
        "v49_plan": pd.DataFrame(),
        "actions": pd.DataFrame(),
    }

    try:
        if df is None or cfg is None:
            out = empty.copy()
            out["read"] = "df/cfg manquant pour V4.8."
            return out

        data_map = _v48_data_availability_map(df, cfg, ticker=ticker)
        availability = data_map.get("rows", pd.DataFrame())

        requirements = _v48_expansion_requirements_table(
            data_map=data_map,
            v46_pack=v46_pack if isinstance(v46_pack, dict) else {},
            v47_pack=v47_pack if isinstance(v47_pack, dict) else {},
            ticker=ticker,
        )

        anti_leakage, adapter_schema, v49_plan = _v48_protocol_tables()

        top = pd.Series(dtype=object)
        if isinstance(requirements, pd.DataFrame) and not requirements.empty:
            top = requirements.iloc[0]

        top_family = str(top.get("Data family", "None")) if not top.empty else "None"
        top_score = _safe_float(top.get("Priority score"), 0.0) if not top.empty else 0.0

        v45_decision = str(v45_pack.get("decision", "N/A")) if isinstance(v45_pack, dict) else "N/A"
        v46_decision = str(v46_pack.get("decision", "N/A")) if isinstance(v46_pack, dict) else "N/A"
        v47_decision = str(v47_pack.get("decision", "N/A")) if isinstance(v47_pack, dict) else "N/A"

        v47_candidates = _v48_summary_value(v47_pack if isinstance(v47_pack, dict) else {}, "Raw alpha candidates", "N/A")
        v47_watch = _v48_summary_value(v47_pack if isinstance(v47_pack, dict) else {}, "Watch primitives", "N/A")
        v47_top = _v48_summary_value(v47_pack if isinstance(v47_pack, dict) else {}, "Top primitive", "N/A")
        v47_top_score = _v48_summary_value(v47_pack if isinstance(v47_pack, dict) else {}, "Top score", "N/A")

        if "SOURCE_DATA_EXPANSION_REQUIRED" in v47_decision:
            level = "Catalyst data required"
            decision = "BUILD_V49_EXTERNAL_SOURCE_DATA_ADAPTER"
            score = max(70.0, min(90.0, top_score))
            read = (
                "V4.8 confirme que le price-only est épuisé : V4.7 n'a trouvé aucune primitive candidate/watch. "
                "La prochaine étape doit être un adaptateur de données externes causales, pas un runner de stratégie."
            )
        elif top_score >= 75:
            level = "Data expansion recommended"
            decision = "PREPARE_V49_EXTERNAL_FEATURE_AUDIT"
            score = min(85.0, top_score)
            read = (
                "V4.8 recommande d'enrichir la source avant toute validation, même si V4.7 n'est pas totalement vide."
            )
        else:
            level = "Data map inconclusive"
            decision = "MANUAL_REVIEW_REQUIRED"
            score = max(30.0, top_score)
            read = "V4.8 n'a pas assez de contexte pour classer proprement les sources externes."

        summary = pd.DataFrame(
            [
                ["V4.8 level", level, "Lecture synthétique de la carte d'expansion data."],
                ["V4.8 score", f"{_format_num(score, 0)}/100", "Score research : priorité d'expansion data, pas performance."],
                ["Decision", decision, "Décision de recherche V4.8."],
                ["Read", read, "Interprétation opérationnelle."],
                ["Ticker", ticker or "N/A", "Ticker audité."],
                ["Sample window", f"{data_map.get('start', 'N/A')} → {data_map.get('end', 'N/A')}", "Fenêtre actuellement disponible."],
                ["Rows", str(data_map.get("n_rows", 0)), "Nombre de barres disponibles."],
                ["Sample years", _format_num(data_map.get("sample_years", np.nan), 2), "Approximation en années."],
                ["Current benchmark", str(data_map.get("benchmark", "N/A")), "Benchmark relatif actuel."],
                ["V4.5 input", v45_decision, "Coverage repair précédent."],
                ["V4.6 input", v46_decision, "Router source précédent."],
                ["V4.7 input", v47_decision, "Raw Alpha Discovery précédent."],
                ["V4.7 candidates", str(v47_candidates), "Nombre de primitives candidates."],
                ["V4.7 watchlist", str(v47_watch), "Nombre de primitives watchlist."],
                ["V4.7 top primitive", str(v47_top), "Meilleure primitive price-only."],
                ["V4.7 top score", str(v47_top_score), "Score de la meilleure primitive price-only."],
                ["Top missing data family", top_family, "Famille data prioritaire."],
                ["Top data priority", f"{_format_num(top_score, 0)}/100", "Priorité de la famille data principale."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        actions = pd.DataFrame(
            [
                [
                    "P0",
                    "Do not OOS",
                    "No validated source",
                    "OOS interdit tant qu'une feature externe n'a pas produit de forward active return positif.",
                ],
                [
                    "P0",
                    "Do not promote",
                    "V4.8 is requirements mapping only",
                    "Aucune donnée externe ne doit modifier le moteur courant.",
                ],
                [
                    "P0",
                    "Do not tune exits/sizing",
                    "The failure remains source-level",
                    "Ne pas compenser l'absence d'edge source par des exits ou du sizing.",
                ],
                [
                    "P1",
                    "Build V4.9 data adapter",
                    f"Top family: {top_family}",
                    "Créer un adaptateur CSV/API point-in-time avec available_at et safety gate.",
                ],
                [
                    "P1",
                    "Run external feature audit before scanner",
                    "Leakage risk is high with catalysts/estimates",
                    "Contrôler timestamps, missingness, revisions et source tags avant tout score alpha.",
                ],
                [
                    "P2",
                    "Expand benchmark map",
                    "SMH-only active return may be too narrow",
                    "Ajouter QQQ, XLK, SPY, SOXX/factor proxies pour attribution relative.",
                ],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        cards = [
            {"label": "V4.8 data map", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Top missing source", "value": top_family, "delta": "external data"},
            {"label": "Top priority", "value": f"{_format_num(top_score, 0)}/100", "delta": str(top.get("Decision", "N/A")) if not top.empty else "N/A"},
            {"label": "V4.7 candidates", "value": str(v47_candidates), "delta": "raw alpha"},
            {"label": "Next block", "value": decision, "delta": "research only"},
            {"label": "Do not promote", "value": "PASS", "delta": "no engine impact"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "data_availability": availability,
            "requirements": requirements,
            "anti_leakage": anti_leakage,
            "adapter_schema": adapter_schema,
            "v49_plan": v49_plan,
            "actions": actions,
            "top_data_family": top_family,
            "data_map": data_map,
        }

    except Exception as exc:
        out = empty.copy()
        out["enabled"] = True
        out["level"] = "Diagnostic error"
        out["score"] = 0.0
        out["decision"] = "ERROR"
        out["read"] = f"Erreur V4.8 : {exc}"
        out["summary"] = pd.DataFrame(
            [["Error", str(exc), "Erreur capturée sans interrompre le backtest."]],
            columns=["Metric", "Value", "Read"],
        )
        return out


def _v48_display_requirements(table: pd.DataFrame) -> pd.DataFrame:
    if table is None or not isinstance(table, pd.DataFrame) or table.empty:
        return pd.DataFrame()

    out = table.copy()

    if "Priority score" in out.columns:
        out["Priority score"] = out["Priority score"].map(lambda x: _format_num(x, 0))

    return out


def _render_source_data_expansion_map_v48(*args, **kwargs) -> dict[str, Any]:
    pack = _source_data_expansion_map_v48_pack(*args, **kwargs)

    st.subheader("Source Data Expansion Map / Catalyst Requirements V4.8")
    st.caption(
        "Carte lecture seule après V4.7 : transforme l'échec des primitives price-only en cahier des charges data. "
        "Classe les données externes nécessaires : earnings, surprises, analyst revisions, guidance, options IV/skew/gamma, "
        "news/catalyst tags, volume institutionnel, macro/liquidité et multi-benchmark. "
        "Aucun impact sur le moteur courant, l'equity curve, les trades ou le verdict."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))

    if "required" in level.lower() or "error" in level.lower():
        st.error(f"Lecture V4.8 : {read}")
    elif "recommended" in level.lower():
        st.warning(f"Lecture V4.8 : {read}")
    else:
        st.info(f"Lecture V4.8 : {read}")

    with st.expander("V4.8 source data expansion summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.8 indisponible.")

    with st.expander("V4.8 current data availability map", expanded=True):
        availability = pack.get("data_availability", pd.DataFrame())
        if isinstance(availability, pd.DataFrame) and not availability.empty:
            st.dataframe(availability, use_container_width=True, hide_index=True)
        else:
            st.info("Carte de disponibilité data indisponible.")

    with st.expander("V4.8 external data requirements queue", expanded=True):
        requirements = _v48_display_requirements(pack.get("requirements", pd.DataFrame()))
        if isinstance(requirements, pd.DataFrame) and not requirements.empty:
            st.dataframe(requirements, use_container_width=True, hide_index=True)
        else:
            st.info("Requirements V4.8 indisponibles.")

    with st.expander("V4.8 anti-leakage protocol", expanded=True):
        anti = pack.get("anti_leakage", pd.DataFrame())
        if isinstance(anti, pd.DataFrame) and not anti.empty:
            st.dataframe(anti, use_container_width=True, hide_index=True)
        else:
            st.info("Protocole anti-leakage indisponible.")

    with st.expander("V4.9 external feature adapter schema", expanded=True):
        schema = pack.get("adapter_schema", pd.DataFrame())
        if isinstance(schema, pd.DataFrame) and not schema.empty:
            st.dataframe(schema, use_container_width=True, hide_index=True)
        else:
            st.info("Schema V4.9 indisponible.")

    with st.expander("V4.9 recommended build plan", expanded=True):
        plan = pack.get("v49_plan", pd.DataFrame())
        if isinstance(plan, pd.DataFrame) and not plan.empty:
            st.dataframe(plan, use_container_width=True, hide_index=True)
        else:
            st.info("Plan V4.9 indisponible.")

    with st.expander("V4.8 next controlled actions", expanded=True):
        actions = pack.get("actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.8 indisponibles.")

    # --- V4.9A external source data adapter call ---
    try:
        ctx_v49a = _v48_extract_context(args, kwargs)

        df_v49a = ctx_v49a.get("df", None)
        cfg_v49a = ctx_v49a.get("cfg", None)

        ticker_v49a = str(
            ctx_v49a.get("ticker", "")
            or getattr(cfg_v49a, "asset_ticker", "")
            or ""
        )

        price_index_v49a = (
            df_v49a.index
            if isinstance(df_v49a, pd.DataFrame) and not df_v49a.empty
            else pd.Index([])
        )

        v49a_pack = _render_external_source_data_adapter_v49a(
            ticker=ticker_v49a,
            price_index=price_index_v49a,
            cfg=cfg_v49a,
            price_data=df_v49a,
        )

        if isinstance(pack, dict):
            pack["external_source_data_adapter_v49a"] = v49a_pack

    except Exception as exc:
        st.warning(f"V4.9A External Source Data Adapter indisponible : {exc}")
    # --- end V4.9A external source data adapter call ---

    return pack


# Wrapper : on garde V4.4b + V4.5 + V4.6 + V4.7 intacts et on ajoute V4.8 juste après.
if "_V47_RENDER_BASE_FOR_V48" not in globals():
    _V47_RENDER_BASE_FOR_V48 = _render_mutation_trade_failure_decomposition_v44


def _render_mutation_trade_failure_decomposition_v44(*args, **kwargs):
    v44_pack = _V47_RENDER_BASE_FOR_V48(*args, **kwargs)

    try:
        v45_pack = {}
        v46_pack = {}
        v47_pack = {}

        if isinstance(v44_pack, dict):
            v45_pack = v44_pack.get("coverage_without_overfit_v45", {})
            v46_pack = v44_pack.get("source_redesign_router_v46", {})
            v47_pack = v44_pack.get("raw_alpha_discovery_v47", {})

        v48_kwargs = dict(kwargs)
        v48_kwargs["v44_pack"] = v44_pack
        v48_kwargs["v45_pack"] = v45_pack
        v48_kwargs["v46_pack"] = v46_pack
        v48_kwargs["v47_pack"] = v47_pack

        v48_pack = _render_source_data_expansion_map_v48(*args, **v48_kwargs)

        if isinstance(v44_pack, dict):
            v44_pack["source_data_expansion_map_v48"] = v48_pack

    except Exception as exc:
        st.warning(f"V4.8 Source Data Expansion Map indisponible : {exc}")

    return v44_pack


# ============================================================
# EXTERNAL SOURCE DATA ADAPTER V4.9A
# ============================================================
# Research-only adapter after V4.8.
# Purpose:
# - parse external causal feature tables;
# - enforce point-in-time / available_at discipline;
# - detect leakage-style columns;
# - align external rows to the trading calendar;
# - produce an audit map before any alpha scanner.
#
# Hard guardrail:
# - no signal generation;
# - no backtest mutation;
# - no equity curve impact;
# - no verdict impact;
# - no OOS / promotion / exits / sizing.

def _v49a_norm_col(value: Any) -> str:
    try:
        return (
            str(value or "")
            .strip()
            .lower()
            .replace(" ", "_")
            .replace("-", "_")
            .replace("/", "_")
        )
    except Exception:
        return ""


def _v49a_pick_col(columns: list[str], aliases: list[str]) -> str | None:
    norm_map = {_v49a_norm_col(c): c for c in columns}
    for alias in aliases:
        key = _v49a_norm_col(alias)
        if key in norm_map:
            return norm_map[key]
    return None


def _v49a_required_schema() -> pd.DataFrame:
    return pd.DataFrame(
        [
            ["date", "datetime/date", "Economic/event date or feature observation date."],
            ["available_at", "datetime", "Earliest timestamp when the information was tradable. Mandatory."],
            ["ticker", "string", "Asset identifier. Example: NVDA."],
            ["feature_family", "string", "earnings / revision / guidance / options / news / macro / factor / volume / fundamental."],
            ["feature_name", "string", "Stable feature name. Example: eps_surprise_pct."],
            ["value", "float/string", "Observed value or normalized state."],
            ["source", "string", "Provider or manual source tag."],
            ["confidence", "float optional", "Optional reliability score between 0 and 1."],
            ["notes", "string optional", "Audit note."],
        ],
        columns=["Column", "Type", "Read"],
    )


def _v49a_sample_external_source(ticker: str, price_index: pd.Index) -> str:
    try:
        price_start, price_end = _price_index_bounds(price_index)
        if price_start is None or price_end is None:
            base_dates = pd.date_range("2025-01-01", periods=4, freq="90D")
        else:
            idx = pd.to_datetime(pd.Index(price_index), errors="coerce")
            idx = pd.Series(idx).dropna().drop_duplicates().sort_values()
            if len(idx) >= 4:
                pos = np.linspace(0, len(idx) - 1, 4, dtype=int)
                base_dates = idx.iloc[pos].tolist()
            else:
                base_dates = pd.date_range(price_start, price_end, periods=4)

        t = str(ticker or "NVDA").upper().strip()
        rows = [
            "date,available_at,ticker,feature_family,feature_name,value,source,confidence,notes"
        ]

        examples = [
            ("earnings", "eps_surprise_pct", "8.2", "manual_example", "example earnings surprise"),
            ("revision", "eps_revision_30d_pct", "4.5", "manual_example", "example analyst revision"),
            ("guidance", "revenue_guidance_change_pct", "3.1", "manual_example", "example guidance revision"),
            ("news", "ai_datacenter_catalyst_tag", "positive", "manual_example", "example catalyst tag"),
        ]

        for dt, row in zip(base_dates, examples):
            ts = pd.Timestamp(dt)
            available_at = ts + pd.Timedelta(hours=21, minutes=30)
            family, name, value, source, notes = row
            rows.append(
                f"{ts.strftime('%Y-%m-%d')},{available_at.strftime('%Y-%m-%d %H:%M:%S')},"
                f"{t},{family},{name},{value},{source},0.80,{notes}"
            )

        return "\n".join(rows)

    except Exception:
        t = str(ticker or "NVDA").upper().strip()
        return (
            "date,available_at,ticker,feature_family,feature_name,value,source,confidence,notes\n"
            f"2025-01-01,2025-01-01 21:30:00,{t},earnings,eps_surprise_pct,8.2,manual_example,0.80,example"
        )


def _parse_external_source_features_v49a(
    uploaded_file: Any = None,
    pasted_text: str = "",
    default_ticker: str = "",
) -> tuple[pd.DataFrame | None, str]:
    """
    Parse external source data for V4.9A.

    Accepted logical schema:
    date, available_at, ticker, feature_family, feature_name, value, source, confidence, notes

    This parser does not generate a signal and does not execute user code.
    """
    raw: pd.DataFrame | None = None

    try:
        if uploaded_file is not None:
            file_name = str(getattr(uploaded_file, "name", "") or "").lower()
            if file_name.endswith((".xlsx", ".xls")):
                raw = pd.read_excel(uploaded_file)
            else:
                raw = pd.read_csv(uploaded_file, sep=None, engine="python")
        elif pasted_text and str(pasted_text).strip():
            raw = pd.read_csv(StringIO(str(pasted_text).strip()), sep=None, engine="python")
    except Exception as exc:
        return None, f"V4.9A import impossible : {exc}"

    if raw is None or raw.empty:
        return None, "Aucune donnée externe chargée."

    df = raw.copy()
    df.columns = [str(c).strip() for c in df.columns]
    source_columns = [str(c) for c in df.columns]
    raw_rows = int(len(df))

    date_col = _v49a_pick_col(source_columns, ["date", "event_date", "observation_date", "fiscal_date", "period_date"])
    available_col = _v49a_pick_col(
        source_columns,
        ["available_at", "available_time", "published_at", "release_time", "report_time", "asof", "as_of", "effective_at"],
    )
    ticker_col = _v49a_pick_col(source_columns, ["ticker", "symbol", "asset", "ric"])
    family_col = _v49a_pick_col(source_columns, ["feature_family", "family", "data_family", "category", "type"])
    name_col = _v49a_pick_col(source_columns, ["feature_name", "name", "metric", "field", "factor"])
    value_col = _v49a_pick_col(source_columns, ["value", "feature_value", "metric_value", "signal_value", "state"])
    source_col = _v49a_pick_col(source_columns, ["source", "provider", "vendor", "origin"])
    confidence_col = _v49a_pick_col(source_columns, ["confidence", "reliability", "quality_score"])
    notes_col = _v49a_pick_col(source_columns, ["notes", "comment", "description", "read"])

    out = pd.DataFrame()

    out["date"] = pd.to_datetime(df[date_col], errors="coerce") if date_col else pd.NaT
    out["available_at"] = pd.to_datetime(df[available_col], errors="coerce") if available_col else pd.NaT

    if ticker_col:
        out["ticker"] = df[ticker_col].astype(str).str.upper().str.strip()
    else:
        out["ticker"] = str(default_ticker or "").upper().strip()

    out["feature_family"] = (
        df[family_col].astype(str).map(_v49a_norm_col)
        if family_col
        else "unknown"
    )

    out["feature_name"] = (
        df[name_col].astype(str).map(_v49a_norm_col)
        if name_col
        else ""
    )

    if value_col:
        out["value"] = df[value_col]
    else:
        out["value"] = np.nan

    out["source"] = df[source_col].astype(str).str.strip() if source_col else "unknown"
    out["confidence"] = pd.to_numeric(df[confidence_col], errors="coerce") if confidence_col else np.nan
    out["notes"] = df[notes_col].astype(str).str.strip() if notes_col else ""

    out = out.replace([np.inf, -np.inf], np.nan)

    try:
        out.attrs.update(
            {
                "source_columns": source_columns,
                "raw_rows": raw_rows,
                "date_col": str(date_col or ""),
                "available_at_col": str(available_col or ""),
                "ticker_col": str(ticker_col or ""),
                "family_col": str(family_col or ""),
                "name_col": str(name_col or ""),
                "value_col": str(value_col or ""),
                "source_col": str(source_col or ""),
                "confidence_col": str(confidence_col or ""),
                "notes_col": str(notes_col or ""),
                "parser_version": "External Source Data Adapter V4.9A",
            }
        )
    except Exception:
        pass

    clean_rows = int(len(out))
    return out, f"V4.9A external source chargée : {clean_rows} lignes nettoyées / {raw_rows} lignes brutes."


def _v49a_price_calendar_frame(price_index: pd.Index) -> pd.DataFrame:
    try:
        if not _is_datetime_like_index(price_index):
            return pd.DataFrame()

        dates = pd.to_datetime(pd.Index(price_index), errors="coerce")
        dates = pd.Series(dates).dropna().drop_duplicates().sort_values()

        if dates.empty:
            return pd.DataFrame()

        return pd.DataFrame({"trading_date": dates.dt.normalize().drop_duplicates().values})
    except Exception:
        return pd.DataFrame()


def _v49a_align_external_features_to_calendar(
    features_df: pd.DataFrame,
    price_index: pd.Index,
) -> pd.DataFrame:
    """
    Align external features to the next available trading date after available_at.
    This creates an audit map only. It does not produce a signal.
    """
    if features_df is None or features_df.empty:
        return pd.DataFrame()

    cal = _v49a_price_calendar_frame(price_index)
    if cal.empty:
        return pd.DataFrame()

    trading_days = pd.to_datetime(cal["trading_date"]).sort_values().reset_index(drop=True)
    trading_np = trading_days.values.astype("datetime64[ns]")

    out = features_df.copy()
    out["available_date"] = pd.to_datetime(out["available_at"], errors="coerce").dt.normalize()
    out["decision_date"] = pd.NaT

    for idx, row in out.iterrows():
        available_date = row.get("available_date", pd.NaT)
        if pd.isna(available_date):
            continue

        try:
            pos = np.searchsorted(trading_np, np.datetime64(pd.Timestamp(available_date)), side="left")
            if 0 <= pos < len(trading_days):
                out.at[idx, "decision_date"] = pd.Timestamp(trading_days.iloc[int(pos)])
        except Exception:
            continue

    out["calendar_aligned"] = out["decision_date"].notna()
    return out


def _external_source_data_adapter_v49a_pack(
    features_df: Any,
    price_index: pd.Index,
    ticker: str = "",
) -> dict[str, Any]:
    def _row(check: str, status: str, severity: str, value: Any, read: str) -> dict[str, Any]:
        return {
            "Check": str(check),
            "Status": str(status),
            "Severity": str(severity),
            "Value": str(value),
            "Read": str(read),
        }

    schema = _v49a_required_schema()

    empty_summary = pd.DataFrame(
        [
            ["V4.9A level", "Waiting for external source data", "Aucune table externe n'est chargée."],
            ["V4.9A score", "0/100", "Score non applicable sans données externes."],
            ["Decision", "NO_EXTERNAL_DATA", "Importer une table externe causale avant V4.9B."],
            ["Read", "V4.9A attend une source externe avec available_at obligatoire.", "Lecture opérationnelle."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    if features_df is None or not isinstance(features_df, pd.DataFrame) or features_df.empty:
        return {
            "enabled": False,
            "level": "Waiting for external source data",
            "score": 0.0,
            "decision": "NO_EXTERNAL_DATA",
            "read": "Importer une table externe causale avant V4.9B.",
            "cards": [
                {"label": "V4.9A adapter", "value": "Waiting data", "delta": "research only"},
                {"label": "Rows", "value": "0", "delta": "external"},
                {"label": "Decision", "value": "NO_EXTERNAL_DATA", "delta": "no engine impact"},
            ],
            "summary": empty_summary,
            "checks": pd.DataFrame(
                [
                    _row(
                        "External source present",
                        "SKIP",
                        "Low",
                        "0 rows",
                        "Aucune donnée externe chargée.",
                    )
                ]
            ),
            "schema": schema,
            "family_map": pd.DataFrame(),
            "alignment": pd.DataFrame(),
            "actions": pd.DataFrame(
                [
                    ["P0", "Load external data", "No source data", "Importer earnings/revisions/guidance/options/news avec available_at."],
                    ["P0", "Do not scan alpha", "Adapter not ready", "V4.9C interdit tant que V4.9A/V4.9B ne passent pas."],
                ],
                columns=["Priority", "Action", "Reason", "Next Step"],
            ),
            "clean_features": pd.DataFrame(),
        }

    df = features_df.copy()
    attrs = getattr(features_df, "attrs", {}) if hasattr(features_df, "attrs") else {}
    source_columns = attrs.get("source_columns", list(df.columns))
    if not isinstance(source_columns, list):
        source_columns = list(df.columns)

    required_cols = ["date", "available_at", "ticker", "feature_family", "feature_name", "value", "source"]
    missing_required = [c for c in required_cols if c not in df.columns]

    rows = []

    rows.append(
        _row(
            "External source present",
            "PASS",
            "None",
            f"{len(df)} clean rows",
            "Table externe parsée sans exécution de code utilisateur.",
        )
    )

    if missing_required:
        rows.append(
            _row(
                "Required schema",
                "FAIL",
                "Critical",
                ", ".join(missing_required),
                "Colonnes obligatoires manquantes : adapter non validable.",
            )
        )
    else:
        rows.append(
            _row(
                "Required schema",
                "PASS",
                "None",
                "complete",
                "Schéma minimal V4.9A présent.",
            )
        )

    forbidden_tokens = [
        "future_return",
        "next_return",
        "fwd_return",
        "forward_return",
        "return_next",
        "return_fwd",
        "target_return",
        "target_price",
        "hit_target",
        "label",
        "outcome",
        "pnl",
        "profit",
        "realized_alpha",
        "realized_return",
        "next_close",
        "next_open",
        "future_close",
        "future_price",
        "lookahead",
        "look_ahead",
    ]

    allowed_cols = {
        "date",
        "event_date",
        "observation_date",
        "fiscal_date",
        "period_date",
        "available_at",
        "available_time",
        "published_at",
        "release_time",
        "report_time",
        "asof",
        "as_of",
        "effective_at",
        "ticker",
        "symbol",
        "asset",
        "ric",
        "feature_family",
        "family",
        "data_family",
        "category",
        "type",
        "feature_name",
        "name",
        "metric",
        "field",
        "factor",
        "value",
        "feature_value",
        "metric_value",
        "state",
        "source",
        "provider",
        "vendor",
        "origin",
        "confidence",
        "reliability",
        "quality_score",
        "notes",
        "comment",
        "description",
        "read",
    }

    forbidden_columns = []
    for col in source_columns:
        norm = _v49a_norm_col(col)
        if norm in allowed_cols:
            continue
        if any(tok == norm or tok in norm for tok in forbidden_tokens):
            forbidden_columns.append(str(col))

    if forbidden_columns:
        rows.append(
            _row(
                "Forbidden leakage columns",
                "FAIL",
                "Critical",
                ", ".join(forbidden_columns[:12]),
                "Colonnes future/outcome/target détectées : validation interdite.",
            )
        )
    else:
        rows.append(
            _row(
                "Forbidden leakage columns",
                "PASS",
                "None",
                "0",
                "Aucune colonne explicitement future-looking détectée.",
            )
        )

    date_valid = pd.to_datetime(df.get("date", pd.Series(dtype="datetime64[ns]")), errors="coerce")
    available_valid = pd.to_datetime(df.get("available_at", pd.Series(dtype="datetime64[ns]")), errors="coerce")

    invalid_date_count = int(date_valid.isna().sum()) if "date" in df.columns else len(df)
    invalid_available_count = int(available_valid.isna().sum()) if "available_at" in df.columns else len(df)

    rows.append(
        _row(
            "Event date quality",
            "WARN" if invalid_date_count > 0 else "PASS",
            "Medium" if invalid_date_count > 0 else "None",
            invalid_date_count,
            "Dates événement invalides. Ce n'est pas toujours bloquant si available_at est propre.",
        )
    )

    rows.append(
        _row(
            "available_at mandatory",
            "FAIL" if invalid_available_count > 0 else "PASS",
            "Critical" if invalid_available_count > 0 else "None",
            invalid_available_count,
            "Chaque feature externe doit avoir un timestamp de disponibilité réel.",
        )
    )

    event_available_diff = 0
    try:
        event_available_diff = int(
            (
                date_valid.dt.normalize()
                != available_valid.dt.normalize()
            ).fillna(False).sum()
        )
    except Exception:
        event_available_diff = 0

    rows.append(
        _row(
            "event_date != available_at",
            "INFO" if event_available_diff > 0 else "PASS",
            "Low" if event_available_diff > 0 else "None",
            event_available_diff,
            "Normal pour earnings/news : le backtest devra utiliser available_at, pas la période économique.",
        )
    )

    price_start, price_end = _price_index_bounds(price_index)
    price_window_txt = (
        f"{_format_dt(price_start)} -> {_format_dt(price_end)}"
        if price_start is not None and price_end is not None
        else "N/A"
    )

    rows.append(
        _row(
            "Price calendar",
            "PASS" if price_start is not None and price_end is not None else "WARN",
            "None" if price_start is not None and price_end is not None else "High",
            price_window_txt,
            "Calendrier prix utilisé pour l'alignement des features.",
        )
    )

    target_ticker = str(ticker or "").upper().strip()
    ticker_series = df.get("ticker", pd.Series("", index=df.index)).astype(str).str.upper().str.strip()

    if target_ticker:
        ticker_match = int((ticker_series == target_ticker).sum())
        ticker_other = int((ticker_series != target_ticker).sum())
    else:
        ticker_match = int(ticker_series.astype(bool).sum())
        ticker_other = 0

    rows.append(
        _row(
            "Ticker match",
            "WARN" if ticker_other > 0 else "PASS",
            "Medium" if ticker_other > 0 else "None",
            f"{ticker_match} match / {ticker_other} other",
            "V4.9A contrôle que les features correspondent au ticker audité.",
        )
    )

    alignment = _v49a_align_external_features_to_calendar(df, price_index)
    aligned_count = int(alignment.get("calendar_aligned", pd.Series(dtype=bool)).fillna(False).sum()) if not alignment.empty else 0
    align_rate = aligned_count / max(len(df), 1)

    rows.append(
        _row(
            "Calendar alignment",
            "PASS" if align_rate >= 0.80 else ("WARN" if aligned_count > 0 else "FAIL"),
            "None" if align_rate >= 0.80 else ("Medium" if aligned_count > 0 else "High"),
            f"{aligned_count}/{len(df)}",
            "Nombre de features pouvant être placées sur un jour de trading via available_at.",
        )
    )

    duplicate_count = 0
    try:
        key_cols = [c for c in ["ticker", "feature_family", "feature_name", "available_at"] if c in df.columns]
        if key_cols:
            duplicate_count = int(df.duplicated(subset=key_cols).sum())
    except Exception:
        duplicate_count = 0

    rows.append(
        _row(
            "Duplicate feature keys",
            "WARN" if duplicate_count > 0 else "PASS",
            "Medium" if duplicate_count > 0 else "None",
            duplicate_count,
            "Doublons ticker/family/name/available_at à vérifier.",
        )
    )

    if "feature_family" in df.columns:
        family_map = (
            df.groupby("feature_family", dropna=False)
            .agg(
                rows=("feature_family", "size"),
                feature_count=("feature_name", "nunique"),
                source_count=("source", "nunique"),
                first_available=("available_at", "min"),
                last_available=("available_at", "max"),
            )
            .reset_index()
            .sort_values(["rows", "feature_count"], ascending=[False, False])
        )
    else:
        family_map = pd.DataFrame()

    priority_families = [
        "earnings",
        "revision",
        "analyst_revisions",
        "guidance",
        "forward_estimates",
        "options",
        "iv",
        "skew",
        "gamma",
        "news",
        "macro",
        "factor",
        "volume",
        "fundamental",
    ]

    family_present = set()
    try:
        family_present = set(df["feature_family"].astype(str).map(_v49a_norm_col).unique())
    except Exception:
        family_present = set()

    covered_priority = [
        fam for fam in priority_families
        if any(fam in x or x in fam for x in family_present)
    ]
    family_coverage = len(covered_priority) / max(len(priority_families), 1)

    rows.append(
        _row(
            "Priority family coverage",
            "PASS" if len(covered_priority) >= 3 else ("WARN" if len(covered_priority) >= 1 else "FAIL"),
            "None" if len(covered_priority) >= 3 else ("Medium" if len(covered_priority) >= 1 else "High"),
            f"{len(covered_priority)} priority families",
            "V4.9B aura besoin d'au moins quelques familles externes pour auditer la source.",
        )
    )

    value_missing = int(df["value"].isna().sum()) if "value" in df.columns else len(df)
    value_missing_rate = value_missing / max(len(df), 1)

    rows.append(
        _row(
            "Feature value missingness",
            "PASS" if value_missing_rate <= 0.20 else "WARN",
            "None" if value_missing_rate <= 0.20 else "Medium",
            _format_pct(value_missing_rate),
            "Taux de valeurs manquantes dans les features externes.",
        )
    )

    checks = pd.DataFrame(rows)

    fail_count = int((checks["Status"].astype(str) == "FAIL").sum()) if not checks.empty else 0
    warn_count = int((checks["Status"].astype(str) == "WARN").sum()) if not checks.empty else 0
    critical_count = int(((checks["Status"].astype(str) == "FAIL") & (checks["Severity"].astype(str) == "Critical")).sum()) if not checks.empty else 0
    high_count = int((checks["Severity"].astype(str) == "High").sum()) if not checks.empty else 0
    medium_count = int((checks["Severity"].astype(str) == "Medium").sum()) if not checks.empty else 0
    low_count = int((checks["Severity"].astype(str) == "Low").sum()) if not checks.empty else 0

    score = 100.0
    score -= critical_count * 45.0
    score -= max(0, fail_count - critical_count) * 25.0
    score -= high_count * 12.0
    score -= medium_count * 6.0
    score -= low_count * 2.0
    score += min(10.0, len(covered_priority) * 1.5)
    score = max(0.0, min(100.0, score))

    if critical_count > 0:
        level = "External source blocked"
        decision = "BLOCKED_LEAKAGE_OR_TIMESTAMP"
        read = "Donnée externe bloquée : problème critique de leakage, schéma ou available_at."
    elif aligned_count <= 0:
        level = "External source not aligned"
        decision = "NO_CALENDAR_ALIGNMENT"
        read = "Donnée externe lue mais impossible à aligner sur le calendrier de prix."
    elif len(covered_priority) < 1:
        level = "External source incomplete"
        decision = "NEED_MORE_CATALYST_FAMILIES"
        read = "Donnée externe utilisable techniquement, mais couverture catalyst trop faible."
    elif warn_count > 0 or score < 80:
        level = "External source review"
        decision = "REVIEW_BEFORE_V49B"
        read = "Donnée externe exploitable en audit, mais revue requise avant scanner alpha."
    else:
        level = "External adapter ready"
        decision = "READY_FOR_V49B_FEATURE_AUDIT"
        read = "Adapter externe propre : prêt pour Catalyst Feature Audit V4.9B."

    summary = pd.DataFrame(
        [
            ["V4.9A level", level, "Lecture synthétique de l'adaptateur externe."],
            ["V4.9A score", f"{_format_num(score, 0)}/100", "Score de qualité data, pas score de performance."],
            ["Decision", decision, "Décision research V4.9A."],
            ["Read", read, "Interprétation opérationnelle."],
            ["Ticker", target_ticker or "N/A", "Ticker audité."],
            ["Rows", str(len(df)), "Lignes externes nettoyées."],
            ["Aligned rows", str(aligned_count), "Lignes alignées sur calendrier via available_at."],
            ["Alignment rate", _format_pct(align_rate), "Part des lignes externes alignables."],
            ["Priority families covered", ", ".join(covered_priority) if covered_priority else "None", "Familles externes détectées."],
            ["Forbidden columns", ", ".join(forbidden_columns) if forbidden_columns else "None", "Colonnes suspectes de leakage."],
            ["Missing available_at", str(invalid_available_count), "available_at invalides ou absents."],
            ["Duplicate feature keys", str(duplicate_count), "Doublons à vérifier."],
            ["Do not promote", "PASS", "V4.9A est research-only et ne modifie aucun moteur."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    actions = pd.DataFrame(
        [
            ["P0", "Do not OOS", "External source not alpha-validated", "OOS interdit avant V4.9C/V4.9E positif."],
            ["P0", "Do not promote", "V4.9A is adapter only", "Aucune donnée externe ne doit modifier le moteur."],
            ["P0", "Enforce available_at", "Catalyst leakage risk", "Toute feature sans available_at doit être rejetée ou retraitée."],
            ["P1", "Run V4.9B audit", "Adapter parsed source data", "Auditer coverage, missingness, timestamps, familles, source tags."],
            ["P1", "Prepare V4.9C only after V4.9B", "Need clean feature map", "Scanner alpha uniquement après audit data propre."],
        ],
        columns=["Priority", "Action", "Reason", "Next Step"],
    )

    cards = [
        {"label": "V4.9A adapter", "value": level, "delta": f"{_format_num(score, 0)}/100"},
        {"label": "Rows", "value": str(len(df)), "delta": "external"},
        {"label": "Aligned rows", "value": str(aligned_count), "delta": _format_pct(align_rate, 0)},
        {"label": "Families", "value": str(len(covered_priority)), "delta": "priority"},
        {"label": "Leakage columns", "value": str(len(forbidden_columns)), "delta": "forbidden"},
        {"label": "Decision", "value": decision, "delta": "research only"},
    ]

    alignment_display = alignment.copy()
    if not alignment_display.empty:
        for col in ["date", "available_at", "available_date", "decision_date"]:
            if col in alignment_display.columns:
                alignment_display[col] = alignment_display[col].map(_format_dt)

        keep_cols = [
            "date",
            "available_at",
            "decision_date",
            "ticker",
            "feature_family",
            "feature_name",
            "value",
            "source",
            "confidence",
            "calendar_aligned",
            "notes",
        ]
        alignment_display = alignment_display[[c for c in keep_cols if c in alignment_display.columns]]

    return {
        "enabled": True,
        "level": level,
        "score": score,
        "decision": decision,
        "read": read,
        "cards": cards,
        "summary": summary,
        "checks": checks,
        "schema": schema,
        "family_map": family_map,
        "alignment": alignment_display,
        "actions": actions,
        "clean_features": df,
        "fail_count": fail_count,
        "warn_count": warn_count,
        "critical_count": critical_count,
        "forbidden_columns": forbidden_columns,
        "aligned_count": aligned_count,
        "covered_priority": covered_priority,
    }


def _render_external_source_data_adapter_v49a(
    ticker: str,
    price_index: pd.Index,
    cfg: BacktestConfig | None = None,
    price_data: pd.DataFrame | None = None,
) -> dict[str, Any]:
    st.subheader("External Source Data Adapter V4.9A")
    st.caption(
        "Adaptateur lecture seule après V4.8 : importe des features externes causales "
        "avec available_at, contrôle le leakage, aligne au calendrier de trading et prépare V4.9B. "
        "Aucun signal, aucun trade, aucune equity curve et aucun verdict ne sont modifiés."
    )

    sample = _v49a_sample_external_source(ticker, price_index)

    with st.expander("V4.9A external data input", expanded=True):
        st.markdown("**Format attendu**")
        st.dataframe(_v49a_required_schema(), use_container_width=True, hide_index=True)

        c1, c2 = st.columns([1, 1])

        uploaded = c1.file_uploader(
            "Upload external feature CSV/XLSX",
            type=["csv", "txt", "xlsx", "xls"],
            key="bt_v49a_external_feature_upload",
        )

        pasted = c2.text_area(
            "Ou coller une table CSV externe",
            value="",
            height=180,
            key="bt_v49a_external_feature_paste",
            placeholder=sample,
        )

        st.download_button(
            "Télécharger exemple CSV V4.9A",
            data=sample.encode("utf-8"),
            file_name=f"{str(ticker or 'ticker').upper()}_v49a_external_features_example.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49a_sample_download",
        )

    features_df, status = _parse_external_source_features_v49a(
        uploaded_file=uploaded,
        pasted_text=pasted,
        default_ticker=ticker,
    )

    pack = _external_source_data_adapter_v49a_pack(
        features_df=features_df,
        price_index=price_index,
        ticker=ticker,
    )

    _card_grid(pack.get("cards", []), columns=6)

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))

    if "blocked" in level.lower():
        st.error(f"Lecture V4.9A : {read}")
    elif "review" in level.lower() or "incomplete" in level.lower() or "not aligned" in level.lower():
        st.warning(f"Lecture V4.9A : {read}")
    elif "ready" in level.lower():
        st.success(f"Lecture V4.9A : {read}")
    else:
        st.info(f"Lecture V4.9A : {read}")

    st.caption(status)

    with st.expander("V4.9A adapter summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.9A indisponible.")

    with st.expander("V4.9A safety / leakage / timestamp checks", expanded=True):
        checks = pack.get("checks", pd.DataFrame())
        if isinstance(checks, pd.DataFrame) and not checks.empty:
            st.dataframe(checks, use_container_width=True, hide_index=True)
        else:
            st.info("Checks V4.9A indisponibles.")

    with st.expander("V4.9A family coverage map", expanded=True):
        family_map = pack.get("family_map", pd.DataFrame())
        if isinstance(family_map, pd.DataFrame) and not family_map.empty:
            display = family_map.copy()
            for col in ["first_available", "last_available"]:
                if col in display.columns:
                    display[col] = display[col].map(_format_dt)
            st.dataframe(display, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune famille externe détectée.")

    with st.expander("V4.9A calendar alignment preview", expanded=False):
        alignment = pack.get("alignment", pd.DataFrame())
        if isinstance(alignment, pd.DataFrame) and not alignment.empty:
            st.dataframe(alignment.tail(100), use_container_width=True, hide_index=True)
        else:
            st.info("Aucun alignement calendrier affichable.")

    with st.expander("V4.9A next controlled actions", expanded=True):
        actions = pack.get("actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.9A indisponibles.")

    clean_features = pack.get("clean_features", pd.DataFrame())
    alignment = pack.get("alignment", pd.DataFrame())

    d1, d2 = st.columns(2)

    if isinstance(clean_features, pd.DataFrame) and not clean_features.empty:
        d1.download_button(
            "Télécharger V4.9A clean features CSV",
            data=clean_features.to_csv(index=False).encode("utf-8"),
            file_name=f"{str(ticker or 'ticker').upper()}_v49a_clean_external_features.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49a_clean_download",
        )

    if isinstance(alignment, pd.DataFrame) and not alignment.empty:
        d2.download_button(
            "Télécharger V4.9A alignment CSV",
            data=alignment.to_csv(index=False).encode("utf-8"),
            file_name=f"{str(ticker or 'ticker').upper()}_v49a_external_alignment.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49a_alignment_download",
        )

    # --- V4.9B catalyst feature audit call ---
    v49b_pack = {}

    try:
        v49b_pack = _render_catalyst_feature_audit_v49b(
            v49a_pack=pack,
            price_index=price_index,
            ticker=ticker,
        )

        if isinstance(pack, dict):
            pack["catalyst_feature_audit_v49b"] = v49b_pack

    except Exception as exc:
        st.warning(f"V4.9B Catalyst Feature Audit indisponible : {exc}")
    # --- end V4.9B catalyst feature audit call ---

    # --- V4.9C catalyst raw alpha scanner call ---
    v49c_pack = {}

    try:
        v49c_pack = _render_catalyst_raw_alpha_scanner_v49c(
            v49a_pack=pack,
            v49b_pack=v49b_pack if isinstance(v49b_pack, dict) else {},
            price_data=price_data,
            cfg=cfg,
            ticker=ticker,
        )

        if isinstance(pack, dict):
            pack["catalyst_raw_alpha_scanner_v49c"] = v49c_pack

    except Exception as exc:
        st.warning(f"V4.9C Catalyst Raw Alpha Scanner indisponible : {exc}")
    # --- end V4.9C catalyst raw alpha scanner call ---

    # --- V4.9C.1 external feature refinement protocol call ---
    v49c1_pack = {}

    try:
        v49c1_pack = _render_external_feature_refinement_protocol_v49c1(
            v49c_pack=v49c_pack if isinstance(v49c_pack, dict) else {},
            v49b_pack=v49b_pack if isinstance(v49b_pack, dict) else {},
            ticker=ticker,
        )

        if isinstance(pack, dict):
            pack["external_feature_refinement_protocol_v49c1"] = v49c1_pack

    except Exception as exc:
        st.warning(f"V4.9C.1 External Feature Refinement Protocol indisponible : {exc}")
    # --- end V4.9C.1 external feature refinement protocol call ---

    # --- V4.9D multi-benchmark active return map call ---
    try:
        v49d_pack = _render_multi_benchmark_active_return_map_v49d(
            v49c_pack=v49c_pack if isinstance(v49c_pack, dict) else {},
            v49c1_pack=v49c1_pack if isinstance(v49c1_pack, dict) else {},
            price_data=price_data,
            cfg=cfg,
            ticker=ticker,
            v49a_pack=pack if isinstance(pack, dict) else {},
            v49b_pack=v49b_pack if isinstance(v49b_pack, dict) else {},
        )

        if isinstance(pack, dict):
            pack["multi_benchmark_active_return_map_v49d"] = v49d_pack

    except Exception as exc:
        st.warning(f"V4.9D Multi-Benchmark Active Return Map indisponible : {exc}")
    # --- end V4.9D multi-benchmark active return map call ---

    return pack

# ============================================================
# END EXTERNAL SOURCE DATA ADAPTER V4.9A
# ============================================================


# ============================================================
# CATALYST FEATURE AUDIT V4.9B
# ============================================================
# Research-only audit after V4.9A.
# Purpose:
# - audit external feature quality before alpha scanning;
# - measure sample size, family coverage, missingness, timestamp quality,
#   source quality, concentration and readiness for V4.9C;
# - never generate signals;
# - never modify backtest engine, equity curve, trades or verdict.

def _v49b_norm(value: Any) -> str:
    try:
        return (
            str(value or "")
            .strip()
            .lower()
            .replace(" ", "_")
            .replace("-", "_")
            .replace("/", "_")
        )
    except Exception:
        return ""


def _v49b_dt_series(series: Any) -> pd.Series:
    try:
        return pd.to_datetime(series, errors="coerce")
    except Exception:
        return pd.Series(dtype="datetime64[ns]")


def _v49b_concentration_share(values: pd.Series) -> float:
    try:
        s = pd.Series(values).dropna()
        if s.empty:
            return np.nan
        counts = s.astype(str).value_counts()
        return float(counts.iloc[0] / max(len(s), 1))
    except Exception:
        return np.nan


def _v49b_feature_missing_rate(df: pd.DataFrame) -> float:
    try:
        if df is None or df.empty or "value" not in df.columns:
            return np.nan
        return float(df["value"].isna().mean())
    except Exception:
        return np.nan


def _v49b_build_feature_audit(
    features: pd.DataFrame,
    alignment: pd.DataFrame,
) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    """
    Tables d'audit détaillées.
    Lecture seule.
    """
    if features is None or not isinstance(features, pd.DataFrame) or features.empty:
        return pd.DataFrame(), pd.DataFrame(), pd.DataFrame(), pd.DataFrame()

    df = features.copy()

    for col in ["feature_family", "feature_name", "ticker", "source"]:
        if col not in df.columns:
            df[col] = "unknown"

    if "confidence" not in df.columns:
        df["confidence"] = np.nan

    if "value" not in df.columns:
        df["value"] = np.nan

    df["feature_family"] = df["feature_family"].map(_v49b_norm)
    df["feature_name"] = df["feature_name"].map(_v49b_norm)
    df["source"] = df["source"].astype(str).str.strip().replace("", "unknown")

    date_s = _v49b_dt_series(df.get("date"))
    available_s = _v49b_dt_series(df.get("available_at"))

    df["_date"] = date_s
    df["_available_at"] = available_s
    df["_value_missing"] = df["value"].isna()
    df["_confidence_num"] = pd.to_numeric(df["confidence"], errors="coerce")

    if alignment is not None and isinstance(alignment, pd.DataFrame) and not alignment.empty:
        align = alignment.copy()
        if "decision_date" in align.columns:
            align["_decision_date"] = _v49b_dt_series(align["decision_date"])
        else:
            align["_decision_date"] = pd.NaT
    else:
        align = pd.DataFrame()

    family_rows = []

    for fam, grp in df.groupby("feature_family", dropna=False):
        fam_txt = str(fam or "unknown")
        rows = int(len(grp))
        feature_count = int(grp["feature_name"].nunique())
        source_count = int(grp["source"].nunique())
        missing_rate = float(grp["_value_missing"].mean())
        avg_conf = float(grp["_confidence_num"].dropna().mean()) if grp["_confidence_num"].notna().any() else np.nan
        first_avail = grp["_available_at"].dropna().min() if grp["_available_at"].notna().any() else pd.NaT
        last_avail = grp["_available_at"].dropna().max() if grp["_available_at"].notna().any() else pd.NaT
        concentration = _v49b_concentration_share(grp["_available_at"].dt.normalize())

        if rows < 5:
            sample_status = "LOW_SAMPLE"
        elif rows < 20:
            sample_status = "THIN"
        else:
            sample_status = "USABLE"

        if missing_rate > 0.40:
            quality = "WEAK_MISSINGNESS"
        elif source_count <= 1 and rows >= 10:
            quality = "SOURCE_CONCENTRATED"
        elif sample_status == "USABLE":
            quality = "AUDITABLE"
        else:
            quality = sample_status

        family_rows.append(
            {
                "Feature family": fam_txt,
                "Rows": rows,
                "Feature count": feature_count,
                "Source count": source_count,
                "Missing rate": missing_rate,
                "Avg confidence": avg_conf,
                "First available": first_avail,
                "Last available": last_avail,
                "Date concentration": concentration,
                "Sample status": sample_status,
                "Audit quality": quality,
            }
        )

    family_audit = pd.DataFrame(family_rows)

    if not family_audit.empty:
        family_audit = family_audit.sort_values(
            ["Rows", "Feature count"],
            ascending=[False, False],
        ).reset_index(drop=True)

    feature_rows = []

    for (fam, name), grp in df.groupby(["feature_family", "feature_name"], dropna=False):
        rows = int(len(grp))
        value_missing = float(grp["_value_missing"].mean())
        source_count = int(grp["source"].nunique())
        confidence_avg = float(grp["_confidence_num"].dropna().mean()) if grp["_confidence_num"].notna().any() else np.nan
        numeric_values = pd.to_numeric(grp["value"], errors="coerce")
        numeric_share = float(numeric_values.notna().mean())
        unique_values = int(grp["value"].astype(str).nunique(dropna=True))
        top_date_share = _v49b_concentration_share(grp["_available_at"].dt.normalize())

        if rows < 3:
            audit_label = "TOO_RARE"
        elif value_missing > 0.40:
            audit_label = "MISSING_HEAVY"
        elif numeric_share < 0.20 and unique_values <= 1:
            audit_label = "LOW_INFORMATION"
        elif top_date_share > 0.60 and rows >= 5:
            audit_label = "DATE_CONCENTRATED"
        else:
            audit_label = "AUDITABLE"

        feature_rows.append(
            {
                "Feature family": str(fam),
                "Feature name": str(name),
                "Rows": rows,
                "Missing rate": value_missing,
                "Numeric share": numeric_share,
                "Unique values": unique_values,
                "Source count": source_count,
                "Avg confidence": confidence_avg,
                "Top date concentration": top_date_share,
                "Audit label": audit_label,
            }
        )

    feature_audit = pd.DataFrame(feature_rows)

    if not feature_audit.empty:
        feature_audit = feature_audit.sort_values(
            ["Rows", "Feature family", "Feature name"],
            ascending=[False, True, True],
        ).reset_index(drop=True)

    if "source" in df.columns:
        source_audit = (
            df.groupby("source", dropna=False)
            .agg(
                rows=("source", "size"),
                family_count=("feature_family", "nunique"),
                feature_count=("feature_name", "nunique"),
                avg_confidence=("_confidence_num", "mean"),
                missing_rate=("_value_missing", "mean"),
                first_available=("_available_at", "min"),
                last_available=("_available_at", "max"),
            )
            .reset_index()
            .sort_values(["rows", "family_count"], ascending=[False, False])
        )
    else:
        source_audit = pd.DataFrame()

    timestamp_rows = []

    n = max(len(df), 1)
    valid_date = int(df["_date"].notna().sum())
    valid_available = int(df["_available_at"].notna().sum())
    same_day = int((df["_date"].dt.normalize() == df["_available_at"].dt.normalize()).fillna(False).sum())
    available_after_event = int((df["_available_at"] >= df["_date"]).fillna(False).sum())

    if df["_available_at"].notna().any():
        first_available = df["_available_at"].dropna().min()
        last_available = df["_available_at"].dropna().max()
        span_days = max((last_available - first_available).days, 0)
    else:
        first_available = pd.NaT
        last_available = pd.NaT
        span_days = 0

    if align is not None and not align.empty and "calendar_aligned" in align.columns:
        aligned_rows = int(pd.Series(align["calendar_aligned"]).fillna(False).astype(bool).sum())
    else:
        aligned_rows = 0

    align_rate = aligned_rows / n

    if align is not None and not align.empty and "_decision_date" in align.columns:
        decision_concentration = _v49b_concentration_share(align["_decision_date"].dt.normalize())
    else:
        decision_concentration = np.nan

    timestamp_rows.extend(
        [
            ["Rows", str(len(df)), "Nombre de lignes externes auditées."],
            ["Valid event dates", f"{valid_date}/{n}", "Dates événement lisibles."],
            ["Valid available_at", f"{valid_available}/{n}", "Timestamps de disponibilité lisibles."],
            ["Same-day event/available", f"{same_day}/{n}", "Cas où event_date et available_at tombent le même jour."],
            ["available_at >= event date", f"{available_after_event}/{n}", "Cohérence causale minimale date/available_at."],
            ["First available", _format_dt(first_available), "Premier timestamp disponible."],
            ["Last available", _format_dt(last_available), "Dernier timestamp disponible."],
            ["Available span days", str(span_days), "Amplitude temporelle couverte par la source externe."],
            ["Calendar aligned rows", f"{aligned_rows}/{n}", "Lignes alignées au calendrier de prix."],
            ["Calendar alignment rate", _format_pct(align_rate), "Part des lignes alignables."],
            ["Decision-date concentration", _format_pct(decision_concentration), "Concentration des features sur une seule date de décision."],
        ]
    )

    timestamp_audit = pd.DataFrame(timestamp_rows, columns=["Metric", "Value", "Read"])

    return family_audit, feature_audit, source_audit, timestamp_audit


def _catalyst_feature_audit_v49b_pack(
    v49a_pack: dict[str, Any],
    price_index: pd.Index,
    ticker: str = "",
) -> dict[str, Any]:
    """
    V4.9B — Catalyst Feature Audit.

    Lecture seule :
    - audite la table externe nettoyée par V4.9A ;
    - ne calcule aucun alpha ;
    - ne génère aucun signal ;
    - ne modifie pas le moteur courant.
    """
    v49a_pack = v49a_pack if isinstance(v49a_pack, dict) else {}

    empty = {
        "enabled": False,
        "level": "Waiting for V4.9A",
        "score": 0.0,
        "decision": "WAITING_FOR_V49A",
        "read": "V4.9B attend une table externe validée par V4.9A.",
        "cards": [],
        "summary": pd.DataFrame(),
        "checks": pd.DataFrame(),
        "family_audit": pd.DataFrame(),
        "feature_audit": pd.DataFrame(),
        "source_audit": pd.DataFrame(),
        "timestamp_audit": pd.DataFrame(),
        "readiness": pd.DataFrame(),
        "actions": pd.DataFrame(),
    }

    try:
        features = v49a_pack.get("clean_features", pd.DataFrame())
        alignment = v49a_pack.get("alignment", pd.DataFrame())
        v49a_decision = str(v49a_pack.get("decision", "N/A"))

        if features is None or not isinstance(features, pd.DataFrame) or features.empty:
            out = empty.copy()
            out["cards"] = [
                {"label": "V4.9B audit", "value": "Waiting data", "delta": "no external rows"},
                {"label": "Rows", "value": "0", "delta": "external"},
                {"label": "Decision", "value": "WAITING_FOR_V49A", "delta": "research only"},
            ]
            out["summary"] = pd.DataFrame(
                [
                    ["V4.9B level", "Waiting for external features", "Aucune feature externe à auditer."],
                    ["V4.9B score", "0/100", "Non applicable sans données."],
                    ["Decision", "WAITING_FOR_V49A", "Importer/valider une table V4.9A d'abord."],
                    ["Read", out["read"], "Interprétation opérationnelle."],
                ],
                columns=["Metric", "Value", "Read"],
            )
            out["actions"] = pd.DataFrame(
                [
                    ["P0", "Load external features", "No V4.9A data", "Uploader/coller une table externe avec available_at."],
                    ["P0", "Do not run V4.9C", "No feature audit", "Scanner alpha interdit tant que V4.9B n'a pas audité les données."],
                ],
                columns=["Priority", "Action", "Reason", "Next Step"],
            )
            return out

        df = features.copy()

        for col in ["feature_family", "feature_name", "source", "ticker"]:
            if col not in df.columns:
                df[col] = "unknown"

        if "value" not in df.columns:
            df["value"] = np.nan

        if "confidence" not in df.columns:
            df["confidence"] = np.nan

        df["feature_family"] = df["feature_family"].map(_v49b_norm)
        df["feature_name"] = df["feature_name"].map(_v49b_norm)
        df["source"] = df["source"].astype(str).str.strip().replace("", "unknown")
        df["confidence"] = pd.to_numeric(df["confidence"], errors="coerce")

        family_audit, feature_audit, source_audit, timestamp_audit = _v49b_build_feature_audit(df, alignment)

        n = int(len(df))
        families = sorted([x for x in df["feature_family"].dropna().unique() if str(x).strip()])
        family_count = len(families)
        feature_count = int(df["feature_name"].nunique())
        source_count = int(df["source"].nunique())
        missing_rate = _v49b_feature_missing_rate(df)
        avg_confidence = float(df["confidence"].dropna().mean()) if df["confidence"].notna().any() else np.nan

        priority_families = [
            "earnings",
            "revision",
            "analyst_revisions",
            "guidance",
            "forward_estimates",
            "options",
            "iv",
            "skew",
            "gamma",
            "news",
            "macro",
            "factor",
            "volume",
            "fundamental",
        ]

        covered_priority = [
            fam for fam in priority_families
            if any(fam in str(x) or str(x) in fam for x in families)
        ]

        if alignment is not None and isinstance(alignment, pd.DataFrame) and not alignment.empty and "calendar_aligned" in alignment.columns:
            aligned_count = int(pd.Series(alignment["calendar_aligned"]).fillna(False).astype(bool).sum())
        else:
            aligned_count = int(v49a_pack.get("aligned_count", 0) or 0)

        alignment_rate = aligned_count / max(n, 1)

        available_at = _v49b_dt_series(df.get("available_at", pd.Series(pd.NaT, index=df.index)))
        date_s = _v49b_dt_series(df.get("date", pd.Series(pd.NaT, index=df.index)))

        invalid_available = int(available_at.isna().sum())
        invalid_dates = int(date_s.isna().sum())

        if available_at.notna().any():
            span_days = int(max((available_at.dropna().max() - available_at.dropna().min()).days, 0))
        else:
            span_days = 0

        duplicate_count = 0
        try:
            duplicate_count = int(df.duplicated(subset=["ticker", "feature_family", "feature_name", "available_at"]).sum())
        except Exception:
            duplicate_count = 0

        concentration = _v49b_concentration_share(available_at.dt.normalize())

        checks_rows = []

        def _check(name: str, status: str, severity: str, value: Any, read: str) -> None:
            checks_rows.append(
                {
                    "Check": str(name),
                    "Status": str(status),
                    "Severity": str(severity),
                    "Value": str(value),
                    "Read": str(read),
                }
            )

        _check(
            "V4.9A readiness",
            "PASS" if v49a_decision in {"READY_FOR_V49B_FEATURE_AUDIT", "REVIEW_BEFORE_V49B"} else "FAIL",
            "Critical" if v49a_decision.startswith("BLOCKED") else "Medium",
            v49a_decision,
            "V4.9B doit partir d'un adaptateur V4.9A propre ou au moins reviewable.",
        )

        _check(
            "External rows",
            "PASS" if n >= 50 else ("WARN" if n >= 10 else "WARN"),
            "None" if n >= 50 else ("Medium" if n >= 10 else "High"),
            n,
            "Échantillon externe. Moins de 20 lignes = audit technique seulement, pas alpha scanner.",
        )

        _check(
            "Priority family coverage",
            "PASS" if len(covered_priority) >= 4 else ("WARN" if len(covered_priority) >= 2 else "FAIL"),
            "None" if len(covered_priority) >= 4 else ("Medium" if len(covered_priority) >= 2 else "High"),
            ", ".join(covered_priority) if covered_priority else "None",
            "Couverture des familles causales prioritaires.",
        )

        _check(
            "Feature diversity",
            "PASS" if feature_count >= 10 else ("WARN" if feature_count >= 4 else "FAIL"),
            "None" if feature_count >= 10 else ("Medium" if feature_count >= 4 else "High"),
            feature_count,
            "Nombre de features distinctes disponibles.",
        )

        _check(
            "Calendar alignment",
            "PASS" if alignment_rate >= 0.90 else ("WARN" if alignment_rate >= 0.75 else "FAIL"),
            "None" if alignment_rate >= 0.90 else ("Medium" if alignment_rate >= 0.75 else "High"),
            f"{aligned_count}/{n}",
            "Part des features alignables sur le calendrier prix via available_at.",
        )

        _check(
            "available_at quality",
            "PASS" if invalid_available == 0 else "FAIL",
            "None" if invalid_available == 0 else "Critical",
            invalid_available,
            "available_at doit être valide pour toute feature externe.",
        )

        _check(
            "event date quality",
            "PASS" if invalid_dates == 0 else "WARN",
            "None" if invalid_dates == 0 else "Medium",
            invalid_dates,
            "Dates événement invalides. Moins critique que available_at, mais à auditer.",
        )

        _check(
            "Feature missingness",
            "PASS" if pd.notna(missing_rate) and missing_rate <= 0.20 else "WARN",
            "None" if pd.notna(missing_rate) and missing_rate <= 0.20 else "Medium",
            _format_pct(missing_rate),
            "Taux de valeurs manquantes sur les features externes.",
        )

        _check(
            "Source diversity",
            "PASS" if source_count >= 3 else "WARN",
            "None" if source_count >= 3 else "Medium",
            source_count,
            "Une seule source est acceptable pour test technique, mais fragile pour validation.",
        )

        _check(
            "Confidence quality",
            "PASS" if pd.notna(avg_confidence) and avg_confidence >= 0.70 else "WARN",
            "None" if pd.notna(avg_confidence) and avg_confidence >= 0.70 else "Low",
            _format_num(avg_confidence),
            "Score de confiance moyen si fourni.",
        )

        _check(
            "Duplicate feature keys",
            "PASS" if duplicate_count == 0 else "WARN",
            "None" if duplicate_count == 0 else "Medium",
            duplicate_count,
            "Doublons ticker/family/name/available_at à contrôler.",
        )

        _check(
            "Date concentration",
            "PASS" if pd.isna(concentration) or concentration <= 0.50 else "WARN",
            "None" if pd.isna(concentration) or concentration <= 0.50 else "Medium",
            _format_pct(concentration),
            "Concentration excessive sur une seule date = sample fragile.",
        )

        _check(
            "Time span",
            "PASS" if span_days >= 180 else ("WARN" if span_days >= 30 else "WARN"),
            "None" if span_days >= 180 else "Medium",
            f"{span_days} days",
            "Amplitude temporelle couverte par les features externes.",
        )

        checks = pd.DataFrame(checks_rows)

        fail_count = int((checks["Status"].astype(str) == "FAIL").sum())
        warn_count = int((checks["Status"].astype(str) == "WARN").sum())
        critical_count = int(((checks["Status"].astype(str) == "FAIL") & (checks["Severity"].astype(str) == "Critical")).sum())
        high_count = int((checks["Severity"].astype(str) == "High").sum())
        medium_count = int((checks["Severity"].astype(str) == "Medium").sum())
        low_count = int((checks["Severity"].astype(str) == "Low").sum())

        score = 100.0
        score -= critical_count * 45.0
        score -= max(0, fail_count - critical_count) * 22.0
        score -= high_count * 12.0
        score -= medium_count * 6.0
        score -= low_count * 2.0

        if n < 10:
            score -= 18.0
        elif n < 20:
            score -= 10.0

        if len(covered_priority) >= 4:
            score += 4.0

        score = max(0.0, min(100.0, score))

        if critical_count > 0 or fail_count > 0:
            level = "Feature audit blocked"
            decision = "BLOCK_V49C_FEATURE_AUDIT_FAIL"
            read = "V4.9B bloque V4.9C : problème critique de schema, timestamps, familles ou alignement."
        elif n < 20:
            level = "Technically valid / low sample"
            decision = "TECHNICALLY_VALID_BUT_LOW_SAMPLE"
            read = (
                "V4.9B valide la structure externe, mais l'échantillon est trop faible pour scanner l'alpha. "
                "Il faut charger plus de lignes réelles avant V4.9C."
            )
        elif warn_count > 0 or score < 80:
            level = "Feature audit review"
            decision = "REVIEW_BEFORE_V49C"
            read = "V4.9B autorise une revue data, mais pas encore un scanner alpha automatique."
        else:
            level = "Feature audit ready"
            decision = "READY_FOR_V49C_CATALYST_ALPHA_SCANNER"
            read = "V4.9B valide la qualité minimale des features externes : V4.9C peut être préparé."

        summary = pd.DataFrame(
            [
                ["V4.9B level", level, "Lecture synthétique de l'audit des features externes."],
                ["V4.9B score", f"{_format_num(score, 0)}/100", "Score qualité data, pas score alpha."],
                ["Decision", decision, "Décision research V4.9B."],
                ["Read", read, "Interprétation opérationnelle."],
                ["Ticker", str(ticker or "N/A").upper(), "Ticker audité."],
                ["V4.9A input", v49a_decision, "Décision de l'adaptateur précédent."],
                ["Rows", str(n), "Lignes externes nettoyées."],
                ["Feature families", str(family_count), "Nombre de familles détectées."],
                ["Features", str(feature_count), "Nombre de feature_name distincts."],
                ["Sources", str(source_count), "Nombre de sources/providers."],
                ["Priority families covered", ", ".join(covered_priority) if covered_priority else "None", "Familles prioritaires couvertes."],
                ["Alignment rate", _format_pct(alignment_rate), "Taux d'alignement calendrier."],
                ["Missing rate", _format_pct(missing_rate), "Taux de valeurs manquantes."],
                ["Average confidence", _format_num(avg_confidence), "Confiance moyenne si disponible."],
                ["Date concentration", _format_pct(concentration), "Part de la date la plus représentée."],
                ["Available span", f"{span_days} days", "Amplitude temporelle de available_at."],
                ["Warnings", str(warn_count), "Nombre d'avertissements."],
                ["Fails", str(fail_count), "Nombre d'échecs."],
                ["Do not promote", "PASS", "V4.9B ne modifie aucun moteur."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        readiness = pd.DataFrame(
            [
                [
                    "V4.9C prerequisite",
                    "Enough external sample",
                    "Minimum pratique : idéalement 50+ lignes, plusieurs dates, plusieurs familles.",
                    "PASS" if n >= 50 else "NOT YET",
                ],
                [
                    "V4.9C prerequisite",
                    "Clean available_at",
                    "Aucun timestamp manquant ou invalide.",
                    "PASS" if invalid_available == 0 else "FAIL",
                ],
                [
                    "V4.9C prerequisite",
                    "Calendar alignment",
                    "Features alignées sur le calendrier de prix via available_at.",
                    "PASS" if alignment_rate >= 0.90 else "REVIEW",
                ],
                [
                    "V4.9C prerequisite",
                    "Family coverage",
                    "Earnings/revisions/guidance/options/news/macro/factor selon disponibilité.",
                    "PASS" if len(covered_priority) >= 4 else "REVIEW",
                ],
                [
                    "V4.9C forbidden",
                    "No alpha scan yet",
                    "V4.9B ne teste pas la performance forward.",
                    "ENFORCED",
                ],
            ],
            columns=["Block", "Requirement", "Read", "Status"],
        )

        actions = pd.DataFrame(
            [
                [
                    "P0",
                    "Do not run OOS",
                    "No alpha scanner yet",
                    "OOS interdit avant V4.9C/V4.9E positif.",
                ],
                [
                    "P0",
                    "Do not promote",
                    "V4.9B is data audit only",
                    "Aucune feature externe ne doit modifier le moteur courant.",
                ],
                [
                    "P0",
                    "Increase external sample",
                    f"Rows={n}",
                    "Charger des données réelles sur plus de dates avant V4.9C.",
                ],
                [
                    "P1",
                    "Improve family coverage",
                    f"Families={family_count}",
                    "Ajouter earnings/revisions/guidance/options/news/macro/factor selon disponibilité.",
                ],
                [
                    "P1",
                    "Prepare V4.9C only after audit readiness",
                    decision,
                    "Scanner alpha externe seulement si sample et timestamps sont suffisants.",
                ],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        cards = [
            {"label": "V4.9B audit", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Rows", "value": str(n), "delta": "external"},
            {"label": "Families", "value": str(family_count), "delta": "coverage"},
            {"label": "Features", "value": str(feature_count), "delta": "names"},
            {"label": "Missingness", "value": _format_pct(missing_rate, 0), "delta": "value"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "checks": checks,
            "family_audit": family_audit,
            "feature_audit": feature_audit,
            "source_audit": source_audit,
            "timestamp_audit": timestamp_audit,
            "readiness": readiness,
            "actions": actions,
            "clean_features": df,
            "covered_priority": covered_priority,
            "fail_count": fail_count,
            "warn_count": warn_count,
        }

    except Exception as exc:
        out = empty.copy()
        out["enabled"] = True
        out["level"] = "Feature audit error"
        out["score"] = 0.0
        out["decision"] = "ERROR"
        out["read"] = f"Erreur V4.9B : {exc}"
        out["summary"] = pd.DataFrame(
            [["Error", str(exc), "Erreur capturée sans interrompre le backtest."]],
            columns=["Metric", "Value", "Read"],
        )
        return out


def _v49b_display_family_audit(table: pd.DataFrame) -> pd.DataFrame:
    if table is None or not isinstance(table, pd.DataFrame) or table.empty:
        return pd.DataFrame()

    out = table.copy()

    for col in ["Missing rate", "Date concentration"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_pct(x))

    for col in ["Avg confidence"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_num(x))

    for col in ["First available", "Last available"]:
        if col in out.columns:
            out[col] = out[col].map(_format_dt)

    return out


def _v49b_display_feature_audit(table: pd.DataFrame) -> pd.DataFrame:
    if table is None or not isinstance(table, pd.DataFrame) or table.empty:
        return pd.DataFrame()

    out = table.copy()

    for col in ["Missing rate", "Numeric share", "Top date concentration"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_pct(x))

    for col in ["Avg confidence"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_num(x))

    return out


def _v49b_display_source_audit(table: pd.DataFrame) -> pd.DataFrame:
    if table is None or not isinstance(table, pd.DataFrame) or table.empty:
        return pd.DataFrame()

    out = table.copy()

    for col in ["avg_confidence"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_num(x))

    for col in ["missing_rate"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_pct(x))

    for col in ["first_available", "last_available"]:
        if col in out.columns:
            out[col] = out[col].map(_format_dt)

    return out


def _render_catalyst_feature_audit_v49b(
    v49a_pack: dict[str, Any],
    price_index: pd.Index,
    ticker: str = "",
) -> dict[str, Any]:
    pack = _catalyst_feature_audit_v49b_pack(
        v49a_pack=v49a_pack,
        price_index=price_index,
        ticker=ticker,
    )

    st.subheader("Catalyst Feature Audit V4.9B")
    st.caption(
        "Audit lecture seule après V4.9A : contrôle sample, familles, features, missingness, "
        "timestamps available_at, sources/providers, concentration par date et readiness V4.9C. "
        "Aucun alpha, aucun signal, aucun trade, aucune equity curve et aucun verdict ne sont modifiés."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))

    if "blocked" in level.lower() or "error" in level.lower():
        st.error(f"Lecture V4.9B : {read}")
    elif "low sample" in level.lower() or "review" in level.lower() or "waiting" in level.lower():
        st.warning(f"Lecture V4.9B : {read}")
    elif "ready" in level.lower():
        st.success(f"Lecture V4.9B : {read}")
    else:
        st.info(f"Lecture V4.9B : {read}")

    with st.expander("V4.9B feature audit summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.9B indisponible.")

    with st.expander("V4.9B readiness checks", expanded=True):
        checks = pack.get("checks", pd.DataFrame())
        if isinstance(checks, pd.DataFrame) and not checks.empty:
            st.dataframe(checks, use_container_width=True, hide_index=True)
        else:
            st.info("Checks V4.9B indisponibles.")

    with st.expander("V4.9B family audit map", expanded=True):
        family = _v49b_display_family_audit(pack.get("family_audit", pd.DataFrame()))
        if isinstance(family, pd.DataFrame) and not family.empty:
            st.dataframe(family, use_container_width=True, hide_index=True)
        else:
            st.info("Family audit V4.9B indisponible.")

    with st.expander("V4.9B feature audit map", expanded=True):
        feature = _v49b_display_feature_audit(pack.get("feature_audit", pd.DataFrame()))
        if isinstance(feature, pd.DataFrame) and not feature.empty:
            st.dataframe(feature, use_container_width=True, hide_index=True)
        else:
            st.info("Feature audit V4.9B indisponible.")

    with st.expander("V4.9B source/provider audit", expanded=False):
        source = _v49b_display_source_audit(pack.get("source_audit", pd.DataFrame()))
        if isinstance(source, pd.DataFrame) and not source.empty:
            st.dataframe(source, use_container_width=True, hide_index=True)
        else:
            st.info("Source audit V4.9B indisponible.")

    with st.expander("V4.9B timestamp / coverage audit", expanded=False):
        ts = pack.get("timestamp_audit", pd.DataFrame())
        if isinstance(ts, pd.DataFrame) and not ts.empty:
            st.dataframe(ts, use_container_width=True, hide_index=True)
        else:
            st.info("Timestamp audit V4.9B indisponible.")

    with st.expander("V4.9C readiness blueprint", expanded=True):
        readiness = pack.get("readiness", pd.DataFrame())
        if isinstance(readiness, pd.DataFrame) and not readiness.empty:
            st.dataframe(readiness, use_container_width=True, hide_index=True)
        else:
            st.info("Readiness V4.9C indisponible.")

    with st.expander("V4.9B next controlled actions", expanded=True):
        actions = pack.get("actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.9B indisponibles.")

    clean = pack.get("clean_features", pd.DataFrame())

    if isinstance(clean, pd.DataFrame) and not clean.empty:
        st.download_button(
            "Télécharger V4.9B audited features CSV",
            data=clean.to_csv(index=False).encode("utf-8"),
            file_name=f"{str(ticker or 'ticker').upper()}_v49b_audited_external_features.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49b_audited_features_download",
        )

    # --- V4.9B.1 external data expansion protocol call ---
    try:
        v49b1_pack = _render_external_data_expansion_protocol_v49b1(
            v49a_pack=v49a_pack,
            v49b_pack=pack,
            ticker=ticker,
        )

        if isinstance(pack, dict):
            pack["external_data_expansion_protocol_v49b1"] = v49b1_pack

    except Exception as exc:
        st.warning(f"V4.9B.1 External Data Expansion Protocol indisponible : {exc}")
    # --- end V4.9B.1 external data expansion protocol call ---

    return pack

# ============================================================
# END CATALYST FEATURE AUDIT V4.9B
# ============================================================

# ============================================================
# EXTERNAL DATA EXPANSION PROTOCOL V4.9B.1
# ============================================================
# Research-only protocol after V4.9B.
# Purpose:
# - turn the V4.9B low-sample gate into a concrete data acquisition plan;
# - define target rows, required families, schemas, accepted sources,
#   available_at rules and V4.9C pass thresholds;
# - never scan alpha;
# - never generate a signal;
# - never modify engine, trades, equity curve or verdict.

def _v49b1_safe_int(value: Any, default: int = 0) -> int:
    try:
        if value is None or pd.isna(value):
            return default
        return int(float(value))
    except Exception:
        return default


def _v49b1_pack(
    v49a_pack: dict[str, Any],
    v49b_pack: dict[str, Any],
    ticker: str = "",
) -> dict[str, Any]:
    v49a_pack = v49a_pack if isinstance(v49a_pack, dict) else {}
    v49b_pack = v49b_pack if isinstance(v49b_pack, dict) else {}

    features = v49a_pack.get("clean_features", pd.DataFrame())
    v49a_decision = str(v49a_pack.get("decision", "N/A"))
    v49b_decision = str(v49b_pack.get("decision", "N/A"))

    if isinstance(features, pd.DataFrame) and not features.empty:
        rows = int(len(features))
        families = sorted(
            [
                str(x)
                for x in features.get("feature_family", pd.Series(dtype=object))
                .dropna()
                .astype(str)
                .unique()
                if str(x).strip()
            ]
        )
        feature_count = int(features.get("feature_name", pd.Series(dtype=object)).nunique())
        source_count = int(features.get("source", pd.Series(dtype=object)).nunique())
    else:
        rows = 0
        families = []
        feature_count = 0
        source_count = 0

    minimum_rows = 50
    preferred_rows = 100
    institutional_rows = 250

    missing_to_minimum = max(minimum_rows - rows, 0)
    missing_to_preferred = max(preferred_rows - rows, 0)

    target_families = [
        "earnings",
        "revision",
        "guidance",
        "options",
        "news",
        "macro",
        "factor",
        "volume",
        "fundamental",
    ]

    current_family_set = {str(x).lower().strip() for x in families}

    def _covered(target: str) -> bool:
        return any(target in fam or fam in target for fam in current_family_set)

    acquisition_rows = []

    family_specs = [
        {
            "family": "earnings",
            "priority": "P0",
            "target_rows": 20,
            "fields": "date, available_at, ticker, fiscal_period, eps_actual, eps_estimate, eps_surprise_pct, revenue_actual, revenue_estimate, revenue_surprise_pct",
            "source": "earnings calendar / provider export / manual point-in-time file",
            "why": "Tester post-earnings drift et surprise continuation.",
        },
        {
            "family": "revision",
            "priority": "P0",
            "target_rows": 20,
            "fields": "date, available_at, ticker, metric, old_estimate, new_estimate, revision_pct, horizon, broker/source",
            "source": "analyst revision feed / estimate history export",
            "why": "Tester estimate revision momentum.",
        },
        {
            "family": "guidance",
            "priority": "P0",
            "target_rows": 15,
            "fields": "date, available_at, ticker, guidance_metric, old_guidance, new_guidance, guidance_change_pct, source",
            "source": "company releases / transcript-derived table / provider export",
            "why": "Tester forward guidance repricing.",
        },
        {
            "family": "options",
            "priority": "P0",
            "target_rows": 60,
            "fields": "date, available_at, ticker, expiry, atm_iv, iv_rank, skew_25d, term_slope, put_call_ratio, gamma_proxy",
            "source": "options EOD snapshots / IV provider / broker export",
            "why": "Tester IV squeeze, event-vol et positioning proxy.",
        },
        {
            "family": "news",
            "priority": "P1",
            "target_rows": 30,
            "fields": "date, available_at, ticker, headline, catalyst_tag, severity, source, confidence",
            "source": "news API / curated manual catalyst log",
            "why": "Séparer AI/datacenter/order/regulatory catalysts du bruit.",
        },
        {
            "family": "factor",
            "priority": "P1",
            "target_rows": 252,
            "fields": "date, available_at, ticker, benchmark_symbol, benchmark_return, qqq_return, xlk_return, smh_return, spy_return",
            "source": "Yahoo/FMP/provider benchmark OHLCV",
            "why": "Construire V4.9D multi-benchmark active return map.",
        },
        {
            "family": "macro",
            "priority": "P2",
            "target_rows": 252,
            "fields": "date, available_at, ticker, ust10y, dxy_or_uup, vix_or_vixy, qqq_regime, liquidity_proxy",
            "source": "macro proxies / ETF proxies / rates data",
            "why": "Conditionner l’alpha aux régimes rates/liquidité/risk-on.",
        },
        {
            "family": "volume",
            "priority": "P2",
            "target_rows": 100,
            "fields": "date, available_at, ticker, dollar_volume, rel_volume, volume_zscore, block_proxy, institutional_proxy",
            "source": "OHLCV enriched / broker flow proxy / provider export",
            "why": "Remplacer le volume brut par abnormal participation.",
        },
        {
            "family": "fundamental",
            "priority": "P3",
            "target_rows": 12,
            "fields": "date, available_at, ticker, forward_pe, ev_sales, revenue_growth, margin, fcf, roe, roic",
            "source": "fundamental provider point-in-time export",
            "why": "Contexte valuation-growth, pas alpha scanner direct au départ.",
        },
    ]

    for spec in family_specs:
        fam = spec["family"]
        present = _covered(fam)

        if isinstance(features, pd.DataFrame) and not features.empty and "feature_family" in features.columns:
            fam_rows = int(
                features["feature_family"]
                .astype(str)
                .str.lower()
                .str.contains(fam, regex=False, na=False)
                .sum()
            )
        else:
            fam_rows = 0

        target = int(spec["target_rows"])
        missing = max(target - fam_rows, 0)

        if fam_rows >= target:
            status = "ENOUGH_FOR_AUDIT"
        elif fam_rows > 0:
            status = "PARTIAL"
        else:
            status = "MISSING"

        acquisition_rows.append(
            {
                "Priority": spec["priority"],
                "Family": fam,
                "Current rows": fam_rows,
                "Target rows": target,
                "Missing rows": missing,
                "Status": status,
                "Required fields": spec["fields"],
                "Accepted source": spec["source"],
                "Why": spec["why"],
            }
        )

    acquisition_plan = pd.DataFrame(acquisition_rows)

    schema_templates = pd.DataFrame(
        [
            [
                "Generic long format",
                "date,available_at,ticker,feature_family,feature_name,value,source,confidence,notes",
                "Format universel déjà accepté par V4.9A.",
            ],
            [
                "Earnings wide format",
                "date,available_at,ticker,feature_family,feature_name,value,source,confidence,notes + optional eps_actual/estimate/surprise fields",
                "Importer en long format de préférence ; les colonnes larges doivent être converties en feature_name/value.",
            ],
            [
                "Options wide format",
                "date,available_at,ticker,feature_family,feature_name,value,source,confidence,notes + expiry/atm_iv/iv_rank/skew/term_slope/gamma_proxy",
                "Si plusieurs expiries, une ligne par date/expiry/feature.",
            ],
            [
                "News/catalyst format",
                "date,available_at,ticker,feature_family,feature_name,value,source,confidence,notes",
                "value peut être positive/negative/neutral ou score numérique ; notes peut contenir headline/tag.",
            ],
            [
                "Factor/macro format",
                "date,available_at,ticker,feature_family,feature_name,value,source,confidence,notes",
                "Une ligne par proxy : smh_return, qqq_return, xlk_return, vix_state, ust10y_change, etc.",
            ],
        ],
        columns=["Template", "Columns", "Read"],
    )

    available_at_rules = pd.DataFrame(
        [
            ["Mandatory", "Every row must have available_at.", "Rows without available_at cannot pass V4.9B/V4.9C."],
            ["Point-in-time", "available_at must be the first tradable timestamp.", "No latest snapshot backfill."],
            ["Earnings", "Use actual report timestamp or next market-open assumption.", "If exact timestamp unknown, mark confidence lower."],
            ["Analyst revision", "Use publication/revision timestamp, not fiscal period.", "Revision date must precede decision_date."],
            ["Options", "Use EOD option snapshot only on next decision bar.", "No same-close lookahead."],
            ["News", "Use publication timestamp, not article update time.", "No outcome-based tags."],
            ["Macro/factor", "Use same market-close convention and shift to next decision bar.", "Avoid calendar mismatch."],
            ["No outcome labels", "No future_return, target_hit, pnl, realized_alpha columns.", "Such columns must block validation."],
        ],
        columns=["Rule", "Definition", "Operational consequence"],
    )

    v49c_thresholds = pd.DataFrame(
        [
            ["Minimum external rows", ">= 50", "Current", str(rows), "PASS" if rows >= 50 else "NOT YET"],
            ["Preferred external rows", ">= 100", "Current", str(rows), "PASS" if rows >= 100 else "NOT YET"],
            ["Priority families", ">= 4", "Current", str(len(families)), "PASS" if len(families) >= 4 else "NOT YET"],
            ["Feature names", ">= 10", "Current", str(feature_count), "PASS" if feature_count >= 10 else "NOT YET"],
            ["Source diversity", ">= 2", "Current", str(source_count), "PASS" if source_count >= 2 else "REVIEW"],
            ["available_at quality", "0 invalid", "From V4.9B", "see audit", "PASS if V4.9B passes"],
            ["Calendar alignment", ">= 90%", "From V4.9B", "see audit", "PASS if V4.9B passes"],
            ["Missingness", "<= 20%", "From V4.9B", "see audit", "PASS if V4.9B passes"],
            ["Alpha scan permission", "only after all minimum gates", "Current decision", v49b_decision, "BLOCK" if rows < 50 else "REVIEW"],
        ],
        columns=["Gate", "Required", "Source", "Current", "Status"],
    )

    example_rows = [
        "date,available_at,ticker,feature_family,feature_name,value,source,confidence,notes",
        f"2025-06-10,2025-06-10 21:30:00,{str(ticker or 'NVDA').upper()},earnings,eps_surprise_pct,8.2,provider_or_manual,0.80,earnings surprise after release",
        f"2025-06-10,2025-06-10 21:30:00,{str(ticker or 'NVDA').upper()},earnings,revenue_surprise_pct,5.1,provider_or_manual,0.80,revenue surprise after release",
        f"2025-10-08,2025-10-08 21:30:00,{str(ticker or 'NVDA').upper()},revision,eps_revision_30d_pct,4.5,provider_or_manual,0.75,revision known at timestamp",
        f"2026-02-09,2026-02-09 21:30:00,{str(ticker or 'NVDA').upper()},guidance,revenue_guidance_change_pct,3.1,provider_or_manual,0.75,guidance revision",
        f"2026-03-15,2026-03-15 21:30:00,{str(ticker or 'NVDA').upper()},options,iv_rank,72.0,provider_or_manual,0.70,EOD option snapshot usable next bar",
        f"2026-03-15,2026-03-15 21:30:00,{str(ticker or 'NVDA').upper()},news,ai_datacenter_catalyst_tag,positive,provider_or_manual,0.70,publication timestamp required",
    ]

    example_csv = "\n".join(example_rows)

    if rows >= minimum_rows and len(families) >= 4 and feature_count >= 10:
        level = "Expansion protocol satisfied"
        decision = "PREPARE_V49C_AFTER_FINAL_AUDIT"
        score = 80.0
        read = "La densité minimale semble suffisante pour préparer V4.9C, sous réserve des checks V4.9B."
    elif rows > 0:
        level = "Data expansion required"
        decision = "EXPAND_EXTERNAL_DATA_BEFORE_V49C"
        score = max(20.0, min(70.0, 30.0 + rows / max(minimum_rows, 1) * 40.0))
        read = (
            "V4.9B.1 confirme que la structure est prête, mais le dataset externe doit être enrichi "
            "avant tout scanner alpha V4.9C."
        )
    else:
        level = "No external expansion base"
        decision = "LOAD_EXTERNAL_DATA_FIRST"
        score = 0.0
        read = "Aucune table externe exploitable : charger une source V4.9A avant le protocole V4.9B.1."

    summary = pd.DataFrame(
        [
            ["V4.9B.1 level", level, "Lecture synthétique du protocole d'expansion data."],
            ["V4.9B.1 score", f"{_format_num(score, 0)}/100", "Score de préparation data, pas score alpha."],
            ["Decision", decision, "Décision research V4.9B.1."],
            ["Read", read, "Interprétation opérationnelle."],
            ["Ticker", str(ticker or "N/A").upper(), "Ticker audité."],
            ["V4.9A input", v49a_decision, "Décision adaptateur."],
            ["V4.9B input", v49b_decision, "Décision audit feature."],
            ["Current rows", str(rows), "Lignes externes actuellement chargées."],
            ["Minimum rows", str(minimum_rows), "Minimum avant scanner alpha."],
            ["Preferred rows", str(preferred_rows), "Niveau préférable avant scanner alpha."],
            ["Rows missing to minimum", str(missing_to_minimum), "Lignes à ajouter pour seuil minimal."],
            ["Rows missing to preferred", str(missing_to_preferred), "Lignes à ajouter pour seuil préférable."],
            ["Current families", ", ".join(families) if families else "None", "Familles présentes."],
            ["Target families", ", ".join(target_families), "Familles visées."],
            ["Current feature names", str(feature_count), "Nombre de feature_name distincts."],
            ["Current sources", str(source_count), "Nombre de providers/sources."],
            ["Do not scan alpha", "PASS", "V4.9B.1 ne calcule aucun forward return."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    actions = pd.DataFrame(
        [
            ["P0", "Do not run V4.9C yet", f"Rows={rows}, minimum={minimum_rows}", "Scanner alpha interdit tant que le sample externe reste insuffisant."],
            ["P0", "Expand external rows", f"Missing={missing_to_minimum}", "Ajouter des lignes réelles avec available_at avant tout test alpha."],
            ["P0", "Keep point-in-time discipline", "Leakage risk", "Chaque ligne doit avoir available_at, source et pas d'outcome label."],
            ["P1", "Prioritize P0 families", "earnings/revision/guidance/options", "Commencer par earnings surprise, analyst revisions, guidance et options IV/skew/gamma."],
            ["P1", "Add source diversity", f"Sources={source_count}", "Éviter une validation basée uniquement sur manual_example."],
            ["P2", "Prepare V4.9C only after gates", decision, "Construire V4.9C seulement quand V4.9B.1 + V4.9B sont prêts."],
        ],
        columns=["Priority", "Action", "Reason", "Next Step"],
    )

    cards = [
        {"label": "V4.9B.1 protocol", "value": level, "delta": f"{_format_num(score, 0)}/100"},
        {"label": "Rows current/min", "value": f"{rows}/{minimum_rows}", "delta": f"missing {missing_to_minimum}"},
        {"label": "Preferred rows", "value": str(preferred_rows), "delta": f"missing {missing_to_preferred}"},
        {"label": "Families", "value": str(len(families)), "delta": "current"},
        {"label": "Features", "value": str(feature_count), "delta": "names"},
        {"label": "Decision", "value": decision, "delta": "research only"},
    ]

    return {
        "enabled": True,
        "level": level,
        "score": score,
        "decision": decision,
        "read": read,
        "cards": cards,
        "summary": summary,
        "acquisition_plan": acquisition_plan,
        "schema_templates": schema_templates,
        "available_at_rules": available_at_rules,
        "v49c_thresholds": v49c_thresholds,
        "example_csv": example_csv,
        "actions": actions,
        "minimum_rows": minimum_rows,
        "preferred_rows": preferred_rows,
        "missing_to_minimum": missing_to_minimum,
    }


def _render_external_data_expansion_protocol_v49b1(
    v49a_pack: dict[str, Any],
    v49b_pack: dict[str, Any],
    ticker: str = "",
) -> dict[str, Any]:
    pack = _v49b1_pack(
        v49a_pack=v49a_pack,
        v49b_pack=v49b_pack,
        ticker=ticker,
    )

    st.subheader("External Data Expansion Protocol V4.9B.1")
    st.caption(
        "Protocole lecture seule après V4.9B : définit quelles données réelles ajouter avant V4.9C, "
        "les familles prioritaires, les champs attendus, les règles available_at, les seuils de passage "
        "et un exemple CSV. Aucun alpha, aucun signal, aucun trade, aucune equity curve et aucun verdict ne sont modifiés."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))

    if "required" in level.lower() or "no external" in level.lower():
        st.warning(f"Lecture V4.9B.1 : {read}")
    elif "satisfied" in level.lower():
        st.success(f"Lecture V4.9B.1 : {read}")
    else:
        st.info(f"Lecture V4.9B.1 : {read}")

    with st.expander("V4.9B.1 expansion protocol summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.9B.1 indisponible.")

    with st.expander("V4.9B.1 acquisition plan by data family", expanded=True):
        table = pack.get("acquisition_plan", pd.DataFrame())
        if isinstance(table, pd.DataFrame) and not table.empty:
            st.dataframe(table, use_container_width=True, hide_index=True)
        else:
            st.info("Plan d'acquisition V4.9B.1 indisponible.")

    with st.expander("V4.9B.1 CSV schema templates", expanded=True):
        schema = pack.get("schema_templates", pd.DataFrame())
        if isinstance(schema, pd.DataFrame) and not schema.empty:
            st.dataframe(schema, use_container_width=True, hide_index=True)
        else:
            st.info("Schémas V4.9B.1 indisponibles.")

    with st.expander("V4.9B.1 available_at / anti-leakage rules", expanded=True):
        rules = pack.get("available_at_rules", pd.DataFrame())
        if isinstance(rules, pd.DataFrame) and not rules.empty:
            st.dataframe(rules, use_container_width=True, hide_index=True)
        else:
            st.info("Règles available_at V4.9B.1 indisponibles.")

    with st.expander("V4.9C minimum gates", expanded=True):
        gates = pack.get("v49c_thresholds", pd.DataFrame())
        if isinstance(gates, pd.DataFrame) and not gates.empty:
            st.dataframe(gates, use_container_width=True, hide_index=True)
        else:
            st.info("Seuils V4.9C indisponibles.")

    with st.expander("V4.9B.1 example external dataset CSV", expanded=False):
        example_csv = str(pack.get("example_csv", ""))
        if example_csv.strip():
            st.code(example_csv, language="csv")
            st.download_button(
                "Télécharger exemple dataset V4.9B.1 CSV",
                data=example_csv.encode("utf-8"),
                file_name=f"{str(ticker or 'ticker').upper()}_v49b1_external_dataset_template.csv",
                mime="text/csv",
                use_container_width=True,
                key="bt_v49b1_example_dataset_download",
            )
        else:
            st.info("Exemple CSV V4.9B.1 indisponible.")

    with st.expander("V4.9B.1 next controlled actions", expanded=True):
        actions = pack.get("actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.9B.1 indisponibles.")

     # --- V4.9B.2 external dataset builder / real data workbench call ---
    v49b2_pack = {}

    try:
        v49b2_pack = _render_external_dataset_builder_v49b2(
            v49a_pack=v49a_pack,
            v49b_pack=v49b_pack,
            v49b1_pack=pack,
            ticker=ticker,
        )

        if isinstance(pack, dict) and isinstance(v49b2_pack, dict):
            pack["external_dataset_builder_v49b2_summary"] = {
                "enabled": bool(v49b2_pack.get("enabled", False)),
                "level": str(v49b2_pack.get("level", "N/A")),
                "score": _safe_float(v49b2_pack.get("score"), np.nan),
                "decision": str(v49b2_pack.get("decision", "N/A")),
                "read": str(v49b2_pack.get("read", "")),
                "master_template_rows": (
                    int(len(v49b2_pack.get("master_template")))
                    if isinstance(v49b2_pack.get("master_template"), pd.DataFrame)
                    else 0
                ),
                "p0_template_rows": (
                    int(len(v49b2_pack.get("p0_template")))
                    if isinstance(v49b2_pack.get("p0_template"), pd.DataFrame)
                    else 0
                ),
            }

    except Exception as exc:
        st.warning(f"V4.9B.2 External Dataset Builder indisponible : {exc}")
    # --- end V4.9B.2 external dataset builder / real data workbench call ---

    # --- V4.9B.3 template contamination / provenance audit call ---
    try:
        v49b3_pack = _render_template_contamination_provenance_audit_v49b3(
            v49a_pack=v49a_pack,
            v49b_pack=v49b_pack,
            v49b1_pack=pack,
            v49b2_pack=v49b2_pack,
            ticker=ticker,
        )

        if isinstance(pack, dict) and isinstance(v49b3_pack, dict):
            pack["template_contamination_provenance_audit_v49b3_summary"] = {
                "enabled": bool(v49b3_pack.get("enabled", False)),
                "level": str(v49b3_pack.get("level", "N/A")),
                "score": _safe_float(v49b3_pack.get("score"), np.nan),
                "decision": str(v49b3_pack.get("decision", "N/A")),
                "read": str(v49b3_pack.get("read", "")),
                "template_rows": int(v49b3_pack.get("template_rows", 0) or 0),
                "provider_placeholder_rows": int(v49b3_pack.get("provider_placeholder_rows", 0) or 0),
                "warn_count": int(v49b3_pack.get("warn_count", 0) or 0),
                "fail_count": int(v49b3_pack.get("fail_count", 0) or 0),
            }

    except Exception as exc:
        st.warning(f"V4.9B.3 Template Contamination / Provenance Audit indisponible : {exc}")
    # --- end V4.9B.3 template contamination / provenance audit call ---

    return pack

