# ============================================================
# EXTERNAL DATASET BUILDER / REAL DATA WORKBENCH V4.9B.2
# ============================================================
# Research-only workbench after V4.9B.1.
# Purpose:
# - help build a real external catalyst dataset before V4.9C;
# - generate family templates, backlog, source checklist and collection plan;
# - measure current/minimum/preferred dataset progress;
# - never scan alpha;
# - never generate signals;
# - never modify engine, trades, equity curve or verdict.

def _v49b2_norm(value: Any) -> str:
    try:
        return (
            str(value or "")
            .strip()
            .lower()
            .replace(" ", "_")
            .replace("-", "_")
            .replace("/", "_")
        )
    except Exception:
        return ""


