def _v49e_norm(value: Any) -> str:
    try:
        return str(value or "").strip().lower().replace(" ", "_").replace("-", "_")
    except Exception:
        return ""


def _v49e_scalar_text(value: Any, default: str = "N/A") -> str:
    """
    Convertit toute valeur potentiellement non-hashable en string stable.
    Corrige les erreurs pandas du type: unhashable type: 'list'
    dans drop_duplicates / groupby / set.
    """
    try:
        if value is None:
            return default

        if isinstance(value, (list, tuple, set)):
            clean = [str(x).strip() for x in value if str(x).strip()]
            return " | ".join(clean) if clean else default

        if isinstance(value, dict):
            clean = []
            for k, v in value.items():
                clean.append(f"{str(k).strip()}={str(v).strip()}")
            return " | ".join(clean) if clean else default

        try:
            if pd.isna(value):
                return default
        except Exception:
            pass

        txt = str(value).strip()
        return txt if txt else default

    except Exception:
        return default


def _v49e_is_bad_feature_identity(value: Any) -> bool:
    """
    Detects corrupted feature identities caused by candidate-column lists
    being converted to text, e.g.
    'feature_name | Feature name | feature | top_feature | Top feature'.
    """
    try:
        txt = _v49e_scalar_text(value, default="").strip()
        low = txt.lower()

        if not txt:
            return True

        bad_exact = {
            "feature_name",
            "feature name",
            "top_feature",
            "top feature",
            "source",
            "source_name",
            "source name",
        }

        if low in bad_exact:
            return True

        if "feature_name" in low and "top_feature" in low:
            return True

        if "feature name" in low and "top feature" in low:
            return True

        if "|" in txt and ("feature" in low or "top_feature" in low):
            return True

    except Exception:
        return True

    return False


def _v49e_recover_summary_evidence_rows(
    v49c_pack: Any = None,
    v49c1_pack: Any = None,
    v49d_pack: Any = None,
) -> pd.DataFrame:
    """
    Emergency evidence recovery for V4.9E.

    Purpose:
    - If detailed V4.9D/V4.9C tables are not detected by the strict extractor,
      recover at least card-level evidence from top_feature/top_family/decision.
    - Prevent V4.9E from returning WAIT_FOR_V49D when V4.9D already says
      PREPARE_V49E_WATCH_REVIEW.
    - Does not promote anything. It only restores WATCH-level evidence.
    """

    def _safe_int_local(value: Any, default: int = 0) -> int:
        try:
            val = _safe_float(value, np.nan)
            if pd.isna(val):
                return default
            return int(val)
        except Exception:
            return default

    def _infer_family(feature: Any, fallback: Any = "") -> str:
        fam = _v49e_scalar_text(fallback, default="").strip()
        if fam and fam not in {"N/A", "None", "nan"}:
            return fam

        low = _v49e_scalar_text(feature, default="").lower()

        if any(x in low for x in ["eps", "revenue_surprise", "margin_surprise", "earnings"]):
            return "earnings"
        if any(x in low for x in ["revision", "estimate", "target_price"]):
            return "revision"
        if any(x in low for x in ["guidance", "forward"]):
            return "guidance"
        if any(x in low for x in ["iv", "skew", "gamma", "put_call", "option"]):
            return "options"
        if any(x in low for x in ["news", "catalyst", "headline"]):
            return "news"
        if any(x in low for x in ["qqq", "spy", "smh", "soxx", "xlk", "factor"]):
            return "factor"

        return "external"

    records: list[dict[str, Any]] = []

    packs = [
        ("v49d_summary_recovery", v49d_pack),
        ("v49c1_summary_recovery", v49c1_pack),
        ("v49c_summary_recovery", v49c_pack),
    ]

    for source_block, pack in packs:
        if not isinstance(pack, dict):
            continue

        top_feature = (
            pack.get("top_feature")
            or pack.get("source_feature")
            or pack.get("feature_name")
            or pack.get("top_source")
        )

        if _v49e_is_bad_feature_identity(top_feature):
            continue

        top_family = (
            pack.get("top_family")
            or pack.get("source_family")
            or pack.get("feature_family")
            or pack.get("family")
        )

        decision = _v49e_scalar_text(pack.get("decision", ""), default="").upper()
        level = _v49e_scalar_text(pack.get("level", ""), default="").upper()
        read = _v49e_scalar_text(pack.get("read", ""), default="").upper()

        score = _safe_float(pack.get("score"), np.nan)

        watch_count = _safe_int_local(
            pack.get("watch_count", pack.get("watch", pack.get("watchlist", 0))),
            0,
        )
        candidate_count = _safe_int_local(
            pack.get("candidate_count", pack.get("candidates", 0)),
            0,
        )

        usable = (
            "PREPARE_V49E" in decision
            or "WATCH" in decision
            or "WATCH" in level
            or "WATCH" in read
            or "MULTI_BENCH" in decision
            or watch_count > 0
            or candidate_count > 0
            or (pd.notna(score) and score >= 50)
        )

        if not usable:
            continue

        family = _infer_family(top_feature, top_family)
        feature = _v49e_scalar_text(top_feature, default="N/A")

        row_decision = "SOURCE_WATCH"
        if candidate_count > 0 or "CANDIDATE" in decision:
            row_decision = "SOURCE_CANDIDATE"
        elif "REJECT" in decision:
            row_decision = "SOURCE_REJECT"

        records.append(
            {
                "source_block": source_block,
                "feature_family": family,
                "feature_name": feature,
                "benchmark": "MULTI_BENCH" if "v49d" in source_block else "N/A",
                "row_decision": row_decision,
                "score": score if pd.notna(score) else 55.0,
                "sample": _safe_float(pack.get("sample", pack.get("rows", np.nan)), np.nan),
                "hit_rate": _safe_float(pack.get("hit_rate", np.nan), np.nan),
                "avg_active_3b": _safe_float(pack.get("avg_active_3b", np.nan), np.nan),
                "avg_active_5b": _safe_float(pack.get("avg_active_5b", np.nan), np.nan),
                "avg_active_10b": _safe_float(pack.get("avg_active_10b", np.nan), np.nan),
                "avg_active_20b": _safe_float(pack.get("avg_active_20b", np.nan), np.nan),
                "median_active_10b": _safe_float(pack.get("median_active_10b", np.nan), np.nan),
                "median_active_20b": _safe_float(pack.get("median_active_20b", np.nan), np.nan),
                "benchmarks_passed": _safe_float(pack.get("benchmarks_passed", np.nan), np.nan),
                "benchmark_count": _safe_float(
                    pack.get("benchmark_count", pack.get("benchmarks", np.nan)),
                    np.nan,
                ),
            }
        )

        # Priority: if V4.9D provides usable evidence, stop there.
        if source_block.startswith("v49d"):
            break

    return pd.DataFrame(records)


def _v49e_col(df: pd.DataFrame, candidates: Any) -> str | None:
    """
    Robust column resolver for V4.9E.

    Critical fix:
    - never return a list/tuple/set as a column name;
    - flatten candidate lists;
    - only return an actual column present in df.columns;
    - avoid fuzzy matching that can confuse feature_name with feature_family.
    """
    try:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return None

        flat: list[str] = []

        def _flatten(x: Any) -> None:
            if isinstance(x, (list, tuple, set)):
                for item in x:
                    _flatten(item)
            elif x is not None:
                txt = str(x).strip()
                if txt:
                    flat.append(txt)

        _flatten(candidates)

        if not flat:
            return None

        cols = list(df.columns)

        exact = {str(c).strip(): c for c in cols}
        lower = {str(c).strip().lower(): c for c in cols}
        normed = {_v49e_norm(c): c for c in cols}

        for cand in flat:
            if cand in exact:
                return exact[cand]

        for cand in flat:
            key = cand.lower().strip()
            if key in lower:
                return lower[key]

        for cand in flat:
            key = _v49e_norm(cand)
            if key in normed:
                return normed[key]

    except Exception:
        return None

    return None


def _v49e_parse_numeric(value: Any, default: float = np.nan, score_mode: bool = False) -> float:
    try:
        if value is None or pd.isna(value):
            return default

        txt = str(value).strip()
        if txt == "" or txt.upper() in {"N/A", "NA", "NONE", "NAN"}:
            return default

        txt = txt.replace(",", ".")

        if "/" in txt and score_mode:
            left, right = txt.split("/", 1)
            left_f = float(left.strip())
            right_f = float(right.strip())
            if right_f > 0:
                return 100.0 * left_f / right_f
            return left_f

        is_pct = "%" in txt
        cleaned = txt.replace("%", "").replace("$", "").replace(" ", "")
        out = float(cleaned)

        if is_pct and not score_mode:
            return out / 100.0

        return out
    except Exception:
        return default


def _v49e_first_numeric(row: pd.Series, columns: list[str], score_mode: bool = False) -> float:
    for col in columns:
        if col in row.index:
            val = _v49e_parse_numeric(row.get(col), np.nan, score_mode=score_mode)
            if pd.notna(val):
                return val
    return np.nan


def _v49e_collect_dataframes(obj: Any, prefix: str = "root", depth: int = 0) -> list[tuple[str, pd.DataFrame]]:
    if depth > 4:
        return []

    found: list[tuple[str, pd.DataFrame]] = []

    if isinstance(obj, pd.DataFrame):
        if not obj.empty:
            found.append((prefix, obj.copy()))
        return found

    if isinstance(obj, dict):
        for key, value in obj.items():
            found.extend(_v49e_collect_dataframes(value, f"{prefix}.{key}", depth + 1))
        return found

    if isinstance(obj, (list, tuple)):
        for i, value in enumerate(obj):
            found.extend(_v49e_collect_dataframes(value, f"{prefix}[{i}]", depth + 1))

    return found


def _v49e_infer_family(feature_name: str, fallback: str = "external") -> str:
    name = _v49e_norm(feature_name)

    if any(x in name for x in ["eps", "revenue_surprise", "margin_surprise", "surprise"]):
        return "earnings"
    if any(x in name for x in ["revision", "estimate", "target_price"]):
        return "revision"
    if any(x in name for x in ["guidance", "forward"]):
        return "guidance"
    if any(x in name for x in ["iv", "skew", "gamma", "put_call", "option", "term_slope"]):
        return "options"
    if any(x in name for x in ["news", "catalyst", "headline", "tag"]):
        return "news"
    if any(x in name for x in ["qqq", "xlk", "spy", "smh", "soxx", "benchmark", "factor"]):
        return "factor"
    if any(x in name for x in ["ust", "dxy", "uup", "vix", "macro", "liquidity"]):
        return "macro"
    if any(x in name for x in ["volume", "dollar_volume", "rel_volume", "block"]):
        return "volume"

    return str(fallback or "external")


def _v49e_extract_feature_rows(df: pd.DataFrame, source_label: str) -> pd.DataFrame:
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame()

    feature_col = _v49e_col(
        df,
        [
            "feature_name",
            "Feature name",
            "feature",
            "Feature",
            "top_feature",
            "Top feature",
            "source_feature",
            "Source feature",
            "primitive",
            "Primitive",
            "signal_name",
            "Signal name",
        ],
    )

    if feature_col is None:
        return pd.DataFrame()

    family_col = _v49e_col(
        df,
        [
            "feature_family",
            "Feature family",
            "family",
            "Family",
            "source_family",
            "Source family",
            "data_family",
            "Data family",
            "category",
            "Category",
        ],
    )
    benchmark_col = _v49e_col(df, ["benchmark", "Benchmark", "benchmark_symbol", "Benchmark symbol"])
    decision_col = _v49e_col(df, ["decision", "Decision", "label", "Label", "Status", "status"])

    def _valid_v49e_col(col: Any) -> str | None:
        if isinstance(col, (list, tuple, set)):
            col = _v49e_col(df, col)

        if isinstance(col, str) and col in df.columns:
            return col

        return None

    feature_col = _valid_v49e_col(feature_col)
    family_col = _valid_v49e_col(family_col)
    benchmark_col = _valid_v49e_col(benchmark_col)
    decision_col = _valid_v49e_col(decision_col)

    if feature_col is None:
        return pd.DataFrame()


    score_cols = [
        c for c in df.columns
        if any(x in _v49e_norm(c) for x in ["score", "priority"])
    ]

    avg3_cols = [c for c in df.columns if "active" in _v49e_norm(c) and "3" in _v49e_norm(c) and "avg" in _v49e_norm(c)]
    avg5_cols = [c for c in df.columns if "active" in _v49e_norm(c) and "5" in _v49e_norm(c) and "avg" in _v49e_norm(c)]
    avg10_cols = [c for c in df.columns if "active" in _v49e_norm(c) and "10" in _v49e_norm(c) and "avg" in _v49e_norm(c)]
    avg20_cols = [c for c in df.columns if "active" in _v49e_norm(c) and "20" in _v49e_norm(c) and "avg" in _v49e_norm(c)]

    med10_cols = [c for c in df.columns if "active" in _v49e_norm(c) and "10" in _v49e_norm(c) and ("median" in _v49e_norm(c) or "med" in _v49e_norm(c))]
    med20_cols = [c for c in df.columns if "active" in _v49e_norm(c) and "20" in _v49e_norm(c) and ("median" in _v49e_norm(c) or "med" in _v49e_norm(c))]

    hit10_cols = [c for c in df.columns if ("hit" in _v49e_norm(c) or "win" in _v49e_norm(c)) and "10" in _v49e_norm(c)]
    hit20_cols = [c for c in df.columns if ("hit" in _v49e_norm(c) or "win" in _v49e_norm(c)) and "20" in _v49e_norm(c)]

    sample_cols = [c for c in df.columns if _v49e_norm(c) in {"sample", "rows", "events", "observations", "obs"}]
    coverage_cols = [c for c in df.columns if "coverage" in _v49e_norm(c)]

    rows: list[dict[str, Any]] = []

    for _, row in df.iterrows():
        feature = _v49e_scalar_text(row.get(feature_col, ""), default="")
        if _v49e_is_bad_feature_identity(feature):
            continue
        if not feature or feature.upper() in {"N/A", "NA", "NONE", "NAN"}:
            continue

        family = _v49e_scalar_text(row.get(family_col, ""), default="") if family_col else ""
        if not family:
            family = _v49e_infer_family(feature)

        benchmark = _v49e_scalar_text(row.get(benchmark_col, ""), default="N/A") if benchmark_col else "N/A"
        decision = _v49e_scalar_text(row.get(decision_col, ""), default="") if decision_col else ""

        raw_score = _v49e_first_numeric(row, score_cols, score_mode=True)

        # Si la ligne ne contient pas de score mais vient d'une watchlist/candidate, on garde un score proxy.
        if pd.isna(raw_score):
            d = decision.lower()
            if "candidate" in d:
                raw_score = 80.0
            elif "watch" in d:
                raw_score = 55.0
            elif "reject" in d:
                raw_score = 20.0

        rows.append(
            {
                "source_block": source_label,
                "feature_family": _v49e_norm(family),
                "feature_name": ["feature_name", "Feature name", "feature", "top_feature", "Top feature"],
                "benchmark": benchmark if benchmark else "N/A",
                "row_decision": decision if decision else "N/A",
                "raw_score": raw_score,
                "sample": _v49e_first_numeric(row, sample_cols),
                "coverage": _v49e_first_numeric(row, coverage_cols),
                "avg_active_3b": _v49e_first_numeric(row, avg3_cols),
                "avg_active_5b": _v49e_first_numeric(row, avg5_cols),
                "avg_active_10b": _v49e_first_numeric(row, avg10_cols),
                "avg_active_20b": _v49e_first_numeric(row, avg20_cols),
                "median_active_10b": _v49e_first_numeric(row, med10_cols),
                "median_active_20b": _v49e_first_numeric(row, med20_cols),
                "hit_10b": _v49e_first_numeric(row, hit10_cols),
                "hit_20b": _v49e_first_numeric(row, hit20_cols),
            }
        )

    if not rows:
        return pd.DataFrame()

    out = pd.DataFrame(rows)
    out = out.replace([np.inf, -np.inf], np.nan)
    return out


def _v49e_source_rows_from_packs(
    v49c_pack: dict[str, Any] | None = None,
    v49c1_pack: dict[str, Any] | None = None,
    v49d_pack: dict[str, Any] | None = None,
) -> pd.DataFrame:
    """
    V4.9E evidence bridge.
    Objectif : récupérer proprement les évidences V4.9C/V4.9C.1/V4.9D,
    surtout les tables V4.9D benchmark_stability / benchmark_feature_map.

    Patch important :
    - empêche V4.9E de retourner WAIT_FOR_V49D alors que V4.9D a déjà une watch/candidate ;
    - force feature_family / feature_name / benchmark en scalaires hashables ;
    - évite l'ancien bug unhashable type: 'list' ;
    - ne promeut rien : source candidate/watch seulement.
    """

    def _txt(x: Any, default: str = "") -> str:
        try:
            if x is None:
                return default

            if isinstance(x, (list, tuple, set)):
                clean = [str(v).strip() for v in x if str(v).strip()]
                return " | ".join(clean) if clean else default

            if isinstance(x, dict):
                clean = [f"{str(k).strip()}={str(v).strip()}" for k, v in x.items()]
                return " | ".join(clean) if clean else default

            try:
                if pd.isna(x):
                    return default
            except Exception:
                pass

            out = str(x).strip()
            if out.lower() in {"", "none", "nan", "n/a"}:
                return default
            return out
        except Exception:
            return default

    def _num(x: Any, default: float = np.nan) -> float:
        try:
            val = _safe_float(x, default)
            if pd.isna(val):
                return default
            return float(val)
        except Exception:
            return default

    def _first(row: pd.Series, cols: list[str], default: Any = np.nan) -> Any:
        for col in cols:
            if col in row.index:
                val = row.get(col)
                try:
                    if pd.isna(val):
                        continue
                except Exception:
                    pass
                if _txt(val, "") != "":
                    return val
        return default

    def _bad_feature(x: Any) -> bool:
        txt = _txt(x, "").strip()
        low = txt.lower()

        if not txt:
            return True

        bad_exact = {
            "0",
            "none",
            "nan",
            "n/a",
            "external",
            "identity",
            "feature_name",
            "feature name",
            "top_feature",
            "top feature",
            "source",
            "source_name",
            "source name",
        }

        if low in bad_exact:
            return True

        if "feature_name" in low and "top_feature" in low:
            return True

        if "feature name" in low and "top feature" in low:
            return True

        if "|" in txt and ("feature" in low or "top_feature" in low):
            return True

        if low.startswith("[") or low.startswith("{"):
            return True

        return False

    def _infer_family(feature: Any, fallback: Any = "") -> str:
        fam = _txt(fallback, "").strip()
        if fam and fam.lower() not in {"none", "nan", "n/a", "external"}:
            return fam.lower()

        low = _txt(feature, "").lower()

        if any(k in low for k in ["eps", "revenue_surprise", "margin_surprise", "earnings"]):
            return "earnings"
        if any(k in low for k in ["revision", "estimate", "target_price"]):
            return "revision"
        if any(k in low for k in ["guidance", "forward"]):
            return "guidance"
        if any(k in low for k in ["iv", "skew", "gamma", "put_call", "option"]):
            return "options"
        if any(k in low for k in ["news", "catalyst", "headline"]):
            return "news"
        if any(k in low for k in ["smh", "soxx", "qqq", "xlk", "spy", "factor"]):
            return "factor"

        return "external"

    def _map_decision(x: Any) -> str:
        up = _txt(x, "").upper()

        if "SOURCE_CANDIDATE" in up or "MULTI_BENCH_CANDIDATE" in up or "READY_FOR_V49E_SOURCE_SELECTION" in up:
            return "SOURCE_CANDIDATE"

        if "SOURCE_WATCH" in up or "MULTI_BENCH_WATCH" in up or "PREPARE_V49E_WATCH" in up or "WATCH" in up:
            return "SOURCE_WATCH"

        if "MIXED" in up or "DEPENDENT" in up or "REFINE" in up:
            return "MIXED_EVIDENCE"

        if "REJECT" in up or "FRAGILE" in up or "DO_NOT" in up:
            return "REJECT"

        if "CANDIDATE" in up:
            return "SOURCE_CANDIDATE"

        return "REJECT"

    frames: list[pd.DataFrame] = []

    # 1) Extraction générique existante, mais sécurisée.
    for label, pack in [
        ("V4.9C", v49c_pack),
        ("V4.9C.1", v49c1_pack),
        ("V4.9D", v49d_pack),
    ]:
        if not isinstance(pack, dict):
            continue

        try:
            for source_label, df in _v49e_collect_dataframes(pack, prefix=label):
                extracted = _v49e_extract_feature_rows(df, source_label)
                if isinstance(extracted, pd.DataFrame) and not extracted.empty:
                    frames.append(extracted)
        except Exception:
            pass

    # 2) Extraction explicite V4.9D benchmark_stability.
    try:
        dpack = v49d_pack if isinstance(v49d_pack, dict) else {}
        stability = dpack.get("benchmark_stability", pd.DataFrame())

        if isinstance(stability, pd.DataFrame) and not stability.empty:
            rows = []

            for _, row in stability.iterrows():
                feature = _txt(_first(row, ["Feature", "feature", "feature_name", "Feature name"], ""), "")
                if _bad_feature(feature):
                    continue

                family = _infer_family(
                    feature,
                    _first(row, ["Family", "family", "feature_family", "Feature family"], ""),
                )

                stability_label = _first(row, ["Stability", "stability", "Decision", "decision"], "")
                row_decision = _map_decision(stability_label)

                rows.append(
                    {
                        "source_block": "V4.9D.benchmark_stability",
                        "feature_family": family,
                        "feature_name": feature,
                        "benchmark": "MULTI_BENCH",
                        "row_decision": row_decision,
                        "raw_score": _num(_first(row, ["Avg score", "Best score", "Score", "score"], np.nan)),
                        "sample": _num(_first(row, ["Sample", "Rows", "sample", "rows"], np.nan)),
                        "coverage": np.nan,
                        "avg_active_3b": np.nan,
                        "avg_active_5b": np.nan,
                        "avg_active_10b": np.nan,
                        "avg_active_20b": np.nan,
                        "median_active_10b": np.nan,
                        "median_active_20b": np.nan,
                        "hit_10b": np.nan,
                        "hit_20b": np.nan,
                    }
                )

            if rows:
                frames.append(pd.DataFrame(rows))
    except Exception:
        pass

    # 3) Extraction explicite V4.9D benchmark_feature_map.
    try:
        dpack = v49d_pack if isinstance(v49d_pack, dict) else {}
        fmap = dpack.get("benchmark_feature_map", pd.DataFrame())

        if isinstance(fmap, pd.DataFrame) and not fmap.empty:
            rows = []

            for _, row in fmap.iterrows():
                feature = _txt(_first(row, ["Feature", "feature", "feature_name", "Feature name"], ""), "")
                if _bad_feature(feature):
                    continue

                family = _infer_family(
                    feature,
                    _first(row, ["Family", "family", "feature_family", "Feature family"], ""),
                )

                benchmark = _txt(_first(row, ["Benchmark", "benchmark", "Benchmark label"], "N/A"), "N/A")
                decision_raw = _first(row, ["Decision", "decision", "Stability", "stability"], "")
                row_decision = _map_decision(decision_raw)

                rows.append(
                    {
                        "source_block": "V4.9D.benchmark_feature_map",
                        "feature_family": family,
                        "feature_name": feature,
                        "benchmark": benchmark,
                        "row_decision": row_decision,
                        "raw_score": _num(_first(row, ["Score", "score", "Feature score", "Avg score", "Best score"], np.nan)),
                        "sample": _num(_first(row, ["Sample", "Rows", "sample", "rows"], np.nan)),
                        "coverage": _num(_first(row, ["Coverage", "coverage"], np.nan)),
                        "avg_active_3b": _num(_first(row, ["Avg active 3B", "avg_active_3b"], np.nan)),
                        "avg_active_5b": _num(_first(row, ["Avg active 5B", "avg_active_5b"], np.nan)),
                        "avg_active_10b": _num(_first(row, ["Avg active 10B", "avg_active_10b"], np.nan)),
                        "avg_active_20b": _num(_first(row, ["Avg active 20B", "avg_active_20b"], np.nan)),
                        "median_active_10b": _num(_first(row, ["Median active 10B", "median_active_10b"], np.nan)),
                        "median_active_20b": _num(_first(row, ["Median active 20B", "median_active_20b"], np.nan)),
                        "hit_10b": _num(_first(row, ["Hit 10B", "hit_10b", "Hit rate 10B"], np.nan)),
                        "hit_20b": _num(_first(row, ["Hit 20B", "hit_20b", "Hit rate 20B"], np.nan)),
                    }
                )

            if rows:
                frames.append(pd.DataFrame(rows))
    except Exception:
        pass

    # 4) Fallback résumé pack : top_feature/top_family/decision.
    try:
        for source_block, pack in [
            ("V4.9D.summary", v49d_pack),
            ("V4.9C.1.summary", v49c1_pack),
            ("V4.9C.summary", v49c_pack),
        ]:
            if not isinstance(pack, dict):
                continue

            decision = _txt(pack.get("decision", ""), "").upper()
            level = _txt(pack.get("level", ""), "").upper()

            if not any(k in decision + " " + level for k in ["WATCH", "CANDIDATE", "PREPARE_V49E", "READY_FOR_V49E"]):
                continue

            feature = _txt(
                pack.get("top_feature")
                or pack.get("source_feature")
                or pack.get("feature_name")
                or pack.get("top_source"),
                "",
            )

            if _bad_feature(feature):
                continue

            family = _infer_family(
                feature,
                pack.get("top_family")
                or pack.get("source_family")
                or pack.get("feature_family")
                or pack.get("family"),
            )

            frames.append(
                pd.DataFrame(
                    [
                        {
                            "source_block": source_block,
                            "feature_family": family,
                            "feature_name": feature,
                            "benchmark": "SUMMARY",
                            "row_decision": _map_decision(decision or level),
                            "raw_score": _num(pack.get("score"), 55.0),
                            "sample": _num(pack.get("sample"), np.nan),
                            "coverage": np.nan,
                            "avg_active_3b": _num(pack.get("avg_active_3b"), np.nan),
                            "avg_active_5b": _num(pack.get("avg_active_5b"), np.nan),
                            "avg_active_10b": _num(pack.get("avg_active_10b"), np.nan),
                            "avg_active_20b": _num(pack.get("avg_active_20b"), np.nan),
                            "median_active_10b": _num(pack.get("median_active_10b"), np.nan),
                            "median_active_20b": _num(pack.get("median_active_20b"), np.nan),
                            "hit_10b": _num(pack.get("hit_10b"), np.nan),
                            "hit_20b": _num(pack.get("hit_20b"), np.nan),
                        }
                    ]
                )
            )
            break
    except Exception:
        pass

    if not frames:
        return pd.DataFrame()

    out = pd.concat(frames, ignore_index=True)
    out = out.replace([np.inf, -np.inf], np.nan)

    # Normalisation anti-list / anti-unhashable.
    for col in ["source_block", "feature_family", "feature_name", "benchmark", "row_decision"]:
        if col not in out.columns:
            out[col] = ""
        out[col] = out[col].map(lambda x: _txt(x, ""))

    out["feature_family"] = out.apply(
        lambda r: _infer_family(r.get("feature_name"), r.get("feature_family")),
        axis=1,
    )

    out = out[~out["feature_name"].map(_bad_feature)].copy()

    for col in [
        "raw_score",
        "sample",
        "coverage",
        "avg_active_3b",
        "avg_active_5b",
        "avg_active_10b",
        "avg_active_20b",
        "median_active_10b",
        "median_active_20b",
        "hit_10b",
        "hit_20b",
    ]:
        if col in out.columns:
            out[col] = pd.to_numeric(out[col], errors="coerce").replace([np.inf, -np.inf], np.nan)

    if out.empty:
        return pd.DataFrame()

    out = out.drop_duplicates(
        subset=["source_block", "feature_family", "feature_name", "benchmark", "row_decision"],
        keep="last",
    ).reset_index(drop=True)

    return out

def _v49e_aggregate_sources(rows: pd.DataFrame) -> pd.DataFrame:
    if rows is None or not isinstance(rows, pd.DataFrame) or rows.empty:
        return pd.DataFrame()

    work = rows.copy()

    for col in ["source_block", "feature_family", "feature_name", "benchmark", "row_decision"]:
        if col in work.columns:
            work[col] = work[col].map(lambda x: _v49e_scalar_text(x, default="N/A"))

    for col in [
        "raw_score",
        "sample",
        "coverage",
        "avg_active_3b",
        "avg_active_5b",
        "avg_active_10b",
        "avg_active_20b",
        "median_active_10b",
        "median_active_20b",
        "hit_10b",
        "hit_20b",
    ]:
        if col in work.columns:
            work[col] = pd.to_numeric(work[col], errors="coerce").replace([np.inf, -np.inf], np.nan)

    group_cols = ["feature_family", "feature_name"]
    grouped = work.groupby(group_cols, dropna=False)

    rows_out: list[dict[str, Any]] = []

    for (family, feature), grp in grouped:
        benchmarks = sorted(
            {
                str(x).strip()
                for x in grp.get("benchmark", pd.Series(dtype=str)).dropna().tolist()
                if str(x).strip() and str(x).strip().upper() != "N/A"
            }
        )

        decisions = " | ".join(
            sorted(
                {
                    str(x).strip()
                    for x in grp.get("row_decision", pd.Series(dtype=str)).dropna().tolist()
                    if str(x).strip() and str(x).strip().upper() != "N/A"
                }
            )
        )

        avg10 = float(grp["avg_active_10b"].dropna().mean()) if "avg_active_10b" in grp.columns and grp["avg_active_10b"].dropna().size else np.nan
        avg20 = float(grp["avg_active_20b"].dropna().mean()) if "avg_active_20b" in grp.columns and grp["avg_active_20b"].dropna().size else np.nan
        med10 = float(grp["median_active_10b"].dropna().median()) if "median_active_10b" in grp.columns and grp["median_active_10b"].dropna().size else np.nan
        med20 = float(grp["median_active_20b"].dropna().median()) if "median_active_20b" in grp.columns and grp["median_active_20b"].dropna().size else np.nan
        hit10 = float(grp["hit_10b"].dropna().mean()) if "hit_10b" in grp.columns and grp["hit_10b"].dropna().size else np.nan
        hit20 = float(grp["hit_20b"].dropna().mean()) if "hit_20b" in grp.columns and grp["hit_20b"].dropna().size else np.nan
        raw_score = float(grp["raw_score"].dropna().max()) if "raw_score" in grp.columns and grp["raw_score"].dropna().size else np.nan
        sample = float(grp["sample"].dropna().max()) if "sample" in grp.columns and grp["sample"].dropna().size else np.nan
        coverage = float(grp["coverage"].dropna().max()) if "coverage" in grp.columns and grp["coverage"].dropna().size else np.nan

        pos10 = int((pd.to_numeric(grp.get("avg_active_10b", pd.Series(dtype=float)), errors="coerce") > 0).sum())
        pos20 = int((pd.to_numeric(grp.get("avg_active_20b", pd.Series(dtype=float)), errors="coerce") > 0).sum())
        bench_count = len(benchmarks)

        sample_score = min((sample if pd.notna(sample) else len(grp)) / 20.0, 1.0) * 15.0
        bench_score = min(max(bench_count, 1) / 4.0, 1.0) * 20.0

        return_score = 0.0
        if pd.notna(avg10):
            return_score += _clip(avg10 / 0.03, -1.0, 1.0) * 16.0
        if pd.notna(med10):
            return_score += _clip(med10 / 0.02, -1.0, 1.0) * 14.0
        if pd.notna(avg20):
            return_score += _clip(avg20 / 0.04, -1.0, 1.0) * 8.0

        hit_score = 0.0
        if pd.notna(hit10):
            hit_score += _clip((hit10 - 0.45) / 0.20, 0.0, 1.0) * 12.0
        if pd.notna(hit20):
            hit_score += _clip((hit20 - 0.45) / 0.20, 0.0, 1.0) * 6.0

        positive_bench_score = min(max(pos10, pos20) / 3.0, 1.0) * 15.0

        computed_score = sample_score + bench_score + return_score + hit_score + positive_bench_score
        if pd.notna(raw_score):
            score = max(computed_score, raw_score)
        else:
            score = computed_score

        score = max(0.0, min(100.0, float(score)))

        candidate_gate = (
            score >= 75.0
            and pd.notna(avg10) and avg10 > 0
            and pd.notna(med10) and med10 > 0
            and (pd.isna(hit10) or hit10 >= 0.50)
            and bench_count >= 3
            and max(pos10, pos20) >= 2
        )

        watch_gate = (
            not candidate_gate
            and (
                score >= 50.0
                or "watch" in decisions.lower()
                or ((pd.notna(avg10) and avg10 > 0) and max(pos10, pos20) >= 1)
            )
        )

        mixed_gate = (
            not candidate_gate
            and not watch_gate
            and (
                score >= 35.0
                or (pd.notna(avg10) and avg10 > 0)
                or (pd.notna(avg20) and avg20 > 0)
            )
        )

        if candidate_gate:
            decision = "SOURCE_CANDIDATE"
            next_step = "Prepare V4.9F source-only micro-runner."
        elif watch_gate:
            decision = "SOURCE_WATCH"
            next_step = "Refine feature definition before V4.9F."
        elif mixed_gate:
            decision = "MIXED_EVIDENCE"
            next_step = "Keep in review; do not promote."
        else:
            decision = "REJECT"
            next_step = "Reject as source candidate."

        rows_out.append(
            {
                "Feature family": str(family),
                "Feature name": str(feature),
                "Decision": decision,
                "Source score": score,
                "Rows observed": int(len(grp)),
                "Sample": sample,
                "Coverage": coverage,
                "Benchmarks": bench_count,
                "Positive bench 10B": pos10,
                "Positive bench 20B": pos20,
                "Avg active 10B": avg10,
                "Avg active 20B": avg20,
                "Median active 10B": med10,
                "Median active 20B": med20,
                "Hit 10B": hit10,
                "Hit 20B": hit20,
                "Prior decisions": decisions if decisions else "N/A",
                "Benchmark list": ", ".join(benchmarks) if benchmarks else "N/A",
                "Next step": next_step,
            }
        )

    out = pd.DataFrame(rows_out)
    if out.empty:
        return out

    decision_rank = {
        "SOURCE_CANDIDATE": 0,
        "SOURCE_WATCH": 1,
        "MIXED_EVIDENCE": 2,
        "REJECT": 3,
    }
    out["_rank"] = out["Decision"].map(decision_rank).fillna(9)
    out = out.sort_values(["_rank", "Source score"], ascending=[True, False]).drop(columns=["_rank"])
    return out.reset_index(drop=True)


def _v49e_display_source_table(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame()

    out = df.copy()

    for col in ["Avg active 10B", "Avg active 20B", "Median active 10B", "Median active 20B", "Hit 10B", "Hit 20B", "Coverage"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_pct(x) if pd.notna(x) else "N/A")

    for col in ["Source score", "Sample"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_num(x, 0) if pd.notna(x) else "N/A")

    return out


def _external_source_candidate_selection_v49e_pack(
    v49c_pack: dict[str, Any] | None = None,
    v49c1_pack: dict[str, Any] | None = None,
    v49d_pack: dict[str, Any] | None = None,
    ticker: str = "",
) -> dict[str, Any]:
    rows = _v49e_source_rows_from_packs(v49c_pack=v49c_pack, v49c1_pack=v49c1_pack, v49d_pack=v49d_pack)

    # --- V4.9E forced summary evidence recovery ---
    try:
        if not isinstance(rows, pd.DataFrame) or rows.empty:
            rows = _v49e_recover_summary_evidence_rows(
                v49c_pack=v49c_pack,
                v49c1_pack=locals().get("v49c1_pack", None),
                v49d_pack=v49d_pack,
            )
    except Exception:
        pass
    # --- end V4.9E forced summary evidence recovery ---

    source_table = _v49e_aggregate_sources(rows)

    if source_table.empty:
        summary = pd.DataFrame(
            [
                ["V4.9E level", "No external source evidence", "Aucune table V4.9C/V4.9D exploitable pour sélectionner une source."],
                ["V4.9E score", "0/100", "Score de sélection source non applicable."],
                ["Decision", "WAIT_FOR_V49D", "Exécuter V4.9C/V4.9D avant V4.9E."],
                ["Read", "V4.9E attend une watchlist multi-benchmark exploitable.", "Interprétation opérationnelle."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        return {
            "enabled": False,
            "level": "No external source evidence",
            "score": 0.0,
            "decision": "WAIT_FOR_V49D",
            "read": "V4.9E attend une watchlist multi-benchmark exploitable.",
            "cards": [
                {"label": "V4.9E selection", "value": "No evidence", "delta": "0/100"},
                {"label": "Candidates", "value": "0", "delta": "external"},
                {"label": "Watchlist", "value": "0", "delta": "review"},
                {"label": "Decision", "value": "WAIT_FOR_V49D", "delta": "research only"},
            ],
            "summary": summary,
            "source_table": pd.DataFrame(),
            "candidate_table": pd.DataFrame(),
            "watch_table": pd.DataFrame(),
            "rejected_table": pd.DataFrame(),
            "source_spec": pd.DataFrame(),
            "selection_gates": pd.DataFrame(),
            "actions": pd.DataFrame(),
            "raw_evidence_rows": rows,
        }

    candidate_table = source_table[source_table["Decision"] == "SOURCE_CANDIDATE"].copy()
    watch_table = source_table[source_table["Decision"] == "SOURCE_WATCH"].copy()
    rejected_table = source_table[source_table["Decision"].isin(["MIXED_EVIDENCE", "REJECT"])].copy()

    top = source_table.iloc[0]
    top_feature = str(top.get("Feature name", "N/A"))
    top_family = str(top.get("Feature family", "external"))
    top_score = _safe_float(top.get("Source score"), 0.0)
    top_decision = str(top.get("Decision", "REJECT"))

    candidate_count = int(len(candidate_table))
    watch_count = int(len(watch_table))

    if candidate_count > 0:
        level = "External source candidate selected"
        decision = "PREPARE_V49F_SOURCE_MICRO_RUNNER"
        read = "V4.9E sélectionne une source externe candidate, mais uniquement pour micro-runner source-only V4.9F."
        score = max(80.0, top_score)
    elif watch_count > 0:
        level = "External source watch review"
        decision = "WATCH_ONLY_REFINE_BEFORE_V49F"
        read = "V4.9E conserve une source watch : robustesse partielle, pas encore candidate. Raffiner avant tout runner."
        score = max(50.0, min(74.0, top_score))
    else:
        level = "No selectable external source"
        decision = "REJECT_EXTERNAL_SOURCE_SELECTION"
        read = "V4.9E ne sélectionne aucune source externe : ne pas construire V4.9F."
        score = min(49.0, top_score)

    summary = pd.DataFrame(
        [
            ["V4.9E level", level, "Lecture synthétique de la sélection de source externe."],
            ["V4.9E score", f"{_format_num(score, 0)}/100", "Score de sélection source, pas score de performance."],
            ["Decision", decision, "Décision research V4.9E."],
            ["Read", read, "Interprétation opérationnelle."],
            ["Ticker", str(ticker or "N/A").upper(), "Ticker audité."],
            ["Top feature", top_feature, "Feature externe la mieux classée."],
            ["Top family", top_family, "Famille de la feature dominante."],
            ["Top source score", f"{_format_num(top_score, 0)}/100", "Score source de la meilleure feature."],
            ["Top decision", top_decision, "Décision de la meilleure feature."],
            ["Candidates", str(candidate_count), "Nombre de sources candidates."],
            ["Watchlist", str(watch_count), "Nombre de sources watch."],
            ["Evidence rows", str(len(rows)), "Nombre de lignes d'évidence V4.9C/V4.9D lues."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    selection_gates = pd.DataFrame(
        [
            ["Candidate gate", "score >= 75", _format_num(top_score, 0), "PASS" if top_score >= 75 else "NOT YET", "Seuil minimal pour construire un source micro-runner."],
            ["Forward active 10B", "avg > 0", _format_pct(top.get("Avg active 10B")), "PASS" if _safe_float(top.get("Avg active 10B"), np.nan) > 0 else "NOT YET", "La source doit produire un active return forward positif."],
            ["Median active 10B", "median > 0", _format_pct(top.get("Median active 10B")), "PASS" if _safe_float(top.get("Median active 10B"), np.nan) > 0 else "NOT YET", "Évite qu'une moyenne positive soit portée par quelques outliers."],
            ["Hit 10B", ">= 50% or missing", _format_pct(top.get("Hit 10B")), "PASS" if pd.isna(_safe_float(top.get("Hit 10B"), np.nan)) or _safe_float(top.get("Hit 10B"), 0.0) >= 0.50 else "NOT YET", "Taux de réussite forward minimal."],
            ["Benchmark breadth", ">= 3 benchmarks", str(int(_safe_float(top.get("Benchmarks"), 0))), "PASS" if int(_safe_float(top.get("Benchmarks"), 0)) >= 3 else "NOT YET", "La source ne doit pas dépendre d'un seul benchmark."],
            ["Positive benchmark count", ">= 2", str(max(int(_safe_float(top.get("Positive bench 10B"), 0)), int(_safe_float(top.get("Positive bench 20B"), 0)))), "PASS" if max(int(_safe_float(top.get("Positive bench 10B"), 0)), int(_safe_float(top.get("Positive bench 20B"), 0))) >= 2 else "NOT YET", "Nombre de benchmarks où la feature reste positive."],
            ["Promotion", "forbidden", "ENFORCED", "PASS", "V4.9E ne promeut pas le moteur courant."],
            ["OOS", "forbidden", "ENFORCED", "PASS", "OOS seulement après V4.9F/V4.9G source-only positif."],
        ],
        columns=["Gate", "Required", "Current", "Status", "Read"],
    )

    source_spec = pd.DataFrame(
        [
            ["Source ID", "SRC-V49E-01", "Identifiant research de la source prioritaire."],
            ["Feature family", top_family, "Famille externe dominante."],
            ["Feature name", top_feature, "Feature candidate/watch à raffiner."],
            ["Signal direction", "positive feature state", "Hypothèse initiale : état positif ou quantile haut de la feature."],
            ["Causality rule", "available_at + t+1", "Le micro-runner doit utiliser la disponibilité réelle, pas event_date final."],
            ["Benchmark rule", "multi-benchmark attribution", "Comparer SMH/SOXX/QQQ/XLK/SPY selon disponibilité."],
            ["Allowed mutation", "source-only", "Ne pas modifier exits/sizing/costs pendant V4.9F."],
            ["Validation target", "active return > 0, median > 0, hit > 50%", "Même discipline que V4.9E mais sur signal causal."],
            ["Still forbidden", "OOS / promotion / live / exits / sizing", "Interdit tant qu'une source-only candidate ne passe pas."],
        ],
        columns=["Item", "Value", "Read"],
    )

    actions = pd.DataFrame(
        [
            ["P0", "Do not OOS", "Source not validated", "OOS interdit avant V4.9F/V4.9G positif."],
            ["P0", "Do not promote", "V4.9E is selection review only", "Aucune feature externe ne doit modifier le moteur courant."],
            ["P0", "Freeze exits/sizing", "Still source-level", "Ne pas compenser une source faible par sorties ou sizing."],
            ["P1", "Review top watch/candidate", top_feature, "Inspecter sample, dates, benchmark breadth, hit-rate et median active."],
            ["P1", "Prepare V4.9F only if gate passes", top_decision, "Construire un micro-runner source-only seulement si la source devient candidate."],
            ["P2", "Expand source data if watch only", "partial robustness", "Ajouter plus d'observations réelles point-in-time et diversité provider."],
        ],
        columns=["Priority", "Action", "Reason", "Next Step"],
    )

    cards = [
        {"label": "V4.9E selection", "value": level, "delta": f"{_format_num(score, 0)}/100"},
        {"label": "Top source", "value": top_feature, "delta": top_family},
        {"label": "Top score", "value": f"{_format_num(top_score, 0)}/100", "delta": top_decision},
        {"label": "Candidates", "value": str(candidate_count), "delta": "external"},
        {"label": "Watchlist", "value": str(watch_count), "delta": "review"},
        {"label": "Decision", "value": decision, "delta": "research only"},
    ]



    return {
        "enabled": True,
        "level": level,
        "score": score,
        "decision": decision,
        "read": read,
        "top_feature": top_feature,
        "top_family": top_family,
        "top_score": top_score,
        "candidate_count": candidate_count,
        "watch_count": watch_count,
        "cards": cards,
        "summary": summary,
        "source_table": source_table,
        "candidate_table": candidate_table,
        "watch_table": watch_table,
        "rejected_table": rejected_table,
        "source_spec": source_spec,
        "selection_gates": selection_gates,
        "actions": actions,
        "raw_evidence_rows": rows,
    }


def _render_external_source_candidate_selection_v49e(
    v49c_pack: dict[str, Any] | None = None,
    v49c1_pack: dict[str, Any] | None = None,
    v49d_pack: dict[str, Any] | None = None,
    ticker: str = "",
) -> dict[str, Any]:
    pack = _external_source_candidate_selection_v49e_pack(
        v49c_pack=v49c_pack,
        v49c1_pack=v49c1_pack,
        v49d_pack=v49d_pack,
        ticker=ticker,
    )

    st.subheader("External Source Candidate Selection Review V4.9E")
    st.caption(
        "Revue lecture seule après V4.9C/V4.9D : sélectionne ou rejette les features externes causales "
        "selon score, active return forward, médiane, hit-rate et robustesse multi-benchmark. "
        "Aucun signal, aucun trade, aucune equity curve, aucun sizing et aucun verdict ne sont modifiés."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))

    if "candidate selected" in level.lower():
        st.success(f"Lecture V4.9E : {read}")
    elif "watch" in level.lower():
        st.warning(f"Lecture V4.9E : {read}")
    elif "no" in level.lower() or "reject" in level.lower():
        st.error(f"Lecture V4.9E : {read}")
    else:
        st.info(f"Lecture V4.9E : {read}")

    with st.expander("V4.9E source selection summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.9E indisponible.")

    with st.expander("V4.9E source selection leaderboard", expanded=True):
        table = _v49e_display_source_table(pack.get("source_table", pd.DataFrame()))
        if isinstance(table, pd.DataFrame) and not table.empty:
            st.dataframe(table, use_container_width=True, hide_index=True)
        else:
            st.info("Leaderboard V4.9E indisponible.")

    with st.expander("V4.9E candidate sources", expanded=True):
        candidates = _v49e_display_source_table(pack.get("candidate_table", pd.DataFrame()))
        if isinstance(candidates, pd.DataFrame) and not candidates.empty:
            st.dataframe(candidates, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune source candidate V4.9E détectée.")

    with st.expander("V4.9E watch sources", expanded=True):
        watch = _v49e_display_source_table(pack.get("watch_table", pd.DataFrame()))
        if isinstance(watch, pd.DataFrame) and not watch.empty:
            st.dataframe(watch, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune source watch V4.9E détectée.")

    with st.expander("V4.9E rejected / mixed sources", expanded=False):
        rejected = _v49e_display_source_table(pack.get("rejected_table", pd.DataFrame()))
        if isinstance(rejected, pd.DataFrame) and not rejected.empty:
            st.dataframe(rejected, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune source rejetée/mixed affichable.")

    with st.expander("V4.9E selection gates", expanded=True):
        gates = pack.get("selection_gates", pd.DataFrame())
        if isinstance(gates, pd.DataFrame) and not gates.empty:
            st.dataframe(gates, use_container_width=True, hide_index=True)
        else:
            st.info("Gates V4.9E indisponibles.")

    with st.expander("V4.9F recommended source-only blueprint", expanded=True):
        source_spec = pack.get("source_spec", pd.DataFrame())
        if isinstance(source_spec, pd.DataFrame) and not source_spec.empty:
            st.dataframe(source_spec, use_container_width=True, hide_index=True)
        else:
            st.info("Blueprint V4.9F indisponible.")

    with st.expander("V4.9E raw evidence rows", expanded=False):
        evidence = pack.get("raw_evidence_rows", pd.DataFrame())
        if isinstance(evidence, pd.DataFrame) and not evidence.empty:
            st.dataframe(evidence, use_container_width=True, hide_index=True)
        else:
            st.info("Évidence brute V4.9E indisponible.")

    with st.expander("V4.9E next controlled actions", expanded=True):
        actions = pack.get("actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.9E indisponibles.")

    d1, d2, d3 = st.columns(3)

    source_table = pack.get("source_table", pd.DataFrame())
    source_spec = pack.get("source_spec", pd.DataFrame())
    raw_rows = pack.get("raw_evidence_rows", pd.DataFrame())

    if isinstance(source_table, pd.DataFrame) and not source_table.empty:
        d1.download_button(
            "Télécharger V4.9E source selection CSV",
            data=source_table.to_csv(index=False).encode("utf-8"),
            file_name=f"{str(ticker or 'ticker').upper()}_v49e_source_selection.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49e_source_selection_download",
        )

    if isinstance(source_spec, pd.DataFrame) and not source_spec.empty:
        d2.download_button(
            "Télécharger V4.9E source spec CSV",
            data=source_spec.to_csv(index=False).encode("utf-8"),
            file_name=f"{str(ticker or 'ticker').upper()}_v49e_source_spec.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49e_source_spec_download",
        )

    if isinstance(raw_rows, pd.DataFrame) and not raw_rows.empty:
        d3.download_button(
            "Télécharger V4.9E evidence rows CSV",
            data=raw_rows.to_csv(index=False).encode("utf-8"),
            file_name=f"{str(ticker or 'ticker').upper()}_v49e_raw_evidence.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49e_raw_evidence_download",
        )

    return pack

