def _v49f_get_first_df(container: Any, keys: list[str] | None = None) -> pd.DataFrame:
    """
    Small defensive extractor for V4.9F.
    It accepts either a DataFrame directly or a dict containing one of several possible table names.
    """
    keys = keys or []

    try:
        if isinstance(container, pd.DataFrame):
            return container.copy()

        if not isinstance(container, dict):
            return pd.DataFrame()

        for key in keys:
            value = container.get(key)
            if isinstance(value, pd.DataFrame) and not value.empty:
                return value.copy()

        # Defensive fallback: find the first non-empty dataframe in the pack.
        for _, value in container.items():
            if isinstance(value, pd.DataFrame) and not value.empty:
                return value.copy()

    except Exception:
        pass

    return pd.DataFrame()


def _v49f_normalize_feature_table(df: pd.DataFrame) -> pd.DataFrame:
    """
    Normalizes V4.9C/V4.9D/V4.9E source tables into a stable schema.
    No engine impact. No signal mutation.
    """
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame()

    out = df.copy()
    out.columns = [str(c).strip() for c in out.columns]
    lower = {str(c).lower().strip(): c for c in out.columns}

    def pick(candidates: list[str]) -> str | None:
        for candidate in candidates:
            if candidate.lower().strip() in lower:
                return lower[candidate.lower().strip()]
        for col in out.columns:
            norm = str(col).lower().strip().replace(" ", "_").replace("-", "_")
            for candidate in candidates:
                cn = candidate.lower().strip().replace(" ", "_").replace("-", "_")
                if norm == cn or cn in norm:
                    return col
        return None

    family_col = pick(["feature_family", "family", "source_family", "data_family"])
    feature_col = pick([
        "feature_name",
        "Feature name",
        "feature",
        "top_feature",
        "Top feature",
        "primitive",
    ])
    decision_col = pick(["decision", "selection", "label", "status", "audit_label"])
    score_col = pick(["score", "selection_score", "priority_score", "top_score", "v49e_score"])
    sample_col = pick(["sample", "rows", "event_count", "events", "n"])
    coverage_col = pick(["coverage", "event_coverage", "active_coverage"])
    hit_col = pick(["hit_10b", "hit 10b", "hit_rate_10b", "hit_rate", "hit", "positive_rate"])
    bench_pass_col = pick(["benchmarks_passed", "benchmark_pass_count", "bench_pass", "robust_benchmarks"])
    bench_count_col = pick(["benchmarks", "benchmark_count", "bench_count"])

    avg3_col = pick(["avg_active_3b", "avg active 3b", "mean_active_3b", "mean active 3b"])
    avg5_col = pick(["avg_active_5b", "avg active 5b", "mean_active_5b", "mean active 5b"])
    avg10_col = pick(["avg_active_10b", "avg active 10b", "mean_active_10b", "mean active 10b"])
    avg20_col = pick(["avg_active_20b", "avg active 20b", "mean_active_20b", "mean active 20b"])

    med10_col = pick(["median_active_10b", "median active 10b", "med_active_10b"])
    med20_col = pick(["median_active_20b", "median active 20b", "med_active_20b"])

    norm = pd.DataFrame(index=out.index)
    norm["feature_family"] = out[family_col].astype(str) if family_col else "external"
    norm["feature_name"] = out[feature_col].astype(str) if feature_col else out.index.astype(str)
    norm["decision"] = out[decision_col].astype(str) if decision_col else "REVIEW"

    def num(col: str | None, default: float = np.nan) -> pd.Series:
        if col and col in out.columns:
            if out[col].dtype == object:
                return pd.to_numeric(
                    out[col].astype(str).str.replace("%", "", regex=False).str.replace(",", ".", regex=False),
                    errors="coerce",
                ).map(lambda x: x / 100.0 if pd.notna(x) and abs(x) > 1.0 and "%" in str(out[col].iloc[0]) else x)
            return pd.to_numeric(out[col], errors="coerce")
        return pd.Series(default, index=out.index)

    norm["score"] = num(score_col, 0.0)
    # Scores are usually 0-100. If the source supplied 0-1, convert to 0-100.
    if norm["score"].dropna().max() <= 1.0:
        norm["score"] = norm["score"] * 100.0

    norm["sample"] = num(sample_col, 0.0).fillna(0.0)
    norm["coverage"] = num(coverage_col, np.nan)
    norm["hit_rate"] = num(hit_col, np.nan)

    norm["benchmarks_passed"] = num(bench_pass_col, np.nan)
    norm["benchmark_count"] = num(bench_count_col, np.nan)

    norm["avg_active_3b"] = num(avg3_col, np.nan)
    norm["avg_active_5b"] = num(avg5_col, np.nan)
    norm["avg_active_10b"] = num(avg10_col, np.nan)
    norm["avg_active_20b"] = num(avg20_col, np.nan)
    norm["median_active_10b"] = num(med10_col, np.nan)
    norm["median_active_20b"] = num(med20_col, np.nan)

    # If pct-like columns were imported as 2.5 instead of 0.025, normalize defensively.
    pct_cols = [
        "coverage", "hit_rate", "avg_active_3b", "avg_active_5b", "avg_active_10b",
        "avg_active_20b", "median_active_10b", "median_active_20b",
    ]
    for col in pct_cols:
        clean = pd.to_numeric(norm[col], errors="coerce").replace([np.inf, -np.inf], np.nan)
        if clean.dropna().abs().median() > 1.0:
            norm[col] = clean / 100.0
        else:
            norm[col] = clean

    # Preserve original columns for evidence audit when useful.
    norm["raw_decision"] = norm["decision"].astype(str)
    norm["raw_feature_key"] = norm["feature_family"].astype(str) + ":" + norm["feature_name"].astype(str)

    return norm.replace([np.inf, -np.inf], np.nan)


def _v49f_collect_candidate_universe(
    v49e_pack: Any = None,
    v49d_pack: Any = None,
    v49c_pack: Any = None,
) -> pd.DataFrame:
    """
    V4.9F strict dependency patch.

    Règle :
    - V4.9F ne doit consommer que V4.9E.
    - Pas de fallback direct vers V4.9D/V4.9C.
    - Si V4.9E dit WAIT_FOR_V49D / No evidence, V4.9F doit rester vide.
    """

    if not isinstance(v49e_pack, dict):
        return pd.DataFrame()

    e_decision = str(v49e_pack.get("decision", "")).upper()
    e_level = str(v49e_pack.get("level", "")).lower()
    e_enabled = bool(v49e_pack.get("enabled", False))

    blocked_markers = [
        "WAIT_FOR",
        "NO_EXTERNAL",
        "NO EVIDENCE",
        "NO EXTERNAL SOURCE EVIDENCE",
        "V49E_ERROR",
    ]

    if (not e_enabled) or any(x in e_decision for x in blocked_markers) or any(x.lower() in e_level for x in blocked_markers):
        return pd.DataFrame()

    tables: list[pd.DataFrame] = []

    e_keys = [
        "candidate_table",
        "watch_table",
        "source_table",
        "source_spec",
        "selection",
        "candidate_sources",
        "watch_sources",
        "source_selection",
        "leaderboard",
        "source_selection_leaderboard",
    ]

    for key in e_keys:
        try:
            df = v49e_pack.get(key, pd.DataFrame())
            norm = _v49f_normalize_feature_table(df)

            if isinstance(norm, pd.DataFrame) and not norm.empty:
                norm["source_level"] = "V4.9E"
                norm["source_key"] = key
                tables.append(norm)
        except Exception:
            continue

    if not tables:
        return pd.DataFrame()

    universe = pd.concat(tables, ignore_index=True)
    universe = universe.replace([np.inf, -np.inf], np.nan)

    for col in ["feature_family", "feature_name", "decision"]:
        if col not in universe.columns:
            universe[col] = ""

        universe[col] = universe[col].map(lambda x: str(x).strip())

    bad_names = {
        "",
        "0",
        "none",
        "nan",
        "n/a",
        "external",
        "identity",
        "feature_name",
        "top_feature",
        "source",
    }

    universe = universe[
        ~universe["feature_name"].str.lower().isin(bad_names)
    ].copy()

    decision_upper = universe["decision"].astype(str).str.upper()

    # V4.9F ne garde que les candidates/watch explicitement validées par V4.9E.
    keep = (
        decision_upper.str.contains("SOURCE_CANDIDATE", na=False)
        | decision_upper.str.contains("SOURCE_WATCH", na=False)
        | decision_upper.str.contains("CANDIDATE", na=False)
        | decision_upper.str.contains("WATCH", na=False)
    )

    universe = universe[keep].copy()

    if universe.empty:
        return pd.DataFrame()

    universe["_score_sort"] = pd.to_numeric(universe.get("score", 0.0), errors="coerce").fillna(0.0)
    universe = universe.sort_values("_score_sort", ascending=False)
    universe = universe.drop_duplicates(subset=["feature_family", "feature_name"], keep="first")
    universe = universe.drop(columns=["_score_sort"], errors="ignore")

    return universe.reset_index(drop=True)


def _source_micro_runner_v49f_pack(
    v49e_pack: Any = None,
    v49d_pack: Any = None,
    v49c_pack: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    """
    External Source Micro-Runner / Source-Only Blueprint V4.9F.

    Purpose:
    - consume V4.9E selected/watch external features;
    - produce a source-only micro-runner specification;
    - define causal t+1 feature-to-signal rules;
    - gate whether the selected source deserves a controlled micro-runner.

    Strict guardrail:
    - no main engine mutation;
    - no trade mutation;
    - no equity curve mutation;
    - no sizing/exits/OOS/live promotion.
    """
    try:
        universe = _v49f_collect_candidate_universe(v49e_pack, v49d_pack, v49c_pack)

        if universe.empty:
            summary = pd.DataFrame(
                [
                    ["V4.9F level", "No source candidate", "Aucune source V4.9E/V4.9D/V4.9C exploitable."],
                    ["V4.9F score", "0/100", "Score non applicable sans source candidate."],
                    ["Decision", "RETURN_TO_V49E_OR_DATA_EXPANSION", "Revenir à la sélection source ou enrichir la data."],
                    ["Read", "V4.9F ne peut pas construire de micro-runner sans source candidate.", "Interprétation opérationnelle."],
                ],
                columns=["Metric", "Value", "Read"],
            )
            return {
                "enabled": False,
                "level": "No source candidate",
                "score": 0.0,
                "decision": "RETURN_TO_V49E_OR_DATA_EXPANSION",
                "read": "Aucune source candidate exploitable pour V4.9F.",
                "top_feature": "N/A",
                "candidate_count": 0,
                "watch_count": 0,
                "cards": [
                    {"label": "V4.9F runner", "value": "No candidate", "delta": "0/100"},
                    {"label": "Decision", "value": "RETURN", "delta": "research only"},
                ],
                "summary": summary,
                "selection": pd.DataFrame(),
                "runner_spec": pd.DataFrame(),
                "gates": pd.DataFrame(),
                "signal_schema": pd.DataFrame(),
                "next_actions": pd.DataFrame(),
                "evidence": pd.DataFrame(),
            }

        work = universe.copy()
        work["decision_upper"] = work["decision"].astype(str).str.upper()
        work["is_candidate"] = work["decision_upper"].str.contains("CANDIDATE|SOURCE_CANDIDATE|SELECTED", regex=True, na=False)
        work["is_watch"] = work["decision_upper"].str.contains("WATCH|REVIEW|MULTI_BENCH", regex=True, na=False) & ~work["is_candidate"]

        # V4.9F runner score: selection strength + forward active evidence + robust-benchmark evidence.
        active_cols = ["avg_active_5b", "avg_active_10b", "avg_active_20b"]
        med_cols = ["median_active_10b", "median_active_20b"]

        work["mean_forward_active"] = work[active_cols].mean(axis=1, skipna=True)
        work["mean_forward_median"] = work[med_cols].mean(axis=1, skipna=True)

        positive_mean = (work["mean_forward_active"].fillna(0.0) > 0).astype(float)
        positive_median = (work["mean_forward_median"].fillna(0.0) > 0).astype(float)
        hit_score = ((work["hit_rate"].fillna(0.50) - 0.50) * 100.0).clip(lower=0.0, upper=25.0)

        bench_ratio = work["benchmarks_passed"] / work["benchmark_count"].replace(0, np.nan)
        bench_score = (bench_ratio.fillna(0.50) * 20.0).clip(lower=0.0, upper=20.0)

        base_score = pd.to_numeric(work["score"], errors="coerce").fillna(0.0).clip(0.0, 100.0)

        work["v49f_runner_score"] = (
            0.55 * base_score
            + 10.0 * positive_mean
            + 10.0 * positive_median
            + hit_score
            + bench_score
        ).clip(0.0, 100.0)

        # Candidate rows have priority, but a watch row can remain visible if no candidate exists.
        work = work.sort_values(["is_candidate", "v49f_runner_score"], ascending=[False, False]).reset_index(drop=True)

        top = work.iloc[0]
        top_feature = str(top.get("feature_name", "N/A"))
        top_family = str(top.get("feature_family", "external"))
        top_score = float(_safe_float(top.get("v49f_runner_score"), 0.0))

        candidate_count = int(work["is_candidate"].sum())
        watch_count = int(work["is_watch"].sum())

        sample = float(_safe_float(top.get("sample"), 0.0))
        mean_active = float(_safe_float(top.get("mean_forward_active"), np.nan))
        median_active = float(_safe_float(top.get("mean_forward_median"), np.nan))
        hit_rate = float(_safe_float(top.get("hit_rate"), np.nan))
        benchmark_count = float(_safe_float(top.get("benchmark_count"), np.nan))
        benchmarks_passed = float(_safe_float(top.get("benchmarks_passed"), np.nan))

        gates_rows = []

        def add_gate(gate: str, required: str, current: Any, passed: bool, read: str) -> None:
            gates_rows.append(
                {
                    "Gate": gate,
                    "Required": required,
                    "Current": str(current),
                    "Status": "PASS" if passed else "REVIEW" if gate in {"Sample", "Hit rate"} else "FAIL",
                    "Read": read,
                }
            )

        add_gate(
            "V4.9E candidate",
            "selected source or strong watch",
            str(top.get("decision", "N/A")),
            bool(top.get("is_candidate", False)) or top_score >= 70.0,
            "La source doit venir de V4.9E/V4.9D, pas d'un forcing manuel.",
        )
        add_gate(
            "Forward active mean",
            "> 0",
            _format_pct(mean_active) if pd.notna(mean_active) else "N/A",
            pd.notna(mean_active) and mean_active > 0,
            "Le micro-runner ne doit tester qu'une source avec active return forward moyen positif.",
        )
        add_gate(
            "Forward active median",
            ">= 0 preferred",
            _format_pct(median_active) if pd.notna(median_active) else "N/A",
            pd.isna(median_active) or median_active >= 0,
            "La médiane évite une sélection portée par un seul outlier.",
        )
        add_gate(
            "Hit rate",
            ">= 50% preferred",
            _format_pct(hit_rate) if pd.notna(hit_rate) else "N/A",
            pd.isna(hit_rate) or hit_rate >= 0.50,
            "Le hit-rate doit confirmer que l'edge n'est pas seulement moyen/outlier.",
        )
        add_gate(
            "Sample",
            ">= 8 events preferred",
            _format_num(sample, 0),
            sample >= 8 or sample == 0,
            "Sample faible = micro-runner autorisé seulement en research, pas OOS/promotion.",
        )
        add_gate(
            "Multi-benchmark robustness",
            ">= partial pass",
            (
                f"{_format_num(benchmarks_passed, 0)}/{_format_num(benchmark_count, 0)}"
                if pd.notna(benchmark_count)
                else "N/A"
            ),
            pd.isna(benchmark_count) or benchmarks_passed >= max(1.0, benchmark_count * 0.30),
            "Une source candidate doit survivre au moins partiellement hors benchmark unique.",
        )
        add_gate(
            "No engine promotion",
            "always enforced",
            "ENFORCED",
            True,
            "V4.9F reste source-only : aucun changement moteur, exits, sizing, trades ou verdict.",
        )

        gates = pd.DataFrame(gates_rows)
        blocking = int((gates["Status"].astype(str) == "FAIL").sum())
        reviews = int((gates["Status"].astype(str) == "REVIEW").sum())

        if candidate_count > 0 and blocking == 0 and top_score >= 75:
            level = "Source-only micro-runner ready"
            decision = "BUILD_V49F_SOURCE_ONLY_MICRO_RUNNER"
            read = "V4.9F peut construire un micro-runner source-only sur la source externe candidate. Aucune promotion moteur."
        elif candidate_count > 0 and blocking <= 1:
            level = "Source micro-runner review"
            decision = "BUILD_V49F_REVIEW_RUNNER_ONLY"
            read = "Source candidate détectée, mais les gates imposent un micro-runner review-only avant toute étape supérieure."
        elif watch_count > 0:
            level = "Watch-only source refinement"
            decision = "REFINE_SOURCE_BEFORE_V49F_RUNNER"
            read = "V4.9F ne doit pas encore runner : la source reste watchlist ou incomplète."
        else:
            level = "No valid source runner"
            decision = "RETURN_TO_V49E_SELECTION"
            read = "Aucune source externe assez propre pour un micro-runner source-only."

        runner_spec = pd.DataFrame(
            [
                ["Runner objective", "source-only causal micro-runner", "Tester uniquement la source sélectionnée, sans modifier le moteur principal."],
                ["Ticker", str(ticker or "N/A"), "Ticker audité."],
                ["Selected feature", top_feature, "Feature candidate retenue par V4.9E/V4.9D."],
                ["Feature family", top_family, "Famille de données externe."],
                ["Source decision", str(top.get("decision", "N/A")), "Décision héritée de la sélection source."],
                ["Signal construction", "event available_at -> decision_date t+1", "Aucune utilisation de date économique si available_at diffère."],
                ["Signal side", "long-only first pass", "Ne pas introduire short/levier avant preuve source robuste."],
                ["Holding grid", "3B / 5B / 10B / 20B", "Mesurer le decay et la fenêtre où l'active return survit."],
                ["Benchmark map", "SMH/SOXX/QQQ/XLK/SPY if available", "Comparer l'active return à plusieurs benchmarks."],
                ["Frozen", "exits / sizing / costs / OOS / live", "Ne pas compenser une source faible par de l'optimisation."],
                ["Promotion condition", "positive active mean + median + hit-rate + sample", "Prépare seulement V4.9G si le source-only runner confirme."],
            ],
            columns=["Item", "Value", "Read"],
        )

        signal_schema = pd.DataFrame(
            [
                ["date", "datetime/date", "Date de marché alignée, dérivée de available_at."],
                ["available_at", "datetime", "Timestamp causal obligatoire de disponibilité de la feature."],
                ["ticker", "string", "Ticker concerné."],
                ["feature_family", "string", f"Exemple : {top_family}."],
                ["feature_name", "string", f"Exemple : {top_feature}."],
                ["feature_value", "float/string", "Valeur observée point-in-time."],
                ["source_signal", "float", "Signal source-only brut, décalé t+1 avant évaluation."],
                ["hold_bars", "int", "Horizon de détention testé : 3/5/10/20."],
                ["benchmark", "string", "Benchmark utilisé pour active return."],
                ["forward_active_return", "float", "Mesure d'évaluation, jamais feature d'entrée."],
            ],
            columns=["Column", "Type", "Read"],
        )

        next_actions = pd.DataFrame(
            [
                ["P0", "Do not OOS", "V4.9F is source-only", "OOS interdit tant que le micro-runner ne confirme pas la source."],
                ["P0", "Do not promote", "No engine validation yet", "Aucune feature externe ne doit modifier le moteur courant."],
                ["P0", "Use available_at only", "Catalyst leakage risk", "Le signal source doit être utilisable uniquement après disponibilité réelle."],
                ["P1", "Build source-only micro-runner", top_feature, "Créer un runner isolé sur la source candidate top-ranked."],
                ["P1", "Test holding grid", "3B/5B/10B/20B", "Identifier l'horizon où l'active return est réellement capturable."],
                ["P2", "Prepare V4.9G only if confirmed", decision, "V4.9G seulement si moyenne, médiane, hit-rate et sample restent positifs."],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        selection = work.copy()
        display_cols = [
            "feature_family", "feature_name", "decision", "source_level", "score", "v49f_runner_score",
            "sample", "hit_rate", "mean_forward_active", "mean_forward_median",
            "benchmarks_passed", "benchmark_count", "is_candidate", "is_watch",
        ]
        selection = selection[[c for c in display_cols if c in selection.columns]].copy()

        summary = pd.DataFrame(
            [
                ["V4.9F level", level, "Lecture synthétique du micro-runner source-only."],
                ["V4.9F score", f"{_format_num(top_score, 0)}/100", "Score de préparation runner, pas score de performance live."],
                ["Decision", decision, "Décision research V4.9F."],
                ["Read", read, "Interprétation opérationnelle."],
                ["Ticker", str(ticker or "N/A"), "Ticker audité."],
                ["Top source", top_feature, "Source externe prioritaire."],
                ["Top family", top_family, "Famille de la source prioritaire."],
                ["Candidate count", str(candidate_count), "Sources candidates héritées de V4.9E."],
                ["Watch count", str(watch_count), "Sources watchlist à surveiller."],
                ["Blocking gates", str(blocking), "Nombre de gates bloquants."],
                ["Review gates", str(reviews), "Nombre de gates en revue."],
                ["Forward active mean", _format_pct(mean_active) if pd.notna(mean_active) else "N/A", "Moyenne active forward si disponible."],
                ["Forward active median", _format_pct(median_active) if pd.notna(median_active) else "N/A", "Médiane active forward si disponible."],
                ["Hit rate", _format_pct(hit_rate) if pd.notna(hit_rate) else "N/A", "Hit-rate forward si disponible."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        cards = [
            {"label": "V4.9F runner", "value": level, "delta": f"{_format_num(top_score, 0)}/100"},
            {"label": "Top source", "value": top_feature, "delta": top_family},
            {"label": "Candidates", "value": str(candidate_count), "delta": "source-only"},
            {"label": "Watchlist", "value": str(watch_count), "delta": "review"},
            {"label": "Blocking gates", "value": str(blocking), "delta": "runner gates"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": top_score,
            "decision": decision,
            "read": read,
            "top_feature": top_feature,
            "top_family": top_family,
            "candidate_count": candidate_count,
            "watch_count": watch_count,
            "blocking_gates": blocking,
            "review_gates": reviews,
            "cards": cards,
            "summary": summary,
            "selection": selection,
            "runner_spec": runner_spec,
            "gates": gates,
            "signal_schema": signal_schema,
            "next_actions": next_actions,
            "evidence": work,
        }

    except Exception as exc:
        summary = pd.DataFrame(
            [
                ["V4.9F error", str(exc), "Erreur capturée sans interrompre le backtest."],
            ],
            columns=["Metric", "Value", "Read"],
        )
        return {
            "enabled": False,
            "level": "V4.9F error",
            "score": 0.0,
            "decision": "V49F_ERROR_SAFE_SKIP",
            "read": f"Erreur V4.9F : {exc}",
            "top_feature": "N/A",
            "candidate_count": 0,
            "watch_count": 0,
            "cards": [{"label": "V4.9F runner", "value": "Error", "delta": "safe skip"}],
            "summary": summary,
            "selection": pd.DataFrame(),
            "runner_spec": pd.DataFrame(),
            "gates": pd.DataFrame(),
            "signal_schema": pd.DataFrame(),
            "next_actions": pd.DataFrame(),
            "evidence": pd.DataFrame(),
        }


def _render_source_micro_runner_v49f(
    v49e_pack: Any = None,
    v49d_pack: Any = None,
    v49c_pack: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    """
    Streamlit renderer for V4.9F.
    Read-only source-only blueprint. No main engine impact.
    """
    pack = _source_micro_runner_v49f_pack(
        v49e_pack=v49e_pack,
        v49d_pack=v49d_pack,
        v49c_pack=v49c_pack,
        ticker=ticker,
    )

    st.subheader("External Source Micro-Runner / Source-Only Blueprint V4.9F")
    st.caption(
        "Micro-runner lecture seule après V4.9E : transforme la source externe candidate en spécification "
        "source-only causale t+1. Aucun signal moteur, aucun trade, aucune equity curve, aucun sizing, aucun OOS "
        "et aucun verdict ne sont modifiés."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", "Unavailable"))
    read = str(pack.get("read", ""))

    if "ready" in level.lower() or str(pack.get("decision", "")).startswith("BUILD_V49F"):
        st.success(f"Lecture V4.9F : {read}")
    elif "review" in level.lower() or "watch" in level.lower() or "refine" in str(pack.get("decision", "")).lower():
        st.warning(f"Lecture V4.9F : {read}")
    elif "error" in level.lower() or "no" in level.lower():
        st.error(f"Lecture V4.9F : {read}")
    else:
        st.info(f"Lecture V4.9F : {read}")

    with st.expander("V4.9F micro-runner summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.9F indisponible.")

    with st.expander("V4.9F source selection table", expanded=True):
        selection = pack.get("selection", pd.DataFrame())
        if isinstance(selection, pd.DataFrame) and not selection.empty:
            display = selection.copy()
            for col in ["hit_rate", "mean_forward_active", "mean_forward_median"]:
                if col in display.columns:
                    display[col] = pd.to_numeric(display[col], errors="coerce").map(lambda x: _format_pct(x))
            for col in ["score", "v49f_runner_score", "sample", "benchmarks_passed", "benchmark_count"]:
                if col in display.columns:
                    display[col] = pd.to_numeric(display[col], errors="coerce").map(lambda x: _format_num(x, 0))
            st.dataframe(display, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune source sélectionnable pour V4.9F.")

    with st.expander("V4.9F runner gates", expanded=True):
        gates = pack.get("gates", pd.DataFrame())
        if isinstance(gates, pd.DataFrame) and not gates.empty:
            st.dataframe(gates, use_container_width=True, hide_index=True)
        else:
            st.info("Gates V4.9F indisponibles.")

    with st.expander("V4.9F source-only runner spec", expanded=True):
        spec = pack.get("runner_spec", pd.DataFrame())
        if isinstance(spec, pd.DataFrame) and not spec.empty:
            st.dataframe(spec, use_container_width=True, hide_index=True)
        else:
            st.info("Spécification runner V4.9F indisponible.")

    with st.expander("V4.9F causal signal schema", expanded=False):
        schema = pack.get("signal_schema", pd.DataFrame())
        if isinstance(schema, pd.DataFrame) and not schema.empty:
            st.dataframe(schema, use_container_width=True, hide_index=True)
        else:
            st.info("Schéma signal causal V4.9F indisponible.")

    with st.expander("V4.9F next controlled actions", expanded=True):
        actions = pack.get("next_actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions contrôlées V4.9F indisponibles.")

    with st.expander("V4.9F raw evidence rows", expanded=False):
        evidence = pack.get("evidence", pd.DataFrame())
        if isinstance(evidence, pd.DataFrame) and not evidence.empty:
            st.dataframe(evidence, use_container_width=True, hide_index=True)
        else:
            st.info("Evidence V4.9F indisponible.")

    d1, d2 = st.columns(2)

    selection = pack.get("selection", pd.DataFrame())
    spec = pack.get("runner_spec", pd.DataFrame())

    if isinstance(selection, pd.DataFrame) and not selection.empty:
        d1.download_button(
            "Télécharger V4.9F source selection CSV",
            data=selection.to_csv(index=False).encode("utf-8"),
            file_name="v49f_source_selection.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49f_source_selection_download",
        )

    if isinstance(spec, pd.DataFrame) and not spec.empty:
        d2.download_button(
            "Télécharger V4.9F runner spec CSV",
            data=spec.to_csv(index=False).encode("utf-8"),
            file_name="v49f_source_runner_spec.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49f_runner_spec_download",
        )

    return pack

