def _v49f1_first_df(container: Any, keys: list[str] | None = None) -> pd.DataFrame:
    """
    Defensive extractor for V4.9F.1.
    Accepts a DataFrame directly or a dict containing one of the expected tables.
    """
    keys = keys or []

    try:
        if isinstance(container, pd.DataFrame):
            return container.copy()

        if not isinstance(container, dict):
            return pd.DataFrame()

        for key in keys:
            value = container.get(key)
            if isinstance(value, pd.DataFrame) and not value.empty:
                return value.copy()

        for _, value in container.items():
            if isinstance(value, pd.DataFrame) and not value.empty:
                return value.copy()

    except Exception:
        pass

    return pd.DataFrame()


def _v49f1_gate_status_counts(gates: pd.DataFrame) -> dict[str, int]:
    """Count blocking/review/pass statuses from a V4.9F gate table."""
    out = {
        "blocking": 0,
        "review": 0,
        "pass": 0,
        "warn": 0,
        "fail": 0,
        "unknown": 0,
    }

    if gates is None or not isinstance(gates, pd.DataFrame) or gates.empty:
        out["unknown"] = 1
        return out

    status_col = None
    for col in gates.columns:
        norm = str(col).lower().strip().replace(" ", "_")
        if norm in {"status", "gate_status", "decision", "result"}:
            status_col = col
            break

    if status_col is None:
        out["unknown"] = len(gates)
        return out

    statuses = gates[status_col].astype(str).str.upper().str.strip()

    blocking_tokens = ["FAIL", "BLOCK", "BLOCKED", "NO", "NOT_YET", "NOT READY", "REJECT"]
    review_tokens = ["REVIEW", "WARN", "WATCH", "CAUTION", "LOW_SAMPLE", "LOW SAMPLE"]
    pass_tokens = ["PASS", "READY", "OK", "CLEAN"]

    for status in statuses:
        if any(tok in status for tok in blocking_tokens):
            out["blocking"] += 1
            out["fail"] += 1
        elif any(tok in status for tok in review_tokens):
            out["review"] += 1
            out["warn"] += 1
        elif any(tok in status for tok in pass_tokens):
            out["pass"] += 1
        else:
            out["unknown"] += 1

    return out


def _v49f1_pick_top_source(v49f_pack: Any) -> dict[str, Any]:
    """
    Extract the top source identity and evidence from V4.9F.

    Correction V4.9F.1:
    - do not re-rank the selection table in a way that changes the source identity;
    - preserve v49f_pack["top_family"] + v49f_pack["top_feature"] as source of truth;
    - use the matching row only to enrich sample / hit-rate / active-return evidence.
    """
    result = {
        "feature_family": "N/A",
        "feature_name": "N/A",
        "score": np.nan,
        "sample": np.nan,
        "hit_rate": np.nan,
        "mean_forward_active": np.nan,
        "mean_forward_median": np.nan,
        "benchmarks_passed": np.nan,
        "benchmark_count": np.nan,
        "source_level": "N/A",
        "decision": "N/A",
    }

    def _bad_identity(value: Any) -> bool:
        txt = str(value or "").strip()
        return txt in {"", "N/A", "NA", "None", "nan"}

    def _norm_identity(value: Any) -> str:
        try:
            return str(value or "").strip().lower().replace(" ", "_").replace("-", "_")
        except Exception:
            return ""

    def _first_existing_col(df: pd.DataFrame, candidates: list[str]) -> str | None:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return None

        lookup = {str(c).strip().lower(): c for c in df.columns}

        for candidate in candidates:
            key = str(candidate).strip().lower()
            if key in lookup:
                return lookup[key]

        for candidate in candidates:
            key = str(candidate).strip().lower()
            for low_col, real_col in lookup.items():
                if key and key in low_col:
                    return real_col

        return None

    try:
        v49f_pack = v49f_pack if isinstance(v49f_pack, dict) else {}

        # V4.9F explicit identity is the source of truth.
        result["feature_name"] = str(v49f_pack.get("top_feature", "N/A"))
        result["feature_family"] = str(v49f_pack.get("top_family", "N/A"))
        result["score"] = _safe_float(v49f_pack.get("score"), np.nan)
        result["decision"] = str(v49f_pack.get("decision", "N/A"))

        selection = _v49f1_first_df(
            v49f_pack,
            ["selection", "evidence", "candidate_sources", "source_selection"],
        )

        if selection.empty:
            return result

        work = selection.copy()
        work.columns = [str(c).strip() for c in work.columns]

        family_col = _first_existing_col(work, ["feature_family", "family", "source_family"])
        feature_col = _first_existing_col(work, ["feature_name", "feature", "source", "top_feature"])

        row_to_use = None

        pack_family_norm = _norm_identity(result.get("feature_family"))
        pack_feature_norm = _norm_identity(result.get("feature_name"))

        # Priority 1: enrich from the exact V4.9F identity row.
        if (
            family_col is not None
            and feature_col is not None
            and not _bad_identity(result.get("feature_family"))
            and not _bad_identity(result.get("feature_name"))
        ):
            fam_norm = work[family_col].map(_norm_identity)
            feat_norm = work[feature_col].map(_norm_identity)

            exact = work[
                (fam_norm == pack_family_norm)
                & (feat_norm == pack_feature_norm)
            ].copy()

            if not exact.empty:
                if "v49f_runner_score" in exact.columns:
                    exact["_sort_score"] = pd.to_numeric(exact["v49f_runner_score"], errors="coerce").fillna(-1.0)
                    exact = exact.sort_values("_sort_score", ascending=False)
                elif "score" in exact.columns:
                    exact["_sort_score"] = pd.to_numeric(exact["score"], errors="coerce").fillna(-1.0)
                    exact = exact.sort_values("_sort_score", ascending=False)

                row_to_use = exact.iloc[0]

        # Priority 2: only if V4.9F did not provide identity, take the best row.
        if row_to_use is None:
            rank = work.copy()

            if "is_candidate" in rank.columns:
                rank["_candidate_sort"] = rank["is_candidate"].astype(bool).astype(int)
            elif "decision" in rank.columns:
                rank["_candidate_sort"] = rank["decision"].astype(str).str.upper().str.contains(
                    "CANDIDATE|SOURCE_CANDIDATE|SELECTED",
                    regex=True,
                    na=False,
                ).astype(int)
            else:
                rank["_candidate_sort"] = 0

            if "v49f_runner_score" in rank.columns:
                rank["_score_sort"] = pd.to_numeric(rank["v49f_runner_score"], errors="coerce").fillna(-1.0)
            elif "score" in rank.columns:
                rank["_score_sort"] = pd.to_numeric(rank["score"], errors="coerce").fillna(-1.0)
            else:
                rank["_score_sort"] = -1.0

            rank = rank.sort_values(["_candidate_sort", "_score_sort"], ascending=[False, False])
            row_to_use = rank.iloc[0] if not rank.empty else None

        if row_to_use is None:
            return result

        # Fill identity only if pack identity was missing.
        if family_col is not None and _bad_identity(result.get("feature_family")):
            result["feature_family"] = str(row_to_use.get(family_col, "N/A"))

        if feature_col is not None and _bad_identity(result.get("feature_name")):
            result["feature_name"] = str(row_to_use.get(feature_col, "N/A"))

        for key, candidates in {
            "source_level": ["source_level", "level"],
        }.items():
            for col in candidates:
                if col in work.columns and str(row_to_use.get(col, "")).strip():
                    result[key] = str(row_to_use.get(col))
                    break

        for key, candidates in {
            "score": ["v49f_runner_score", "score"],
            "sample": ["sample", "rows", "event_count"],
            "hit_rate": ["hit_rate", "hit_10b"],
            "mean_forward_active": ["mean_forward_active", "avg_active_10b", "avg_active_20b"],
            "mean_forward_median": ["mean_forward_median", "median_active_10b", "median_active_20b"],
            "benchmarks_passed": ["benchmarks_passed", "benchmark_pass_count"],
            "benchmark_count": ["benchmark_count", "benchmarks", "bench_count"],
        }.items():
            for col in candidates:
                if col in work.columns:
                    val = _safe_float(row_to_use.get(col), np.nan)
                    if pd.notna(val):
                        result[key] = val
                        break

    except Exception:
        pass

    return result


def _source_micro_runner_gate_review_v49f1_pack(
    v49f_pack: Any = None,
    v49e_pack: Any = None,
    v49d_pack: Any = None,
    v49c_pack: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    """
    Source-Only Runner Gate Review V4.9F.1.

    Purpose:
    - explain exactly why V4.9F is review-only or runner-ready;
    - preserve the source identity bridge: family + feature;
    - define the next source-only micro-runner contract;
    - prevent accidental OOS/promotion before gates are clean.

    Strict guardrail:
    - no main engine mutation;
    - no signal execution;
    - no trades;
    - no equity curve mutation;
    - no sizing/exits/OOS/live promotion.
    """
    try:
        v49f_pack = v49f_pack if isinstance(v49f_pack, dict) else {}

        top = _v49f1_pick_top_source(v49f_pack)
        gates = _v49f1_first_df(v49f_pack, ["gates", "runner_gates", "selection_gates"])
        selection = _v49f1_first_df(v49f_pack, ["selection", "evidence", "candidate_sources", "source_selection"])
        runner_spec = _v49f1_first_df(v49f_pack, ["runner_spec", "source_runner_spec", "spec"])
        signal_schema = _v49f1_first_df(v49f_pack, ["signal_schema", "causal_signal_schema", "schema"])

        gate_counts = _v49f1_gate_status_counts(gates)

        top_family = str(top.get("feature_family", "N/A"))
        top_feature = str(top.get("feature_name", "N/A"))
        top_score = _safe_float(top.get("score"), np.nan)
        sample = _safe_float(top.get("sample"), np.nan)
        hit_rate = _safe_float(top.get("hit_rate"), np.nan)
        mean_active = _safe_float(top.get("mean_forward_active"), np.nan)
        median_active = _safe_float(top.get("mean_forward_median"), np.nan)
        bench_passed = _safe_float(top.get("benchmarks_passed"), np.nan)
        bench_count = _safe_float(top.get("benchmark_count"), np.nan)

        blocking = int(_safe_float(v49f_pack.get("blocking_gates"), gate_counts.get("blocking", 0)))
        review = int(_safe_float(v49f_pack.get("review_gates"), gate_counts.get("review", 0)))
        candidate_count = int(_safe_float(v49f_pack.get("candidate_count"), 0))
        watch_count = int(_safe_float(v49f_pack.get("watch_count"), 0))
        v49f_decision = str(v49f_pack.get("decision", "N/A"))
        v49f_level = str(v49f_pack.get("level", "N/A"))

        source_identity_ok = top_family not in {"", "N/A", "nan", "None"} and top_feature not in {"", "N/A", "nan", "None"}
        has_candidate = candidate_count > 0 or "CANDIDATE" in str(v49f_decision).upper() or "BUILD_V49F" in str(v49f_decision).upper()
        sample_ok = pd.notna(sample) and sample >= 20
        score_ok = pd.notna(top_score) and top_score >= 75
        hit_ok = pd.notna(hit_rate) and hit_rate >= 0.50
        mean_ok = pd.notna(mean_active) and mean_active > 0
        median_ok = pd.notna(median_active) and median_active >= 0

        if pd.notna(bench_count) and bench_count > 0:
            bench_ok = pd.notna(bench_passed) and bench_passed >= max(2, min(3, bench_count))
        else:
            bench_ok = True

        spec_ok = isinstance(runner_spec, pd.DataFrame) and not runner_spec.empty
        schema_ok = isinstance(signal_schema, pd.DataFrame) and not signal_schema.empty

        review_rows = [
            {
                "Gate": "V4.9F pack present",
                "Status": "PASS" if bool(v49f_pack) else "FAIL",
                "Severity": "None" if bool(v49f_pack) else "Critical",
                "Value": v49f_level,
                "Read": "V4.9F doit exister avant V4.9F.1.",
            },
            {
                "Gate": "Source identity bridge",
                "Status": "PASS" if source_identity_ok else "FAIL",
                "Severity": "None" if source_identity_ok else "Critical",
                "Value": f"{top_family}:{top_feature}",
                "Read": "Préserve famille + feature exacte pour éviter de confondre earnings et revenue_surprise_pct.",
            },
            {
                "Gate": "Candidate source",
                "Status": "PASS" if has_candidate else "FAIL",
                "Severity": "None" if has_candidate else "High",
                "Value": f"candidates={candidate_count}, watch={watch_count}",
                "Read": "Il faut au moins une source candidate ou un build V4.9F review-only.",
            },
            {
                "Gate": "Runner gates clean",
                "Status": "PASS" if blocking == 0 else "REVIEW",
                "Severity": "None" if blocking == 0 else "High",
                "Value": f"blocking={blocking}, review={review}",
                "Read": "Si un gate bloque, V4.9F.1 doit expliquer avant tout runner actif.",
            },
            {
                "Gate": "Top score sufficient",
                "Status": "PASS" if score_ok else "REVIEW",
                "Severity": "None" if score_ok else "Medium",
                "Value": _format_num(top_score, 0) if pd.notna(top_score) else "N/A",
                "Read": "Score de préparation runner, pas performance live.",
            },
            {
                "Gate": "Sample sufficient",
                "Status": "PASS" if sample_ok else "REVIEW",
                "Severity": "None" if sample_ok else "Medium",
                "Value": _format_num(sample, 0) if pd.notna(sample) else "N/A",
                "Read": "Minimum pratique pour un micro-runner review-only : 20 observations source.",
            },
            {
                "Gate": "Positive mean active",
                "Status": "PASS" if mean_ok else "REVIEW",
                "Severity": "None" if mean_ok else "Medium",
                "Value": _format_pct(mean_active) if pd.notna(mean_active) else "N/A",
                "Read": "La moyenne active forward doit rester positive.",
            },
            {
                "Gate": "Non-negative median active",
                "Status": "PASS" if median_ok else "REVIEW",
                "Severity": "None" if median_ok else "Medium",
                "Value": _format_pct(median_active) if pd.notna(median_active) else "N/A",
                "Read": "La médiane évite de valider une source portée par quelques outliers.",
            },
            {
                "Gate": "Hit-rate >= 50%",
                "Status": "PASS" if hit_ok else "REVIEW",
                "Severity": "None" if hit_ok else "Medium",
                "Value": _format_pct(hit_rate) if pd.notna(hit_rate) else "N/A",
                "Read": "Le hit-rate confirme que la source n'est pas uniquement asymétrique/outlier.",
            },
            {
                "Gate": "Multi-benchmark robustness",
                "Status": "PASS" if bench_ok else "REVIEW",
                "Severity": "None" if bench_ok else "Medium",
                "Value": f"{_format_num(bench_passed, 0)}/{_format_num(bench_count, 0)}" if pd.notna(bench_count) else "N/A",
                "Read": "La source doit rester exploitable au-delà d'un seul benchmark.",
            },
            {
                "Gate": "Runner spec present",
                "Status": "PASS" if spec_ok else "REVIEW",
                "Severity": "None" if spec_ok else "Medium",
                "Value": f"{len(runner_spec)} rows" if spec_ok else "missing",
                "Read": "Le blueprint source-only doit être lisible avant construction du runner.",
            },
            {
                "Gate": "Causal signal schema present",
                "Status": "PASS" if schema_ok else "REVIEW",
                "Severity": "None" if schema_ok else "Medium",
                "Value": f"{len(signal_schema)} rows" if schema_ok else "missing",
                "Read": "Le signal doit être défini avec available_at, decision_date et t+1.",
            },
        ]

        gate_review = pd.DataFrame(review_rows)

        fail_count = int((gate_review["Status"].astype(str) == "FAIL").sum())
        review_count = int((gate_review["Status"].astype(str) == "REVIEW").sum())
        high_or_critical = int(gate_review["Severity"].astype(str).isin(["High", "Critical"]).sum())

        score = 100.0
        score -= fail_count * 35.0
        score -= review_count * 7.5
        score -= high_or_critical * 10.0
        score = max(0.0, min(100.0, score))

        if fail_count > 0:
            level = "Runner blocked"
            decision = "RETURN_TO_V49F_OR_V49E"
            read = "V4.9F.1 détecte un blocage structurel : ne pas construire de runner actif."
        elif blocking > 0 or review_count > 0:
            level = "Runner review required"
            decision = "BUILD_V49F_REVIEW_RUNNER_ONLY"
            read = "La source est exploitable pour un micro-runner review-only, mais pas encore pour OOS/promotion."
        else:
            level = "Runner contract ready"
            decision = "PREPARE_V49G_SOURCE_ONLY_TEST"
            read = "Les gates F.1 sont propres : préparer un test source-only isolé, toujours sans promotion moteur."

        blocker_map = gate_review[gate_review["Status"].astype(str).isin(["FAIL", "REVIEW"])].copy()
        if blocker_map.empty:
            blocker_map = pd.DataFrame(
                [["None", "PASS", "None", "All gates clean", "Aucun bloqueur V4.9F.1 détecté."]],
                columns=["Gate", "Status", "Severity", "Value", "Read"],
            )

        source_bridge = pd.DataFrame(
            [
                ["ticker", str(ticker or "N/A"), "Ticker audité."],
                ["source_family", top_family, "Famille externe. Exemple : earnings."],
                ["source_feature", top_feature, "Feature exacte. Exemple : revenue_surprise_pct."],
                ["source_level", str(top.get("source_level", "N/A")), "Bloc d'origine : V4.9E/V4.9D/V4.9C."],
                ["v49f_decision", v49f_decision, "Décision héritée de V4.9F."],
                ["v49f_level", v49f_level, "Niveau hérité de V4.9F."],
                ["top_score", _format_num(top_score, 0) if pd.notna(top_score) else "N/A", "Score source runner."],
                ["sample", _format_num(sample, 0) if pd.notna(sample) else "N/A", "Nombre d'observations source si disponible."],
                ["hit_rate", _format_pct(hit_rate) if pd.notna(hit_rate) else "N/A", "Hit-rate forward si disponible."],
                ["mean_forward_active", _format_pct(mean_active) if pd.notna(mean_active) else "N/A", "Moyenne active forward."],
                ["median_forward_active", _format_pct(median_active) if pd.notna(median_active) else "N/A", "Médiane active forward."],
                ["benchmark_robustness", f"{_format_num(bench_passed, 0)}/{_format_num(bench_count, 0)}" if pd.notna(bench_count) else "N/A", "Nombre de benchmarks passés."],
            ],
            columns=["Field", "Value", "Read"],
        )

        runner_contract = pd.DataFrame(
            [
                ["Input", "V4.9A/V4.9B.3 audited external features", "Utiliser uniquement features nettoyées, point-in-time."],
                ["Source family", top_family, "Ne pas mélanger plusieurs familles dans le premier runner."],
                ["Source feature", top_feature, "Tester la feature candidate exacte."],
                ["Decision timestamp", "available_at", "Le signal ne peut exister qu'après disponibilité réelle."],
                ["Signal timing", "decision_date = next trading bar after available_at", "Pas de same-close lookahead."],
                ["Execution timing", "position_t = signal.shift(1)", "Même discipline t+1 que Custom Signal Import."],
                ["Direction rule", "feature threshold -> exposure in {0, 1}", "Long-only source test en premier, pas de sizing optimisé."],
                ["Holding grid", "3B / 5B / 10B / 20B", "Tester horizon source, pas exits optimisés."],
                ["Benchmark", "SMH + QQQ + XLK + SOXX + SPY if available", "Préserver la logique multi-benchmark V4.9D."],
                ["Forbidden", "OOS / promotion / live / exits / sizing", "Interdit avant validation source-only positive."],
            ],
            columns=["Contract", "Value", "Read"],
        )

        next_actions = pd.DataFrame(
            [
                ["P0", "Do not OOS", "V4.9F.1 is gate review", "OOS interdit tant qu'un source-only runner n'a pas confirmé l'edge."],
                ["P0", "Do not promote", "No engine signal yet", "Aucune donnée externe ne doit modifier le moteur courant."],
                ["P0", "Keep source identity", f"{top_family}:{top_feature}", "Toujours afficher famille + feature exacte dans les prochains blocs."],
                ["P1", "Build review-only runner shell", decision, "Construire V4.9G seulement si ce bloc est Runner contract ready ou review-only assumé."],
                ["P1", "Audit blocking gates", f"blocking={blocking}, review={review_count}", "Corriger ou documenter chaque gate avant un test source-only."],
                ["P2", "Prepare V4.9G source-only test", top_feature, "Runner isolé, signal causal t+1, aucun sizing/exits/OOS."],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        summary = pd.DataFrame(
            [
                ["V4.9F.1 level", level, "Lecture synthétique du gate review micro-runner."],
                ["V4.9F.1 score", f"{_format_num(score, 0)}/100", "Score de readiness runner, pas score alpha/live."],
                ["Decision", decision, "Décision research V4.9F.1."],
                ["Read", read, "Interprétation opérationnelle."],
                ["Ticker", str(ticker or "N/A"), "Ticker audité."],
                ["Source family", top_family, "Famille retenue."],
                ["Source feature", top_feature, "Feature exacte retenue."],
                ["V4.9F decision", v49f_decision, "Décision du bloc précédent."],
                ["V4.9F blocking gates", str(blocking), "Bloqueurs hérités de V4.9F."],
                ["F.1 fail gates", str(fail_count), "Bloqueurs structurels détectés par F.1."],
                ["F.1 review gates", str(review_count), "Points à revoir avant V4.9G."],
                ["Candidate count", str(candidate_count), "Nombre de sources candidates héritées."],
                ["Watch count", str(watch_count), "Nombre de sources watchlist."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        cards = [
            {"label": "V4.9F.1 gate", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Source family", "value": top_family, "delta": "identity"},
            {"label": "Source feature", "value": top_feature, "delta": "exact"},
            {"label": "Blocking gates", "value": str(blocking + fail_count), "delta": "no OOS"},
            {"label": "Review gates", "value": str(review_count), "delta": "before V4.9G"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "top_family": top_family,
            "top_feature": top_feature,
            "blocking_gates": int(blocking + fail_count),
            "review_gates": int(review_count),
            "cards": cards,
            "summary": summary,
            "gate_review": gate_review,
            "blocker_map": blocker_map,
            "source_bridge": source_bridge,
            "runner_contract": runner_contract,
            "next_actions": next_actions,
            "selection": selection,
            "runner_spec": runner_spec,
            "signal_schema": signal_schema,
        }

    except Exception as exc:
        summary = pd.DataFrame(
            [["V4.9F.1 error", str(exc), "Erreur capturée sans interrompre le backtest."]],
            columns=["Metric", "Value", "Read"],
        )
        return {
            "enabled": False,
            "level": "V4.9F.1 error",
            "score": 0.0,
            "decision": "V49F1_ERROR_SAFE_SKIP",
            "read": f"Erreur V4.9F.1 : {exc}",
            "top_family": "N/A",
            "top_feature": "N/A",
            "blocking_gates": 1,
            "review_gates": 0,
            "cards": [{"label": "V4.9F.1 gate", "value": "Error", "delta": "safe skip"}],
            "summary": summary,
            "gate_review": pd.DataFrame(),
            "blocker_map": pd.DataFrame(),
            "source_bridge": pd.DataFrame(),
            "runner_contract": pd.DataFrame(),
            "next_actions": pd.DataFrame(),
            "selection": pd.DataFrame(),
            "runner_spec": pd.DataFrame(),
            "signal_schema": pd.DataFrame(),
        }


