def _v49g_norm(value: Any) -> str:
    try:
        return str(value or "").strip().lower().replace(" ", "_").replace("-", "_")
    except Exception:
        return ""


def _v49g_col(df: pd.DataFrame, candidates: list[str]) -> str | None:
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return None

    lookup = {_v49g_norm(c): c for c in df.columns}

    for candidate in candidates:
        key = _v49g_norm(candidate)
        if key in lookup:
            return lookup[key]

    for candidate in candidates:
        key = _v49g_norm(candidate)
        for norm_col, original in lookup.items():
            if key and (norm_col == key or key in norm_col):
                return original

    return None


def _v49g_parse_number(value: Any, default: float = np.nan) -> float:
    try:
        if value is None or pd.isna(value):
            return default
        txt = str(value).strip().replace(",", ".")
        if txt == "" or txt.upper() in {"N/A", "NA", "NONE", "NAN"}:
            return default
        is_pct = "%" in txt
        txt = txt.replace("%", "").replace("$", "").replace(" ", "")
        out = float(txt)
        return out / 100.0 if is_pct else out
    except Exception:
        return default


def _v49g_collect_dataframes(obj: Any, prefix: str = "root", depth: int = 0) -> list[tuple[str, pd.DataFrame]]:
    """Collect DataFrames recursively from packs/session_state without assuming exact key names."""
    if depth > 5:
        return []

    found: list[tuple[str, pd.DataFrame]] = []

    if isinstance(obj, pd.DataFrame):
        if not obj.empty:
            found.append((prefix, obj.copy()))
        return found

    if isinstance(obj, dict):
        for key, value in obj.items():
            found.extend(_v49g_collect_dataframes(value, f"{prefix}.{key}", depth + 1))
        return found

    if isinstance(obj, (list, tuple)):
        for i, value in enumerate(obj):
            found.extend(_v49g_collect_dataframes(value, f"{prefix}[{i}]", depth + 1))

    return found


def _v49g_normalize_external_features(df: pd.DataFrame, ticker: str = "") -> pd.DataFrame:
    """
    Normalize V4.9A/V4.9B/V4.9B.3 external feature rows into one stable schema.
    Required target schema:
    date, available_at, ticker, feature_family, feature_name, value, source, confidence, notes.
    """
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame()

    work = df.copy()
    work.columns = [str(c).strip() for c in work.columns]

    date_col = _v49g_col(work, ["date", "event_date", "observation_date", "decision_date"])
    available_col = _v49g_col(work, ["available_at", "available", "published_at", "release_time", "asof", "as_of"])
    ticker_col = _v49g_col(work, ["ticker", "symbol", "asset"])
    family_col = _v49g_col(work, ["feature_family", "family", "source_family", "data_family"])
    feature_col = _v49g_col(work, ["feature_name", "feature", "source_feature", "name", "metric"])
    value_col = _v49g_col(work, ["value", "feature_value", "signal_value", "state"])
    source_col = _v49g_col(work, ["source", "provider", "source_tag", "vendor"])
    confidence_col = _v49g_col(work, ["confidence", "quality", "reliability"])
    notes_col = _v49g_col(work, ["notes", "note", "comment", "headline"])

    if feature_col is None or value_col is None:
        return pd.DataFrame()

    out = pd.DataFrame(index=work.index)
    out["date"] = pd.to_datetime(work[date_col], errors="coerce") if date_col else pd.NaT
    out["available_at"] = pd.to_datetime(work[available_col], errors="coerce") if available_col else out["date"]
    out["ticker"] = work[ticker_col].astype(str).str.upper().str.strip() if ticker_col else str(ticker or "").upper().strip()
    out["feature_family"] = work[family_col].astype(str).map(_v49g_norm) if family_col else "external"
    out["feature_name"] = work[feature_col].astype(str).str.strip()
    out["value_raw"] = work[value_col]
    out["value_num"] = work[value_col].map(_v49g_parse_number)
    out["value_text"] = work[value_col].astype(str).str.strip().str.lower()
    out["source"] = work[source_col].astype(str).str.strip() if source_col else "unknown"
    out["confidence"] = work[confidence_col].map(_v49g_parse_number) if confidence_col else np.nan
    out["notes"] = work[notes_col].astype(str).str.strip() if notes_col else ""

    out = out.replace([np.inf, -np.inf], np.nan)
    out = out.dropna(subset=["available_at"])
    out = out[out["feature_name"].astype(str).str.strip() != ""]

    wanted = str(ticker or "").upper().strip()
    if wanted:
        out = out[(out["ticker"].astype(str).str.upper().str.strip() == wanted) | (out["ticker"].astype(str).str.strip() == "")]

    out = out.sort_values(["available_at", "feature_family", "feature_name"]).reset_index(drop=True)
    return out


def _v49g_find_external_features(
    external_features: Any = None,
    v49a_pack: Any = None,
    v49b_pack: Any = None,
    v49b3_pack: Any = None,
    v49b2_pack: Any = None,
    ticker: str = "",
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Find the best audited external feature table from explicit args, packs, or session_state."""
    sources: list[tuple[str, Any]] = [
        ("external_features", external_features),
        ("v49b3_pack", v49b3_pack),
        ("v49b_pack", v49b_pack),
        ("v49a_pack", v49a_pack),
        ("v49b2_pack", v49b2_pack),
    ]

    try:
        if "st" in globals() and hasattr(st, "session_state"):
            for key in list(st.session_state.keys()):
                if any(tok in str(key).lower() for tok in ["v49", "external", "feature", "catalyst"]):
                    sources.append((f"session_state.{key}", st.session_state.get(key)))
    except Exception:
        pass

    candidates: list[dict[str, Any]] = []

    for source_name, obj in sources:
        for path, df in _v49g_collect_dataframes(obj, prefix=source_name):
            norm = _v49g_normalize_external_features(df, ticker=ticker)
            if norm.empty:
                continue

            schema_score = 0
            cols = {_v49g_norm(c) for c in df.columns}
            for token in ["date", "available_at", "ticker", "feature_family", "feature_name", "value", "source", "confidence"]:
                if token in cols:
                    schema_score += 1

            candidates.append(
                {
                    "source_path": path,
                    "rows": int(len(norm)),
                    "families": int(norm["feature_family"].nunique()),
                    "features": int(norm["feature_name"].nunique()),
                    "sources": int(norm["source"].nunique()),
                    "schema_score": schema_score,
                    "table": norm,
                }
            )

    if not candidates:
        return pd.DataFrame(), pd.DataFrame()

    audit = pd.DataFrame([{k: v for k, v in c.items() if k != "table"} for c in candidates])
    audit = audit.sort_values(["schema_score", "rows", "features"], ascending=[False, False, False]).reset_index(drop=True)

    best_path = str(audit.iloc[0]["source_path"])
    best = next(c["table"] for c in candidates if str(c["source_path"]) == best_path)

    return best.copy(), audit


def _v49g_pick_source_identity(v49f1_pack: Any = None, v49f_pack: Any = None) -> dict[str, str]:
    """Extract source_family/source_feature from V4.9F.1 first, then V4.9F fallback."""
    out = {"source_family": "N/A", "source_feature": "N/A"}

    try:
        if isinstance(v49f1_pack, dict):
            fam = str(v49f1_pack.get("top_family", "") or "").strip()
            feat = str(v49f1_pack.get("top_feature", "") or "").strip()
            if fam and fam.upper() not in {"N/A", "NA", "NONE", "NAN"}:
                out["source_family"] = fam
            if feat and feat.upper() not in {"N/A", "NA", "NONE", "NAN"}:
                out["source_feature"] = feat

            bridge = None
            for key in ["source_bridge", "source_identity_bridge"]:
                value = v49f1_pack.get(key)
                if isinstance(value, pd.DataFrame) and not value.empty:
                    bridge = value.copy()
                    break

            if bridge is not None:
                field_col = _v49g_col(bridge, ["Field", "field", "Metric", "metric"])
                value_col = _v49g_col(bridge, ["Value", "value"])
                if field_col and value_col:
                    for _, row in bridge.iterrows():
                        field = _v49g_norm(row.get(field_col))
                        val = str(row.get(value_col, "") or "").strip()
                        if field in {"source_family", "feature_family"} and val:
                            out["source_family"] = val
                        if field in {"source_feature", "feature_name", "top_feature"} and val:
                            out["source_feature"] = val

        if isinstance(v49f_pack, dict):
            if out["source_family"] in {"", "N/A"}:
                out["source_family"] = str(v49f_pack.get("top_family", "N/A"))
            if out["source_feature"] in {"", "N/A"}:
                out["source_feature"] = str(v49f_pack.get("top_feature", "N/A"))

    except Exception:
        pass

    out["source_family"] = _v49g_norm(out.get("source_family", "N/A")) or "N/A"
    out["source_feature"] = str(out.get("source_feature", "N/A") or "N/A").strip()
    return out


def _v49g_trading_position(price_index: pd.Index, ts: Any) -> int | None:
    try:
        if price_index is None or len(price_index) == 0:
            return None
        idx = pd.to_datetime(pd.Index(price_index), errors="coerce")
        target = pd.to_datetime(ts, errors="coerce")
        if pd.isna(target):
            return None
        positions = np.where(idx >= target.normalize())[0]
        if len(positions) == 0:
            return None
        return int(positions[0])
    except Exception:
        return None


def _v49g_build_rule_masks(feature_rows: pd.DataFrame) -> list[dict[str, Any]]:
    """Create source-only review rules from the selected external feature values."""
    if feature_rows is None or not isinstance(feature_rows, pd.DataFrame) or feature_rows.empty:
        return []

    rows = feature_rows.copy()
    nums = pd.to_numeric(rows.get("value_num"), errors="coerce")
    has_num = nums.notna().sum() >= max(3, int(len(rows) * 0.40))

    rules: list[dict[str, Any]] = []

    if has_num:
        clean = nums.dropna()
        q75 = float(clean.quantile(0.75)) if not clean.empty else np.nan
        median = float(clean.median()) if not clean.empty else np.nan

        rules.append(
            {
                "rule_name": "value_top_quartile",
                "threshold": q75,
                "direction": "long_if_value_high",
                "mask": nums >= q75,
                "read": "Long review when selected feature is in its top quartile.",
            }
        )
        rules.append(
            {
                "rule_name": "value_above_median",
                "threshold": median,
                "direction": "long_if_value_above_median",
                "mask": nums >= median,
                "read": "Long review when selected feature is above or equal to its median.",
            }
        )
        rules.append(
            {
                "rule_name": "value_positive",
                "threshold": 0.0,
                "direction": "long_if_value_positive",
                "mask": nums > 0.0,
                "read": "Long review when selected feature is positive.",
            }
        )

        if clean.min() < 0:
            rules.append(
                {
                    "rule_name": "value_bottom_quartile_contrarian",
                    "threshold": float(clean.quantile(0.25)),
                    "direction": "long_if_value_low_contrarian",
                    "mask": nums <= float(clean.quantile(0.25)),
                    "read": "Contrarian review rule for low feature values.",
                }
            )

    text = rows.get("value_text", pd.Series("", index=rows.index)).astype(str).str.lower()
    positive_mask = text.str.contains("positive|bull|beat|up|raise|strong|accel", regex=True, na=False)
    negative_mask = text.str.contains("negative|bear|miss|down|cut|weak|slow", regex=True, na=False)

    if int(positive_mask.sum()) > 0:
        rules.append(
            {
                "rule_name": "text_positive_tag",
                "threshold": "positive tag",
                "direction": "long_if_positive_text",
                "mask": positive_mask,
                "read": "Long review when categorical value contains a positive catalyst tag.",
            }
        )

    if int(negative_mask.sum()) > 0:
        rules.append(
            {
                "rule_name": "text_negative_contrarian",
                "threshold": "negative tag",
                "direction": "long_if_negative_text_contrarian",
                "mask": negative_mask,
                "read": "Contrarian review when categorical value contains a negative catalyst tag.",
            }
        )

    # Deduplicate masks/rule names defensively.
    out = []
    seen = set()
    for rule in rules:
        name = str(rule.get("rule_name"))
        if name in seen:
            continue
        seen.add(name)
        out.append(rule)
    return out


def _v49g_compute_event_returns(
    df: pd.DataFrame,
    cfg: Any,
    events: pd.DataFrame,
    horizons: tuple[int, ...] = (3, 5, 10, 20),
) -> tuple[pd.DataFrame, str, bool]:
    """Compute causal source-only forward active returns from event execution bars."""
    if df is None or not isinstance(df, pd.DataFrame) or df.empty or "close" not in df.columns:
        return pd.DataFrame(), "N/A", True

    close = pd.to_numeric(df["close"], errors="coerce").replace([np.inf, -np.inf], np.nan).ffill()
    close = close.dropna()

    if close.empty or events is None or not isinstance(events, pd.DataFrame) or events.empty:
        return pd.DataFrame(), "N/A", True

    # Use the current benchmark config. If no benchmark is configured, force auto sector/SPY to avoid asset-vs-itself active returns.
    benchmark_label = "Ticker Buy & Hold"
    benchmark_fallback = True
    benchmark_returns = close.pct_change().fillna(0.0)

    try:
        local_cfg = cfg
        if local_cfg is not None and not str(getattr(local_cfg, "benchmark_ticker", "") or "").strip():
            ticker = str(getattr(local_cfg, "asset_ticker", "") or "").upper().strip()
            auto_symbol = _sector_benchmark_guess(ticker) if "_sector_benchmark_guess" in globals() else "SPY"
            if "BacktestConfig" in globals() and hasattr(local_cfg, "__dict__"):
                local_cfg = BacktestConfig(
                    **{
                        **local_cfg.__dict__,
                        "benchmark_ticker": auto_symbol,
                        "benchmark_label": f"Auto Sector ETF ({auto_symbol})",
                        "benchmark_mode": "Sector ETF",
                    }
                )

        if local_cfg is not None and "_load_benchmark_returns" in globals():
            benchmark_returns, benchmark_label, benchmark_fallback = _load_benchmark_returns(df.reindex(close.index), local_cfg)
            benchmark_returns = (
                pd.to_numeric(benchmark_returns.reindex(close.index), errors="coerce")
                .replace([np.inf, -np.inf], np.nan)
                .fillna(0.0)
            )
    except Exception:
        benchmark_returns = close.pct_change().fillna(0.0)
        benchmark_label = "Ticker Buy & Hold — fallback error"
        benchmark_fallback = True

    bench_nav = (1.0 + benchmark_returns).cumprod().replace([np.inf, -np.inf], np.nan).ffill().bfill()
    bench_nav = bench_nav.reindex(close.index).ffill().bfill()

    out_rows: list[dict[str, Any]] = []
    price_index = close.index

    for _, event in events.iterrows():
        available_at = event.get("available_at")
        decision_pos = _v49g_trading_position(price_index, available_at)

        if decision_pos is None:
            continue

        # Strict t+1 source-only review: the event becomes executable on the next bar.
        execution_pos = decision_pos + 1
        if execution_pos >= len(close):
            continue

        base_price = _safe_float(close.iloc[execution_pos], np.nan)
        base_bench = _safe_float(bench_nav.iloc[execution_pos], np.nan)

        if pd.isna(base_price) or base_price <= 0 or pd.isna(base_bench) or base_bench <= 0:
            continue

        row = {
            "event_date": _format_dt(event.get("date")),
            "available_at": str(pd.to_datetime(available_at, errors="coerce")) if pd.notna(pd.to_datetime(available_at, errors="coerce")) else str(available_at),
            "decision_date": _format_dt(price_index[decision_pos]),
            "execution_date_t1": _format_dt(price_index[execution_pos]),
            "ticker": str(event.get("ticker", "")),
            "feature_family": str(event.get("feature_family", "")),
            "feature_name": str(event.get("feature_name", "")),
            "value": event.get("value_raw"),
            "value_num": _safe_float(event.get("value_num"), np.nan),
            "source": str(event.get("source", "")),
            "confidence": _safe_float(event.get("confidence"), np.nan),
            "benchmark_label": benchmark_label,
        }

        for h in horizons:
            end_pos = execution_pos + int(h)
            if end_pos >= len(close):
                row[f"asset_return_{h}b"] = np.nan
                row[f"benchmark_return_{h}b"] = np.nan
                row[f"active_return_{h}b"] = np.nan
                continue

            asset_ret = _safe_float(close.iloc[end_pos] / base_price - 1.0, np.nan)
            bench_ret = _safe_float(bench_nav.iloc[end_pos] / base_bench - 1.0, np.nan)
            row[f"asset_return_{h}b"] = asset_ret
            row[f"benchmark_return_{h}b"] = bench_ret
            row[f"active_return_{h}b"] = asset_ret - bench_ret if pd.notna(asset_ret) and pd.notna(bench_ret) else np.nan

        out_rows.append(row)

    return pd.DataFrame(out_rows).replace([np.inf, -np.inf], np.nan), benchmark_label, bool(benchmark_fallback)


def _source_only_review_runner_v49g_pack(
    df: pd.DataFrame | None = None,
    cfg: Any = None,
    external_features: Any = None,
    v49f1_pack: Any = None,
    v49f_pack: Any = None,
    v49a_pack: Any = None,
    v49b_pack: Any = None,
    v49b2_pack: Any = None,
    v49b3_pack: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    """
    V4.9G — Source-Only Review Runner.

    Read-only micro-runner:
    - consumes the V4.9F.1 source identity and audited external feature rows;
    - builds simple causal t+1 source-only rules;
    - measures forward active returns 3B/5B/10B/20B;
    - does not mutate the main signal, trades, sizing, exits, OOS, equity curve, or verdict.
    """
    empty = {
        "enabled": False,
        "level": "Unavailable",
        "score": 0.0,
        "decision": "V49G_UNAVAILABLE",
        "read": "V4.9G indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "source_identity": pd.DataFrame(),
        "data_audit": pd.DataFrame(),
        "gates": pd.DataFrame(),
        "rule_leaderboard": pd.DataFrame(),
        "event_map": pd.DataFrame(),
        "selected_events": pd.DataFrame(),
        "next_actions": pd.DataFrame(),
    }

    try:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty or "close" not in df.columns:
            out = empty.copy()
            out["level"] = "No price frame"
            out["decision"] = "WAIT_FOR_PRICE_DATA"
            out["read"] = "V4.9G a besoin du price frame courant pour mesurer les forward returns."
            return out

        if cfg is not None and not str(ticker or "").strip():
            ticker = str(getattr(cfg, "asset_ticker", "") or "").upper().strip()

        identity = _v49g_pick_source_identity(v49f1_pack=v49f1_pack, v49f_pack=v49f_pack)
        source_family = _v49g_norm(identity.get("source_family"))
        source_feature = str(identity.get("source_feature", "N/A") or "N/A").strip()

        features, data_audit = _v49g_find_external_features(
            external_features=external_features,
            v49a_pack=v49a_pack,
            v49b_pack=v49b_pack,
            v49b2_pack=v49b2_pack,
            v49b3_pack=v49b3_pack,
            ticker=ticker,
        )

        identity_ok = source_family not in {"", "n/a", "na", "none", "nan"} and source_feature.upper() not in {"", "N/A", "NA", "NONE", "NAN"}
        data_ok = isinstance(features, pd.DataFrame) and not features.empty

        if data_ok and identity_ok:
            selected = features[
                (features["feature_family"].astype(str).map(_v49g_norm) == source_family)
                & (features["feature_name"].astype(str).str.strip() == source_feature)
            ].copy()

            # Defensive fallback for exact feature mismatch: use normalized feature name.
            if selected.empty:
                target_norm = _v49g_norm(source_feature)
                selected = features[
                    (features["feature_family"].astype(str).map(_v49g_norm) == source_family)
                    & (features["feature_name"].astype(str).map(_v49g_norm) == target_norm)
                ].copy()
        else:
            selected = pd.DataFrame()

        rule_rows: list[dict[str, Any]] = []
        event_tables: list[pd.DataFrame] = []
        benchmark_label = "N/A"
        benchmark_fallback = True

        rules = _v49g_build_rule_masks(selected)

        for rule in rules:
            mask = pd.Series(rule.get("mask", False), index=selected.index).fillna(False).astype(bool)
            rule_events = selected.loc[mask].copy()

            event_map, benchmark_label, benchmark_fallback = _v49g_compute_event_returns(
                df=df,
                cfg=cfg,
                events=rule_events,
                horizons=(3, 5, 10, 20),
            )

            if not event_map.empty:
                event_map["rule_name"] = str(rule.get("rule_name"))
                event_map["rule_direction"] = str(rule.get("direction"))
                event_map["rule_threshold"] = str(rule.get("threshold"))
                event_tables.append(event_map)

            sample = int(len(event_map)) if isinstance(event_map, pd.DataFrame) else 0
            total_rows = max(int(len(selected)), 1)
            coverage = sample / total_rows

            def avg(col: str) -> float:
                if event_map is None or event_map.empty or col not in event_map.columns:
                    return np.nan
                s = pd.to_numeric(event_map[col], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
                return float(s.mean()) if not s.empty else np.nan

            def med(col: str) -> float:
                if event_map is None or event_map.empty or col not in event_map.columns:
                    return np.nan
                s = pd.to_numeric(event_map[col], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
                return float(s.median()) if not s.empty else np.nan

            def hit(col: str) -> float:
                if event_map is None or event_map.empty or col not in event_map.columns:
                    return np.nan
                s = pd.to_numeric(event_map[col], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
                return float((s > 0).mean()) if not s.empty else np.nan

            avg3 = avg("active_return_3b")
            avg5 = avg("active_return_5b")
            avg10 = avg("active_return_10b")
            avg20 = avg("active_return_20b")
            med10 = med("active_return_10b")
            med20 = med("active_return_20b")
            hit10 = hit("active_return_10b")
            hit20 = hit("active_return_20b")

            score = 0.0
            if sample > 0:
                score = 45.0
                score += min(sample, 20) * 1.0
                if pd.notna(avg10):
                    score += np.clip(avg10 * 350.0, -20.0, 25.0)
                if pd.notna(avg20):
                    score += np.clip(avg20 * 250.0, -20.0, 20.0)
                if pd.notna(med10) and med10 >= 0:
                    score += 8.0
                if pd.notna(med20) and med20 >= 0:
                    score += 8.0
                if pd.notna(hit10):
                    score += np.clip((hit10 - 0.50) * 35.0, -15.0, 20.0)
                if pd.notna(hit20):
                    score += np.clip((hit20 - 0.50) * 25.0, -10.0, 15.0)
                if bool(benchmark_fallback):
                    score -= 5.0

            score = max(0.0, min(100.0, float(score)))

            if sample < 4:
                decision = "LOW_SAMPLE_REVIEW"
            elif score >= 75 and pd.notna(avg10) and avg10 > 0 and pd.notna(hit10) and hit10 >= 0.50:
                decision = "SOURCE_ONLY_POSITIVE_REVIEW"
            elif score >= 55:
                decision = "SOURCE_ONLY_WATCH_REVIEW"
            else:
                decision = "SOURCE_ONLY_REJECT_REVIEW"

            rule_rows.append(
                {
                    "rule_name": str(rule.get("rule_name")),
                    "rule_direction": str(rule.get("direction")),
                    "threshold": rule.get("threshold"),
                    "sample": sample,
                    "coverage_on_source_rows": coverage,
                    "avg_active_3b": avg3,
                    "avg_active_5b": avg5,
                    "avg_active_10b": avg10,
                    "avg_active_20b": avg20,
                    "median_active_10b": med10,
                    "median_active_20b": med20,
                    "hit_10b": hit10,
                    "hit_20b": hit20,
                    "v49g_review_score": score,
                    "decision": decision,
                    "read": str(rule.get("read")),
                }
            )

        rule_leaderboard = pd.DataFrame(rule_rows)
        if not rule_leaderboard.empty:
            rule_leaderboard = rule_leaderboard.sort_values(
                ["v49g_review_score", "sample", "avg_active_10b"],
                ascending=[False, False, False],
            ).reset_index(drop=True)

        event_map_all = pd.concat(event_tables, ignore_index=True) if event_tables else pd.DataFrame()

        top = rule_leaderboard.iloc[0] if not rule_leaderboard.empty else pd.Series(dtype=object)
        top_rule = str(top.get("rule_name", "N/A")) if not top.empty else "N/A"
        top_score = _safe_float(top.get("v49g_review_score"), 0.0) if not top.empty else 0.0
        top_decision = str(top.get("decision", "NO_RULE")) if not top.empty else "NO_RULE"
        top_sample = int(_safe_float(top.get("sample"), 0)) if not top.empty else 0
        top_avg10 = _safe_float(top.get("avg_active_10b"), np.nan) if not top.empty else np.nan
        top_hit10 = _safe_float(top.get("hit_10b"), np.nan) if not top.empty else np.nan

        gates = pd.DataFrame(
            [
                ["Price frame", "PASS" if df is not None and not df.empty else "FAIL", len(df) if df is not None else 0, "Prix nécessaires pour forward returns."],
                ["Source identity", "PASS" if identity_ok else "FAIL", f"{source_family}:{source_feature}", "Identité héritée de V4.9F.1."],
                ["Audited feature data", "PASS" if data_ok else "FAIL", len(features) if isinstance(features, pd.DataFrame) else 0, "Features externes nettoyées/auditées."],
                ["Selected feature rows", "PASS" if not selected.empty else "FAIL", len(selected), "Lignes disponibles pour la feature candidate exacte."],
                ["Rule generated", "PASS" if len(rules) > 0 else "FAIL", len(rules), "Règles source-only causales générées."],
                ["Event sample", "PASS" if top_sample >= 8 else ("REVIEW" if top_sample >= 4 else "FAIL"), top_sample, "Nombre d'évènements exécutables t+1."],
                ["Mean active 10B", "PASS" if pd.notna(top_avg10) and top_avg10 > 0 else "REVIEW", _format_pct(top_avg10) if pd.notna(top_avg10) else "N/A", "Forward active return moyen 10B."],
                ["Hit 10B", "PASS" if pd.notna(top_hit10) and top_hit10 >= 0.50 else "REVIEW", _format_pct(top_hit10) if pd.notna(top_hit10) else "N/A", "Hit-rate actif 10B."],
                ["No OOS / no promotion", "ENFORCED", "read-only", "V4.9G n'autorise aucune promotion moteur."],
            ],
            columns=["Gate", "Status", "Value", "Read"],
        )

        hard_gate_names = {
            "Price frame",
            "Source identity",
            "Audited feature data",
            "Selected feature rows",
            "Rule generated",
        }

        hard_fail_count = int(
            (
                gates["Status"].astype(str).eq("FAIL")
                & gates["Gate"].astype(str).isin(hard_gate_names)
            ).sum()
        )

        soft_sample_fail = bool(
            (
                gates["Status"].astype(str).eq("FAIL")
                & gates["Gate"].astype(str).eq("Event sample")
                ).any()
        )

        review_count = int((gates["Status"].astype(str) == "REVIEW").sum())

        if hard_fail_count > 0:
            level = "Source-only runner blocked"
            decision = "RETURN_TO_V49F1_OR_DATA"
            read = (
                "V4.9G ne peut pas exécuter le runner review-only : "
                "price frame, identité source, données auditées, lignes sélectionnées ou règles manquantes."
            )

        elif soft_sample_fail or top_decision == "LOW_SAMPLE_REVIEW":
            level = "Source-only low-sample review"
            decision = "EXPAND_SOURCE_SAMPLE_BEFORE_V49H"
            read = (
                "V4.9G a exécuté le runner source-only, mais l'échantillon est trop faible "
                "pour préparer V4.9H. Ajouter davantage d'évènements source réels ou élargir la fenêtre."
            )

        elif top_decision == "SOURCE_ONLY_POSITIVE_REVIEW":
            level = "Source-only positive review"
            decision = "PREPARE_V49H_SOURCE_STRATEGY_BLUEPRINT"
            read = (
                "V4.9G trouve une règle source-only positive en review. "
                "Prochaine étape : blueprint stratégie, toujours sans OOS/promotion."
            )

        elif top_decision == "SOURCE_ONLY_WATCH_REVIEW":
            level = "Source-only watch review"
            decision = "REFINE_SOURCE_ONLY_RULE_BEFORE_V49H"
            read = (
                "V4.9G trouve une lecture exploitable mais encore fragile : "
                "affiner seuil/sample avant blueprint supérieur."
            )

        else:
            level = "Source-only rejected review"
            decision = "RETURN_TO_V49E_OR_EXPAND_DATA"
            read = "V4.9G ne confirme pas la source candidate en runner review-only."

        source_identity = pd.DataFrame(
            [
                ["ticker", str(ticker or "N/A"), "Ticker audité."],
                ["source_family", source_family, "Famille héritée de V4.9F.1."],
                ["source_feature", source_feature, "Feature exacte héritée de V4.9F.1."],
                ["selected_rows", str(len(selected)), "Lignes source exactes disponibles."],
                ["top_rule", top_rule, "Meilleure règle source-only testée."],
                ["benchmark", benchmark_label, "Benchmark actif pour active returns."],
                ["benchmark_fallback", str(bool(benchmark_fallback)), "Si True, lecture relative moins fiable."],
            ],
            columns=["Field", "Value", "Read"],
        )

        summary = pd.DataFrame(
            [
                ["V4.9G level", level, "Lecture synthétique du source-only review runner."],
                ["V4.9G score", f"{_format_num(top_score, 0)}/100", "Score de review source-only, pas score live."],
                ["Decision", decision, "Décision research V4.9G."],
                ["Read", read, "Interprétation opérationnelle."],
                ["Ticker", str(ticker or "N/A"), "Ticker audité."],
                ["Source family", source_family, "Famille source testée."],
                ["Source feature", source_feature, "Feature source testée."],
                ["Top rule", top_rule, "Règle source-only la mieux classée."],
                ["Top sample", str(top_sample), "Nombre d'évènements exécutables t+1."],
                ["Top avg active 10B", _format_pct(top_avg10) if pd.notna(top_avg10) else "N/A", "Active return moyen 10B."],
                ["Top hit 10B", _format_pct(top_hit10) if pd.notna(top_hit10) else "N/A", "Hit-rate actif 10B."],
                ["No engine impact", "PASS", "Aucun signal moteur/trade/equity/verdict modifié."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        next_actions = pd.DataFrame(
            [
                ["P0", "Do not OOS", "V4.9G is source-only review", "OOS interdit avant un vrai blueprint source strategy V4.9H."],
                ["P0", "Do not promote", "No engine signal", "Aucune modification du moteur courant."],
                ["P0", "Keep t+1 discipline", "available_at -> next trading bar -> execution t+1", "Pas de same-close lookahead."],
                ["P1", "Review best rule", top_rule, "Analyser event map et stabilité horizon 10B/20B."],
                ["P1", "Prepare V4.9H only if positive", decision, "Blueprint stratégie seulement si source-only positive review."],
                ["P2", "Expand sample if fragile", f"sample={top_sample}", "Ajouter davantage d'évènements réels si sample insuffisant."],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        cards = [
            {"label": "V4.9G runner", "value": level, "delta": f"{_format_num(top_score, 0)}/100"},
            {"label": "Top source", "value": source_feature, "delta": source_family},
            {"label": "Top rule", "value": top_rule, "delta": "source-only"},
            {"label": "Events", "value": str(top_sample), "delta": "t+1"},
            {"label": "Avg active 10B", "value": _format_pct(top_avg10) if pd.notna(top_avg10) else "N/A", "delta": "review"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": top_score,
            "decision": decision,
            "read": read,
            "top_rule": top_rule,
            "top_family": source_family,
            "top_feature": source_feature,
            "top_sample": top_sample,
            "cards": cards,
            "summary": summary,
            "source_identity": source_identity,
            "data_audit": data_audit,
            "gates": gates,
            "rule_leaderboard": rule_leaderboard,
            "event_map": event_map_all,
            "selected_events": selected,
            "next_actions": next_actions,
        }

    except Exception as exc:
        out = empty.copy()
        out["enabled"] = False
        out["level"] = "V4.9G error"
        out["decision"] = "V49G_ERROR_SAFE_SKIP"
        out["read"] = f"Erreur V4.9G capturée sans interrompre le backtest : {exc}"
        out["summary"] = pd.DataFrame(
            [["V4.9G error", str(exc), "Erreur capturée, aucun impact moteur."]],
            columns=["Metric", "Value", "Read"],
        )
        return out


def _v49g_display_percent_table(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame()
    out = df.copy()
    pct_cols = [c for c in out.columns if any(tok in str(c).lower() for tok in ["active_", "hit", "coverage", "return_"])]
    for col in pct_cols:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_pct(x) if pd.notna(_safe_float(x, np.nan)) else "N/A")
    for col in ["v49g_review_score", "score"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_num(x, 0) if pd.notna(_safe_float(x, np.nan)) else "N/A")
    return out


def _render_source_only_review_runner_v49g(
    df: pd.DataFrame | None = None,
    cfg: Any = None,
    external_features: Any = None,
    v49f1_pack: Any = None,
    v49f_pack: Any = None,
    v49a_pack: Any = None,
    v49b_pack: Any = None,
    v49b2_pack: Any = None,
    v49b3_pack: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    """Streamlit renderer for V4.9G. Read-only source-only review runner."""
    pack = _source_only_review_runner_v49g_pack(
        df=df,
        cfg=cfg,
        external_features=external_features,
        v49f1_pack=v49f1_pack,
        v49f_pack=v49f_pack,
        v49a_pack=v49a_pack,
        v49b_pack=v49b_pack,
        v49b2_pack=v49b2_pack,
        v49b3_pack=v49b3_pack,
        ticker=ticker,
    )

    st.subheader("Source-Only Review Runner V4.9G")
    st.caption(
        "Micro-runner lecture seule après V4.9F.1 : transforme la source externe candidate en règles source-only causales t+1, "
        "mesure les forward active returns 3B/5B/10B/20B et bloque OOS/promotion. "
        "Aucun signal moteur, aucun trade, aucune equity curve, aucun sizing, aucun exit et aucun verdict ne sont modifiés."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", "Unavailable"))
    read = str(pack.get("read", ""))

    if "blocked" in level.lower() or "error" in level.lower() or "rejected" in level.lower():
        st.error(f"Lecture V4.9G : {read}")
    elif "watch" in level.lower() or "fragile" in level.lower():
        st.warning(f"Lecture V4.9G : {read}")
    elif "positive" in level.lower():
        st.success(f"Lecture V4.9G : {read}")
    else:
        st.info(f"Lecture V4.9G : {read}")

    with st.expander("V4.9G source-only runner summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.9G indisponible.")

    with st.expander("V4.9G source identity", expanded=True):
        identity = pack.get("source_identity", pd.DataFrame())
        if isinstance(identity, pd.DataFrame) and not identity.empty:
            st.dataframe(identity, use_container_width=True, hide_index=True)
        else:
            st.info("Identité source V4.9G indisponible.")

    with st.expander("V4.9G runner gates", expanded=True):
        gates = pack.get("gates", pd.DataFrame())
        if isinstance(gates, pd.DataFrame) and not gates.empty:
            st.dataframe(gates, use_container_width=True, hide_index=True)
        else:
            st.info("Gates V4.9G indisponibles.")

    with st.expander("V4.9G source-only rule leaderboard", expanded=True):
        rules = pack.get("rule_leaderboard", pd.DataFrame())
        if isinstance(rules, pd.DataFrame) and not rules.empty:
            st.dataframe(_v49g_display_percent_table(rules), use_container_width=True, hide_index=True)
        else:
            st.info("Aucune règle source-only V4.9G affichable.")

    with st.expander("V4.9G event-level forward active return map", expanded=False):
        event_map = pack.get("event_map", pd.DataFrame())
        if isinstance(event_map, pd.DataFrame) and not event_map.empty:
            st.dataframe(_v49g_display_percent_table(event_map), use_container_width=True, hide_index=True)
        else:
            st.info("Event map V4.9G indisponible.")

    with st.expander("V4.9G selected source rows", expanded=False):
        selected = pack.get("selected_events", pd.DataFrame())
        if isinstance(selected, pd.DataFrame) and not selected.empty:
            st.dataframe(selected, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune ligne source sélectionnée.")

    with st.expander("V4.9G data source audit", expanded=False):
        audit = pack.get("data_audit", pd.DataFrame())
        if isinstance(audit, pd.DataFrame) and not audit.empty:
            st.dataframe(audit, use_container_width=True, hide_index=True)
        else:
            st.info("Audit source data V4.9G indisponible.")

    with st.expander("V4.9G next controlled actions", expanded=True):
        actions = pack.get("next_actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.9G indisponibles.")

    d1, d2, d3 = st.columns(3)
    rules = pack.get("rule_leaderboard", pd.DataFrame())
    event_map = pack.get("event_map", pd.DataFrame())
    selected = pack.get("selected_events", pd.DataFrame())

    if isinstance(rules, pd.DataFrame) and not rules.empty:
        d1.download_button(
            "Télécharger V4.9G rule leaderboard CSV",
            data=rules.to_csv(index=False).encode("utf-8"),
            file_name="v49g_source_only_rule_leaderboard.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g_rule_leaderboard_download",
        )

    if isinstance(event_map, pd.DataFrame) and not event_map.empty:
        d2.download_button(
            "Télécharger V4.9G event map CSV",
            data=event_map.to_csv(index=False).encode("utf-8"),
            file_name="v49g_source_only_event_map.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g_event_map_download",
        )

    if isinstance(selected, pd.DataFrame) and not selected.empty:
        d3.download_button(
            "Télécharger V4.9G selected rows CSV",
            data=selected.to_csv(index=False).encode("utf-8"),
            file_name="v49g_selected_source_rows.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g_selected_rows_download",
        )

    return pack

# ============================================================
# END SOURCE-ONLY REVIEW RUNNER V4.9G
# ============================================================



# ============================================================
# SOURCE SAMPLE EXPANSION / EVENT SUFFICIENCY GATE V4.9G.1
# ============================================================

def _source_sample_expansion_gate_v49g1_pack(
    v49g_pack: Any = None,
    external_features: Any = None,
    v49f1_pack: Any = None,
    ticker: str = "",
    min_events: int = 8,
    preferred_events: int = 15,
) -> dict[str, Any]:
    """
    V4.9G.1 — Source Sample Expansion / Event Sufficiency Gate.

    Lecture seule :
    - part de V4.9G ;
    - mesure si la source candidate a assez d'évènements pour préparer V4.9H ;
    - construit un backlog de lignes externes à ajouter ;
    - ne lance aucun OOS ;
    - ne modifie aucun signal moteur, trade, sizing, exit, equity curve ou verdict.
    """
    def _row(gate: str, required: Any, current: Any, status: str, read: str) -> dict[str, Any]:
        return {
            "Gate": str(gate),
            "Required": str(required),
            "Current": str(current),
            "Status": str(status),
            "Read": str(read),
        }

    def _norm(x: Any) -> str:
        return str(x or "").strip().lower().replace(" ", "_").replace("-", "_")

    def _get_first_number(row: pd.Series, names: list[str], default: float = np.nan) -> float:
        try:
            for name in names:
                if name in row.index:
                    val = _safe_float(row.get(name), np.nan)
                    if pd.notna(val):
                        return val
            return default
        except Exception:
            return default

    empty = {
        "enabled": False,
        "level": "Unavailable",
        "score": 0.0,
        "decision": "V49G1_UNAVAILABLE",
        "read": "V4.9G.1 indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "gates": pd.DataFrame(),
        "expansion_plan": pd.DataFrame(),
        "selected_source_rows": pd.DataFrame(),
        "template_rows": pd.DataFrame(),
        "next_actions": pd.DataFrame(),
    }

    try:
        pack = v49g_pack if isinstance(v49g_pack, dict) else {}

        if cfg is not None and not str(ticker or "").strip():
            ticker = str(getattr(cfg, "asset_ticker", "") or "").upper().strip()

    except Exception:
        pass

    try:
        pack = v49g_pack if isinstance(v49g_pack, dict) else {}

        top_family = str(pack.get("top_family", "") or "").strip()
        top_feature = str(pack.get("top_feature", "") or "").strip()
        top_rule = str(pack.get("top_rule", "") or "").strip()
        v49g_level = str(pack.get("level", "N/A") or "N/A")
        v49g_decision = str(pack.get("decision", "N/A") or "N/A")

        rule_lb = pack.get("rule_leaderboard", pd.DataFrame())
        event_map = pack.get("event_map", pd.DataFrame())
        selected = pack.get("selected_events", pd.DataFrame())

        if isinstance(rule_lb, pd.DataFrame) and not rule_lb.empty:
            top_row = rule_lb.iloc[0]

            if not top_family:
                top_family = str(top_row.get("feature_family", top_row.get("family", "")) or "").strip()
            if not top_feature:
                top_feature = str(top_row.get("feature_name", top_row.get("feature", "")) or "").strip()
            if not top_rule:
                top_rule = str(top_row.get("rule_name", top_row.get("rule", "")) or "").strip()

            current_events = int(
                _get_first_number(
                    top_row,
                    ["sample", "events", "event_count", "top_sample", "rows"],
                    default=0,
                )
            )
            avg_active_10b = _get_first_number(
                top_row,
                ["avg_active_10b", "active_return_10b", "avg active 10B"],
                default=np.nan,
            )
            hit_10b = _get_first_number(
                top_row,
                ["hit_10b", "hit_rate_10b", "hit active 10B"],
                default=np.nan,
            )
        else:
            current_events = int(pack.get("top_sample", 0) or 0)
            avg_active_10b = np.nan
            hit_10b = np.nan

        if current_events <= 0 and isinstance(event_map, pd.DataFrame) and not event_map.empty:
            if top_rule and "rule_name" in event_map.columns:
                current_events = int((event_map["rule_name"].astype(str) == top_rule).sum())
            else:
                current_events = int(len(event_map))

        if isinstance(selected, pd.DataFrame) and not selected.empty:
            selected_rows = selected.copy()
        else:
            selected_rows = pd.DataFrame()

        unique_dates = 0
        first_event = "N/A"
        last_event = "N/A"

        date_candidates = []
        for source_df in [selected_rows, event_map if isinstance(event_map, pd.DataFrame) else pd.DataFrame()]:
            if isinstance(source_df, pd.DataFrame) and not source_df.empty:
                for col in ["decision_date", "available_at", "date", "event_date"]:
                    if col in source_df.columns:
                        d = pd.to_datetime(source_df[col], errors="coerce").dropna()
                        if not d.empty:
                            date_candidates.append(d)

        if date_candidates:
            all_dates = pd.concat(date_candidates, ignore_index=True).dropna()
            if not all_dates.empty:
                unique_dates = int(all_dates.dt.normalize().nunique())
                first_event = _format_dt(all_dates.min())
                last_event = _format_dt(all_dates.max())

        source_count = 0
        if isinstance(selected_rows, pd.DataFrame) and not selected_rows.empty and "source" in selected_rows.columns:
            source_count = int(selected_rows["source"].astype(str).replace("", np.nan).dropna().nunique())
        elif isinstance(event_map, pd.DataFrame) and not event_map.empty and "source" in event_map.columns:
            source_count = int(event_map["source"].astype(str).replace("", np.nan).dropna().nunique())

        has_identity = bool(top_family and top_feature and top_family.upper() not in {"N/A", "NA", "NONE"} and top_feature.upper() not in {"N/A", "NA", "NONE"})
        has_runner = bool(pack.get("enabled", False)) or current_events > 0
        missing_min = max(int(min_events) - int(current_events), 0)
        missing_pref = max(int(preferred_events) - int(current_events), 0)

        gate_rows = [
            _row(
                "V4.9G runner executed",
                "runner review available",
                v49g_level,
                "PASS" if has_runner else "BLOCK",
                "V4.9G doit avoir produit une lecture source-only exploitable.",
            ),
            _row(
                "Source identity",
                "family + feature",
                f"{top_family or 'N/A'} / {top_feature or 'N/A'}",
                "PASS" if has_identity else "BLOCK",
                "La source candidate doit être explicitement identifiée.",
            ),
            _row(
                "Minimum source events",
                f">= {min_events}",
                current_events,
                "PASS" if current_events >= min_events else "NOT YET",
                "Minimum pratique avant de préparer V4.9H.",
            ),
            _row(
                "Preferred source events",
                f">= {preferred_events}",
                current_events,
                "PASS" if current_events >= preferred_events else "REVIEW",
                "Niveau préférable avant blueprint stratégie.",
            ),
            _row(
                "Unique event dates",
                ">= 4",
                unique_dates,
                "PASS" if unique_dates >= 4 else "NOT YET",
                "Évite qu'une source semble bonne sur 1 ou 2 dates seulement.",
            ),
            _row(
                "Source diversity",
                ">= 2 providers/sources",
                source_count,
                "PASS" if source_count >= 2 else "REVIEW",
                "Évite une validation basée sur une seule provenance.",
            ),
            _row(
                "OOS / promotion",
                "forbidden",
                "blocked",
                "ENFORCED",
                "V4.9G.1 ne peut pas autoriser OOS, live, paper ou promotion.",
            ),
        ]

        gates = pd.DataFrame(gate_rows)

        hard_blocks = int((gates["Status"].astype(str) == "BLOCK").sum())
        not_yet = int((gates["Status"].astype(str) == "NOT YET").sum())
        reviews = int((gates["Status"].astype(str) == "REVIEW").sum())

        score = 100.0
        score -= hard_blocks * 50.0
        score -= missing_min * 6.0
        score -= max(0, 4 - unique_dates) * 8.0
        score -= max(0, 2 - source_count) * 6.0
        score -= reviews * 3.0
        score = max(0.0, min(100.0, score))

        if hard_blocks > 0:
            level = "Source sample blocked"
            decision = "RETURN_TO_V49G_OR_V49F1"
            read = "V4.9G.1 bloque : identité source ou runner V4.9G indisponible."
        elif current_events < min_events:
            level = "Source sample insufficient"
            decision = "EXPAND_SOURCE_EVENTS_BEFORE_V49H"
            read = (
                "V4.9G.1 confirme que la source existe, mais l'échantillon est trop faible "
                "pour préparer V4.9H. Ajouter des évènements source réels point-in-time."
            )
        elif unique_dates < 4:
            level = "Source date concentration review"
            decision = "ADD_EVENT_DATE_DIVERSITY_BEFORE_V49H"
            read = (
                "Le nombre de lignes peut être suffisant, mais les dates sont trop concentrées. "
                "Ajouter des évènements répartis dans le temps."
            )
        elif source_count < 2:
            level = "Source provenance review"
            decision = "ADD_SOURCE_DIVERSITY_BEFORE_V49H"
            read = (
                "Le sample minimal est atteint, mais la provenance reste fragile. "
                "Ajouter au moins une deuxième source/provider."
            )
        else:
            level = "Source sample ready for blueprint"
            decision = "PREPARE_V49H_SOURCE_STRATEGY_BLUEPRINT"
            read = (
                "V4.9G.1 valide le sample minimal pour préparer V4.9H en lecture seule. "
                "Toujours aucun OOS/promotion."
            )

        expansion_plan = pd.DataFrame(
            [
                {
                    "Priority": "P0",
                    "Object": "Add source events",
                    "Current": current_events,
                    "Minimum": min_events,
                    "Missing": missing_min,
                    "Target": preferred_events,
                    "Read": f"Ajouter au moins {missing_min} évènements réels pour {top_family}/{top_feature}.",
                },
                {
                    "Priority": "P0",
                    "Object": "Spread event dates",
                    "Current": unique_dates,
                    "Minimum": 4,
                    "Missing": max(0, 4 - unique_dates),
                    "Target": "multiple quarters/regimes",
                    "Read": "Éviter que le signal soit porté par une seule date ou un seul cluster.",
                },
                {
                    "Priority": "P1",
                    "Object": "Add source diversity",
                    "Current": source_count,
                    "Minimum": 2,
                    "Missing": max(0, 2 - source_count),
                    "Target": "provider + manual point-in-time log",
                    "Read": "La source doit rester auditable et reproductible.",
                },
                {
                    "Priority": "P1",
                    "Object": "Keep causal timestamps",
                    "Current": "available_at required",
                    "Minimum": "no missing available_at",
                    "Missing": "block if missing",
                    "Target": "first tradable timestamp",
                    "Read": "Chaque ligne doit rester point-in-time.",
                },
                {
                    "Priority": "P0",
                    "Object": "No outcome labels",
                    "Current": "forbidden",
                    "Minimum": "no future_return / pnl / target_hit",
                    "Missing": "N/A",
                    "Target": "clean source-only dataset",
                    "Read": "Ne jamais ajouter de colonnes de résultat futur.",
                },
            ]
        )

        template_rows = []
        template_n = min(max(missing_min, 3), 10)

        base_dt = pd.Timestamp.today().normalize()
        if date_candidates:
            try:
                last_dt = pd.concat(date_candidates, ignore_index=True).dropna().max()
                if pd.notna(last_dt):
                    base_dt = pd.Timestamp(last_dt).normalize() + pd.Timedelta(days=14)
            except Exception:
                pass

        for i in range(template_n):
            d = base_dt + pd.Timedelta(days=21 * i)
            template_rows.append(
                {
                    "date": d.strftime("%Y-%m-%d"),
                    "available_at": f"{d.strftime('%Y-%m-%d')} 21:30:00",
                    "ticker": str(ticker or "").upper().strip() or "TICKER",
                    "feature_family": top_family or "earnings",
                    "feature_name": top_feature or "revenue_surprise_pct",
                    "value": "REPLACE_WITH_REAL_VALUE",
                    "source": "replace_with_real_provider",
                    "confidence": 0.75,
                    "notes": "real point-in-time event to expand V4.9G.1 sample",
                }
            )

        template = pd.DataFrame(template_rows)

        next_actions = pd.DataFrame(
            [
                ["P0", "Do not run V4.9H yet", f"Events={current_events}/{min_events}", "Blueprint stratégie interdit tant que le sample source reste insuffisant."],
                ["P0", "Expand selected source", f"{top_family}/{top_feature}", "Ajouter des lignes réelles point-in-time sur la source candidate."],
                ["P0", "Re-upload through V4.9A", "adapter remains source of truth", "Toute table enrichie doit repasser par V4.9A puis V4.9B/V4.9B.3."],
                ["P1", "Re-run V4.9G", "same source-only runner", "Vérifier si le score/règle tient avec plus d'évènements."],
                ["P1", "Prepare V4.9H only after gates", decision, "V4.9H seulement si V4.9G.1 passe sans blocage sample/provenance."],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        summary = pd.DataFrame(
            [
                ["V4.9G.1 level", level, "Lecture synthétique du gate sample source."],
                ["V4.9G.1 score", f"{_format_num(score, 0)}/100", "Score de suffisance sample, pas score alpha."],
                ["Decision", decision, "Décision research V4.9G.1."],
                ["Read", read, "Interprétation opérationnelle."],
                ["Ticker", str(ticker or "N/A").upper(), "Ticker audité."],
                ["Top family", top_family or "N/A", "Famille source candidate."],
                ["Top feature", top_feature or "N/A", "Feature source candidate."],
                ["Top rule", top_rule or "N/A", "Règle source-only issue de V4.9G."],
                ["Current events", str(current_events), "Nombre d'évènements source-only utilisables."],
                ["Minimum events", str(min_events), "Minimum avant V4.9H."],
                ["Preferred events", str(preferred_events), "Niveau préférable."],
                ["Missing to minimum", str(missing_min), "Évènements à ajouter avant V4.9H."],
                ["Unique dates", str(unique_dates), "Nombre de dates distinctes."],
                ["Source count", str(source_count), "Nombre de sources/providers distincts."],
                ["First event", first_event, "Premier timestamp disponible."],
                ["Last event", last_event, "Dernier timestamp disponible."],
                ["Avg active 10B from V4.9G", _format_pct(avg_active_10b), "Lecture héritée, non utilisée comme validation finale."],
                ["Hit 10B from V4.9G", _format_pct(hit_10b), "Lecture héritée, fragile si sample faible."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        cards = [
            {"label": "V4.9G.1 gate", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Events current/min", "value": f"{current_events}/{min_events}", "delta": f"missing {missing_min}"},
            {"label": "Preferred", "value": str(preferred_events), "delta": f"missing {missing_pref}"},
            {"label": "Unique dates", "value": str(unique_dates), "delta": "event spread"},
            {"label": "Sources", "value": str(source_count), "delta": "providers"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "gates": gates,
            "expansion_plan": expansion_plan,
            "selected_source_rows": selected_rows,
            "template_rows": template,
            "next_actions": next_actions,
            "top_family": top_family,
            "top_feature": top_feature,
            "top_rule": top_rule,
            "current_events": current_events,
            "missing_min": missing_min,
            "source_count": source_count,
            "unique_dates": unique_dates,
        }

    except Exception as exc:
        out = empty.copy()
        out["enabled"] = False
        out["level"] = "V4.9G.1 error"
        out["decision"] = "V49G1_ERROR_SAFE_SKIP"
        out["read"] = f"Erreur V4.9G.1 capturée sans interrompre le backtest : {exc}"
        out["summary"] = pd.DataFrame(
            [["V4.9G.1 error", str(exc), "Erreur capturée, aucun impact moteur."]],
            columns=["Metric", "Value", "Read"],
        )
        return out


def _render_source_sample_expansion_gate_v49g1(
    v49g_pack: Any = None,
    external_features: Any = None,
    v49f1_pack: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    """Streamlit renderer for V4.9G.1. Read-only event sufficiency gate."""
    pack = _source_sample_expansion_gate_v49g1_pack(
        v49g_pack=v49g_pack,
        external_features=external_features,
        v49f1_pack=v49f1_pack,
        ticker=ticker,
    )

    st.subheader("Source Sample Expansion / Event Sufficiency Gate V4.9G.1")
    st.caption(
        "Gate lecture seule après V4.9G : contrôle si la source externe candidate a assez d'évènements "
        "pour préparer V4.9H. Aucun OOS, aucun signal moteur, aucun trade, aucune equity curve, aucun sizing, "
        "aucun exit et aucun verdict ne sont modifiés."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", "Unavailable"))
    read = str(pack.get("read", ""))

    if "blocked" in level.lower() or "error" in level.lower():
        st.error(f"Lecture V4.9G.1 : {read}")
    elif "insufficient" in level.lower() or "review" in level.lower() or "concentration" in level.lower():
        st.warning(f"Lecture V4.9G.1 : {read}")
    elif "ready" in level.lower():
        st.success(f"Lecture V4.9G.1 : {read}")
    else:
        st.info(f"Lecture V4.9G.1 : {read}")

    with st.expander("V4.9G.1 sample sufficiency summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.9G.1 indisponible.")

    with st.expander("V4.9G.1 event sufficiency gates", expanded=True):
        gates = pack.get("gates", pd.DataFrame())
        if isinstance(gates, pd.DataFrame) and not gates.empty:
            st.dataframe(gates, use_container_width=True, hide_index=True)
        else:
            st.info("Gates V4.9G.1 indisponibles.")

    with st.expander("V4.9G.1 source expansion plan", expanded=True):
        expansion = pack.get("expansion_plan", pd.DataFrame())
        if isinstance(expansion, pd.DataFrame) and not expansion.empty:
            st.dataframe(expansion, use_container_width=True, hide_index=True)
        else:
            st.info("Plan d'expansion V4.9G.1 indisponible.")

    with st.expander("V4.9G.1 selected source rows", expanded=False):
        selected = pack.get("selected_source_rows", pd.DataFrame())
        if isinstance(selected, pd.DataFrame) and not selected.empty:
            st.dataframe(selected, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune ligne source sélectionnée pour V4.9G.1.")

    with st.expander("V4.9G.1 CSV rows to add template", expanded=False):
        template = pack.get("template_rows", pd.DataFrame())
        if isinstance(template, pd.DataFrame) and not template.empty:
            st.dataframe(template, use_container_width=True, hide_index=True)
        else:
            st.info("Template V4.9G.1 indisponible.")

    with st.expander("V4.9G.1 next controlled actions", expanded=True):
        actions = pack.get("next_actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.9G.1 indisponibles.")

    d1, d2, d3 = st.columns(3)

    expansion = pack.get("expansion_plan", pd.DataFrame())
    selected = pack.get("selected_source_rows", pd.DataFrame())
    template = pack.get("template_rows", pd.DataFrame())

    if isinstance(expansion, pd.DataFrame) and not expansion.empty:
        d1.download_button(
            "Télécharger V4.9G.1 expansion plan CSV",
            data=expansion.to_csv(index=False).encode("utf-8"),
            file_name="v49g1_source_sample_expansion_plan.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g1_expansion_plan_download",
        )

    if isinstance(selected, pd.DataFrame) and not selected.empty:
        d2.download_button(
            "Télécharger V4.9G.1 selected source rows CSV",
            data=selected.to_csv(index=False).encode("utf-8"),
            file_name="v49g1_selected_source_rows.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g1_selected_rows_download",
        )

    if isinstance(template, pd.DataFrame) and not template.empty:
        d3.download_button(
            "Télécharger V4.9G.1 rows-to-add template CSV",
            data=template.to_csv(index=False).encode("utf-8"),
            file_name="v49g1_rows_to_add_template.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g1_rows_to_add_template_download",
        )

    return pack

# ============================================================
# END SOURCE SAMPLE EXPANSION / EVENT SUFFICIENCY GATE V4.9G.1
# ============================================================


# ============================================================
# SOURCE EVENT EXPANSION BUILDER / REAL SAMPLE WORKBENCH V4.9G.2
# ============================================================

def _source_event_expansion_builder_v49g2_pack(
    v49g1_pack: Any = None,
    v49g_pack: Any = None,
    external_features: Any = None,
    ticker: str = "",
    min_events: int = 8,
    preferred_events: int = 15,
    provider_target: int = 2,
) -> dict[str, Any]:
    """
    V4.9G.2 — Source Event Expansion Builder / Real Sample Augmentation Workbench.

    Lecture seule :
    - part de V4.9G.1 ;
    - transforme le blocage sample en plan de collecte actionnable ;
    - génère des templates CSV ciblés sur la source candidate ;
    - ne lance aucun alpha scan, aucun OOS, aucun signal moteur, aucun trade,
      aucune equity curve, aucun sizing, aucun exit et aucun verdict.
    """
    def _norm(x: Any) -> str:
        try:
            return str(x or "").strip().lower().replace(" ", "_").replace("-", "_")
        except Exception:
            return ""

    def _row(item: str, value: Any, read: str) -> dict[str, Any]:
        return {"Item": str(item), "Value": str(value), "Read": str(read)}

    def _gate(gate: str, required: Any, current: Any, status: str, read: str) -> dict[str, Any]:
        return {
            "Gate": str(gate),
            "Required": str(required),
            "Current": str(current),
            "Status": str(status),
            "Read": str(read),
        }

    def _safe_int(x: Any, default: int = 0) -> int:
        try:
            if x is None or pd.isna(x):
                return default
            return int(float(x))
        except Exception:
            return default

    def _clean_source_frame(df: Any) -> pd.DataFrame:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return pd.DataFrame()

        out = df.copy()
        out.columns = [str(c).strip() for c in out.columns]
        lower = {str(c).lower().strip(): c for c in out.columns}

        rename_map = {}
        aliases = {
            "date": ["date", "event_date", "decision_date", "trading_date"],
            "available_at": ["available_at", "asof", "as_of", "published_at", "release_time", "timestamp"],
            "ticker": ["ticker", "symbol", "asset", "asset_ticker"],
            "feature_family": ["feature_family", "family", "source_family"],
            "feature_name": ["feature_name", "feature", "source_feature", "name"],
            "value": ["value", "feature_value", "signal_value", "raw_value"],
            "source": ["source", "provider", "source_tag", "data_source"],
            "confidence": ["confidence", "reliability", "quality_score"],
            "notes": ["notes", "note", "comment", "headline"],
        }

        for target, names in aliases.items():
            if target in out.columns:
                continue
            for name in names:
                if name in lower:
                    rename_map[lower[name]] = target
                    break

        if rename_map:
            out = out.rename(columns=rename_map)

        for col in ["date", "available_at", "ticker", "feature_family", "feature_name", "value", "source", "confidence", "notes"]:
            if col not in out.columns:
                out[col] = np.nan

        out["date"] = pd.to_datetime(out["date"], errors="coerce")
        out["available_at"] = pd.to_datetime(out["available_at"], errors="coerce")
        out["feature_family"] = out["feature_family"].astype(str).str.strip()
        out["feature_name"] = out["feature_name"].astype(str).str.strip()
        out["ticker"] = out["ticker"].astype(str).str.upper().str.strip()
        out["source"] = out["source"].astype(str).str.strip()
        out["notes"] = out["notes"].astype(str).str.strip()
        out["confidence"] = pd.to_numeric(out["confidence"], errors="coerce")

        return out[["date", "available_at", "ticker", "feature_family", "feature_name", "value", "source", "confidence", "notes"]].copy()

    def _date_text(x: Any) -> str:
        try:
            if x is None or pd.isna(x):
                return "N/A"
            return pd.Timestamp(x).strftime("%Y-%m-%d")
        except Exception:
            return str(x)

    def _datetime_text(x: Any) -> str:
        try:
            if x is None or pd.isna(x):
                return "N/A"
            return pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S")
        except Exception:
            return str(x)

    empty = {
        "enabled": False,
        "level": "Unavailable",
        "score": 0.0,
        "decision": "V49G2_UNAVAILABLE",
        "read": "V4.9G.2 indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "gates": pd.DataFrame(),
        "event_gap_plan": pd.DataFrame(),
        "minimum_template": pd.DataFrame(),
        "preferred_template": pd.DataFrame(),
        "provider_plan": pd.DataFrame(),
        "row_quality_protocol": pd.DataFrame(),
        "current_source_rows": pd.DataFrame(),
        "next_actions": pd.DataFrame(),
    }

    try:
        g1 = v49g1_pack if isinstance(v49g1_pack, dict) else {}
        g = v49g_pack if isinstance(v49g_pack, dict) else {}

        top_family = str(g1.get("top_family", g.get("top_family", "")) or "").strip()
        top_feature = str(g1.get("top_feature", g.get("top_feature", "")) or "").strip()
        top_rule = str(g1.get("top_rule", g.get("top_rule", "")) or "").strip()

        current_events = _safe_int(g1.get("current_events", g.get("top_sample", 0)), 0)
        unique_dates_g1 = _safe_int(g1.get("unique_dates", 0), 0)
        source_count_g1 = _safe_int(g1.get("source_count", 0), 0)

        selected = g1.get("selected_source_rows", pd.DataFrame())
        if not isinstance(selected, pd.DataFrame) or selected.empty:
            selected = g.get("selected_events", pd.DataFrame())

        current_rows = _clean_source_frame(selected)

        if current_rows.empty:
            ext = _clean_source_frame(external_features)
            if not ext.empty and top_family and top_feature:
                fam_norm = ext["feature_family"].map(_norm)
                feat_norm = ext["feature_name"].map(_norm)
                current_rows = ext[(fam_norm == _norm(top_family)) & (feat_norm == _norm(top_feature))].copy()
            else:
                current_rows = ext.copy() if isinstance(ext, pd.DataFrame) else pd.DataFrame()

        if not current_rows.empty:
            if not str(ticker or "").strip():
                tickers = current_rows["ticker"].replace("", np.nan).dropna().astype(str).unique().tolist()
                ticker = tickers[0] if tickers else ""

            if not top_family:
                vals = current_rows["feature_family"].replace("", np.nan).dropna().astype(str).unique().tolist()
                top_family = vals[0] if vals else ""

            if not top_feature:
                vals = current_rows["feature_name"].replace("", np.nan).dropna().astype(str).unique().tolist()
                top_feature = vals[0] if vals else ""

        date_series = pd.Series(dtype="datetime64[ns]")
        if not current_rows.empty:
            d1 = pd.to_datetime(current_rows["available_at"], errors="coerce")
            d2 = pd.to_datetime(current_rows["date"], errors="coerce")
            date_series = d1.fillna(d2).dropna()

        if current_events <= 0 and not current_rows.empty:
            current_events = int(len(current_rows))

        unique_dates = unique_dates_g1
        if unique_dates <= 0 and not date_series.empty:
            unique_dates = int(date_series.dt.normalize().nunique())

        source_count = source_count_g1
        if source_count <= 0 and not current_rows.empty and "source" in current_rows.columns:
            source_count = int(current_rows["source"].astype(str).replace("", np.nan).dropna().nunique())

        source_tags = []
        if not current_rows.empty and "source" in current_rows.columns:
            source_tags = sorted([str(x) for x in current_rows["source"].replace("", np.nan).dropna().unique().tolist()])

        first_event = _date_text(date_series.min()) if not date_series.empty else "N/A"
        last_event = _date_text(date_series.max()) if not date_series.empty else "N/A"

        missing_min = max(int(min_events) - int(current_events), 0)
        missing_pref = max(int(preferred_events) - int(current_events), 0)
        missing_providers = max(int(provider_target) - int(source_count), 0)

        has_identity = bool(top_family and top_feature and _norm(top_family) not in {"n/a", "na", "none"} and _norm(top_feature) not in {"n/a", "na", "none"})
        has_existing_rows = bool(current_events > 0 or not current_rows.empty)

        provider_candidates = [
            "provider_earnings_export",
            "company_release_point_in_time_log",
            "manual_point_in_time_log",
            "analyst_revision_provider",
            "options_eod_snapshot_provider",
            "news_catalyst_feed",
        ]

        if _norm(top_family) == "earnings":
            provider_candidates = ["provider_earnings_export", "company_release_point_in_time_log", "manual_point_in_time_log"]
        elif _norm(top_family) in {"revision", "analyst_revisions"}:
            provider_candidates = ["analyst_revision_provider", "provider_estimate_history_export", "manual_point_in_time_log"]
        elif _norm(top_family) == "guidance":
            provider_candidates = ["company_release_point_in_time_log", "transcript_derived_table", "provider_guidance_export"]
        elif _norm(top_family) == "options":
            provider_candidates = ["options_eod_snapshot_provider", "broker_option_export", "iv_provider_export"]
        elif _norm(top_family) == "news":
            provider_candidates = ["news_catalyst_feed", "curated_manual_catalyst_log", "company_release_point_in_time_log"]

        provider_plan = pd.DataFrame(
            [
                {
                    "Priority": "P0" if i < provider_target else "P1",
                    "Provider / source tag": src,
                    "Status": "CURRENT" if src in source_tags else "TO_ADD",
                    "Use case": "source diversity / reproducibility",
                    "Rule": "Chaque ligne doit garder source + available_at.",
                }
                for i, src in enumerate(provider_candidates)
            ]
        )

        if not source_tags:
            current_source_text = "none"
        else:
            current_source_text = ", ".join(source_tags[:6])

        gates = pd.DataFrame(
            [
                _gate("Source identity", "family + feature", f"{top_family or 'N/A'} / {top_feature or 'N/A'}", "PASS" if has_identity else "BLOCK", "La source à enrichir doit être unique et stable."),
                _gate("Current source rows", "> 0", current_events, "PASS" if has_existing_rows else "NOT YET", "Il faut au moins des lignes réelles ou candidates."),
                _gate("Minimum events", f">= {min_events}", current_events, "PASS" if current_events >= min_events else "NOT YET", "Minimum avant V4.9H."),
                _gate("Preferred events", f">= {preferred_events}", current_events, "PASS" if current_events >= preferred_events else "REVIEW", "Niveau préférable avant blueprint."),
                _gate("Unique dates", ">= 4", unique_dates, "PASS" if unique_dates >= 4 else "REVIEW", "Répartition temporelle minimale."),
                _gate("Source diversity", f">= {provider_target}", source_count, "PASS" if source_count >= provider_target else "REVIEW", "Évite une validation portée par un seul provider."),
                _gate("Outcome labels", "forbidden", "future_return/pnl/target_hit blocked", "ENFORCED", "Aucune colonne de résultat futur ne doit servir de feature."),
                _gate("V4.9H permission", "all minimum gates", "blocked" if missing_min > 0 or not has_identity else "review", "BLOCK" if missing_min > 0 or not has_identity else "REVIEW", "V4.9H reste interdit tant que le dataset enrichi n'est pas re-audité."),
            ]
        )

        score = 0.0
        score += 20.0 if has_identity else 0.0
        score += min(current_events / max(int(min_events), 1), 1.0) * 35.0
        score += min(current_events / max(int(preferred_events), 1), 1.0) * 15.0
        score += min(unique_dates / 4.0, 1.0) * 15.0
        score += min(source_count / max(int(provider_target), 1), 1.0) * 15.0
        score = max(0.0, min(100.0, score))

        if not has_identity:
            level = "Expansion builder blocked"
            decision = "RETURN_TO_V49G1_SOURCE_IDENTITY"
            read = "V4.9G.2 bloque : source_family/source_feature indisponibles. Revenir à V4.9G/V4.9G.1."
        elif current_events < min_events:
            level = "Expansion workbench ready"
            decision = "EXPAND_SOURCE_EVENTS_AND_REUPLOAD_V49A"
            read = "V4.9G.2 transforme le blocage sample en template de collecte. Ajouter les évènements réels puis repasser par V4.9A/V4.9B."
        elif source_count < provider_target:
            level = "Sample met / provider review"
            decision = "ADD_PROVIDER_DIVERSITY_THEN_REAUDIT"
            read = "Le minimum d'évènements est atteint, mais la provenance reste fragile. Ajouter au moins une source/provider distincte."
        else:
            level = "Expansion gates met"
            decision = "READY_FOR_V49H_AFTER_REAUDIT"
            read = "Le dataset semble assez dense pour préparer V4.9H, uniquement après re-audit V4.9A→V4.9G.1 propre."

        if not date_series.empty and pd.notna(date_series.max()):
            start_date = pd.Timestamp(date_series.max()).normalize() + pd.Timedelta(days=21)
        else:
            start_date = pd.Timestamp.today().normalize()

        min_rows = max(missing_min, 0)
        pref_rows = max(missing_pref, min_rows)

        def _make_template(n: int, mode: str) -> pd.DataFrame:
            rows = []
            for i in range(int(n)):
                dt = start_date + pd.Timedelta(days=21 * i)
                provider = provider_candidates[i % max(len(provider_candidates), 1)]
                if source_tags and i % 2 == 0:
                    provider = source_tags[0]
                rows.append(
                    {
                        "date": dt.strftime("%Y-%m-%d"),
                        "available_at": f"{dt.strftime('%Y-%m-%d')} 21:30:00",
                        "ticker": str(ticker or "TICKER").upper().strip(),
                        "feature_family": top_family,
                        "feature_name": top_feature,
                        "value": "REPLACE_WITH_REAL_POINT_IN_TIME_VALUE",
                        "source": provider,
                        "confidence": 0.75,
                        "notes": f"{mode} expansion row {i + 1} — replace with real source event",
                    }
                )
            return pd.DataFrame(rows)

        minimum_template = _make_template(max(min_rows, 1 if missing_min > 0 else 0), "minimum")
        preferred_template = _make_template(max(pref_rows, 1 if missing_pref > 0 else 0), "preferred")

        event_gap_rows = []
        for i in range(max(missing_min, 0)):
            dt = start_date + pd.Timedelta(days=21 * i)
            event_gap_rows.append(
                {
                    "Priority": "P0",
                    "Missing event #": i + 1,
                    "Target date placeholder": dt.strftime("%Y-%m-%d"),
                    "Source family": top_family,
                    "Source feature": top_feature,
                    "Required value": "real numeric/string value, point-in-time",
                    "Required available_at": "first tradable timestamp",
                    "Required source": provider_candidates[i % max(len(provider_candidates), 1)],
                    "Read": "Remplacer la ligne placeholder par un vrai évènement observable à cette date ou proche.",
                }
            )

        event_gap_plan = pd.DataFrame(event_gap_rows)
        if event_gap_plan.empty:
            event_gap_plan = pd.DataFrame(
                [
                    {
                        "Priority": "P1",
                        "Missing event #": 0,
                        "Target date placeholder": "N/A",
                        "Source family": top_family,
                        "Source feature": top_feature,
                        "Required value": "sample minimum already met",
                        "Required available_at": "keep mandatory",
                        "Required source": "add provider diversity if needed",
                        "Read": "Aucun évènement minimum manquant ; contrôler surtout la provenance et le re-audit.",
                    }
                ]
            )

        row_quality_protocol = pd.DataFrame(
            [
                ["available_at mandatory", "Every row", "BLOCK if missing", "Timestamp de première disponibilité tradable."],
                ["source mandatory", "Every row", "BLOCK/REVIEW if missing", "Provider ou log manuel stable et auditable."],
                ["no template source", "source", "BLOCK if replace_with/template/manual_example", "Les lignes exemple ne valident pas un edge."],
                ["no outcome labels", "columns", "BLOCK", "Interdit : future_return, pnl, target_hit, realized_alpha, next_close."],
                ["stable feature taxonomy", "feature_name", "REVIEW", "Ne pas changer revenue_surprise_pct en variantes libres non comparables."],
                ["event_date vs available_at", "date/available_at", "REVIEW", "Si publication after-close, utiliser available_at au prochain timestamp tradable."],
                ["re-upload through V4.9A", "workflow", "MANDATORY", "L'adapter reste la source de vérité du pipeline."],
            ],
            columns=["Rule", "Object", "Status", "Read"],
        )

        next_actions = pd.DataFrame(
            [
                ["P0", "Do not run V4.9H yet", f"Events={current_events}/{min_events}", "V4.9H interdit tant que V4.9G.1 ne repasse pas proprement."],
                ["P0", "Fill minimum source template", f"missing_min={missing_min}", "Ajouter les vraies lignes de source candidate, pas des lignes template."],
                ["P0", "Keep point-in-time discipline", "leakage risk", "Chaque ligne doit avoir available_at, source, confidence et aucune colonne outcome."],
                ["P0", "Re-upload through V4.9A", "adapter is source of truth", "Toute table enrichie doit repasser par V4.9A avant V4.9B/G."],
                ["P1", "Re-run V4.9B/V4.9B.3", "quality/provenance", "Vérifier missingness, sources, contamination template et timestamps."],
                ["P1", "Re-run V4.9G/V4.9G.1", "source-only sample", "V4.9H seulement si sample/provenance passent après enrichissement."],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        summary = pd.DataFrame(
            [
                _row("V4.9G.2 level", level, "Lecture synthétique du workbench d'expansion sample."),
                _row("V4.9G.2 score", f"{_format_num(score, 0)}/100", "Score de préparation dataset, pas score alpha."),
                _row("Decision", decision, "Décision research V4.9G.2."),
                _row("Read", read, "Interprétation opérationnelle."),
                _row("Ticker", str(ticker or "N/A").upper(), "Ticker cible."),
                _row("Source family", top_family or "N/A", "Famille source candidate."),
                _row("Source feature", top_feature or "N/A", "Feature source candidate."),
                _row("Top rule", top_rule or "N/A", "Règle source-only héritée de V4.9G."),
                _row("Current events", current_events, "Évènements utilisables actuellement."),
                _row("Missing to minimum", missing_min, "Nombre de vrais évènements à ajouter avant V4.9H."),
                _row("Missing to preferred", missing_pref, "Nombre à ajouter pour un sample plus confortable."),
                _row("Unique dates", unique_dates, "Répartition temporelle."),
                _row("Source count", source_count, "Nombre de providers/sources distincts."),
                _row("Current source tags", current_source_text, "Sources observées."),
                _row("First event", first_event, "Premier évènement disponible."),
                _row("Last event", last_event, "Dernier évènement disponible."),
            ]
        )

        cards = [
            {"label": "V4.9G.2 builder", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Events", "value": f"{current_events}/{min_events}", "delta": f"missing {missing_min}"},
            {"label": "Preferred", "value": str(preferred_events), "delta": f"missing {missing_pref}"},
            {"label": "Feature", "value": top_feature or "N/A", "delta": top_family or "source"},
            {"label": "Sources", "value": str(source_count), "delta": f"missing {missing_providers}"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "gates": gates,
            "event_gap_plan": event_gap_plan,
            "minimum_template": minimum_template,
            "preferred_template": preferred_template,
            "provider_plan": provider_plan,
            "row_quality_protocol": row_quality_protocol,
            "current_source_rows": current_rows,
            "next_actions": next_actions,
            "top_family": top_family,
            "top_feature": top_feature,
            "top_rule": top_rule,
            "current_events": current_events,
            "missing_min": missing_min,
            "missing_pref": missing_pref,
            "source_count": source_count,
            "unique_dates": unique_dates,
        }

    except Exception as exc:
        out = empty.copy()
        out["enabled"] = False
        out["level"] = "V4.9G.2 error"
        out["decision"] = "V49G2_ERROR_SAFE_SKIP"
        out["read"] = f"Erreur V4.9G.2 capturée sans interrompre le backtest : {exc}"
        out["summary"] = pd.DataFrame(
            [["V4.9G.2 error", str(exc), "Erreur capturée, aucun impact moteur."]],
            columns=["Metric", "Value", "Read"],
        )
        return out


def _render_source_event_expansion_builder_v49g2(
    v49g1_pack: Any = None,
    v49g_pack: Any = None,
    external_features: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    """Streamlit renderer for V4.9G.2. Read-only source event expansion workbench."""
    pack = _source_event_expansion_builder_v49g2_pack(
        v49g1_pack=v49g1_pack,
        v49g_pack=v49g_pack,
        external_features=external_features,
        ticker=ticker,
    )

    st.subheader("Source Event Expansion Builder / Real Sample Augmentation Workbench V4.9G.2")
    st.caption(
        "Workbench lecture seule après V4.9G.1 : transforme le sample insuffisant en plan de collecte, "
        "templates CSV ciblés, protocole provider et gates avant V4.9H. Aucun alpha scan, aucun OOS, "
        "aucun signal moteur, aucun trade, aucune equity curve, aucun sizing, aucun exit et aucun verdict ne sont modifiés."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", "Unavailable"))
    read = str(pack.get("read", ""))

    if "blocked" in level.lower() or "error" in level.lower():
        st.error(f"Lecture V4.9G.2 : {read}")
    elif "ready" in level.lower() or "met" in level.lower():
        st.success(f"Lecture V4.9G.2 : {read}")
    else:
        st.warning(f"Lecture V4.9G.2 : {read}")

    with st.expander("V4.9G.2 expansion builder summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.9G.2 indisponible.")

    with st.expander("V4.9G.2 gates before V4.9H", expanded=True):
        gates = pack.get("gates", pd.DataFrame())
        if isinstance(gates, pd.DataFrame) and not gates.empty:
            st.dataframe(gates, use_container_width=True, hide_index=True)
        else:
            st.info("Gates V4.9G.2 indisponibles.")

    with st.expander("V4.9G.2 event gap plan", expanded=True):
        event_gap_plan = pack.get("event_gap_plan", pd.DataFrame())
        if isinstance(event_gap_plan, pd.DataFrame) and not event_gap_plan.empty:
            st.dataframe(event_gap_plan, use_container_width=True, hide_index=True)
        else:
            st.info("Plan de gaps évènements V4.9G.2 indisponible.")

    with st.expander("V4.9G.2 minimum CSV template to fill", expanded=True):
        minimum_template = pack.get("minimum_template", pd.DataFrame())
        if isinstance(minimum_template, pd.DataFrame) and not minimum_template.empty:
            st.dataframe(minimum_template, use_container_width=True, hide_index=True)
        else:
            st.info("Template minimum V4.9G.2 indisponible ou non nécessaire.")

    with st.expander("V4.9G.2 preferred CSV template", expanded=False):
        preferred_template = pack.get("preferred_template", pd.DataFrame())
        if isinstance(preferred_template, pd.DataFrame) and not preferred_template.empty:
            st.dataframe(preferred_template, use_container_width=True, hide_index=True)
        else:
            st.info("Template preferred V4.9G.2 indisponible ou non nécessaire.")

    with st.expander("V4.9G.2 provider / source plan", expanded=True):
        provider_plan = pack.get("provider_plan", pd.DataFrame())
        if isinstance(provider_plan, pd.DataFrame) and not provider_plan.empty:
            st.dataframe(provider_plan, use_container_width=True, hide_index=True)
        else:
            st.info("Plan provider V4.9G.2 indisponible.")

    with st.expander("V4.9G.2 row quality / anti-leakage protocol", expanded=False):
        protocol = pack.get("row_quality_protocol", pd.DataFrame())
        if isinstance(protocol, pd.DataFrame) and not protocol.empty:
            st.dataframe(protocol, use_container_width=True, hide_index=True)
        else:
            st.info("Protocole qualité V4.9G.2 indisponible.")

    with st.expander("V4.9G.2 current selected source rows", expanded=False):
        current_rows = pack.get("current_source_rows", pd.DataFrame())
        if isinstance(current_rows, pd.DataFrame) and not current_rows.empty:
            st.dataframe(current_rows, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune ligne source courante affichable pour V4.9G.2.")

    with st.expander("V4.9G.2 next controlled actions", expanded=True):
        actions = pack.get("next_actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.9G.2 indisponibles.")

    d1, d2, d3, d4 = st.columns(4)

    minimum_template = pack.get("minimum_template", pd.DataFrame())
    preferred_template = pack.get("preferred_template", pd.DataFrame())
    provider_plan = pack.get("provider_plan", pd.DataFrame())
    current_rows = pack.get("current_source_rows", pd.DataFrame())

    if isinstance(minimum_template, pd.DataFrame) and not minimum_template.empty:
        d1.download_button(
            "Télécharger V4.9G.2 minimum template CSV",
            data=minimum_template.to_csv(index=False).encode("utf-8"),
            file_name="v49g2_minimum_source_events_template.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g2_minimum_template_download",
        )

    if isinstance(preferred_template, pd.DataFrame) and not preferred_template.empty:
        d2.download_button(
            "Télécharger V4.9G.2 preferred template CSV",
            data=preferred_template.to_csv(index=False).encode("utf-8"),
            file_name="v49g2_preferred_source_events_template.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g2_preferred_template_download",
        )

    if isinstance(provider_plan, pd.DataFrame) and not provider_plan.empty:
        d3.download_button(
            "Télécharger V4.9G.2 provider plan CSV",
            data=provider_plan.to_csv(index=False).encode("utf-8"),
            file_name="v49g2_provider_plan.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g2_provider_plan_download",
        )

    if isinstance(current_rows, pd.DataFrame) and not current_rows.empty:
        d4.download_button(
            "Télécharger V4.9G.2 current source rows CSV",
            data=current_rows.to_csv(index=False).encode("utf-8"),
            file_name="v49g2_current_source_rows.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g2_current_source_rows_download",
        )

    return pack

# ============================================================
# END SOURCE EVENT EXPANSION BUILDER / REAL SAMPLE WORKBENCH V4.9G.2
# ============================================================


# ============================================================
# SOURCE EVENT COLLECTION CONTROL / REUPLOAD VALIDATOR V4.9G.3
# ============================================================

def _source_event_reupload_validator_v49g3_pack(
    v49g2_pack: Any = None,
    v49g1_pack: Any = None,
    v49g_pack: Any = None,
    external_features: Any = None,
    ticker: str = "",
    min_rule_events: int = 8,
    preferred_rule_events: int = 15,
    min_source_rows: int = 8,
    provider_target: int = 2,
) -> dict[str, Any]:
    """
    V4.9G.3 — Source Event Collection Control / Reupload Validator.

    Lecture seule :
    - contrôle le CSV enrichi après V4.9G.2 ;
    - vérifie que la source candidate exacte a assez d'évènements réels ;
    - détecte placeholders/template rows, colonnes outcome/leakage, available_at manquant,
      concentration date/source et faiblesse provider ;
    - ne lance aucun alpha scan, aucun OOS, aucun signal moteur, aucun trade,
      aucune equity curve, aucun sizing, aucun exit et aucun verdict.
    """
    def _norm(x: Any) -> str:
        try:
            return str(x or "").strip().lower().replace(" ", "_").replace("-", "_")
        except Exception:
            return ""

    def _row(metric: str, value: Any, read: str) -> dict[str, Any]:
        return {"Metric": str(metric), "Value": str(value), "Read": str(read)}

    def _gate(check: str, status: str, severity: str, value: Any, read: str) -> dict[str, Any]:
        return {
            "Check": str(check),
            "Status": str(status),
            "Severity": str(severity),
            "Value": str(value),
            "Read": str(read),
        }

    def _safe_int(x: Any, default: int = 0) -> int:
        try:
            if x is None or pd.isna(x):
                return default
            return int(float(x))
        except Exception:
            return default

    def _first_non_empty(*values: Any) -> str:
        for value in values:
            txt = str(value or "").strip()
            if txt and txt.upper() not in {"N/A", "NA", "NONE", "NAN", "NULL"}:
                return txt
        return ""

    def _clean_features(df: Any) -> pd.DataFrame:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return pd.DataFrame()

        out = df.copy()
        out.columns = [str(c).strip() for c in out.columns]
        lower = {str(c).lower().strip(): c for c in out.columns}

        aliases = {
            "date": ["date", "event_date", "decision_date", "trading_date"],
            "available_at": ["available_at", "asof", "as_of", "published_at", "release_time", "timestamp"],
            "ticker": ["ticker", "symbol", "asset", "asset_ticker"],
            "feature_family": ["feature_family", "family", "source_family"],
            "feature_name": ["feature_name", "feature", "source_feature", "name"],
            "value": ["value", "feature_value", "signal_value", "raw_value"],
            "source": ["source", "provider", "source_tag", "data_source"],
            "confidence": ["confidence", "reliability", "quality_score"],
            "notes": ["notes", "note", "comment", "headline"],
        }

        rename_map = {}
        for target, names in aliases.items():
            if target in out.columns:
                continue
            for name in names:
                if name in lower:
                    rename_map[lower[name]] = target
                    break

        if rename_map:
            out = out.rename(columns=rename_map)

        for col in ["date", "available_at", "ticker", "feature_family", "feature_name", "value", "source", "confidence", "notes"]:
            if col not in out.columns:
                out[col] = np.nan

        out["date"] = pd.to_datetime(out["date"], errors="coerce")
        out["available_at"] = pd.to_datetime(out["available_at"], errors="coerce")
        out["ticker"] = out["ticker"].astype(str).str.strip().str.upper()
        out["feature_family"] = out["feature_family"].astype(str).str.strip()
        out["feature_name"] = out["feature_name"].astype(str).str.strip()
        out["source"] = out["source"].astype(str).str.strip()
        out["notes"] = out["notes"].astype(str).str.strip()
        out["confidence"] = pd.to_numeric(out["confidence"], errors="coerce")

        return out.replace([np.inf, -np.inf], np.nan)

    def _target_rule_events(selected: pd.DataFrame, top_rule: str, v49g_pack_obj: dict[str, Any]) -> pd.DataFrame:
        if selected is None or not isinstance(selected, pd.DataFrame) or selected.empty:
            return pd.DataFrame()

        rule_txt = _norm(top_rule)

        event_map = v49g_pack_obj.get("event_map", pd.DataFrame()) if isinstance(v49g_pack_obj, dict) else pd.DataFrame()
        if isinstance(event_map, pd.DataFrame) and not event_map.empty:
            em = event_map.copy()
            if "rule_name" in em.columns and top_rule:
                em = em[em["rule_name"].astype(str).map(_norm) == rule_txt].copy()
            if not em.empty:
                return em

        out = selected.copy()
        values = pd.to_numeric(out.get("value"), errors="coerce")

        if values.notna().sum() <= 0:
            return pd.DataFrame()

        if "top_quartile" in rule_txt or "q75" in rule_txt:
            threshold = float(values.quantile(0.75))
            out = out[values >= threshold].copy()
        elif "bottom_quartile" in rule_txt or "q25" in rule_txt:
            threshold = float(values.quantile(0.25))
            out = out[values <= threshold].copy()
        elif "positive" in rule_txt or "non_negative" in rule_txt:
            out = out[values >= 0].copy()
        elif "negative" in rule_txt:
            out = out[values < 0].copy()
        else:
            threshold = float(values.quantile(0.75))
            out = out[values >= threshold].copy()

        return out

    empty = {
        "enabled": False,
        "level": "Unavailable",
        "score": 0.0,
        "decision": "V49G3_UNAVAILABLE",
        "read": "V4.9G.3 indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "gates": pd.DataFrame(),
        "source_quality": pd.DataFrame(),
        "rule_event_sample": pd.DataFrame(),
        "selected_source_rows": pd.DataFrame(),
        "contaminated_rows": pd.DataFrame(),
        "next_actions": pd.DataFrame(),
    }

    try:
        g2 = v49g2_pack if isinstance(v49g2_pack, dict) else {}
        g1 = v49g1_pack if isinstance(v49g1_pack, dict) else {}
        g = v49g_pack if isinstance(v49g_pack, dict) else {}

        top_family = _first_non_empty(g2.get("top_family"), g1.get("top_family"), g.get("top_family"))
        top_feature = _first_non_empty(g2.get("top_feature"), g1.get("top_feature"), g.get("top_feature"))
        top_rule = _first_non_empty(g2.get("top_rule"), g1.get("top_rule"), g.get("top_rule"), "value_top_quartile")

        clean = _clean_features(external_features)

        target_ticker = str(ticker or "").upper().strip()
        if target_ticker and isinstance(clean, pd.DataFrame) and not clean.empty and "ticker" in clean.columns:
            ticker_filtered = clean[clean["ticker"].astype(str).str.upper().str.strip() == target_ticker].copy()
            if not ticker_filtered.empty:
                clean = ticker_filtered

        identity_ok = bool(top_family and top_feature)
        data_ok = isinstance(clean, pd.DataFrame) and not clean.empty

        if data_ok and identity_ok:
            family_norm = _norm(top_family)
            feature_norm = _norm(top_feature)
            selected = clean[
                (clean["feature_family"].astype(str).map(_norm) == family_norm)
                & (clean["feature_name"].astype(str).map(_norm) == feature_norm)
            ].copy()
        else:
            selected = pd.DataFrame()

        rule_events = _target_rule_events(selected, top_rule, g)

        source_rows = int(len(selected)) if isinstance(selected, pd.DataFrame) else 0
        rule_event_count = int(len(rule_events)) if isinstance(rule_events, pd.DataFrame) else 0

        if rule_event_count <= 0:
            rule_event_count = _safe_int(g.get("top_sample", g1.get("current_events", 0)), 0)

        date_source = rule_events if isinstance(rule_events, pd.DataFrame) and not rule_events.empty else selected
        if isinstance(date_source, pd.DataFrame) and not date_source.empty:
            date_col = "decision_date" if "decision_date" in date_source.columns else "available_at" if "available_at" in date_source.columns else "date"
            date_series = pd.to_datetime(date_source.get(date_col), errors="coerce").dropna()
        else:
            date_col = "date"
            date_series = pd.Series(dtype="datetime64[ns]")

        unique_dates = int(date_series.dt.normalize().nunique()) if not date_series.empty else 0
        first_event = _format_dt(date_series.min()) if not date_series.empty else "N/A"
        last_event = _format_dt(date_series.max()) if not date_series.empty else "N/A"
        max_date_concentration = 0.0
        if not date_series.empty:
            date_counts = date_series.dt.normalize().value_counts()
            max_date_concentration = float(date_counts.max() / max(len(date_series), 1))

        if isinstance(selected, pd.DataFrame) and not selected.empty and "source" in selected.columns:
            source_clean = selected["source"].astype(str).str.strip()
            source_clean = source_clean.replace({"": np.nan, "nan": np.nan, "None": np.nan})
            source_count = int(source_clean.dropna().nunique())
            source_text = ", ".join(sorted(source_clean.dropna().astype(str).unique().tolist())[:8]) or "N/A"
        else:
            source_count = 0
            source_text = "N/A"

        # V4.9G.3 fix — contamination detection must be field-aware.
        # Previous logic was too broad: tokens such as "example" or "sample" in notes could block
        # a structurally clean source even after V4.9B.3 provenance passed.
        # Blocking is now reserved for explicit placeholders/template markers.
        strong_placeholder_tokens = [
            "replace_with", "template_row", "placeholder", "provider_or_manual", "manual_example",
            "dummy", "to_fill", "fill_me", "fake", "test_row", "replace_me",
        ]
        weak_review_tokens = [
            "example ", " sample ", "demo", "synthetic", "illustrative",
        ]

        def _contamination_reason(row: pd.Series) -> str:
            try:
                source_norm = _norm(row.get("source", ""))
                notes_norm = _norm(row.get("notes", ""))
                value_norm = _norm(row.get("value", ""))

                # Hard blocks: explicit source/provider placeholders.
                if source_norm.startswith("replace_with") or source_norm in {
                    "manual_example",
                    "provider_or_manual",
                    "replace_with_provider",
                    "replace_with_earnings_provider",
                    "replace_with_revision_provider",
                    "replace_with_guidance_provider",
                    "replace_with_options_provider",
                    "replace_with_news_provider",
                }:
                    return "placeholder_source"

                # Hard blocks: explicit template markers in notes.
                hard_note_markers = [
                    "replace_with",
                    "replace_with_real",
                    "template_row",
                    "placeholder",
                    "to_fill",
                    "fill_me",
                    "dummy",
                    "fake",
                    "test_row",
                ]
                if any(tok in notes_norm for tok in hard_note_markers):
                    return "placeholder_notes"

                # Hard blocks: non-numeric placeholder value.
                if any(tok in value_norm for tok in ["replace_with", "placeholder", "to_fill", "fill_me"]):
                    return "placeholder_value"

                return ""
            except Exception:
                return ""
        forbidden_columns = []
        forbidden_tokens = [
            "future_return", "forward_return", "next_return", "return_fwd", "return_next",
            "realized_alpha", "realized_return", "target_hit", "hit_target", "pnl",
            "profit", "outcome", "next_close", "future_close", "label_y", "target_y",
        ]

        if isinstance(clean, pd.DataFrame) and not clean.empty:
            for col in clean.columns:
                col_norm = _norm(col)
                if any(tok in col_norm for tok in forbidden_tokens):
                    forbidden_columns.append(str(col))

        if isinstance(selected, pd.DataFrame) and not selected.empty:
            contamination_reasons = selected.apply(_contamination_reason, axis=1)
            contam_mask = contamination_reasons.astype(str).str.len() > 0
            contaminated_rows = selected.loc[contam_mask].copy()
            if not contaminated_rows.empty:
                contaminated_rows.insert(
                    0,
                    "block_reason",
                    contamination_reasons.loc[contam_mask].astype(str).values,
                )
        else:
            contaminated_rows = pd.DataFrame()

        contaminated_count = int(len(contaminated_rows)) if isinstance(contaminated_rows, pd.DataFrame) else 0
        contamination_share = contaminated_count / max(source_rows, 1)

        available_invalid = 0
        event_date_invalid = 0
        future_availability_rows = 0
        value_missing = 0
        value_missing_rate = 1.0
        duplicate_keys = 0
        numeric_share = np.nan
        confidence_mean = np.nan

        if isinstance(selected, pd.DataFrame) and not selected.empty:
            available = pd.to_datetime(selected.get("available_at"), errors="coerce")
            event_dates = pd.to_datetime(selected.get("date"), errors="coerce")
            available_invalid = int(available.isna().sum())
            event_date_invalid = int(event_dates.isna().sum())
            future_availability_rows = int((available.dt.normalize() < event_dates.dt.normalize()).fillna(False).sum())

            value_series = selected.get("value")
            value_missing = int(pd.Series(value_series).isna().sum())
            value_missing_rate = value_missing / max(source_rows, 1)

            numeric_values = pd.to_numeric(value_series, errors="coerce")
            numeric_share = float(numeric_values.notna().mean()) if len(numeric_values) else np.nan

            conf = pd.to_numeric(selected.get("confidence"), errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
            confidence_mean = float(conf.mean()) if not conf.empty else np.nan

            key_cols = [c for c in ["date", "available_at", "ticker", "feature_family", "feature_name", "source"] if c in selected.columns]
            duplicate_keys = int(selected.duplicated(subset=key_cols).sum()) if key_cols else 0

        feature_norm = _norm(top_feature)
        numeric_required = not any(tok in feature_norm for tok in ["tag", "headline", "news", "sentiment", "category", "state"])

        gates = pd.DataFrame(
            [
                _gate("Source identity", "PASS" if identity_ok else "BLOCK", "Critical" if not identity_ok else "None", f"{top_family or 'N/A'} / {top_feature or 'N/A'}", "Famille/feature candidate héritée de V4.9G.2/V4.9G."),
                _gate("External feature table", "PASS" if data_ok else "BLOCK", "Critical" if not data_ok else "None", len(clean) if isinstance(clean, pd.DataFrame) else 0, "Table externe chargée via V4.9A/V4.9B."),
                _gate("Selected source rows", "PASS" if source_rows >= min_source_rows else "NOT YET", "High" if source_rows < min_source_rows else "None", f"{source_rows}/{min_source_rows}", "Lignes disponibles pour la source candidate exacte."),
                _gate("Rule event sample", "PASS" if rule_event_count >= min_rule_events else "NOT YET", "High" if rule_event_count < min_rule_events else "None", f"{rule_event_count}/{min_rule_events}", "Évènements réellement exploitables pour la règle source-only."),
                _gate("Preferred rule events", "PASS" if rule_event_count >= preferred_rule_events else "REVIEW", "Low" if rule_event_count < preferred_rule_events else "None", f"{rule_event_count}/{preferred_rule_events}", "Niveau préférable avant V4.9H."),
                _gate("Unique event dates", "PASS" if unique_dates >= 4 else "NOT YET", "Medium" if unique_dates < 4 else "None", unique_dates, "Évite une validation sur un cluster de dates."),
                _gate("Source diversity", "PASS" if source_count >= provider_target else "REVIEW", "Medium" if source_count < provider_target else "None", f"{source_count}/{provider_target}", "Au moins deux sources/providers préférable avant blueprint."),
                _gate("Template / placeholder rows", "PASS" if contaminated_count == 0 else "BLOCK", "Critical" if contaminated_count > 0 else "None", f"{contaminated_count} rows", "Blocage uniquement sur placeholders explicites : replace_with, template_row, placeholder, manual_example, provider_or_manual."),
                _gate("Forbidden outcome columns", "PASS" if not forbidden_columns else "BLOCK", "Critical" if forbidden_columns else "None", ", ".join(forbidden_columns) if forbidden_columns else "0", "Colonnes future/outcome interdites."),
                _gate("available_at quality", "PASS" if available_invalid == 0 and source_rows > 0 else "BLOCK", "Critical" if available_invalid > 0 or source_rows <= 0 else "None", available_invalid, "Chaque ligne source doit avoir un timestamp de disponibilité."),
                _gate("event date quality", "PASS" if event_date_invalid == 0 and source_rows > 0 else "REVIEW", "Medium" if event_date_invalid > 0 else "None", event_date_invalid, "Date économique/évènement lisible."),
                _gate("available_at before event_date", "PASS" if future_availability_rows == 0 else "REVIEW", "Medium" if future_availability_rows > 0 else "None", future_availability_rows, "available_at avant event_date est suspect pour une surprise publiée."),
                _gate("Value missingness", "PASS" if value_missing_rate <= 0.05 else "BLOCK", "High" if value_missing_rate > 0.05 else "None", _format_pct(value_missing_rate), "La feature source ne doit pas être vide."),
                _gate("Numeric value share", "PASS" if (not numeric_required or (pd.notna(numeric_share) and numeric_share >= 0.80)) else "REVIEW", "Medium" if numeric_required and (pd.isna(numeric_share) or numeric_share < 0.80) else "None", _format_pct(numeric_share) if pd.notna(numeric_share) else "N/A", "Les surprise/revision/guidance doivent être majoritairement numériques."),
                _gate("Duplicate source keys", "PASS" if duplicate_keys == 0 else "REVIEW", "Medium" if duplicate_keys > 0 else "None", duplicate_keys, "Doublons date/available_at/ticker/family/feature/source à inspecter."),
                _gate("Date concentration", "PASS" if max_date_concentration <= 0.40 or rule_event_count < min_rule_events else "REVIEW", "Medium" if max_date_concentration > 0.40 and rule_event_count >= min_rule_events else "None", _format_pct(max_date_concentration), "Concentration maximale sur une même date."),
                _gate("No OOS / no promotion", "ENFORCED", "None", "read-only", "V4.9G.3 ne peut pas autoriser live/OOS/promotion moteur."),
            ]
        )

        block_count = int((gates["Status"].astype(str) == "BLOCK").sum()) if not gates.empty else 0
        not_yet_count = int((gates["Status"].astype(str) == "NOT YET").sum()) if not gates.empty else 0
        review_count = int((gates["Status"].astype(str) == "REVIEW").sum()) if not gates.empty else 0

        score = 100.0
        score -= block_count * 35.0
        score -= max(0, min_rule_events - rule_event_count) * 6.0
        score -= max(0, min_source_rows - source_rows) * 3.0
        score -= max(0, 4 - unique_dates) * 5.0
        score -= max(0, provider_target - source_count) * 8.0
        score -= contamination_share * 60.0
        score -= value_missing_rate * 25.0
        score -= review_count * 4.0
        score = max(0.0, min(100.0, float(score)))

        if block_count > 0:
            level = "Source event reupload blocked"
            decision = "FIX_SOURCE_DATA_BEFORE_V49H"
            read = "V4.9G.3 bloque uniquement si placeholder explicite, leakage, available_at manquant ou source identity/data manquante est détecté."
        elif rule_event_count < min_rule_events or source_rows < min_source_rows:
            level = "Source event sample still insufficient"
            decision = "EXPAND_MORE_AND_REUPLOAD_V49A"
            read = "La source est propre mais l'échantillon reste insuffisant pour V4.9H. Ajouter des évènements réels puis repasser V4.9A/V4.9B/V4.9G."
        elif unique_dates < 4:
            level = "Source event date spread review"
            decision = "ADD_DATE_DIVERSITY_BEFORE_V49H"
            read = "Le nombre d'évènements approche le minimum, mais la distribution temporelle est trop concentrée."
        elif source_count < provider_target:
            level = "Source event provenance review"
            decision = "ADD_PROVIDER_DIVERSITY_BEFORE_V49H"
            read = "Le sample minimal est atteint, mais la provenance reste fragile. Ajouter au moins une deuxième source."
        elif review_count > 0:
            level = "Source event reupload review"
            decision = "REVIEW_SOURCE_EVENTS_BEFORE_V49H"
            read = "Le reupload est exploitable mais certaines alertes doivent être revues avant V4.9H."
        else:
            level = "Source event reupload validated"
            decision = "READY_FOR_V49H_SOURCE_ONLY_REVIEW"
            read = "V4.9G.3 valide le reupload source : sample/provenance/available_at suffisants pour préparer V4.9H en lecture seule."

        source_quality = pd.DataFrame(
            [
                ["Target family", top_family or "N/A", "Famille source auditée."],
                ["Target feature", top_feature or "N/A", "Feature source auditée."],
                ["Top rule", top_rule or "N/A", "Règle source-only à contrôler."],
                ["Selected source rows", source_rows, "Lignes exactes family/feature."],
                ["Rule event count", rule_event_count, "Évènements exploitables par la règle top."],
                ["Unique dates", unique_dates, "Dates distinctes."],
                ["First event", first_event, "Premier évènement."],
                ["Last event", last_event, "Dernier évènement."],
                ["Source count", source_count, "Nombre de sources/providers distincts."],
                ["Source tags", source_text, "Sources observées."],
                ["Template/placeholder rows", contaminated_count, "Lignes contaminées par placeholders explicites uniquement."],
                ["Forbidden columns", ", ".join(forbidden_columns) if forbidden_columns else "None", "Colonnes outcome/leakage."],
                ["available_at invalid", available_invalid, "Timestamps de disponibilité invalides."],
                ["value missing rate", _format_pct(value_missing_rate), "Taux de valeurs manquantes."],
                ["numeric share", _format_pct(numeric_share) if pd.notna(numeric_share) else "N/A", "Part numérique de value."],
                ["avg confidence", _format_num(confidence_mean) if pd.notna(confidence_mean) else "N/A", "Confiance moyenne si fournie."],
                ["duplicate keys", duplicate_keys, "Doublons à inspecter."],
                ["max date concentration", _format_pct(max_date_concentration), "Part max sur une seule date."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        rule_event_sample = pd.DataFrame(
            [
                ["Rule events current/min", f"{rule_event_count}/{min_rule_events}", "Minimum avant V4.9H."],
                ["Rule events preferred", f"{rule_event_count}/{preferred_rule_events}", "Niveau préférable."],
                ["Missing to minimum", max(0, min_rule_events - rule_event_count), "Évènements règle à ajouter."],
                ["Missing to preferred", max(0, preferred_rule_events - rule_event_count), "Évènements règle à ajouter pour confort."],
                ["Source rows current/min", f"{source_rows}/{min_source_rows}", "Lignes brutes source candidate."],
                ["Rule event coverage", _format_pct(rule_event_count / max(source_rows, 1)), "Part des lignes source retenues par la règle."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        next_actions = pd.DataFrame(
            [
                ["P0", "Do not run OOS/live", "V4.9H not built yet", "Aucune promotion tant que V4.9H puis gates OOS/overfit ne passent pas."],
                ["P0", "Use V4.9A as source of truth", "reupload discipline", "Toute correction du CSV doit repasser par V4.9A puis V4.9B/V4.9B.3."],
                ["P0", "Fix blocking source issues", f"blocks={block_count}", "Supprimer placeholders/leakage et compléter available_at si nécessaire."],
                ["P0", "Expand rule event sample", f"events={rule_event_count}/{min_rule_events}", "Ajouter des évènements réels pour la feature candidate si le seuil n'est pas atteint."],
                ["P1", "Add provider diversity", f"sources={source_count}/{provider_target}", "Ajouter un second provider/source tag si possible."],
                ["P1", "Prepare V4.9H only if READY", decision, "V4.9H seulement si V4.9G.3 finit READY_FOR_V49H_SOURCE_ONLY_REVIEW."],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        summary = pd.DataFrame(
            [
                _row("V4.9G.3 level", level, "Lecture synthétique du validator de reupload source."),
                _row("V4.9G.3 score", f"{_format_num(score, 0)}/100", "Score de qualité source, pas score alpha."),
                _row("Decision", decision, "Décision research V4.9G.3."),
                _row("Read", read, "Interprétation opérationnelle."),
                _row("Ticker", str(ticker or "N/A").upper(), "Ticker cible."),
                _row("Target source", f"{top_family or 'N/A'} / {top_feature or 'N/A'}", "Source candidate contrôlée."),
                _row("Top rule", top_rule or "N/A", "Règle source-only contrôlée."),
                _row("Source rows", source_rows, "Lignes source exactes."),
                _row("Rule events", rule_event_count, "Évènements exploitables par la règle."),
                _row("Unique dates", unique_dates, "Distribution temporelle."),
                _row("Sources", source_count, "Providers/sources distincts."),
                _row("Blocks / reviews", f"{block_count} / {review_count}", "Alertes bloquantes et non-bloquantes."),
                _row("Blocking rows exported", contaminated_count, "Si >0, voir le CSV contaminated rows avec block_reason."),
                _row("No engine impact", "PASS", "Aucun signal/trade/equity/verdict modifié."),
            ]
        )

        cards = [
            {"label": "V4.9G.3 validator", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Rule events", "value": f"{rule_event_count}/{min_rule_events}", "delta": f"missing {max(0, min_rule_events - rule_event_count)}"},
            {"label": "Source rows", "value": str(source_rows), "delta": top_feature or "feature"},
            {"label": "Sources", "value": f"{source_count}/{provider_target}", "delta": "providers"},
            {"label": "Blocks", "value": str(block_count), "delta": "must fix"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "gates": gates,
            "source_quality": source_quality,
            "rule_event_sample": rule_event_sample,
            "selected_source_rows": selected,
            "contaminated_rows": contaminated_rows,
            "next_actions": next_actions,
            "top_family": top_family,
            "top_feature": top_feature,
            "top_rule": top_rule,
            "source_rows": source_rows,
            "rule_event_count": rule_event_count,
            "unique_dates": unique_dates,
            "source_count": source_count,
            "block_count": block_count,
            "review_count": review_count,
        }

    except Exception as exc:
        out = empty.copy()
        out["enabled"] = False
        out["level"] = "V4.9G.3 error"
        out["decision"] = "V49G3_ERROR_SAFE_SKIP"
        out["read"] = f"Erreur V4.9G.3 capturée sans interrompre le backtest : {exc}"
        out["summary"] = pd.DataFrame(
            [["V4.9G.3 error", str(exc), "Erreur capturée, aucun impact moteur."]],
            columns=["Metric", "Value", "Read"],
        )
        return out


def _render_source_event_reupload_validator_v49g3(
    v49g2_pack: Any = None,
    v49g1_pack: Any = None,
    v49g_pack: Any = None,
    external_features: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    """Streamlit renderer for V4.9G.3. Read-only source event reupload validator."""
    pack = _source_event_reupload_validator_v49g3_pack(
        v49g2_pack=v49g2_pack,
        v49g1_pack=v49g1_pack,
        v49g_pack=v49g_pack,
        external_features=external_features,
        ticker=ticker,
    )

    st.subheader("Source Event Collection Control / Reupload Validator V4.9G.3")
    st.caption(
        "Validator lecture seule après V4.9G.2 : contrôle le CSV enrichi, le sample source réel, "
        "les providers, available_at, contamination template et colonnes outcome avant tout V4.9H. "
        "Aucun alpha scan, aucun OOS, aucun signal moteur, aucun trade, aucune equity curve, aucun sizing, "
        "aucun exit et aucun verdict ne sont modifiés."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", "Unavailable"))
    read = str(pack.get("read", ""))

    if "blocked" in level.lower() or "error" in level.lower():
        st.error(f"Lecture V4.9G.3 : {read}")
    elif "insufficient" in level.lower() or "review" in level.lower():
        st.warning(f"Lecture V4.9G.3 : {read}")
    elif "validated" in level.lower() or "ready" in level.lower():
        st.success(f"Lecture V4.9G.3 : {read}")
    else:
        st.info(f"Lecture V4.9G.3 : {read}")

    with st.expander("V4.9G.3 reupload validator summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.9G.3 indisponible.")

    with st.expander("V4.9G.3 validation gates", expanded=True):
        gates = pack.get("gates", pd.DataFrame())
        if isinstance(gates, pd.DataFrame) and not gates.empty:
            st.dataframe(gates, use_container_width=True, hide_index=True)
        else:
            st.info("Gates V4.9G.3 indisponibles.")

    with st.expander("V4.9G.3 source quality map", expanded=True):
        quality = pack.get("source_quality", pd.DataFrame())
        if isinstance(quality, pd.DataFrame) and not quality.empty:
            st.dataframe(quality, use_container_width=True, hide_index=True)
        else:
            st.info("Source quality map V4.9G.3 indisponible.")

    with st.expander("V4.9G.3 rule event sample", expanded=True):
        sample = pack.get("rule_event_sample", pd.DataFrame())
        if isinstance(sample, pd.DataFrame) and not sample.empty:
            st.dataframe(sample, use_container_width=True, hide_index=True)
        else:
            st.info("Rule event sample V4.9G.3 indisponible.")

    with st.expander("V4.9G.3 selected source rows", expanded=False):
        selected = pack.get("selected_source_rows", pd.DataFrame())
        if isinstance(selected, pd.DataFrame) and not selected.empty:
            st.dataframe(selected, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune ligne source sélectionnée pour V4.9G.3.")

    with st.expander("V4.9G.3 contaminated / blocking rows", expanded=False):
        contaminated = pack.get("contaminated_rows", pd.DataFrame())
        if isinstance(contaminated, pd.DataFrame) and not contaminated.empty:
            st.dataframe(contaminated, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune ligne contaminée détectée par V4.9G.3.")

    with st.expander("V4.9G.3 next controlled actions", expanded=True):
        actions = pack.get("next_actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.9G.3 indisponibles.")

    d1, d2, d3 = st.columns(3)
    selected = pack.get("selected_source_rows", pd.DataFrame())
    contaminated = pack.get("contaminated_rows", pd.DataFrame())
    gates = pack.get("gates", pd.DataFrame())

    if isinstance(selected, pd.DataFrame) and not selected.empty:
        d1.download_button(
            "Télécharger V4.9G.3 selected source rows CSV",
            data=selected.to_csv(index=False).encode("utf-8"),
            file_name="v49g3_selected_source_rows.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g3_selected_source_rows_download",
        )

    if isinstance(contaminated, pd.DataFrame) and not contaminated.empty:
        d2.download_button(
            "Télécharger V4.9G.3 contaminated rows CSV",
            data=contaminated.to_csv(index=False).encode("utf-8"),
            file_name="v49g3_contaminated_rows.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g3_contaminated_rows_download",
        )

    if isinstance(gates, pd.DataFrame) and not gates.empty:
        d3.download_button(
            "Télécharger V4.9G.3 gates CSV",
            data=gates.to_csv(index=False).encode("utf-8"),
            file_name="v49g3_validation_gates.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g3_gates_download",
        )

    return pack

