# ============================================================
# V4.9H / V4.9I / V4.9J / V4.9K / V5.0 — COMPLETE SECTIONS PATCH
# ============================================================
# Remplace le bloc condensé "Source Validation Suite V4.9H -> V5.0".
# Règle de construction : une lettre = une section complète.
# Pas de H.1/H.2/H.3, pas de bloc résumé H->V5.
# Lecture seule : aucun signal moteur, aucun trade, aucune equity curve,
# aucun sizing, aucun exit, aucun OOS moteur et aucun verdict principal modifiés.


def _v49x_norm(value: Any) -> str:
    try:
        return str(value or "").strip().lower().replace(" ", "_").replace("-", "_")
    except Exception:
        return ""


def _v49x_clean_text(value: Any, default: str = "N/A") -> str:
    try:
        if value is None:
            return default
        try:
            if pd.isna(value):
                return default
        except Exception:
            pass
        txt = str(value).strip()
        return txt if txt else default
    except Exception:
        return default


def _v49x_col(df: pd.DataFrame, candidates: list[str]) -> str | None:
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return None
    lookup = {_v49x_norm(c): c for c in df.columns}
    for c in candidates:
        if _v49x_norm(c) in lookup:
            return lookup[_v49x_norm(c)]
    return None


def _v49x_pct_or_num_display(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame()
    out = df.copy()
    for col in out.columns:
        low = str(col).lower()
        if any(tok in low for tok in ["return", "active", "hit", "rate", "coverage", "missing", "concentration", "share"]):
            out[col] = out[col].map(lambda x: _format_pct(x) if pd.notna(_safe_float(x, np.nan)) else _v49x_clean_text(x))
        elif "score" in low:
            out[col] = out[col].map(lambda x: _format_num(x, 0) if pd.notna(_safe_float(x, np.nan)) else _v49x_clean_text(x))
        elif any(tok in low for tok in ["date", "available", "decision"]):
            out[col] = out[col].map(lambda x: _format_dt(x) if str(x).strip() not in {"", "N/A", "nan", "None"} else "N/A")
    return out


def _v49x_pick_source_identity(
    v49g_pack: Any = None,
    v49g3_pack: Any = None,
    v49f1_pack: Any = None,
    v49f_pack: Any = None,
) -> dict[str, str]:
    """Résout la source candidate en regardant tous les packs amont disponibles."""
    out = {
        "source_family": "N/A",
        "source_feature": "N/A",
        "source_rule": "N/A",
    }

    for pack in [v49g3_pack, v49g_pack, v49f1_pack, v49f_pack]:
        if not isinstance(pack, dict):
            continue

        for target, keys in {
            "source_family": ["top_family", "source_family", "family", "selected_family"],
            "source_feature": ["top_feature", "source_feature", "feature", "feature_name", "selected_feature"],
            "source_rule": ["top_rule", "source_rule", "rule", "selected_rule"],
        }.items():
            for k in keys:
                txt = _v49x_clean_text(pack.get(k, ""), default="")
                if txt and txt.upper() not in {"N/A", "NA", "NONE", "NAN"}:
                    out[target] = txt
                    break

        # Fallback dataframe source_identity / bridge / contract.
        for table_key in ["source_identity", "source_bridge", "runner_contract", "summary"]:
            tab = pack.get(table_key, pd.DataFrame())
            if not isinstance(tab, pd.DataFrame) or tab.empty:
                continue
            low_cols = {_v49x_norm(c): c for c in tab.columns}
            if {"metric", "value"}.issubset(low_cols):
                mcol, vcol = low_cols["metric"], low_cols["value"]
                for _, row in tab.iterrows():
                    metric = _v49x_norm(row.get(mcol, ""))
                    val = _v49x_clean_text(row.get(vcol, ""), default="")
                    if not val:
                        continue
                    if "family" in metric and out["source_family"] == "N/A":
                        out["source_family"] = val
                    elif "feature" in metric and out["source_feature"] == "N/A":
                        out["source_feature"] = val
                    elif "rule" in metric and out["source_rule"] == "N/A":
                        out["source_rule"] = val
            else:
                fcol = _v49x_col(tab, ["source_family", "top_family", "family", "feature_family"])
                ncol = _v49x_col(tab, ["source_feature", "top_feature", "feature_name", "feature"])
                rcol = _v49x_col(tab, ["source_rule", "top_rule", "rule"])
                if len(tab) > 0:
                    first = tab.iloc[0]
                    if fcol and out["source_family"] == "N/A":
                        out["source_family"] = _v49x_clean_text(first.get(fcol, "N/A"))
                    if ncol and out["source_feature"] == "N/A":
                        out["source_feature"] = _v49x_clean_text(first.get(ncol, "N/A"))
                    if rcol and out["source_rule"] == "N/A":
                        out["source_rule"] = _v49x_clean_text(first.get(rcol, "N/A"))

        if out["source_family"] != "N/A" and out["source_feature"] != "N/A":
            break

    return out


def _v49x_normalize_external_features(raw: Any, ticker: str = "") -> pd.DataFrame:
    """Normalise toute table externe en colonnes standard V4.9H+ sans exécuter de code utilisateur."""
    if raw is None or not isinstance(raw, pd.DataFrame) or raw.empty:
        return pd.DataFrame(columns=["date", "available_at", "decision_date", "ticker", "feature_family", "feature_name", "value", "source", "confidence", "notes"])

    df = raw.copy()
    if isinstance(df.columns, pd.MultiIndex):
        df.columns = ["_".join([str(x) for x in c if str(x) != ""]) for c in df.columns]

    date_col = _v49x_col(df, ["date", "event_date", "observation_date", "economic_date"])
    avail_col = _v49x_col(df, ["available_at", "published_at", "release_time", "report_time", "as_of", "asof", "decision_date"])
    dec_col = _v49x_col(df, ["decision_date", "trade_date", "aligned_date", "calendar_date"])
    ticker_col = _v49x_col(df, ["ticker", "symbol", "asset"])
    fam_col = _v49x_col(df, ["feature_family", "source_family", "family", "data_family"])
    feat_col = _v49x_col(df, ["feature_name", "source_feature", "feature", "top_feature", "name"])
    value_col = _v49x_col(df, ["value", "feature_value", "signal_value", "score", "state"])
    source_col = _v49x_col(df, ["source", "provider", "source_tag", "provider_tag"])
    conf_col = _v49x_col(df, ["confidence", "source_confidence", "quality"])
    notes_col = _v49x_col(df, ["notes", "note", "headline", "description", "read"])

    out = pd.DataFrame(index=df.index)
    out["date"] = pd.to_datetime(df[date_col], errors="coerce") if date_col else pd.NaT
    out["available_at"] = pd.to_datetime(df[avail_col], errors="coerce") if avail_col else out["date"]
    out["decision_date"] = pd.to_datetime(df[dec_col], errors="coerce") if dec_col else pd.NaT
    out["ticker"] = df[ticker_col].astype(str).str.upper().str.strip() if ticker_col else str(ticker or "").upper().strip()
    out["feature_family"] = df[fam_col].astype(str).str.strip() if fam_col else "N/A"
    out["feature_name"] = df[feat_col].astype(str).str.strip() if feat_col else "N/A"
    out["value"] = df[value_col] if value_col else np.nan
    out["source"] = df[source_col].astype(str).str.strip() if source_col else "unknown_source"
    out["confidence"] = pd.to_numeric(df[conf_col], errors="coerce") if conf_col else np.nan
    out["notes"] = df[notes_col].astype(str).str.strip() if notes_col else ""

    out["date"] = out["date"].fillna(out["available_at"])
    out["available_at"] = out["available_at"].fillna(out["date"])
    out = out.replace([np.inf, -np.inf], np.nan)
    out = out.dropna(subset=["available_at"])

    if ticker:
        t = str(ticker).upper().strip()
        if t:
            mask = out["ticker"].astype(str).str.upper().str.strip().isin([t, "", "N/A", "NAN", "NONE"])
            out = out.loc[mask].copy()
            out.loc[out["ticker"].astype(str).str.strip().isin(["", "N/A", "nan", "None"]), "ticker"] = t

    out["feature_family_norm"] = out["feature_family"].map(_v49x_norm)
    out["feature_name_norm"] = out["feature_name"].map(_v49x_norm)
    return out.reset_index(drop=True)


def _v49x_candidate_source_rows(
    external_features: Any = None,
    identity: dict[str, str] | None = None,
    ticker: str = "",
    *packs: Any,
) -> pd.DataFrame:
    """Récupère les lignes de la source candidate depuis V4.9G/G.3 puis fallback V4.9A table."""
    identity = identity or {}
    fam = _v49x_norm(identity.get("source_family", ""))
    feat = _v49x_norm(identity.get("source_feature", ""))

    frames = []
    for pack in packs:
        if not isinstance(pack, dict):
            continue
        for key in ["selected_source_rows", "source_rows_df", "rule_event_sample", "selected_rows", "evidence_rows"]:
            tab = pack.get(key, pd.DataFrame())
            if isinstance(tab, pd.DataFrame) and not tab.empty:
                frames.append(_v49x_normalize_external_features(tab, ticker=ticker))

    ext = _v49x_normalize_external_features(external_features, ticker=ticker)
    if not ext.empty:
        frames.append(ext)

    if not frames:
        return pd.DataFrame()

    df = pd.concat(frames, ignore_index=True, sort=False)
    df = df.dropna(subset=["available_at"])

    if feat:
        candidate = df[df["feature_name_norm"] == feat].copy()
        if not candidate.empty:
            df = candidate

    if fam and not df.empty:
        candidate = df[df["feature_family_norm"] == fam].copy()
        if not candidate.empty:
            df = candidate

    # Déduplication stable source event. Ne déduplique pas par value seule.
    key_cols = [c for c in ["ticker", "available_at", "feature_family", "feature_name", "value", "source"] if c in df.columns]
    if key_cols:
        df = df.sort_values("available_at").drop_duplicates(key_cols, keep="last")

    return df.sort_values("available_at").reset_index(drop=True)


def _v49x_build_price_and_benchmark(df: pd.DataFrame | None, cfg: Any = None, ticker: str = "") -> dict[str, Any]:
    if df is None or not isinstance(df, pd.DataFrame) or df.empty or "close" not in df.columns:
        return {"price": pd.DataFrame(), "benchmark_nav": pd.Series(dtype=float), "benchmark_label": "N/A", "benchmark_fallback": True}

    price = df.copy()
    if not _is_datetime_like_index(price.index):
        date_col = _v49x_col(price, ["date", "datetime", "timestamp"])
        if date_col:
            price.index = pd.to_datetime(price[date_col], errors="coerce")
    price.index = pd.to_datetime(price.index, errors="coerce")
    price = price.loc[pd.Series(price.index).notna().values].copy()
    price = price.sort_index()
    price = price.loc[~price.index.duplicated(keep="last")]
    price["close"] = pd.to_numeric(price["close"], errors="coerce")
    price = price.dropna(subset=["close"])

    if price.empty:
        return {"price": pd.DataFrame(), "benchmark_nav": pd.Series(dtype=float), "benchmark_label": "N/A", "benchmark_fallback": True}

    bench_cfg = cfg
    try:
        if cfg is not None and not str(getattr(cfg, "benchmark_ticker", "") or "").strip():
            t = str(ticker or getattr(cfg, "asset_ticker", "") or "").upper().strip()
            auto_symbol = _sector_benchmark_guess(t) if t else "SPY"
            bench_cfg = BacktestConfig(**{**cfg.__dict__, "benchmark_ticker": auto_symbol, "benchmark_label": f"Auto Sector ETF ({auto_symbol})", "benchmark_mode": "Sector ETF"})
    except Exception:
        bench_cfg = cfg

    try:
        bench_ret, bench_label, bench_fallback = _load_benchmark_returns(price, bench_cfg) if bench_cfg is not None else (price["close"].pct_change().fillna(0.0), "Ticker Buy & Hold fallback", True)
        bench_ret = pd.to_numeric(bench_ret.reindex(price.index), errors="coerce").fillna(0.0)
        bench_nav = (1.0 + bench_ret).cumprod().replace([np.inf, -np.inf], np.nan).ffill().bfill()
    except Exception:
        bench_label = "Benchmark fallback error"
        bench_fallback = True
        bench_nav = (1.0 + price["close"].pct_change().fillna(0.0)).cumprod()

    return {"price": price, "benchmark_nav": bench_nav, "benchmark_label": bench_label, "benchmark_fallback": bool(bench_fallback)}


def _v49x_decision_position(price_index: pd.DatetimeIndex, available_at: Any) -> int | None:
    try:
        idx = pd.to_datetime(pd.Index(price_index), errors="coerce")
        idx = idx[~pd.isna(idx)]
        if len(idx) == 0:
            return None
        ts = pd.to_datetime(available_at, errors="coerce")
        if pd.isna(ts):
            return None
        # t+1 strict : décision au premier bar de trading strictement après available_at normalisé.
        pos = int(np.searchsorted(idx.normalize().values, np.datetime64(pd.Timestamp(ts).normalize()), side="right"))
        if pos >= len(idx):
            return None
        return pos
    except Exception:
        return None


def _v49x_event_forward_map(
    source_rows: pd.DataFrame,
    price_pack: dict[str, Any],
    identity: dict[str, str],
    horizons: tuple[int, ...] = (3, 5, 10, 20),
) -> pd.DataFrame:
    price = price_pack.get("price", pd.DataFrame()) if isinstance(price_pack, dict) else pd.DataFrame()
    bench_nav = price_pack.get("benchmark_nav", pd.Series(dtype=float)) if isinstance(price_pack, dict) else pd.Series(dtype=float)
    if source_rows is None or source_rows.empty or price.empty or "close" not in price.columns:
        return pd.DataFrame()

    close = pd.to_numeric(price["close"], errors="coerce").ffill()
    bench_nav = pd.to_numeric(bench_nav.reindex(price.index), errors="coerce").ffill().bfill()

    rows = []
    for _, r in source_rows.iterrows():
        pos = _v49x_decision_position(price.index, r.get("available_at"))
        if pos is None or pos >= len(price) - 1:
            continue
        entry_px = _safe_float(close.iloc[pos], np.nan)
        entry_bench = _safe_float(bench_nav.iloc[pos], np.nan)
        if pd.isna(entry_px) or entry_px <= 0 or pd.isna(entry_bench) or entry_bench <= 0:
            continue

        row = {
            "date": r.get("date"),
            "available_at": r.get("available_at"),
            "decision_date": price.index[pos],
            "ticker": r.get("ticker", ""),
            "feature_family": r.get("feature_family", identity.get("source_family", "N/A")),
            "feature_name": r.get("feature_name", identity.get("source_feature", "N/A")),
            "value": r.get("value", np.nan),
            "value_num": _safe_float(r.get("value"), np.nan),
            "source": r.get("source", "unknown_source"),
            "confidence": _safe_float(r.get("confidence"), np.nan),
            "notes": r.get("notes", ""),
        }
        for h in horizons:
            fpos = min(pos + int(h), len(price) - 1)
            asset_ret = _safe_float(close.iloc[fpos] / entry_px - 1.0, np.nan)
            bench_ret = _safe_float(bench_nav.iloc[fpos] / entry_bench - 1.0, np.nan)
            row[f"asset_return_{h}b"] = asset_ret
            row[f"benchmark_return_{h}b"] = bench_ret
            row[f"active_return_{h}b"] = asset_ret - bench_ret if pd.notna(asset_ret) and pd.notna(bench_ret) else np.nan
        rows.append(row)

    ev = pd.DataFrame(rows)
    if not ev.empty:
        ev = ev.sort_values("decision_date").reset_index(drop=True)
    return ev


def _v49x_rule_candidates(ev: pd.DataFrame, preferred_rule: str = "") -> pd.DataFrame:
    if ev is None or ev.empty:
        return pd.DataFrame(columns=["rule", "direction", "threshold", "sample", "avg_active_10b", "median_active_10b", "hit_10b", "avg_active_20b", "score", "read"])

    value_num = pd.to_numeric(ev.get("value_num"), errors="coerce")
    rows = []

    def _metrics(mask: pd.Series, rule: str, direction: str, threshold: Any, read: str) -> dict[str, Any]:
        sub = ev.loc[mask.fillna(False)].copy()
        r10 = pd.to_numeric(sub.get("active_return_10b"), errors="coerce").dropna() if not sub.empty else pd.Series(dtype=float)
        r20 = pd.to_numeric(sub.get("active_return_20b"), errors="coerce").dropna() if not sub.empty else pd.Series(dtype=float)
        sample = int(len(sub))
        avg10 = float(r10.mean()) if not r10.empty else np.nan
        med10 = float(r10.median()) if not r10.empty else np.nan
        hit10 = float((r10 > 0).mean()) if not r10.empty else np.nan
        avg20 = float(r20.mean()) if not r20.empty else np.nan
        score = 35.0 + min(sample, 20) * 1.5
        if pd.notna(avg10): score += float(np.clip(avg10 * 450.0, -25.0, 25.0))
        if pd.notna(med10) and med10 > 0: score += 8.0
        if pd.notna(hit10): score += float(np.clip((hit10 - 0.50) * 35.0, -15.0, 15.0))
        if pd.notna(avg20): score += float(np.clip(avg20 * 250.0, -12.0, 12.0))
        return {"rule": rule, "direction": direction, "threshold": threshold, "sample": sample, "avg_active_10b": avg10, "median_active_10b": med10, "hit_10b": hit10, "avg_active_20b": avg20, "score": max(0.0, min(100.0, score)), "read": read}

    if value_num.notna().sum() >= max(3, int(len(ev) * 0.40)):
        q25 = float(value_num.quantile(0.25))
        q50 = float(value_num.quantile(0.50))
        q75 = float(value_num.quantile(0.75))
        rows.append(_metrics(value_num >= q75, "value_top_quartile", "positive", q75, "Feature numérique dans le quartile supérieur."))
        rows.append(_metrics(value_num <= q25, "value_bottom_quartile", "negative", q25, "Feature numérique dans le quartile inférieur."))
        rows.append(_metrics(value_num >= q50, "value_above_median", "positive", q50, "Feature numérique au-dessus de la médiane."))
        rows.append(_metrics(value_num <= q50, "value_below_median", "negative", q50, "Feature numérique sous la médiane."))
    else:
        txt = ev.get("value", pd.Series("", index=ev.index)).astype(str).str.lower().str.strip()
        positive_mask = txt.isin(["positive", "bullish", "beat", "up", "true", "1", "yes"])
        negative_mask = txt.isin(["negative", "bearish", "miss", "down", "-1", "false", "no"])
        if positive_mask.any():
            rows.append(_metrics(positive_mask, "value_positive_tag", "positive", "positive", "Catégorie positive."))
        if negative_mask.any():
            rows.append(_metrics(negative_mask, "value_negative_tag", "negative", "negative", "Catégorie négative."))
        rows.append(_metrics(pd.Series(True, index=ev.index), "all_events", "positive", "any", "Toutes les observations de la source."))

    out = pd.DataFrame(rows)
    if out.empty:
        return out

    pref = _v49x_norm(preferred_rule)
    if pref:
        out["preferred"] = out["rule"].map(lambda x: 1 if _v49x_norm(x) == pref else 0)
    else:
        out["preferred"] = 0
    out = out.sort_values(["preferred", "score", "avg_active_10b", "sample"], ascending=[False, False, False, False]).reset_index(drop=True)
    return out


def _v49x_apply_rule(ev: pd.DataFrame, rule_row: pd.Series | dict[str, Any]) -> pd.Series:
    if ev is None or ev.empty:
        return pd.Series(dtype=bool)
    rule = _v49x_norm(rule_row.get("rule", "") if isinstance(rule_row, (pd.Series, dict)) else "")
    threshold = rule_row.get("threshold", np.nan) if isinstance(rule_row, (pd.Series, dict)) else np.nan
    value_num = pd.to_numeric(ev.get("value_num"), errors="coerce")
    txt = ev.get("value", pd.Series("", index=ev.index)).astype(str).str.lower().str.strip()
    if rule == "value_top_quartile" or rule == "value_above_median":
        return value_num >= _safe_float(threshold, np.nan)
    if rule == "value_bottom_quartile" or rule == "value_below_median":
        return value_num <= _safe_float(threshold, np.nan)
    if rule == "value_positive_tag":
        return txt.isin(["positive", "bullish", "beat", "up", "true", "1", "yes"])
    if rule == "value_negative_tag":
        return txt.isin(["negative", "bearish", "miss", "down", "-1", "false", "no"])
    return pd.Series(True, index=ev.index)


def _v49x_common_context(
    df: pd.DataFrame | None = None,
    cfg: Any = None,
    external_features: Any = None,
    v49g_pack: Any = None,
    v49g3_pack: Any = None,
    v49f1_pack: Any = None,
    v49f_pack: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    identity = _v49x_pick_source_identity(v49g_pack=v49g_pack, v49g3_pack=v49g3_pack, v49f1_pack=v49f1_pack, v49f_pack=v49f_pack)
    if cfg is not None and not str(ticker or "").strip():
        ticker = str(getattr(cfg, "asset_ticker", "") or "").upper().strip()
    source_rows = _v49x_candidate_source_rows(external_features, identity, ticker, v49g3_pack, v49g_pack, v49f1_pack, v49f_pack)
    price_pack = _v49x_build_price_and_benchmark(df, cfg=cfg, ticker=ticker)
    ev = _v49x_event_forward_map(source_rows, price_pack, identity)
    rule_candidates = _v49x_rule_candidates(ev, preferred_rule=identity.get("source_rule", ""))
    rule_row = rule_candidates.iloc[0].to_dict() if isinstance(rule_candidates, pd.DataFrame) and not rule_candidates.empty else {}
    rule_mask = _v49x_apply_rule(ev, rule_row) if not ev.empty else pd.Series(dtype=bool)
    rule_events = ev.loc[rule_mask.fillna(False)].copy() if not ev.empty else pd.DataFrame()
    return {
        "identity": identity,
        "ticker": ticker,
        "source_rows": source_rows,
        "price_pack": price_pack,
        "event_map": ev,
        "rule_candidates": rule_candidates,
        "rule_row": rule_row,
        "rule_events": rule_events,
        "benchmark_label": price_pack.get("benchmark_label", "N/A") if isinstance(price_pack, dict) else "N/A",
        "benchmark_fallback": bool(price_pack.get("benchmark_fallback", True)) if isinstance(price_pack, dict) else True,
        "upstream": {"v49g": v49g_pack if isinstance(v49g_pack, dict) else {}, "v49g3": v49g3_pack if isinstance(v49g3_pack, dict) else {}, "v49f1": v49f1_pack if isinstance(v49f1_pack, dict) else {}, "v49f": v49f_pack if isinstance(v49f_pack, dict) else {}},
    }

# ============================================================
# V4.9H SOURCE SUFFICIENCY GATE — DATA GATE VS ALPHA REVIEW FIX
# Replace _source_sufficiency_gate_v49h_pack only
# ============================================================

def _source_sufficiency_gate_v49h_pack(ctx: dict[str, Any]) -> dict[str, Any]:
    """
    V4.9H — Source Sufficiency & Causal Event Validation Gate.

    Correctif objectif :
    - V4.9G.3 data/provenance BLOCK reste un vrai hard block.
    - V4.9G hard technical/data block reste un vrai hard block.
    - V4.9G negative alpha/rejected review n'est plus un hard block de suffisance H.
      C'est un alpha-review warning transmis à V4.9J/V4.9K.
    - H décide donc sur sample/provenance/available_at/rule events.
    - J/K restent responsables de rejeter la source si le holdout est négatif.
    - Lecture seule : aucun moteur, signal, trade, equity curve, sizing, exit ou verdict n'est modifié.
    """
    def _as_dict(x: Any) -> dict[str, Any]:
        return x if isinstance(x, dict) else {}

    def _norm_txt(x: Any) -> str:
        return str(x or "").strip().upper()

    def _gate_row(
        name: str,
        status: str,
        severity: str,
        current: Any,
        required: str,
        read: str,
    ) -> dict[str, Any]:
        return {
            "Gate": str(name),
            "Status": str(status),
            "Severity": str(severity),
            "Current": current,
            "Required": str(required),
            "Read": str(read),
        }

    def _safe_nunique_date(df: pd.DataFrame, col: str) -> int:
        try:
            if df is None or df.empty or col not in df.columns:
                return 0
            s = pd.to_datetime(df[col], errors="coerce").dropna().dt.normalize()
            return int(s.nunique())
        except Exception:
            return 0

    def _safe_concentration(df: pd.DataFrame, col: str, date_mode: bool = False) -> float:
        try:
            if df is None or df.empty or col not in df.columns:
                return 1.0
            if date_mode:
                s = pd.to_datetime(df[col], errors="coerce").dropna().dt.normalize()
            else:
                s = df[col].astype(str).replace("", np.nan).dropna()
            if s.empty:
                return 1.0
            vc = s.value_counts(normalize=True)
            return float(vc.max()) if not vc.empty else 1.0
        except Exception:
            return 1.0

    identity = _as_dict(ctx.get("identity", {}))
    source_rows = ctx.get("source_rows", pd.DataFrame())
    ev = ctx.get("event_map", pd.DataFrame())
    rule_events = ctx.get("rule_events", pd.DataFrame())
    rule_row = _as_dict(ctx.get("rule_row", {}))
    upstream = _as_dict(ctx.get("upstream", {}))

    v49g = _as_dict(upstream.get("v49g", {}))
    v49g3 = _as_dict(upstream.get("v49g3", {}))

    g_decision = _norm_txt(v49g.get("decision", ""))
    g_level = str(v49g.get("level", "N/A"))
    g_read = str(v49g.get("read", ""))
    g3_decision = _norm_txt(v49g3.get("decision", ""))
    g3_level = str(v49g3.get("level", "N/A"))
    g3_read = str(v49g3.get("read", ""))

    g3_block_count = int(_safe_float(v49g3.get("block_count", 0), 0))
    g3_review_count = int(_safe_float(v49g3.get("review_count", 0), 0))

    rows_total = int(len(source_rows)) if isinstance(source_rows, pd.DataFrame) else 0
    events_total = int(len(ev)) if isinstance(ev, pd.DataFrame) else 0
    rule_event_count = int(len(rule_events)) if isinstance(rule_events, pd.DataFrame) else 0

    unique_dates = _safe_nunique_date(source_rows, "available_at") if rows_total else 0

    try:
        source_count = (
            int(source_rows.get("source", pd.Series(dtype=str)).astype(str).replace("", np.nan).dropna().nunique())
            if rows_total else 0
        )
    except Exception:
        source_count = 0

    try:
        feature_count = (
            int(source_rows.get("feature_name", pd.Series(dtype=str)).astype(str).replace("", np.nan).dropna().nunique())
            if rows_total else 0
        )
    except Exception:
        feature_count = 0

    try:
        missing_available = (
            int(pd.to_datetime(source_rows.get("available_at", pd.Series(dtype="datetime64[ns]")), errors="coerce").isna().sum())
            if rows_total else 0
        )
    except Exception:
        missing_available = rows_total

    try:
        missing_value = (
            int(source_rows.get("value", pd.Series(dtype=object)).isna().sum())
            if rows_total else 0
        )
    except Exception:
        missing_value = rows_total

    invalid_decision = max(0, rows_total - events_total)
    date_concentration = _safe_concentration(source_rows, "available_at", date_mode=True)
    source_concentration = _safe_concentration(source_rows, "source", date_mode=False)

    # Hard-block only real data/provenance/technical failures.
    # Negative source-only alpha from V4.9G is not a data sufficiency failure.
    g3_ready = (
        "READY_FOR_V49H" in g3_decision
        or "REUPLOAD_VALIDATED" in g3_decision
        or "VALIDATED" in g3_decision
    )
    g3_hard_block = (
        g3_block_count > 0
        or "FIX_SOURCE_DATA_BEFORE_V49H" in g3_decision
        or "BLOCK" in g3_decision
        or "ERROR" in g3_decision
    )

    g_hard_block = (
        "WAIT_FOR_PRICE_DATA" in g_decision
        or "V49G_ERROR" in g_decision
        or "RETURN_TO_V49F1_OR_DATA" in g_decision
        or "RUNNER_BLOCKED" in g_level.upper()
    )

    # Alpha review is intentionally non-blocking for H.
    # J/K must reject later if holdout remains negative.
    g_alpha_negative_or_rejected = (
        "RETURN_TO_V49E_OR_EXPAND_DATA" in g_decision
        or "SOURCE_ONLY_REJECT" in g_decision
        or "REJECTED" in g_level.upper()
    )

    upstream_data_blocked = bool(g3_hard_block or g_hard_block)
    upstream_reviews = []
    if not g3_ready and g3_decision:
        upstream_reviews.append("V4.9G.3 not explicitly ready")
    if g3_review_count > 0:
        upstream_reviews.append(f"V4.9G.3 review_count={g3_review_count}")
    if g_alpha_negative_or_rejected:
        upstream_reviews.append("V4.9G alpha/source-only review negative")

    gates_rows: list[dict[str, Any]] = []

    gates_rows.append(
        _gate_row(
            "Upstream data/provenance gate",
            "FAIL" if upstream_data_blocked else ("REVIEW" if upstream_reviews else "PASS"),
            "Critical" if upstream_data_blocked else ("Medium" if upstream_reviews else "None"),
            f"V4.9G={g_decision or 'N/A'} ; V4.9G.3={g3_decision or 'N/A'} ; G3 blocks={g3_block_count}",
            "no hard data/provenance block",
            (
                "H bloque seulement si G/G.3 signalent un blocage data/provenance/technique. "
                "Une alpha review négative de G doit être traitée par J/K, pas par le gate de suffisance H."
            ),
        )
    )

    gates_rows.append(
        _gate_row(
            "V4.9G source-only alpha review",
            "REVIEW" if g_alpha_negative_or_rejected else ("PASS" if g_decision else "REVIEW"),
            "High" if g_alpha_negative_or_rejected else ("None" if g_decision else "Medium"),
            f"{g_level} / {g_decision or 'N/A'}",
            "positive preferred, but not an H data blocker",
            (
                "V4.9G négatif interdit la promotion directe, mais ne doit pas empêcher H/I/J "
                "de produire un diagnostic holdout complet si la provenance et le sample sont propres."
            ),
        )
    )

    gates_rows.append(
        _gate_row(
            "Source rows",
            "PASS" if rows_total >= 30 else ("REVIEW" if rows_total >= 15 else "FAIL"),
            "High" if rows_total < 15 else ("Medium" if rows_total < 30 else "None"),
            rows_total,
            ">=30 preferred, >=15 review",
            "Nombre de lignes source candidates après filtre family/feature.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Rule events",
            "PASS" if rule_event_count >= 8 else "FAIL",
            "Critical" if rule_event_count < 5 else ("High" if rule_event_count < 8 else "None"),
            rule_event_count,
            ">=8 minimum",
            "Évènements qui passent la règle source-only choisie.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Unique dates",
            "PASS" if unique_dates >= 6 else "FAIL",
            "High" if unique_dates < 6 else "None",
            unique_dates,
            ">=6 dates",
            "Évite une conclusion concentrée sur une seule date.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Source diversity",
            "PASS" if source_count >= 2 else "REVIEW",
            "Medium" if source_count < 2 else "None",
            source_count,
            ">=2 providers/source tags",
            "Réduit le risque d'une source unique fragile.",
        )
    )

    gates_rows.append(
        _gate_row(
            "available_at quality",
            "PASS" if missing_available == 0 else "FAIL",
            "Critical" if missing_available else "None",
            missing_available,
            "0 missing",
            "Chaque feature doit avoir un timestamp de disponibilité causale.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Forward map alignment",
            "PASS" if invalid_decision == 0 and events_total > 0 else "FAIL",
            "High" if invalid_decision or events_total <= 0 else "None",
            f"{events_total}/{rows_total}",
            "all rows alignable",
            "Les lignes doivent être plaçables sur le calendrier prix après available_at.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Value missingness",
            "PASS" if rows_total and missing_value / max(rows_total, 1) <= 0.05 else "REVIEW",
            "Medium" if missing_value else "None",
            missing_value,
            "<=5%",
            "Valeurs source manquantes avant construction de règle.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Date concentration",
            "PASS" if date_concentration <= 0.40 or unique_dates >= 10 else "REVIEW",
            "Medium" if date_concentration > 0.40 and unique_dates < 10 else "None",
            _format_pct(date_concentration),
            "<=40% preferred or >=10 dates",
            "Part de lignes concentrées sur la même date.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Provider concentration",
            "PASS" if source_concentration <= 0.80 or source_count >= 3 else "REVIEW",
            "Medium" if source_concentration > 0.80 and source_count < 3 else "None",
            _format_pct(source_concentration),
            "<=80% preferred or >=3 sources",
            "Risque de dépendance à un seul provider.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Benchmark active map",
            "REVIEW" if ctx.get("benchmark_fallback", True) else "PASS",
            "Medium" if ctx.get("benchmark_fallback", True) else "None",
            ctx.get("benchmark_label", "N/A"),
            "external/sector benchmark preferred",
            "Active return forward doit être relatif à un benchmark exploitable.",
        )
    )

    gates = pd.DataFrame(gates_rows)

    # Upstream alpha review is not a hard failure. Upstream data/provenance and core H failures remain hard.
    fail_count = int((gates["Status"].astype(str) == "FAIL").sum()) if not gates.empty else 0
    review_count = int((gates["Status"].astype(str) == "REVIEW").sum()) if not gates.empty else 0
    critical_count = int(((gates["Status"].astype(str) == "FAIL") & (gates["Severity"].astype(str) == "Critical")).sum()) if not gates.empty else 0

    score = 100.0
    score -= critical_count * 35.0
    score -= max(0, fail_count - critical_count) * 18.0
    score -= review_count * 5.0
    score = max(0.0, min(100.0, float(score)))

    if upstream_data_blocked:
        level = "Source sufficiency blocked by upstream data gate"
        decision = "RETURN_TO_V49G3_BEFORE_V49I"
        read = (
            "V4.9H bloque par propagation data/provenance : V4.9G/V4.9G.3 signalent un blocage technique "
            "ou un reupload non propre avant construction I/J."
        )
    elif fail_count > 0:
        level = "Source sufficiency blocked"
        decision = "EXPAND_SOURCE_SAMPLE_BEFORE_V49I"
        read = (
            "V4.9H bloque : sample/rule events, available_at ou alignement insuffisant avant construction de signal source-only."
        )
    elif g_alpha_negative_or_rejected:
        level = "Source sufficiency ready / alpha review negative"
        decision = "READY_FOR_V49I_SOURCE_SIGNAL_CONSTRUCTION_WITH_ALPHA_REVIEW"
        read = (
            "V4.9H valide la suffisance data/provenance/sample. V4.9G reste négatif : "
            "I/J peuvent produire le blueprint et le holdout, mais K/V5 devront rejeter si le holdout ne confirme pas."
        )
    elif review_count > 0:
        level = "Source sufficiency review"
        decision = "READY_FOR_V49I_SOURCE_SIGNAL_CONSTRUCTION_WITH_REVIEW"
        read = (
            "V4.9H accepte la construction V4.9I sous revue : pas de promotion avant validation J/K."
        )
    else:
        level = "Source sufficiency ready"
        decision = "READY_FOR_V49I_SOURCE_SIGNAL_CONSTRUCTION"
        read = "V4.9H valide la suffisance minimale de la source candidate pour construire un blueprint causal."

    summary = pd.DataFrame(
        [
            ["V4.9H level", level, "Lecture synthétique du gate de suffisance source."],
            ["V4.9H score", f"{_format_num(score, 0)}/100", "Score data/provenance/sample, pas score alpha."],
            ["Decision", decision, "Décision research V4.9H."],
            ["Read", read, "Interprétation opérationnelle."],
            ["Ticker", ctx.get("ticker", "N/A"), "Ticker audité."],
            ["Source family", identity.get("source_family", "N/A"), "Famille source candidate."],
            ["Source feature", identity.get("source_feature", "N/A"), "Feature source candidate."],
            ["Rule", str(rule_row.get("rule", "N/A")), "Règle source-only utilisée."],
            ["Direction", str(rule_row.get("direction", "N/A")), "Direction économique déclarée par la règle."],
            ["Rule events", rule_event_count, "Évènements passés par la règle."],
            ["Source rows", rows_total, "Lignes source candidates."],
            ["Events total", events_total, "Lignes alignées au calendrier prix."],
            ["Unique dates", unique_dates, "Dates distinctes available_at."],
            ["Source count", source_count, "Providers/source tags distincts."],
            ["Feature count", feature_count, "Features distinctes dans la source sélectionnée."],
            ["V4.9G decision", g_decision or "N/A", "Décision alpha review source-only."],
            ["V4.9G.3 decision", g3_decision or "N/A", "Décision reupload/provenance."],
            ["V4.9G.3 block count", g3_block_count, "Blocages data/provenance hérités."],
            ["Alpha review negative", str(bool(g_alpha_negative_or_rejected)), "Doit être tranché par J/K, pas par H seul."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    next_actions = pd.DataFrame(
        [
            {
                "Priority": "P0",
                "Action": "Do not promote",
                "Reason": "H is sufficiency only",
                "Next Step": "Même si H passe, K/V5 doivent rejeter si J ne valide pas le holdout.",
            },
            {
                "Priority": "P0",
                "Action": "Keep G.3 hard block",
                "Reason": f"G3 blocks={g3_block_count}",
                "Next Step": "Toute contamination, missing available_at ou outcome label doit bloquer H.",
            },
            {
                "Priority": "P1",
                "Action": "Run V4.9I/J diagnostic",
                "Reason": "sample/provenance sufficient",
                "Next Step": "Construire blueprint puis valider/rejeter en holdout événementiel.",
            },
            {
                "Priority": "P1",
                "Action": "Treat V4.9G negative as alpha review",
                "Reason": g_decision or "N/A",
                "Next Step": "Si J confirme négatif, K rejette et V5 n'enregistre pas.",
            },
        ]
    )

    cards = [
        {"label": "V4.9H gate", "value": level, "delta": f"{_format_num(score, 0)}/100"},
        {"label": "Upstream data gate", "value": "BLOCK" if upstream_data_blocked else "PASS", "delta": "G/G.3"},
        {"label": "V4.9G alpha", "value": "REVIEW" if g_alpha_negative_or_rejected else "PASS", "delta": g_decision or "N/A"},
        {"label": "Rule events", "value": f"{rule_event_count}/8", "delta": "source-only"},
        {"label": "Sources", "value": f"{source_count}/2", "delta": "providers"},
        {"label": "Decision", "value": decision, "delta": "research only"},
    ]

    return {
        "enabled": True,
        "level": level,
        "score": score,
        "decision": decision,
        "read": read,
        "cards": cards,
        "summary": summary,
        "gates": gates,
        "next_actions": next_actions,
        "rule_events": rule_events,
        "rule_row": rule_row,
        "rule_event_count": rule_event_count,
        "source_rows": rows_total,
        "source_count": source_count,
        "unique_dates": unique_dates,
        "upstream_blocked": upstream_data_blocked,
        "upstream_block_reasons": ["data/provenance hard block"] if upstream_data_blocked else [],
        "upstream_reviews": upstream_reviews,
        "v49g_decision": g_decision,
        "v49g3_decision": g3_decision,
        "v49g3_block_count": g3_block_count,
        "alpha_review_negative": bool(g_alpha_negative_or_rejected),
    }

def _causal_source_signal_construction_lab_v49i_pack(ctx: dict[str, Any], h_pack: dict[str, Any]) -> dict[str, Any]:
    identity = ctx.get("identity", {})
    ev = ctx.get("event_map", pd.DataFrame())
    candidates = ctx.get("rule_candidates", pd.DataFrame())
    rule_row = ctx.get("rule_row", {})
    rule_events = h_pack.get("rule_events", pd.DataFrame())
    source_feature = identity.get("source_feature", "N/A")
    source_family = identity.get("source_family", "N/A")
    rule = rule_row.get("rule", "N/A")
    threshold = rule_row.get("threshold", "N/A")
    direction = rule_row.get("direction", "positive")

    h_pass = str(h_pack.get("decision", "")).startswith("READY_FOR_V49I")
    sample = int(len(rule_events)) if isinstance(rule_events, pd.DataFrame) else 0

    blueprint = pd.DataFrame([
        ["source_id", f"SRC-V49-{_v49x_norm(source_family).upper()}-{_v49x_norm(source_feature).upper()}", "Identifiant stable de recherche, non moteur."],
        ["ticker", ctx.get("ticker", "N/A"), "Ticker source."],
        ["source_family", source_family, "Famille externe causale."],
        ["source_feature", source_feature, "Feature externe sélectionnée."],
        ["rule", rule, "Règle source-only retenue."],
        ["threshold", threshold, "Seuil de la règle."],
        ["direction", direction, "Direction économique de la règle."],
        ["available_at_policy", "mandatory point-in-time", "Aucune ligne sans available_at ne peut entrer dans le blueprint."],
        ["decision_bar_policy", "strict t+1 after available_at", "La décision est placée au bar de trading suivant la disponibilité."],
        ["holding_horizons", "3B / 5B / 10B / 20B", "Horizons de mesure source-only, pas exits moteur."],
        ["benchmark_policy", ctx.get("benchmark_label", "N/A"), "Active return mesuré vs benchmark."],
        ["engine_injection", "forbidden", "V4.9I ne modifie pas le moteur ni le signal existant."],
        ["oos_permission", "forbidden before V4.9J/V4.9K", "Pas de passage OOS/live depuis V4.9I."],
    ], columns=["Field", "Value", "Read"])

    schema = pd.DataFrame([
        {"Column": "date", "Type": "datetime/date", "Requirement": "event/economic date", "Leakage rule": "not used as decision bar if available_at differs"},
        {"Column": "available_at", "Type": "datetime", "Requirement": "mandatory", "Leakage rule": "decision bar must be strictly after available_at"},
        {"Column": "ticker", "Type": "string", "Requirement": "mandatory", "Leakage rule": "must match audited ticker"},
        {"Column": "feature_family", "Type": "string", "Requirement": "mandatory", "Leakage rule": "stable taxonomy"},
        {"Column": "feature_name", "Type": "string", "Requirement": "mandatory", "Leakage rule": "stable taxonomy"},
        {"Column": "value", "Type": "float/string", "Requirement": "mandatory", "Leakage rule": "no realized_alpha / future_return / pnl labels"},
        {"Column": "source", "Type": "string", "Requirement": "mandatory", "Leakage rule": "provider/source audit retained"},
        {"Column": "confidence", "Type": "float", "Requirement": "recommended", "Leakage rule": "quality metadata only"},
    ])

    if not h_pass:
        level = "Signal blueprint blocked by H"
        score = max(0.0, min(60.0, _safe_float(h_pack.get("score", 0.0), 0.0) * 0.75))
        decision = "WAIT_FOR_V49H_PASS_BEFORE_V49I"
        read = "V4.9I prépare le contrat, mais ne valide pas de blueprint actif tant que V4.9H bloque la source."
    elif sample < 8:
        level = "Signal blueprint low sample"
        score = 55.0
        decision = "SOURCE_RULE_TOO_FRAGILE"
        read = "La règle existe mais l'échantillon d'évènements reste trop faible pour un blueprint exploitable."
    else:
        level = "Causal source signal blueprint ready"
        score = min(100.0, 70.0 + min(sample, 20))
        decision = "SOURCE_SIGNAL_BLUEPRINT_READY_FOR_V49J"
        read = "V4.9I construit un blueprint causal t+1 exploitable pour validation événementielle V4.9J."

    summary = pd.DataFrame([
        ["V4.9I level", level, "Lecture synthétique du blueprint causal."],
        ["V4.9I score", score, "Score de construction source-only, pas score moteur."],
        ["Decision", decision, "Décision avant holdout V4.9J."],
        ["Read", read, "Interprétation opérationnelle."],
        ["Source family", source_family, "Famille retenue."],
        ["Source feature", source_feature, "Feature retenue."],
        ["Selected rule", rule, "Règle retenue."],
        ["Threshold", threshold, "Seuil utilisé."],
        ["Rule events", sample, "Évènements utilisables par la règle."],
        ["t+1 enforcement", "strict", "Blueprint causal uniquement."],
    ], columns=["Metric", "Value", "Read"])

    cards = [
        {"label": "V4.9I blueprint", "value": level, "delta": f"{_format_num(score,0)}/100"},
        {"label": "Source", "value": source_feature, "delta": source_family},
        {"label": "Rule", "value": rule, "delta": "t+1"},
        {"label": "Events", "value": str(sample), "delta": "rule sample"},
        {"label": "Decision", "value": decision, "delta": "research only"},
    ]

    next_actions = pd.DataFrame([
        {"Priority": "P0", "Action": "Do not inject signal", "Reason": "V4.9I is blueprint only", "Next Step": "Le moteur reste inchangé."},
        {"Priority": "P0", "Action": "Enforce t+1", "Reason": "available_at causality", "Next Step": "Toutes les décisions utilisent le bar suivant available_at."},
        {"Priority": "P1", "Action": "Run V4.9J holdout", "Reason": decision, "Next Step": "Valider early/late event stability avant promotion."},
    ])

    return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": cards, "summary": summary, "blueprint": blueprint, "schema": schema, "rule_leaderboard": candidates if isinstance(candidates, pd.DataFrame) else pd.DataFrame(), "next_actions": next_actions, "rule_row": rule_row, "rule_events": rule_events}


def _event_holdout_source_validation_v49j_pack(ctx: dict[str, Any], h_pack: dict[str, Any], i_pack: dict[str, Any]) -> dict[str, Any]:
    """
    V4.9J — Event Holdout / Walk-Forward Source Validation.

    Gate propagation patch:
    - V4.9J cannot validate, reject, or watch a holdout if V4.9H is not READY.
    - V4.9J cannot run an autonomous holdout if V4.9I did not produce a valid source-only blueprint.
    - This preserves institutional sequencing:
        G/G.3 BLOCK -> H BLOCK -> I BLOCK -> J BLOCK -> K REJECT -> V5 REJECT.
    - Read-only: no engine, signal, trade, equity curve, sizing, exit, OOS, paper/live or main verdict is modified.
    """
    def _as_dict(x: Any) -> dict[str, Any]:
        return x if isinstance(x, dict) else {}

    def _norm_decision(x: Any) -> str:
        return str(x or "").strip().upper()

    h_pack = _as_dict(h_pack)
    i_pack = _as_dict(i_pack)
    ctx = _as_dict(ctx)

    h_decision = _norm_decision(h_pack.get("decision", ""))
    i_decision = _norm_decision(i_pack.get("decision", ""))

    h_ready = h_decision.startswith("READY_FOR_V49I")
    i_ready = i_decision.startswith("SOURCE_SIGNAL_BLUEPRINT_READY")

    rule_events = i_pack.get("rule_events", pd.DataFrame())
    if rule_events is None or not isinstance(rule_events, pd.DataFrame) or rule_events.empty:
        rule_events = pd.DataFrame()

    if not rule_events.empty and "decision_date" in rule_events.columns:
        ev = rule_events.sort_values("decision_date").copy()
    else:
        ev = rule_events.copy() if isinstance(rule_events, pd.DataFrame) else pd.DataFrame()

    n = int(len(ev))

    # ------------------------------------------------------------------
    # HARD UPSTREAM BLOCK
    # ------------------------------------------------------------------
    # Important: V4.9J must not classify the source as rejected/watch/validated
    # when H/I are already blocked. Otherwise the UI suggests that J performed
    # a valid holdout despite a failed causal/sufficiency gate.
    if not h_ready or not i_ready:
        level = "Holdout blocked by upstream gate"
        score = 0.0
        decision = "WAIT_FOR_V49I_PASS_BEFORE_V49J"
        read = (
            "V4.9J bloque par propagation : V4.9H ou V4.9I n'a pas donné "
            "l'autorisation propre pour une validation événementielle holdout. "
            f"V4.9H decision={h_decision or 'N/A'} ; V4.9I decision={i_decision or 'N/A'}."
        )

        event_map = ev.copy()
        if not event_map.empty:
            event_map["holdout_segment"] = "BLOCKED_BY_UPSTREAM_GATE"
            event_map["rule"] = _as_dict(i_pack.get("rule_row", {})).get("rule", "N/A")
            event_map["benchmark"] = ctx.get("benchmark_label", "N/A")
            event_map["v49j_status"] = "UPSTREAM_BLOCKED"

        # Keep a matrix-shaped object so the existing renderer/download buttons
        # remain stable, but do not report holdout performance as valid.
        summary_map = pd.DataFrame(
            [
                {
                    "Segment": "Blocked before holdout",
                    "Events": n,
                    "avg_active_3b": np.nan,
                    "median_active_3b": np.nan,
                    "hit_3b": np.nan,
                    "worst_active_3b": np.nan,
                    "avg_active_5b": np.nan,
                    "median_active_5b": np.nan,
                    "hit_5b": np.nan,
                    "worst_active_5b": np.nan,
                    "avg_active_10b": np.nan,
                    "median_active_10b": np.nan,
                    "hit_10b": np.nan,
                    "worst_active_10b": np.nan,
                    "avg_active_20b": np.nan,
                    "median_active_20b": np.nan,
                    "hit_20b": np.nan,
                    "worst_active_20b": np.nan,
                    "Block reason": "V4.9H/V4.9I upstream gate did not pass",
                }
            ]
        )

        summary = pd.DataFrame(
            [
                ["V4.9J level", level, "Lecture synthétique holdout."],
                ["V4.9J score", score, "Score holdout événementiel."],
                ["Decision", decision, "Décision avant V4.9K."],
                ["Read", read, "Interprétation opérationnelle."],
                ["V4.9H decision", h_decision or "N/A", "H doit être READY_FOR_V49I avant J."],
                ["V4.9I decision", i_decision or "N/A", "I doit être SOURCE_SIGNAL_BLUEPRINT_READY avant J."],
                ["Full events available", n, "Évènements visibles mais non validés en holdout."],
                ["Holdout events", 0, "Aucun holdout autorisé tant que H/I bloquent."],
                ["Holdout avg active 10B", np.nan, "Non calculé comme validation tant que H/I bloquent."],
                ["Holdout hit 10B", np.nan, "Non calculé comme validation tant que H/I bloquent."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        cards = [
            {"label": "V4.9J holdout", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Upstream", "value": "BLOCK", "delta": "H/I"},
            {"label": "Events", "value": str(n), "delta": "not validated"},
            {"label": "Holdout n", "value": "0", "delta": "blocked"},
            {"label": "Holdout 10B", "value": "N/A", "delta": "blocked"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        next_actions = pd.DataFrame(
            [
                {
                    "Priority": "P0",
                    "Action": "Do not run V4.9J holdout",
                    "Reason": "H/I upstream gate blocked",
                    "Next Step": "Corriger V4.9G.3/V4.9H puis reconstruire V4.9I avant tout holdout.",
                },
                {
                    "Priority": "P0",
                    "Action": "Do not OOS promote",
                    "Reason": decision,
                    "Next Step": "V4.9K doit hériter du blocage et rejeter la promotion.",
                },
                {
                    "Priority": "P1",
                    "Action": "Fix upstream source gate",
                    "Reason": f"H={h_decision or 'N/A'} / I={i_decision or 'N/A'}",
                    "Next Step": "Repasser V4.9A→V4.9G.3 proprement, puis V4.9H/I.",
                },
            ]
        )

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "holdout_matrix": summary_map,
            "event_map": event_map,
            "next_actions": next_actions,
            "holdout_avg_active_10b": np.nan,
            "full_avg_active_10b": np.nan,
            "holdout_n": 0,
            "upstream_blocked": True,
            "h_decision": h_decision,
            "i_decision": i_decision,
        }

    # ------------------------------------------------------------------
    # NORMAL V4.9J HOLDOUT LOGIC — only after H and I are both ready.
    # ------------------------------------------------------------------
    split = int(max(1, np.floor(n * 0.70))) if n > 1 else n
    train = ev.iloc[:split].copy() if n else pd.DataFrame()
    holdout = ev.iloc[split:].copy() if n > split else pd.DataFrame()

    def stats(label: str, sub: pd.DataFrame) -> dict[str, Any]:
        row = {"Segment": label, "Events": int(len(sub))}
        for h in [3, 5, 10, 20]:
            r = pd.to_numeric(
                sub.get(f"active_return_{h}b", pd.Series(dtype=float)),
                errors="coerce",
            ).dropna()
            row[f"avg_active_{h}b"] = float(r.mean()) if not r.empty else np.nan
            row[f"median_active_{h}b"] = float(r.median()) if not r.empty else np.nan
            row[f"hit_{h}b"] = float((r > 0).mean()) if not r.empty else np.nan
            row[f"worst_active_{h}b"] = float(r.min()) if not r.empty else np.nan
        return row

    summary_map = (
        pd.DataFrame(
            [
                stats("Full", ev),
                stats("Train early events", train),
                stats("Holdout late events", holdout),
            ]
        )
        if n
        else pd.DataFrame()
    )

    holdout_n = int(len(holdout))
    holdout_avg10 = (
        _safe_float(
            summary_map.loc[
                summary_map["Segment"] == "Holdout late events",
                "avg_active_10b",
            ].iloc[0],
            np.nan,
        )
        if not summary_map.empty
        else np.nan
    )
    holdout_hit10 = (
        _safe_float(
            summary_map.loc[
                summary_map["Segment"] == "Holdout late events",
                "hit_10b",
            ].iloc[0],
            np.nan,
        )
        if not summary_map.empty
        else np.nan
    )
    full_avg10 = (
        _safe_float(
            summary_map.loc[
                summary_map["Segment"] == "Full",
                "avg_active_10b",
            ].iloc[0],
            np.nan,
        )
        if not summary_map.empty
        else np.nan
    )

    event_map = ev.copy()
    if not event_map.empty:
        event_map["holdout_segment"] = np.where(
            np.arange(len(event_map)) < split,
            "TRAIN_EARLY",
            "HOLDOUT_LATE",
        )
        event_map["rule"] = _as_dict(i_pack.get("rule_row", {})).get("rule", "N/A")
        event_map["benchmark"] = ctx.get("benchmark_label", "N/A")

    if n < 8:
        level = "Holdout blocked / low events"
        score = 25.0 + n * 3.0
        decision = "EXPAND_EVENTS_BEFORE_V49K"
        read = "V4.9J ne peut pas valider le holdout : échantillon d'évènements trop faible."
    elif holdout_n < 3:
        level = "Holdout review / thin test"
        score = 45.0
        decision = "HOLDOUT_SOURCE_WATCH_ONLY"
        read = "Holdout calculé mais test trop fin pour promotion."
    elif pd.notna(holdout_avg10) and holdout_avg10 > 0 and pd.notna(holdout_hit10) and holdout_hit10 >= 0.55:
        level = "Holdout source validated"
        score = min(100.0, 70.0 + holdout_avg10 * 500.0 + (holdout_hit10 - 0.5) * 40.0)
        decision = "HOLDOUT_SOURCE_VALIDATED_FOR_V49K"
        read = "V4.9J valide un holdout événementiel positif à confirmer par governance V4.9K."
    elif pd.notna(holdout_avg10) and holdout_avg10 > 0:
        level = "Holdout source watch"
        score = 58.0
        decision = "HOLDOUT_SOURCE_WATCH_ONLY"
        read = "Holdout positif mais hit-rate ou robustesse insuffisante : source watch uniquement."
    else:
        level = "Holdout source rejected"
        score = 35.0
        decision = "HOLDOUT_SOURCE_REJECTED"
        read = "V4.9J ne confirme pas l'active return en holdout."

    summary = pd.DataFrame(
        [
            ["V4.9J level", level, "Lecture synthétique holdout."],
            ["V4.9J score", score, "Score holdout événementiel."],
            ["Decision", decision, "Décision avant V4.9K."],
            ["Read", read, "Interprétation opérationnelle."],
            ["V4.9H decision", h_decision or "N/A", "Gate H validé avant J."],
            ["V4.9I decision", i_decision or "N/A", "Gate I validé avant J."],
            ["Full events", n, "Évènements source-only passés par la règle."],
            ["Train events", int(len(train)), "Première partie chronologique."],
            ["Holdout events", holdout_n, "Dernière partie chronologique."],
            ["Full avg active 10B", full_avg10, "Moyenne active 10B full sample."],
            ["Holdout avg active 10B", holdout_avg10, "Moyenne active 10B holdout."],
            ["Holdout hit 10B", holdout_hit10, "Hit-rate actif 10B holdout."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    cards = [
        {"label": "V4.9J holdout", "value": level, "delta": f"{_format_num(score, 0)}/100"},
        {"label": "Events", "value": str(n), "delta": "rule sample"},
        {"label": "Holdout n", "value": str(holdout_n), "delta": "late events"},
        {"label": "Holdout 10B", "value": _format_pct(holdout_avg10), "delta": "active"},
        {"label": "Hit 10B", "value": _format_pct(holdout_hit10), "delta": "holdout"},
        {"label": "Decision", "value": decision, "delta": "research only"},
    ]

    next_actions = pd.DataFrame(
        [
            {
                "Priority": "P0",
                "Action": "Do not OOS promote",
                "Reason": decision,
                "Next Step": "V4.9K décide uniquement après H/I/J.",
            },
            {
                "Priority": "P1",
                "Action": "Increase late events",
                "Reason": f"holdout_n={holdout_n}",
                "Next Step": "Ajouter des observations récentes point-in-time.",
            },
            {
                "Priority": "P1",
                "Action": "Check horizon stability",
                "Reason": "3B/5B/10B/20B",
                "Next Step": "Ne pas sélectionner une source positive sur un seul horizon isolé.",
            },
        ]
    )

    return {
        "enabled": True,
        "level": level,
        "score": score,
        "decision": decision,
        "read": read,
        "cards": cards,
        "summary": summary,
        "holdout_matrix": summary_map,
        "event_map": event_map,
        "next_actions": next_actions,
        "holdout_avg_active_10b": holdout_avg10,
        "full_avg_active_10b": full_avg10,
        "holdout_n": holdout_n,
        "upstream_blocked": False,
        "h_decision": h_decision,
        "i_decision": i_decision,
    }


def _source_promotion_governance_gate_v49k_pack(ctx: dict[str, Any], h_pack: dict[str, Any], i_pack: dict[str, Any], j_pack: dict[str, Any]) -> dict[str, Any]:
    h_dec = str(h_pack.get("decision", ""))
    i_dec = str(i_pack.get("decision", ""))
    j_dec = str(j_pack.get("decision", ""))
    source_count = int(h_pack.get("source_count", 0) or 0)
    rule_events = int(h_pack.get("rule_event_count", 0) or 0)
    holdout_avg10 = _safe_float(j_pack.get("holdout_avg_active_10b"), np.nan)
    holdout_n = int(j_pack.get("holdout_n", 0) or 0)

    gates_rows = []
    def gate(name: str, status: str, severity: str, current: Any, required: str, read: str):
        gates_rows.append({"Gate": name, "Status": status, "Severity": severity, "Current": current, "Required": required, "Read": read})

    gate("V4.9H source sufficiency", "PASS" if h_dec.startswith("READY_FOR_V49I") else "FAIL", "Critical", h_dec, "READY_FOR_V49I", "La source doit passer sample/provenance.")
    gate("V4.9I blueprint", "PASS" if i_dec.startswith("SOURCE_SIGNAL_BLUEPRINT_READY") else ("REVIEW" if "WAIT" not in i_dec else "FAIL"), "High", i_dec, "SOURCE_SIGNAL_BLUEPRINT_READY", "La règle t+1 doit être définie sans moteur.")
    gate("V4.9J holdout", "PASS" if j_dec.startswith("HOLDOUT_SOURCE_VALIDATED") else ("REVIEW" if "WATCH" in j_dec else "FAIL"), "High", j_dec, "HOLDOUT_SOURCE_VALIDATED", "La source doit garder un edge en late holdout.")
    gate("Rule event count", "PASS" if rule_events >= 8 else "FAIL", "High", rule_events, ">=8", "Minimum d'évènements de règle.")
    gate("Provider diversity", "PASS" if source_count >= 2 else "REVIEW", "Medium", source_count, ">=2", "Diversité source recommandée avant registry.")
    gate("Holdout active 10B", "PASS" if pd.notna(holdout_avg10) and holdout_avg10 > 0 else "FAIL", "High", holdout_avg10, ">0", "Le forward active return holdout doit être positif.")
    gate("Holdout sample", "PASS" if holdout_n >= 3 else "REVIEW", "Medium", holdout_n, ">=3 late events", "Minimum pratique pour éviter un holdout anecdotique.")
    gate("Paper/live permission", "BLOCK", "Critical", "not allowed", "never from V4.9K", "Même promue, la source reste research/tournament only.")

    gates = pd.DataFrame(gates_rows)
    fail_core = int(((gates["Status"] == "FAIL") & (gates["Gate"] != "Paper/live permission")).sum())
    review_core = int((gates["Status"] == "REVIEW").sum())

    if fail_core == 0 and j_dec.startswith("HOLDOUT_SOURCE_VALIDATED"):
        level = "Source promotion ready for V5 registry"
        decision = "PROMOTE_SOURCE_TO_V50_REGISTRY"
        score = max(75.0, min(100.0, (h_pack.get("score", 0) + i_pack.get("score", 0) + j_pack.get("score", 0)) / 3.0))
        read = "V4.9K autorise l'enregistrement registry research/tournament, pas le live/paper." 
    elif fail_core <= 1 and review_core >= 1:
        level = "Source promotion watch"
        decision = "WATCHLIST_SOURCE_REQUIRES_MORE_EVENTS"
        score = 55.0
        read = "V4.9K garde la source en watch : données ou holdout encore insuffisants." 
    else:
        level = "Source promotion rejected"
        decision = "REJECT_SOURCE_DO_NOT_PROMOTE"
        score = 25.0
        read = "V4.9K rejette la promotion : H/I/J ne confirment pas assez la source." 

    summary = pd.DataFrame([
        ["V4.9K level", level, "Lecture synthétique du gate de promotion."],
        ["V4.9K score", score, "Score governance, pas score live."],
        ["Decision", decision, "Décision avant V5.0 registry."],
        ["Read", read, "Interprétation opérationnelle."],
        ["H decision", h_dec, "Décision source sufficiency."],
        ["I decision", i_dec, "Décision blueprint."],
        ["J decision", j_dec, "Décision holdout."],
        ["Paper/live", "blocked", "Pas de live/paper depuis cette couche."],
    ], columns=["Metric", "Value", "Read"])

    next_actions = pd.DataFrame([
        {"Priority": "P0", "Action": "No paper/live", "Reason": "governance rule", "Next Step": "Même une source promue reste research-only."},
        {"Priority": "P0", "Action": "Register only if V5 allowed", "Reason": decision, "Next Step": "V5.0 devient registry / handoff vers tournament, pas moteur."},
        {"Priority": "P1", "Action": "If watch, expand sample", "Reason": f"rule_events={rule_events}, holdout_n={holdout_n}", "Next Step": "Ajouter évènements réels et rerun H/I/J/K."},
    ])

    cards = [
        {"label": "V4.9K promotion", "value": level, "delta": f"{_format_num(score,0)}/100"},
        {"label": "H/I/J", "value": f"{h_dec[:12]} / {i_dec[:12]} / {j_dec[:12]}", "delta": "gates"},
        {"label": "Rule events", "value": str(rule_events), "delta": "min 8"},
        {"label": "Holdout 10B", "value": _format_pct(holdout_avg10), "delta": f"n={holdout_n}"},
        {"label": "Decision", "value": decision, "delta": "registry only"},
    ]

    return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": cards, "summary": summary, "gates": gates, "next_actions": next_actions}


def _external_source_registry_handoff_v50_pack(ctx: dict[str, Any], h_pack: dict[str, Any], i_pack: dict[str, Any], j_pack: dict[str, Any], k_pack: dict[str, Any]) -> dict[str, Any]:
    identity = ctx.get("identity", {})
    rule_row = i_pack.get("rule_row", {})
    k_dec = str(k_pack.get("decision", ""))
    source_family = identity.get("source_family", "N/A")
    source_feature = identity.get("source_feature", "N/A")
    source_id = f"SRC-V50-{_v49x_norm(source_family).upper()}-{_v49x_norm(source_feature).upper()}"

    if k_dec == "PROMOTE_SOURCE_TO_V50_REGISTRY":
        registry_status = "SOURCE_REGISTERED_FOR_TOURNAMENT_TEST"
        level = "V5 registry tournament-ready"
        score = 80.0
        read = "V5.0 enregistre la source pour Strategy Tournament / OOS ultérieur, sans injection moteur automatique."
    elif "WATCH" in k_dec:
        registry_status = "SOURCE_REGISTERED_RESEARCH_ONLY"
        level = "V5 registry research-only"
        score = 55.0
        read = "V5.0 garde la source en registry research-only : sample/holdout à renforcer." 
    else:
        registry_status = "SOURCE_REJECTED_NOT_REGISTERED"
        level = "V5 registry rejected"
        score = 20.0
        read = "V5.0 ne doit pas enregistrer la source comme candidat actif." 

    registry = pd.DataFrame([
        ["source_id", source_id, "Identifiant source stable."],
        ["ticker", ctx.get("ticker", "N/A"), "Ticker audité."],
        ["source_family", source_family, "Famille source externe."],
        ["source_feature", source_feature, "Feature source externe."],
        ["source_rule", rule_row.get("rule", "N/A"), "Règle source-only."],
        ["threshold", rule_row.get("threshold", "N/A"), "Seuil règle."],
        ["direction", rule_row.get("direction", "N/A"), "Direction économique."],
        ["available_at_policy", "mandatory point-in-time", "Timestamp obligatoire."],
        ["decision_policy", "strict t+1 after available_at", "Décision causale."],
        ["benchmark", ctx.get("benchmark_label", "N/A"), "Benchmark actif utilisé."],
        ["h_status", h_pack.get("decision", "N/A"), "Gate sufficiency."],
        ["i_status", i_pack.get("decision", "N/A"), "Gate blueprint."],
        ["j_status", j_pack.get("decision", "N/A"), "Gate holdout."],
        ["k_status", k_pack.get("decision", "N/A"), "Gate promotion."],
        ["registry_status", registry_status, "Statut V5.0."],
        ["handoff_target", "Strategy Tournament / external source lab", "Destination autorisée."],
        ["forbidden_target", "paper/live/direct engine injection", "Interdit à ce stade."],
    ], columns=["Field", "Value", "Read"])

    handoff = pd.DataFrame([
        {"Step": "V5.0-A", "Action": "Store source spec", "Allowed": registry_status != "SOURCE_REJECTED_NOT_REGISTERED", "Read": "Enregistrer source_id, feature, rule, threshold, available_at policy."},
        {"Step": "V5.0-B", "Action": "Generate tournament candidate", "Allowed": registry_status == "SOURCE_REGISTERED_FOR_TOURNAMENT_TEST", "Read": "Créer un candidat de test isolé, sans modifier la stratégie courante."},
        {"Step": "V5.0-C", "Action": "Run OOS/WF later", "Allowed": registry_status == "SOURCE_REGISTERED_FOR_TOURNAMENT_TEST", "Read": "Le vrai OOS reste une étape ultérieure contrôlée."},
        {"Step": "V5.0-D", "Action": "Block paper/live", "Allowed": True, "Read": "Aucune promotion opérationnelle directe."},
    ])

    summary = pd.DataFrame([
        ["V5.0 level", level, "Lecture synthétique registry."],
        ["V5.0 score", score, "Score handoff registry."],
        ["Decision", registry_status, "Décision V5.0."],
        ["Read", read, "Interprétation opérationnelle."],
        ["source_id", source_id, "Identifiant généré."],
        ["handoff", "Strategy Tournament / source lab", "Destination autorisée."],
        ["engine impact", "none", "Aucune modification moteur."],
    ], columns=["Metric", "Value", "Read"])

    cards = [
        {"label": "V5.0 registry", "value": level, "delta": f"{_format_num(score,0)}/100"},
        {"label": "Source ID", "value": source_id, "delta": "registry"},
        {"label": "Status", "value": registry_status, "delta": "research"},
        {"label": "Handoff", "value": "Tournament" if registry_status == "SOURCE_REGISTERED_FOR_TOURNAMENT_TEST" else "Research only", "delta": "no live"},
    ]

    next_actions = pd.DataFrame([
        {"Priority": "P0", "Action": "Do not edit engine", "Reason": registry_status, "Next Step": "V5.0 est registry/handoff, pas injection."},
        {"Priority": "P1", "Action": "Use source_id for future tests", "Reason": source_id, "Next Step": "Tous les tests ultérieurs doivent référencer source_id et rule."},
        {"Priority": "P1", "Action": "Prepare tournament only if allowed", "Reason": registry_status, "Next Step": "Passage à Strategy Tournament seulement si V4.9K promeut."},
    ])

    return {"enabled": True, "level": level, "score": score, "decision": registry_status, "read": read, "cards": cards, "summary": summary, "registry": registry, "handoff": handoff, "next_actions": next_actions, "source_id": source_id}


def _complete_source_validation_v49h_to_v50_pack(
    df: pd.DataFrame | None = None,
    cfg: Any = None,
    external_features: Any = None,
    v49g_pack: Any = None,
    v49g3_pack: Any = None,
    v49f1_pack: Any = None,
    v49f_pack: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    try:
        ctx = _v49x_common_context(df=df, cfg=cfg, external_features=external_features, v49g_pack=v49g_pack, v49g3_pack=v49g3_pack, v49f1_pack=v49f1_pack, v49f_pack=v49f_pack, ticker=ticker)
        h = _source_sufficiency_gate_v49h_pack(ctx)
        i = _causal_source_signal_construction_lab_v49i_pack(ctx, h)
        j = _event_holdout_source_validation_v49j_pack(ctx, h, i)
        k = _source_promotion_governance_gate_v49k_pack(ctx, h, i, j)
        v5 = _external_source_registry_handoff_v50_pack(ctx, h, i, j, k)
        return {"enabled": True, "context": ctx, "v49h": h, "v49i": i, "v49j": j, "v49k": k, "v50": v5, "level": v5.get("level", k.get("level", "N/A")), "score": v5.get("score", k.get("score", 0.0)), "decision": v5.get("decision", k.get("decision", "N/A")), "read": v5.get("read", k.get("read", "")), "top_family": ctx.get("identity", {}).get("source_family", "N/A"), "top_feature": ctx.get("identity", {}).get("source_feature", "N/A"), "top_rule": i.get("rule_row", {}).get("rule", "N/A"), "rule_event_count": h.get("rule_event_count", 0), "source_rows": h.get("source_rows", 0), "source_count": h.get("source_count", 0), "unique_dates": h.get("unique_dates", 0), "full_avg_active_10b": j.get("full_avg_active_10b", np.nan), "oos_avg_active_10b": j.get("holdout_avg_active_10b", np.nan)}
    except Exception as exc:
        err = pd.DataFrame([["V4.9H-V5.0 error", str(exc), "Erreur capturée sans impact moteur."]], columns=["Metric", "Value", "Read"])
        safe = {"enabled": False, "level": "V4.9H-V5.0 error", "score": 0.0, "decision": "V49H_TO_V50_ERROR_SAFE_SKIP", "read": f"Erreur capturée sans impact moteur : {exc}", "summary": err}
        return {"enabled": False, "v49h": safe, "v49i": safe, "v49j": safe, "v49k": safe, "v50": safe, "level": safe["level"], "score": 0.0, "decision": safe["decision"], "read": safe["read"]}


def _v49x_render_pack_section(title: str, caption: str, pack: dict[str, Any], table_keys: list[tuple[str, str, bool]], download_keys: list[tuple[str, str, str]] | None = None) -> None:
    st.subheader(title)
    st.caption(caption)
    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass
    read = str(pack.get("read", ""))
    decision = str(pack.get("decision", ""))
    level = str(pack.get("level", ""))
    if any(tok in decision.lower() for tok in ["reject", "block", "wait", "expand"]) or "blocked" in level.lower():
        st.warning(f"Lecture {title.split(' — ')[0]} : {read}")
    elif any(tok in decision.lower() for tok in ["ready", "validated", "promote", "registered"]):
        st.success(f"Lecture {title.split(' — ')[0]} : {read}")
    else:
        st.info(f"Lecture {title.split(' — ')[0]} : {read}")

    for label, key, expanded in table_keys:
        with st.expander(label, expanded=expanded):
            tab = pack.get(key, pd.DataFrame()) if isinstance(pack, dict) else pd.DataFrame()
            if isinstance(tab, pd.DataFrame) and not tab.empty:
                st.dataframe(_v49x_pct_or_num_display(tab), use_container_width=True, hide_index=True)
            else:
                st.info(f"{label} indisponible.")

    download_keys = download_keys or []
    if download_keys:
        cols = st.columns(min(3, len(download_keys)))
        for col, (label, key, filename) in zip(cols, download_keys):
            tab = pack.get(key, pd.DataFrame()) if isinstance(pack, dict) else pd.DataFrame()
            if isinstance(tab, pd.DataFrame) and not tab.empty:
                col.download_button(label, data=tab.to_csv(index=False).encode("utf-8"), file_name=filename, mime="text/csv", use_container_width=True, key=f"bt_{filename.replace('.', '_')}_download")


