def _v49g_norm(value: Any) -> str:
    try:
        return str(value or "").strip().lower().replace(" ", "_").replace("-", "_")
    except Exception:
        return ""


def _v49g_col(df: pd.DataFrame, candidates: list[str]) -> str | None:
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return None

    lookup = {_v49g_norm(c): c for c in df.columns}

    for candidate in candidates:
        key = _v49g_norm(candidate)
        if key in lookup:
            return lookup[key]

    for candidate in candidates:
        key = _v49g_norm(candidate)
        for norm_col, original in lookup.items():
            if key and (norm_col == key or key in norm_col):
                return original

    return None


def _v49g_parse_number(value: Any, default: float = np.nan) -> float:
    try:
        if value is None or pd.isna(value):
            return default
        txt = str(value).strip().replace(",", ".")
        if txt == "" or txt.upper() in {"N/A", "NA", "NONE", "NAN"}:
            return default
        is_pct = "%" in txt
        txt = txt.replace("%", "").replace("$", "").replace(" ", "")
        out = float(txt)
        return out / 100.0 if is_pct else out
    except Exception:
        return default


def _v49g_collect_dataframes(obj: Any, prefix: str = "root", depth: int = 0) -> list[tuple[str, pd.DataFrame]]:
    """Collect DataFrames recursively from packs/session_state without assuming exact key names."""
    if depth > 5:
        return []

    found: list[tuple[str, pd.DataFrame]] = []

    if isinstance(obj, pd.DataFrame):
        if not obj.empty:
            found.append((prefix, obj.copy()))
        return found

    if isinstance(obj, dict):
        for key, value in obj.items():
            found.extend(_v49g_collect_dataframes(value, f"{prefix}.{key}", depth + 1))
        return found

    if isinstance(obj, (list, tuple)):
        for i, value in enumerate(obj):
            found.extend(_v49g_collect_dataframes(value, f"{prefix}[{i}]", depth + 1))

    return found


def _v49g_normalize_external_features(df: pd.DataFrame, ticker: str = "") -> pd.DataFrame:
    """
    Normalize V4.9A/V4.9B/V4.9B.3 external feature rows into one stable schema.
    Required target schema:
    date, available_at, ticker, feature_family, feature_name, value, source, confidence, notes.
    """
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame()

    work = df.copy()
    work.columns = [str(c).strip() for c in work.columns]

    date_col = _v49g_col(work, ["date", "event_date", "observation_date", "decision_date"])
    available_col = _v49g_col(work, ["available_at", "available", "published_at", "release_time", "asof", "as_of"])
    ticker_col = _v49g_col(work, ["ticker", "symbol", "asset"])
    family_col = _v49g_col(work, ["feature_family", "family", "source_family", "data_family"])
    feature_col = _v49g_col(work, ["feature_name", "feature", "source_feature", "name", "metric"])
    value_col = _v49g_col(work, ["value", "feature_value", "signal_value", "state"])
    source_col = _v49g_col(work, ["source", "provider", "source_tag", "vendor"])
    confidence_col = _v49g_col(work, ["confidence", "quality", "reliability"])
    notes_col = _v49g_col(work, ["notes", "note", "comment", "headline"])

    if feature_col is None or value_col is None:
        return pd.DataFrame()

    out = pd.DataFrame(index=work.index)
    out["date"] = pd.to_datetime(work[date_col], errors="coerce") if date_col else pd.NaT
    out["available_at"] = pd.to_datetime(work[available_col], errors="coerce") if available_col else out["date"]
    out["ticker"] = work[ticker_col].astype(str).str.upper().str.strip() if ticker_col else str(ticker or "").upper().strip()
    out["feature_family"] = work[family_col].astype(str).map(_v49g_norm) if family_col else "external"
    out["feature_name"] = work[feature_col].astype(str).str.strip()
    out["value_raw"] = work[value_col]
    out["value_num"] = work[value_col].map(_v49g_parse_number)
    out["value_text"] = work[value_col].astype(str).str.strip().str.lower()
    out["source"] = work[source_col].astype(str).str.strip() if source_col else "unknown"
    out["confidence"] = work[confidence_col].map(_v49g_parse_number) if confidence_col else np.nan
    out["notes"] = work[notes_col].astype(str).str.strip() if notes_col else ""

    out = out.replace([np.inf, -np.inf], np.nan)
    out = out.dropna(subset=["available_at"])
    out = out[out["feature_name"].astype(str).str.strip() != ""]

    wanted = str(ticker or "").upper().strip()
    if wanted:
        out = out[(out["ticker"].astype(str).str.upper().str.strip() == wanted) | (out["ticker"].astype(str).str.strip() == "")]

    out = out.sort_values(["available_at", "feature_family", "feature_name"]).reset_index(drop=True)
    return out


def _v49g_find_external_features(
    external_features: Any = None,
    v49a_pack: Any = None,
    v49b_pack: Any = None,
    v49b3_pack: Any = None,
    v49b2_pack: Any = None,
    ticker: str = "",
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Find the best audited external feature table from explicit args, packs, or session_state."""
    sources: list[tuple[str, Any]] = [
        ("external_features", external_features),
        ("v49b3_pack", v49b3_pack),
        ("v49b_pack", v49b_pack),
        ("v49a_pack", v49a_pack),
        ("v49b2_pack", v49b2_pack),
    ]

    try:
        if "st" in globals() and hasattr(st, "session_state"):
            for key in list(st.session_state.keys()):
                if any(tok in str(key).lower() for tok in ["v49", "external", "feature", "catalyst"]):
                    sources.append((f"session_state.{key}", st.session_state.get(key)))
    except Exception:
        pass

    candidates: list[dict[str, Any]] = []

    for source_name, obj in sources:
        for path, df in _v49g_collect_dataframes(obj, prefix=source_name):
            norm = _v49g_normalize_external_features(df, ticker=ticker)
            if norm.empty:
                continue

            schema_score = 0
            cols = {_v49g_norm(c) for c in df.columns}
            for token in ["date", "available_at", "ticker", "feature_family", "feature_name", "value", "source", "confidence"]:
                if token in cols:
                    schema_score += 1

            candidates.append(
                {
                    "source_path": path,
                    "rows": int(len(norm)),
                    "families": int(norm["feature_family"].nunique()),
                    "features": int(norm["feature_name"].nunique()),
                    "sources": int(norm["source"].nunique()),
                    "schema_score": schema_score,
                    "table": norm,
                }
            )

    if not candidates:
        return pd.DataFrame(), pd.DataFrame()

    audit = pd.DataFrame([{k: v for k, v in c.items() if k != "table"} for c in candidates])
    audit = audit.sort_values(["schema_score", "rows", "features"], ascending=[False, False, False]).reset_index(drop=True)

    best_path = str(audit.iloc[0]["source_path"])
    best = next(c["table"] for c in candidates if str(c["source_path"]) == best_path)

    return best.copy(), audit


def _v49g_pick_source_identity(v49f1_pack: Any = None, v49f_pack: Any = None) -> dict[str, str]:
    """Extract source_family/source_feature from V4.9F.1 first, then V4.9F fallback."""
    out = {"source_family": "N/A", "source_feature": "N/A"}

    try:
        if isinstance(v49f1_pack, dict):
            fam = str(v49f1_pack.get("top_family", "") or "").strip()
            feat = str(v49f1_pack.get("top_feature", "") or "").strip()
            if fam and fam.upper() not in {"N/A", "NA", "NONE", "NAN"}:
                out["source_family"] = fam
            if feat and feat.upper() not in {"N/A", "NA", "NONE", "NAN"}:
                out["source_feature"] = feat

            bridge = None
            for key in ["source_bridge", "source_identity_bridge"]:
                value = v49f1_pack.get(key)
                if isinstance(value, pd.DataFrame) and not value.empty:
                    bridge = value.copy()
                    break

            if bridge is not None:
                field_col = _v49g_col(bridge, ["Field", "field", "Metric", "metric"])
                value_col = _v49g_col(bridge, ["Value", "value"])
                if field_col and value_col:
                    for _, row in bridge.iterrows():
                        field = _v49g_norm(row.get(field_col))
                        val = str(row.get(value_col, "") or "").strip()
                        if field in {"source_family", "feature_family"} and val:
                            out["source_family"] = val
                        if field in {"source_feature", "feature_name", "top_feature"} and val:
                            out["source_feature"] = val

        if isinstance(v49f_pack, dict):
            if out["source_family"] in {"", "N/A"}:
                out["source_family"] = str(v49f_pack.get("top_family", "N/A"))
            if out["source_feature"] in {"", "N/A"}:
                out["source_feature"] = str(v49f_pack.get("top_feature", "N/A"))

    except Exception:
        pass

    out["source_family"] = _v49g_norm(out.get("source_family", "N/A")) or "N/A"
    out["source_feature"] = str(out.get("source_feature", "N/A") or "N/A").strip()
    return out


def _v49g_trading_position(price_index: pd.Index, ts: Any) -> int | None:
    try:
        if price_index is None or len(price_index) == 0:
            return None
        idx = pd.to_datetime(pd.Index(price_index), errors="coerce")
        target = pd.to_datetime(ts, errors="coerce")
        if pd.isna(target):
            return None
        positions = np.where(idx >= target.normalize())[0]
        if len(positions) == 0:
            return None
        return int(positions[0])
    except Exception:
        return None


def _v49g_build_rule_masks(feature_rows: pd.DataFrame) -> list[dict[str, Any]]:
    """Create source-only review rules from the selected external feature values."""
    if feature_rows is None or not isinstance(feature_rows, pd.DataFrame) or feature_rows.empty:
        return []

    rows = feature_rows.copy()
    nums = pd.to_numeric(rows.get("value_num"), errors="coerce")
    has_num = nums.notna().sum() >= max(3, int(len(rows) * 0.40))

    rules: list[dict[str, Any]] = []

    if has_num:
        clean = nums.dropna()
        q75 = float(clean.quantile(0.75)) if not clean.empty else np.nan
        median = float(clean.median()) if not clean.empty else np.nan

        rules.append(
            {
                "rule_name": "value_top_quartile",
                "threshold": q75,
                "direction": "long_if_value_high",
                "mask": nums >= q75,
                "read": "Long review when selected feature is in its top quartile.",
            }
        )
        rules.append(
            {
                "rule_name": "value_above_median",
                "threshold": median,
                "direction": "long_if_value_above_median",
                "mask": nums >= median,
                "read": "Long review when selected feature is above or equal to its median.",
            }
        )
        rules.append(
            {
                "rule_name": "value_positive",
                "threshold": 0.0,
                "direction": "long_if_value_positive",
                "mask": nums > 0.0,
                "read": "Long review when selected feature is positive.",
            }
        )

        if clean.min() < 0:
            rules.append(
                {
                    "rule_name": "value_bottom_quartile_contrarian",
                    "threshold": float(clean.quantile(0.25)),
                    "direction": "long_if_value_low_contrarian",
                    "mask": nums <= float(clean.quantile(0.25)),
                    "read": "Contrarian review rule for low feature values.",
                }
            )

    text = rows.get("value_text", pd.Series("", index=rows.index)).astype(str).str.lower()
    positive_mask = text.str.contains("positive|bull|beat|up|raise|strong|accel", regex=True, na=False)
    negative_mask = text.str.contains("negative|bear|miss|down|cut|weak|slow", regex=True, na=False)

    if int(positive_mask.sum()) > 0:
        rules.append(
            {
                "rule_name": "text_positive_tag",
                "threshold": "positive tag",
                "direction": "long_if_positive_text",
                "mask": positive_mask,
                "read": "Long review when categorical value contains a positive catalyst tag.",
            }
        )

    if int(negative_mask.sum()) > 0:
        rules.append(
            {
                "rule_name": "text_negative_contrarian",
                "threshold": "negative tag",
                "direction": "long_if_negative_text_contrarian",
                "mask": negative_mask,
                "read": "Contrarian review when categorical value contains a negative catalyst tag.",
            }
        )

    # Deduplicate masks/rule names defensively.
    out = []
    seen = set()
    for rule in rules:
        name = str(rule.get("rule_name"))
        if name in seen:
            continue
        seen.add(name)
        out.append(rule)
    return out


def _v49g_compute_event_returns(
    df: pd.DataFrame,
    cfg: Any,
    events: pd.DataFrame,
    horizons: tuple[int, ...] = (3, 5, 10, 20),
) -> tuple[pd.DataFrame, str, bool]:
    """Compute causal source-only forward active returns from event execution bars."""
    if df is None or not isinstance(df, pd.DataFrame) or df.empty or "close" not in df.columns:
        return pd.DataFrame(), "N/A", True

    close = pd.to_numeric(df["close"], errors="coerce").replace([np.inf, -np.inf], np.nan).ffill()
    close = close.dropna()

    if close.empty or events is None or not isinstance(events, pd.DataFrame) or events.empty:
        return pd.DataFrame(), "N/A", True

    # Use the current benchmark config. If no benchmark is configured, force auto sector/SPY to avoid asset-vs-itself active returns.
    benchmark_label = "Ticker Buy & Hold"
    benchmark_fallback = True
    benchmark_returns = close.pct_change().fillna(0.0)

    try:
        local_cfg = cfg
        if local_cfg is not None and not str(getattr(local_cfg, "benchmark_ticker", "") or "").strip():
            ticker = str(getattr(local_cfg, "asset_ticker", "") or "").upper().strip()
            auto_symbol = _sector_benchmark_guess(ticker) if "_sector_benchmark_guess" in globals() else "SPY"
            if "BacktestConfig" in globals() and hasattr(local_cfg, "__dict__"):
                local_cfg = BacktestConfig(
                    **{
                        **local_cfg.__dict__,
                        "benchmark_ticker": auto_symbol,
                        "benchmark_label": f"Auto Sector ETF ({auto_symbol})",
                        "benchmark_mode": "Sector ETF",
                    }
                )

        if local_cfg is not None and "_load_benchmark_returns" in globals():
            benchmark_returns, benchmark_label, benchmark_fallback = _load_benchmark_returns(df.reindex(close.index), local_cfg)
            benchmark_returns = (
                pd.to_numeric(benchmark_returns.reindex(close.index), errors="coerce")
                .replace([np.inf, -np.inf], np.nan)
                .fillna(0.0)
            )
    except Exception:
        benchmark_returns = close.pct_change().fillna(0.0)
        benchmark_label = "Ticker Buy & Hold — fallback error"
        benchmark_fallback = True

    bench_nav = (1.0 + benchmark_returns).cumprod().replace([np.inf, -np.inf], np.nan).ffill().bfill()
    bench_nav = bench_nav.reindex(close.index).ffill().bfill()

    out_rows: list[dict[str, Any]] = []
    price_index = close.index

    for _, event in events.iterrows():
        available_at = event.get("available_at")
        decision_pos = _v49g_trading_position(price_index, available_at)

        if decision_pos is None:
            continue

        # Strict t+1 source-only review: the event becomes executable on the next bar.
        execution_pos = decision_pos + 1
        if execution_pos >= len(close):
            continue

        base_price = _safe_float(close.iloc[execution_pos], np.nan)
        base_bench = _safe_float(bench_nav.iloc[execution_pos], np.nan)

        if pd.isna(base_price) or base_price <= 0 or pd.isna(base_bench) or base_bench <= 0:
            continue

        row = {
            "event_date": _format_dt(event.get("date")),
            "available_at": str(pd.to_datetime(available_at, errors="coerce")) if pd.notna(pd.to_datetime(available_at, errors="coerce")) else str(available_at),
            "decision_date": _format_dt(price_index[decision_pos]),
            "execution_date_t1": _format_dt(price_index[execution_pos]),
            "ticker": str(event.get("ticker", "")),
            "feature_family": str(event.get("feature_family", "")),
            "feature_name": str(event.get("feature_name", "")),
            "value": event.get("value_raw"),
            "value_num": _safe_float(event.get("value_num"), np.nan),
            "source": str(event.get("source", "")),
            "confidence": _safe_float(event.get("confidence"), np.nan),
            "benchmark_label": benchmark_label,
        }

        for h in horizons:
            end_pos = execution_pos + int(h)
            if end_pos >= len(close):
                row[f"asset_return_{h}b"] = np.nan
                row[f"benchmark_return_{h}b"] = np.nan
                row[f"active_return_{h}b"] = np.nan
                continue

            asset_ret = _safe_float(close.iloc[end_pos] / base_price - 1.0, np.nan)
            bench_ret = _safe_float(bench_nav.iloc[end_pos] / base_bench - 1.0, np.nan)
            row[f"asset_return_{h}b"] = asset_ret
            row[f"benchmark_return_{h}b"] = bench_ret
            row[f"active_return_{h}b"] = asset_ret - bench_ret if pd.notna(asset_ret) and pd.notna(bench_ret) else np.nan

        out_rows.append(row)

    return pd.DataFrame(out_rows).replace([np.inf, -np.inf], np.nan), benchmark_label, bool(benchmark_fallback)


def _source_only_review_runner_v49g_pack(
    df: pd.DataFrame | None = None,
    cfg: Any = None,
    external_features: Any = None,
    v49f1_pack: Any = None,
    v49f_pack: Any = None,
    v49a_pack: Any = None,
    v49b_pack: Any = None,
    v49b2_pack: Any = None,
    v49b3_pack: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    """
    V4.9G — Source-Only Review Runner.

    Read-only micro-runner:
    - consumes the V4.9F.1 source identity and audited external feature rows;
    - builds simple causal t+1 source-only rules;
    - measures forward active returns 3B/5B/10B/20B;
    - does not mutate the main signal, trades, sizing, exits, OOS, equity curve, or verdict.
    """
    empty = {
        "enabled": False,
        "level": "Unavailable",
        "score": 0.0,
        "decision": "V49G_UNAVAILABLE",
        "read": "V4.9G indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "source_identity": pd.DataFrame(),
        "data_audit": pd.DataFrame(),
        "gates": pd.DataFrame(),
        "rule_leaderboard": pd.DataFrame(),
        "event_map": pd.DataFrame(),
        "selected_events": pd.DataFrame(),
        "next_actions": pd.DataFrame(),
    }

    try:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty or "close" not in df.columns:
            out = empty.copy()
            out["level"] = "No price frame"
            out["decision"] = "WAIT_FOR_PRICE_DATA"
            out["read"] = "V4.9G a besoin du price frame courant pour mesurer les forward returns."
            return out

        if cfg is not None and not str(ticker or "").strip():
            ticker = str(getattr(cfg, "asset_ticker", "") or "").upper().strip()

        identity = _v49g_pick_source_identity(v49f1_pack=v49f1_pack, v49f_pack=v49f_pack)
        source_family = _v49g_norm(identity.get("source_family"))
        source_feature = str(identity.get("source_feature", "N/A") or "N/A").strip()

        features, data_audit = _v49g_find_external_features(
            external_features=external_features,
            v49a_pack=v49a_pack,
            v49b_pack=v49b_pack,
            v49b2_pack=v49b2_pack,
            v49b3_pack=v49b3_pack,
            ticker=ticker,
        )

        identity_ok = source_family not in {"", "n/a", "na", "none", "nan"} and source_feature.upper() not in {"", "N/A", "NA", "NONE", "NAN"}
        data_ok = isinstance(features, pd.DataFrame) and not features.empty

        if data_ok and identity_ok:
            selected = features[
                (features["feature_family"].astype(str).map(_v49g_norm) == source_family)
                & (features["feature_name"].astype(str).str.strip() == source_feature)
            ].copy()

            # Defensive fallback for exact feature mismatch: use normalized feature name.
            if selected.empty:
                target_norm = _v49g_norm(source_feature)
                selected = features[
                    (features["feature_family"].astype(str).map(_v49g_norm) == source_family)
                    & (features["feature_name"].astype(str).map(_v49g_norm) == target_norm)
                ].copy()
        else:
            selected = pd.DataFrame()

        rule_rows: list[dict[str, Any]] = []
        event_tables: list[pd.DataFrame] = []
        benchmark_label = "N/A"
        benchmark_fallback = True

        rules = _v49g_build_rule_masks(selected)

        for rule in rules:
            mask = pd.Series(rule.get("mask", False), index=selected.index).fillna(False).astype(bool)
            rule_events = selected.loc[mask].copy()

            event_map, benchmark_label, benchmark_fallback = _v49g_compute_event_returns(
                df=df,
                cfg=cfg,
                events=rule_events,
                horizons=(3, 5, 10, 20),
            )

            if not event_map.empty:
                event_map["rule_name"] = str(rule.get("rule_name"))
                event_map["rule_direction"] = str(rule.get("direction"))
                event_map["rule_threshold"] = str(rule.get("threshold"))
                event_tables.append(event_map)

            sample = int(len(event_map)) if isinstance(event_map, pd.DataFrame) else 0
            total_rows = max(int(len(selected)), 1)
            coverage = sample / total_rows

            def avg(col: str) -> float:
                if event_map is None or event_map.empty or col not in event_map.columns:
                    return np.nan
                s = pd.to_numeric(event_map[col], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
                return float(s.mean()) if not s.empty else np.nan

            def med(col: str) -> float:
                if event_map is None or event_map.empty or col not in event_map.columns:
                    return np.nan
                s = pd.to_numeric(event_map[col], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
                return float(s.median()) if not s.empty else np.nan

            def hit(col: str) -> float:
                if event_map is None or event_map.empty or col not in event_map.columns:
                    return np.nan
                s = pd.to_numeric(event_map[col], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
                return float((s > 0).mean()) if not s.empty else np.nan

            avg3 = avg("active_return_3b")
            avg5 = avg("active_return_5b")
            avg10 = avg("active_return_10b")
            avg20 = avg("active_return_20b")
            med10 = med("active_return_10b")
            med20 = med("active_return_20b")
            hit10 = hit("active_return_10b")
            hit20 = hit("active_return_20b")

            score = 0.0
            if sample > 0:
                score = 45.0
                score += min(sample, 20) * 1.0
                if pd.notna(avg10):
                    score += np.clip(avg10 * 350.0, -20.0, 25.0)
                if pd.notna(avg20):
                    score += np.clip(avg20 * 250.0, -20.0, 20.0)
                if pd.notna(med10) and med10 >= 0:
                    score += 8.0
                if pd.notna(med20) and med20 >= 0:
                    score += 8.0
                if pd.notna(hit10):
                    score += np.clip((hit10 - 0.50) * 35.0, -15.0, 20.0)
                if pd.notna(hit20):
                    score += np.clip((hit20 - 0.50) * 25.0, -10.0, 15.0)
                if bool(benchmark_fallback):
                    score -= 5.0

            score = max(0.0, min(100.0, float(score)))

            if sample < 4:
                decision = "LOW_SAMPLE_REVIEW"
            elif score >= 75 and pd.notna(avg10) and avg10 > 0 and pd.notna(hit10) and hit10 >= 0.50:
                decision = "SOURCE_ONLY_POSITIVE_REVIEW"
            elif score >= 55:
                decision = "SOURCE_ONLY_WATCH_REVIEW"
            else:
                decision = "SOURCE_ONLY_REJECT_REVIEW"

            rule_rows.append(
                {
                    "rule_name": str(rule.get("rule_name")),
                    "rule_direction": str(rule.get("direction")),
                    "threshold": rule.get("threshold"),
                    "sample": sample,
                    "coverage_on_source_rows": coverage,
                    "avg_active_3b": avg3,
                    "avg_active_5b": avg5,
                    "avg_active_10b": avg10,
                    "avg_active_20b": avg20,
                    "median_active_10b": med10,
                    "median_active_20b": med20,
                    "hit_10b": hit10,
                    "hit_20b": hit20,
                    "v49g_review_score": score,
                    "decision": decision,
                    "read": str(rule.get("read")),
                }
            )

        rule_leaderboard = pd.DataFrame(rule_rows)
        if not rule_leaderboard.empty:
            rule_leaderboard = rule_leaderboard.sort_values(
                ["v49g_review_score", "sample", "avg_active_10b"],
                ascending=[False, False, False],
            ).reset_index(drop=True)

        event_map_all = pd.concat(event_tables, ignore_index=True) if event_tables else pd.DataFrame()

        top = rule_leaderboard.iloc[0] if not rule_leaderboard.empty else pd.Series(dtype=object)
        top_rule = str(top.get("rule_name", "N/A")) if not top.empty else "N/A"
        top_score = _safe_float(top.get("v49g_review_score"), 0.0) if not top.empty else 0.0
        top_decision = str(top.get("decision", "NO_RULE")) if not top.empty else "NO_RULE"
        top_sample = int(_safe_float(top.get("sample"), 0)) if not top.empty else 0
        top_avg10 = _safe_float(top.get("avg_active_10b"), np.nan) if not top.empty else np.nan
        top_hit10 = _safe_float(top.get("hit_10b"), np.nan) if not top.empty else np.nan

        gates = pd.DataFrame(
            [
                ["Price frame", "PASS" if df is not None and not df.empty else "FAIL", len(df) if df is not None else 0, "Prix nécessaires pour forward returns."],
                ["Source identity", "PASS" if identity_ok else "FAIL", f"{source_family}:{source_feature}", "Identité héritée de V4.9F.1."],
                ["Audited feature data", "PASS" if data_ok else "FAIL", len(features) if isinstance(features, pd.DataFrame) else 0, "Features externes nettoyées/auditées."],
                ["Selected feature rows", "PASS" if not selected.empty else "FAIL", len(selected), "Lignes disponibles pour la feature candidate exacte."],
                ["Rule generated", "PASS" if len(rules) > 0 else "FAIL", len(rules), "Règles source-only causales générées."],
                ["Event sample", "PASS" if top_sample >= 8 else ("REVIEW" if top_sample >= 4 else "FAIL"), top_sample, "Nombre d'évènements exécutables t+1."],
                ["Mean active 10B", "PASS" if pd.notna(top_avg10) and top_avg10 > 0 else "REVIEW", _format_pct(top_avg10) if pd.notna(top_avg10) else "N/A", "Forward active return moyen 10B."],
                ["Hit 10B", "PASS" if pd.notna(top_hit10) and top_hit10 >= 0.50 else "REVIEW", _format_pct(top_hit10) if pd.notna(top_hit10) else "N/A", "Hit-rate actif 10B."],
                ["No OOS / no promotion", "ENFORCED", "read-only", "V4.9G n'autorise aucune promotion moteur."],
            ],
            columns=["Gate", "Status", "Value", "Read"],
        )

        fail_count = int((gates["Status"].astype(str) == "FAIL").sum())
        review_count = int((gates["Status"].astype(str) == "REVIEW").sum())

        if fail_count > 0:
            level = "Source-only runner blocked"
            decision = "RETURN_TO_V49F1_OR_DATA"
            read = "V4.9G ne peut pas exécuter le runner review-only : source, données ou évènements manquants."
        elif top_decision == "SOURCE_ONLY_POSITIVE_REVIEW":
            level = "Source-only positive review"
            decision = "PREPARE_V49H_SOURCE_STRATEGY_BLUEPRINT"
            read = "V4.9G trouve une règle source-only positive en review. Prochaine étape : blueprint stratégie, toujours sans OOS/promotion."
        elif top_decision in {"SOURCE_ONLY_WATCH_REVIEW", "LOW_SAMPLE_REVIEW"}:
            level = "Source-only watch review"
            decision = "REFINE_SOURCE_ONLY_RULE_BEFORE_V49H"
            read = "V4.9G trouve une lecture exploitable mais encore fragile : affiner seuil/sample avant blueprint supérieur."
        else:
            level = "Source-only rejected review"
            decision = "RETURN_TO_V49E_OR_EXPAND_DATA"
            read = "V4.9G ne confirme pas la source candidate en runner review-only."

        source_identity = pd.DataFrame(
            [
                ["ticker", str(ticker or "N/A"), "Ticker audité."],
                ["source_family", source_family, "Famille héritée de V4.9F.1."],
                ["source_feature", source_feature, "Feature exacte héritée de V4.9F.1."],
                ["selected_rows", str(len(selected)), "Lignes source exactes disponibles."],
                ["top_rule", top_rule, "Meilleure règle source-only testée."],
                ["benchmark", benchmark_label, "Benchmark actif pour active returns."],
                ["benchmark_fallback", str(bool(benchmark_fallback)), "Si True, lecture relative moins fiable."],
            ],
            columns=["Field", "Value", "Read"],
        )

        summary = pd.DataFrame(
            [
                ["V4.9G level", level, "Lecture synthétique du source-only review runner."],
                ["V4.9G score", f"{_format_num(top_score, 0)}/100", "Score de review source-only, pas score live."],
                ["Decision", decision, "Décision research V4.9G."],
                ["Read", read, "Interprétation opérationnelle."],
                ["Ticker", str(ticker or "N/A"), "Ticker audité."],
                ["Source family", source_family, "Famille source testée."],
                ["Source feature", source_feature, "Feature source testée."],
                ["Top rule", top_rule, "Règle source-only la mieux classée."],
                ["Top sample", str(top_sample), "Nombre d'évènements exécutables t+1."],
                ["Top avg active 10B", _format_pct(top_avg10) if pd.notna(top_avg10) else "N/A", "Active return moyen 10B."],
                ["Top hit 10B", _format_pct(top_hit10) if pd.notna(top_hit10) else "N/A", "Hit-rate actif 10B."],
                ["No engine impact", "PASS", "Aucun signal moteur/trade/equity/verdict modifié."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        next_actions = pd.DataFrame(
            [
                ["P0", "Do not OOS", "V4.9G is source-only review", "OOS interdit avant un vrai blueprint source strategy V4.9H."],
                ["P0", "Do not promote", "No engine signal", "Aucune modification du moteur courant."],
                ["P0", "Keep t+1 discipline", "available_at -> next trading bar -> execution t+1", "Pas de same-close lookahead."],
                ["P1", "Review best rule", top_rule, "Analyser event map et stabilité horizon 10B/20B."],
                ["P1", "Prepare V4.9H only if positive", decision, "Blueprint stratégie seulement si source-only positive review."],
                ["P2", "Expand sample if fragile", f"sample={top_sample}", "Ajouter davantage d'évènements réels si sample insuffisant."],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        cards = [
            {"label": "V4.9G runner", "value": level, "delta": f"{_format_num(top_score, 0)}/100"},
            {"label": "Top source", "value": source_feature, "delta": source_family},
            {"label": "Top rule", "value": top_rule, "delta": "source-only"},
            {"label": "Events", "value": str(top_sample), "delta": "t+1"},
            {"label": "Avg active 10B", "value": _format_pct(top_avg10) if pd.notna(top_avg10) else "N/A", "delta": "review"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": top_score,
            "decision": decision,
            "read": read,
            "top_rule": top_rule,
            "top_family": source_family,
            "top_feature": source_feature,
            "top_sample": top_sample,
            "cards": cards,
            "summary": summary,
            "source_identity": source_identity,
            "data_audit": data_audit,
            "gates": gates,
            "rule_leaderboard": rule_leaderboard,
            "event_map": event_map_all,
            "selected_events": selected,
            "next_actions": next_actions,
        }

    except Exception as exc:
        out = empty.copy()
        out["enabled"] = False
        out["level"] = "V4.9G error"
        out["decision"] = "V49G_ERROR_SAFE_SKIP"
        out["read"] = f"Erreur V4.9G capturée sans interrompre le backtest : {exc}"
        out["summary"] = pd.DataFrame(
            [["V4.9G error", str(exc), "Erreur capturée, aucun impact moteur."]],
            columns=["Metric", "Value", "Read"],
        )
        return out


def _v49g_display_percent_table(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame()
    out = df.copy()
    pct_cols = [c for c in out.columns if any(tok in str(c).lower() for tok in ["active_", "hit", "coverage", "return_"])]
    for col in pct_cols:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_pct(x) if pd.notna(_safe_float(x, np.nan)) else "N/A")
    for col in ["v49g_review_score", "score"]:
        if col in out.columns:
            out[col] = out[col].map(lambda x: _format_num(x, 0) if pd.notna(_safe_float(x, np.nan)) else "N/A")
    return out


def _render_source_only_review_runner_v49g(
    df: pd.DataFrame | None = None,
    cfg: Any = None,
    external_features: Any = None,
    v49f1_pack: Any = None,
    v49f_pack: Any = None,
    v49a_pack: Any = None,
    v49b_pack: Any = None,
    v49b2_pack: Any = None,
    v49b3_pack: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    """Streamlit renderer for V4.9G. Read-only source-only review runner."""
    pack = _source_only_review_runner_v49g_pack(
        df=df,
        cfg=cfg,
        external_features=external_features,
        v49f1_pack=v49f1_pack,
        v49f_pack=v49f_pack,
        v49a_pack=v49a_pack,
        v49b_pack=v49b_pack,
        v49b2_pack=v49b2_pack,
        v49b3_pack=v49b3_pack,
        ticker=ticker,
    )

    st.subheader("Source-Only Review Runner V4.9G")
    st.caption(
        "Micro-runner lecture seule après V4.9F.1 : transforme la source externe candidate en règles source-only causales t+1, "
        "mesure les forward active returns 3B/5B/10B/20B et bloque OOS/promotion. "
        "Aucun signal moteur, aucun trade, aucune equity curve, aucun sizing, aucun exit et aucun verdict ne sont modifiés."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", "Unavailable"))
    read = str(pack.get("read", ""))

    if "blocked" in level.lower() or "error" in level.lower() or "rejected" in level.lower():
        st.error(f"Lecture V4.9G : {read}")
    elif "watch" in level.lower() or "fragile" in level.lower():
        st.warning(f"Lecture V4.9G : {read}")
    elif "positive" in level.lower():
        st.success(f"Lecture V4.9G : {read}")
    else:
        st.info(f"Lecture V4.9G : {read}")

    with st.expander("V4.9G source-only runner summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.9G indisponible.")

    with st.expander("V4.9G source identity", expanded=True):
        identity = pack.get("source_identity", pd.DataFrame())
        if isinstance(identity, pd.DataFrame) and not identity.empty:
            st.dataframe(identity, use_container_width=True, hide_index=True)
        else:
            st.info("Identité source V4.9G indisponible.")

    with st.expander("V4.9G runner gates", expanded=True):
        gates = pack.get("gates", pd.DataFrame())
        if isinstance(gates, pd.DataFrame) and not gates.empty:
            st.dataframe(gates, use_container_width=True, hide_index=True)
        else:
            st.info("Gates V4.9G indisponibles.")

    with st.expander("V4.9G source-only rule leaderboard", expanded=True):
        rules = pack.get("rule_leaderboard", pd.DataFrame())
        if isinstance(rules, pd.DataFrame) and not rules.empty:
            st.dataframe(_v49g_display_percent_table(rules), use_container_width=True, hide_index=True)
        else:
            st.info("Aucune règle source-only V4.9G affichable.")

    with st.expander("V4.9G event-level forward active return map", expanded=False):
        event_map = pack.get("event_map", pd.DataFrame())
        if isinstance(event_map, pd.DataFrame) and not event_map.empty:
            st.dataframe(_v49g_display_percent_table(event_map), use_container_width=True, hide_index=True)
        else:
            st.info("Event map V4.9G indisponible.")

    with st.expander("V4.9G selected source rows", expanded=False):
        selected = pack.get("selected_events", pd.DataFrame())
        if isinstance(selected, pd.DataFrame) and not selected.empty:
            st.dataframe(selected, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune ligne source sélectionnée.")

    with st.expander("V4.9G data source audit", expanded=False):
        audit = pack.get("data_audit", pd.DataFrame())
        if isinstance(audit, pd.DataFrame) and not audit.empty:
            st.dataframe(audit, use_container_width=True, hide_index=True)
        else:
            st.info("Audit source data V4.9G indisponible.")

    with st.expander("V4.9G next controlled actions", expanded=True):
        actions = pack.get("next_actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.9G indisponibles.")

    d1, d2, d3 = st.columns(3)
    rules = pack.get("rule_leaderboard", pd.DataFrame())
    event_map = pack.get("event_map", pd.DataFrame())
    selected = pack.get("selected_events", pd.DataFrame())

    if isinstance(rules, pd.DataFrame) and not rules.empty:
        d1.download_button(
            "Télécharger V4.9G rule leaderboard CSV",
            data=rules.to_csv(index=False).encode("utf-8"),
            file_name="v49g_source_only_rule_leaderboard.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g_rule_leaderboard_download",
        )

    if isinstance(event_map, pd.DataFrame) and not event_map.empty:
        d2.download_button(
            "Télécharger V4.9G event map CSV",
            data=event_map.to_csv(index=False).encode("utf-8"),
            file_name="v49g_source_only_event_map.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g_event_map_download",
        )

    if isinstance(selected, pd.DataFrame) and not selected.empty:
        d3.download_button(
            "Télécharger V4.9G selected rows CSV",
            data=selected.to_csv(index=False).encode("utf-8"),
            file_name="v49g_selected_source_rows.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g_selected_rows_download",
        )

    return pack

# ============================================================
# END SOURCE-ONLY REVIEW RUNNER V4.9G
# ============================================================


# ============================================================
# SOURCE SAMPLE EXPANSION / EVENT SUFFICIENCY GATE V4.9G.1
# ============================================================

def _source_sample_expansion_gate_v49g1_pack(
    v49g_pack: Any = None,
    external_features: Any = None,
    v49f1_pack: Any = None,
    ticker: str = "",
    min_events: int = 8,
    preferred_events: int = 15,
) -> dict[str, Any]:
    """
    V4.9G.1 — Source Sample Expansion / Event Sufficiency Gate.

    Lecture seule :
    - contrôle le nombre d'événements source/règle après V4.9G ;
    - contrôle la dispersion des dates et des providers ;
    - prépare le passage V4.9G.2/V4.9G.3/V4.9H ;
    - ne lance aucun OOS, aucun signal moteur et ne modifie ni trades ni verdict.
    """
    def _row(gate: str, required: Any, current: Any, status: str, read: str) -> dict[str, Any]:
        return {
            "Gate": str(gate),
            "Required": str(required),
            "Current": str(current),
            "Status": str(status),
            "Read": str(read),
        }

    def _norm(x: Any) -> str:
        return str(x or "").strip().lower().replace(" ", "_").replace("-", "_")

    def _first_df(*values: Any) -> pd.DataFrame:
        for value in values:
            if isinstance(value, pd.DataFrame) and not value.empty:
                return value.copy()
        return pd.DataFrame()

    empty = {
        "enabled": False,
        "level": "Unavailable",
        "score": 0.0,
        "decision": "V49G1_UNAVAILABLE",
        "read": "V4.9G.1 indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "gates": pd.DataFrame(),
        "expansion_plan": pd.DataFrame(),
        "selected_source_rows": pd.DataFrame(),
        "template_rows": pd.DataFrame(),
        "next_actions": pd.DataFrame(),
        "rule_events": 0,
        "source_rows": 0,
        "source_count": 0,
        "unique_dates": 0,
    }

    try:
        g = v49g_pack if isinstance(v49g_pack, dict) else {}
        f1 = v49f1_pack if isinstance(v49f1_pack, dict) else {}

        top_family = str(
            g.get("top_family")
            or g.get("source_family")
            or f1.get("top_family")
            or ""
        ).strip()
        top_feature = str(
            g.get("top_feature")
            or g.get("source_feature")
            or f1.get("top_feature")
            or ""
        ).strip()
        top_rule = str(g.get("top_rule") or g.get("rule") or "value_positive").strip()

        selected = _first_df(
            g.get("selected_source_rows"),
            g.get("selected_rows"),
            g.get("rule_events"),
            g.get("event_map"),
        )

        if selected.empty:
            selected = _first_df(external_features)

        if not selected.empty and top_feature:
            feature_col = None
            family_col = None
            for c in selected.columns:
                nc = _norm(c)
                if nc in {"feature_name", "feature", "source_feature"}:
                    feature_col = c
                if nc in {"feature_family", "family", "source_family"}:
                    family_col = c
            mask = pd.Series(True, index=selected.index)
            if feature_col is not None:
                mask &= selected[feature_col].astype(str).map(_norm).eq(_norm(top_feature))
            if family_col is not None and top_family:
                mask &= selected[family_col].astype(str).map(_norm).eq(_norm(top_family))
            filtered = selected.loc[mask].copy()
            if not filtered.empty:
                selected = filtered

        if selected.empty:
            pack = empty.copy()
            pack["summary"] = pd.DataFrame(
                [
                    ["V4.9G.1 level", "No source rows", "Aucune ligne source exploitable après V4.9G."],
                    ["Decision", "RETURN_TO_V49G_OR_EXPAND_DATA", "Impossible de préparer V4.9H sans événements source."],
                ],
                columns=["Metric", "Value", "Read"],
            )
            pack["gates"] = pd.DataFrame([
                _row("Source rows", f">= {min_events}", "0", "FAIL", "Aucune ligne source/règle détectée."),
            ])
            pack["cards"] = [
                {"label": "V4.9G.1 gate", "value": "No source rows", "delta": "0/100"},
                {"label": "Events current/min", "value": f"0/{min_events}", "delta": f"missing {min_events}"},
                {"label": "Decision", "value": "RETURN_TO_V49G_OR_EXPAND_DATA", "delta": "research only"},
            ]
            return pack

        df = selected.copy()
        date_col = None
        available_col = None
        source_col = None
        value_col = None

        for c in df.columns:
            nc = _norm(c)
            if nc in {"decision_date", "available_at", "date", "event_date"} and date_col is None:
                date_col = c
            if nc == "available_at":
                available_col = c
            if nc in {"source", "provider", "data_source"} and source_col is None:
                source_col = c
            if nc == "value" and value_col is None:
                value_col = c

        if date_col is not None:
            dates = pd.to_datetime(df[date_col], errors="coerce")
            unique_dates = int(dates.dropna().dt.normalize().nunique())
            first_date = _format_dt(dates.dropna().min()) if dates.notna().any() else "N/A"
            last_date = _format_dt(dates.dropna().max()) if dates.notna().any() else "N/A"
        else:
            dates = pd.Series(pd.NaT, index=df.index)
            unique_dates = 0
            first_date = "N/A"
            last_date = "N/A"

        if available_col is not None:
            available = pd.to_datetime(df[available_col], errors="coerce")
            invalid_available = int(available.isna().sum())
        else:
            invalid_available = int(len(df))

        if source_col is not None:
            source_count = int(df[source_col].astype(str).replace("", np.nan).dropna().nunique())
            source_list = sorted(df[source_col].astype(str).replace("", np.nan).dropna().unique().tolist())[:8]
        else:
            source_count = 0
            source_list = []

        rule_events = int(_safe_float(g.get("top_sample"), 0) or 0)
        if rule_events <= 0:
            rule_events = int(len(df))

        source_rows = int(len(df))
        missing_min = max(0, int(min_events) - rule_events)
        missing_preferred = max(0, int(preferred_events) - rule_events)

        concentration = np.nan
        if date_col is not None and dates.notna().any():
            counts = dates.dt.normalize().value_counts(dropna=True)
            concentration = float(counts.iloc[0] / max(len(df), 1)) if not counts.empty else np.nan

        enough_events = rule_events >= int(min_events)
        enough_sources = source_count >= 2
        clean_available = invalid_available == 0
        enough_dates = unique_dates >= min(int(min_events), max(1, rule_events)) or unique_dates >= 5
        concentration_ok = pd.isna(concentration) or concentration <= 0.50 or source_rows < 20

        gates = pd.DataFrame(
            [
                _row("Rule events", f">= {min_events}", rule_events, "PASS" if enough_events else "FAIL", "Nombre d'événements de la règle source-only sélectionnée."),
                _row("Preferred events", f">= {preferred_events}", rule_events, "PASS" if rule_events >= int(preferred_events) else "WARN", "Niveau préférable avant validation événementielle."),
                _row("Unique dates", ">= diversified", unique_dates, "PASS" if enough_dates else "WARN", "Évite une source concentrée sur quelques dates."),
                _row("Source diversity", ">= 2 providers", source_count, "PASS" if enough_sources else "WARN", "Deux sources/providers réduisent le risque de validation fragile."),
                _row("available_at quality", "0 invalid", invalid_available, "PASS" if clean_available else "FAIL", "Chaque ligne causale doit avoir un timestamp de disponibilité."),
                _row("Date concentration", "<= 50%", _format_pct(concentration) if pd.notna(concentration) else "N/A", "PASS" if concentration_ok else "WARN", "Concentration excessive = sample fragile."),
                _row("No engine impact", "enforced", "PASS", "PASS", "V4.9G.1 ne modifie pas le moteur, les trades ou le verdict."),
            ]
        )

        fail_count = int((gates["Status"] == "FAIL").sum())
        warn_count = int((gates["Status"] == "WARN").sum())

        score = 100.0
        score -= max(0, missing_min) * 8.0
        score -= 0.0 if enough_sources else 12.0
        score -= 0.0 if clean_available else 35.0
        score -= 0.0 if enough_dates else 8.0
        score -= 0.0 if concentration_ok else 6.0
        score = max(0.0, min(100.0, score))

        if fail_count > 0:
            level = "Source sample blocked"
            decision = "EXPAND_SOURCE_SAMPLE_BEFORE_V49G2"
            read = "V4.9G.1 bloque : événements ou timestamps insuffisants avant V4.9H."
        elif enough_events and rule_events >= int(preferred_events) and enough_sources:
            level = "Source sample ready for blueprint"
            decision = "PREPARE_V49H_SOURCE_STRATEGY_BLUEPRINT"
            read = "V4.9G.1 valide le sample minimal/préférable pour préparer V4.9H en lecture seule. Toujours aucun OOS/promotion."
        elif enough_events:
            level = "Source sample minimum ready"
            decision = "PREPARE_V49G2_EXPANSION_OR_V49H_REVIEW"
            read = "V4.9G.1 valide le minimum, mais recommande encore d'enrichir sources/dates avant holdout."
        else:
            level = "Source sample still insufficient"
            decision = "EXPAND_SOURCE_SAMPLE_BEFORE_V49H"
            read = "V4.9G.1 demande plus d'événements source avant V4.9H."

        summary = pd.DataFrame(
            [
                ["V4.9G.1 level", level, "Lecture synthétique du gate d'événements source."],
                ["V4.9G.1 score", f"{_format_num(score, 0)}/100", "Score de suffisance sample, pas score alpha."],
                ["Decision", decision, "Décision research V4.9G.1."],
                ["Read", read, "Interprétation opérationnelle."],
                ["Ticker", str(ticker or "N/A"), "Ticker audité."],
                ["Source family", top_family or "N/A", "Famille source sélectionnée."],
                ["Source feature", top_feature or "N/A", "Feature source sélectionnée."],
                ["Top rule", top_rule or "N/A", "Règle source-only héritée de V4.9G."],
                ["Rule events", str(rule_events), "Événements de la règle."],
                ["Source rows", str(source_rows), "Lignes source filtrées."],
                ["Unique dates", str(unique_dates), "Dates distinctes."],
                ["Sources", str(source_count), "Providers/source tags distincts."],
                ["Source list", ", ".join(source_list) if source_list else "N/A", "Sources observées."],
                ["Available span", f"{first_date} → {last_date}", "Fenêtre des événements source."],
                ["Missing to minimum", str(missing_min), "Lignes/événements à ajouter avant minimum."],
                ["Missing to preferred", str(missing_preferred), "Lignes/événements à ajouter avant niveau préférable."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        expansion_plan = pd.DataFrame(
            [
                ["P0", "Add rule events", rule_events, int(min_events), missing_min, "Augmenter les événements réels avec available_at/source."],
                ["P0", "Add provider diversity", source_count, 2, max(0, 2 - source_count), "Ajouter au moins deux sources/providers distincts si possible."],
                ["P1", "Improve date spread", unique_dates, int(min_events), max(0, int(min_events) - unique_dates), "Éviter une validation sur une seule période."],
                ["P1", "Keep t+1 discipline", "mandatory", "mandatory", 0, "Aucune ligne ne doit contenir outcome/next/future/pnl."],
            ],
            columns=["Priority", "Action", "Current", "Target", "Missing", "Read"],
        )

        template_rows = []
        for i in range(max(0, min(10, missing_min))):
            template_rows.append(
                {
                    "date": "YYYY-MM-DD",
                    "available_at": "YYYY-MM-DD HH:MM:SS",
                    "ticker": str(ticker or "TICKER").upper(),
                    "feature_family": top_family or "earnings",
                    "feature_name": top_feature or "source_feature",
                    "value": "replace_with_real_point_in_time_value",
                    "source": "replace_with_real_provider",
                    "confidence": 0.75,
                    "notes": f"add real event row {i + 1} for V4.9G.1",
                }
            )
        template_df = pd.DataFrame(template_rows)

        next_actions = pd.DataFrame(
            [
                ["P0", "Do not OOS", "source sample gate only", "OOS interdit avant V4.9H/I/J/K/V5."],
                ["P0", "Do not promote", "no holdout validation yet", "Aucune source ne doit modifier le moteur courant."],
                ["P0", "Run V4.9G.2", f"missing_min={missing_min}", "Utiliser le builder pour planifier les lignes manquantes si nécessaire."],
                ["P1", "Run V4.9G.3", "provenance before H", "Valider contamination/source/available_at après enrichissement."],
                ["P1", "Prepare V4.9H only after clean G.3", decision, "H ne doit lire que des données source propres."],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        cards = [
            {"label": "V4.9G.1 gate", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Events current/min", "value": f"{rule_events}/{min_events}", "delta": f"missing {missing_min}"},
            {"label": "Preferred", "value": str(preferred_events), "delta": f"missing {missing_preferred}"},
            {"label": "Unique dates", "value": str(unique_dates), "delta": "event spread"},
            {"label": "Sources", "value": f"{source_count}/2", "delta": "providers"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "gates": gates,
            "expansion_plan": expansion_plan,
            "selected_source_rows": df,
            "template_rows": template_df,
            "next_actions": next_actions,
            "rule_events": rule_events,
            "source_rows": source_rows,
            "source_count": source_count,
            "unique_dates": unique_dates,
            "top_family": top_family,
            "top_feature": top_feature,
            "top_rule": top_rule,
            "fail_count": fail_count,
            "warn_count": warn_count,
        }

    except Exception as exc:
        pack = empty.copy()
        pack["enabled"] = True
        pack["level"] = "V4.9G.1 error"
        pack["score"] = 0.0
        pack["decision"] = "V49G1_ERROR_SAFE_SKIP"
        pack["read"] = f"Erreur V4.9G.1 : {exc}"
        pack["summary"] = pd.DataFrame(
            [["V4.9G.1 error", str(exc), "Erreur capturée sans interrompre le backtest."]],
            columns=["Metric", "Value", "Read"],
        )
        pack["cards"] = [{"label": "V4.9G.1 gate", "value": "Error", "delta": "safe skip"}]
        return pack


def _render_source_sample_expansion_gate_v49g1(
    v49g_pack: Any = None,
    external_features: Any = None,
    v49f1_pack: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    """Streamlit renderer for V4.9G.1. Read-only source sample gate."""
    pack = _source_sample_expansion_gate_v49g1_pack(
        v49g_pack=v49g_pack,
        external_features=external_features,
        v49f1_pack=v49f1_pack,
        ticker=ticker,
    )

    st.subheader("Source Sample Expansion / Event Sufficiency Gate V4.9G.1")
    st.caption(
        "Gate lecture seule après V4.9G : contrôle si la source externe candidate a assez d'évènements "
        "pour préparer V4.9H. Aucun OOS, aucun signal moteur, aucun trade, aucune equity curve, "
        "aucun sizing, aucun exit et aucun verdict ne sont modifiés."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))

    if "blocked" in level.lower() or "insufficient" in level.lower() or "error" in level.lower():
        st.error(f"Lecture V4.9G.1 : {read}")
    elif "minimum" in level.lower() or "warn" in level.lower():
        st.warning(f"Lecture V4.9G.1 : {read}")
    elif "ready" in level.lower():
        st.success(f"Lecture V4.9G.1 : {read}")
    else:
        st.info(f"Lecture V4.9G.1 : {read}")

    with st.expander("V4.9G.1 sample sufficiency summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.9G.1 indisponible.")

    with st.expander("V4.9G.1 event sufficiency gates", expanded=True):
        gates = pack.get("gates", pd.DataFrame())
        if isinstance(gates, pd.DataFrame) and not gates.empty:
            st.dataframe(gates, use_container_width=True, hide_index=True)
        else:
            st.info("Gates V4.9G.1 indisponibles.")

    with st.expander("V4.9G.1 source expansion plan", expanded=True):
        plan = pack.get("expansion_plan", pd.DataFrame())
        if isinstance(plan, pd.DataFrame) and not plan.empty:
            st.dataframe(plan, use_container_width=True, hide_index=True)
        else:
            st.info("Plan d'expansion V4.9G.1 indisponible.")

    with st.expander("V4.9G.1 selected source rows", expanded=False):
        rows = pack.get("selected_source_rows", pd.DataFrame())
        if isinstance(rows, pd.DataFrame) and not rows.empty:
            st.dataframe(rows.tail(200), use_container_width=True, hide_index=True)
        else:
            st.info("Lignes source V4.9G.1 indisponibles.")

    with st.expander("V4.9G.1 CSV rows to add template", expanded=False):
        template = pack.get("template_rows", pd.DataFrame())
        if isinstance(template, pd.DataFrame) and not template.empty:
            st.dataframe(template, use_container_width=True, hide_index=True)
        else:
            st.info("Template V4.9G.1 indisponible ou non nécessaire.")

    with st.expander("V4.9G.1 next controlled actions", expanded=True):
        actions = pack.get("next_actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.9G.1 indisponibles.")

    d1, d2, d3 = st.columns(3)
    plan = pack.get("expansion_plan", pd.DataFrame())
    rows = pack.get("selected_source_rows", pd.DataFrame())
    template = pack.get("template_rows", pd.DataFrame())

    if isinstance(plan, pd.DataFrame) and not plan.empty:
        d1.download_button(
            "Télécharger V4.9G.1 expansion plan CSV",
            data=plan.to_csv(index=False).encode("utf-8"),
            file_name="v49g1_source_sample_expansion_plan.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g1_expansion_plan_download",
        )
    if isinstance(rows, pd.DataFrame) and not rows.empty:
        d2.download_button(
            "Télécharger V4.9G.1 selected source rows CSV",
            data=rows.to_csv(index=False).encode("utf-8"),
            file_name="v49g1_selected_source_rows.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g1_selected_rows_download",
        )
    if isinstance(template, pd.DataFrame) and not template.empty:
        d3.download_button(
            "Télécharger V4.9G.1 rows-to-add template CSV",
            data=template.to_csv(index=False).encode("utf-8"),
            file_name="v49g1_rows_to_add_template.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g1_template_download",
        )

    return pack

# ============================================================
# END SOURCE SAMPLE EXPANSION / EVENT SUFFICIENCY GATE V4.9G.1
# ============================================================


# ============================================================
# SOURCE EVENT EXPANSION BUILDER / REAL SAMPLE WORKBENCH V4.9G.2
# ============================================================

def _source_event_expansion_builder_v49g2_pack(
    v49g1_pack: Any = None,
    v49g_pack: Any = None,
    external_features: Any = None,
    ticker: str = "",
    min_events: int = 8,
    preferred_events: int = 15,
    provider_target: int = 2,
) -> dict[str, Any]:
    """
    V4.9G.2 — Source Event Expansion Builder / Real Sample Augmentation Workbench.

    Lecture seule :
    - part de V4.9G.1 ;
    - transforme le blocage sample en plan de collecte actionnable ;
    - génère des templates CSV ciblés sur la source candidate ;
    - ne lance aucun alpha scan, aucun OOS, aucun signal moteur, aucun trade,
      aucune equity curve, aucun sizing, aucun exit et aucun verdict.
    """
    def _norm(x: Any) -> str:
        try:
            return str(x or "").strip().lower().replace(" ", "_").replace("-", "_")
        except Exception:
            return ""

    def _row(item: str, value: Any, read: str) -> dict[str, Any]:
        return {"Item": str(item), "Value": str(value), "Read": str(read)}

    def _gate(gate: str, required: Any, current: Any, status: str, read: str) -> dict[str, Any]:
        return {
            "Gate": str(gate),
            "Required": str(required),
            "Current": str(current),
            "Status": str(status),
            "Read": str(read),
        }

    def _safe_int(x: Any, default: int = 0) -> int:
        try:
            if x is None or pd.isna(x):
                return default
            return int(float(x))
        except Exception:
            return default

    def _clean_source_frame(df: Any) -> pd.DataFrame:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return pd.DataFrame()

        out = df.copy()
        out.columns = [str(c).strip() for c in out.columns]
        lower = {str(c).lower().strip(): c for c in out.columns}

        rename_map = {}
        aliases = {
            "date": ["date", "event_date", "decision_date", "trading_date"],
            "available_at": ["available_at", "asof", "as_of", "published_at", "release_time", "timestamp"],
            "ticker": ["ticker", "symbol", "asset", "asset_ticker"],
            "feature_family": ["feature_family", "family", "source_family"],
            "feature_name": ["feature_name", "feature", "source_feature", "name"],
            "value": ["value", "feature_value", "signal_value", "raw_value"],
            "source": ["source", "provider", "source_tag", "data_source"],
            "confidence": ["confidence", "reliability", "quality_score"],
            "notes": ["notes", "note", "comment", "headline"],
        }

        for target, names in aliases.items():
            if target in out.columns:
                continue
            for name in names:
                if name in lower:
                    rename_map[lower[name]] = target
                    break

        if rename_map:
            out = out.rename(columns=rename_map)

        for col in ["date", "available_at", "ticker", "feature_family", "feature_name", "value", "source", "confidence", "notes"]:
            if col not in out.columns:
                out[col] = np.nan

        out["date"] = pd.to_datetime(out["date"], errors="coerce")
        out["available_at"] = pd.to_datetime(out["available_at"], errors="coerce")
        out["feature_family"] = out["feature_family"].astype(str).str.strip()
        out["feature_name"] = out["feature_name"].astype(str).str.strip()
        out["ticker"] = out["ticker"].astype(str).str.upper().str.strip()
        out["source"] = out["source"].astype(str).str.strip()
        out["notes"] = out["notes"].astype(str).str.strip()
        out["confidence"] = pd.to_numeric(out["confidence"], errors="coerce")

        return out[["date", "available_at", "ticker", "feature_family", "feature_name", "value", "source", "confidence", "notes"]].copy()

    def _date_text(x: Any) -> str:
        try:
            if x is None or pd.isna(x):
                return "N/A"
            return pd.Timestamp(x).strftime("%Y-%m-%d")
        except Exception:
            return str(x)

    def _datetime_text(x: Any) -> str:
        try:
            if x is None or pd.isna(x):
                return "N/A"
            return pd.Timestamp(x).strftime("%Y-%m-%d %H:%M:%S")
        except Exception:
            return str(x)

    empty = {
        "enabled": False,
        "level": "Unavailable",
        "score": 0.0,
        "decision": "V49G2_UNAVAILABLE",
        "read": "V4.9G.2 indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "gates": pd.DataFrame(),
        "event_gap_plan": pd.DataFrame(),
        "minimum_template": pd.DataFrame(),
        "preferred_template": pd.DataFrame(),
        "provider_plan": pd.DataFrame(),
        "row_quality_protocol": pd.DataFrame(),
        "current_source_rows": pd.DataFrame(),
        "next_actions": pd.DataFrame(),
    }

    try:
        g1 = v49g1_pack if isinstance(v49g1_pack, dict) else {}
        g = v49g_pack if isinstance(v49g_pack, dict) else {}

        top_family = str(g1.get("top_family", g.get("top_family", "")) or "").strip()
        top_feature = str(g1.get("top_feature", g.get("top_feature", "")) or "").strip()
        top_rule = str(g1.get("top_rule", g.get("top_rule", "")) or "").strip()

        current_events = _safe_int(g1.get("current_events", g.get("top_sample", 0)), 0)
        unique_dates_g1 = _safe_int(g1.get("unique_dates", 0), 0)
        source_count_g1 = _safe_int(g1.get("source_count", 0), 0)

        selected = g1.get("selected_source_rows", pd.DataFrame())
        if not isinstance(selected, pd.DataFrame) or selected.empty:
            selected = g.get("selected_events", pd.DataFrame())

        current_rows = _clean_source_frame(selected)

        if current_rows.empty:
            ext = _clean_source_frame(external_features)
            if not ext.empty and top_family and top_feature:
                fam_norm = ext["feature_family"].map(_norm)
                feat_norm = ext["feature_name"].map(_norm)
                current_rows = ext[(fam_norm == _norm(top_family)) & (feat_norm == _norm(top_feature))].copy()
            else:
                current_rows = ext.copy() if isinstance(ext, pd.DataFrame) else pd.DataFrame()

        if not current_rows.empty:
            if not str(ticker or "").strip():
                tickers = current_rows["ticker"].replace("", np.nan).dropna().astype(str).unique().tolist()
                ticker = tickers[0] if tickers else ""

            if not top_family:
                vals = current_rows["feature_family"].replace("", np.nan).dropna().astype(str).unique().tolist()
                top_family = vals[0] if vals else ""

            if not top_feature:
                vals = current_rows["feature_name"].replace("", np.nan).dropna().astype(str).unique().tolist()
                top_feature = vals[0] if vals else ""

        date_series = pd.Series(dtype="datetime64[ns]")
        if not current_rows.empty:
            d1 = pd.to_datetime(current_rows["available_at"], errors="coerce")
            d2 = pd.to_datetime(current_rows["date"], errors="coerce")
            date_series = d1.fillna(d2).dropna()

        if current_events <= 0 and not current_rows.empty:
            current_events = int(len(current_rows))

        unique_dates = unique_dates_g1
        if unique_dates <= 0 and not date_series.empty:
            unique_dates = int(date_series.dt.normalize().nunique())

        source_count = source_count_g1
        if source_count <= 0 and not current_rows.empty and "source" in current_rows.columns:
            source_count = int(current_rows["source"].astype(str).replace("", np.nan).dropna().nunique())

        source_tags = []
        if not current_rows.empty and "source" in current_rows.columns:
            source_tags = sorted([str(x) for x in current_rows["source"].replace("", np.nan).dropna().unique().tolist()])

        first_event = _date_text(date_series.min()) if not date_series.empty else "N/A"
        last_event = _date_text(date_series.max()) if not date_series.empty else "N/A"

        missing_min = max(int(min_events) - int(current_events), 0)
        missing_pref = max(int(preferred_events) - int(current_events), 0)
        missing_providers = max(int(provider_target) - int(source_count), 0)

        has_identity = bool(top_family and top_feature and _norm(top_family) not in {"n/a", "na", "none"} and _norm(top_feature) not in {"n/a", "na", "none"})
        has_existing_rows = bool(current_events > 0 or not current_rows.empty)

        provider_candidates = [
            "provider_earnings_export",
            "company_release_point_in_time_log",
            "manual_point_in_time_log",
            "analyst_revision_provider",
            "options_eod_snapshot_provider",
            "news_catalyst_feed",
        ]

        if _norm(top_family) == "earnings":
            provider_candidates = ["provider_earnings_export", "company_release_point_in_time_log", "manual_point_in_time_log"]
        elif _norm(top_family) in {"revision", "analyst_revisions"}:
            provider_candidates = ["analyst_revision_provider", "provider_estimate_history_export", "manual_point_in_time_log"]
        elif _norm(top_family) == "guidance":
            provider_candidates = ["company_release_point_in_time_log", "transcript_derived_table", "provider_guidance_export"]
        elif _norm(top_family) == "options":
            provider_candidates = ["options_eod_snapshot_provider", "broker_option_export", "iv_provider_export"]
        elif _norm(top_family) == "news":
            provider_candidates = ["news_catalyst_feed", "curated_manual_catalyst_log", "company_release_point_in_time_log"]

        provider_plan = pd.DataFrame(
            [
                {
                    "Priority": "P0" if i < provider_target else "P1",
                    "Provider / source tag": src,
                    "Status": "CURRENT" if src in source_tags else "TO_ADD",
                    "Use case": "source diversity / reproducibility",
                    "Rule": "Chaque ligne doit garder source + available_at.",
                }
                for i, src in enumerate(provider_candidates)
            ]
        )

        if not source_tags:
            current_source_text = "none"
        else:
            current_source_text = ", ".join(source_tags[:6])

        gates = pd.DataFrame(
            [
                _gate("Source identity", "family + feature", f"{top_family or 'N/A'} / {top_feature or 'N/A'}", "PASS" if has_identity else "BLOCK", "La source à enrichir doit être unique et stable."),
                _gate("Current source rows", "> 0", current_events, "PASS" if has_existing_rows else "NOT YET", "Il faut au moins des lignes réelles ou candidates."),
                _gate("Minimum events", f">= {min_events}", current_events, "PASS" if current_events >= min_events else "NOT YET", "Minimum avant V4.9H."),
                _gate("Preferred events", f">= {preferred_events}", current_events, "PASS" if current_events >= preferred_events else "REVIEW", "Niveau préférable avant blueprint."),
                _gate("Unique dates", ">= 4", unique_dates, "PASS" if unique_dates >= 4 else "REVIEW", "Répartition temporelle minimale."),
                _gate("Source diversity", f">= {provider_target}", source_count, "PASS" if source_count >= provider_target else "REVIEW", "Évite une validation portée par un seul provider."),
                _gate("Outcome labels", "forbidden", "future_return/pnl/target_hit blocked", "ENFORCED", "Aucune colonne de résultat futur ne doit servir de feature."),
                _gate("V4.9H permission", "all minimum gates", "blocked" if missing_min > 0 or not has_identity else "review", "BLOCK" if missing_min > 0 or not has_identity else "REVIEW", "V4.9H reste interdit tant que le dataset enrichi n'est pas re-audité."),
            ]
        )

        score = 0.0
        score += 20.0 if has_identity else 0.0
        score += min(current_events / max(int(min_events), 1), 1.0) * 35.0
        score += min(current_events / max(int(preferred_events), 1), 1.0) * 15.0
        score += min(unique_dates / 4.0, 1.0) * 15.0
        score += min(source_count / max(int(provider_target), 1), 1.0) * 15.0
        score = max(0.0, min(100.0, score))

        if not has_identity:
            level = "Expansion builder blocked"
            decision = "RETURN_TO_V49G1_SOURCE_IDENTITY"
            read = "V4.9G.2 bloque : source_family/source_feature indisponibles. Revenir à V4.9G/V4.9G.1."
        elif current_events < min_events:
            level = "Expansion workbench ready"
            decision = "EXPAND_SOURCE_EVENTS_AND_REUPLOAD_V49A"
            read = "V4.9G.2 transforme le blocage sample en template de collecte. Ajouter les évènements réels puis repasser par V4.9A/V4.9B."
        elif source_count < provider_target:
            level = "Sample met / provider review"
            decision = "ADD_PROVIDER_DIVERSITY_THEN_REAUDIT"
            read = "Le minimum d'évènements est atteint, mais la provenance reste fragile. Ajouter au moins une source/provider distincte."
        else:
            level = "Expansion gates met"
            decision = "READY_FOR_V49H_AFTER_REAUDIT"
            read = "Le dataset semble assez dense pour préparer V4.9H, uniquement après re-audit V4.9A→V4.9G.1 propre."

        if not date_series.empty and pd.notna(date_series.max()):
            start_date = pd.Timestamp(date_series.max()).normalize() + pd.Timedelta(days=21)
        else:
            start_date = pd.Timestamp.today().normalize()

        min_rows = max(missing_min, 0)
        pref_rows = max(missing_pref, min_rows)

        def _make_template(n: int, mode: str) -> pd.DataFrame:
            rows = []
            for i in range(int(n)):
                dt = start_date + pd.Timedelta(days=21 * i)
                provider = provider_candidates[i % max(len(provider_candidates), 1)]
                if source_tags and i % 2 == 0:
                    provider = source_tags[0]
                rows.append(
                    {
                        "date": dt.strftime("%Y-%m-%d"),
                        "available_at": f"{dt.strftime('%Y-%m-%d')} 21:30:00",
                        "ticker": str(ticker or "TICKER").upper().strip(),
                        "feature_family": top_family,
                        "feature_name": top_feature,
                        "value": "REPLACE_WITH_REAL_POINT_IN_TIME_VALUE",
                        "source": provider,
                        "confidence": 0.75,
                        "notes": f"{mode} expansion row {i + 1} — replace with real source event",
                    }
                )
            return pd.DataFrame(rows)

        minimum_template = _make_template(max(min_rows, 1 if missing_min > 0 else 0), "minimum")
        preferred_template = _make_template(max(pref_rows, 1 if missing_pref > 0 else 0), "preferred")

        event_gap_rows = []
        for i in range(max(missing_min, 0)):
            dt = start_date + pd.Timedelta(days=21 * i)
            event_gap_rows.append(
                {
                    "Priority": "P0",
                    "Missing event #": i + 1,
                    "Target date placeholder": dt.strftime("%Y-%m-%d"),
                    "Source family": top_family,
                    "Source feature": top_feature,
                    "Required value": "real numeric/string value, point-in-time",
                    "Required available_at": "first tradable timestamp",
                    "Required source": provider_candidates[i % max(len(provider_candidates), 1)],
                    "Read": "Remplacer la ligne placeholder par un vrai évènement observable à cette date ou proche.",
                }
            )

        event_gap_plan = pd.DataFrame(event_gap_rows)
        if event_gap_plan.empty:
            event_gap_plan = pd.DataFrame(
                [
                    {
                        "Priority": "P1",
                        "Missing event #": 0,
                        "Target date placeholder": "N/A",
                        "Source family": top_family,
                        "Source feature": top_feature,
                        "Required value": "sample minimum already met",
                        "Required available_at": "keep mandatory",
                        "Required source": "add provider diversity if needed",
                        "Read": "Aucun évènement minimum manquant ; contrôler surtout la provenance et le re-audit.",
                    }
                ]
            )

        row_quality_protocol = pd.DataFrame(
            [
                ["available_at mandatory", "Every row", "BLOCK if missing", "Timestamp de première disponibilité tradable."],
                ["source mandatory", "Every row", "BLOCK/REVIEW if missing", "Provider ou log manuel stable et auditable."],
                ["no template source", "source", "BLOCK if replace_with/template/manual_example", "Les lignes exemple ne valident pas un edge."],
                ["no outcome labels", "columns", "BLOCK", "Interdit : future_return, pnl, target_hit, realized_alpha, next_close."],
                ["stable feature taxonomy", "feature_name", "REVIEW", "Ne pas changer revenue_surprise_pct en variantes libres non comparables."],
                ["event_date vs available_at", "date/available_at", "REVIEW", "Si publication after-close, utiliser available_at au prochain timestamp tradable."],
                ["re-upload through V4.9A", "workflow", "MANDATORY", "L'adapter reste la source de vérité du pipeline."],
            ],
            columns=["Rule", "Object", "Status", "Read"],
        )

        next_actions = pd.DataFrame(
            [
                ["P0", "Do not run V4.9H yet", f"Events={current_events}/{min_events}", "V4.9H interdit tant que V4.9G.1 ne repasse pas proprement."],
                ["P0", "Fill minimum source template", f"missing_min={missing_min}", "Ajouter les vraies lignes de source candidate, pas des lignes template."],
                ["P0", "Keep point-in-time discipline", "leakage risk", "Chaque ligne doit avoir available_at, source, confidence et aucune colonne outcome."],
                ["P0", "Re-upload through V4.9A", "adapter is source of truth", "Toute table enrichie doit repasser par V4.9A avant V4.9B/G."],
                ["P1", "Re-run V4.9B/V4.9B.3", "quality/provenance", "Vérifier missingness, sources, contamination template et timestamps."],
                ["P1", "Re-run V4.9G/V4.9G.1", "source-only sample", "V4.9H seulement si sample/provenance passent après enrichissement."],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        summary = pd.DataFrame(
            [
                _row("V4.9G.2 level", level, "Lecture synthétique du workbench d'expansion sample."),
                _row("V4.9G.2 score", f"{_format_num(score, 0)}/100", "Score de préparation dataset, pas score alpha."),
                _row("Decision", decision, "Décision research V4.9G.2."),
                _row("Read", read, "Interprétation opérationnelle."),
                _row("Ticker", str(ticker or "N/A").upper(), "Ticker cible."),
                _row("Source family", top_family or "N/A", "Famille source candidate."),
                _row("Source feature", top_feature or "N/A", "Feature source candidate."),
                _row("Top rule", top_rule or "N/A", "Règle source-only héritée de V4.9G."),
                _row("Current events", current_events, "Évènements utilisables actuellement."),
                _row("Missing to minimum", missing_min, "Nombre de vrais évènements à ajouter avant V4.9H."),
                _row("Missing to preferred", missing_pref, "Nombre à ajouter pour un sample plus confortable."),
                _row("Unique dates", unique_dates, "Répartition temporelle."),
                _row("Source count", source_count, "Nombre de providers/sources distincts."),
                _row("Current source tags", current_source_text, "Sources observées."),
                _row("First event", first_event, "Premier évènement disponible."),
                _row("Last event", last_event, "Dernier évènement disponible."),
            ]
        )

        cards = [
            {"label": "V4.9G.2 builder", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Events", "value": f"{current_events}/{min_events}", "delta": f"missing {missing_min}"},
            {"label": "Preferred", "value": str(preferred_events), "delta": f"missing {missing_pref}"},
            {"label": "Feature", "value": top_feature or "N/A", "delta": top_family or "source"},
            {"label": "Sources", "value": str(source_count), "delta": f"missing {missing_providers}"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "gates": gates,
            "event_gap_plan": event_gap_plan,
            "minimum_template": minimum_template,
            "preferred_template": preferred_template,
            "provider_plan": provider_plan,
            "row_quality_protocol": row_quality_protocol,
            "current_source_rows": current_rows,
            "next_actions": next_actions,
            "top_family": top_family,
            "top_feature": top_feature,
            "top_rule": top_rule,
            "current_events": current_events,
            "missing_min": missing_min,
            "missing_pref": missing_pref,
            "source_count": source_count,
            "unique_dates": unique_dates,
        }

    except Exception as exc:
        out = empty.copy()
        out["enabled"] = False
        out["level"] = "V4.9G.2 error"
        out["decision"] = "V49G2_ERROR_SAFE_SKIP"
        out["read"] = f"Erreur V4.9G.2 capturée sans interrompre le backtest : {exc}"
        out["summary"] = pd.DataFrame(
            [["V4.9G.2 error", str(exc), "Erreur capturée, aucun impact moteur."]],
            columns=["Metric", "Value", "Read"],
        )
        return out


def _render_source_event_expansion_builder_v49g2(
    v49g1_pack: Any = None,
    v49g_pack: Any = None,
    external_features: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    """Streamlit renderer for V4.9G.2. Read-only source event expansion workbench."""
    pack = _source_event_expansion_builder_v49g2_pack(
        v49g1_pack=v49g1_pack,
        v49g_pack=v49g_pack,
        external_features=external_features,
        ticker=ticker,
    )

    st.subheader("Source Event Expansion Builder / Real Sample Augmentation Workbench V4.9G.2")
    st.caption(
        "Workbench lecture seule après V4.9G.1 : transforme le sample insuffisant en plan de collecte, "
        "templates CSV ciblés, protocole provider et gates avant V4.9H. Aucun alpha scan, aucun OOS, "
        "aucun signal moteur, aucun trade, aucune equity curve, aucun sizing, aucun exit et aucun verdict ne sont modifiés."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", "Unavailable"))
    read = str(pack.get("read", ""))

    if "blocked" in level.lower() or "error" in level.lower():
        st.error(f"Lecture V4.9G.2 : {read}")
    elif "ready" in level.lower() or "met" in level.lower():
        st.success(f"Lecture V4.9G.2 : {read}")
    else:
        st.warning(f"Lecture V4.9G.2 : {read}")

    with st.expander("V4.9G.2 expansion builder summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.9G.2 indisponible.")

    with st.expander("V4.9G.2 gates before V4.9H", expanded=True):
        gates = pack.get("gates", pd.DataFrame())
        if isinstance(gates, pd.DataFrame) and not gates.empty:
            st.dataframe(gates, use_container_width=True, hide_index=True)
        else:
            st.info("Gates V4.9G.2 indisponibles.")

    with st.expander("V4.9G.2 event gap plan", expanded=True):
        event_gap_plan = pack.get("event_gap_plan", pd.DataFrame())
        if isinstance(event_gap_plan, pd.DataFrame) and not event_gap_plan.empty:
            st.dataframe(event_gap_plan, use_container_width=True, hide_index=True)
        else:
            st.info("Plan de gaps évènements V4.9G.2 indisponible.")

    with st.expander("V4.9G.2 minimum CSV template to fill", expanded=True):
        minimum_template = pack.get("minimum_template", pd.DataFrame())
        if isinstance(minimum_template, pd.DataFrame) and not minimum_template.empty:
            st.dataframe(minimum_template, use_container_width=True, hide_index=True)
        else:
            st.info("Template minimum V4.9G.2 indisponible ou non nécessaire.")

    with st.expander("V4.9G.2 preferred CSV template", expanded=False):
        preferred_template = pack.get("preferred_template", pd.DataFrame())
        if isinstance(preferred_template, pd.DataFrame) and not preferred_template.empty:
            st.dataframe(preferred_template, use_container_width=True, hide_index=True)
        else:
            st.info("Template preferred V4.9G.2 indisponible ou non nécessaire.")

    with st.expander("V4.9G.2 provider / source plan", expanded=True):
        provider_plan = pack.get("provider_plan", pd.DataFrame())
        if isinstance(provider_plan, pd.DataFrame) and not provider_plan.empty:
            st.dataframe(provider_plan, use_container_width=True, hide_index=True)
        else:
            st.info("Plan provider V4.9G.2 indisponible.")

    with st.expander("V4.9G.2 row quality / anti-leakage protocol", expanded=False):
        protocol = pack.get("row_quality_protocol", pd.DataFrame())
        if isinstance(protocol, pd.DataFrame) and not protocol.empty:
            st.dataframe(protocol, use_container_width=True, hide_index=True)
        else:
            st.info("Protocole qualité V4.9G.2 indisponible.")

    with st.expander("V4.9G.2 current selected source rows", expanded=False):
        current_rows = pack.get("current_source_rows", pd.DataFrame())
        if isinstance(current_rows, pd.DataFrame) and not current_rows.empty:
            st.dataframe(current_rows, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune ligne source courante affichable pour V4.9G.2.")

    with st.expander("V4.9G.2 next controlled actions", expanded=True):
        actions = pack.get("next_actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.9G.2 indisponibles.")

    d1, d2, d3, d4 = st.columns(4)

    minimum_template = pack.get("minimum_template", pd.DataFrame())
    preferred_template = pack.get("preferred_template", pd.DataFrame())
    provider_plan = pack.get("provider_plan", pd.DataFrame())
    current_rows = pack.get("current_source_rows", pd.DataFrame())

    if isinstance(minimum_template, pd.DataFrame) and not minimum_template.empty:
        d1.download_button(
            "Télécharger V4.9G.2 minimum template CSV",
            data=minimum_template.to_csv(index=False).encode("utf-8"),
            file_name="v49g2_minimum_source_events_template.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g2_minimum_template_download",
        )

    if isinstance(preferred_template, pd.DataFrame) and not preferred_template.empty:
        d2.download_button(
            "Télécharger V4.9G.2 preferred template CSV",
            data=preferred_template.to_csv(index=False).encode("utf-8"),
            file_name="v49g2_preferred_source_events_template.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g2_preferred_template_download",
        )

    if isinstance(provider_plan, pd.DataFrame) and not provider_plan.empty:
        d3.download_button(
            "Télécharger V4.9G.2 provider plan CSV",
            data=provider_plan.to_csv(index=False).encode("utf-8"),
            file_name="v49g2_provider_plan.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g2_provider_plan_download",
        )

    if isinstance(current_rows, pd.DataFrame) and not current_rows.empty:
        d4.download_button(
            "Télécharger V4.9G.2 current source rows CSV",
            data=current_rows.to_csv(index=False).encode("utf-8"),
            file_name="v49g2_current_source_rows.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g2_current_source_rows_download",
        )

    return pack

# ============================================================
# END SOURCE EVENT EXPANSION BUILDER / REAL SAMPLE WORKBENCH V4.9G.2
# ============================================================


# ============================================================
# SOURCE EVENT COLLECTION CONTROL / REUPLOAD VALIDATOR V4.9G.3
# ============================================================

def _source_event_reupload_validator_v49g3_pack(
    v49g2_pack: Any = None,
    v49g1_pack: Any = None,
    v49g_pack: Any = None,
    external_features: Any = None,
    ticker: str = "",
    min_rule_events: int = 8,
    preferred_rule_events: int = 15,
    min_source_rows: int = 8,
    provider_target: int = 2,
) -> dict[str, Any]:
    """
    V4.9G.3 — Source Event Collection Control / Reupload Validator.

    Lecture seule :
    - contrôle le CSV enrichi après V4.9G.2 ;
    - vérifie que la source candidate exacte a assez d'évènements réels ;
    - détecte placeholders/template rows, colonnes outcome/leakage, available_at manquant,
      concentration date/source et faiblesse provider ;
    - ne lance aucun alpha scan, aucun OOS, aucun signal moteur, aucun trade,
      aucune equity curve, aucun sizing, aucun exit et aucun verdict.
    """
    def _norm(x: Any) -> str:
        try:
            return str(x or "").strip().lower().replace(" ", "_").replace("-", "_")
        except Exception:
            return ""

    def _row(metric: str, value: Any, read: str) -> dict[str, Any]:
        return {"Metric": str(metric), "Value": str(value), "Read": str(read)}

    def _gate(check: str, status: str, severity: str, value: Any, read: str) -> dict[str, Any]:
        return {
            "Check": str(check),
            "Status": str(status),
            "Severity": str(severity),
            "Value": str(value),
            "Read": str(read),
        }

    def _safe_int(x: Any, default: int = 0) -> int:
        try:
            if x is None or pd.isna(x):
                return default
            return int(float(x))
        except Exception:
            return default

    def _first_non_empty(*values: Any) -> str:
        for value in values:
            txt = str(value or "").strip()
            if txt and txt.upper() not in {"N/A", "NA", "NONE", "NAN", "NULL"}:
                return txt
        return ""

    def _clean_features(df: Any) -> pd.DataFrame:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return pd.DataFrame()

        out = df.copy()
        out.columns = [str(c).strip() for c in out.columns]
        lower = {str(c).lower().strip(): c for c in out.columns}

        aliases = {
            "date": ["date", "event_date", "decision_date", "trading_date"],
            "available_at": ["available_at", "asof", "as_of", "published_at", "release_time", "timestamp"],
            "ticker": ["ticker", "symbol", "asset", "asset_ticker"],
            "feature_family": ["feature_family", "family", "source_family"],
            "feature_name": ["feature_name", "feature", "source_feature", "name"],
            "value": ["value", "feature_value", "signal_value", "raw_value"],
            "source": ["source", "provider", "source_tag", "data_source"],
            "confidence": ["confidence", "reliability", "quality_score"],
            "notes": ["notes", "note", "comment", "headline"],
        }

        rename_map = {}
        for target, names in aliases.items():
            if target in out.columns:
                continue
            for name in names:
                if name in lower:
                    rename_map[lower[name]] = target
                    break

        if rename_map:
            out = out.rename(columns=rename_map)

        for col in ["date", "available_at", "ticker", "feature_family", "feature_name", "value", "source", "confidence", "notes"]:
            if col not in out.columns:
                out[col] = np.nan

        out["date"] = pd.to_datetime(out["date"], errors="coerce")
        out["available_at"] = pd.to_datetime(out["available_at"], errors="coerce")
        out["ticker"] = out["ticker"].astype(str).str.strip().str.upper()
        out["feature_family"] = out["feature_family"].astype(str).str.strip()
        out["feature_name"] = out["feature_name"].astype(str).str.strip()
        out["source"] = out["source"].astype(str).str.strip()
        out["notes"] = out["notes"].astype(str).str.strip()
        out["confidence"] = pd.to_numeric(out["confidence"], errors="coerce")

        return out.replace([np.inf, -np.inf], np.nan)

    def _target_rule_events(selected: pd.DataFrame, top_rule: str, v49g_pack_obj: dict[str, Any]) -> pd.DataFrame:
        if selected is None or not isinstance(selected, pd.DataFrame) or selected.empty:
            return pd.DataFrame()

        rule_txt = _norm(top_rule)

        event_map = v49g_pack_obj.get("event_map", pd.DataFrame()) if isinstance(v49g_pack_obj, dict) else pd.DataFrame()
        if isinstance(event_map, pd.DataFrame) and not event_map.empty:
            em = event_map.copy()
            if "rule_name" in em.columns and top_rule:
                em = em[em["rule_name"].astype(str).map(_norm) == rule_txt].copy()
            if not em.empty:
                return em

        out = selected.copy()
        values = pd.to_numeric(out.get("value"), errors="coerce")

        if values.notna().sum() <= 0:
            return pd.DataFrame()

        if "top_quartile" in rule_txt or "q75" in rule_txt:
            threshold = float(values.quantile(0.75))
            out = out[values >= threshold].copy()
        elif "bottom_quartile" in rule_txt or "q25" in rule_txt:
            threshold = float(values.quantile(0.25))
            out = out[values <= threshold].copy()
        elif "positive" in rule_txt or "non_negative" in rule_txt:
            out = out[values >= 0].copy()
        elif "negative" in rule_txt:
            out = out[values < 0].copy()
        else:
            threshold = float(values.quantile(0.75))
            out = out[values >= threshold].copy()

        return out

    empty = {
        "enabled": False,
        "level": "Unavailable",
        "score": 0.0,
        "decision": "V49G3_UNAVAILABLE",
        "read": "V4.9G.3 indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "gates": pd.DataFrame(),
        "source_quality": pd.DataFrame(),
        "rule_event_sample": pd.DataFrame(),
        "selected_source_rows": pd.DataFrame(),
        "contaminated_rows": pd.DataFrame(),
        "next_actions": pd.DataFrame(),
    }

    try:
        g2 = v49g2_pack if isinstance(v49g2_pack, dict) else {}
        g1 = v49g1_pack if isinstance(v49g1_pack, dict) else {}
        g = v49g_pack if isinstance(v49g_pack, dict) else {}

        top_family = _first_non_empty(g2.get("top_family"), g1.get("top_family"), g.get("top_family"))
        top_feature = _first_non_empty(g2.get("top_feature"), g1.get("top_feature"), g.get("top_feature"))
        top_rule = _first_non_empty(g2.get("top_rule"), g1.get("top_rule"), g.get("top_rule"), "value_top_quartile")

        clean = _clean_features(external_features)

        target_ticker = str(ticker or "").upper().strip()
        if target_ticker and isinstance(clean, pd.DataFrame) and not clean.empty and "ticker" in clean.columns:
            ticker_filtered = clean[clean["ticker"].astype(str).str.upper().str.strip() == target_ticker].copy()
            if not ticker_filtered.empty:
                clean = ticker_filtered

        identity_ok = bool(top_family and top_feature)
        data_ok = isinstance(clean, pd.DataFrame) and not clean.empty

        if data_ok and identity_ok:
            family_norm = _norm(top_family)
            feature_norm = _norm(top_feature)
            selected = clean[
                (clean["feature_family"].astype(str).map(_norm) == family_norm)
                & (clean["feature_name"].astype(str).map(_norm) == feature_norm)
            ].copy()
        else:
            selected = pd.DataFrame()

        rule_events = _target_rule_events(selected, top_rule, g)

        source_rows = int(len(selected)) if isinstance(selected, pd.DataFrame) else 0
        rule_event_count = int(len(rule_events)) if isinstance(rule_events, pd.DataFrame) else 0

        if rule_event_count <= 0:
            rule_event_count = _safe_int(g.get("top_sample", g1.get("current_events", 0)), 0)

        date_source = rule_events if isinstance(rule_events, pd.DataFrame) and not rule_events.empty else selected
        if isinstance(date_source, pd.DataFrame) and not date_source.empty:
            date_col = "decision_date" if "decision_date" in date_source.columns else "available_at" if "available_at" in date_source.columns else "date"
            date_series = pd.to_datetime(date_source.get(date_col), errors="coerce").dropna()
        else:
            date_col = "date"
            date_series = pd.Series(dtype="datetime64[ns]")

        unique_dates = int(date_series.dt.normalize().nunique()) if not date_series.empty else 0
        first_event = _format_dt(date_series.min()) if not date_series.empty else "N/A"
        last_event = _format_dt(date_series.max()) if not date_series.empty else "N/A"
        max_date_concentration = 0.0
        if not date_series.empty:
            date_counts = date_series.dt.normalize().value_counts()
            max_date_concentration = float(date_counts.max() / max(len(date_series), 1))

        if isinstance(selected, pd.DataFrame) and not selected.empty and "source" in selected.columns:
            source_clean = selected["source"].astype(str).str.strip()
            source_clean = source_clean.replace({"": np.nan, "nan": np.nan, "None": np.nan})
            source_count = int(source_clean.dropna().nunique())
            source_text = ", ".join(sorted(source_clean.dropna().astype(str).unique().tolist())[:8]) or "N/A"
        else:
            source_count = 0
            source_text = "N/A"

        contamination_tokens = [
            "replace_with", "template", "placeholder", "provider_or_manual", "manual_example",
            "example", "dummy", "sample", "to_fill", "fill_me", "fake", "test_row",
        ]
        forbidden_columns = []
        forbidden_tokens = [
            "future_return", "forward_return", "next_return", "return_fwd", "return_next",
            "realized_alpha", "realized_return", "target_hit", "hit_target", "pnl",
            "profit", "outcome", "next_close", "future_close", "label_y", "target_y",
        ]

        if isinstance(clean, pd.DataFrame) and not clean.empty:
            for col in clean.columns:
                col_norm = _norm(col)
                if any(tok in col_norm for tok in forbidden_tokens):
                    forbidden_columns.append(str(col))

        if isinstance(selected, pd.DataFrame) and not selected.empty:
            text_cols = []
            for col in ["source", "notes", "value"]:
                if col in selected.columns:
                    text_cols.append(selected[col].astype(str).fillna(""))
            if text_cols:
                row_text = text_cols[0]
                for s in text_cols[1:]:
                    row_text = row_text + " " + s
                contam_mask = row_text.astype(str).map(_norm).apply(
                    lambda x: any(tok in x for tok in contamination_tokens)
                )
                contaminated_rows = selected.loc[contam_mask].copy()
            else:
                contaminated_rows = pd.DataFrame()
        else:
            contaminated_rows = pd.DataFrame()

        contaminated_count = int(len(contaminated_rows)) if isinstance(contaminated_rows, pd.DataFrame) else 0
        contamination_share = contaminated_count / max(source_rows, 1)

        available_invalid = 0
        event_date_invalid = 0
        future_availability_rows = 0
        value_missing = 0
        value_missing_rate = 1.0
        duplicate_keys = 0
        numeric_share = np.nan
        confidence_mean = np.nan

        if isinstance(selected, pd.DataFrame) and not selected.empty:
            available = pd.to_datetime(selected.get("available_at"), errors="coerce")
            event_dates = pd.to_datetime(selected.get("date"), errors="coerce")
            available_invalid = int(available.isna().sum())
            event_date_invalid = int(event_dates.isna().sum())
            future_availability_rows = int((available.dt.normalize() < event_dates.dt.normalize()).fillna(False).sum())

            value_series = selected.get("value")
            value_missing = int(pd.Series(value_series).isna().sum())
            value_missing_rate = value_missing / max(source_rows, 1)

            numeric_values = pd.to_numeric(value_series, errors="coerce")
            numeric_share = float(numeric_values.notna().mean()) if len(numeric_values) else np.nan

            conf = pd.to_numeric(selected.get("confidence"), errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
            confidence_mean = float(conf.mean()) if not conf.empty else np.nan

            key_cols = [c for c in ["date", "available_at", "ticker", "feature_family", "feature_name", "source"] if c in selected.columns]
            duplicate_keys = int(selected.duplicated(subset=key_cols).sum()) if key_cols else 0

        feature_norm = _norm(top_feature)
        numeric_required = not any(tok in feature_norm for tok in ["tag", "headline", "news", "sentiment", "category", "state"])

        gates = pd.DataFrame(
            [
                _gate("Source identity", "PASS" if identity_ok else "BLOCK", "Critical" if not identity_ok else "None", f"{top_family or 'N/A'} / {top_feature or 'N/A'}", "Famille/feature candidate héritée de V4.9G.2/V4.9G."),
                _gate("External feature table", "PASS" if data_ok else "BLOCK", "Critical" if not data_ok else "None", len(clean) if isinstance(clean, pd.DataFrame) else 0, "Table externe chargée via V4.9A/V4.9B."),
                _gate("Selected source rows", "PASS" if source_rows >= min_source_rows else "NOT YET", "High" if source_rows < min_source_rows else "None", f"{source_rows}/{min_source_rows}", "Lignes disponibles pour la source candidate exacte."),
                _gate("Rule event sample", "PASS" if rule_event_count >= min_rule_events else "NOT YET", "High" if rule_event_count < min_rule_events else "None", f"{rule_event_count}/{min_rule_events}", "Évènements réellement exploitables pour la règle source-only."),
                _gate("Preferred rule events", "PASS" if rule_event_count >= preferred_rule_events else "REVIEW", "Low" if rule_event_count < preferred_rule_events else "None", f"{rule_event_count}/{preferred_rule_events}", "Niveau préférable avant V4.9H."),
                _gate("Unique event dates", "PASS" if unique_dates >= 4 else "NOT YET", "Medium" if unique_dates < 4 else "None", unique_dates, "Évite une validation sur un cluster de dates."),
                _gate("Source diversity", "PASS" if source_count >= provider_target else "REVIEW", "Medium" if source_count < provider_target else "None", f"{source_count}/{provider_target}", "Au moins deux sources/providers préférable avant blueprint."),
                _gate("Template / placeholder rows", "PASS" if contaminated_count == 0 else "BLOCK", "Critical" if contaminated_count > 0 else "None", f"{contaminated_count} rows", "Aucune ligne template/example/replace_with ne doit valider la source."),
                _gate("Forbidden outcome columns", "PASS" if not forbidden_columns else "BLOCK", "Critical" if forbidden_columns else "None", ", ".join(forbidden_columns) if forbidden_columns else "0", "Colonnes future/outcome interdites."),
                _gate("available_at quality", "PASS" if available_invalid == 0 and source_rows > 0 else "BLOCK", "Critical" if available_invalid > 0 or source_rows <= 0 else "None", available_invalid, "Chaque ligne source doit avoir un timestamp de disponibilité."),
                _gate("event date quality", "PASS" if event_date_invalid == 0 and source_rows > 0 else "REVIEW", "Medium" if event_date_invalid > 0 else "None", event_date_invalid, "Date économique/évènement lisible."),
                _gate("available_at before event_date", "PASS" if future_availability_rows == 0 else "REVIEW", "Medium" if future_availability_rows > 0 else "None", future_availability_rows, "available_at avant event_date est suspect pour une surprise publiée."),
                _gate("Value missingness", "PASS" if value_missing_rate <= 0.05 else "BLOCK", "High" if value_missing_rate > 0.05 else "None", _format_pct(value_missing_rate), "La feature source ne doit pas être vide."),
                _gate("Numeric value share", "PASS" if (not numeric_required or (pd.notna(numeric_share) and numeric_share >= 0.80)) else "REVIEW", "Medium" if numeric_required and (pd.isna(numeric_share) or numeric_share < 0.80) else "None", _format_pct(numeric_share) if pd.notna(numeric_share) else "N/A", "Les surprise/revision/guidance doivent être majoritairement numériques."),
                _gate("Duplicate source keys", "PASS" if duplicate_keys == 0 else "REVIEW", "Medium" if duplicate_keys > 0 else "None", duplicate_keys, "Doublons date/available_at/ticker/family/feature/source à inspecter."),
                _gate("Date concentration", "PASS" if max_date_concentration <= 0.40 or rule_event_count < min_rule_events else "REVIEW", "Medium" if max_date_concentration > 0.40 and rule_event_count >= min_rule_events else "None", _format_pct(max_date_concentration), "Concentration maximale sur une même date."),
                _gate("No OOS / no promotion", "ENFORCED", "None", "read-only", "V4.9G.3 ne peut pas autoriser live/OOS/promotion moteur."),
            ]
        )

        block_count = int((gates["Status"].astype(str) == "BLOCK").sum()) if not gates.empty else 0
        not_yet_count = int((gates["Status"].astype(str) == "NOT YET").sum()) if not gates.empty else 0
        review_count = int((gates["Status"].astype(str) == "REVIEW").sum()) if not gates.empty else 0

        score = 100.0
        score -= block_count * 35.0
        score -= max(0, min_rule_events - rule_event_count) * 6.0
        score -= max(0, min_source_rows - source_rows) * 3.0
        score -= max(0, 4 - unique_dates) * 5.0
        score -= max(0, provider_target - source_count) * 8.0
        score -= contamination_share * 60.0
        score -= value_missing_rate * 25.0
        score -= review_count * 4.0
        score = max(0.0, min(100.0, float(score)))

        if block_count > 0:
            level = "Source event reupload blocked"
            decision = "FIX_SOURCE_DATA_BEFORE_V49H"
            read = "V4.9G.3 bloque : contamination, leakage, available_at manquant ou source identity/data manquante."
        elif rule_event_count < min_rule_events or source_rows < min_source_rows:
            level = "Source event sample still insufficient"
            decision = "EXPAND_MORE_AND_REUPLOAD_V49A"
            read = "La source est propre mais l'échantillon reste insuffisant pour V4.9H. Ajouter des évènements réels puis repasser V4.9A/V4.9B/V4.9G."
        elif unique_dates < 4:
            level = "Source event date spread review"
            decision = "ADD_DATE_DIVERSITY_BEFORE_V49H"
            read = "Le nombre d'évènements approche le minimum, mais la distribution temporelle est trop concentrée."
        elif source_count < provider_target:
            level = "Source event provenance review"
            decision = "ADD_PROVIDER_DIVERSITY_BEFORE_V49H"
            read = "Le sample minimal est atteint, mais la provenance reste fragile. Ajouter au moins une deuxième source."
        elif review_count > 0:
            level = "Source event reupload review"
            decision = "REVIEW_SOURCE_EVENTS_BEFORE_V49H"
            read = "Le reupload est exploitable mais certaines alertes doivent être revues avant V4.9H."
        else:
            level = "Source event reupload validated"
            decision = "READY_FOR_V49H_SOURCE_ONLY_REVIEW"
            read = "V4.9G.3 valide le reupload source : sample/provenance/available_at suffisants pour préparer V4.9H en lecture seule."

        source_quality = pd.DataFrame(
            [
                ["Target family", top_family or "N/A", "Famille source auditée."],
                ["Target feature", top_feature or "N/A", "Feature source auditée."],
                ["Top rule", top_rule or "N/A", "Règle source-only à contrôler."],
                ["Selected source rows", source_rows, "Lignes exactes family/feature."],
                ["Rule event count", rule_event_count, "Évènements exploitables par la règle top."],
                ["Unique dates", unique_dates, "Dates distinctes."],
                ["First event", first_event, "Premier évènement."],
                ["Last event", last_event, "Dernier évènement."],
                ["Source count", source_count, "Nombre de sources/providers distincts."],
                ["Source tags", source_text, "Sources observées."],
                ["Template/placeholder rows", contaminated_count, "Lignes contaminées par template/example/replace_with."],
                ["Forbidden columns", ", ".join(forbidden_columns) if forbidden_columns else "None", "Colonnes outcome/leakage."],
                ["available_at invalid", available_invalid, "Timestamps de disponibilité invalides."],
                ["value missing rate", _format_pct(value_missing_rate), "Taux de valeurs manquantes."],
                ["numeric share", _format_pct(numeric_share) if pd.notna(numeric_share) else "N/A", "Part numérique de value."],
                ["avg confidence", _format_num(confidence_mean) if pd.notna(confidence_mean) else "N/A", "Confiance moyenne si fournie."],
                ["duplicate keys", duplicate_keys, "Doublons à inspecter."],
                ["max date concentration", _format_pct(max_date_concentration), "Part max sur une seule date."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        rule_event_sample = pd.DataFrame(
            [
                ["Rule events current/min", f"{rule_event_count}/{min_rule_events}", "Minimum avant V4.9H."],
                ["Rule events preferred", f"{rule_event_count}/{preferred_rule_events}", "Niveau préférable."],
                ["Missing to minimum", max(0, min_rule_events - rule_event_count), "Évènements règle à ajouter."],
                ["Missing to preferred", max(0, preferred_rule_events - rule_event_count), "Évènements règle à ajouter pour confort."],
                ["Source rows current/min", f"{source_rows}/{min_source_rows}", "Lignes brutes source candidate."],
                ["Rule event coverage", _format_pct(rule_event_count / max(source_rows, 1)), "Part des lignes source retenues par la règle."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        next_actions = pd.DataFrame(
            [
                ["P0", "Do not run OOS/live", "V4.9H not built yet", "Aucune promotion tant que V4.9H puis gates OOS/overfit ne passent pas."],
                ["P0", "Use V4.9A as source of truth", "reupload discipline", "Toute correction du CSV doit repasser par V4.9A puis V4.9B/V4.9B.3."],
                ["P0", "Fix blocking source issues", f"blocks={block_count}", "Supprimer placeholders/leakage et compléter available_at si nécessaire."],
                ["P0", "Expand rule event sample", f"events={rule_event_count}/{min_rule_events}", "Ajouter des évènements réels pour la feature candidate si le seuil n'est pas atteint."],
                ["P1", "Add provider diversity", f"sources={source_count}/{provider_target}", "Ajouter un second provider/source tag si possible."],
                ["P1", "Prepare V4.9H only if READY", decision, "V4.9H seulement si V4.9G.3 finit READY_FOR_V49H_SOURCE_ONLY_REVIEW."],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        summary = pd.DataFrame(
            [
                _row("V4.9G.3 level", level, "Lecture synthétique du validator de reupload source."),
                _row("V4.9G.3 score", f"{_format_num(score, 0)}/100", "Score de qualité source, pas score alpha."),
                _row("Decision", decision, "Décision research V4.9G.3."),
                _row("Read", read, "Interprétation opérationnelle."),
                _row("Ticker", str(ticker or "N/A").upper(), "Ticker cible."),
                _row("Target source", f"{top_family or 'N/A'} / {top_feature or 'N/A'}", "Source candidate contrôlée."),
                _row("Top rule", top_rule or "N/A", "Règle source-only contrôlée."),
                _row("Source rows", source_rows, "Lignes source exactes."),
                _row("Rule events", rule_event_count, "Évènements exploitables par la règle."),
                _row("Unique dates", unique_dates, "Distribution temporelle."),
                _row("Sources", source_count, "Providers/sources distincts."),
                _row("Blocks / reviews", f"{block_count} / {review_count}", "Alertes bloquantes et non-bloquantes."),
                _row("No engine impact", "PASS", "Aucun signal/trade/equity/verdict modifié."),
            ]
        )

        cards = [
            {"label": "V4.9G.3 validator", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Rule events", "value": f"{rule_event_count}/{min_rule_events}", "delta": f"missing {max(0, min_rule_events - rule_event_count)}"},
            {"label": "Source rows", "value": str(source_rows), "delta": top_feature or "feature"},
            {"label": "Sources", "value": f"{source_count}/{provider_target}", "delta": "providers"},
            {"label": "Blocks", "value": str(block_count), "delta": "must fix"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "gates": gates,
            "source_quality": source_quality,
            "rule_event_sample": rule_event_sample,
            "selected_source_rows": selected,
            "contaminated_rows": contaminated_rows,
            "next_actions": next_actions,
            "top_family": top_family,
            "top_feature": top_feature,
            "top_rule": top_rule,
            "source_rows": source_rows,
            "rule_event_count": rule_event_count,
            "unique_dates": unique_dates,
            "source_count": source_count,
            "block_count": block_count,
            "review_count": review_count,
        }

    except Exception as exc:
        out = empty.copy()
        out["enabled"] = False
        out["level"] = "V4.9G.3 error"
        out["decision"] = "V49G3_ERROR_SAFE_SKIP"
        out["read"] = f"Erreur V4.9G.3 capturée sans interrompre le backtest : {exc}"
        out["summary"] = pd.DataFrame(
            [["V4.9G.3 error", str(exc), "Erreur capturée, aucun impact moteur."]],
            columns=["Metric", "Value", "Read"],
        )
        return out


def _render_source_event_reupload_validator_v49g3(
    v49g2_pack: Any = None,
    v49g1_pack: Any = None,
    v49g_pack: Any = None,
    external_features: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    """Streamlit renderer for V4.9G.3. Read-only source event reupload validator."""
    pack = _source_event_reupload_validator_v49g3_pack(
        v49g2_pack=v49g2_pack,
        v49g1_pack=v49g1_pack,
        v49g_pack=v49g_pack,
        external_features=external_features,
        ticker=ticker,
    )

    st.subheader("Source Event Collection Control / Reupload Validator V4.9G.3")
    st.caption(
        "Validator lecture seule après V4.9G.2 : contrôle le CSV enrichi, le sample source réel, "
        "les providers, available_at, contamination template et colonnes outcome avant tout V4.9H. "
        "Aucun alpha scan, aucun OOS, aucun signal moteur, aucun trade, aucune equity curve, aucun sizing, "
        "aucun exit et aucun verdict ne sont modifiés."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", "Unavailable"))
    read = str(pack.get("read", ""))

    if "blocked" in level.lower() or "error" in level.lower():
        st.error(f"Lecture V4.9G.3 : {read}")
    elif "insufficient" in level.lower() or "review" in level.lower():
        st.warning(f"Lecture V4.9G.3 : {read}")
    elif "validated" in level.lower() or "ready" in level.lower():
        st.success(f"Lecture V4.9G.3 : {read}")
    else:
        st.info(f"Lecture V4.9G.3 : {read}")

    with st.expander("V4.9G.3 reupload validator summary", expanded=True):
        summary = pack.get("summary", pd.DataFrame())
        if isinstance(summary, pd.DataFrame) and not summary.empty:
            st.dataframe(summary, use_container_width=True, hide_index=True)
        else:
            st.info("Résumé V4.9G.3 indisponible.")

    with st.expander("V4.9G.3 validation gates", expanded=True):
        gates = pack.get("gates", pd.DataFrame())
        if isinstance(gates, pd.DataFrame) and not gates.empty:
            st.dataframe(gates, use_container_width=True, hide_index=True)
        else:
            st.info("Gates V4.9G.3 indisponibles.")

    with st.expander("V4.9G.3 source quality map", expanded=True):
        quality = pack.get("source_quality", pd.DataFrame())
        if isinstance(quality, pd.DataFrame) and not quality.empty:
            st.dataframe(quality, use_container_width=True, hide_index=True)
        else:
            st.info("Source quality map V4.9G.3 indisponible.")

    with st.expander("V4.9G.3 rule event sample", expanded=True):
        sample = pack.get("rule_event_sample", pd.DataFrame())
        if isinstance(sample, pd.DataFrame) and not sample.empty:
            st.dataframe(sample, use_container_width=True, hide_index=True)
        else:
            st.info("Rule event sample V4.9G.3 indisponible.")

    with st.expander("V4.9G.3 selected source rows", expanded=False):
        selected = pack.get("selected_source_rows", pd.DataFrame())
        if isinstance(selected, pd.DataFrame) and not selected.empty:
            st.dataframe(selected, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune ligne source sélectionnée pour V4.9G.3.")

    with st.expander("V4.9G.3 contaminated / blocking rows", expanded=False):
        contaminated = pack.get("contaminated_rows", pd.DataFrame())
        if isinstance(contaminated, pd.DataFrame) and not contaminated.empty:
            st.dataframe(contaminated, use_container_width=True, hide_index=True)
        else:
            st.info("Aucune ligne contaminée détectée par V4.9G.3.")

    with st.expander("V4.9G.3 next controlled actions", expanded=True):
        actions = pack.get("next_actions", pd.DataFrame())
        if isinstance(actions, pd.DataFrame) and not actions.empty:
            st.dataframe(actions, use_container_width=True, hide_index=True)
        else:
            st.info("Actions V4.9G.3 indisponibles.")

    d1, d2, d3 = st.columns(3)
    selected = pack.get("selected_source_rows", pd.DataFrame())
    contaminated = pack.get("contaminated_rows", pd.DataFrame())
    gates = pack.get("gates", pd.DataFrame())

    if isinstance(selected, pd.DataFrame) and not selected.empty:
        d1.download_button(
            "Télécharger V4.9G.3 selected source rows CSV",
            data=selected.to_csv(index=False).encode("utf-8"),
            file_name="v49g3_selected_source_rows.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g3_selected_source_rows_download",
        )

    if isinstance(contaminated, pd.DataFrame) and not contaminated.empty:
        d2.download_button(
            "Télécharger V4.9G.3 contaminated rows CSV",
            data=contaminated.to_csv(index=False).encode("utf-8"),
            file_name="v49g3_contaminated_rows.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g3_contaminated_rows_download",
        )

    if isinstance(gates, pd.DataFrame) and not gates.empty:
        d3.download_button(
            "Télécharger V4.9G.3 gates CSV",
            data=gates.to_csv(index=False).encode("utf-8"),
            file_name="v49g3_validation_gates.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v49g3_gates_download",
        )

    return pack

# ============================================================
# END SOURCE EVENT COLLECTION CONTROL / REUPLOAD VALIDATOR V4.9G.3
# ============================================================


# ============================================================
# V4.9G.3 FALSE CONTAMINATION FIX — OVERRIDE PACK ONLY
# ============================================================
def _source_event_reupload_validator_v49g3_pack(
    v49g2_pack: Any = None,
    v49g1_pack: Any = None,
    v49g_pack: Any = None,
    external_features: Any = None,
    ticker: str = "",
    min_rule_events: int = 8,
    preferred_rule_events: int = 15,
    min_source_rows: int = 8,
    provider_target: int = 2,
) -> dict[str, Any]:
    """
    V4.9G.3 — Source Event Collection Control / Reupload Validator.

    Lecture seule :
    - contrôle le CSV enrichi après V4.9G.2 ;
    - vérifie que la source candidate exacte a assez d'évènements réels ;
    - détecte placeholders/template rows, colonnes outcome/leakage, available_at manquant,
      concentration date/source et faiblesse provider ;
    - ne lance aucun alpha scan, aucun OOS, aucun signal moteur, aucun trade,
      aucune equity curve, aucun sizing, aucun exit et aucun verdict.
    """
    def _norm(x: Any) -> str:
        try:
            return str(x or "").strip().lower().replace(" ", "_").replace("-", "_")
        except Exception:
            return ""

    def _row(metric: str, value: Any, read: str) -> dict[str, Any]:
        return {"Metric": str(metric), "Value": str(value), "Read": str(read)}

    def _gate(check: str, status: str, severity: str, value: Any, read: str) -> dict[str, Any]:
        return {
            "Check": str(check),
            "Status": str(status),
            "Severity": str(severity),
            "Value": str(value),
            "Read": str(read),
        }

    def _safe_int(x: Any, default: int = 0) -> int:
        try:
            if x is None or pd.isna(x):
                return default
            return int(float(x))
        except Exception:
            return default

    def _first_non_empty(*values: Any) -> str:
        for value in values:
            txt = str(value or "").strip()
            if txt and txt.upper() not in {"N/A", "NA", "NONE", "NAN", "NULL"}:
                return txt
        return ""

    def _clean_features(df: Any) -> pd.DataFrame:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return pd.DataFrame()

        out = df.copy()
        out.columns = [str(c).strip() for c in out.columns]
        lower = {str(c).lower().strip(): c for c in out.columns}

        aliases = {
            "date": ["date", "event_date", "decision_date", "trading_date"],
            "available_at": ["available_at", "asof", "as_of", "published_at", "release_time", "timestamp"],
            "ticker": ["ticker", "symbol", "asset", "asset_ticker"],
            "feature_family": ["feature_family", "family", "source_family"],
            "feature_name": ["feature_name", "feature", "source_feature", "name"],
            "value": ["value", "feature_value", "signal_value", "raw_value"],
            "source": ["source", "provider", "source_tag", "data_source"],
            "confidence": ["confidence", "reliability", "quality_score"],
            "notes": ["notes", "note", "comment", "headline"],
        }

        rename_map = {}
        for target, names in aliases.items():
            if target in out.columns:
                continue
            for name in names:
                if name in lower:
                    rename_map[lower[name]] = target
                    break

        if rename_map:
            out = out.rename(columns=rename_map)

        for col in ["date", "available_at", "ticker", "feature_family", "feature_name", "value", "source", "confidence", "notes"]:
            if col not in out.columns:
                out[col] = np.nan

        out["date"] = pd.to_datetime(out["date"], errors="coerce")
        out["available_at"] = pd.to_datetime(out["available_at"], errors="coerce")
        out["ticker"] = out["ticker"].astype(str).str.strip().str.upper()
        out["feature_family"] = out["feature_family"].astype(str).str.strip()
        out["feature_name"] = out["feature_name"].astype(str).str.strip()
        out["source"] = out["source"].astype(str).str.strip()
        out["notes"] = out["notes"].astype(str).str.strip()
        out["confidence"] = pd.to_numeric(out["confidence"], errors="coerce")

        return out.replace([np.inf, -np.inf], np.nan)

    def _target_rule_events(selected: pd.DataFrame, top_rule: str, v49g_pack_obj: dict[str, Any]) -> pd.DataFrame:
        if selected is None or not isinstance(selected, pd.DataFrame) or selected.empty:
            return pd.DataFrame()

        rule_txt = _norm(top_rule)

        event_map = v49g_pack_obj.get("event_map", pd.DataFrame()) if isinstance(v49g_pack_obj, dict) else pd.DataFrame()
        if isinstance(event_map, pd.DataFrame) and not event_map.empty:
            em = event_map.copy()
            if "rule_name" in em.columns and top_rule:
                em = em[em["rule_name"].astype(str).map(_norm) == rule_txt].copy()
            if not em.empty:
                return em

        out = selected.copy()
        values = pd.to_numeric(out.get("value"), errors="coerce")

        if values.notna().sum() <= 0:
            return pd.DataFrame()

        if "top_quartile" in rule_txt or "q75" in rule_txt:
            threshold = float(values.quantile(0.75))
            out = out[values >= threshold].copy()
        elif "bottom_quartile" in rule_txt or "q25" in rule_txt:
            threshold = float(values.quantile(0.25))
            out = out[values <= threshold].copy()
        elif "positive" in rule_txt or "non_negative" in rule_txt:
            out = out[values >= 0].copy()
        elif "negative" in rule_txt:
            out = out[values < 0].copy()
        else:
            threshold = float(values.quantile(0.75))
            out = out[values >= threshold].copy()

        return out

    empty = {
        "enabled": False,
        "level": "Unavailable",
        "score": 0.0,
        "decision": "V49G3_UNAVAILABLE",
        "read": "V4.9G.3 indisponible.",
        "cards": [],
        "summary": pd.DataFrame(),
        "gates": pd.DataFrame(),
        "source_quality": pd.DataFrame(),
        "rule_event_sample": pd.DataFrame(),
        "selected_source_rows": pd.DataFrame(),
        "contaminated_rows": pd.DataFrame(),
        "next_actions": pd.DataFrame(),
    }

    try:
        g2 = v49g2_pack if isinstance(v49g2_pack, dict) else {}
        g1 = v49g1_pack if isinstance(v49g1_pack, dict) else {}
        g = v49g_pack if isinstance(v49g_pack, dict) else {}

        top_family = _first_non_empty(g2.get("top_family"), g1.get("top_family"), g.get("top_family"))
        top_feature = _first_non_empty(g2.get("top_feature"), g1.get("top_feature"), g.get("top_feature"))
        top_rule = _first_non_empty(g2.get("top_rule"), g1.get("top_rule"), g.get("top_rule"), "value_top_quartile")

        clean = _clean_features(external_features)

        target_ticker = str(ticker or "").upper().strip()
        if target_ticker and isinstance(clean, pd.DataFrame) and not clean.empty and "ticker" in clean.columns:
            ticker_filtered = clean[clean["ticker"].astype(str).str.upper().str.strip() == target_ticker].copy()
            if not ticker_filtered.empty:
                clean = ticker_filtered

        identity_ok = bool(top_family and top_feature)
        data_ok = isinstance(clean, pd.DataFrame) and not clean.empty

        if data_ok and identity_ok:
            family_norm = _norm(top_family)
            feature_norm = _norm(top_feature)
            selected = clean[
                (clean["feature_family"].astype(str).map(_norm) == family_norm)
                & (clean["feature_name"].astype(str).map(_norm) == feature_norm)
            ].copy()
        else:
            selected = pd.DataFrame()

        rule_events = _target_rule_events(selected, top_rule, g)

        source_rows = int(len(selected)) if isinstance(selected, pd.DataFrame) else 0
        rule_event_count = int(len(rule_events)) if isinstance(rule_events, pd.DataFrame) else 0

        if rule_event_count <= 0:
            rule_event_count = _safe_int(g.get("top_sample", g1.get("current_events", 0)), 0)

        date_source = rule_events if isinstance(rule_events, pd.DataFrame) and not rule_events.empty else selected
        if isinstance(date_source, pd.DataFrame) and not date_source.empty:
            date_col = "decision_date" if "decision_date" in date_source.columns else "available_at" if "available_at" in date_source.columns else "date"
            date_series = pd.to_datetime(date_source.get(date_col), errors="coerce").dropna()
        else:
            date_col = "date"
            date_series = pd.Series(dtype="datetime64[ns]")

        unique_dates = int(date_series.dt.normalize().nunique()) if not date_series.empty else 0
        first_event = _format_dt(date_series.min()) if not date_series.empty else "N/A"
        last_event = _format_dt(date_series.max()) if not date_series.empty else "N/A"
        max_date_concentration = 0.0
        if not date_series.empty:
            date_counts = date_series.dt.normalize().value_counts()
            max_date_concentration = float(date_counts.max() / max(len(date_series), 1))

        if isinstance(selected, pd.DataFrame) and not selected.empty and "source" in selected.columns:
            source_clean = selected["source"].astype(str).str.strip()
            source_clean = source_clean.replace({"": np.nan, "nan": np.nan, "None": np.nan})
            source_count = int(source_clean.dropna().nunique())
            source_text = ", ".join(sorted(source_clean.dropna().astype(str).unique().tolist())[:8]) or "N/A"
        else:
            source_count = 0
            source_text = "N/A"

        # V4.9G.3 fix — contamination detection must be field-aware.
        # Previous logic was too broad: tokens such as "example" or "sample" in notes could block
        # a structurally clean source even after V4.9B.3 provenance passed.
        # Blocking is now reserved for explicit placeholders/template markers.
        strong_placeholder_tokens = [
            "replace_with", "template_row", "placeholder", "provider_or_manual", "manual_example",
            "dummy", "to_fill", "fill_me", "fake", "test_row", "replace_me",
        ]
        weak_review_tokens = [
            "example ", " sample ", "demo", "synthetic", "illustrative",
        ]

        def _contamination_reason(row: pd.Series) -> str:
            try:
                source_norm = _norm(row.get("source", ""))
                notes_norm = _norm(row.get("notes", ""))
                value_norm = _norm(row.get("value", ""))

                # Hard blocks: explicit source/provider placeholders.
                if source_norm.startswith("replace_with") or source_norm in {
                    "manual_example",
                    "provider_or_manual",
                    "replace_with_provider",
                    "replace_with_earnings_provider",
                    "replace_with_revision_provider",
                    "replace_with_guidance_provider",
                    "replace_with_options_provider",
                    "replace_with_news_provider",
                }:
                    return "placeholder_source"

                # Hard blocks: explicit template markers in notes.
                hard_note_markers = [
                    "replace_with",
                    "replace_with_real",
                    "template_row",
                    "placeholder",
                    "to_fill",
                    "fill_me",
                    "dummy",
                    "fake",
                    "test_row",
                ]
                if any(tok in notes_norm for tok in hard_note_markers):
                    return "placeholder_notes"

                # Hard blocks: non-numeric placeholder value.
                if any(tok in value_norm for tok in ["replace_with", "placeholder", "to_fill", "fill_me"]):
                    return "placeholder_value"

                return ""
            except Exception:
                return ""
        forbidden_columns = []
        forbidden_tokens = [
            "future_return", "forward_return", "next_return", "return_fwd", "return_next",
            "realized_alpha", "realized_return", "target_hit", "hit_target", "pnl",
            "profit", "outcome", "next_close", "future_close", "label_y", "target_y",
        ]

        if isinstance(clean, pd.DataFrame) and not clean.empty:
            for col in clean.columns:
                col_norm = _norm(col)
                if any(tok in col_norm for tok in forbidden_tokens):
                    forbidden_columns.append(str(col))

        if isinstance(selected, pd.DataFrame) and not selected.empty:
            contamination_reasons = selected.apply(_contamination_reason, axis=1)
            contam_mask = contamination_reasons.astype(str).str.len() > 0
            contaminated_rows = selected.loc[contam_mask].copy()
            if not contaminated_rows.empty:
                contaminated_rows.insert(
                    0,
                    "block_reason",
                    contamination_reasons.loc[contam_mask].astype(str).values,
                )
        else:
            contaminated_rows = pd.DataFrame()

        contaminated_count = int(len(contaminated_rows)) if isinstance(contaminated_rows, pd.DataFrame) else 0
        contamination_share = contaminated_count / max(source_rows, 1)

        available_invalid = 0
        event_date_invalid = 0
        future_availability_rows = 0
        value_missing = 0
        value_missing_rate = 1.0
        duplicate_keys = 0
        numeric_share = np.nan
        confidence_mean = np.nan

        if isinstance(selected, pd.DataFrame) and not selected.empty:
            available = pd.to_datetime(selected.get("available_at"), errors="coerce")
            event_dates = pd.to_datetime(selected.get("date"), errors="coerce")
            available_invalid = int(available.isna().sum())
            event_date_invalid = int(event_dates.isna().sum())
            future_availability_rows = int((available.dt.normalize() < event_dates.dt.normalize()).fillna(False).sum())

            value_series = selected.get("value")
            value_missing = int(pd.Series(value_series).isna().sum())
            value_missing_rate = value_missing / max(source_rows, 1)

            numeric_values = pd.to_numeric(value_series, errors="coerce")
            numeric_share = float(numeric_values.notna().mean()) if len(numeric_values) else np.nan

            conf = pd.to_numeric(selected.get("confidence"), errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
            confidence_mean = float(conf.mean()) if not conf.empty else np.nan

            key_cols = [c for c in ["date", "available_at", "ticker", "feature_family", "feature_name", "source"] if c in selected.columns]
            duplicate_keys = int(selected.duplicated(subset=key_cols).sum()) if key_cols else 0

        feature_norm = _norm(top_feature)
        numeric_required = not any(tok in feature_norm for tok in ["tag", "headline", "news", "sentiment", "category", "state"])

        gates = pd.DataFrame(
            [
                _gate("Source identity", "PASS" if identity_ok else "BLOCK", "Critical" if not identity_ok else "None", f"{top_family or 'N/A'} / {top_feature or 'N/A'}", "Famille/feature candidate héritée de V4.9G.2/V4.9G."),
                _gate("External feature table", "PASS" if data_ok else "BLOCK", "Critical" if not data_ok else "None", len(clean) if isinstance(clean, pd.DataFrame) else 0, "Table externe chargée via V4.9A/V4.9B."),
                _gate("Selected source rows", "PASS" if source_rows >= min_source_rows else "NOT YET", "High" if source_rows < min_source_rows else "None", f"{source_rows}/{min_source_rows}", "Lignes disponibles pour la source candidate exacte."),
                _gate("Rule event sample", "PASS" if rule_event_count >= min_rule_events else "NOT YET", "High" if rule_event_count < min_rule_events else "None", f"{rule_event_count}/{min_rule_events}", "Évènements réellement exploitables pour la règle source-only."),
                _gate("Preferred rule events", "PASS" if rule_event_count >= preferred_rule_events else "REVIEW", "Low" if rule_event_count < preferred_rule_events else "None", f"{rule_event_count}/{preferred_rule_events}", "Niveau préférable avant V4.9H."),
                _gate("Unique event dates", "PASS" if unique_dates >= 4 else "NOT YET", "Medium" if unique_dates < 4 else "None", unique_dates, "Évite une validation sur un cluster de dates."),
                _gate("Source diversity", "PASS" if source_count >= provider_target else "REVIEW", "Medium" if source_count < provider_target else "None", f"{source_count}/{provider_target}", "Au moins deux sources/providers préférable avant blueprint."),
                _gate("Template / placeholder rows", "PASS" if contaminated_count == 0 else "BLOCK", "Critical" if contaminated_count > 0 else "None", f"{contaminated_count} rows", "Blocage uniquement sur placeholders explicites : replace_with, template_row, placeholder, manual_example, provider_or_manual."),
                _gate("Forbidden outcome columns", "PASS" if not forbidden_columns else "BLOCK", "Critical" if forbidden_columns else "None", ", ".join(forbidden_columns) if forbidden_columns else "0", "Colonnes future/outcome interdites."),
                _gate("available_at quality", "PASS" if available_invalid == 0 and source_rows > 0 else "BLOCK", "Critical" if available_invalid > 0 or source_rows <= 0 else "None", available_invalid, "Chaque ligne source doit avoir un timestamp de disponibilité."),
                _gate("event date quality", "PASS" if event_date_invalid == 0 and source_rows > 0 else "REVIEW", "Medium" if event_date_invalid > 0 else "None", event_date_invalid, "Date économique/évènement lisible."),
                _gate("available_at before event_date", "PASS" if future_availability_rows == 0 else "REVIEW", "Medium" if future_availability_rows > 0 else "None", future_availability_rows, "available_at avant event_date est suspect pour une surprise publiée."),
                _gate("Value missingness", "PASS" if value_missing_rate <= 0.05 else "BLOCK", "High" if value_missing_rate > 0.05 else "None", _format_pct(value_missing_rate), "La feature source ne doit pas être vide."),
                _gate("Numeric value share", "PASS" if (not numeric_required or (pd.notna(numeric_share) and numeric_share >= 0.80)) else "REVIEW", "Medium" if numeric_required and (pd.isna(numeric_share) or numeric_share < 0.80) else "None", _format_pct(numeric_share) if pd.notna(numeric_share) else "N/A", "Les surprise/revision/guidance doivent être majoritairement numériques."),
                _gate("Duplicate source keys", "PASS" if duplicate_keys == 0 else "REVIEW", "Medium" if duplicate_keys > 0 else "None", duplicate_keys, "Doublons date/available_at/ticker/family/feature/source à inspecter."),
                _gate("Date concentration", "PASS" if max_date_concentration <= 0.40 or rule_event_count < min_rule_events else "REVIEW", "Medium" if max_date_concentration > 0.40 and rule_event_count >= min_rule_events else "None", _format_pct(max_date_concentration), "Concentration maximale sur une même date."),
                _gate("No OOS / no promotion", "ENFORCED", "None", "read-only", "V4.9G.3 ne peut pas autoriser live/OOS/promotion moteur."),
            ]
        )

        block_count = int((gates["Status"].astype(str) == "BLOCK").sum()) if not gates.empty else 0
        not_yet_count = int((gates["Status"].astype(str) == "NOT YET").sum()) if not gates.empty else 0
        review_count = int((gates["Status"].astype(str) == "REVIEW").sum()) if not gates.empty else 0

        score = 100.0
        score -= block_count * 35.0
        score -= max(0, min_rule_events - rule_event_count) * 6.0
        score -= max(0, min_source_rows - source_rows) * 3.0
        score -= max(0, 4 - unique_dates) * 5.0
        score -= max(0, provider_target - source_count) * 8.0
        score -= contamination_share * 60.0
        score -= value_missing_rate * 25.0
        score -= review_count * 4.0
        score = max(0.0, min(100.0, float(score)))

        if block_count > 0:
            level = "Source event reupload blocked"
            decision = "FIX_SOURCE_DATA_BEFORE_V49H"
            read = "V4.9G.3 bloque uniquement si placeholder explicite, leakage, available_at manquant ou source identity/data manquante est détecté."
        elif rule_event_count < min_rule_events or source_rows < min_source_rows:
            level = "Source event sample still insufficient"
            decision = "EXPAND_MORE_AND_REUPLOAD_V49A"
            read = "La source est propre mais l'échantillon reste insuffisant pour V4.9H. Ajouter des évènements réels puis repasser V4.9A/V4.9B/V4.9G."
        elif unique_dates < 4:
            level = "Source event date spread review"
            decision = "ADD_DATE_DIVERSITY_BEFORE_V49H"
            read = "Le nombre d'évènements approche le minimum, mais la distribution temporelle est trop concentrée."
        elif source_count < provider_target:
            level = "Source event provenance review"
            decision = "ADD_PROVIDER_DIVERSITY_BEFORE_V49H"
            read = "Le sample minimal est atteint, mais la provenance reste fragile. Ajouter au moins une deuxième source."
        elif review_count > 0:
            level = "Source event reupload review"
            decision = "REVIEW_SOURCE_EVENTS_BEFORE_V49H"
            read = "Le reupload est exploitable mais certaines alertes doivent être revues avant V4.9H."
        else:
            level = "Source event reupload validated"
            decision = "READY_FOR_V49H_SOURCE_ONLY_REVIEW"
            read = "V4.9G.3 valide le reupload source : sample/provenance/available_at suffisants pour préparer V4.9H en lecture seule."

        source_quality = pd.DataFrame(
            [
                ["Target family", top_family or "N/A", "Famille source auditée."],
                ["Target feature", top_feature or "N/A", "Feature source auditée."],
                ["Top rule", top_rule or "N/A", "Règle source-only à contrôler."],
                ["Selected source rows", source_rows, "Lignes exactes family/feature."],
                ["Rule event count", rule_event_count, "Évènements exploitables par la règle top."],
                ["Unique dates", unique_dates, "Dates distinctes."],
                ["First event", first_event, "Premier évènement."],
                ["Last event", last_event, "Dernier évènement."],
                ["Source count", source_count, "Nombre de sources/providers distincts."],
                ["Source tags", source_text, "Sources observées."],
                ["Template/placeholder rows", contaminated_count, "Lignes contaminées par placeholders explicites uniquement."],
                ["Forbidden columns", ", ".join(forbidden_columns) if forbidden_columns else "None", "Colonnes outcome/leakage."],
                ["available_at invalid", available_invalid, "Timestamps de disponibilité invalides."],
                ["value missing rate", _format_pct(value_missing_rate), "Taux de valeurs manquantes."],
                ["numeric share", _format_pct(numeric_share) if pd.notna(numeric_share) else "N/A", "Part numérique de value."],
                ["avg confidence", _format_num(confidence_mean) if pd.notna(confidence_mean) else "N/A", "Confiance moyenne si fournie."],
                ["duplicate keys", duplicate_keys, "Doublons à inspecter."],
                ["max date concentration", _format_pct(max_date_concentration), "Part max sur une seule date."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        rule_event_sample = pd.DataFrame(
            [
                ["Rule events current/min", f"{rule_event_count}/{min_rule_events}", "Minimum avant V4.9H."],
                ["Rule events preferred", f"{rule_event_count}/{preferred_rule_events}", "Niveau préférable."],
                ["Missing to minimum", max(0, min_rule_events - rule_event_count), "Évènements règle à ajouter."],
                ["Missing to preferred", max(0, preferred_rule_events - rule_event_count), "Évènements règle à ajouter pour confort."],
                ["Source rows current/min", f"{source_rows}/{min_source_rows}", "Lignes brutes source candidate."],
                ["Rule event coverage", _format_pct(rule_event_count / max(source_rows, 1)), "Part des lignes source retenues par la règle."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        next_actions = pd.DataFrame(
            [
                ["P0", "Do not run OOS/live", "V4.9H not built yet", "Aucune promotion tant que V4.9H puis gates OOS/overfit ne passent pas."],
                ["P0", "Use V4.9A as source of truth", "reupload discipline", "Toute correction du CSV doit repasser par V4.9A puis V4.9B/V4.9B.3."],
                ["P0", "Fix blocking source issues", f"blocks={block_count}", "Supprimer placeholders/leakage et compléter available_at si nécessaire."],
                ["P0", "Expand rule event sample", f"events={rule_event_count}/{min_rule_events}", "Ajouter des évènements réels pour la feature candidate si le seuil n'est pas atteint."],
                ["P1", "Add provider diversity", f"sources={source_count}/{provider_target}", "Ajouter un second provider/source tag si possible."],
                ["P1", "Prepare V4.9H only if READY", decision, "V4.9H seulement si V4.9G.3 finit READY_FOR_V49H_SOURCE_ONLY_REVIEW."],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        summary = pd.DataFrame(
            [
                _row("V4.9G.3 level", level, "Lecture synthétique du validator de reupload source."),
                _row("V4.9G.3 score", f"{_format_num(score, 0)}/100", "Score de qualité source, pas score alpha."),
                _row("Decision", decision, "Décision research V4.9G.3."),
                _row("Read", read, "Interprétation opérationnelle."),
                _row("Ticker", str(ticker or "N/A").upper(), "Ticker cible."),
                _row("Target source", f"{top_family or 'N/A'} / {top_feature or 'N/A'}", "Source candidate contrôlée."),
                _row("Top rule", top_rule or "N/A", "Règle source-only contrôlée."),
                _row("Source rows", source_rows, "Lignes source exactes."),
                _row("Rule events", rule_event_count, "Évènements exploitables par la règle."),
                _row("Unique dates", unique_dates, "Distribution temporelle."),
                _row("Sources", source_count, "Providers/sources distincts."),
                _row("Blocks / reviews", f"{block_count} / {review_count}", "Alertes bloquantes et non-bloquantes."),
                _row("Blocking rows exported", contaminated_count, "Si >0, voir le CSV contaminated rows avec block_reason."),
                _row("No engine impact", "PASS", "Aucun signal/trade/equity/verdict modifié."),
            ]
        )

        cards = [
            {"label": "V4.9G.3 validator", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Rule events", "value": f"{rule_event_count}/{min_rule_events}", "delta": f"missing {max(0, min_rule_events - rule_event_count)}"},
            {"label": "Source rows", "value": str(source_rows), "delta": top_feature or "feature"},
            {"label": "Sources", "value": f"{source_count}/{provider_target}", "delta": "providers"},
            {"label": "Blocks", "value": str(block_count), "delta": "must fix"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "gates": gates,
            "source_quality": source_quality,
            "rule_event_sample": rule_event_sample,
            "selected_source_rows": selected,
            "contaminated_rows": contaminated_rows,
            "next_actions": next_actions,
            "top_family": top_family,
            "top_feature": top_feature,
            "top_rule": top_rule,
            "source_rows": source_rows,
            "rule_event_count": rule_event_count,
            "unique_dates": unique_dates,
            "source_count": source_count,
            "block_count": block_count,
            "review_count": review_count,
        }

    except Exception as exc:
        out = empty.copy()
        out["enabled"] = False
        out["level"] = "V4.9G.3 error"
        out["decision"] = "V49G3_ERROR_SAFE_SKIP"
        out["read"] = f"Erreur V4.9G.3 capturée sans interrompre le backtest : {exc}"
        out["summary"] = pd.DataFrame(
            [["V4.9G.3 error", str(exc), "Erreur capturée, aucun impact moteur."]],
            columns=["Metric", "Value", "Read"],
        )
        return out




# ============================================================
# V4.9H / V4.9I / V4.9J / V4.9K / V5.0 — COMPLETE SECTIONS PATCH
# ============================================================
# Remplace le bloc condensé "Source Validation Suite V4.9H -> V5.0".
# Règle de construction : une lettre = une section complète.
# Pas de H.1/H.2/H.3, pas de bloc résumé H->V5.
# Lecture seule : aucun signal moteur, aucun trade, aucune equity curve,
# aucun sizing, aucun exit, aucun OOS moteur et aucun verdict principal modifiés.


def _v49x_norm(value: Any) -> str:
    try:
        return str(value or "").strip().lower().replace(" ", "_").replace("-", "_")
    except Exception:
        return ""


def _v49x_clean_text(value: Any, default: str = "N/A") -> str:
    try:
        if value is None:
            return default
        try:
            if pd.isna(value):
                return default
        except Exception:
            pass
        txt = str(value).strip()
        return txt if txt else default
    except Exception:
        return default


def _v49x_col(df: pd.DataFrame, candidates: list[str]) -> str | None:
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return None
    lookup = {_v49x_norm(c): c for c in df.columns}
    for c in candidates:
        if _v49x_norm(c) in lookup:
            return lookup[_v49x_norm(c)]
    return None


def _v49x_pct_or_num_display(df: pd.DataFrame) -> pd.DataFrame:
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return pd.DataFrame()
    out = df.copy()
    for col in out.columns:
        low = str(col).lower()
        if any(tok in low for tok in ["return", "active", "hit", "rate", "coverage", "missing", "concentration", "share"]):
            out[col] = out[col].map(lambda x: _format_pct(x) if pd.notna(_safe_float(x, np.nan)) else _v49x_clean_text(x))
        elif "score" in low:
            out[col] = out[col].map(lambda x: _format_num(x, 0) if pd.notna(_safe_float(x, np.nan)) else _v49x_clean_text(x))
        elif any(tok in low for tok in ["date", "available", "decision"]):
            out[col] = out[col].map(lambda x: _format_dt(x) if str(x).strip() not in {"", "N/A", "nan", "None"} else "N/A")
    return out


def _v49x_pick_source_identity(
    v49g_pack: Any = None,
    v49g3_pack: Any = None,
    v49f1_pack: Any = None,
    v49f_pack: Any = None,
) -> dict[str, str]:
    """Résout la source candidate en regardant tous les packs amont disponibles."""
    out = {
        "source_family": "N/A",
        "source_feature": "N/A",
        "source_rule": "N/A",
    }

    for pack in [v49g3_pack, v49g_pack, v49f1_pack, v49f_pack]:
        if not isinstance(pack, dict):
            continue

        for target, keys in {
            "source_family": ["top_family", "source_family", "family", "selected_family"],
            "source_feature": ["top_feature", "source_feature", "feature", "feature_name", "selected_feature"],
            "source_rule": ["top_rule", "source_rule", "rule", "selected_rule"],
        }.items():
            for k in keys:
                txt = _v49x_clean_text(pack.get(k, ""), default="")
                if txt and txt.upper() not in {"N/A", "NA", "NONE", "NAN"}:
                    out[target] = txt
                    break

        # Fallback dataframe source_identity / bridge / contract.
        for table_key in ["source_identity", "source_bridge", "runner_contract", "summary"]:
            tab = pack.get(table_key, pd.DataFrame())
            if not isinstance(tab, pd.DataFrame) or tab.empty:
                continue
            low_cols = {_v49x_norm(c): c for c in tab.columns}
            if {"metric", "value"}.issubset(low_cols):
                mcol, vcol = low_cols["metric"], low_cols["value"]
                for _, row in tab.iterrows():
                    metric = _v49x_norm(row.get(mcol, ""))
                    val = _v49x_clean_text(row.get(vcol, ""), default="")
                    if not val:
                        continue
                    if "family" in metric and out["source_family"] == "N/A":
                        out["source_family"] = val
                    elif "feature" in metric and out["source_feature"] == "N/A":
                        out["source_feature"] = val
                    elif "rule" in metric and out["source_rule"] == "N/A":
                        out["source_rule"] = val
            else:
                fcol = _v49x_col(tab, ["source_family", "top_family", "family", "feature_family"])
                ncol = _v49x_col(tab, ["source_feature", "top_feature", "feature_name", "feature"])
                rcol = _v49x_col(tab, ["source_rule", "top_rule", "rule"])
                if len(tab) > 0:
                    first = tab.iloc[0]
                    if fcol and out["source_family"] == "N/A":
                        out["source_family"] = _v49x_clean_text(first.get(fcol, "N/A"))
                    if ncol and out["source_feature"] == "N/A":
                        out["source_feature"] = _v49x_clean_text(first.get(ncol, "N/A"))
                    if rcol and out["source_rule"] == "N/A":
                        out["source_rule"] = _v49x_clean_text(first.get(rcol, "N/A"))

        if out["source_family"] != "N/A" and out["source_feature"] != "N/A":
            break

    return out


def _v49x_normalize_external_features(raw: Any, ticker: str = "") -> pd.DataFrame:
    """Normalise toute table externe en colonnes standard V4.9H+ sans exécuter de code utilisateur."""
    if raw is None or not isinstance(raw, pd.DataFrame) or raw.empty:
        return pd.DataFrame(columns=["date", "available_at", "decision_date", "ticker", "feature_family", "feature_name", "value", "source", "confidence", "notes"])

    df = raw.copy()
    if isinstance(df.columns, pd.MultiIndex):
        df.columns = ["_".join([str(x) for x in c if str(x) != ""]) for c in df.columns]

    date_col = _v49x_col(df, ["date", "event_date", "observation_date", "economic_date"])
    avail_col = _v49x_col(df, ["available_at", "published_at", "release_time", "report_time", "as_of", "asof", "decision_date"])
    dec_col = _v49x_col(df, ["decision_date", "trade_date", "aligned_date", "calendar_date"])
    ticker_col = _v49x_col(df, ["ticker", "symbol", "asset"])
    fam_col = _v49x_col(df, ["feature_family", "source_family", "family", "data_family"])
    feat_col = _v49x_col(df, ["feature_name", "source_feature", "feature", "top_feature", "name"])
    value_col = _v49x_col(df, ["value", "feature_value", "signal_value", "score", "state"])
    source_col = _v49x_col(df, ["source", "provider", "source_tag", "provider_tag"])
    conf_col = _v49x_col(df, ["confidence", "source_confidence", "quality"])
    notes_col = _v49x_col(df, ["notes", "note", "headline", "description", "read"])

    out = pd.DataFrame(index=df.index)
    out["date"] = pd.to_datetime(df[date_col], errors="coerce") if date_col else pd.NaT
    out["available_at"] = pd.to_datetime(df[avail_col], errors="coerce") if avail_col else out["date"]
    out["decision_date"] = pd.to_datetime(df[dec_col], errors="coerce") if dec_col else pd.NaT
    out["ticker"] = df[ticker_col].astype(str).str.upper().str.strip() if ticker_col else str(ticker or "").upper().strip()
    out["feature_family"] = df[fam_col].astype(str).str.strip() if fam_col else "N/A"
    out["feature_name"] = df[feat_col].astype(str).str.strip() if feat_col else "N/A"
    out["value"] = df[value_col] if value_col else np.nan
    out["source"] = df[source_col].astype(str).str.strip() if source_col else "unknown_source"
    out["confidence"] = pd.to_numeric(df[conf_col], errors="coerce") if conf_col else np.nan
    out["notes"] = df[notes_col].astype(str).str.strip() if notes_col else ""

    out["date"] = out["date"].fillna(out["available_at"])
    out["available_at"] = out["available_at"].fillna(out["date"])
    out = out.replace([np.inf, -np.inf], np.nan)
    out = out.dropna(subset=["available_at"])

    if ticker:
        t = str(ticker).upper().strip()
        if t:
            mask = out["ticker"].astype(str).str.upper().str.strip().isin([t, "", "N/A", "NAN", "NONE"])
            out = out.loc[mask].copy()
            out.loc[out["ticker"].astype(str).str.strip().isin(["", "N/A", "nan", "None"]), "ticker"] = t

    out["feature_family_norm"] = out["feature_family"].map(_v49x_norm)
    out["feature_name_norm"] = out["feature_name"].map(_v49x_norm)
    return out.reset_index(drop=True)


def _v49x_candidate_source_rows(
    external_features: Any = None,
    identity: dict[str, str] | None = None,
    ticker: str = "",
    *packs: Any,
) -> pd.DataFrame:
    """Récupère les lignes de la source candidate depuis V4.9G/G.3 puis fallback V4.9A table."""
    identity = identity or {}
    fam = _v49x_norm(identity.get("source_family", ""))
    feat = _v49x_norm(identity.get("source_feature", ""))

    frames = []
    for pack in packs:
        if not isinstance(pack, dict):
            continue
        for key in ["selected_source_rows", "source_rows_df", "rule_event_sample", "selected_rows", "evidence_rows"]:
            tab = pack.get(key, pd.DataFrame())
            if isinstance(tab, pd.DataFrame) and not tab.empty:
                frames.append(_v49x_normalize_external_features(tab, ticker=ticker))

    ext = _v49x_normalize_external_features(external_features, ticker=ticker)
    if not ext.empty:
        frames.append(ext)

    if not frames:
        return pd.DataFrame()

    df = pd.concat(frames, ignore_index=True, sort=False)
    df = df.dropna(subset=["available_at"])

    if feat:
        candidate = df[df["feature_name_norm"] == feat].copy()
        if not candidate.empty:
            df = candidate

    if fam and not df.empty:
        candidate = df[df["feature_family_norm"] == fam].copy()
        if not candidate.empty:
            df = candidate

    # Déduplication stable source event. Ne déduplique pas par value seule.
    key_cols = [c for c in ["ticker", "available_at", "feature_family", "feature_name", "value", "source"] if c in df.columns]
    if key_cols:
        df = df.sort_values("available_at").drop_duplicates(key_cols, keep="last")

    return df.sort_values("available_at").reset_index(drop=True)


def _v49x_build_price_and_benchmark(df: pd.DataFrame | None, cfg: Any = None, ticker: str = "") -> dict[str, Any]:
    if df is None or not isinstance(df, pd.DataFrame) or df.empty or "close" not in df.columns:
        return {"price": pd.DataFrame(), "benchmark_nav": pd.Series(dtype=float), "benchmark_label": "N/A", "benchmark_fallback": True}

    price = df.copy()
    if not _is_datetime_like_index(price.index):
        date_col = _v49x_col(price, ["date", "datetime", "timestamp"])
        if date_col:
            price.index = pd.to_datetime(price[date_col], errors="coerce")
    price.index = pd.to_datetime(price.index, errors="coerce")
    price = price.loc[pd.Series(price.index).notna().values].copy()
    price = price.sort_index()
    price = price.loc[~price.index.duplicated(keep="last")]
    price["close"] = pd.to_numeric(price["close"], errors="coerce")
    price = price.dropna(subset=["close"])

    if price.empty:
        return {"price": pd.DataFrame(), "benchmark_nav": pd.Series(dtype=float), "benchmark_label": "N/A", "benchmark_fallback": True}

    bench_cfg = cfg
    try:
        if cfg is not None and not str(getattr(cfg, "benchmark_ticker", "") or "").strip():
            t = str(ticker or getattr(cfg, "asset_ticker", "") or "").upper().strip()
            auto_symbol = _sector_benchmark_guess(t) if t else "SPY"
            bench_cfg = BacktestConfig(**{**cfg.__dict__, "benchmark_ticker": auto_symbol, "benchmark_label": f"Auto Sector ETF ({auto_symbol})", "benchmark_mode": "Sector ETF"})
    except Exception:
        bench_cfg = cfg

    try:
        bench_ret, bench_label, bench_fallback = _load_benchmark_returns(price, bench_cfg) if bench_cfg is not None else (price["close"].pct_change().fillna(0.0), "Ticker Buy & Hold fallback", True)
        bench_ret = pd.to_numeric(bench_ret.reindex(price.index), errors="coerce").fillna(0.0)
        bench_nav = (1.0 + bench_ret).cumprod().replace([np.inf, -np.inf], np.nan).ffill().bfill()
    except Exception:
        bench_label = "Benchmark fallback error"
        bench_fallback = True
        bench_nav = (1.0 + price["close"].pct_change().fillna(0.0)).cumprod()

    return {"price": price, "benchmark_nav": bench_nav, "benchmark_label": bench_label, "benchmark_fallback": bool(bench_fallback)}


def _v49x_decision_position(price_index: pd.DatetimeIndex, available_at: Any) -> int | None:
    try:
        idx = pd.to_datetime(pd.Index(price_index), errors="coerce")
        idx = idx[~pd.isna(idx)]
        if len(idx) == 0:
            return None
        ts = pd.to_datetime(available_at, errors="coerce")
        if pd.isna(ts):
            return None
        # t+1 strict : décision au premier bar de trading strictement après available_at normalisé.
        pos = int(np.searchsorted(idx.normalize().values, np.datetime64(pd.Timestamp(ts).normalize()), side="right"))
        if pos >= len(idx):
            return None
        return pos
    except Exception:
        return None


def _v49x_event_forward_map(
    source_rows: pd.DataFrame,
    price_pack: dict[str, Any],
    identity: dict[str, str],
    horizons: tuple[int, ...] = (3, 5, 10, 20),
) -> pd.DataFrame:
    price = price_pack.get("price", pd.DataFrame()) if isinstance(price_pack, dict) else pd.DataFrame()
    bench_nav = price_pack.get("benchmark_nav", pd.Series(dtype=float)) if isinstance(price_pack, dict) else pd.Series(dtype=float)
    if source_rows is None or source_rows.empty or price.empty or "close" not in price.columns:
        return pd.DataFrame()

    close = pd.to_numeric(price["close"], errors="coerce").ffill()
    bench_nav = pd.to_numeric(bench_nav.reindex(price.index), errors="coerce").ffill().bfill()

    rows = []
    for _, r in source_rows.iterrows():
        pos = _v49x_decision_position(price.index, r.get("available_at"))
        if pos is None or pos >= len(price) - 1:
            continue
        entry_px = _safe_float(close.iloc[pos], np.nan)
        entry_bench = _safe_float(bench_nav.iloc[pos], np.nan)
        if pd.isna(entry_px) or entry_px <= 0 or pd.isna(entry_bench) or entry_bench <= 0:
            continue

        row = {
            "date": r.get("date"),
            "available_at": r.get("available_at"),
            "decision_date": price.index[pos],
            "ticker": r.get("ticker", ""),
            "feature_family": r.get("feature_family", identity.get("source_family", "N/A")),
            "feature_name": r.get("feature_name", identity.get("source_feature", "N/A")),
            "value": r.get("value", np.nan),
            "value_num": _safe_float(r.get("value"), np.nan),
            "source": r.get("source", "unknown_source"),
            "confidence": _safe_float(r.get("confidence"), np.nan),
            "notes": r.get("notes", ""),
        }
        for h in horizons:
            fpos = min(pos + int(h), len(price) - 1)
            asset_ret = _safe_float(close.iloc[fpos] / entry_px - 1.0, np.nan)
            bench_ret = _safe_float(bench_nav.iloc[fpos] / entry_bench - 1.0, np.nan)
            row[f"asset_return_{h}b"] = asset_ret
            row[f"benchmark_return_{h}b"] = bench_ret
            row[f"active_return_{h}b"] = asset_ret - bench_ret if pd.notna(asset_ret) and pd.notna(bench_ret) else np.nan
        rows.append(row)

    ev = pd.DataFrame(rows)
    if not ev.empty:
        ev = ev.sort_values("decision_date").reset_index(drop=True)
    return ev


def _v49x_rule_candidates(ev: pd.DataFrame, preferred_rule: str = "") -> pd.DataFrame:
    if ev is None or ev.empty:
        return pd.DataFrame(columns=["rule", "direction", "threshold", "sample", "avg_active_10b", "median_active_10b", "hit_10b", "avg_active_20b", "score", "read"])

    value_num = pd.to_numeric(ev.get("value_num"), errors="coerce")
    rows = []

    def _metrics(mask: pd.Series, rule: str, direction: str, threshold: Any, read: str) -> dict[str, Any]:
        sub = ev.loc[mask.fillna(False)].copy()
        r10 = pd.to_numeric(sub.get("active_return_10b"), errors="coerce").dropna() if not sub.empty else pd.Series(dtype=float)
        r20 = pd.to_numeric(sub.get("active_return_20b"), errors="coerce").dropna() if not sub.empty else pd.Series(dtype=float)
        sample = int(len(sub))
        avg10 = float(r10.mean()) if not r10.empty else np.nan
        med10 = float(r10.median()) if not r10.empty else np.nan
        hit10 = float((r10 > 0).mean()) if not r10.empty else np.nan
        avg20 = float(r20.mean()) if not r20.empty else np.nan
        score = 35.0 + min(sample, 20) * 1.5
        if pd.notna(avg10): score += float(np.clip(avg10 * 450.0, -25.0, 25.0))
        if pd.notna(med10) and med10 > 0: score += 8.0
        if pd.notna(hit10): score += float(np.clip((hit10 - 0.50) * 35.0, -15.0, 15.0))
        if pd.notna(avg20): score += float(np.clip(avg20 * 250.0, -12.0, 12.0))
        return {"rule": rule, "direction": direction, "threshold": threshold, "sample": sample, "avg_active_10b": avg10, "median_active_10b": med10, "hit_10b": hit10, "avg_active_20b": avg20, "score": max(0.0, min(100.0, score)), "read": read}

    if value_num.notna().sum() >= max(3, int(len(ev) * 0.40)):
        q25 = float(value_num.quantile(0.25))
        q50 = float(value_num.quantile(0.50))
        q75 = float(value_num.quantile(0.75))
        rows.append(_metrics(value_num >= q75, "value_top_quartile", "positive", q75, "Feature numérique dans le quartile supérieur."))
        rows.append(_metrics(value_num <= q25, "value_bottom_quartile", "negative", q25, "Feature numérique dans le quartile inférieur."))
        rows.append(_metrics(value_num >= q50, "value_above_median", "positive", q50, "Feature numérique au-dessus de la médiane."))
        rows.append(_metrics(value_num <= q50, "value_below_median", "negative", q50, "Feature numérique sous la médiane."))
    else:
        txt = ev.get("value", pd.Series("", index=ev.index)).astype(str).str.lower().str.strip()
        positive_mask = txt.isin(["positive", "bullish", "beat", "up", "true", "1", "yes"])
        negative_mask = txt.isin(["negative", "bearish", "miss", "down", "-1", "false", "no"])
        if positive_mask.any():
            rows.append(_metrics(positive_mask, "value_positive_tag", "positive", "positive", "Catégorie positive."))
        if negative_mask.any():
            rows.append(_metrics(negative_mask, "value_negative_tag", "negative", "negative", "Catégorie négative."))
        rows.append(_metrics(pd.Series(True, index=ev.index), "all_events", "positive", "any", "Toutes les observations de la source."))

    out = pd.DataFrame(rows)
    if out.empty:
        return out

    pref = _v49x_norm(preferred_rule)
    if pref:
        out["preferred"] = out["rule"].map(lambda x: 1 if _v49x_norm(x) == pref else 0)
    else:
        out["preferred"] = 0
    out = out.sort_values(["preferred", "score", "avg_active_10b", "sample"], ascending=[False, False, False, False]).reset_index(drop=True)
    return out


def _v49x_apply_rule(ev: pd.DataFrame, rule_row: pd.Series | dict[str, Any]) -> pd.Series:
    if ev is None or ev.empty:
        return pd.Series(dtype=bool)
    rule = _v49x_norm(rule_row.get("rule", "") if isinstance(rule_row, (pd.Series, dict)) else "")
    threshold = rule_row.get("threshold", np.nan) if isinstance(rule_row, (pd.Series, dict)) else np.nan
    value_num = pd.to_numeric(ev.get("value_num"), errors="coerce")
    txt = ev.get("value", pd.Series("", index=ev.index)).astype(str).str.lower().str.strip()
    if rule == "value_top_quartile" or rule == "value_above_median":
        return value_num >= _safe_float(threshold, np.nan)
    if rule == "value_bottom_quartile" or rule == "value_below_median":
        return value_num <= _safe_float(threshold, np.nan)
    if rule == "value_positive_tag":
        return txt.isin(["positive", "bullish", "beat", "up", "true", "1", "yes"])
    if rule == "value_negative_tag":
        return txt.isin(["negative", "bearish", "miss", "down", "-1", "false", "no"])
    return pd.Series(True, index=ev.index)


def _v49x_common_context(
    df: pd.DataFrame | None = None,
    cfg: Any = None,
    external_features: Any = None,
    v49g_pack: Any = None,
    v49g3_pack: Any = None,
    v49f1_pack: Any = None,
    v49f_pack: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    identity = _v49x_pick_source_identity(v49g_pack=v49g_pack, v49g3_pack=v49g3_pack, v49f1_pack=v49f1_pack, v49f_pack=v49f_pack)
    if cfg is not None and not str(ticker or "").strip():
        ticker = str(getattr(cfg, "asset_ticker", "") or "").upper().strip()
    source_rows = _v49x_candidate_source_rows(external_features, identity, ticker, v49g3_pack, v49g_pack, v49f1_pack, v49f_pack)
    price_pack = _v49x_build_price_and_benchmark(df, cfg=cfg, ticker=ticker)
    ev = _v49x_event_forward_map(source_rows, price_pack, identity)
    rule_candidates = _v49x_rule_candidates(ev, preferred_rule=identity.get("source_rule", ""))
    rule_row = rule_candidates.iloc[0].to_dict() if isinstance(rule_candidates, pd.DataFrame) and not rule_candidates.empty else {}
    rule_mask = _v49x_apply_rule(ev, rule_row) if not ev.empty else pd.Series(dtype=bool)
    rule_events = ev.loc[rule_mask.fillna(False)].copy() if not ev.empty else pd.DataFrame()
    return {
        "identity": identity,
        "ticker": ticker,
        "source_rows": source_rows,
        "price_pack": price_pack,
        "event_map": ev,
        "rule_candidates": rule_candidates,
        "rule_row": rule_row,
        "rule_events": rule_events,
        "benchmark_label": price_pack.get("benchmark_label", "N/A") if isinstance(price_pack, dict) else "N/A",
        "benchmark_fallback": bool(price_pack.get("benchmark_fallback", True)) if isinstance(price_pack, dict) else True,
        "upstream": {"v49g": v49g_pack if isinstance(v49g_pack, dict) else {}, "v49g3": v49g3_pack if isinstance(v49g3_pack, dict) else {}, "v49f1": v49f1_pack if isinstance(v49f1_pack, dict) else {}, "v49f": v49f_pack if isinstance(v49f_pack, dict) else {}},
    }


def _source_sufficiency_gate_v49h_pack(ctx: dict[str, Any]) -> dict[str, Any]:
    identity = ctx.get("identity", {})
    source_rows = ctx.get("source_rows", pd.DataFrame())
    ev = ctx.get("event_map", pd.DataFrame())
    rule_events = ctx.get("rule_events", pd.DataFrame())
    rule_row = ctx.get("rule_row", {})

    rows_total = int(len(source_rows)) if isinstance(source_rows, pd.DataFrame) else 0
    events_total = int(len(ev)) if isinstance(ev, pd.DataFrame) else 0
    rule_event_count = int(len(rule_events)) if isinstance(rule_events, pd.DataFrame) else 0
    unique_dates = int(pd.to_datetime(source_rows.get("available_at", pd.Series(dtype="datetime64[ns]")), errors="coerce").dt.normalize().nunique()) if rows_total else 0
    source_count = int(source_rows.get("source", pd.Series(dtype=str)).astype(str).replace("", np.nan).dropna().nunique()) if rows_total else 0
    feature_count = int(source_rows.get("feature_name", pd.Series(dtype=str)).astype(str).nunique()) if rows_total else 0
    missing_available = int(pd.to_datetime(source_rows.get("available_at", pd.Series(dtype="datetime64[ns]")), errors="coerce").isna().sum()) if rows_total else 0
    missing_value = int(source_rows.get("value", pd.Series(dtype=object)).isna().sum()) if rows_total else 0
    invalid_decision = max(0, rows_total - events_total)
    date_concentration = 1.0
    if rows_total and "available_at" in source_rows.columns:
        date_concentration = float(pd.to_datetime(source_rows["available_at"], errors="coerce").dt.normalize().value_counts(normalize=True).max())
    source_concentration = 1.0
    if rows_total and "source" in source_rows.columns:
        source_concentration = float(source_rows["source"].astype(str).value_counts(normalize=True).max())

    gates_rows = []
    def gate(name: str, status: str, severity: str, current: Any, required: str, read: str):
        gates_rows.append({"Gate": name, "Status": status, "Severity": severity, "Current": current, "Required": required, "Read": read})

    gate("Source rows", "PASS" if rows_total >= 30 else ("REVIEW" if rows_total >= 15 else "FAIL"), "High" if rows_total < 15 else "Medium" if rows_total < 30 else "None", rows_total, ">=30 preferred, >=15 review", "Nombre de lignes source candidates après filtre family/feature.")
    gate("Rule events", "PASS" if rule_event_count >= 8 else "FAIL", "Critical" if rule_event_count < 5 else "High", rule_event_count, ">=8 minimum", "Évènements qui passent la règle source-only choisie.")
    gate("Unique dates", "PASS" if unique_dates >= 6 else "FAIL", "High" if unique_dates < 6 else "None", unique_dates, ">=6 dates", "Évite une conclusion concentrée sur une seule date.")
    gate("Source diversity", "PASS" if source_count >= 2 else "REVIEW", "Medium" if source_count < 2 else "None", source_count, ">=2 providers/source tags", "Réduit le risque d'une source unique fragile.")
    gate("available_at quality", "PASS" if missing_available == 0 else "FAIL", "Critical" if missing_available else "None", missing_available, "0 missing", "Chaque feature doit avoir un timestamp de disponibilité causale.")
    gate("Forward map alignment", "PASS" if invalid_decision == 0 and events_total > 0 else "FAIL", "High" if invalid_decision else "None", f"{events_total}/{rows_total}", "all rows alignable", "Les lignes doivent être plaçables sur le calendrier prix après available_at.")
    gate("Value missingness", "PASS" if rows_total and missing_value / max(rows_total, 1) <= 0.05 else "REVIEW", "Medium" if missing_value else "None", missing_value, "<=5%", "Valeurs source manquantes avant construction de règle.")
    gate("Date concentration", "PASS" if date_concentration <= 0.40 or unique_dates >= 10 else "REVIEW", "Medium" if date_concentration > 0.40 else "None", date_concentration, "<=40% preferred", "Part de lignes concentrées sur la même date.")
    gate("Provider concentration", "PASS" if source_concentration <= 0.80 or source_count >= 3 else "REVIEW", "Medium" if source_concentration > 0.80 else "None", source_concentration, "<=80% preferred", "Risque de dépendance à un seul provider.")
    gate("Benchmark active map", "REVIEW" if ctx.get("benchmark_fallback", True) else "PASS", "Medium" if ctx.get("benchmark_fallback", True) else "None", ctx.get("benchmark_label", "N/A"), "external/sector benchmark preferred", "Active return forward doit être relatif à un benchmark exploitable.")

    gates = pd.DataFrame(gates_rows)
    fail_count = int((gates["Status"] == "FAIL").sum()) if not gates.empty else 0
    review_count = int((gates["Status"] == "REVIEW").sum()) if not gates.empty else 0
    critical_count = int(((gates["Status"] == "FAIL") & (gates["Severity"] == "Critical")).sum()) if not gates.empty else 0

    score = 100.0 - critical_count * 35.0 - max(0, fail_count - critical_count) * 18.0 - review_count * 7.0
    score = max(0.0, min(100.0, score))

    if critical_count > 0 or rule_event_count < 8 or missing_available > 0:
        level = "Source sufficiency blocked"
        decision = "EXPAND_SOURCE_SAMPLE_BEFORE_V49I"
        read = "V4.9H bloque : sample/rule events, available_at ou alignement insuffisant avant construction de signal source-only."
    elif fail_count > 0 or review_count >= 3:
        level = "Source sufficiency review"
        decision = "REVIEW_SOURCE_PROVENANCE_BEFORE_V49I"
        read = "V4.9H accepte la structure mais demande revue provenance/sample avant V4.9I."
    else:
        level = "Source sufficiency ready"
        decision = "READY_FOR_V49I_SOURCE_SIGNAL_CONSTRUCTION"
        read = "V4.9H valide la suffisance minimale de la source candidate pour construire un blueprint causal."

    summary = pd.DataFrame([
        ["V4.9H level", level, "Lecture synthétique de suffisance source."],
        ["V4.9H score", score, "Score qualité source, pas score alpha."],
        ["Decision", decision, "Décision avant V4.9I."],
        ["Read", read, "Interprétation opérationnelle."],
        ["Ticker", ctx.get("ticker", "N/A"), "Ticker audité."],
        ["Source family", identity.get("source_family", "N/A"), "Famille candidate."],
        ["Source feature", identity.get("source_feature", "N/A"), "Feature candidate."],
        ["Selected rule", rule_row.get("rule", identity.get("source_rule", "N/A")), "Règle source-only sélectionnée ou héritée."],
        ["Source rows", rows_total, "Lignes source candidates."],
        ["Forward mapped rows", events_total, "Lignes alignées au calendrier et forward-return calculables."],
        ["Rule events", rule_event_count, "Évènements qui passent la règle sélectionnée."],
        ["Unique available dates", unique_dates, "Dates source distinctes."],
        ["Source count", source_count, "Providers/source tags distincts."],
        ["Feature count", feature_count, "Nombre de features dans les lignes candidate."],
        ["Benchmark", ctx.get("benchmark_label", "N/A"), "Benchmark actif utilisé."],
    ], columns=["Metric", "Value", "Read"])

    next_actions = pd.DataFrame([
        {"Priority": "P0", "Action": "Do not promote", "Reason": decision, "Next Step": "Aucune source ne va au moteur tant que V4.9H ne passe pas."},
        {"Priority": "P0", "Action": "Expand rule events", "Reason": f"rule_events={rule_event_count}/8", "Next Step": "Ajouter des évènements réels sur la même source_feature avec available_at."},
        {"Priority": "P0", "Action": "Keep point-in-time", "Reason": "available_at mandatory", "Next Step": "Chaque nouvelle ligne doit garder available_at, source, confidence et aucune colonne outcome."},
        {"Priority": "P1", "Action": "Add provider diversity", "Reason": f"sources={source_count}", "Next Step": "Ajouter au moins un provider/source tag distinct si possible."},
        {"Priority": "P1", "Action": "Proceed to V4.9I only if pass", "Reason": "source sufficiency", "Next Step": "Construire le blueprint causal uniquement après PASS ou REVIEW contrôlé."},
    ])

    cards = [
        {"label": "V4.9H gate", "value": level, "delta": f"{_format_num(score,0)}/100"},
        {"label": "Rule events", "value": f"{rule_event_count}/8", "delta": "source-only"},
        {"label": "Source rows", "value": str(rows_total), "delta": "candidate"},
        {"label": "Unique dates", "value": str(unique_dates), "delta": "spread"},
        {"label": "Sources", "value": f"{source_count}/2", "delta": "providers"},
        {"label": "Decision", "value": decision, "delta": "research only"},
    ]

    return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": cards, "summary": summary, "gates": gates, "next_actions": next_actions, "rule_events": rule_events, "rule_row": rule_row, "rule_event_count": rule_event_count, "source_rows": rows_total, "source_count": source_count, "unique_dates": unique_dates}


def _causal_source_signal_construction_lab_v49i_pack(ctx: dict[str, Any], h_pack: dict[str, Any]) -> dict[str, Any]:
    identity = ctx.get("identity", {})
    ev = ctx.get("event_map", pd.DataFrame())
    candidates = ctx.get("rule_candidates", pd.DataFrame())
    rule_row = ctx.get("rule_row", {})
    rule_events = h_pack.get("rule_events", pd.DataFrame())
    source_feature = identity.get("source_feature", "N/A")
    source_family = identity.get("source_family", "N/A")
    rule = rule_row.get("rule", "N/A")
    threshold = rule_row.get("threshold", "N/A")
    direction = rule_row.get("direction", "positive")

    h_pass = str(h_pack.get("decision", "")).startswith("READY_FOR_V49I")
    sample = int(len(rule_events)) if isinstance(rule_events, pd.DataFrame) else 0

    blueprint = pd.DataFrame([
        ["source_id", f"SRC-V49-{_v49x_norm(source_family).upper()}-{_v49x_norm(source_feature).upper()}", "Identifiant stable de recherche, non moteur."],
        ["ticker", ctx.get("ticker", "N/A"), "Ticker source."],
        ["source_family", source_family, "Famille externe causale."],
        ["source_feature", source_feature, "Feature externe sélectionnée."],
        ["rule", rule, "Règle source-only retenue."],
        ["threshold", threshold, "Seuil de la règle."],
        ["direction", direction, "Direction économique de la règle."],
        ["available_at_policy", "mandatory point-in-time", "Aucune ligne sans available_at ne peut entrer dans le blueprint."],
        ["decision_bar_policy", "strict t+1 after available_at", "La décision est placée au bar de trading suivant la disponibilité."],
        ["holding_horizons", "3B / 5B / 10B / 20B", "Horizons de mesure source-only, pas exits moteur."],
        ["benchmark_policy", ctx.get("benchmark_label", "N/A"), "Active return mesuré vs benchmark."],
        ["engine_injection", "forbidden", "V4.9I ne modifie pas le moteur ni le signal existant."],
        ["oos_permission", "forbidden before V4.9J/V4.9K", "Pas de passage OOS/live depuis V4.9I."],
    ], columns=["Field", "Value", "Read"])

    schema = pd.DataFrame([
        {"Column": "date", "Type": "datetime/date", "Requirement": "event/economic date", "Leakage rule": "not used as decision bar if available_at differs"},
        {"Column": "available_at", "Type": "datetime", "Requirement": "mandatory", "Leakage rule": "decision bar must be strictly after available_at"},
        {"Column": "ticker", "Type": "string", "Requirement": "mandatory", "Leakage rule": "must match audited ticker"},
        {"Column": "feature_family", "Type": "string", "Requirement": "mandatory", "Leakage rule": "stable taxonomy"},
        {"Column": "feature_name", "Type": "string", "Requirement": "mandatory", "Leakage rule": "stable taxonomy"},
        {"Column": "value", "Type": "float/string", "Requirement": "mandatory", "Leakage rule": "no realized_alpha / future_return / pnl labels"},
        {"Column": "source", "Type": "string", "Requirement": "mandatory", "Leakage rule": "provider/source audit retained"},
        {"Column": "confidence", "Type": "float", "Requirement": "recommended", "Leakage rule": "quality metadata only"},
    ])

    if not h_pass:
        level = "Signal blueprint blocked by H"
        score = max(0.0, min(60.0, _safe_float(h_pack.get("score", 0.0), 0.0) * 0.75))
        decision = "WAIT_FOR_V49H_PASS_BEFORE_V49I"
        read = "V4.9I prépare le contrat, mais ne valide pas de blueprint actif tant que V4.9H bloque la source."
    elif sample < 8:
        level = "Signal blueprint low sample"
        score = 55.0
        decision = "SOURCE_RULE_TOO_FRAGILE"
        read = "La règle existe mais l'échantillon d'évènements reste trop faible pour un blueprint exploitable."
    else:
        level = "Causal source signal blueprint ready"
        score = min(100.0, 70.0 + min(sample, 20))
        decision = "SOURCE_SIGNAL_BLUEPRINT_READY_FOR_V49J"
        read = "V4.9I construit un blueprint causal t+1 exploitable pour validation événementielle V4.9J."

    summary = pd.DataFrame([
        ["V4.9I level", level, "Lecture synthétique du blueprint causal."],
        ["V4.9I score", score, "Score de construction source-only, pas score moteur."],
        ["Decision", decision, "Décision avant holdout V4.9J."],
        ["Read", read, "Interprétation opérationnelle."],
        ["Source family", source_family, "Famille retenue."],
        ["Source feature", source_feature, "Feature retenue."],
        ["Selected rule", rule, "Règle retenue."],
        ["Threshold", threshold, "Seuil utilisé."],
        ["Rule events", sample, "Évènements utilisables par la règle."],
        ["t+1 enforcement", "strict", "Blueprint causal uniquement."],
    ], columns=["Metric", "Value", "Read"])

    cards = [
        {"label": "V4.9I blueprint", "value": level, "delta": f"{_format_num(score,0)}/100"},
        {"label": "Source", "value": source_feature, "delta": source_family},
        {"label": "Rule", "value": rule, "delta": "t+1"},
        {"label": "Events", "value": str(sample), "delta": "rule sample"},
        {"label": "Decision", "value": decision, "delta": "research only"},
    ]

    next_actions = pd.DataFrame([
        {"Priority": "P0", "Action": "Do not inject signal", "Reason": "V4.9I is blueprint only", "Next Step": "Le moteur reste inchangé."},
        {"Priority": "P0", "Action": "Enforce t+1", "Reason": "available_at causality", "Next Step": "Toutes les décisions utilisent le bar suivant available_at."},
        {"Priority": "P1", "Action": "Run V4.9J holdout", "Reason": decision, "Next Step": "Valider early/late event stability avant promotion."},
    ])

    return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": cards, "summary": summary, "blueprint": blueprint, "schema": schema, "rule_leaderboard": candidates if isinstance(candidates, pd.DataFrame) else pd.DataFrame(), "next_actions": next_actions, "rule_row": rule_row, "rule_events": rule_events}


def _event_holdout_source_validation_v49j_pack(ctx: dict[str, Any], h_pack: dict[str, Any], i_pack: dict[str, Any]) -> dict[str, Any]:
    rule_events = i_pack.get("rule_events", pd.DataFrame())
    if rule_events is None or not isinstance(rule_events, pd.DataFrame) or rule_events.empty:
        rule_events = pd.DataFrame()

    ev = rule_events.sort_values("decision_date").copy() if not rule_events.empty else pd.DataFrame()
    n = int(len(ev))
    split = int(max(1, np.floor(n * 0.70))) if n > 1 else n
    train = ev.iloc[:split].copy() if n else pd.DataFrame()
    holdout = ev.iloc[split:].copy() if n > split else pd.DataFrame()

    def stats(label: str, sub: pd.DataFrame) -> dict[str, Any]:
        row = {"Segment": label, "Events": int(len(sub))}
        for h in [3, 5, 10, 20]:
            r = pd.to_numeric(sub.get(f"active_return_{h}b", pd.Series(dtype=float)), errors="coerce").dropna()
            row[f"avg_active_{h}b"] = float(r.mean()) if not r.empty else np.nan
            row[f"median_active_{h}b"] = float(r.median()) if not r.empty else np.nan
            row[f"hit_{h}b"] = float((r > 0).mean()) if not r.empty else np.nan
            row[f"worst_active_{h}b"] = float(r.min()) if not r.empty else np.nan
        return row

    summary_map = pd.DataFrame([stats("Full", ev), stats("Train early events", train), stats("Holdout late events", holdout)]) if n else pd.DataFrame()
    holdout_n = int(len(holdout))
    holdout_avg10 = _safe_float(summary_map.loc[summary_map["Segment"] == "Holdout late events", "avg_active_10b"].iloc[0], np.nan) if not summary_map.empty else np.nan
    holdout_hit10 = _safe_float(summary_map.loc[summary_map["Segment"] == "Holdout late events", "hit_10b"].iloc[0], np.nan) if not summary_map.empty else np.nan
    full_avg10 = _safe_float(summary_map.loc[summary_map["Segment"] == "Full", "avg_active_10b"].iloc[0], np.nan) if not summary_map.empty else np.nan

    event_map = ev.copy()
    if not event_map.empty:
        event_map["holdout_segment"] = np.where(np.arange(len(event_map)) < split, "TRAIN_EARLY", "HOLDOUT_LATE")
        event_map["rule"] = i_pack.get("rule_row", {}).get("rule", "N/A")
        event_map["benchmark"] = ctx.get("benchmark_label", "N/A")

    if n < 8:
        level = "Holdout blocked / low events"
        score = 25.0 + n * 3.0
        decision = "EXPAND_EVENTS_BEFORE_V49K"
        read = "V4.9J ne peut pas valider le holdout : échantillon d'évènements trop faible."
    elif holdout_n < 3:
        level = "Holdout review / thin test"
        score = 45.0
        decision = "HOLDOUT_SOURCE_WATCH_ONLY"
        read = "Holdout calculé mais test trop fin pour promotion." 
    elif pd.notna(holdout_avg10) and holdout_avg10 > 0 and pd.notna(holdout_hit10) and holdout_hit10 >= 0.55:
        level = "Holdout source validated"
        score = min(100.0, 70.0 + holdout_avg10 * 500.0 + (holdout_hit10 - 0.5) * 40.0)
        decision = "HOLDOUT_SOURCE_VALIDATED_FOR_V49K"
        read = "V4.9J valide un holdout événementiel positif à confirmer par governance V4.9K."
    elif pd.notna(holdout_avg10) and holdout_avg10 > 0:
        level = "Holdout source watch"
        score = 58.0
        decision = "HOLDOUT_SOURCE_WATCH_ONLY"
        read = "Holdout positif mais hit-rate ou robustesse insuffisante : source watch uniquement."
    else:
        level = "Holdout source rejected"
        score = 35.0
        decision = "HOLDOUT_SOURCE_REJECTED"
        read = "V4.9J ne confirme pas l'active return en holdout." 

    summary = pd.DataFrame([
        ["V4.9J level", level, "Lecture synthétique holdout."],
        ["V4.9J score", score, "Score holdout événementiel."],
        ["Decision", decision, "Décision avant V4.9K."],
        ["Read", read, "Interprétation opérationnelle."],
        ["Full events", n, "Évènements source-only passés par la règle."],
        ["Train events", int(len(train)), "Première partie chronologique."],
        ["Holdout events", holdout_n, "Dernière partie chronologique."],
        ["Full avg active 10B", full_avg10, "Moyenne active 10B full sample."],
        ["Holdout avg active 10B", holdout_avg10, "Moyenne active 10B holdout."],
        ["Holdout hit 10B", holdout_hit10, "Hit-rate actif 10B holdout."],
    ], columns=["Metric", "Value", "Read"])

    cards = [
        {"label": "V4.9J holdout", "value": level, "delta": f"{_format_num(score,0)}/100"},
        {"label": "Events", "value": str(n), "delta": "rule sample"},
        {"label": "Holdout n", "value": str(holdout_n), "delta": "late events"},
        {"label": "Holdout 10B", "value": _format_pct(holdout_avg10), "delta": "active"},
        {"label": "Hit 10B", "value": _format_pct(holdout_hit10), "delta": "holdout"},
        {"label": "Decision", "value": decision, "delta": "research only"},
    ]

    next_actions = pd.DataFrame([
        {"Priority": "P0", "Action": "Do not OOS promote", "Reason": decision, "Next Step": "V4.9K décide uniquement après H/I/J."},
        {"Priority": "P1", "Action": "Increase late events", "Reason": f"holdout_n={holdout_n}", "Next Step": "Ajouter des observations récentes point-in-time."},
        {"Priority": "P1", "Action": "Check horizon stability", "Reason": "3B/5B/10B/20B", "Next Step": "Ne pas sélectionner une source positive sur un seul horizon isolé."},
    ])

    return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": cards, "summary": summary, "holdout_matrix": summary_map, "event_map": event_map, "next_actions": next_actions, "holdout_avg_active_10b": holdout_avg10, "full_avg_active_10b": full_avg10, "holdout_n": holdout_n}


def _source_promotion_governance_gate_v49k_pack(ctx: dict[str, Any], h_pack: dict[str, Any], i_pack: dict[str, Any], j_pack: dict[str, Any]) -> dict[str, Any]:
    h_dec = str(h_pack.get("decision", ""))
    i_dec = str(i_pack.get("decision", ""))
    j_dec = str(j_pack.get("decision", ""))
    source_count = int(h_pack.get("source_count", 0) or 0)
    rule_events = int(h_pack.get("rule_event_count", 0) or 0)
    holdout_avg10 = _safe_float(j_pack.get("holdout_avg_active_10b"), np.nan)
    holdout_n = int(j_pack.get("holdout_n", 0) or 0)

    gates_rows = []
    def gate(name: str, status: str, severity: str, current: Any, required: str, read: str):
        gates_rows.append({"Gate": name, "Status": status, "Severity": severity, "Current": current, "Required": required, "Read": read})

    gate("V4.9H source sufficiency", "PASS" if h_dec.startswith("READY_FOR_V49I") else "FAIL", "Critical", h_dec, "READY_FOR_V49I", "La source doit passer sample/provenance.")
    gate("V4.9I blueprint", "PASS" if i_dec.startswith("SOURCE_SIGNAL_BLUEPRINT_READY") else ("REVIEW" if "WAIT" not in i_dec else "FAIL"), "High", i_dec, "SOURCE_SIGNAL_BLUEPRINT_READY", "La règle t+1 doit être définie sans moteur.")
    gate("V4.9J holdout", "PASS" if j_dec.startswith("HOLDOUT_SOURCE_VALIDATED") else ("REVIEW" if "WATCH" in j_dec else "FAIL"), "High", j_dec, "HOLDOUT_SOURCE_VALIDATED", "La source doit garder un edge en late holdout.")
    gate("Rule event count", "PASS" if rule_events >= 8 else "FAIL", "High", rule_events, ">=8", "Minimum d'évènements de règle.")
    gate("Provider diversity", "PASS" if source_count >= 2 else "REVIEW", "Medium", source_count, ">=2", "Diversité source recommandée avant registry.")
    gate("Holdout active 10B", "PASS" if pd.notna(holdout_avg10) and holdout_avg10 > 0 else "FAIL", "High", holdout_avg10, ">0", "Le forward active return holdout doit être positif.")
    gate("Holdout sample", "PASS" if holdout_n >= 3 else "REVIEW", "Medium", holdout_n, ">=3 late events", "Minimum pratique pour éviter un holdout anecdotique.")
    gate("Paper/live permission", "BLOCK", "Critical", "not allowed", "never from V4.9K", "Même promue, la source reste research/tournament only.")

    gates = pd.DataFrame(gates_rows)
    fail_core = int(((gates["Status"] == "FAIL") & (gates["Gate"] != "Paper/live permission")).sum())
    review_core = int((gates["Status"] == "REVIEW").sum())

    if fail_core == 0 and j_dec.startswith("HOLDOUT_SOURCE_VALIDATED"):
        level = "Source promotion ready for V5 registry"
        decision = "PROMOTE_SOURCE_TO_V50_REGISTRY"
        score = max(75.0, min(100.0, (h_pack.get("score", 0) + i_pack.get("score", 0) + j_pack.get("score", 0)) / 3.0))
        read = "V4.9K autorise l'enregistrement registry research/tournament, pas le live/paper." 
    elif fail_core <= 1 and review_core >= 1:
        level = "Source promotion watch"
        decision = "WATCHLIST_SOURCE_REQUIRES_MORE_EVENTS"
        score = 55.0
        read = "V4.9K garde la source en watch : données ou holdout encore insuffisants." 
    else:
        level = "Source promotion rejected"
        decision = "REJECT_SOURCE_DO_NOT_PROMOTE"
        score = 25.0
        read = "V4.9K rejette la promotion : H/I/J ne confirment pas assez la source." 

    summary = pd.DataFrame([
        ["V4.9K level", level, "Lecture synthétique du gate de promotion."],
        ["V4.9K score", score, "Score governance, pas score live."],
        ["Decision", decision, "Décision avant V5.0 registry."],
        ["Read", read, "Interprétation opérationnelle."],
        ["H decision", h_dec, "Décision source sufficiency."],
        ["I decision", i_dec, "Décision blueprint."],
        ["J decision", j_dec, "Décision holdout."],
        ["Paper/live", "blocked", "Pas de live/paper depuis cette couche."],
    ], columns=["Metric", "Value", "Read"])

    next_actions = pd.DataFrame([
        {"Priority": "P0", "Action": "No paper/live", "Reason": "governance rule", "Next Step": "Même une source promue reste research-only."},
        {"Priority": "P0", "Action": "Register only if V5 allowed", "Reason": decision, "Next Step": "V5.0 devient registry / handoff vers tournament, pas moteur."},
        {"Priority": "P1", "Action": "If watch, expand sample", "Reason": f"rule_events={rule_events}, holdout_n={holdout_n}", "Next Step": "Ajouter évènements réels et rerun H/I/J/K."},
    ])

    cards = [
        {"label": "V4.9K promotion", "value": level, "delta": f"{_format_num(score,0)}/100"},
        {"label": "H/I/J", "value": f"{h_dec[:12]} / {i_dec[:12]} / {j_dec[:12]}", "delta": "gates"},
        {"label": "Rule events", "value": str(rule_events), "delta": "min 8"},
        {"label": "Holdout 10B", "value": _format_pct(holdout_avg10), "delta": f"n={holdout_n}"},
        {"label": "Decision", "value": decision, "delta": "registry only"},
    ]

    return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": cards, "summary": summary, "gates": gates, "next_actions": next_actions}


def _external_source_registry_handoff_v50_pack(ctx: dict[str, Any], h_pack: dict[str, Any], i_pack: dict[str, Any], j_pack: dict[str, Any], k_pack: dict[str, Any]) -> dict[str, Any]:
    identity = ctx.get("identity", {})
    rule_row = i_pack.get("rule_row", {})
    k_dec = str(k_pack.get("decision", ""))
    source_family = identity.get("source_family", "N/A")
    source_feature = identity.get("source_feature", "N/A")
    source_id = f"SRC-V50-{_v49x_norm(source_family).upper()}-{_v49x_norm(source_feature).upper()}"

    if k_dec == "PROMOTE_SOURCE_TO_V50_REGISTRY":
        registry_status = "SOURCE_REGISTERED_FOR_TOURNAMENT_TEST"
        level = "V5 registry tournament-ready"
        score = 80.0
        read = "V5.0 enregistre la source pour Strategy Tournament / OOS ultérieur, sans injection moteur automatique."
    elif "WATCH" in k_dec:
        registry_status = "SOURCE_REGISTERED_RESEARCH_ONLY"
        level = "V5 registry research-only"
        score = 55.0
        read = "V5.0 garde la source en registry research-only : sample/holdout à renforcer." 
    else:
        registry_status = "SOURCE_REJECTED_NOT_REGISTERED"
        level = "V5 registry rejected"
        score = 20.0
        read = "V5.0 ne doit pas enregistrer la source comme candidat actif." 

    registry = pd.DataFrame([
        ["source_id", source_id, "Identifiant source stable."],
        ["ticker", ctx.get("ticker", "N/A"), "Ticker audité."],
        ["source_family", source_family, "Famille source externe."],
        ["source_feature", source_feature, "Feature source externe."],
        ["source_rule", rule_row.get("rule", "N/A"), "Règle source-only."],
        ["threshold", rule_row.get("threshold", "N/A"), "Seuil règle."],
        ["direction", rule_row.get("direction", "N/A"), "Direction économique."],
        ["available_at_policy", "mandatory point-in-time", "Timestamp obligatoire."],
        ["decision_policy", "strict t+1 after available_at", "Décision causale."],
        ["benchmark", ctx.get("benchmark_label", "N/A"), "Benchmark actif utilisé."],
        ["h_status", h_pack.get("decision", "N/A"), "Gate sufficiency."],
        ["i_status", i_pack.get("decision", "N/A"), "Gate blueprint."],
        ["j_status", j_pack.get("decision", "N/A"), "Gate holdout."],
        ["k_status", k_pack.get("decision", "N/A"), "Gate promotion."],
        ["registry_status", registry_status, "Statut V5.0."],
        ["handoff_target", "Strategy Tournament / external source lab", "Destination autorisée."],
        ["forbidden_target", "paper/live/direct engine injection", "Interdit à ce stade."],
    ], columns=["Field", "Value", "Read"])

    handoff = pd.DataFrame([
        {"Step": "V5.0-A", "Action": "Store source spec", "Allowed": registry_status != "SOURCE_REJECTED_NOT_REGISTERED", "Read": "Enregistrer source_id, feature, rule, threshold, available_at policy."},
        {"Step": "V5.0-B", "Action": "Generate tournament candidate", "Allowed": registry_status == "SOURCE_REGISTERED_FOR_TOURNAMENT_TEST", "Read": "Créer un candidat de test isolé, sans modifier la stratégie courante."},
        {"Step": "V5.0-C", "Action": "Run OOS/WF later", "Allowed": registry_status == "SOURCE_REGISTERED_FOR_TOURNAMENT_TEST", "Read": "Le vrai OOS reste une étape ultérieure contrôlée."},
        {"Step": "V5.0-D", "Action": "Block paper/live", "Allowed": True, "Read": "Aucune promotion opérationnelle directe."},
    ])

    summary = pd.DataFrame([
        ["V5.0 level", level, "Lecture synthétique registry."],
        ["V5.0 score", score, "Score handoff registry."],
        ["Decision", registry_status, "Décision V5.0."],
        ["Read", read, "Interprétation opérationnelle."],
        ["source_id", source_id, "Identifiant généré."],
        ["handoff", "Strategy Tournament / source lab", "Destination autorisée."],
        ["engine impact", "none", "Aucune modification moteur."],
    ], columns=["Metric", "Value", "Read"])

    cards = [
        {"label": "V5.0 registry", "value": level, "delta": f"{_format_num(score,0)}/100"},
        {"label": "Source ID", "value": source_id, "delta": "registry"},
        {"label": "Status", "value": registry_status, "delta": "research"},
        {"label": "Handoff", "value": "Tournament" if registry_status == "SOURCE_REGISTERED_FOR_TOURNAMENT_TEST" else "Research only", "delta": "no live"},
    ]

    next_actions = pd.DataFrame([
        {"Priority": "P0", "Action": "Do not edit engine", "Reason": registry_status, "Next Step": "V5.0 est registry/handoff, pas injection."},
        {"Priority": "P1", "Action": "Use source_id for future tests", "Reason": source_id, "Next Step": "Tous les tests ultérieurs doivent référencer source_id et rule."},
        {"Priority": "P1", "Action": "Prepare tournament only if allowed", "Reason": registry_status, "Next Step": "Passage à Strategy Tournament seulement si V4.9K promeut."},
    ])

    return {"enabled": True, "level": level, "score": score, "decision": registry_status, "read": read, "cards": cards, "summary": summary, "registry": registry, "handoff": handoff, "next_actions": next_actions, "source_id": source_id}


def _complete_source_validation_v49h_to_v50_pack(
    df: pd.DataFrame | None = None,
    cfg: Any = None,
    external_features: Any = None,
    v49g_pack: Any = None,
    v49g3_pack: Any = None,
    v49f1_pack: Any = None,
    v49f_pack: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    try:
        ctx = _v49x_common_context(df=df, cfg=cfg, external_features=external_features, v49g_pack=v49g_pack, v49g3_pack=v49g3_pack, v49f1_pack=v49f1_pack, v49f_pack=v49f_pack, ticker=ticker)
        h = _source_sufficiency_gate_v49h_pack(ctx)
        i = _causal_source_signal_construction_lab_v49i_pack(ctx, h)
        j = _event_holdout_source_validation_v49j_pack(ctx, h, i)
        k = _source_promotion_governance_gate_v49k_pack(ctx, h, i, j)
        v5 = _external_source_registry_handoff_v50_pack(ctx, h, i, j, k)
        return {"enabled": True, "context": ctx, "v49h": h, "v49i": i, "v49j": j, "v49k": k, "v50": v5, "level": v5.get("level", k.get("level", "N/A")), "score": v5.get("score", k.get("score", 0.0)), "decision": v5.get("decision", k.get("decision", "N/A")), "read": v5.get("read", k.get("read", "")), "top_family": ctx.get("identity", {}).get("source_family", "N/A"), "top_feature": ctx.get("identity", {}).get("source_feature", "N/A"), "top_rule": i.get("rule_row", {}).get("rule", "N/A"), "rule_event_count": h.get("rule_event_count", 0), "source_rows": h.get("source_rows", 0), "source_count": h.get("source_count", 0), "unique_dates": h.get("unique_dates", 0), "full_avg_active_10b": j.get("full_avg_active_10b", np.nan), "oos_avg_active_10b": j.get("holdout_avg_active_10b", np.nan)}
    except Exception as exc:
        err = pd.DataFrame([["V4.9H-V5.0 error", str(exc), "Erreur capturée sans impact moteur."]], columns=["Metric", "Value", "Read"])
        safe = {"enabled": False, "level": "V4.9H-V5.0 error", "score": 0.0, "decision": "V49H_TO_V50_ERROR_SAFE_SKIP", "read": f"Erreur capturée sans impact moteur : {exc}", "summary": err}
        return {"enabled": False, "v49h": safe, "v49i": safe, "v49j": safe, "v49k": safe, "v50": safe, "level": safe["level"], "score": 0.0, "decision": safe["decision"], "read": safe["read"]}


def _v49x_render_pack_section(title: str, caption: str, pack: dict[str, Any], table_keys: list[tuple[str, str, bool]], download_keys: list[tuple[str, str, str]] | None = None) -> None:
    st.subheader(title)
    st.caption(caption)
    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass
    read = str(pack.get("read", ""))
    decision = str(pack.get("decision", ""))
    level = str(pack.get("level", ""))
    if any(tok in decision.lower() for tok in ["reject", "block", "wait", "expand"]) or "blocked" in level.lower():
        st.warning(f"Lecture {title.split(' — ')[0]} : {read}")
    elif any(tok in decision.lower() for tok in ["ready", "validated", "promote", "registered"]):
        st.success(f"Lecture {title.split(' — ')[0]} : {read}")
    else:
        st.info(f"Lecture {title.split(' — ')[0]} : {read}")

    for label, key, expanded in table_keys:
        with st.expander(label, expanded=expanded):
            tab = pack.get(key, pd.DataFrame()) if isinstance(pack, dict) else pd.DataFrame()
            if isinstance(tab, pd.DataFrame) and not tab.empty:
                st.dataframe(_v49x_pct_or_num_display(tab), use_container_width=True, hide_index=True)
            else:
                st.info(f"{label} indisponible.")

    download_keys = download_keys or []
    if download_keys:
        cols = st.columns(min(3, len(download_keys)))
        for col, (label, key, filename) in zip(cols, download_keys):
            tab = pack.get(key, pd.DataFrame()) if isinstance(pack, dict) else pd.DataFrame()
            if isinstance(tab, pd.DataFrame) and not tab.empty:
                col.download_button(label, data=tab.to_csv(index=False).encode("utf-8"), file_name=filename, mime="text/csv", use_container_width=True, key=f"bt_{filename.replace('.', '_')}_download")


def _render_complete_source_validation_v49h_to_v50(
    df: pd.DataFrame | None = None,
    cfg: Any = None,
    external_features: Any = None,
    v49g_pack: Any = None,
    v49g3_pack: Any = None,
    v49f1_pack: Any = None,
    v49f_pack: Any = None,
    ticker: str = "",
) -> dict[str, Any]:
    """Renderer principal : cinq sections complètes, sans sous-versions."""
    pack = _complete_source_validation_v49h_to_v50_pack(df=df, cfg=cfg, external_features=external_features, v49g_pack=v49g_pack, v49g3_pack=v49g3_pack, v49f1_pack=v49f1_pack, v49f_pack=v49f_pack, ticker=ticker)

    st.markdown("---")
    _v49x_render_pack_section(
        "V4.9H — Source Sufficiency & Causal Event Validation Gate",
        "Section complète lecture seule : sample source, rule events, dates, providers, available_at, alignement calendrier, concentration et actions. Aucun moteur modifié.",
        pack.get("v49h", {}),
        [("V4.9H source sufficiency summary", "summary", True), ("V4.9H source sufficiency gates", "gates", True), ("V4.9H next controlled actions", "next_actions", True), ("V4.9H rule event sample", "rule_events", False)],
        [("Télécharger V4.9H gates CSV", "gates", "v49h_source_sufficiency_gates.csv"), ("Télécharger V4.9H rule events CSV", "rule_events", "v49h_rule_events.csv")],
    )

    _v49x_render_pack_section(
        "V4.9I — Causal Source-Only Signal Construction Lab",
        "Section complète lecture seule : source_id, règle, seuil, direction, available_at policy, t+1, schema signal et leaderboard de règles. Aucun signal moteur injecté.",
        pack.get("v49i", {}),
        [("V4.9I construction summary", "summary", True), ("V4.9I causal signal blueprint", "blueprint", True), ("V4.9I signal schema contract", "schema", True), ("V4.9I rule leaderboard", "rule_leaderboard", False), ("V4.9I next controlled actions", "next_actions", True)],
        [("Télécharger V4.9I blueprint CSV", "blueprint", "v49i_causal_source_signal_blueprint.csv"), ("Télécharger V4.9I rule leaderboard CSV", "rule_leaderboard", "v49i_rule_leaderboard.csv")],
    )

    _v49x_render_pack_section(
        "V4.9J — Event Holdout / Walk-Forward Source Validation",
        "Section complète lecture seule : split chronologique early/late, active returns 3B/5B/10B/20B, hit-rate, worst event et stabilité holdout. Aucun OOS moteur lancé.",
        pack.get("v49j", {}),
        [("V4.9J holdout summary", "summary", True), ("V4.9J train/holdout horizon matrix", "holdout_matrix", True), ("V4.9J event-level forward active return map", "event_map", False), ("V4.9J next controlled actions", "next_actions", True)],
        [("Télécharger V4.9J holdout matrix CSV", "holdout_matrix", "v49j_holdout_matrix.csv"), ("Télécharger V4.9J event map CSV", "event_map", "v49j_event_holdout_map.csv")],
    )

    _v49x_render_pack_section(
        "V4.9K — Source Promotion / Rejection Governance Gate",
        "Section complète lecture seule : consolidation H/I/J, permission registry, blocage paper/live, watch/reject/promote. Aucun verdict principal modifié.",
        pack.get("v49k", {}),
        [("V4.9K promotion summary", "summary", True), ("V4.9K promotion gates", "gates", True), ("V4.9K next controlled actions", "next_actions", True)],
        [("Télécharger V4.9K promotion gates CSV", "gates", "v49k_promotion_gates.csv")],
    )

    _v49x_render_pack_section(
        "V5.0 — External Source Registry & Strategy Handoff Layer",
        "Section complète lecture seule : registry source_id, règle causale, statut, handoff tournament/source lab, interdiction paper/live/direct engine. Aucun moteur modifié.",
        pack.get("v50", {}),
        [("V5.0 registry summary", "summary", True), ("V5.0 source registry", "registry", True), ("V5.0 handoff protocol", "handoff", True), ("V5.0 next controlled actions", "next_actions", True)],
        [("Télécharger V5.0 source registry CSV", "registry", "v50_external_source_registry.csv"), ("Télécharger V5.0 handoff CSV", "handoff", "v50_source_handoff_protocol.csv")],
    )

    return pack


# Backward-compatible alias: si un ancien appel traîne encore, il affiche quand même les sections complètes.
def _render_source_validation_suite_v49h_to_v50(*args: Any, **kwargs: Any) -> dict[str, Any]:
    return _render_complete_source_validation_v49h_to_v50(*args, **kwargs)


# ============================================================
# END V4.9H / V4.9I / V4.9J / V4.9K / V5.0 COMPLETE SECTIONS PATCH
# ============================================================


# ============================================================
# V4.9H SOURCE SUFFICIENCY GATE — DATA GATE VS ALPHA REVIEW FIX
# Replace _source_sufficiency_gate_v49h_pack only
# ============================================================

def _source_sufficiency_gate_v49h_pack(ctx: dict[str, Any]) -> dict[str, Any]:
    """
    V4.9H — Source Sufficiency & Causal Event Validation Gate.

    Correctif objectif :
    - V4.9G.3 data/provenance BLOCK reste un vrai hard block.
    - V4.9G hard technical/data block reste un vrai hard block.
    - V4.9G negative alpha/rejected review n'est plus un hard block de suffisance H.
      C'est un alpha-review warning transmis à V4.9J/V4.9K.
    - H décide donc sur sample/provenance/available_at/rule events.
    - J/K restent responsables de rejeter la source si le holdout est négatif.
    - Lecture seule : aucun moteur, signal, trade, equity curve, sizing, exit ou verdict n'est modifié.
    """
    def _as_dict(x: Any) -> dict[str, Any]:
        return x if isinstance(x, dict) else {}

    def _norm_txt(x: Any) -> str:
        return str(x or "").strip().upper()

    def _gate_row(
        name: str,
        status: str,
        severity: str,
        current: Any,
        required: str,
        read: str,
    ) -> dict[str, Any]:
        return {
            "Gate": str(name),
            "Status": str(status),
            "Severity": str(severity),
            "Current": current,
            "Required": str(required),
            "Read": str(read),
        }

    def _safe_nunique_date(df: pd.DataFrame, col: str) -> int:
        try:
            if df is None or df.empty or col not in df.columns:
                return 0
            s = pd.to_datetime(df[col], errors="coerce").dropna().dt.normalize()
            return int(s.nunique())
        except Exception:
            return 0

    def _safe_concentration(df: pd.DataFrame, col: str, date_mode: bool = False) -> float:
        try:
            if df is None or df.empty or col not in df.columns:
                return 1.0
            if date_mode:
                s = pd.to_datetime(df[col], errors="coerce").dropna().dt.normalize()
            else:
                s = df[col].astype(str).replace("", np.nan).dropna()
            if s.empty:
                return 1.0
            vc = s.value_counts(normalize=True)
            return float(vc.max()) if not vc.empty else 1.0
        except Exception:
            return 1.0

    identity = _as_dict(ctx.get("identity", {}))
    source_rows = ctx.get("source_rows", pd.DataFrame())
    ev = ctx.get("event_map", pd.DataFrame())
    rule_events = ctx.get("rule_events", pd.DataFrame())
    rule_row = _as_dict(ctx.get("rule_row", {}))
    upstream = _as_dict(ctx.get("upstream", {}))

    v49g = _as_dict(upstream.get("v49g", {}))
    v49g3 = _as_dict(upstream.get("v49g3", {}))

    g_decision = _norm_txt(v49g.get("decision", ""))
    g_level = str(v49g.get("level", "N/A"))
    g_read = str(v49g.get("read", ""))
    g3_decision = _norm_txt(v49g3.get("decision", ""))
    g3_level = str(v49g3.get("level", "N/A"))
    g3_read = str(v49g3.get("read", ""))

    g3_block_count = int(_safe_float(v49g3.get("block_count", 0), 0))
    g3_review_count = int(_safe_float(v49g3.get("review_count", 0), 0))

    rows_total = int(len(source_rows)) if isinstance(source_rows, pd.DataFrame) else 0
    events_total = int(len(ev)) if isinstance(ev, pd.DataFrame) else 0
    rule_event_count = int(len(rule_events)) if isinstance(rule_events, pd.DataFrame) else 0

    unique_dates = _safe_nunique_date(source_rows, "available_at") if rows_total else 0

    try:
        source_count = (
            int(source_rows.get("source", pd.Series(dtype=str)).astype(str).replace("", np.nan).dropna().nunique())
            if rows_total else 0
        )
    except Exception:
        source_count = 0

    try:
        feature_count = (
            int(source_rows.get("feature_name", pd.Series(dtype=str)).astype(str).replace("", np.nan).dropna().nunique())
            if rows_total else 0
        )
    except Exception:
        feature_count = 0

    try:
        missing_available = (
            int(pd.to_datetime(source_rows.get("available_at", pd.Series(dtype="datetime64[ns]")), errors="coerce").isna().sum())
            if rows_total else 0
        )
    except Exception:
        missing_available = rows_total

    try:
        missing_value = (
            int(source_rows.get("value", pd.Series(dtype=object)).isna().sum())
            if rows_total else 0
        )
    except Exception:
        missing_value = rows_total

    invalid_decision = max(0, rows_total - events_total)
    date_concentration = _safe_concentration(source_rows, "available_at", date_mode=True)
    source_concentration = _safe_concentration(source_rows, "source", date_mode=False)

    # Hard-block only real data/provenance/technical failures.
    # Negative source-only alpha from V4.9G is not a data sufficiency failure.
    g3_ready = (
        "READY_FOR_V49H" in g3_decision
        or "REUPLOAD_VALIDATED" in g3_decision
        or "VALIDATED" in g3_decision
    )
    g3_hard_block = (
        g3_block_count > 0
        or "FIX_SOURCE_DATA_BEFORE_V49H" in g3_decision
        or "BLOCK" in g3_decision
        or "ERROR" in g3_decision
    )

    g_hard_block = (
        "WAIT_FOR_PRICE_DATA" in g_decision
        or "V49G_ERROR" in g_decision
        or "RETURN_TO_V49F1_OR_DATA" in g_decision
        or "RUNNER_BLOCKED" in g_level.upper()
    )

    # Alpha review is intentionally non-blocking for H.
    # J/K must reject later if holdout remains negative.
    g_alpha_negative_or_rejected = (
        "RETURN_TO_V49E_OR_EXPAND_DATA" in g_decision
        or "SOURCE_ONLY_REJECT" in g_decision
        or "REJECTED" in g_level.upper()
    )

    upstream_data_blocked = bool(g3_hard_block or g_hard_block)
    upstream_reviews = []
    if not g3_ready and g3_decision:
        upstream_reviews.append("V4.9G.3 not explicitly ready")
    if g3_review_count > 0:
        upstream_reviews.append(f"V4.9G.3 review_count={g3_review_count}")
    if g_alpha_negative_or_rejected:
        upstream_reviews.append("V4.9G alpha/source-only review negative")

    gates_rows: list[dict[str, Any]] = []

    gates_rows.append(
        _gate_row(
            "Upstream data/provenance gate",
            "FAIL" if upstream_data_blocked else ("REVIEW" if upstream_reviews else "PASS"),
            "Critical" if upstream_data_blocked else ("Medium" if upstream_reviews else "None"),
            f"V4.9G={g_decision or 'N/A'} ; V4.9G.3={g3_decision or 'N/A'} ; G3 blocks={g3_block_count}",
            "no hard data/provenance block",
            (
                "H bloque seulement si G/G.3 signalent un blocage data/provenance/technique. "
                "Une alpha review négative de G doit être traitée par J/K, pas par le gate de suffisance H."
            ),
        )
    )

    gates_rows.append(
        _gate_row(
            "V4.9G source-only alpha review",
            "REVIEW" if g_alpha_negative_or_rejected else ("PASS" if g_decision else "REVIEW"),
            "High" if g_alpha_negative_or_rejected else ("None" if g_decision else "Medium"),
            f"{g_level} / {g_decision or 'N/A'}",
            "positive preferred, but not an H data blocker",
            (
                "V4.9G négatif interdit la promotion directe, mais ne doit pas empêcher H/I/J "
                "de produire un diagnostic holdout complet si la provenance et le sample sont propres."
            ),
        )
    )

    gates_rows.append(
        _gate_row(
            "Source rows",
            "PASS" if rows_total >= 30 else ("REVIEW" if rows_total >= 15 else "FAIL"),
            "High" if rows_total < 15 else ("Medium" if rows_total < 30 else "None"),
            rows_total,
            ">=30 preferred, >=15 review",
            "Nombre de lignes source candidates après filtre family/feature.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Rule events",
            "PASS" if rule_event_count >= 8 else "FAIL",
            "Critical" if rule_event_count < 5 else ("High" if rule_event_count < 8 else "None"),
            rule_event_count,
            ">=8 minimum",
            "Évènements qui passent la règle source-only choisie.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Unique dates",
            "PASS" if unique_dates >= 6 else "FAIL",
            "High" if unique_dates < 6 else "None",
            unique_dates,
            ">=6 dates",
            "Évite une conclusion concentrée sur une seule date.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Source diversity",
            "PASS" if source_count >= 2 else "REVIEW",
            "Medium" if source_count < 2 else "None",
            source_count,
            ">=2 providers/source tags",
            "Réduit le risque d'une source unique fragile.",
        )
    )

    gates_rows.append(
        _gate_row(
            "available_at quality",
            "PASS" if missing_available == 0 else "FAIL",
            "Critical" if missing_available else "None",
            missing_available,
            "0 missing",
            "Chaque feature doit avoir un timestamp de disponibilité causale.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Forward map alignment",
            "PASS" if invalid_decision == 0 and events_total > 0 else "FAIL",
            "High" if invalid_decision or events_total <= 0 else "None",
            f"{events_total}/{rows_total}",
            "all rows alignable",
            "Les lignes doivent être plaçables sur le calendrier prix après available_at.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Value missingness",
            "PASS" if rows_total and missing_value / max(rows_total, 1) <= 0.05 else "REVIEW",
            "Medium" if missing_value else "None",
            missing_value,
            "<=5%",
            "Valeurs source manquantes avant construction de règle.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Date concentration",
            "PASS" if date_concentration <= 0.40 or unique_dates >= 10 else "REVIEW",
            "Medium" if date_concentration > 0.40 and unique_dates < 10 else "None",
            _format_pct(date_concentration),
            "<=40% preferred or >=10 dates",
            "Part de lignes concentrées sur la même date.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Provider concentration",
            "PASS" if source_concentration <= 0.80 or source_count >= 3 else "REVIEW",
            "Medium" if source_concentration > 0.80 and source_count < 3 else "None",
            _format_pct(source_concentration),
            "<=80% preferred or >=3 sources",
            "Risque de dépendance à un seul provider.",
        )
    )

    gates_rows.append(
        _gate_row(
            "Benchmark active map",
            "REVIEW" if ctx.get("benchmark_fallback", True) else "PASS",
            "Medium" if ctx.get("benchmark_fallback", True) else "None",
            ctx.get("benchmark_label", "N/A"),
            "external/sector benchmark preferred",
            "Active return forward doit être relatif à un benchmark exploitable.",
        )
    )

    gates = pd.DataFrame(gates_rows)

    # Upstream alpha review is not a hard failure. Upstream data/provenance and core H failures remain hard.
    fail_count = int((gates["Status"].astype(str) == "FAIL").sum()) if not gates.empty else 0
    review_count = int((gates["Status"].astype(str) == "REVIEW").sum()) if not gates.empty else 0
    critical_count = int(((gates["Status"].astype(str) == "FAIL") & (gates["Severity"].astype(str) == "Critical")).sum()) if not gates.empty else 0

    score = 100.0
    score -= critical_count * 35.0
    score -= max(0, fail_count - critical_count) * 18.0
    score -= review_count * 5.0
    score = max(0.0, min(100.0, float(score)))

    if upstream_data_blocked:
        level = "Source sufficiency blocked by upstream data gate"
        decision = "RETURN_TO_V49G3_BEFORE_V49I"
        read = (
            "V4.9H bloque par propagation data/provenance : V4.9G/V4.9G.3 signalent un blocage technique "
            "ou un reupload non propre avant construction I/J."
        )
    elif fail_count > 0:
        level = "Source sufficiency blocked"
        decision = "EXPAND_SOURCE_SAMPLE_BEFORE_V49I"
        read = (
            "V4.9H bloque : sample/rule events, available_at ou alignement insuffisant avant construction de signal source-only."
        )
    elif g_alpha_negative_or_rejected:
        level = "Source sufficiency ready / alpha review negative"
        decision = "READY_FOR_V49I_SOURCE_SIGNAL_CONSTRUCTION_WITH_ALPHA_REVIEW"
        read = (
            "V4.9H valide la suffisance data/provenance/sample. V4.9G reste négatif : "
            "I/J peuvent produire le blueprint et le holdout, mais K/V5 devront rejeter si le holdout ne confirme pas."
        )
    elif review_count > 0:
        level = "Source sufficiency review"
        decision = "READY_FOR_V49I_SOURCE_SIGNAL_CONSTRUCTION_WITH_REVIEW"
        read = (
            "V4.9H accepte la construction V4.9I sous revue : pas de promotion avant validation J/K."
        )
    else:
        level = "Source sufficiency ready"
        decision = "READY_FOR_V49I_SOURCE_SIGNAL_CONSTRUCTION"
        read = "V4.9H valide la suffisance minimale de la source candidate pour construire un blueprint causal."

    summary = pd.DataFrame(
        [
            ["V4.9H level", level, "Lecture synthétique du gate de suffisance source."],
            ["V4.9H score", f"{_format_num(score, 0)}/100", "Score data/provenance/sample, pas score alpha."],
            ["Decision", decision, "Décision research V4.9H."],
            ["Read", read, "Interprétation opérationnelle."],
            ["Ticker", ctx.get("ticker", "N/A"), "Ticker audité."],
            ["Source family", identity.get("source_family", "N/A"), "Famille source candidate."],
            ["Source feature", identity.get("source_feature", "N/A"), "Feature source candidate."],
            ["Rule", str(rule_row.get("rule", "N/A")), "Règle source-only utilisée."],
            ["Direction", str(rule_row.get("direction", "N/A")), "Direction économique déclarée par la règle."],
            ["Rule events", rule_event_count, "Évènements passés par la règle."],
            ["Source rows", rows_total, "Lignes source candidates."],
            ["Events total", events_total, "Lignes alignées au calendrier prix."],
            ["Unique dates", unique_dates, "Dates distinctes available_at."],
            ["Source count", source_count, "Providers/source tags distincts."],
            ["Feature count", feature_count, "Features distinctes dans la source sélectionnée."],
            ["V4.9G decision", g_decision or "N/A", "Décision alpha review source-only."],
            ["V4.9G.3 decision", g3_decision or "N/A", "Décision reupload/provenance."],
            ["V4.9G.3 block count", g3_block_count, "Blocages data/provenance hérités."],
            ["Alpha review negative", str(bool(g_alpha_negative_or_rejected)), "Doit être tranché par J/K, pas par H seul."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    next_actions = pd.DataFrame(
        [
            {
                "Priority": "P0",
                "Action": "Do not promote",
                "Reason": "H is sufficiency only",
                "Next Step": "Même si H passe, K/V5 doivent rejeter si J ne valide pas le holdout.",
            },
            {
                "Priority": "P0",
                "Action": "Keep G.3 hard block",
                "Reason": f"G3 blocks={g3_block_count}",
                "Next Step": "Toute contamination, missing available_at ou outcome label doit bloquer H.",
            },
            {
                "Priority": "P1",
                "Action": "Run V4.9I/J diagnostic",
                "Reason": "sample/provenance sufficient",
                "Next Step": "Construire blueprint puis valider/rejeter en holdout événementiel.",
            },
            {
                "Priority": "P1",
                "Action": "Treat V4.9G negative as alpha review",
                "Reason": g_decision or "N/A",
                "Next Step": "Si J confirme négatif, K rejette et V5 n'enregistre pas.",
            },
        ]
    )

    cards = [
        {"label": "V4.9H gate", "value": level, "delta": f"{_format_num(score, 0)}/100"},
        {"label": "Upstream data gate", "value": "BLOCK" if upstream_data_blocked else "PASS", "delta": "G/G.3"},
        {"label": "V4.9G alpha", "value": "REVIEW" if g_alpha_negative_or_rejected else "PASS", "delta": g_decision or "N/A"},
        {"label": "Rule events", "value": f"{rule_event_count}/8", "delta": "source-only"},
        {"label": "Sources", "value": f"{source_count}/2", "delta": "providers"},
        {"label": "Decision", "value": decision, "delta": "research only"},
    ]

    return {
        "enabled": True,
        "level": level,
        "score": score,
        "decision": decision,
        "read": read,
        "cards": cards,
        "summary": summary,
        "gates": gates,
        "next_actions": next_actions,
        "rule_events": rule_events,
        "rule_row": rule_row,
        "rule_event_count": rule_event_count,
        "source_rows": rows_total,
        "source_count": source_count,
        "unique_dates": unique_dates,
        "upstream_blocked": upstream_data_blocked,
        "upstream_block_reasons": ["data/provenance hard block"] if upstream_data_blocked else [],
        "upstream_reviews": upstream_reviews,
        "v49g_decision": g_decision,
        "v49g3_decision": g3_decision,
        "v49g3_block_count": g3_block_count,
        "alpha_review_negative": bool(g_alpha_negative_or_rejected),
    }

def _event_holdout_source_validation_v49j_pack(ctx: dict[str, Any], h_pack: dict[str, Any], i_pack: dict[str, Any]) -> dict[str, Any]:
    """
    V4.9J — Event Holdout / Walk-Forward Source Validation.

    Gate propagation patch:
    - V4.9J cannot validate, reject, or watch a holdout if V4.9H is not READY.
    - V4.9J cannot run an autonomous holdout if V4.9I did not produce a valid source-only blueprint.
    - This preserves institutional sequencing:
        G/G.3 BLOCK -> H BLOCK -> I BLOCK -> J BLOCK -> K REJECT -> V5 REJECT.
    - Read-only: no engine, signal, trade, equity curve, sizing, exit, OOS, paper/live or main verdict is modified.
    """
    def _as_dict(x: Any) -> dict[str, Any]:
        return x if isinstance(x, dict) else {}

    def _norm_decision(x: Any) -> str:
        return str(x or "").strip().upper()

    h_pack = _as_dict(h_pack)
    i_pack = _as_dict(i_pack)
    ctx = _as_dict(ctx)

    h_decision = _norm_decision(h_pack.get("decision", ""))
    i_decision = _norm_decision(i_pack.get("decision", ""))

    h_ready = h_decision.startswith("READY_FOR_V49I")
    i_ready = i_decision.startswith("SOURCE_SIGNAL_BLUEPRINT_READY")

    rule_events = i_pack.get("rule_events", pd.DataFrame())
    if rule_events is None or not isinstance(rule_events, pd.DataFrame) or rule_events.empty:
        rule_events = pd.DataFrame()

    if not rule_events.empty and "decision_date" in rule_events.columns:
        ev = rule_events.sort_values("decision_date").copy()
    else:
        ev = rule_events.copy() if isinstance(rule_events, pd.DataFrame) else pd.DataFrame()

    n = int(len(ev))

    # ------------------------------------------------------------------
    # HARD UPSTREAM BLOCK
    # ------------------------------------------------------------------
    # Important: V4.9J must not classify the source as rejected/watch/validated
    # when H/I are already blocked. Otherwise the UI suggests that J performed
    # a valid holdout despite a failed causal/sufficiency gate.
    if not h_ready or not i_ready:
        level = "Holdout blocked by upstream gate"
        score = 0.0
        decision = "WAIT_FOR_V49I_PASS_BEFORE_V49J"
        read = (
            "V4.9J bloque par propagation : V4.9H ou V4.9I n'a pas donné "
            "l'autorisation propre pour une validation événementielle holdout. "
            f"V4.9H decision={h_decision or 'N/A'} ; V4.9I decision={i_decision or 'N/A'}."
        )

        event_map = ev.copy()
        if not event_map.empty:
            event_map["holdout_segment"] = "BLOCKED_BY_UPSTREAM_GATE"
            event_map["rule"] = _as_dict(i_pack.get("rule_row", {})).get("rule", "N/A")
            event_map["benchmark"] = ctx.get("benchmark_label", "N/A")
            event_map["v49j_status"] = "UPSTREAM_BLOCKED"

        # Keep a matrix-shaped object so the existing renderer/download buttons
        # remain stable, but do not report holdout performance as valid.
        summary_map = pd.DataFrame(
            [
                {
                    "Segment": "Blocked before holdout",
                    "Events": n,
                    "avg_active_3b": np.nan,
                    "median_active_3b": np.nan,
                    "hit_3b": np.nan,
                    "worst_active_3b": np.nan,
                    "avg_active_5b": np.nan,
                    "median_active_5b": np.nan,
                    "hit_5b": np.nan,
                    "worst_active_5b": np.nan,
                    "avg_active_10b": np.nan,
                    "median_active_10b": np.nan,
                    "hit_10b": np.nan,
                    "worst_active_10b": np.nan,
                    "avg_active_20b": np.nan,
                    "median_active_20b": np.nan,
                    "hit_20b": np.nan,
                    "worst_active_20b": np.nan,
                    "Block reason": "V4.9H/V4.9I upstream gate did not pass",
                }
            ]
        )

        summary = pd.DataFrame(
            [
                ["V4.9J level", level, "Lecture synthétique holdout."],
                ["V4.9J score", score, "Score holdout événementiel."],
                ["Decision", decision, "Décision avant V4.9K."],
                ["Read", read, "Interprétation opérationnelle."],
                ["V4.9H decision", h_decision or "N/A", "H doit être READY_FOR_V49I avant J."],
                ["V4.9I decision", i_decision or "N/A", "I doit être SOURCE_SIGNAL_BLUEPRINT_READY avant J."],
                ["Full events available", n, "Évènements visibles mais non validés en holdout."],
                ["Holdout events", 0, "Aucun holdout autorisé tant que H/I bloquent."],
                ["Holdout avg active 10B", np.nan, "Non calculé comme validation tant que H/I bloquent."],
                ["Holdout hit 10B", np.nan, "Non calculé comme validation tant que H/I bloquent."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        cards = [
            {"label": "V4.9J holdout", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Upstream", "value": "BLOCK", "delta": "H/I"},
            {"label": "Events", "value": str(n), "delta": "not validated"},
            {"label": "Holdout n", "value": "0", "delta": "blocked"},
            {"label": "Holdout 10B", "value": "N/A", "delta": "blocked"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        next_actions = pd.DataFrame(
            [
                {
                    "Priority": "P0",
                    "Action": "Do not run V4.9J holdout",
                    "Reason": "H/I upstream gate blocked",
                    "Next Step": "Corriger V4.9G.3/V4.9H puis reconstruire V4.9I avant tout holdout.",
                },
                {
                    "Priority": "P0",
                    "Action": "Do not OOS promote",
                    "Reason": decision,
                    "Next Step": "V4.9K doit hériter du blocage et rejeter la promotion.",
                },
                {
                    "Priority": "P1",
                    "Action": "Fix upstream source gate",
                    "Reason": f"H={h_decision or 'N/A'} / I={i_decision or 'N/A'}",
                    "Next Step": "Repasser V4.9A→V4.9G.3 proprement, puis V4.9H/I.",
                },
            ]
        )

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "holdout_matrix": summary_map,
            "event_map": event_map,
            "next_actions": next_actions,
            "holdout_avg_active_10b": np.nan,
            "full_avg_active_10b": np.nan,
            "holdout_n": 0,
            "upstream_blocked": True,
            "h_decision": h_decision,
            "i_decision": i_decision,
        }

    # ------------------------------------------------------------------
    # NORMAL V4.9J HOLDOUT LOGIC — only after H and I are both ready.
    # ------------------------------------------------------------------
    split = int(max(1, np.floor(n * 0.70))) if n > 1 else n
    train = ev.iloc[:split].copy() if n else pd.DataFrame()
    holdout = ev.iloc[split:].copy() if n > split else pd.DataFrame()

    def stats(label: str, sub: pd.DataFrame) -> dict[str, Any]:
        row = {"Segment": label, "Events": int(len(sub))}
        for h in [3, 5, 10, 20]:
            r = pd.to_numeric(
                sub.get(f"active_return_{h}b", pd.Series(dtype=float)),
                errors="coerce",
            ).dropna()
            row[f"avg_active_{h}b"] = float(r.mean()) if not r.empty else np.nan
            row[f"median_active_{h}b"] = float(r.median()) if not r.empty else np.nan
            row[f"hit_{h}b"] = float((r > 0).mean()) if not r.empty else np.nan
            row[f"worst_active_{h}b"] = float(r.min()) if not r.empty else np.nan
        return row

    summary_map = (
        pd.DataFrame(
            [
                stats("Full", ev),
                stats("Train early events", train),
                stats("Holdout late events", holdout),
            ]
        )
        if n
        else pd.DataFrame()
    )

    holdout_n = int(len(holdout))
    holdout_avg10 = (
        _safe_float(
            summary_map.loc[
                summary_map["Segment"] == "Holdout late events",
                "avg_active_10b",
            ].iloc[0],
            np.nan,
        )
        if not summary_map.empty
        else np.nan
    )
    holdout_hit10 = (
        _safe_float(
            summary_map.loc[
                summary_map["Segment"] == "Holdout late events",
                "hit_10b",
            ].iloc[0],
            np.nan,
        )
        if not summary_map.empty
        else np.nan
    )
    full_avg10 = (
        _safe_float(
            summary_map.loc[
                summary_map["Segment"] == "Full",
                "avg_active_10b",
            ].iloc[0],
            np.nan,
        )
        if not summary_map.empty
        else np.nan
    )

    event_map = ev.copy()
    if not event_map.empty:
        event_map["holdout_segment"] = np.where(
            np.arange(len(event_map)) < split,
            "TRAIN_EARLY",
            "HOLDOUT_LATE",
        )
        event_map["rule"] = _as_dict(i_pack.get("rule_row", {})).get("rule", "N/A")
        event_map["benchmark"] = ctx.get("benchmark_label", "N/A")

    if n < 8:
        level = "Holdout blocked / low events"
        score = 25.0 + n * 3.0
        decision = "EXPAND_EVENTS_BEFORE_V49K"
        read = "V4.9J ne peut pas valider le holdout : échantillon d'évènements trop faible."
    elif holdout_n < 3:
        level = "Holdout review / thin test"
        score = 45.0
        decision = "HOLDOUT_SOURCE_WATCH_ONLY"
        read = "Holdout calculé mais test trop fin pour promotion."
    elif pd.notna(holdout_avg10) and holdout_avg10 > 0 and pd.notna(holdout_hit10) and holdout_hit10 >= 0.55:
        level = "Holdout source validated"
        score = min(100.0, 70.0 + holdout_avg10 * 500.0 + (holdout_hit10 - 0.5) * 40.0)
        decision = "HOLDOUT_SOURCE_VALIDATED_FOR_V49K"
        read = "V4.9J valide un holdout événementiel positif à confirmer par governance V4.9K."
    elif pd.notna(holdout_avg10) and holdout_avg10 > 0:
        level = "Holdout source watch"
        score = 58.0
        decision = "HOLDOUT_SOURCE_WATCH_ONLY"
        read = "Holdout positif mais hit-rate ou robustesse insuffisante : source watch uniquement."
    else:
        level = "Holdout source rejected"
        score = 35.0
        decision = "HOLDOUT_SOURCE_REJECTED"
        read = "V4.9J ne confirme pas l'active return en holdout."

    summary = pd.DataFrame(
        [
            ["V4.9J level", level, "Lecture synthétique holdout."],
            ["V4.9J score", score, "Score holdout événementiel."],
            ["Decision", decision, "Décision avant V4.9K."],
            ["Read", read, "Interprétation opérationnelle."],
            ["V4.9H decision", h_decision or "N/A", "Gate H validé avant J."],
            ["V4.9I decision", i_decision or "N/A", "Gate I validé avant J."],
            ["Full events", n, "Évènements source-only passés par la règle."],
            ["Train events", int(len(train)), "Première partie chronologique."],
            ["Holdout events", holdout_n, "Dernière partie chronologique."],
            ["Full avg active 10B", full_avg10, "Moyenne active 10B full sample."],
            ["Holdout avg active 10B", holdout_avg10, "Moyenne active 10B holdout."],
            ["Holdout hit 10B", holdout_hit10, "Hit-rate actif 10B holdout."],
        ],
        columns=["Metric", "Value", "Read"],
    )

    cards = [
        {"label": "V4.9J holdout", "value": level, "delta": f"{_format_num(score, 0)}/100"},
        {"label": "Events", "value": str(n), "delta": "rule sample"},
        {"label": "Holdout n", "value": str(holdout_n), "delta": "late events"},
        {"label": "Holdout 10B", "value": _format_pct(holdout_avg10), "delta": "active"},
        {"label": "Hit 10B", "value": _format_pct(holdout_hit10), "delta": "holdout"},
        {"label": "Decision", "value": decision, "delta": "research only"},
    ]

    next_actions = pd.DataFrame(
        [
            {
                "Priority": "P0",
                "Action": "Do not OOS promote",
                "Reason": decision,
                "Next Step": "V4.9K décide uniquement après H/I/J.",
            },
            {
                "Priority": "P1",
                "Action": "Increase late events",
                "Reason": f"holdout_n={holdout_n}",
                "Next Step": "Ajouter des observations récentes point-in-time.",
            },
            {
                "Priority": "P1",
                "Action": "Check horizon stability",
                "Reason": "3B/5B/10B/20B",
                "Next Step": "Ne pas sélectionner une source positive sur un seul horizon isolé.",
            },
        ]
    )

    return {
        "enabled": True,
        "level": level,
        "score": score,
        "decision": decision,
        "read": read,
        "cards": cards,
        "summary": summary,
        "holdout_matrix": summary_map,
        "event_map": event_map,
        "next_actions": next_actions,
        "holdout_avg_active_10b": holdout_avg10,
        "full_avg_active_10b": full_avg10,
        "holdout_n": holdout_n,
        "upstream_blocked": False,
        "h_decision": h_decision,
        "i_decision": i_decision,
    }


# ============================================================
# REJECTED SOURCE RECYCLING / ALTERNATIVE SOURCE TOURNAMENT V5.1
# ============================================================

def _v51_first_df(*values: Any) -> pd.DataFrame:
    for value in values:
        if isinstance(value, pd.DataFrame) and not value.empty:
            return value.copy()
    return pd.DataFrame()


def _v51_norm_text(value: Any) -> str:
    try:
        return str(value or "").strip().lower().replace(" ", "_").replace("-", "_").replace("/", "_")
    except Exception:
        return ""


def _v51_pick_col(df: pd.DataFrame, candidates: list[str]) -> str | None:
    if df is None or not isinstance(df, pd.DataFrame) or df.empty:
        return None
    lookup = {_v51_norm_text(c): c for c in df.columns}
    for candidate in candidates:
        key = _v51_norm_text(candidate)
        if key in lookup:
            return lookup[key]
    for candidate in candidates:
        key = _v51_norm_text(candidate)
        for norm_col, original in lookup.items():
            if key and (norm_col == key or key in norm_col):
                return original
    return None


def _v51_collect_candidate_rows(ctx: dict[str, Any]) -> pd.DataFrame:
    """Collecte des candidats alternatifs depuis V4.9C/D/E/G/J/V5 sans hypothèse rigide."""
    rows: list[dict[str, Any]] = []

    def add_rows(df: pd.DataFrame, origin: str, default_family: str = "") -> None:
        if df is None or not isinstance(df, pd.DataFrame) or df.empty:
            return
        table = df.copy()
        fam_col = _v51_pick_col(table, ["family", "feature_family", "source_family", "Family", "Source family"])
        feat_col = _v51_pick_col(table, ["feature", "feature_name", "source_feature", "Feature", "Source feature", "top_feature"])
        rule_col = _v51_pick_col(table, ["rule", "primitive", "Rule", "Primitive", "Top rule", "top_rule"])
        score_col = _v51_pick_col(table, ["priority_score", "Priority score", "score", "Score", "Avg score", "Best score", "V4.9D score", "Source score"])
        decision_col = _v51_pick_col(table, ["decision", "Decision", "label", "Label", "Stability", "Audit label"])
        avg10_col = _v51_pick_col(table, ["Avg active 10B", "avg_active_10b", "active_fwd_10b", "Holdout 10B", "holdout_active_10b"])
        hit10_col = _v51_pick_col(table, ["Hit 10B", "hit_10b", "Hit active 10B", "holdout_hit_10b"])
        sample_col = _v51_pick_col(table, ["sample", "Sample", "Events", "events", "Rows", "rows", "Rule events"])

        for _, r in table.iterrows():
            feature = str(r.get(feat_col, "") if feat_col else "").strip()
            if not feature or feature.lower() in {"nan", "none", "n/a"}:
                continue
            family = str(r.get(fam_col, default_family) if fam_col else default_family).strip() or "unknown"
            rule = str(r.get(rule_col, "candidate_rule") if rule_col else "candidate_rule").strip() or "candidate_rule"
            rows.append(
                {
                    "origin": origin,
                    "family": family,
                    "feature": feature,
                    "rule": rule,
                    "score_raw": _safe_float(r.get(score_col), np.nan) if score_col else np.nan,
                    "decision_raw": str(r.get(decision_col, "N/A") if decision_col else "N/A"),
                    "avg_active_10b": _safe_float(r.get(avg10_col), np.nan) if avg10_col else np.nan,
                    "hit_10b": _safe_float(r.get(hit10_col), np.nan) if hit10_col else np.nan,
                    "sample": int(_safe_float(r.get(sample_col), 0) or 0) if sample_col else 0,
                }
            )

    v49c = ctx.get("v49c_pack", {}) if isinstance(ctx, dict) else {}
    v49d = ctx.get("v49d_pack", {}) if isinstance(ctx, dict) else {}
    v49e = ctx.get("v49e_pack", {}) if isinstance(ctx, dict) else {}
    v49g = ctx.get("v49g_pack", {}) if isinstance(ctx, dict) else {}
    v49i = ctx.get("v49i_pack", {}) if isinstance(ctx, dict) else {}
    v49j = ctx.get("v49j_pack", {}) if isinstance(ctx, dict) else {}

    if isinstance(v49c, dict):
        add_rows(_v51_first_df(v49c.get("leaderboard"), v49c.get("candidate_watch"), v49c.get("rejected")), "V4.9C raw alpha", "external")
    if isinstance(v49d, dict):
        add_rows(_v51_first_df(v49d.get("benchmark_stability"), v49d.get("benchmark_feature_map")), "V4.9D multi-benchmark", "external")
    if isinstance(v49e, dict):
        add_rows(_v51_first_df(v49e.get("leaderboard"), v49e.get("source_selection"), v49e.get("watch_sources"), v49e.get("candidate_sources")), "V4.9E source selection", "external")
    if isinstance(v49g, dict):
        add_rows(_v51_first_df(v49g.get("rule_leaderboard"), v49g.get("leaderboard")), "V4.9G source-only", str(v49g.get("top_family", "external")))
    if isinstance(v49i, dict):
        add_rows(_v51_first_df(v49i.get("rule_leaderboard"), v49i.get("blueprint")), "V4.9I blueprint", str(v49i.get("top_family", "external")))
    if isinstance(v49j, dict):
        add_rows(_v51_first_df(v49j.get("holdout_matrix"), v49j.get("event_map")), "V4.9J holdout", str(v49j.get("top_family", "external")))

    if not rows:
        return pd.DataFrame()

    out = pd.DataFrame(rows)
    out["family_norm"] = out["family"].map(_v51_norm_text)
    out["feature_norm"] = out["feature"].map(_v51_norm_text)
    out["rule_norm"] = out["rule"].map(_v51_norm_text)
    return out


def _v51_score_candidates(candidates: pd.DataFrame, rejected_feature: str = "") -> pd.DataFrame:
    if candidates is None or not isinstance(candidates, pd.DataFrame) or candidates.empty:
        return pd.DataFrame()

    df = candidates.copy()
    rejected_norm = _v51_norm_text(rejected_feature)

    decision_penalty = []
    for val in df.get("decision_raw", pd.Series("", index=df.index)).astype(str):
        low = val.lower()
        if "candidate" in low or "pass" in low or "ready" in low:
            decision_penalty.append(8.0)
        elif "watch" in low or "mixed" in low or "review" in low:
            decision_penalty.append(2.0)
        elif "reject" in low or "fail" in low or "blocked" in low:
            decision_penalty.append(-10.0)
        else:
            decision_penalty.append(0.0)

    score_raw = pd.to_numeric(df.get("score_raw", np.nan), errors="coerce")
    avg10 = pd.to_numeric(df.get("avg_active_10b", np.nan), errors="coerce")
    hit10 = pd.to_numeric(df.get("hit_10b", np.nan), errors="coerce")
    sample = pd.to_numeric(df.get("sample", 0), errors="coerce").fillna(0.0)

    # Normalize sources where score already appears in 0-100 space.
    base = score_raw.copy()
    base = np.where(pd.isna(base), 35.0, np.where(base <= 1.5, base * 100.0, base))
    base = pd.Series(base, index=df.index).clip(0.0, 100.0)

    avg_bonus = avg10.fillna(0.0).clip(-0.10, 0.10) * 180.0
    hit_bonus = (hit10.fillna(0.50).clip(0.0, 1.0) - 0.50) * 30.0
    sample_bonus = np.minimum(sample, 30.0) / 30.0 * 8.0
    reject_penalty = np.where(df["feature_norm"].eq(rejected_norm), -35.0, 0.0)

    df["v51_score"] = (base + avg_bonus + hit_bonus + sample_bonus + pd.Series(decision_penalty, index=df.index) + reject_penalty).clip(0.0, 100.0)

    agg = (
        df.groupby(["family_norm", "feature_norm", "rule_norm"], as_index=False)
        .agg(
            family=("family", "first"),
            feature=("feature", "first"),
            rule=("rule", "first"),
            origins=("origin", lambda x: ", ".join(sorted(set(map(str, x)))[:5])),
            source_views=("origin", "count"),
            best_score=("v51_score", "max"),
            avg_score=("v51_score", "mean"),
            avg_active_10b=("avg_active_10b", "mean"),
            hit_10b=("hit_10b", "mean"),
            sample=("sample", "max"),
            decisions=("decision_raw", lambda x: ", ".join(sorted(set(map(str, x)))[:5])),
        )
    )

    if agg.empty:
        return agg

    agg["rank_score"] = (0.65 * agg["best_score"] + 0.35 * agg["avg_score"]).clip(0.0, 100.0)
    agg["same_as_rejected"] = agg["feature_norm"].eq(rejected_norm)

    def _action(row: pd.Series) -> str:
        if bool(row.get("same_as_rejected")):
            return "Do not recycle rejected rule without new definition"
        score = _safe_float(row.get("rank_score"), 0.0)
        if score >= 65:
            return "Promote to alternative source tournament"
        if score >= 45:
            return "Watch/refine before tournament"
        return "Reject for now / data expansion only"

    def _next_rule(row: pd.Series) -> str:
        feature = str(row.get("feature", ""))
        rule = str(row.get("rule", ""))
        if rule and rule.lower() not in {"candidate_rule", "nan", "none", "n/a"}:
            return rule
        f = _v51_norm_text(feature)
        if "surprise" in f or "revision" in f or "guidance" in f:
            return "value_top_quartile + positive_direction"
        if "iv" in f or "skew" in f or "gamma" in f or "term" in f:
            return "regime_state_split + top/bottom_quartile"
        if "news" in f or "catalyst" in f:
            return "positive_tag_with_severity_filter"
        return "median_split_then_holdout"

    agg["v51_action"] = agg.apply(_action, axis=1)
    agg["next_rule_to_test"] = agg.apply(_next_rule, axis=1)
    agg = agg.sort_values(["same_as_rejected", "rank_score", "source_views"], ascending=[True, False, False])
    return agg


def _rejected_source_recycling_tournament_v51_pack(ctx: dict[str, Any] | None = None) -> dict[str, Any]:
    """
    V5.1 — Rejected Source Recycling / Alternative Source Tournament.

    Lecture seule :
    - prend la source rejetée par V5.0/V4.9K ;
    - recycle les évidences V4.9C/D/E/G/J ;
    - classe les sources alternatives à tester ;
    - interdit engine injection, OOS direct, sizing/exits/live ;
    - prépare la prochaine source sans créer de stratégie.
    """
    ctx = ctx if isinstance(ctx, dict) else {}

    def _row(gate: str, status: str, value: Any, read: str) -> dict[str, Any]:
        return {"Gate": str(gate), "Status": str(status), "Value": str(value), "Read": str(read)}

    try:
        v50 = ctx.get("v50_pack", {}) if isinstance(ctx.get("v50_pack", {}), dict) else {}
        v49k = ctx.get("v49k_pack", {}) if isinstance(ctx.get("v49k_pack", {}), dict) else {}
        v49j = ctx.get("v49j_pack", {}) if isinstance(ctx.get("v49j_pack", {}), dict) else {}
        v49g = ctx.get("v49g_pack", {}) if isinstance(ctx.get("v49g_pack", {}), dict) else {}

        v50_status = str(v50.get("status") or v50.get("decision") or v50.get("registry_status") or "N/A")
        k_decision = str(v49k.get("decision") or "N/A")
        j_decision = str(v49j.get("decision") or "N/A")
        rejected_feature = str(
            v49g.get("top_feature")
            or v49j.get("top_feature")
            or v49k.get("top_feature")
            or v50.get("top_feature")
            or ""
        ).strip()
        rejected_family = str(v49g.get("top_family") or v49j.get("top_family") or v49k.get("top_family") or "").strip()
        rejected_rule = str(v49g.get("top_rule") or v49j.get("top_rule") or v49k.get("top_rule") or "").strip()

        raw_candidates = _v51_collect_candidate_rows(ctx)
        tournament = _v51_score_candidates(raw_candidates, rejected_feature=rejected_feature)

        if tournament.empty:
            alternatives = pd.DataFrame()
        else:
            alternatives = tournament[~tournament["same_as_rejected"]].copy()

        top_alt = alternatives.head(1).iloc[0] if not alternatives.empty else None
        top_feature = str(top_alt.get("feature", "N/A")) if top_alt is not None else "N/A"
        top_family = str(top_alt.get("family", "N/A")) if top_alt is not None else "N/A"
        top_score = _safe_float(top_alt.get("rank_score"), 0.0) if top_alt is not None else 0.0
        candidate_count = int((alternatives.get("rank_score", pd.Series(dtype=float)) >= 65).sum()) if not alternatives.empty else 0
        watch_count = int(((alternatives.get("rank_score", pd.Series(dtype=float)) >= 45) & (alternatives.get("rank_score", pd.Series(dtype=float)) < 65)).sum()) if not alternatives.empty else 0

        combined_status = (v50_status + " " + k_decision + " " + j_decision).upper()
        source_rejected = any(tok in combined_status for tok in ["REJECT", "NOT_REGISTERED", "DO_NOT_PROMOTE", "HOLDOUT_SOURCE_REJECTED"])
        source_promoted = (not source_rejected) and any(
            tok in combined_status
            for tok in ["PROMOTE_SOURCE_TO_V50_REGISTRY", "SOURCE_REGISTERED_FOR_TOURNAMENT_TEST", "REGISTERED_FOR_TOURNAMENT"]
        )

        if source_promoted:
            level = "Registry already has promoted source"
            decision = "NO_RECYCLING_REQUIRED"
            read = "V5.1 n'est pas nécessaire : V5.0/K ne rejette pas la source."
            score = 70.0
        elif candidate_count > 0:
            level = "Alternative source tournament ready"
            decision = "BUILD_ALTERNATIVE_SOURCE_TOURNAMENT"
            read = "V5.1 trouve des sources alternatives à tester proprement, sans injection moteur directe."
            score = max(55.0, min(100.0, top_score))
        elif watch_count > 0:
            level = "Alternative source watchlist"
            decision = "REFINE_ALTERNATIVE_SOURCES_BEFORE_TOURNAMENT"
            read = "V5.1 trouve des alternatives partielles : raffiner règles/data avant nouveau runner."
            score = max(35.0, min(65.0, top_score))
        elif source_rejected:
            level = "Rejected source requires data/source rebuild"
            decision = "EXPAND_EXTERNAL_SOURCE_UNIVERSE"
            read = "La source rejetée ne doit pas être recyclée telle quelle ; enrichir ou tester une nouvelle famille."
            score = max(0.0, min(40.0, top_score))
        else:
            level = "Recycling map neutral"
            decision = "REVIEW_SOURCE_EVIDENCE_MANUALLY"
            read = "V5.1 manque d'évidence claire pour classer les alternatives."
            score = max(0.0, min(50.0, top_score))

        rejected_autopsy = pd.DataFrame(
            [
                ["Rejected family", rejected_family or "N/A", "Famille de la source rejetée ou surveillée."],
                ["Rejected feature", rejected_feature or "N/A", "Feature principale issue de V4.9G/J/K/V5."],
                ["Rejected rule", rejected_rule or "N/A", "Règle source-only utilisée avant rejet."],
                ["V4.9J decision", j_decision, "Holdout/validation événementielle."],
                ["V4.9K decision", k_decision, "Governance promotion/rejection."],
                ["V5.0 status", v50_status, "Registry / handoff status."],
                ["Operational read", "Do not recycle same source/rule unchanged", "Une source rejetée ne doit pas être retestée mécaniquement avec sizing/exits."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        gates = pd.DataFrame(
            [
                _row("No engine injection", "ENFORCED", "read-only", "V5.1 ne crée aucun signal moteur."),
                _row("No direct OOS", "ENFORCED", "source selection first", "OOS interdit tant qu'une alternative ne passe pas source-only + holdout."),
                _row("Rejected source unchanged", "BLOCK" if source_rejected else "REVIEW", rejected_feature or "N/A", "Ne pas recycler la même feature/règle sans nouvelle définition causale."),
                _row("Alternative candidates", "PASS" if candidate_count > 0 else ("REVIEW" if watch_count > 0 else "NOT YET"), candidate_count, "Nombre d'alternatives classées candidate."),
                _row("Watch alternatives", "PASS" if watch_count > 0 else "SKIP", watch_count, "Sources partielles à raffiner."),
                _row("Data enrichment", "REVIEW", len(raw_candidates), "Nombre total de lignes d'évidence collectées depuis les blocs précédents."),
            ]
        )

        next_actions = pd.DataFrame(
            [
                ["P0", "Do not promote rejected source", rejected_feature or "N/A", "Ne pas enregistrer la source rejetée dans V5.0 sans nouvelle validation."],
                ["P0", "Do not tune exits/sizing", "source failure", "Ne pas compenser un holdout négatif par optimisation de sortie ou sizing."],
                ["P1", "Run alternative source tournament", f"candidates={candidate_count}", "Tester une seule source alternative à la fois, même protocole V4.9G→V5."],
                ["P1", "Prioritize top alternative", f"{top_family}/{top_feature}", "Construire un nouveau blueprint source-only causal t+1."],
                ["P2", "Expand data universe", f"watch={watch_count}", "Ajouter options/revisions/guidance/news/factors si les alternatives restent fragiles."],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        summary = pd.DataFrame(
            [
                ["V5.1 level", level, "Lecture synthétique du recyclage source."],
                ["V5.1 score", f"{_format_num(score, 0)}/100", "Score de priorisation alternative, pas score live."],
                ["Decision", decision, "Décision research V5.1."],
                ["Read", read, "Interprétation opérationnelle."],
                ["Rejected source", f"{rejected_family}/{rejected_feature}/{rejected_rule}", "Source rejetée à ne pas forcer."],
                ["Top alternative", f"{top_family}/{top_feature}", "Meilleure alternative selon les évidences collectées."],
                ["Alternative candidates", str(candidate_count), "Sources alternatives candidates."],
                ["Alternative watchlist", str(watch_count), "Sources alternatives à raffiner."],
                ["Evidence rows collected", str(len(raw_candidates)), "Lignes d'évidence venues de C/D/E/G/I/J."],
                ["Still forbidden", "paper/live/direct engine/sizing/exits", "V5.1 reste strictement research-only."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        cards = [
            {"label": "V5.1 recycling", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Rejected source", "value": rejected_feature or "N/A", "delta": rejected_family or "source"},
            {"label": "Top alternative", "value": top_feature, "delta": top_family},
            {"label": "Candidates", "value": str(candidate_count), "delta": "alternative"},
            {"label": "Watchlist", "value": str(watch_count), "delta": "refine"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "rejected_autopsy": rejected_autopsy,
            "gates": gates,
            "tournament": tournament,
            "alternatives": alternatives,
            "next_actions": next_actions,
            "top_feature": top_feature,
            "top_family": top_family,
            "candidate_count": candidate_count,
            "watch_count": watch_count,
        }

    except Exception as exc:
        return {
            "enabled": True,
            "level": "V5.1 error",
            "score": 0.0,
            "decision": "V51_ERROR_SAFE_SKIP",
            "read": f"Erreur V5.1 : {exc}",
            "cards": [{"label": "V5.1 recycling", "value": "Error", "delta": "safe skip"}],
            "summary": pd.DataFrame([["V5.1 error", str(exc), "Erreur capturée sans interrompre le backtest."]], columns=["Metric", "Value", "Read"]),
            "rejected_autopsy": pd.DataFrame(),
            "gates": pd.DataFrame(),
            "tournament": pd.DataFrame(),
            "alternatives": pd.DataFrame(),
            "next_actions": pd.DataFrame(),
        }


def _render_rejected_source_recycling_tournament_v51(ctx: dict[str, Any] | None = None) -> dict[str, Any]:
    """Streamlit renderer V5.1. Read-only rejected-source recycling and alternative tournament."""
    pack = _rejected_source_recycling_tournament_v51_pack(ctx=ctx)

    st.subheader("V5.1 — Rejected Source Recycling / Alternative Source Tournament")
    st.caption(
        "Section complète lecture seule après V5.0 : recycle les sources rejetées, classe les alternatives, "
        "prépare un tournoi source-only causal t+1 et bloque engine/OOS/paper/live tant qu'une nouvelle source n'est pas validée."
    )

    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass

    level = str(pack.get("level", ""))
    read = str(pack.get("read", ""))
    if "ready" in level.lower():
        st.success(f"Lecture V5.1 : {read}")
    elif "watch" in level.lower() or "rebuild" in level.lower() or "neutral" in level.lower():
        st.warning(f"Lecture V5.1 : {read}")
    elif "error" in level.lower():
        st.error(f"Lecture V5.1 : {read}")
    else:
        st.info(f"Lecture V5.1 : {read}")

    sections = [
        ("V5.1 recycling summary", "summary", True),
        ("V5.1 rejected source autopsy", "rejected_autopsy", True),
        ("V5.1 governance gates", "gates", True),
        ("V5.1 alternative source tournament", "tournament", True),
        ("V5.1 alternative candidates only", "alternatives", False),
        ("V5.1 next controlled actions", "next_actions", True),
    ]
    for title, key, expanded in sections:
        with st.expander(title, expanded=expanded):
            table = pack.get(key, pd.DataFrame())
            if isinstance(table, pd.DataFrame) and not table.empty:
                display = table.copy()
                for col in ["avg_active_10b", "hit_10b"]:
                    if col in display.columns:
                        display[col] = display[col].map(lambda x: _format_pct(x))
                for col in ["rank_score", "best_score", "avg_score", "v51_score"]:
                    if col in display.columns:
                        display[col] = display[col].map(lambda x: _format_num(x, 0))
                st.dataframe(display, use_container_width=True, hide_index=True)
            else:
                st.info(f"{title} indisponible.")

    d1, d2, d3 = st.columns(3)
    tournament = pack.get("tournament", pd.DataFrame())
    alternatives = pack.get("alternatives", pd.DataFrame())
    gates = pack.get("gates", pd.DataFrame())

    if isinstance(tournament, pd.DataFrame) and not tournament.empty:
        d1.download_button(
            "Télécharger V5.1 source tournament CSV",
            data=tournament.to_csv(index=False).encode("utf-8"),
            file_name="v51_alternative_source_tournament.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v51_tournament_download",
        )
    if isinstance(alternatives, pd.DataFrame) and not alternatives.empty:
        d2.download_button(
            "Télécharger V5.1 alternatives CSV",
            data=alternatives.to_csv(index=False).encode("utf-8"),
            file_name="v51_alternative_candidates.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v51_alternatives_download",
        )
    if isinstance(gates, pd.DataFrame) and not gates.empty:
        d3.download_button(
            "Télécharger V5.1 gates CSV",
            data=gates.to_csv(index=False).encode("utf-8"),
            file_name="v51_recycling_governance_gates.csv",
            mime="text/csv",
            use_container_width=True,
            key="bt_v51_gates_download",
        )

    return pack

# Backward-compatible alias.
def _render_source_recycling_tournament_v51(*args: Any, **kwargs: Any) -> dict[str, Any]:
    return _render_rejected_source_recycling_tournament_v51(*args, **kwargs)

