def _v52_v60_as_df(obj: Any) -> pd.DataFrame:
    try:
        if isinstance(obj, pd.DataFrame):
            return obj.copy()
        if isinstance(obj, pd.Series):
            return obj.to_frame().copy()
    except Exception:
        pass
    return pd.DataFrame()


def _v52_v60_pct_value(value: Any) -> float:
    try:
        if value is None or pd.isna(value):
            return np.nan
        if isinstance(value, str):
            txt = value.strip().replace("%", "").replace(",", ".")
            if txt == "" or txt.lower() in {"nan", "none", "n/a"}:
                return np.nan
            out = float(txt)
            return out / 100.0 if "%" in value or abs(out) > 1.5 else out
        return float(value)
    except Exception:
        return np.nan


def _v52_v60_norm_colname(x: Any) -> str:
    return str(x or "").strip().lower().replace(" ", "_").replace("-", "_")


def _v52_v60_pick_col(df: pd.DataFrame, candidates: list[str]) -> str | None:
    try:
        mapping = {_v52_v60_norm_colname(c): c for c in df.columns}
        for c in candidates:
            key = _v52_v60_norm_colname(c)
            if key in mapping:
                return mapping[key]
    except Exception:
        pass
    return None


def _v52_v60_ctx_get_dict(ctx: dict[str, Any] | None, key: str) -> dict[str, Any]:
    try:
        obj = (ctx or {}).get(key, {})
        return obj if isinstance(obj, dict) else {}
    except Exception:
        return {}


def _v52_v60_ctx_get_external_features(ctx: dict[str, Any] | None) -> pd.DataFrame:
    ctx = ctx if isinstance(ctx, dict) else {}
    candidates = [
        ctx.get("external_features"),
        ctx.get("v49g_external_features"),
        ctx.get("source_events"),
        ctx.get("features"),
    ]
    for obj in candidates:
        df = _v52_v60_as_df(obj)
        if not df.empty:
            return df
    for key in ["v49g3_pack", "v49g2_pack", "v49g_pack", "v49b2_pack", "v49a_pack"]:
        pack = _v52_v60_ctx_get_dict(ctx, key)
        for subkey in ["external_features", "current_rows", "clean_rows", "audited_features", "source_rows", "features"]:
            df = _v52_v60_as_df(pack.get(subkey))
            if not df.empty:
                return df
    return pd.DataFrame()


def _v52_v60_ctx_get_price_frame(ctx: dict[str, Any] | None) -> pd.DataFrame:
    ctx = ctx if isinstance(ctx, dict) else {}
    for key in ["bt", "data", "price_df", "df", "price_data", "ohlc"]:
        df = _v52_v60_as_df(ctx.get(key))
        if not df.empty and any(_v52_v60_norm_colname(c) == "close" for c in df.columns):
            out = df.copy()
            if not isinstance(out.index, pd.DatetimeIndex):
                date_col = _v52_v60_pick_col(out, ["date", "datetime", "timestamp", "time"])
                if date_col is not None:
                    idx = pd.to_datetime(out[date_col], errors="coerce")
                    if idx.notna().sum() >= max(5, int(len(out) * 0.6)):
                        out.index = idx
            out = out.loc[~out.index.duplicated(keep="last")]
            return out
    for key in ["v49d_pack", "v49c_pack", "complete_pack"]:
        pack = _v52_v60_ctx_get_dict(ctx, key)
        for subkey in ["bt", "data", "price_df", "df", "price_data", "ohlc"]:
            df = _v52_v60_as_df(pack.get(subkey))
            if not df.empty and any(_v52_v60_norm_colname(c) == "close" for c in df.columns):
                return df
    return pd.DataFrame()


def _v52_v60_event_date_series(df: pd.DataFrame) -> pd.Series:
    if df is None or df.empty:
        return pd.Series(dtype="datetime64[ns]")
    for cands in [["decision_date", "decision date"], ["available_at", "available at"], ["date"], ["event_date", "event date"]]:
        col = _v52_v60_pick_col(df, cands)
        if col is not None:
            s = pd.to_datetime(df[col], errors="coerce")
            if s.notna().any():
                return s
    if isinstance(df.index, pd.DatetimeIndex):
        return pd.Series(pd.to_datetime(df.index), index=df.index)
    return pd.Series(pd.NaT, index=df.index)


def _v52_v60_feature_columns(df: pd.DataFrame) -> tuple[str | None, str | None, str | None, str | None, str | None]:
    family_col = _v52_v60_pick_col(df, ["feature_family", "family", "data_family"])
    feature_col = _v52_v60_pick_col(df, ["feature_name", "feature", "source_feature", "name"])
    value_col = _v52_v60_pick_col(df, ["value", "feature_value", "signal_value"])
    source_col = _v52_v60_pick_col(df, ["source", "provider", "source_tag", "provider_tag"])
    confidence_col = _v52_v60_pick_col(df, ["confidence", "reliability", "confidence_score"])
    return family_col, feature_col, value_col, source_col, confidence_col


def _v52_v60_prepare_external_features(df: pd.DataFrame, ticker: str = "") -> pd.DataFrame:
    raw = _v52_v60_as_df(df)
    if raw.empty:
        return pd.DataFrame()
    family_col, feature_col, value_col, source_col, confidence_col = _v52_v60_feature_columns(raw)
    out = pd.DataFrame(index=raw.index)
    out["date"] = _v52_v60_event_date_series(raw)
    out["available_at"] = pd.to_datetime(raw[_v52_v60_pick_col(raw, ["available_at", "available at"])] if _v52_v60_pick_col(raw, ["available_at", "available at"]) else out["date"], errors="coerce")
    out["ticker"] = str(ticker or "")
    tcol = _v52_v60_pick_col(raw, ["ticker", "symbol"])
    if tcol is not None:
        out["ticker"] = raw[tcol].astype(str)
    out["family"] = raw[family_col].astype(str).str.strip() if family_col is not None else "unknown"
    out["feature"] = raw[feature_col].astype(str).str.strip() if feature_col is not None else "unknown_feature"
    out["value_raw"] = raw[value_col] if value_col is not None else np.nan
    out["value_num"] = pd.to_numeric(out["value_raw"], errors="coerce")
    out["source"] = raw[source_col].astype(str).str.strip() if source_col is not None else "unknown_source"
    out["confidence"] = pd.to_numeric(raw[confidence_col], errors="coerce") if confidence_col is not None else np.nan
    out["confidence"] = out["confidence"].fillna(0.50).clip(0.0, 1.0)
    out = out.replace([np.inf, -np.inf], np.nan)
    out = out.dropna(subset=["available_at"])
    out = out[out["feature"].astype(str).str.len() > 0]
    out = out[~out["feature"].astype(str).str.lower().isin({"nan", "none", "n/a"})]
    return out.reset_index(drop=True)


def _v52_v60_forward_return(close: pd.Series, start_pos: int, horizon: int, side: float = 1.0) -> float:
    try:
        if close is None or close.empty:
            return np.nan
        start_pos = int(start_pos)
        end_pos = min(start_pos + int(horizon), len(close) - 1)
        if start_pos < 0 or end_pos <= start_pos:
            return np.nan
        p0 = float(close.iloc[start_pos])
        p1 = float(close.iloc[end_pos])
        if p0 <= 0 or p1 <= 0:
            return np.nan
        ret = p1 / p0 - 1.0
        return ret if side >= 0 else -ret
    except Exception:
        return np.nan


def _v52_v60_build_rule_events(features: pd.DataFrame, price_df: pd.DataFrame, horizons: tuple[int, ...] = (3, 5, 10, 20)) -> pd.DataFrame:
    features = _v52_v60_as_df(features)
    price_df = _v52_v60_as_df(price_df)
    if features.empty or price_df.empty or "close" not in [str(c).lower() for c in price_df.columns]:
        return pd.DataFrame()
    close_col = _v52_v60_pick_col(price_df, ["close"])
    if close_col is None:
        return pd.DataFrame()
    if not isinstance(price_df.index, pd.DatetimeIndex):
        return pd.DataFrame()
    close = pd.to_numeric(price_df[close_col], errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
    if close.empty or len(close) < max(horizons) + 5:
        return pd.DataFrame()
    idx = pd.to_datetime(close.index)
    rows: list[dict[str, Any]] = []
    grouped = features.groupby(["family", "feature"], dropna=False)
    for (family, feature), grp in grouped:
        grp = grp.copy().sort_values("available_at")
        numeric = pd.to_numeric(grp["value_num"], errors="coerce")
        rules: list[tuple[str, pd.Series, float]] = []
        if numeric.notna().sum() >= max(3, min(8, len(grp))):
            med = float(numeric.median())
            q75 = float(numeric.quantile(0.75))
            q25 = float(numeric.quantile(0.25))
            rules.append(("value_above_median", numeric >= med, 1.0))
            rules.append(("value_top_quartile", numeric >= q75, 1.0))
            rules.append(("value_bottom_quartile_short", numeric <= q25, -1.0))
            if (numeric > 0).sum() > 0:
                rules.append(("positive_value", numeric > 0, 1.0))
            if (numeric < 0).sum() > 0:
                rules.append(("negative_value_short", numeric < 0, -1.0))
        else:
            txt = grp["value_raw"].astype(str).str.lower()
            pos = txt.str.contains("positive|bull|raise|raised|beat|up|strong|upgrade", regex=True, na=False)
            neg = txt.str.contains("negative|bear|cut|miss|down|weak|downgrade", regex=True, na=False)
            if pos.sum() > 0:
                rules.append(("positive_text_tag", pos, 1.0))
            if neg.sum() > 0:
                rules.append(("negative_text_tag_short", neg, -1.0))
        for rule_name, mask, side in rules:
            selected = grp.loc[mask.fillna(False)].copy()
            if selected.empty:
                continue
            for _, ev in selected.iterrows():
                available_at = pd.to_datetime(ev.get("available_at"), errors="coerce")
                if pd.isna(available_at):
                    continue
                pos_arr = np.where(idx.normalize() >= available_at.normalize())[0]
                if len(pos_arr) == 0:
                    continue
                start_pos = int(pos_arr[0])
                row = {
                    "family": str(family),
                    "feature": str(feature),
                    "rule": rule_name,
                    "side": "LONG" if side >= 0 else "SHORT",
                    "side_num": float(side),
                    "event_date": _format_dt(ev.get("date")),
                    "available_at": _format_dt(available_at),
                    "decision_date": _format_dt(idx[start_pos]),
                    "value": ev.get("value_raw"),
                    "source": str(ev.get("source", "unknown_source")),
                    "confidence": _safe_float(ev.get("confidence"), 0.50),
                }
                for h in horizons:
                    row[f"fwd_{h}b"] = _v52_v60_forward_return(close, start_pos, h, side=side)
                rows.append(row)
    out = pd.DataFrame(rows)
    if not out.empty:
        out = out.replace([np.inf, -np.inf], np.nan)
    return out


def _v52_v60_score_rule_events(events: pd.DataFrame) -> pd.DataFrame:
    events = _v52_v60_as_df(events)
    if events.empty:
        return pd.DataFrame()
    rows = []
    for keys, grp in events.groupby(["family", "feature", "rule", "side"], dropna=False):
        family, feature, rule, side = keys
        r10 = pd.to_numeric(grp.get("fwd_10b"), errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
        r5 = pd.to_numeric(grp.get("fwd_5b"), errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
        r20 = pd.to_numeric(grp.get("fwd_20b"), errors="coerce").replace([np.inf, -np.inf], np.nan).dropna()
        n = int(len(grp))
        sources = int(grp.get("source", pd.Series(dtype=str)).astype(str).nunique()) if "source" in grp.columns else 0
        dates = int(grp.get("decision_date", pd.Series(dtype=str)).astype(str).nunique()) if "decision_date" in grp.columns else 0
        avg10 = float(r10.mean()) if not r10.empty else np.nan
        med10 = float(r10.median()) if not r10.empty else np.nan
        hit10 = float((r10 > 0).mean()) if not r10.empty else np.nan
        avg5 = float(r5.mean()) if not r5.empty else np.nan
        avg20 = float(r20.mean()) if not r20.empty else np.nan
        worst10 = float(r10.min()) if not r10.empty else np.nan
        stability = 0.0
        if pd.notna(avg5) and pd.notna(avg10) and pd.notna(avg20):
            stability = 1.0 - min(1.0, float(np.nanstd([avg5, avg10, avg20])) / max(abs(avg10), 0.01))
        sample_score = min(25.0, n / 20.0 * 25.0)
        source_score = min(15.0, sources / 3.0 * 15.0)
        date_score = min(10.0, dates / 10.0 * 10.0)
        perf_score = 0.0
        if pd.notna(avg10):
            perf_score += max(-20.0, min(25.0, avg10 * 500.0))
        if pd.notna(med10):
            perf_score += max(-10.0, min(15.0, med10 * 350.0))
        hit_score = 0.0 if pd.isna(hit10) else max(-15.0, min(20.0, (hit10 - 0.50) * 80.0))
        stable_score = max(0.0, min(10.0, stability * 10.0))
        rank_score = max(0.0, min(100.0, 35.0 + sample_score + source_score + date_score + perf_score + hit_score + stable_score))
        if n >= 8 and sources >= 2 and pd.notna(avg10) and avg10 > 0 and pd.notna(hit10) and hit10 >= 0.52:
            label = "CANDIDATE"
        elif n >= 5 and pd.notna(avg10) and avg10 > 0:
            label = "WATCH"
        elif n < 5:
            label = "LOW_SAMPLE"
        else:
            label = "REJECT"
        rows.append({
            "family": str(family),
            "feature": str(feature),
            "rule": str(rule),
            "side": str(side),
            "events": n,
            "unique_dates": dates,
            "sources": sources,
            "avg_5b": avg5,
            "avg_10b": avg10,
            "avg_20b": avg20,
            "median_10b": med10,
            "hit_10b": hit10,
            "worst_10b": worst10,
            "stability_score": stability,
            "rank_score": rank_score,
            "candidate_label": label,
        })
    out = pd.DataFrame(rows)
    if not out.empty:
        out = out.sort_values(["candidate_label", "rank_score", "avg_10b"], ascending=[True, False, False])
        order = {"CANDIDATE": 0, "WATCH": 1, "LOW_SAMPLE": 2, "REJECT": 3}
        out["_order"] = out["candidate_label"].map(order).fillna(9)
        out = out.sort_values(["_order", "rank_score"], ascending=[True, False]).drop(columns=["_order"])
    return out


def _alternative_source_tournament_runner_v52_pack(ctx: dict[str, Any] | None = None) -> dict[str, Any]:
    """V5.2 — Alternative Source Tournament Runner. Read-only source-only tournament."""
    ctx = ctx if isinstance(ctx, dict) else {}
    try:
        ticker = str(ctx.get("ticker", "") or "")
        features = _v52_v60_prepare_external_features(_v52_v60_ctx_get_external_features(ctx), ticker=ticker)
        price_df = _v52_v60_ctx_get_price_frame(ctx)
        v51 = _v52_v60_ctx_get_dict(ctx, "v51_pack")
        v51_tournament = _v52_v60_as_df(v51.get("tournament"))
        event_table = _v52_v60_build_rule_events(features, price_df)
        if not event_table.empty:
            tournament = _v52_v60_score_rule_events(event_table)
            evidence_mode = "event_forward_returns"
        elif not v51_tournament.empty:
            tournament = v51_tournament.copy()
            rename = {}
            for old, new in [("rank_score", "rank_score"), ("feature", "feature"), ("family", "family"), ("rows", "events"), ("sources", "sources")]:
                if old in tournament.columns and new not in tournament.columns:
                    rename[old] = new
            if rename:
                tournament = tournament.rename(columns=rename)
            if "rule" not in tournament.columns:
                tournament["rule"] = "v51_candidate_rule"
            if "side" not in tournament.columns:
                tournament["side"] = "LONG"
            if "candidate_label" not in tournament.columns:
                tournament["candidate_label"] = np.where(pd.to_numeric(tournament.get("rank_score", 0), errors="coerce") >= 65, "CANDIDATE", "WATCH")
            event_table = pd.DataFrame()
            evidence_mode = "v51_fallback_no_price_forward"
        else:
            tournament = pd.DataFrame()
            evidence_mode = "no_candidate_data"
        candidates = tournament[tournament.get("candidate_label", pd.Series(dtype=str)).astype(str).eq("CANDIDATE")].copy() if not tournament.empty else pd.DataFrame()
        watch = tournament[tournament.get("candidate_label", pd.Series(dtype=str)).astype(str).eq("WATCH")].copy() if not tournament.empty else pd.DataFrame()
        top = tournament.head(1).iloc[0] if not tournament.empty else None
        candidate_count = int(len(candidates))
        watch_count = int(len(watch))
        top_feature = str(top.get("feature", "N/A")) if top is not None else "N/A"
        top_family = str(top.get("family", "N/A")) if top is not None else "N/A"
        top_rule = str(top.get("rule", "N/A")) if top is not None else "N/A"
        top_score = _safe_float(top.get("rank_score"), 0.0) if top is not None else 0.0
        if candidate_count > 0:
            level = "Alternative tournament candidate found"
            decision = "READY_FOR_V53_CHAMPION_SELECTION"
            read = "V5.2 a identifié au moins une source alternative candidate en lecture seule."
            score = max(60.0, top_score)
        elif watch_count > 0:
            level = "Alternative tournament watchlist only"
            decision = "EXPAND_OR_REFINE_ALTERNATIVES_BEFORE_V53"
            read = "V5.2 trouve des alternatives partielles mais pas encore assez robustes."
            score = max(35.0, min(64.0, top_score))
        else:
            level = "No alternative source candidate"
            decision = "RETURN_TO_V51_OR_EXPAND_DATA"
            read = "Aucune source alternative ne passe les seuils minimaux du tournoi."
            score = max(0.0, min(40.0, top_score))
        gates = pd.DataFrame([
            ["No engine impact", "ENFORCED", "read-only", "Le tournoi ne modifie aucun signal moteur."],
            ["Event forward mode", "PASS" if evidence_mode == "event_forward_returns" else "REVIEW", evidence_mode, "Forward returns calculés seulement si prix et timestamps disponibles."],
            ["Candidate count", "PASS" if candidate_count > 0 else "NOT YET", candidate_count, "Nombre de sources candidates."],
            ["Watch count", "PASS" if watch_count > 0 else "SKIP", watch_count, "Sources à raffiner."],
        ], columns=["Gate", "Status", "Value", "Read"])
        summary = pd.DataFrame([
            ["V5.2 level", level, "Lecture synthétique du tournoi alternatif."],
            ["V5.2 score", f"{_format_num(score, 0)}/100", "Score research, pas performance live."],
            ["Decision", decision, "Décision V5.2."],
            ["Read", read, "Interprétation opérationnelle."],
            ["Evidence mode", evidence_mode, "Source du scoring."],
            ["Top alternative", f"{top_family}/{top_feature}/{top_rule}", "Meilleur candidat courant."],
            ["Candidate count", str(candidate_count), "Candidats prêts pour V5.3."],
            ["Watch count", str(watch_count), "Alternatives à enrichir."],
        ], columns=["Metric", "Value", "Read"])
        next_actions = pd.DataFrame([
            ["P0", "Do not inject signal", "research-only", "Aucun signal alternatif ne va dans le moteur."],
            ["P0", "Run V5.3 only after candidate", f"candidates={candidate_count}", "Sélection champion seulement si le tournoi produit un candidat."],
            ["P1", "Promote top source to champion audit", top_feature, "Auditer concentration, stabilité et provenance."],
            ["P2", "Expand events if watchlist only", f"watch={watch_count}", "Ajouter événements/sources avant retest."],
        ], columns=["Priority", "Action", "Reason", "Next Step"])
        cards = [
            {"label": "V5.2 tournament", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Top alternative", "value": top_feature, "delta": top_family},
            {"label": "Top rule", "value": top_rule, "delta": "source-only"},
            {"label": "Candidates", "value": str(candidate_count), "delta": "pass"},
            {"label": "Watchlist", "value": str(watch_count), "delta": "review"},
            {"label": "Decision", "value": decision, "delta": "research only"},
        ]
        return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": cards, "summary": summary, "gates": gates, "tournament": tournament, "event_table": event_table, "next_actions": next_actions, "candidate_count": candidate_count, "watch_count": watch_count, "top_feature": top_feature, "top_family": top_family, "top_rule": top_rule, "evidence_mode": evidence_mode}
    except Exception as exc:
        return {"enabled": True, "level": "V5.2 error", "score": 0.0, "decision": "V52_ERROR_SAFE_SKIP", "read": f"Erreur V5.2 : {exc}", "cards": [], "summary": pd.DataFrame([["V5.2 error", str(exc), "Erreur capturée."]], columns=["Metric", "Value", "Read"]), "gates": pd.DataFrame(), "tournament": pd.DataFrame(), "event_table": pd.DataFrame(), "next_actions": pd.DataFrame(), "candidate_count": 0, "watch_count": 0}


def _champion_selection_gate_v53_pack(ctx: dict[str, Any] | None, v52_pack: dict[str, Any]) -> dict[str, Any]:
    """V5.3 — Alternative Source Winner Audit / Champion Selection Gate."""
    try:
        v52_pack = v52_pack if isinstance(v52_pack, dict) else {}
        tournament = _v52_v60_as_df(v52_pack.get("tournament"))
        if tournament.empty:
            champion = None
        else:
            candidate_mask = tournament.get("candidate_label", pd.Series("", index=tournament.index)).astype(str).eq("CANDIDATE")
            eligible = tournament[candidate_mask].copy()
            champion = (eligible if not eligible.empty else tournament).head(1).iloc[0]
        if champion is None:
            level = "No champion selectable"
            decision = "RETURN_TO_V52_BEFORE_V53"
            read = "Aucun champion alternatif sélectionnable."
            score = 0.0
            champion_table = pd.DataFrame()
            gates = pd.DataFrame([["Champion exists", "FAIL", "0", "V5.3 exige un candidat V5.2."]], columns=["Gate", "Status", "Value", "Read"])
        else:
            events = int(_safe_float(champion.get("events"), 0))
            sources = int(_safe_float(champion.get("sources"), 0))
            dates = int(_safe_float(champion.get("unique_dates"), 0))
            avg10 = _safe_float(champion.get("avg_10b"), np.nan)
            hit10 = _safe_float(champion.get("hit_10b"), np.nan)
            worst10 = _safe_float(champion.get("worst_10b"), np.nan)
            rank_score = _safe_float(champion.get("rank_score"), 0.0)
            pass_sample = events >= 8
            pass_sources = sources >= 2
            pass_perf = pd.notna(avg10) and avg10 > 0
            pass_hit = pd.notna(hit10) and hit10 >= 0.52
            pass_tail = pd.isna(worst10) or worst10 > -0.25
            gate_passes = sum([pass_sample, pass_sources, pass_perf, pass_hit, pass_tail])
            score = max(0.0, min(100.0, 0.55 * rank_score + gate_passes * 8.0))
            if all([pass_sample, pass_sources, pass_perf, pass_hit, pass_tail]) and score >= 65:
                level = "Champion source selected"
                decision = "PROMOTE_CHAMPION_TO_V54_CONTRACT"
                read = "V5.3 sélectionne un champion source pour contrat causal."
            elif pass_sample and pass_perf:
                level = "Champion watchlist"
                decision = "WATCH_CHAMPION_MORE_DATA_BEFORE_V54"
                read = "Champion partiel : demander plus de sources/dates avant contrat final."
            else:
                level = "Champion rejected"
                decision = "REJECT_ALL_ALT_SOURCES"
                read = "Aucune alternative ne mérite un contrat causal à ce stade."
            champion_table = pd.DataFrame([champion.to_dict()])
            gates = pd.DataFrame([
                ["Sample events", "PASS" if pass_sample else "FAIL", f"{events}/8", "Minimum pratique avant contrat."],
                ["Source diversity", "PASS" if pass_sources else "FAIL", f"{sources}/2", "Évite une validation mono-provider."],
                ["Avg 10B positive", "PASS" if pass_perf else "FAIL", _format_pct(avg10), "Rendement actif forward 10B moyen."],
                ["Hit 10B", "PASS" if pass_hit else "REVIEW", _format_pct(hit10), "Hit-rate minimal."],
                ["Tail event", "PASS" if pass_tail else "WARN", _format_pct(worst10), "Pire événement 10B."],
            ], columns=["Gate", "Status", "Value", "Read"])
        summary = pd.DataFrame([
            ["V5.3 level", level, "Lecture synthétique champion."],
            ["V5.3 score", f"{_format_num(score, 0)}/100", "Score champion, pas score live."],
            ["Decision", decision, "Décision V5.3."],
            ["Read", read, "Interprétation opérationnelle."],
            ["Champion", "N/A" if champion is None else f"{champion.get('family')}/{champion.get('feature')}/{champion.get('rule')}", "Source champion auditée."],
        ], columns=["Metric", "Value", "Read"])
        cards = [
            {"label": "V5.3 champion", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Champion feature", "value": "N/A" if champion is None else str(champion.get("feature", "N/A")), "delta": "selected"},
            {"label": "Decision", "value": decision, "delta": "gate"},
        ]
        return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": cards, "summary": summary, "gates": gates, "champion": champion_table, "champion_row": champion.to_dict() if champion is not None else {}, "next_actions": pd.DataFrame([["P1", "Build causal contract", decision, "Continuer vers V5.4 seulement si champion promu ou watch review assumé."]], columns=["Priority", "Action", "Reason", "Next Step"])}
    except Exception as exc:
        return {"enabled": True, "level": "V5.3 error", "score": 0.0, "decision": "V53_ERROR_SAFE_SKIP", "read": f"Erreur V5.3 : {exc}", "cards": [], "summary": pd.DataFrame([["V5.3 error", str(exc), "Erreur capturée."]], columns=["Metric", "Value", "Read"]), "gates": pd.DataFrame(), "champion": pd.DataFrame(), "champion_row": {}, "next_actions": pd.DataFrame()}


def _causal_signal_contract_builder_v54_pack(ctx: dict[str, Any] | None, v53_pack: dict[str, Any], v52_pack: dict[str, Any]) -> dict[str, Any]:
    """V5.4 — Causal Signal Contract Builder. Creates a standard source contract and compatible Custom Signal CSV preview."""
    try:
        ctx = ctx if isinstance(ctx, dict) else {}
        v53_pack = v53_pack if isinstance(v53_pack, dict) else {}
        champ = v53_pack.get("champion_row", {}) if isinstance(v53_pack.get("champion_row", {}), dict) else {}
        event_table = _v52_v60_as_df(v52_pack.get("event_table") if isinstance(v52_pack, dict) else None)
        decision_in = str(v53_pack.get("decision", ""))
        can_build = bool(champ) and decision_in in {"PROMOTE_CHAMPION_TO_V54_CONTRACT", "WATCH_CHAMPION_MORE_DATA_BEFORE_V54"}
        if not can_build:
            level = "Contract blocked"
            decision = "WAIT_FOR_V53_CHAMPION_BEFORE_V54"
            read = "V5.4 attend un champion V5.3 exploitable."
            score = 0.0
            contract = pd.DataFrame()
            signal_csv = pd.DataFrame()
        else:
            family = str(champ.get("family", "unknown"))
            feature = str(champ.get("feature", "unknown"))
            rule = str(champ.get("rule", "source_rule"))
            side = str(champ.get("side", "LONG"))
            source_id = f"SRC_{family}_{feature}_{rule}".upper().replace(" ", "_").replace("/", "_")[:96]
            score = max(35.0, min(100.0, _safe_float(champ.get("rank_score"), _safe_float(v53_pack.get("score"), 0.0))))
            contract = pd.DataFrame([
                ["source_id", source_id, "Identifiant stable de source."],
                ["feature_family", family, "Famille causale."],
                ["feature_name", feature, "Feature champion."],
                ["rule_name", rule, "Règle source-only sélectionnée."],
                ["direction", side, "Direction du signal contractuel."],
                ["available_at_rule", "mandatory", "Toute ligne doit avoir available_at."],
                ["execution_lag", "t+1", "Décision sur prochaine barre tradable."],
                ["engine_injection", "forbidden", "Le contrat n'injecte rien dans le moteur courant."],
                ["status", "research_contract", "Contrat compatible Custom Signal Import mais non promu live."],
            ], columns=["Field", "Value", "Read"])
            if not event_table.empty:
                mask = (
                    event_table.get("family", pd.Series(dtype=str)).astype(str).eq(family)
                    & event_table.get("feature", pd.Series(dtype=str)).astype(str).eq(feature)
                    & event_table.get("rule", pd.Series(dtype=str)).astype(str).eq(rule)
                )
                ev = event_table.loc[mask].copy()
                exposure = 1.0 if side.upper() == "LONG" else -1.0
                if not ev.empty:
                    signal_csv = pd.DataFrame({
                        "date": ev.get("decision_date"),
                        "signal": exposure,
                        "exposure": exposure,
                        "source_id": source_id,
                        "available_at": ev.get("available_at"),
                        "rule_name": rule,
                        "confidence": ev.get("confidence", 0.50),
                        "notes": "V5.4 contract preview; research-only; t+1 enforced by Custom Signal Import",
                    }).dropna(subset=["date"])
                else:
                    signal_csv = pd.DataFrame()
            else:
                signal_csv = pd.DataFrame()
            level = "Source signal contract ready" if not signal_csv.empty else "Contract ready / no event CSV"
            decision = "SOURCE_SIGNAL_CONTRACT_READY" if not signal_csv.empty else "SOURCE_SIGNAL_CONTRACT_NEEDS_EVENT_ROWS"
            read = "V5.4 a créé un contrat causal standardisé, lecture seule."
        gates = pd.DataFrame([
            ["V5.3 champion", "PASS" if can_build else "FAIL", decision_in or "N/A", "Contrat seulement après champion."],
            ["available_at", "ENFORCED", "mandatory", "Anti-leakage."],
            ["t+1", "ENFORCED", "next bar", "Pas de same-close lookahead."],
            ["Engine injection", "BLOCKED", "read-only", "Le contrat reste externe."],
        ], columns=["Gate", "Status", "Value", "Read"])
        summary = pd.DataFrame([
            ["V5.4 level", level, "Lecture synthétique contract builder."],
            ["V5.4 score", f"{_format_num(score, 0)}/100", "Score de contrat."],
            ["Decision", decision, "Décision V5.4."],
            ["Read", read, "Interprétation opérationnelle."],
            ["Contract rows", str(len(contract)), "Lignes du contrat."],
            ["Signal CSV rows", str(len(signal_csv)), "Prévisualisation compatible Custom Signal Import."],
        ], columns=["Metric", "Value", "Read"])
        cards = [{"label": "V5.4 contract", "value": level, "delta": f"{_format_num(score, 0)}/100"}, {"label": "Signal rows", "value": str(len(signal_csv)), "delta": "preview"}, {"label": "Decision", "value": decision, "delta": "contract"}]
        return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": cards, "summary": summary, "gates": gates, "contract": contract, "signal_csv": signal_csv, "source_id": contract.loc[contract["Field"].eq("source_id"), "Value"].iloc[0] if not contract.empty else ""}
    except Exception as exc:
        return {"enabled": True, "level": "V5.4 error", "score": 0.0, "decision": "V54_ERROR_SAFE_SKIP", "read": f"Erreur V5.4 : {exc}", "cards": [], "summary": pd.DataFrame([["V5.4 error", str(exc), "Erreur capturée."]], columns=["Metric", "Value", "Read"]), "gates": pd.DataFrame(), "contract": pd.DataFrame(), "signal_csv": pd.DataFrame(), "source_id": ""}


def _source_only_strategy_sandbox_v55_pack(ctx: dict[str, Any] | None, v54_pack: dict[str, Any]) -> dict[str, Any]:
    """V5.5 — Source-Only Strategy Sandbox. Isolated equity curve, never main engine."""
    try:
        ctx = ctx if isinstance(ctx, dict) else {}
        signal_csv = _v52_v60_as_df(v54_pack.get("signal_csv") if isinstance(v54_pack, dict) else None)
        price_df = _v52_v60_ctx_get_price_frame(ctx)
        close_col = _v52_v60_pick_col(price_df, ["close"]) if not price_df.empty else None
        if signal_csv.empty or price_df.empty or close_col is None or not isinstance(price_df.index, pd.DatetimeIndex):
            level = "Sandbox blocked"
            decision = "WAIT_FOR_V54_CONTRACT_AND_PRICE_DATA"
            read = "V5.5 exige un contrat signal et une série de prix datée."
            score = 0.0
            sandbox = pd.DataFrame()
            metrics = pd.DataFrame()
        else:
            close = pd.to_numeric(price_df[close_col], errors="coerce").replace([np.inf, -np.inf], np.nan).ffill().dropna()
            returns = close.pct_change().fillna(0.0)
            sig = signal_csv.copy()
            sig_dates = pd.to_datetime(sig["date"], errors="coerce")
            sig_values = pd.to_numeric(sig.get("exposure", sig.get("signal", 0.0)), errors="coerce").fillna(0.0).clip(-1.0, 1.0)
            signal_series = pd.Series(0.0, index=close.index)
            idx = pd.to_datetime(close.index)
            for dt, val in zip(sig_dates, sig_values):
                if pd.isna(dt):
                    continue
                positions = np.where(idx.normalize() >= pd.Timestamp(dt).normalize())[0]
                if len(positions) > 0:
                    signal_series.iloc[int(positions[0])] = float(val)
            raw_signal = signal_series.replace(0.0, np.nan).ffill().fillna(0.0).clip(-1.0, 1.0)
            engine_signal = raw_signal.shift(1).fillna(0.0).clip(-1.0, 1.0)
            fee_bps = _safe_float(ctx.get("fee_bps"), np.nan)
            slip_bps = _safe_float(ctx.get("slippage_bps"), np.nan)
            if pd.isna(fee_bps):
                fee_bps = _safe_float(getattr(ctx.get("cfg", None), "fee_bps", 2.0), 2.0)
            if pd.isna(slip_bps):
                slip_bps = _safe_float(getattr(ctx.get("cfg", None), "slippage_bps", 5.0), 5.0)
            turnover = engine_signal.diff().abs().fillna(engine_signal.abs())
            costs = turnover * (fee_bps + slip_bps) / 10000.0
            strat_ret = engine_signal * returns - costs
            equity = (1.0 + strat_ret).cumprod()
            sandbox = pd.DataFrame({"close": close, "raw_signal": raw_signal, "engine_signal_t1": engine_signal, "returns": returns, "turnover": turnover, "costs": costs, "strategy_return": strat_ret, "sandbox_equity": equity})
            obs = int(len(sandbox))
            active = int((engine_signal.abs() > 0).sum())
            total = float(equity.iloc[-1] / equity.iloc[0] - 1.0) if len(equity) > 1 else 0.0
            vol = float(strat_ret.std() * np.sqrt(252)) if strat_ret.std() > 0 else np.nan
            sharpe = float(strat_ret.mean() / strat_ret.std() * np.sqrt(252)) if strat_ret.std() > 0 else np.nan
            dd = equity / equity.cummax() - 1.0
            maxdd = float(dd.min()) if not dd.empty else np.nan
            hit = float((strat_ret[strat_ret != 0] > 0).mean()) if (strat_ret != 0).any() else np.nan
            if active >= 8 and total > 0 and pd.notna(sharpe) and sharpe > 0:
                level = "Source sandbox edge present"
                decision = "SOURCE_SANDBOX_EDGE_PRESENT"
                score = min(100.0, 50.0 + total * 100.0 + max(0.0, sharpe) * 10.0)
                read = "V5.5 sandbox isolé positif ; continuer vers robustesse OOS."
            elif active >= 5:
                level = "Source sandbox watch only"
                decision = "SOURCE_SANDBOX_WATCH_ONLY"
                score = 45.0
                read = "Sandbox calculé mais edge insuffisant ou fragile."
            else:
                level = "Source sandbox low sample"
                decision = "SOURCE_SANDBOX_REJECTED_OR_LOW_SAMPLE"
                score = 25.0
                read = "Trop peu d'exposition sandbox pour conclure."
            metrics = pd.DataFrame([
                ["Rows", str(obs), "Observations sandbox."],
                ["Active bars", str(active), "Barres exposées après t+1."],
                ["Total return", _format_pct(total), "Rendement sandbox isolé."],
                ["Sharpe", _format_num(sharpe), "Sharpe sandbox."],
                ["Volatility", _format_pct(vol), "Vol annualisée."],
                ["Max drawdown", _format_pct(maxdd), "Drawdown sandbox."],
                ["Hit active days", _format_pct(hit), "Jours exposés positifs."],
                ["Cost drag", _format_pct(float(costs.sum())), "Coûts sandbox."],
            ], columns=["Metric", "Value", "Read"])
        summary = pd.DataFrame([["V5.5 level", level, "Lecture sandbox."], ["V5.5 score", f"{_format_num(score, 0)}/100", "Score sandbox."], ["Decision", decision, "Décision V5.5."], ["Read", read, "Interprétation."]], columns=["Metric", "Value", "Read"])
        cards = [{"label": "V5.5 sandbox", "value": level, "delta": f"{_format_num(score, 0)}/100"}, {"label": "Decision", "value": decision, "delta": "isolated"}]
        return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": cards, "summary": summary, "metrics": metrics, "sandbox": sandbox}
    except Exception as exc:
        return {"enabled": True, "level": "V5.5 error", "score": 0.0, "decision": "V55_ERROR_SAFE_SKIP", "read": f"Erreur V5.5 : {exc}", "cards": [], "summary": pd.DataFrame([["V5.5 error", str(exc), "Erreur capturée."]], columns=["Metric", "Value", "Read"]), "metrics": pd.DataFrame(), "sandbox": pd.DataFrame()}


def _oos_robustness_gate_v56_pack(ctx: dict[str, Any] | None, v55_pack: dict[str, Any]) -> dict[str, Any]:
    """V5.6 — Source Strategy Robustness / OOS Gate."""
    try:
        sandbox = _v52_v60_as_df(v55_pack.get("sandbox") if isinstance(v55_pack, dict) else None)
        if sandbox.empty or "strategy_return" not in sandbox.columns or len(sandbox) < 60:
            level = "OOS gate blocked"
            decision = "WAIT_FOR_V55_SANDBOX_SAMPLE"
            read = "V5.6 exige un sandbox avec au moins 60 observations."
            score = 0.0
            split = pd.DataFrame()
            wf = pd.DataFrame()
            boot = pd.DataFrame()
        else:
            r = pd.to_numeric(sandbox["strategy_return"], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
            n = len(r)
            split_pos = int(n * 0.60)
            parts = {"IS 60%": r.iloc[:split_pos], "OOS 40%": r.iloc[split_pos:], "Full": r}
            rows = []
            for name, s in parts.items():
                eq = (1.0 + s).cumprod()
                dd = eq / eq.cummax() - 1.0
                rows.append({"Segment": name, "Obs": int(len(s)), "Return": float(eq.iloc[-1] / eq.iloc[0] - 1.0) if len(eq) > 1 else 0.0, "Sharpe": float(s.mean() / s.std() * np.sqrt(252)) if s.std() > 0 else np.nan, "Max DD": float(dd.min()) if not dd.empty else np.nan, "Hit": float((s > 0).mean()) if len(s) else np.nan})
            split = pd.DataFrame(rows)
            wf_rows = []
            segments = 5
            for i, chunk in enumerate(np.array_split(r, segments)):
                if len(chunk) < 5:
                    continue
                eq = (1.0 + pd.Series(chunk)).cumprod()
                wf_rows.append({"Window": f"WF {i+1}", "Obs": int(len(chunk)), "Return": float(eq.iloc[-1] / eq.iloc[0] - 1.0) if len(eq) > 1 else 0.0, "Sharpe": float(pd.Series(chunk).mean() / pd.Series(chunk).std() * np.sqrt(252)) if pd.Series(chunk).std() > 0 else np.nan})
            wf = pd.DataFrame(wf_rows)
            rng = np.random.default_rng(42)
            boot_returns = []
            clean = r.dropna().values
            if len(clean) > 10:
                for _ in range(200):
                    sample = rng.choice(clean, size=len(clean), replace=True)
                    boot_returns.append(float(np.prod(1.0 + sample) - 1.0))
            boot = pd.DataFrame({"Metric": ["Bootstrap median", "Bootstrap p05", "Bootstrap positive share"], "Value": [np.nanmedian(boot_returns) if boot_returns else np.nan, np.nanpercentile(boot_returns, 5) if boot_returns else np.nan, float((np.array(boot_returns) > 0).mean()) if boot_returns else np.nan], "Read": ["Médiane bootstrap.", "Queue gauche bootstrap.", "Part des samples positifs."]})
            oos_row = split[split["Segment"].eq("OOS 40%")].head(1)
            oos_ret = _safe_float(oos_row.iloc[0].get("Return"), np.nan) if not oos_row.empty else np.nan
            oos_sharpe = _safe_float(oos_row.iloc[0].get("Sharpe"), np.nan) if not oos_row.empty else np.nan
            wf_positive = float((pd.to_numeric(wf.get("Return", pd.Series(dtype=float)), errors="coerce") > 0).mean()) if not wf.empty else 0.0
            boot_pos = _safe_float(boot.loc[boot["Metric"].eq("Bootstrap positive share"), "Value"].iloc[0], np.nan) if not boot.empty else np.nan
            score = 35.0
            if pd.notna(oos_ret): score += max(-20, min(25, oos_ret * 150))
            if pd.notna(oos_sharpe): score += max(-10, min(20, oos_sharpe * 8))
            score += wf_positive * 15.0
            if pd.notna(boot_pos): score += (boot_pos - 0.5) * 20.0
            score = max(0.0, min(100.0, score))
            if pd.notna(oos_ret) and oos_ret > 0 and wf_positive >= 0.60 and pd.notna(boot_pos) and boot_pos >= 0.55:
                level = "Source strategy OOS validated"
                decision = "SOURCE_STRATEGY_OOS_VALIDATED"
                read = "V5.6 valide provisoirement le sandbox hors-échantillon."
            elif score >= 45:
                level = "Source strategy fragile watch"
                decision = "SOURCE_STRATEGY_FRAGILE_WATCH"
                read = "OOS mitigé : ne pas promouvoir sans stress/attribution." 
            else:
                level = "Source strategy OOS rejected"
                decision = "SOURCE_STRATEGY_OOS_REJECTED"
                read = "OOS insuffisant ou négatif."
        summary = pd.DataFrame([["V5.6 level", level, "Lecture OOS."], ["V5.6 score", f"{_format_num(score, 0)}/100", "Score robustesse."], ["Decision", decision, "Décision V5.6."], ["Read", read, "Interprétation."]], columns=["Metric", "Value", "Read"])
        cards = [{"label": "V5.6 OOS", "value": level, "delta": f"{_format_num(score, 0)}/100"}, {"label": "Decision", "value": decision, "delta": "robustness"}]
        return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": cards, "summary": summary, "split": split, "walk_forward": wf, "bootstrap": boot}
    except Exception as exc:
        return {"enabled": True, "level": "V5.6 error", "score": 0.0, "decision": "V56_ERROR_SAFE_SKIP", "read": f"Erreur V5.6 : {exc}", "cards": [], "summary": pd.DataFrame([["V5.6 error", str(exc), "Erreur capturée."]], columns=["Metric", "Value", "Read"]), "split": pd.DataFrame(), "walk_forward": pd.DataFrame(), "bootstrap": pd.DataFrame()}


def _source_strategy_stress_lab_v57_pack(ctx: dict[str, Any] | None, v55_pack: dict[str, Any], v56_pack: dict[str, Any]) -> dict[str, Any]:
    """V5.7 — Source Strategy Stress Lab."""
    try:
        sandbox = _v52_v60_as_df(v55_pack.get("sandbox") if isinstance(v55_pack, dict) else None)
        if sandbox.empty or "strategy_return" not in sandbox.columns:
            level = "Stress blocked"
            decision = "WAIT_FOR_V55_SANDBOX_BEFORE_STRESS"
            read = "V5.7 exige un sandbox."
            score = 0.0
            stress = pd.DataFrame()
        else:
            base = pd.to_numeric(sandbox["strategy_return"], errors="coerce").fillna(0.0)
            turnover = pd.to_numeric(sandbox.get("turnover", pd.Series(0.0, index=sandbox.index)), errors="coerce").fillna(0.0)
            rows = []
            for slip in [0, 5, 10, 20, 35]:
                for gap in [0, 25, 50, 100]:
                    stressed = base - turnover * slip / 10000.0
                    if gap > 0:
                        active = pd.to_numeric(sandbox.get("engine_signal_t1", pd.Series(0.0, index=sandbox.index)), errors="coerce").fillna(0.0).abs() > 0
                        adverse = np.where(active, -gap / 10000.0, 0.0)
                        stressed = stressed + adverse
                    eq = (1.0 + stressed).cumprod()
                    dd = eq / eq.cummax() - 1.0
                    rows.append({"Slippage bps": slip, "Gap haircut bps": gap, "Return": float(eq.iloc[-1] / eq.iloc[0] - 1.0) if len(eq) > 1 else 0.0, "Sharpe": float(stressed.mean() / stressed.std() * np.sqrt(252)) if stressed.std() > 0 else np.nan, "Max DD": float(dd.min()) if not dd.empty else np.nan})
            stress = pd.DataFrame(rows)
            severe = stress[(stress["Slippage bps"] >= 20) & (stress["Gap haircut bps"] >= 50)]
            severe_positive = float((severe["Return"] > 0).mean()) if not severe.empty else 0.0
            worst = float(stress["Return"].min()) if not stress.empty else np.nan
            score = max(0.0, min(100.0, 40.0 + severe_positive * 40.0 + max(-20.0, min(20.0, _safe_float(worst, 0.0) * 100.0))))
            if severe_positive >= 0.50 and _safe_float(worst, -1.0) > -0.20:
                level = "Source strategy stress resilient"
                decision = "SOURCE_STRATEGY_STRESS_RESILIENT"
                read = "Sandbox résilient aux coûts/gaps testés."
            elif severe_positive > 0:
                level = "Source strategy stress fragile"
                decision = "SOURCE_STRATEGY_STRESS_FRAGILE"
                read = "Stress mitigé : conserver en watchlist."
            else:
                level = "Source strategy stress rejected"
                decision = "SOURCE_STRATEGY_STRESS_REJECTED"
                read = "Stress défavorable : ne pas promouvoir."
        summary = pd.DataFrame([["V5.7 level", level, "Lecture stress."], ["V5.7 score", f"{_format_num(score, 0)}/100", "Score stress."], ["Decision", decision, "Décision V5.7."], ["Read", read, "Interprétation."]], columns=["Metric", "Value", "Read"])
        return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": [{"label": "V5.7 stress", "value": level, "delta": f"{_format_num(score, 0)}/100"}], "summary": summary, "stress_matrix": stress}
    except Exception as exc:
        return {"enabled": True, "level": "V5.7 error", "score": 0.0, "decision": "V57_ERROR_SAFE_SKIP", "read": f"Erreur V5.7 : {exc}", "cards": [], "summary": pd.DataFrame([["V5.7 error", str(exc), "Erreur capturée."]], columns=["Metric", "Value", "Read"]), "stress_matrix": pd.DataFrame()}


def _source_attribution_explainability_v58_pack(ctx: dict[str, Any] | None, v52_pack: dict[str, Any], v55_pack: dict[str, Any]) -> dict[str, Any]:
    """V5.8 — Source Attribution & Explainability Layer."""
    try:
        event_table = _v52_v60_as_df(v52_pack.get("event_table") if isinstance(v52_pack, dict) else None)
        sandbox = _v52_v60_as_df(v55_pack.get("sandbox") if isinstance(v55_pack, dict) else None)
        by_rule = pd.DataFrame()
        top_events = pd.DataFrame()
        if not event_table.empty:
            cols = [c for c in ["family", "feature", "rule", "source"] if c in event_table.columns]
            if cols and "fwd_10b" in event_table.columns:
                by_rule = event_table.groupby(cols, dropna=False).agg(events=("fwd_10b", "size"), avg_10b=("fwd_10b", "mean"), hit_10b=("fwd_10b", lambda x: float((pd.to_numeric(x, errors="coerce") > 0).mean()))).reset_index()
                by_rule = by_rule.sort_values("avg_10b", ascending=False)
                top_events = event_table.sort_values("fwd_10b", ascending=False).head(20)
        sandbox_stats = pd.DataFrame()
        if not sandbox.empty and "strategy_return" in sandbox.columns:
            r = pd.to_numeric(sandbox["strategy_return"], errors="coerce").fillna(0.0)
            pos = float(r[r > 0].sum()) if (r > 0).any() else 0.0
            neg = float(r[r < 0].sum()) if (r < 0).any() else 0.0
            sandbox_stats = pd.DataFrame([["Gross positive contribution", _format_pct(pos), "Somme des jours positifs."], ["Gross negative contribution", _format_pct(neg), "Somme des jours négatifs."], ["Skew proxy", _format_num(r.skew()), "Skew des rendements sandbox."], ["Kurtosis proxy", _format_num(r.kurtosis()), "Kurtosis des rendements sandbox."]], columns=["Metric", "Value", "Read"])
        explained = not by_rule.empty or not sandbox_stats.empty
        score = 70.0 if explained else 20.0
        level = "Source edge explained" if explained else "Source edge unexplained"
        decision = "SOURCE_EDGE_EXPLAINED" if explained else "SOURCE_EDGE_UNEXPLAINED_REJECT"
        read = "V5.8 fournit une attribution exploitable." if explained else "Aucune attribution suffisante disponible."
        summary = pd.DataFrame([["V5.8 level", level, "Lecture attribution."], ["V5.8 score", f"{_format_num(score, 0)}/100", "Score explainability."], ["Decision", decision, "Décision V5.8."], ["Read", read, "Interprétation."]], columns=["Metric", "Value", "Read"])
        return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": [{"label": "V5.8 attribution", "value": level, "delta": f"{_format_num(score, 0)}/100"}], "summary": summary, "by_rule": by_rule, "top_events": top_events, "sandbox_stats": sandbox_stats}
    except Exception as exc:
        return {"enabled": True, "level": "V5.8 error", "score": 0.0, "decision": "V58_ERROR_SAFE_SKIP", "read": f"Erreur V5.8 : {exc}", "cards": [], "summary": pd.DataFrame([["V5.8 error", str(exc), "Erreur capturée."]], columns=["Metric", "Value", "Read"]), "by_rule": pd.DataFrame(), "top_events": pd.DataFrame(), "sandbox_stats": pd.DataFrame()}


def _strategy_tournament_integration_gate_v59_pack(ctx: dict[str, Any] | None, v55_pack: dict[str, Any], v56_pack: dict[str, Any], v57_pack: dict[str, Any], v58_pack: dict[str, Any]) -> dict[str, Any]:
    """V5.9 — Strategy Tournament Integration Gate."""
    try:
        d55 = str((v55_pack or {}).get("decision", ""))
        d56 = str((v56_pack or {}).get("decision", ""))
        d57 = str((v57_pack or {}).get("decision", ""))
        d58 = str((v58_pack or {}).get("decision", ""))
        passes = {
            "sandbox": d55 == "SOURCE_SANDBOX_EDGE_PRESENT",
            "oos": d56 == "SOURCE_STRATEGY_OOS_VALIDATED",
            "stress": d57 == "SOURCE_STRATEGY_STRESS_RESILIENT",
            "explainability": d58 == "SOURCE_EDGE_EXPLAINED",
        }
        pass_count = sum(passes.values())
        score = pass_count * 25.0
        if pass_count >= 4:
            level = "Ready for strategy tournament"
            decision = "ENTER_STRATEGY_TOURNAMENT"
            read = "La source sandbox peut entrer dans le tournoi global research." 
        elif pass_count >= 2:
            level = "Watchlist before tournament"
            decision = "WATCHLIST_BEFORE_TOURNAMENT"
            read = "Source intéressante mais pas assez complète pour tournoi global." 
        else:
            level = "Do not enter tournament"
            decision = "DO_NOT_ENTER_TOURNAMENT"
            read = "Gates insuffisants pour intégrer le Strategy Tournament." 
        gate_table = pd.DataFrame([[k, "PASS" if v else "FAIL", "Gate V5.9", "Condition requise pour entrée tournament."] for k, v in passes.items()], columns=["Gate", "Status", "Value", "Read"])
        summary = pd.DataFrame([["V5.9 level", level, "Lecture tournament integration."], ["V5.9 score", f"{_format_num(score, 0)}/100", "Score d'intégration."], ["Decision", decision, "Décision V5.9."], ["Read", read, "Interprétation."], ["Pass count", f"{pass_count}/4", "Nombre de gates validés."]], columns=["Metric", "Value", "Read"])
        tournament_row = pd.DataFrame([["source_only_candidate", d55, d56, d57, d58, decision]], columns=["Strategy", "Sandbox", "OOS", "Stress", "Explainability", "Tournament Decision"])
        return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": [{"label": "V5.9 tournament", "value": level, "delta": f"{_format_num(score, 0)}/100"}], "summary": summary, "gates": gate_table, "tournament_row": tournament_row}
    except Exception as exc:
        return {"enabled": True, "level": "V5.9 error", "score": 0.0, "decision": "V59_ERROR_SAFE_SKIP", "read": f"Erreur V5.9 : {exc}", "cards": [], "summary": pd.DataFrame([["V5.9 error", str(exc), "Erreur capturée."]], columns=["Metric", "Value", "Read"]), "gates": pd.DataFrame(), "tournament_row": pd.DataFrame()}


def _institutional_finalization_layer_v60_pack(ctx: dict[str, Any] | None, packs: dict[str, dict[str, Any]]) -> dict[str, Any]:
    """V6.0 — Backtest Lab Institutional Finalization Layer."""
    try:
        packs = packs if isinstance(packs, dict) else {}
        decisions = {k: str(v.get("decision", "N/A")) for k, v in packs.items() if isinstance(v, dict)}
        positive = {"V5.2": "READY_FOR_V53_CHAMPION_SELECTION", "V5.3": "PROMOTE_CHAMPION_TO_V54_CONTRACT", "V5.4": "SOURCE_SIGNAL_CONTRACT_READY", "V5.5": "SOURCE_SANDBOX_EDGE_PRESENT", "V5.6": "SOURCE_STRATEGY_OOS_VALIDATED", "V5.7": "SOURCE_STRATEGY_STRESS_RESILIENT", "V5.8": "SOURCE_EDGE_EXPLAINED", "V5.9": "ENTER_STRATEGY_TOURNAMENT"}
        pass_count = sum(1 for k, expected in positive.items() if decisions.get(k) == expected)
        if decisions.get("V5.9") == "ENTER_STRATEGY_TOURNAMENT":
            level = "Backtest Lab research complete"
            decision = "BACKTEST_LAB_RESEARCH_COMPLETE"
            read = "La chaîne source externe est complète en research-only et peut alimenter le Strategy Tournament."
        elif pass_count >= 4:
            level = "Backtest Lab needs more source validation"
            decision = "BACKTEST_LAB_NEEDS_MORE_SOURCE_DATA"
            read = "Plusieurs gates passent, mais la promotion finale reste bloquée." 
        else:
            level = "No valid source edge found"
            decision = "BACKTEST_LAB_NO_VALID_EDGE_FOUND"
            read = "Aucun edge source externe suffisamment validé dans la chaîne finale." 
        score = max(0.0, min(100.0, pass_count / max(len(positive), 1) * 100.0))
        registry = pd.DataFrame([[k, decisions.get(k, "N/A"), "PASS" if decisions.get(k) == expected else "REVIEW/FAIL"] for k, expected in positive.items()], columns=["Section", "Decision", "Registry Status"])
        governance = pd.DataFrame([
            ["No live permission", "ENFORCED", "Même V6.0 ne donne pas de permission live."],
            ["No main engine mutation", "ENFORCED", "Les sections V5.2→V6.0 restent lecture seule."],
            ["Tournament handoff only", "CONDITIONAL", "Uniquement si V5.9 passe."],
            ["Rejected registry retained", "ENFORCED", "Les sources rejetées restent traçables."],
        ], columns=["Rule", "Status", "Read"])
        summary = pd.DataFrame([["V6.0 level", level, "Lecture finalization."], ["V6.0 score", f"{_format_num(score, 0)}/100", "Score de complétude institutionnelle."], ["Decision", decision, "Décision V6.0."], ["Read", read, "Interprétation."], ["Validated gates", f"{pass_count}/{len(positive)}", "Gates positifs finaux."]], columns=["Metric", "Value", "Read"])
        return {"enabled": True, "level": level, "score": score, "decision": decision, "read": read, "cards": [{"label": "V6.0 final", "value": level, "delta": f"{_format_num(score, 0)}/100"}, {"label": "Final decision", "value": decision, "delta": "research"}], "summary": summary, "registry": registry, "governance": governance}
    except Exception as exc:
        return {"enabled": True, "level": "V6.0 error", "score": 0.0, "decision": "V60_ERROR_SAFE_SKIP", "read": f"Erreur V6.0 : {exc}", "cards": [], "summary": pd.DataFrame([["V6.0 error", str(exc), "Erreur capturée."]], columns=["Metric", "Value", "Read"]), "registry": pd.DataFrame(), "governance": pd.DataFrame()}


def _v52_v60_format_display_table(df: pd.DataFrame) -> pd.DataFrame:
    display = _v52_v60_as_df(df)
    if display.empty:
        return display
    for col in display.columns:
        low = _v52_v60_norm_colname(col)
        if any(tok in low for tok in ["return", "avg_", "median", "hit", "drawdown", "dd", "cost", "vol", "p05", "positive_share", "worst"]):
            if pd.api.types.is_numeric_dtype(display[col]):
                display[col] = display[col].map(lambda x: _format_pct(x) if pd.notna(x) else "N/A")
        if any(tok in low for tok in ["score", "sharpe"]):
            if pd.api.types.is_numeric_dtype(display[col]):
                display[col] = display[col].map(lambda x: _format_num(x) if pd.notna(x) else "N/A")
    return display


def _v52_v60_render_section(title: str, caption: str, pack: dict[str, Any], table_map: list[tuple[str, str, bool]]) -> None:
    st.subheader(title)
    st.caption(caption)
    try:
        _card_grid(pack.get("cards", []), columns=6)
    except Exception:
        pass
    read = str(pack.get("read", ""))
    decision = str(pack.get("decision", ""))
    if any(tok in decision for tok in ["READY", "VALIDATED", "PRESENT", "EXPLAINED", "COMPLETE", "ENTER"]):
        st.success(f"Lecture {title.split(' ')[0]} : {read}")
    elif any(tok in decision for tok in ["WAIT", "WATCH", "REFINE", "NEEDS", "EXPAND"]):
        st.warning(f"Lecture {title.split(' ')[0]} : {read}")
    elif any(tok in decision for tok in ["REJECT", "ERROR", "BLOCK", "DO_NOT", "NO_VALID"]):
        st.error(f"Lecture {title.split(' ')[0]} : {read}")
    else:
        st.info(f"Lecture {title.split(' ')[0]} : {read}")
    for exp_title, key, expanded in table_map:
        with st.expander(exp_title, expanded=expanded):
            df = _v52_v60_as_df(pack.get(key))
            if not df.empty:
                st.dataframe(_v52_v60_format_display_table(df), use_container_width=True, hide_index=True)
            else:
                st.info(f"{exp_title} indisponible.")


def _render_backtest_lab_institutional_final_suite_v52_to_v60(ctx: dict[str, Any] | None = None) -> dict[str, Any]:
    """
    Renders the final institutional Backtest Lab suite V5.2 -> V6.0.
    Read-only. Does not alter main engine, sizing, exits, trades, equity curve or verdict.
    """
    ctx = ctx if isinstance(ctx, dict) else {}
    st.subheader("Backtest Lab Institutional Final Suite V5.2 → V6.0")
    st.caption(
        "Suite finale lecture seule : alternative source tournament, champion gate, signal contract, sandbox isolé, "
        "OOS, stress, attribution, Strategy Tournament integration et final registry. Aucun impact moteur."
    )
    v52 = _alternative_source_tournament_runner_v52_pack(ctx)
    v53 = _champion_selection_gate_v53_pack(ctx, v52)
    v54 = _causal_signal_contract_builder_v54_pack(ctx, v53, v52)
    v55 = _source_only_strategy_sandbox_v55_pack(ctx, v54)
    v56 = _oos_robustness_gate_v56_pack(ctx, v55)
    v57 = _source_strategy_stress_lab_v57_pack(ctx, v55, v56)
    v58 = _source_attribution_explainability_v58_pack(ctx, v52, v55)
    v59 = _strategy_tournament_integration_gate_v59_pack(ctx, v55, v56, v57, v58)
    v60 = _institutional_finalization_layer_v60_pack(ctx, {"V5.2": v52, "V5.3": v53, "V5.4": v54, "V5.5": v55, "V5.6": v56, "V5.7": v57, "V5.8": v58, "V5.9": v59})
    _v52_v60_render_section("V5.2 — Alternative Source Tournament Runner", "Tournoi source-only sur alternatives V5.1 : règles causales, événements, sources, forward returns si prix disponibles.", v52, [("V5.2 summary", "summary", True), ("V5.2 gates", "gates", True), ("V5.2 tournament", "tournament", True), ("V5.2 event table", "event_table", False), ("V5.2 next actions", "next_actions", True)])
    _v52_v60_render_section("V5.3 — Alternative Source Winner Audit / Champion Selection Gate", "Sélection d'un champion source ou rejet du panier alternatif.", v53, [("V5.3 summary", "summary", True), ("V5.3 gates", "gates", True), ("V5.3 champion", "champion", True), ("V5.3 next actions", "next_actions", True)])
    _v52_v60_render_section("V5.4 — Causal Signal Contract Builder", "Contrat causal standardisé compatible Custom Signal Import, sans injection moteur.", v54, [("V5.4 summary", "summary", True), ("V5.4 gates", "gates", True), ("V5.4 contract", "contract", True), ("V5.4 custom signal CSV preview", "signal_csv", False)])
    _v52_v60_render_section("V5.5 — Source-Only Strategy Sandbox", "Sandbox isolé de la source contractuelle. Equity curve séparée du moteur principal.", v55, [("V5.5 summary", "summary", True), ("V5.5 metrics", "metrics", True), ("V5.5 sandbox data", "sandbox", False)])
    _v52_v60_render_section("V5.6 — Source Strategy Robustness / OOS Gate", "IS/OOS, walk-forward et bootstrap sur sandbox isolé.", v56, [("V5.6 summary", "summary", True), ("V5.6 split", "split", True), ("V5.6 walk-forward", "walk_forward", True), ("V5.6 bootstrap", "bootstrap", True)])
    _v52_v60_render_section("V5.7 — Source Strategy Stress Lab", "Stress coûts, slippage, gaps et adverse execution proxy.", v57, [("V5.7 summary", "summary", True), ("V5.7 stress matrix", "stress_matrix", True)])
    _v52_v60_render_section("V5.8 — Source Attribution & Explainability Layer", "Attribution par source/règle/feature, contributions et failure map.", v58, [("V5.8 summary", "summary", True), ("V5.8 by rule/source", "by_rule", True), ("V5.8 top events", "top_events", False), ("V5.8 sandbox stats", "sandbox_stats", True)])
    _v52_v60_render_section("V5.9 — Strategy Tournament Integration Gate", "Gate final avant entrée dans le Strategy Tournament global.", v59, [("V5.9 summary", "summary", True), ("V5.9 gates", "gates", True), ("V5.9 tournament row", "tournament_row", True)])
    _v52_v60_render_section("V6.0 — Backtest Lab Institutional Finalization Layer", "Registry final, governance et handoff research-only.", v60, [("V6.0 summary", "summary", True), ("V6.0 registry", "registry", True), ("V6.0 governance", "governance", True)])
    d1, d2, d3 = st.columns(3)
    try:
        zip_buffer = BytesIO()
        with zipfile.ZipFile(zip_buffer, "w", zipfile.ZIP_DEFLATED) as zf:
            export_map = {
                "v52_tournament.csv": v52.get("tournament"),
                "v52_events.csv": v52.get("event_table"),
                "v53_champion.csv": v53.get("champion"),
                "v54_contract.csv": v54.get("contract"),
                "v54_custom_signal_preview.csv": v54.get("signal_csv"),
                "v55_sandbox.csv": v55.get("sandbox"),
                "v56_split.csv": v56.get("split"),
                "v57_stress.csv": v57.get("stress_matrix"),
                "v58_attribution.csv": v58.get("by_rule"),
                "v59_tournament_gate.csv": v59.get("tournament_row"),
                "v60_registry.csv": v60.get("registry"),
            }
            for name, obj in export_map.items():
                df = _v52_v60_as_df(obj)
                if not df.empty:
                    zf.writestr(name, df.to_csv(index=False))
        d1.download_button("Télécharger V5.2→V6.0 research pack ZIP", data=zip_buffer.getvalue(), file_name="backtest_lab_v52_to_v60_research_pack.zip", mime="application/zip", use_container_width=True, key="bt_v52_v60_research_pack_download")
        sig = _v52_v60_as_df(v54.get("signal_csv"))
        if not sig.empty:
            d2.download_button("Télécharger V5.4 Custom Signal CSV", data=sig.to_csv(index=False).encode("utf-8"), file_name="v54_source_signal_contract_custom_signal.csv", mime="text/csv", use_container_width=True, key="bt_v54_contract_signal_download")
        reg = _v52_v60_as_df(v60.get("registry"))
        if not reg.empty:
            d3.download_button("Télécharger V6.0 registry CSV", data=reg.to_csv(index=False).encode("utf-8"), file_name="v60_backtest_lab_registry.csv", mime="text/csv", use_container_width=True, key="bt_v60_registry_download")
    except Exception as exc:
        st.warning(f"Exports V5.2→V6.0 indisponibles : {exc}")
    return {"enabled": True, "v52_pack": v52, "v53_pack": v53, "v54_pack": v54, "v55_pack": v55, "v56_pack": v56, "v57_pack": v57, "v58_pack": v58, "v59_pack": v59, "v60_pack": v60, "decision": v60.get("decision"), "score": v60.get("score"), "level": v60.get("level"), "read": v60.get("read")}


# Backward-compatible alias for shorter call names.
def _render_final_backtest_lab_completion_suite_v52_to_v60(ctx: dict[str, Any] | None = None) -> dict[str, Any]:
    return _render_backtest_lab_institutional_final_suite_v52_to_v60(ctx=ctx)

