# ============================================================
# V5.3 / V5.8 FINAL LOGIC FIX — SCORE + UPSTREAM GATE PROPAGATION
# ============================================================
# Paste this block at the very end of backtest_lab.py / backtest lab py.rtf,
# AFTER the existing V5.2 -> V6.0 final suite block.
#
# Purpose:
# - V5.3 no longer shows a high score when V5.2 has only watchlist rows and no candidate.
# - V5.3 only selects a champion from true V5.2 CANDIDATE rows.
# - V5.8 no longer declares SOURCE_EDGE_EXPLAINED when V5.4/V5.5 are blocked.
# - V5.8 requires a real V5.5 sandbox before full attribution/explainability.
# Read-only: no engine, trade, equity, sizing, exit, registry or verdict modification.
# ============================================================


def _champion_selection_gate_v53_pack(ctx: dict[str, Any] | None, v52_pack: dict[str, Any]) -> dict[str, Any]:
    """
    V5.3 — Alternative Source Winner Audit / Champion Selection Gate.

    Final logic fix:
    - V5.2 WATCHLIST rows are not champions.
    - Only V5.2 CANDIDATE rows can become champion candidates.
    - A rejected/blocked champion cannot display a high institutional score.
    """
    try:
        v52_pack = v52_pack if isinstance(v52_pack, dict) else {}
        tournament = _v52_v60_as_df(v52_pack.get("tournament"))
        v52_decision = str(v52_pack.get("decision", "N/A"))
        v52_candidate_count = int(v52_pack.get("candidate_count", 0) or 0)
        v52_watch_count = int(v52_pack.get("watch_count", 0) or 0)

        top_watch_row = {}
        champion = None

        if not tournament.empty:
            candidate_label = tournament.get(
                "candidate_label",
                pd.Series("", index=tournament.index),
            ).astype(str).str.upper().str.strip()

            eligible = tournament[candidate_label.eq("CANDIDATE")].copy()
            if not eligible.empty:
                champion = eligible.sort_values("rank_score", ascending=False).head(1).iloc[0]
            else:
                # Keep the top row only for diagnostic display. It is not a champion.
                top_watch_row = tournament.sort_values("rank_score", ascending=False).head(1).iloc[0].to_dict()

        if champion is None:
            if not tournament.empty and v52_watch_count > 0:
                level = "Champion blocked / watchlist only"
                decision = "RETURN_TO_V52_REFINE_BEFORE_V53"
                read = "V5.3 bloque : V5.2 a des alternatives watchlist, mais aucun candidat champion validable."
                raw_score = _safe_float(top_watch_row.get("rank_score"), 0.0) if isinstance(top_watch_row, dict) else 0.0
                score = max(0.0, min(35.0, raw_score * 0.45))
                champion_table = pd.DataFrame([top_watch_row]) if isinstance(top_watch_row, dict) and top_watch_row else pd.DataFrame()
                gates = pd.DataFrame(
                    [
                        ["V5.2 candidate rows", "FAIL", f"{v52_candidate_count}", "Un champion exige au moins une ligne candidate V5.2."],
                        ["V5.2 watchlist rows", "REVIEW", f"{v52_watch_count}", "Les watchlist doivent être enrichies ou raffinées avant V5.3."],
                        ["Champion selection", "BLOCK", "no true candidate", "Ne pas sélectionner automatiquement la meilleure watchlist."],
                        ["Contract permission", "BLOCK", "no champion", "V5.4 doit rester bloqué."],
                    ],
                    columns=["Gate", "Status", "Value", "Read"],
                )
            else:
                level = "No champion selectable"
                decision = "RETURN_TO_V52_BEFORE_V53"
                read = "Aucun champion alternatif sélectionnable."
                score = 0.0
                champion_table = pd.DataFrame()
                gates = pd.DataFrame(
                    [
                        ["V5.2 tournament rows", "FAIL", "0" if tournament.empty else len(tournament), "V5.3 exige un tournoi V5.2 exploitable."],
                        ["V5.2 candidate rows", "FAIL", f"{v52_candidate_count}", "Aucun candidat V5.2."],
                        ["Champion selection", "BLOCK", "none", "Aucune source ne peut être contractualisée."],
                    ],
                    columns=["Gate", "Status", "Value", "Read"],
                )

            champion_row = {}

        else:
            events = int(_safe_float(champion.get("events"), 0))
            sources = int(_safe_float(champion.get("sources"), 0))
            dates = int(_safe_float(champion.get("unique_dates"), 0))
            avg10 = _safe_float(champion.get("avg_10b"), np.nan)
            hit10 = _safe_float(champion.get("hit_10b"), np.nan)
            worst10 = _safe_float(champion.get("worst_10b"), np.nan)
            rank_score = _safe_float(champion.get("rank_score"), 0.0)

            pass_sample = events >= 8
            pass_sources = sources >= 2
            pass_dates = dates >= 6
            pass_perf = pd.notna(avg10) and avg10 > 0
            pass_hit = pd.notna(hit10) and hit10 >= 0.52
            pass_tail = pd.isna(worst10) or worst10 > -0.25

            gate_passes = sum([pass_sample, pass_sources, pass_dates, pass_perf, pass_hit, pass_tail])
            raw_score = max(0.0, min(100.0, 0.50 * rank_score + gate_passes * 7.5))

            if all([pass_sample, pass_sources, pass_dates, pass_perf, pass_hit, pass_tail]) and raw_score >= 65:
                level = "Champion source selected"
                decision = "PROMOTE_CHAMPION_TO_V54_CONTRACT"
                read = "V5.3 sélectionne un champion source pour contrat causal."
                score = max(65.0, min(100.0, raw_score))
            elif pass_sample and pass_sources and pass_perf and gate_passes >= 4:
                level = "Champion watchlist / more validation required"
                decision = "WATCH_CHAMPION_MORE_DATA_BEFORE_V54"
                read = "Champion partiel : plus de dates, sources ou stabilité sont nécessaires avant contrat robuste."
                score = max(45.0, min(64.0, raw_score))
            else:
                level = "Champion rejected"
                decision = "REJECT_ALL_ALT_SOURCES"
                read = "Aucune alternative ne mérite un contrat causal à ce stade."
                score = max(0.0, min(40.0, raw_score))

            champion_table = pd.DataFrame([champion.to_dict()])
            champion_row = champion.to_dict()

            gates = pd.DataFrame(
                [
                    ["V5.2 candidate status", "PASS", "CANDIDATE", "Le champion vient bien d'une ligne candidate V5.2."],
                    ["Sample events", "PASS" if pass_sample else "FAIL", f"{events}/8", "Minimum pratique avant contrat."],
                    ["Source diversity", "PASS" if pass_sources else "FAIL", f"{sources}/2", "Évite une validation mono-provider."],
                    ["Date diversity", "PASS" if pass_dates else "REVIEW", f"{dates}/6", "Évite une concentration d'événements trop forte."],
                    ["Avg 10B positive", "PASS" if pass_perf else "FAIL", _format_pct(avg10), "Rendement actif forward 10B moyen."],
                    ["Hit 10B", "PASS" if pass_hit else "REVIEW", _format_pct(hit10), "Hit-rate minimal."],
                    ["Tail event", "PASS" if pass_tail else "WARN", _format_pct(worst10), "Pire événement 10B."],
                    ["Contract permission", "PASS" if decision == "PROMOTE_CHAMPION_TO_V54_CONTRACT" else "BLOCK", decision, "V5.4 seulement si champion vraiment promu."],
                ],
                columns=["Gate", "Status", "Value", "Read"],
            )

        champion_label = "N/A"
        if isinstance(champion_row, dict) and champion_row:
            champion_label = f"{champion_row.get('family', 'N/A')}/{champion_row.get('feature', 'N/A')}/{champion_row.get('rule', 'N/A')}"
        elif isinstance(top_watch_row, dict) and top_watch_row:
            champion_label = f"watch-only: {top_watch_row.get('family', 'N/A')}/{top_watch_row.get('feature', 'N/A')}/{top_watch_row.get('rule', 'N/A')}"

        summary = pd.DataFrame(
            [
                ["V5.3 level", level, "Lecture synthétique champion."],
                ["V5.3 score", f"{_format_num(score, 0)}/100", "Score champion corrigé : un rejet/watch-only ne peut pas afficher un score institutionnel élevé."],
                ["Decision", decision, "Décision V5.3."],
                ["Read", read, "Interprétation opérationnelle."],
                ["V5.2 decision", v52_decision, "Décision source du tournoi alternatif."],
                ["V5.2 candidates", str(v52_candidate_count), "Nombre de candidats V5.2 réellement éligibles."],
                ["V5.2 watchlist", str(v52_watch_count), "Nombre d'alternatives watchlist non contractualisables."],
                ["Champion", champion_label, "Source champion auditée ou meilleure watchlist diagnostiquée."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        next_actions = pd.DataFrame(
            [
                ["P0", "Do not build contract without champion", decision, "V5.4 reste bloqué si V5.3 n'a pas PROMOTE_CHAMPION_TO_V54_CONTRACT."],
                ["P0", "Do not promote watchlist rows", f"watch={v52_watch_count}", "Une watchlist V5.2 doit être raffinée avant champion."],
                ["P1", "Refine V5.2 alternatives", champion_label, "Ajouter événements/sources ou ajuster définition causale."],
                ["P1", "Retry V5.3 only after true candidate", f"candidates={v52_candidate_count}", "Relancer champion gate seulement quand V5.2 produit au moins un candidat."],
            ],
            columns=["Priority", "Action", "Reason", "Next Step"],
        )

        cards = [
            {"label": "V5.3 champion", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Champion feature", "value": str(champion_row.get("feature", top_watch_row.get("feature", "N/A") if isinstance(top_watch_row, dict) else "N/A")), "delta": "selected" if champion_row else "watch-only"},
            {"label": "V5.2 candidates", "value": str(v52_candidate_count), "delta": "eligible"},
            {"label": "Decision", "value": decision, "delta": "gate"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "gates": gates,
            "champion": champion_table,
            "champion_row": champion_row if decision == "PROMOTE_CHAMPION_TO_V54_CONTRACT" else {},
            "diagnostic_top_watch_row": top_watch_row if isinstance(top_watch_row, dict) else {},
            "next_actions": next_actions,
        }

    except Exception as exc:
        return {
            "enabled": True,
            "level": "V5.3 error",
            "score": 0.0,
            "decision": "V53_ERROR_SAFE_SKIP",
            "read": f"Erreur V5.3 : {exc}",
            "cards": [],
            "summary": pd.DataFrame([["V5.3 error", str(exc), "Erreur capturée."]], columns=["Metric", "Value", "Read"]),
            "gates": pd.DataFrame(),
            "champion": pd.DataFrame(),
            "champion_row": {},
            "next_actions": pd.DataFrame(),
        }


def _source_attribution_explainability_v58_pack(ctx: dict[str, Any] | None, v52_pack: dict[str, Any], v55_pack: dict[str, Any]) -> dict[str, Any]:
    """
    V5.8 — Source Attribution & Explainability Layer.

    Final logic fix:
    - Event-table attribution alone is not a validated source edge.
    - Full explainability requires a V5.5 sandbox with strategy_return.
    - If V5.4/V5.5 are blocked, V5.8 must propagate the upstream block.
    """
    try:
        v52_pack = v52_pack if isinstance(v52_pack, dict) else {}
        v55_pack = v55_pack if isinstance(v55_pack, dict) else {}

        event_table = _v52_v60_as_df(v52_pack.get("event_table"))
        sandbox = _v52_v60_as_df(v55_pack.get("sandbox"))

        v52_decision = str(v52_pack.get("decision", "N/A"))
        v55_decision = str(v55_pack.get("decision", "N/A"))

        by_rule = pd.DataFrame()
        top_events = pd.DataFrame()

        if not event_table.empty:
            cols = [c for c in ["family", "feature", "rule", "source"] if c in event_table.columns]
            if cols and "fwd_10b" in event_table.columns:
                by_rule = (
                    event_table.groupby(cols, dropna=False)
                    .agg(
                        events=("fwd_10b", "size"),
                        avg_10b=("fwd_10b", "mean"),
                        hit_10b=("fwd_10b", lambda x: float((pd.to_numeric(x, errors="coerce") > 0).mean())),
                        worst_10b=("fwd_10b", "min"),
                    )
                    .reset_index()
                    .sort_values("avg_10b", ascending=False)
                )
                top_events = event_table.sort_values("fwd_10b", ascending=False).head(20)

        sandbox_has_returns = (
            isinstance(sandbox, pd.DataFrame)
            and not sandbox.empty
            and "strategy_return" in sandbox.columns
            and pd.to_numeric(sandbox["strategy_return"], errors="coerce").replace([np.inf, -np.inf], np.nan).notna().sum() >= 20
        )

        sandbox_stats = pd.DataFrame()

        if sandbox_has_returns:
            r = pd.to_numeric(sandbox["strategy_return"], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
            pos = float(r[r > 0].sum()) if (r > 0).any() else 0.0
            neg = float(r[r < 0].sum()) if (r < 0).any() else 0.0
            sharpe = float(r.mean() / r.std() * np.sqrt(252)) if r.std() > 0 else np.nan
            sandbox_stats = pd.DataFrame(
                [
                    ["Gross positive contribution", _format_pct(pos), "Somme des jours positifs sandbox."],
                    ["Gross negative contribution", _format_pct(neg), "Somme des jours négatifs sandbox."],
                    ["Sandbox Sharpe", _format_num(sharpe), "Sharpe du sandbox source-only."],
                    ["Skew proxy", _format_num(r.skew()), "Skew des rendements sandbox."],
                    ["Kurtosis proxy", _format_num(r.kurtosis()), "Kurtosis des rendements sandbox."],
                    ["Observations", str(int(len(r))), "Nombre de barres sandbox."],
                ],
                columns=["Metric", "Value", "Read"],
            )

        upstream_blocked = (
            not sandbox_has_returns
            or v55_decision in {
                "WAIT_FOR_V54_CONTRACT_AND_PRICE_DATA",
                "WAIT_FOR_V54_CONTRACT_BEFORE_V55",
                "WAIT_FOR_V55_SANDBOX_SAMPLE",
            }
            or "WAIT_FOR" in v55_decision
            or "BLOCK" in v55_decision.upper()
        )

        if upstream_blocked:
            if not by_rule.empty:
                level = "Attribution limited / upstream blocked"
                decision = "WAIT_FOR_V55_SANDBOX_BEFORE_FULL_ATTRIBUTION"
                read = "V5.8 dispose d'une attribution événementielle, mais pas d'un sandbox V5.5 validé : edge non expliqué."
                score = 25.0
            else:
                level = "Attribution blocked by upstream gate"
                decision = "WAIT_FOR_V55_SANDBOX_BEFORE_FULL_ATTRIBUTION"
                read = "V5.8 attend un contrat V5.4 et un sandbox V5.5 avant attribution complète."
                score = 10.0

        else:
            explained = bool(not by_rule.empty and not sandbox_stats.empty)
            positive_sandbox = False

            if sandbox_has_returns:
                r = pd.to_numeric(sandbox["strategy_return"], errors="coerce").replace([np.inf, -np.inf], np.nan).fillna(0.0)
                positive_sandbox = bool(float(r.mean()) > 0 and float((r > 0).mean()) >= 0.50)

            if explained and v55_decision == "SOURCE_SANDBOX_EDGE_PRESENT" and positive_sandbox:
                level = "Source edge explained"
                decision = "SOURCE_EDGE_EXPLAINED"
                read = "V5.8 fournit une attribution exploitable sur un sandbox validé."
                score = 70.0
            elif explained:
                level = "Source edge unstable but reviewable"
                decision = "SOURCE_EDGE_UNSTABLE_BUT_REVIEWABLE"
                read = "Attribution disponible, mais le sandbox ou l'edge source-only reste fragile."
                score = 45.0
            else:
                level = "Source edge unexplained"
                decision = "SOURCE_EDGE_UNEXPLAINED_REJECT"
                read = "Aucune attribution suffisante disponible."
                score = 20.0

        gates = pd.DataFrame(
            [
                ["V5.5 sandbox available", "PASS" if sandbox_has_returns else "FAIL", "strategy_return" if sandbox_has_returns else "missing", "Attribution complète seulement avec sandbox."],
                ["V5.5 decision", "PASS" if v55_decision == "SOURCE_SANDBOX_EDGE_PRESENT" else "REVIEW", v55_decision, "Décision sandbox amont."],
                ["Event attribution table", "PASS" if not by_rule.empty else "REVIEW", len(by_rule), "Attribution source/rule/feature issue du tournoi."],
                ["Sandbox contribution stats", "PASS" if not sandbox_stats.empty else "FAIL", len(sandbox_stats), "Contribution réelle du sandbox isolé."],
                ["Full explainability permission", "PASS" if decision == "SOURCE_EDGE_EXPLAINED" else "BLOCK", decision, "V5.9 ne doit passer que si V5.8 explique un edge sandbox validé."],
            ],
            columns=["Gate", "Status", "Value", "Read"],
        )

        summary = pd.DataFrame(
            [
                ["V5.8 level", level, "Lecture attribution."],
                ["V5.8 score", f"{_format_num(score, 0)}/100", "Score explainability corrigé par propagation upstream."],
                ["Decision", decision, "Décision V5.8."],
                ["Read", read, "Interprétation."],
                ["V5.2 decision", v52_decision, "Décision du tournoi alternatif."],
                ["V5.5 decision", v55_decision, "Décision sandbox amont."],
                ["Sandbox available", str(bool(sandbox_has_returns)), "Présence d'un sandbox exploitable."],
                ["Rule attribution rows", str(len(by_rule)), "Lignes d'attribution par source/règle."],
            ],
            columns=["Metric", "Value", "Read"],
        )

        cards = [
            {"label": "V5.8 attribution", "value": level, "delta": f"{_format_num(score, 0)}/100"},
            {"label": "Sandbox", "value": "available" if sandbox_has_returns else "blocked", "delta": "V5.5"},
            {"label": "Rule rows", "value": str(len(by_rule)), "delta": "event attribution"},
            {"label": "Decision", "value": decision, "delta": "explainability"},
        ]

        return {
            "enabled": True,
            "level": level,
            "score": score,
            "decision": decision,
            "read": read,
            "cards": cards,
            "summary": summary,
            "gates": gates,
            "by_rule": by_rule,
            "top_events": top_events,
            "sandbox_stats": sandbox_stats,
        }

    except Exception as exc:
        return {
            "enabled": True,
            "level": "V5.8 error",
            "score": 0.0,
            "decision": "V58_ERROR_SAFE_SKIP",
            "read": f"Erreur V5.8 : {exc}",
            "cards": [],
            "summary": pd.DataFrame([["V5.8 error", str(exc), "Erreur capturée."]], columns=["Metric", "Value", "Read"]),
            "gates": pd.DataFrame(),
            "by_rule": pd.DataFrame(),
            "top_events": pd.DataFrame(),
            "sandbox_stats": pd.DataFrame(),
        }


